(window.GIM_TP=window.GIM_TP||{})["Z.Bereshit.1"]={"from":55,"a":[[["אִנּוּן ד' חֵיוָון סָלְקִין כַּד רוּחָא אִזְדְּהַר בְּגוֹ הַהוּא חֵיוָותָא. אַרְבַּע גַּלְגַּלִּין לְכָל חַד וְחַד. גַּלְגַּלָּא חָדָא אִסְתְּכֵי לִסְטַר מִזְרָח. תְּלַת סָמְכִין נָטְלִין לֵיהּ וְאִסְתַּכְיָין לְאֶמְצָעִיתָא. וְגַלְגַּלָּא חָדָא אִסְתְּכֵי לִסְטַר מַעֲרָב, וּתְלַת סָמְכִין נָטְלִין לֵיהּ וְאִסְתַּכְיָין לְאֶמְצָעִיתָא. וְגַלְגַּלָּא חָדָא אִסְתְּכֵי לִסְטַר דָּרוֹם. וּתְלַת סָמְכִין נָטְלִין לֵיהּ וְאִסְתַּכְיָין לְאֶמְצָעִיתָא. וְגַלְגַּלָּא אָחֳרָא אִסְתְּכֵי לִסְטַר צָפוֹן וּתְלַת סָמְכִין נָטְלִין לֵיהּ וְאִסְתַּכְיָין לְאֶמְצָעִיתָא. וְכֻלְהוּ סָמְכִין תְּרֵיסַר נָטְלִין מִגּוֹ אֶמְצָעִיתָא. וְהַהוּא אֶמְצָעִיתָא סָגִיר וּפְתַח. וְכָל גַלְגַּלָּא וְגַלְגַּלָּא כַּד נָטְלָא קָלָא אִשְׁתְּמַע בְּכֻלְהוּ רְקִיעִין.","אִלֵּין אַרְבַּע חֵיוָון (ד\"א דלעילא) כֻּלְהוּ (מתלבשן) (ס\"א אשתלבן) דָּא בְּדָא. וְעָאלִין אִנּוּן אוֹפַנִּים דִּלְתַתָּא בְּגוֹ אִלֵּין חֵיוָון דִּלְעֵילָא כְּלִילָן אִלֵּין בְּאִלֵּין, רוּחָא דָא דְּאִתְכְּלִיל בְּאִנּוּן רוּחִין מְלַהֲטָא וְסָלְקָא לְאִתְאַחֲדָא לְעֵילָא וְקָיְימָא לְאִתְאַחֲדָא וּלְאִתְקַשְּׁרָא בִּרְעוּתָא דְבַר נָשׁ זַכָּאָה בְּהַהִיא צְלוֹתָא דְּצַלֵּי. דְּכַד סָלְקָא וְעָאלַת בְּהַהוּא הֵיכָלָא נָטִיל כֹּלָּא וְכֻלְהוּ נַטְלִין בַּהֲדָהּ וְאִתְכְּלִילוּ דָּא בְּדָא עַד דְּאִתְכְּלִילוּ בְּהַהוּא רוּחָא. וְהַהוּא רוּחָא נָטְלָא בִּרְעוּתָא דְּקִשּׁוּרָא דְּיִחוּדָא דִצְלוֹתָא דִּמְיַחֲדָא כֹּלָּא עַד דְּמָטוּ כֻּלְהוּ לְהֵיכָלָא תְּלִיתָאָה כְּלִילָן דָּא בְּדָא כְּדְּקַדְמָאי, אֶשָׁא בְּמַיָא, וּמַיָא בְּאֶשָׁא. רוּחָא בְּעַפְרָא, וְעַפְרָא בְּרוּחָא. מִזְרָח בְּמַעֲרָב, מַעֲרָב בְּמִזְרָח. צָפוֹן בְּדָרוֹם, דָּרוֹם בְּצָפוֹן. וְהָכִי הָנֵי כֻּלְהוּ מִתְקַשְּׁרָן דָּא בְּדָא וּמִתְאַחֲדָן דָּא בְּדָא וּמְשַׁלְּבָן דָּא עִם דָּא. וְכֵן כַּמָּה חַיָּילִין וּמַשִּׁרְיָין דְּאִתְאַחֲדוּ (נ\"א דנחתי) לְתַתָּא וְאִתְעָרְבוּ בְּאִנּוּן תַּתָּאֵי עַד דְּמָטוּ לְכֹכָבָא דְּצֶדֶק וְתַמָּן כַּמָּה מְמַנָּן עַל עָלְמָא.","וְכַד רוּחָא דָא דְּאִתְכְּלִיל (ד\"א אתכליל) מִכֻּלְהוּ וְכֻלְהוּ כְּלִילָן בֵּיהּ. סָלִיק וְאִתְאַחַד וְעָאל בְּגוֹ הֵיכָלָא תְּלִיתָאָה עַד דְּאִתְאַחַד בְּרוּחָא דְתַמָּן בְּגוֹ הַהוּא עַמּוּדָא דְּקָאִים בְּאֶמְצָעִיתָא. וּכְדֵין כֹּלָּא אִשְׁתְּלִים עַד הָכָא כְּדְקָא יָאוֹת. וְכֻלְהוּ רוּחָא חָדָא כָּלִיל מִכֹּלָּא וּשְׁלִים מִכֹּלָּא כְּמָא דְאַתְּ אָמֵר וְרוּחַ אֶחָד לְהֵנָה. הָכָא הַכְּרָעָה לְאִתְדַּבְּקָא בְּמָארֵיהּ:","הֵיכָלָא תְלִיתָאָה. הֵיכָלָא דָא אִיהוּ הֵיכָלָא דְּהַהוּא רוּחָא דְּאִקְרֵי נֹגַהּ, רוּחָא דָא אִיהוּ דַכְיָיא בָּרִיר מִכֻּלְהוּ. לֵית לֵיהּ גַּוָּון דְּאִתְחַזֵּי בֵּיהּ לָאו חִוַּור וְלָאו יָרוֹק וְלָאו אוּכָם וְלָא סוּמָק. וּבְגִין כָּךְ אִקְרֵי טוֹהַר. דַּכְיָיא בְּרִירָא מִכָּל אִלֵּין תַּתָּאִין. וְאַף עַל גַּב דְּאִיהוּ דַּכְיָיא מִכֹּלָּא, לָא אִתְחַזֵּי עַד דְּאִלֵּין תַּתָּאֵי מִתְגַּלְגְּלָן וְאֲחִידָן (נ\"א וכראן) בֵּיהּ וְעָאלִין בְּגַוִּיהּ (נ\"א ביה). כֵּיוָן דְּעָאלִין בְּגַוֵּיהּ כְּדֵין אַחֲזֵי נְהוֹרֵיהּ וְלָא גַּוָון חַד מִכֻּלְהוּ.","כַּד אִשְׁתְּלִים הַאי רוּחָא מִכֻּלְהוּ תַּתָּאֵי, אַפִּיק מִנֵּיהּ נְהוֹרָא דְּכָלִיל בִּתְלַת נְהוֹרִין. אִנּוּן תְּרֵין נְהוֹרִין סָלְקִין וְנָחֲתִין וְנָצְצִין. בְּהַהוּא נִצּוֹצָא אִתְחַזּוּן עֶשְׂרִין וּתְרֵין נְהוֹרִין מְשַׁנְיָין דָּא מִן דָּא וְכֻלְהוּ חַד נְהוֹרָא. וְעָאלִין בְּגוֹ הַהוּא חַד נְהוֹרָא. וְהַהוּא נְהוֹרָא כָּלִיל לוֹן.","וְלָא נָהִיר, בַּר בְּזִמְנָא דְּאִלֵּין נְהוֹרִין דִּלְתַתָּא סָלְקִין וְהַהוּא רְעוּתָא דִּצְלוֹתָא נָטִיל לְכֻלְהוּ. כְּדֵין הַהוּא נְהוֹרָא נָפִיק מִגּוֹ הַהוּא רוּחָא. אִתְנְהִיר הַהוּא נְהוֹרָא וְאַפִּיק אִלֵּין תְּרֵין נְהוֹרִין נָצְצִין וְאִתְחַזּוּן כְּחוּשְׁבַּן כ\"ב אַתְוָון דְּאוֹרַיְיתָא. לְבָתַר מִתְהַדְּרִין וּכְלִילָן בְּהַהוּא נְהוֹרָא.","כָּל אִנּוּן נְהוֹרִין תַּתָּאֵי (באנון נהורין) כֻּלְהוֹן כְּלִילָן בְּהָנִי נְהוֹרִין (תתאין) וְכֻלְהוּ בִּנְהוֹרָא דָא. הַאי נְהוֹרָא אִיהוּ כָּלִיל בְּגוֹ הַהוּא רוּחָא. וְהַהוּא רוּחָא קַיְימָא בְּהֵיכָלָא תְּלִיתָאָה דָא. וְלָא קָאִים לְאִתְיַשְׁבָא אֶלָּא בְּגוֹ הֵיכָלָא רְבִיעָאָה דְּתִאוּבְתֵּיהּ לְסַלְקָא לְגַוֵּיהּ.","אִלֵּין נְהוֹרִין דְּנָפְקוּ מִגוֹ הַהוּא רוּחָא כַּד מְנַצְצִין מִתְחַבְּרָן כֻּלְהוּ נְהוֹרִין דְּנָצְצָן. בְּשַׁעֲתָא דְּנָפְקֵי מִגּוֹ הַהוּא נְהוֹרָא חָדָא וְדָחֲקִין (נ\"א ודחיין) לְאִתְנַצְּצָא. נָפְקֵי מִנַּיְיהוּ חַד חֵיוָתָא קַדִּישָׁא רַבְרְבָא דְּיוֹקְנָהָא כְּחֵיזוּ דְּכָל אִנּוּן שְׁאָר חֵיוָתָא דִּיוּקְנָא דְאַרְיֵה וְדִיוּקְנָא דְנְשֶׁר כְּלִילָן כְּחֲדָא וְאִתְעֲבִידוּ בָּהּ חַד דִּיוּקְנָא מִנַּיְיהוּ."],[[0,"אנון ד' חיוון סלקין כד רוחא אזדהר בגו ההוא חיוותא","אלו ד' חיות עולות כשהרוח עצם השמים מאיר בתוך חיה העליונה שלמעלה מהן. \u0003ד' גלגלין לכל חד וחד, גלגלא חדא אסתכי לסטר מזרח תלת סמכין נטלין ליה ואסתכיין לאמצעיתא וכו':\u0004 ד' גלגלים יש לכל חיה וחיה מד' החיות, גלגל אחד מסתכל לצד מזרח. ג' אדנים נושאים אותו, ומסתכלים להחיה שבאמצע ד' הגלגלים. וכן גלגל א' לצד מערב וכו' וגלגל א' לצד דרום וכו' וגלגל א' לצד צפון וכו'."],[0,"","פירוש, כי בעת שד' החיות עולות לחיה העליונה, מתפשטת כל חיה וחיה לפרצוף שלם, שמחזה ולמעלה יש לה ד' פנים אריה שור נשר אדם, שהם חו\"ב תו\"מ, לד' רוחות העולם מזרח מערב דרום צפון, והם הנקראים ד' גלגלים, ומחזה ולמטה יש לה רק ג' פנים אריה שור נשר, כי פני אדם חסר שם (כנ\"ל דף מ\"ו ד\"ה ביאור) אמנם הם מקבלים פני אדם ע\"י התכללות בהזווג שמחזה ולמעלה בסוד שנא\"ן (כנ\"ל בבראשית דף פ\"ו ד\"ה שנאן ע\"ש בכל ההמשך) והם נכללות בכל הד' פנים אשר שם, ואפילו מפני אדם, אלא שנבחן שמקבלים רק ט\"ס ראשונות, שהם אריה שור נשר, מכל פנים, דהיינו אריה שור נשר שבאריה, וכן אריה שור נשר שבשור, ואריה שור נשר שבנשר, ואריה שור נשר שבפני אדם, באופן שמצד א' נכללים מכל ד' הפנים, שהרי יש להם אריה שור נשר שהם ט\"ס ראשונות אפילו לפני אדם, אמנם מצד הב' חסר להם בכל מקום בחינת המלכות שה\"ס פני אדם כי אין להם רק ט\"ס ראשונות מהם בלבד. ולפיכך נבחן שלכל גלגל מד' הגלגלים דהיינו לכל פנים ופנים מד' הפנים אריה שור נשר אדם שמחזה ולמעלה יש ג' סמכין אריה שור נשר, כמבואר, באופן שכל חיה מתפשטת לד' גלגלים מחזה ולמעלה ולי\"ב סמכין מחזה ולמטה, אשר כל גלגל יש לו פנים מיוחד מאריה שור נשר אדם ורוח מיוחד ממזרח מערב דרום צפון, אבל הסמכין, מתוך שבאים מהתכללות הזווג על ידי עליה למחזה ולמעלה, הרי הם מקבלים מכל הד' פנים שבד' הגלגלים אשר שם, בבת אחת, וע\"כ הם מסתכלים לאמצעיתא, דהיינו להחיה הכוללת את כולם ולא לשום צד מד' הגלגלים."],[0,"","וזהו אמרו \u0003וכלהו סמכין תריסר נטלין מגו אמצעיתא,\u0004 וכל שנים עשרה סמכין נוסעים מכח החיה הכוללת שבאמצע, ולא לשום צד של הגלגלים כנ\"ל. \u0003וההוא אמצעיתא סגיר ופתח,\u0004 והחיה האמצעית היא סוגרת ופותחת כלומר היא השולטת על כולם שהיא סוגרת האורות מלהאיר ופותחת אותם. \u0003וכל גלגלא וגלגלא כד נטלא, קלא אשתמע בכלהו רקיעין,\u0004 וכל גלגל וגלגל בעת שנוסע נשמע קולו בכל הרקיעים."],[1,"אלין ארבע חיוון כלהו אשתלבן דא בדא ועאלין אינון אופנים דלתתא בגו אלין חיוון דלעילא כלילן אלין באלין:","אלו ארבע חיות כולם, משתלבות זו בזו, והאופנים שלמטה מהיכל הא', נכנסים בתוך אלו החיות שלמעלה, שבהיכל הב', כלולים אלו באלו. \u0003רוחא דא דאתכליל באנון רוחין מלהטא וסלקא לאתאחדא לעילא, ולאתקשרא ברעותא דבר נש זכאה, בההיא צלותא דצלי,\u0004 הרוח הזה שבכאן שנכלל בהרוחות שלמטה מהיכל הא', הוא מתלהט ועולה להתאחז למעלה בהיכל הג', ולהתקשר בהרצון של אדם צדיק, באותה התפלה שהתפלל \u0003דכד סלקא ועאלת בההוא היכלא נטיל כלא וכלהו נטלין בהדה,\u0004 כי כשהתפלה עולה ונכנסת בהיכל ההוא הב', היא לוקחת כולם עמה, וכולם נוסעים עמה, דהיינו כל המציאות שבהיכל הא' והב', \u0003ואתכלילו דא בדא עד דאתכלילו בההוא רוחא,\u0004 ונכללים זה בזה עד שכולם נכללים ברוח ההוא שבכאן, \u0003וההוא רוחא נטלא ברעותא דקשורא דיחודא דצלותא דמיחדא כלא עד דמטו כלהו להיכלא תליתאה.\u0004 ורוח ההוא הנכלל מכולם נוסע בכח הרצון שבקשר היחוד של התפלה המיחד הכל, עד שמגיעים כולם להיכל הג', \u0003כלילן דא בדא כדקדמאי\u0004 נכללים זה בזה כמו הראשונים, כלומר כמו בחינות הראשונות של היכל הא', שנכללו זה בזה בעת עלותם להיכל הב' (כנ\"ל דף מ\"ח אות ע\"א) שאומר שם שהיו כלולים \u0003אשא במיא ומיא באשא רוחא בעפרא ועפרא ברוחא מזרח במערב וכו' והכי הנהו כלהו מתקשרן דא בדא ומתאחדן דא בדא ומשלבן דא בדא,\u0004 וכן אלו שבכאן מתקשרים כולם זה בזה, ומתאחזים זה בזה ומשולבים זה בזה."],[1,"וכן כמה חיילין ומשריין דאתאחדו לתתא ואתערבו באנון תתאי עד דמטי לככבא דצדק ותמן כמה ממנן על עלמא,","וכן כמה צבאות ומחנות יורדים מכאן ולמטה ומתערבים ומאירים באלו מלאכים התחתונים עד שמגיעים בהארתם לככב הנקרא צדק. ששם עומדים כמה ממונים של העולם, המקבלים הארה הזאת ומשפיעים להעולם."],[2,"וכד רוחא דא דאתכליל מכלהו וכלהו כלילן ביה, סליק ואתאחד ועאל בגו היכלא תליתאה,","וכשהרוח הזה שבכאן, הנכלל מכל התחתונים ממנו וכולם כלולים בו, עולה ונאחז ונכנס בתוך היכל הג' \u0003עד דאתאחד ברוחא דתמן בגו ההוא עמודא דקאים באמצעיתא, וכדין כלא אשתלים עד הכא כדקא יאות,\u0004 עד שנאחז בהרוח שבהיכל הג', בתוך העמוד העומד באמצע ההיכל, אז נשלם הכל כראוי עד כאן. כי אלו ג' היכלות שהם נצח הוד יסוד שמחזה דכללות ולמטה, הם כולם שלמות אחד, הנקראים עי\"מ דאחורים (כמ\"ש במראות הסולם כאן דף ל\"ט אות י\"א) וז\"ש \u0003וכלהו רוחא חדא כליל מכלא ושלים מכלא, כד\"א ורוח אחד לכל,\u0004 ונעשו כולם רוח אחד הכלול מכולם ונשלם מכולם, כמ\"ש ורוח אחד לכל. \u0003הכא הכרעה לאתדבקא במאריה,\u0004 כאן סוד ההכרעה בכדי להתדבק ברבונו. וענין הכרעה יתבאר להלן בהיכל הד'."],[3,"היכלא תליתאה, היכלא דא איהו היכלא דההוא רוחא דאקרי נגה.","היכל הג'. היכל זה, הוא ההיכל של הרוח הנקרא נגה. \u0003רוחא דא איהו דכייא בריר מכלהו לית ליה גוון דאתחזי ביה לאו חוור\u0004 וכו', רוח הזה הוא טהור, בדור יותר מכל הרוחין שלמטה ממנו, אין שום גוון נראה בו לא לבן לא ירוק לא שחור לא אדום, \u0003ובגין כך אקרי טוהר, דכייא ברירא מכל אלין תתאין.\u0004 ומשום זח נק' בשם טוהר להיותו טהור וברור יותר מכל התחתונים ממנו. \u0003ואע\"ג דאיהו דכייא מכלא, לא אתחזי עד דאלין תתאי מתגלגלן ואחידן ביה ועאלין בגויה,\u0004 ואע\"פ שהוא טהור מכולם אין הארתו נראה עד שהתחתונים מהיכל הב' מתגלגלים באור הגלגול (כנ\"ל דף מ\"ט ד\"ה דא) ונאחזים בו, בהרוח שבכאן. ונכנסים בתוכו. \u0003כיון דאעלו בגויה כדין אחזי נהוריה ולא גוון חד מכלהו,\u0004 אחר שהתחתונים נכנסים בתוכו, הוא מראה את אורו, ואין בו שום גוון מכל אלו התחתונים שנכנסו בו."],[4,"כד אשתלים האי רוחא מכלהו תתאי אפיק מניה נהורא דכליל בתלת נהורין:","כשהרוח נשלם מכל התחתונים שעלו אליו, הוציא מתוכו אור אחד הכולל ג' אורות, כלומר שכולל בתוכו האורות של כל ג' היכלות נצח הוד יסוד, \u0003אינון תרין נהורין סלקין ונחתין ונצצין,\u0004 ב' אורות, הם עולים ויורדים ומתנוצצים, דהיינו ב' אורות התחתונים דב' היכלות הוד ויסוד, אבל אור העליון של היכל הנצח עולה ואינו יורד למטה. \u0003בההוא נצוצא אתחזון עשרין ותרין נהורין משניין דא מן דא וכלהו חד נהורא,\u0004 בהתנוצצות ההיא נראה כ\"ב אורות משונים זה מזה, שכולם נעשים אור אחד, \u0003ועאלין בגו ההוא חד נהורא, וההוא נהורא כליל לון,\u0004 והכ\"ב אורות אחר שנעשו אחד, הם עולים ונכנסים בתוך אור האחד העליון של היכל הנצח, ואור הזה כולל אותם. ודע שיש כאן לפנינו ב' גרסאות שהמעתיקים ערבבו אותם בהספר, א) הוא הגרסא שבכאן, המתחלת מן כד אשתלים האי רוחא עד המלות וההוא נהורא כליל לון. ב) הוא המתחלת, ולא נהיר בר בזמנא וכו' שבדיבור הסמוך, עד המלות לבתר מתהדרין וכלילן בההוא נהורא. כן נראה לי, אבל לא מצאתי זה בשום מקום.)"],[5,"ולא נהיר בר בזמנא דאלין נהורין דלתתא סלקין, וההוא רעותא דצלותא נטיל לכלהו,","והרוח שבכאן אינו מאיר, רק בעת שהאורות התחתונים מב' היכלות שלמטה עולים אליו, ורצון ההוא של הצדיקים הכלול בהתפלה נושא את כולם, \u0003כדין ההוא נהורא נפיק מגו ההוא רוחא, אתנהיר ההוא נהורא ואפיק אלין תרין נהורין נצצין,\u0004 אז יוצא ונולד אור ההוא מתוך הרוח שבכאן, דהיינו נהורא דכליל בתלת הנ\"ל, ואור ההוא מאיר ומוציא מתוכו ב' אורות מתנוצצים, דהיינו אנון תרין נהורין סלקין ונחתין הנ\"ל. \u0003ואתחזון כחושבן כ\"ב אתוון דאורייתא, לבתר מתהדרין וכלילן בההוא נהורא,\u0004 ונראים האורות כחשבון כ\"ב אותיות התורה, ואחר כך חוזרים ונכללים כאחד באור ההוא שהוליד אותם. (וכבר רמזתי שהדיבור שבכאן הוא גרסא אחרת, או אפשר שגליון היה והמעתיקים הכניסוה בפנים הספר.)"],[6,"כל אנון נהורין תתאי כלהון כלילן בהני נהורין, וכלהו בנהורא דא,","כל אלו האורות התחתונים כלולים כולם בכ\"ב נהורין, וכולם יחד באור הזה שהוליד הכ\"ב נהורין. \u0003האי נהורא איהו כליל בההוא רוחא, וההוא רוחא קיימא בהיכלא תליתאה דא,\u0004 ואור הזה כלול ברוח ההוא, שהולידו, ורוח ההוא עומד בהיכל השלישי הזה, \u0003ולא קאים לאתישבא אלא בגו היכלא רביעאה דתיאובתיה לסלקא לגויה,\u0004 ואינו עומד להתישב, אלא בתוך היכל הד', ת\"ת, שחשקו לעלות לתוכו."],[7,"אלין נהורין דנפקו מגו ההוא רוחא כד מנצצין מתחברן כלהו נהורין דנצצן:","אלו האורות היוצאים מתוך הרוח שבכאן, דהיינו האור דכליל בתלת, ותרין נהורין תתאין דסלקין ונחתין, וכ\"ב נהורין, הנה בעת שהם מתנוצצים מתחברים כאחד כל האורות המתנוצצים. כלומר אע\"פ שהם הרבה בחינות משונות מ\"מ בעת התנוצצות מתחברים להארה אחת."],[7,"בשעתא דנפקי מגו ההוא נהורא חדא, ודחקין לאתנצצא, נפקי מנייהו חד חיוותא קדישא רברבא,","בעת שב' אורות התחתונים מהיכלות דהוד ויסוד, יוצאים מאור האחד של היכל הנצח, (כנ\"ל באות פ\"ה) ודוחקים בהמסך בסוד זווג דהכאה, כדי להתנוצץ, דהיינו להעלות אור חוזר להלביש את אור ישר היורד ממעלה למטה, נולד ויוצא מהם חיה אחת קדושה וגדולה, \u0003דיוקנהא כחיזו דכל אינון שאר חיוותא, דיוקנא דאריה ודיוקנא דנשר כלילן כחדא,\u0004 ודמות החיה, היא כדמות כל שאר החיות, דהיינו מהיכל הא' ומהיכל הב', שמשם באו ב' האורות שהולידו את החיה, שהם, פני אריה שבהיכל הא', ופני נשר, שבהיכל הב', וכלולים יחד, \u0003ואתעבידו בה חד דיוקנא מנייהו,\u0004 ונעשו בה, מהם צורה אחת. כלומר שב' הצורות דאריה ונשר נתמזגו בהחיה לצורה אחת. ומה שאינו נראה בהחיה שום צורה מהיכל הנצח, הוא משום שברוח הזה שבכאן \u0003לית גוון דאתחזי ביה,\u0004 (כנ\"ל באות פ\"ד) וע\"כ אינו נמשך ממנו שום צורה, ועוד, כי אור הנצח אינו נמשך עם ב' נהורין להאיר למטה, (כנ\"ל דף נ\"ו ד\"ה כד)"]],[[0,"","אוֹתָן אַרְבַּע חַיּוֹת עוֹלוֹת כְּשֶׁרוּחַ זוֹהֶרֶת לְתוֹךְ אוֹתָהּ הַחַיָּה. אַרְבָּעָה גַלְגַּלִּים לְכָל אַחַת וְאַחַת. גַּלְגַּל אֶחָד מִסְתַּכֵּל לְצַד מִזְרָח, וּשְׁלֹשָׁה עַמּוּדִים נוֹשְׂאִים אוֹתוֹ וּמִסְתַּכְּלִים לָאֶמְצַע. וְגַלְגַּל אֶחָד מִסְתַּכֵּל לְצַד מַעֲרָב, וּשְׁלֹשָׁה עַמּוּדִים נוֹשְׂאִים אוֹתוֹ וּמִסְתַּכְּלִים לָאֶמְצַע. וְגַלְגַּל אַחֵר מִסְתַּכֵּל לְצַד דָּרוֹם, וּשְׁלֹשָׁה עַמּוּדִים נוֹשְׂאִים אוֹתוֹ וּמִסְתַּכְּלִים לָאֶמְצַע. וְגַלְגַּל אַחֵר מִסְתַּכֵּל לְצַד צָפוֹן וּשְׁלֹשָׁה עַמּוּדִים נוֹשְׂאִים אוֹתוֹ וּמִסְתַּכְּלִים לָאֶמְצַע. וְכָל שְׁנֵים עָשָׂר הָעַמּוּדִים נוֹשְׂאִים מִתּוֹךְ הָאֶמְצַע, וְאוֹתוֹ הָאֶמְצַע סָגוּר וּפָתוּחַ. וְכָל גַּלְגַּל וְגַלְגַּל כְּשֶׁנּוֹסֵעַ, קוֹל נִשְׁמָע בְּכָל הָרְקִיעִים."],[1,"","אֵלּוּ הָאַרְבַּע חַיּוֹת (שלמעלה) כֻּלָּם מִתְלַבְּשׁוֹת (משתלבות) זוֹ בָּזוֹ, וְנִכְנָסִים אוֹתָם אוֹפַנִּים שֶׁלְּמַטָּה לְתוֹךְ הַחַיּוֹת הַלָּלוּ שֶׁלְּמַעְלָה כְּלוּלִים אֵלֶּה בְּאֵלֶּה. רוּחַ זוֹ שֶׁנִּכְלְלָה בְּאוֹתָן רוּחוֹת, לוֹהֶטֶת וְעוֹלָה לְהֵאָחֵז לְמַעְלָה וְעוֹמֶדֶת לְהִתְאַחֵד ולהתקשר ברצון האיש הצדיק באותה תפלה שמתפלל. שכשעולה ונכנסת באותו היכל, לוקח הכל, וכלם נוטלים יחד עמה ונכללו זה בזה עד שנכללים באותה רוח. ואותה רוח נוטלת ברצון של קשר היחוד של התפלה שמיחדת הכל, עד שכלם מגיעים להיכל השלישי כלולים זה בזה, כמו הראשונים אש במים, ומים באש, רוח בעפר, ועפר ברוח. מזרח במערב, מערב במזרח, צפון בדרום, ודרום בצפון. וכך כל הללו מתקשרים זה בזה, ונאחזים זה בזה ומשלבים זה בזה. וכך כמה צבאות ומחנות שנאחזו (נ\"א: שירדו) למטה והתערבו באותם תחתונים עד שהגיעו לכוכב צדק, ושם כמה ממנים על העולם."],[2,"","וּכְשֶׁרוּחַ זֶה שֶׁנִּכְלָל מִכֻּלָּם וְכֻלָּם כְּלוּלִים בּוֹ, עוֹלֶה וְנֶאֱחָז וְנִכְנָס לְתוֹךְ הַהֵיכָל הַשְּׁלִישִׁי עַד שֶׁנֶּאֱחָז בָּרוּחַ שֶׁל שָׁם בְּתוֹךְ אוֹתוֹ הָעַמּוּד שֶׁעוֹמֵד בָּאֶמְצַע, וְאָז הַכֹּל בִּשְׁלֵמוּת עַד כָּאן כָּרָאוּי. וְכֻלָּם רוּחַ אֶחָד כָּלוּל מֵהַכֹּל וְשָׁלֵם מֵהַכֹּל, כְּמוֹ שֶׁנֶּאֱמַר וְרוּחַ אֶחָד לְהֵנָּה (לכל). כָּאן הַכְרִיעָה לְהִדָּבֵק בְּרִבּוֹנוֹ."],[3,"","הֵיכָל שְׁלִישִׁי. הֵיכָל זֶה הוּא הֵיכָל שֶׁל אוֹתוֹ רוּחַ שֶׁנִּקְרָא נֹגַהּ. רוּחַ זֶה הוּא טָהוֹר, בָּרוּר מִכֻּלָּם. אֵין בּוֹ גָּוֶן שֶׁנִּרְאֶה בּוֹ, לֹא לָבָן וְלֹא יָרֹק וְלֹא שָׁחֹר וְלֹא אָדם, וְלָכֵן נִקְרָא טֹהַר. טָהֳרָה בְּרוּרָה מִכָּל הַתַּחְתּוֹנִים הַלָּלוּ. וְאַף עַל גַּב שֶׁהוּא טָהוֹר מֵהַכֹּל, לֹא נִרְאֶה עַד שֶׁהַתַּחְתּוֹנִים הַלָּלוּ מִתְגַּלְגְּלִים וְאוֹחֲזִים (נ\"א: וכורים) בּוֹ וְנִכְנָסִים בְּתוֹכוֹ (בו). כֵּיוָן שֶׁנִּכְנָסִים בְּתוֹכוֹ, אָז מַרְאֶה אֶת אוֹרוֹ, וְלֹא גָוֶן אֶחָד מִכֻּלָּם."],[4,"","כְּשֶׁנִּשְׁלָם רוּחַ זֶה מִכָּל הַתַּחְתּוֹנִים, יוֹצֵא מִמֶּנּוּ אוֹר שֶׁכָּלוּל בִּשְׁלֹשָׁה מְאוֹרוֹת. אוֹתָם שְׁנֵי מְאוֹרוֹת עוֹלִים וְיוֹרְדִים וְנוֹצְצִים. בְּאוֹתוֹ נִצְנוּץ נִרְאִים עֶשְׂרִים וּשְׁנַיִם אוֹרוֹת מְשֻׁנִּים זֶה מִזֶּה, וְכֻלָּם אוֹר אֶחָד. וְנִכְנָסִים בְּאוֹתוֹ הָאוֹר הָאֶחָד. וְאוֹתוֹ הָאוֹר כּוֹלֵל אוֹתָם."],[5,"","וְלֹא מֵאִיר פְּרָט לַזְּמַן שֶׁהָאוֹרוֹת הַלָּלוּ שֶׁלְּמַטָּה עוֹלִים. וְאוֹתוֹ רָצוֹן שֶׁל הַתְּפִלָּה נוֹשֵׂא אֶת כֻּלָּם. אָז אוֹתוֹ אוֹר יוֹצֵא מִתּוֹךְ אוֹתָהּ רוּחַ. מֵאִיר אוֹתוֹ הָאוֹר וּמוֹצִיא שְׁנֵי הָאוֹרוֹת הַנּוֹצְצִים הַלָּלוּ, וְנִרְאִים כְּחֶשְׁבּוֹן עֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת הַתּוֹרָה. אַחַר כָּךְ חוֹזְרִים וְנִכְלָלִים בְּאוֹתוֹ הָאוֹר."],[6,"","כָּל אוֹתָם הָאוֹרוֹת תַּחְתּוֹנִים (באותם אורות), כֻּלָּם כְּלוּלִים בָּאוֹרוֹת הַלָּלוּ (תחתונים), וְכֻלָּם בָּאוֹר הַזֶּה. הָאוֹר הַזֶּה כָּלוּל בְּתוֹךְ אוֹתוֹ הָרוּחַ, וְאוֹתוֹ הָרוּחַ עוֹמֵד בַּהֵיכָל הַשְּׁלִישִׁי הַזֶּה, וְלֹא עוֹמֵד לְהִתְיַשֵּׁב אֶלָּא בְּתוֹךְ הַהֵיכָל הָרְבִיעִי שֶׁהִשְׁתּוֹקְקוּתוֹ לַעֲלוֹת לְתוֹכוֹ."],[7,"","הַמְּאוֹרוֹת הַלָּלוּ שֶׁיָּצְאוּ מִתּוֹךְ אוֹתָהּ הָרוּחַ, כְּשֶׁנּוֹצְצִים מִתְחַבְּרִים כָּל הַמְּאוֹרוֹת הַנּוֹצְצִים. בְּשָׁעָה שֶׁיּוֹצְאִים מִתּוֹךְ אוֹתוֹ אוֹר אֶחָד וְדוֹחֲקִים וְדוֹחִים לְהִתְנוֹצֵץ. יוֹצֵאת מֵהֶם חַיָּה אַחַת קְדוֹשָׁה גְּדוֹלָה, דְּמוּתָהּ כַּמַּרְאֶה שֶׁל כָּל אֵלּוּ שְׁאָר הַחַיּוֹת. דְּמוּת אַרְיֵה וּדְמוּת נֶשֶׁר כְּלוּלִים כְּאֶחָד, וְנַעֲשׂוּ בָהּ דְּמוּת אַחַת מֵהֶם."]]],[["תְּחוֹת הַאי חֵיוָתָא אִית ד' אוֹפַנִּין עִלָּאִין (חיזו דלהון) כְּחֵיזוּ דְתַרְשִׁישׁ מְרַקְמָן בִּכְלִילוּ דְּכָל גְּוָונִין. וְשִׁית מְאָה אֶלֶף רִבּוֹא (רברבן) כֻּלְהוּ בְּגַוַויְהוּ. וְאִלֵּין ד' אוֹפַנִּים בִּתְמַנְיָא גַּדְפִין כֻּלְהוּ. וְכֻלְהוּ נָפְקִין מִגּוֹ נְהִירוּ דְּהַהוּא חֵיוָתָא דְּשָׁלְטָא עֲלַיְיהוּ. בְּשַׁעֲתָא דְּנָצִיץ הַהוּא נְהוֹרָא מַפְקָא חַיָילִין חַיָילִין אִלֵּין.","וְאִלֵּין ד' דִּתְחוֹתָהּ קַיָּימִין בְּד' סִטְרִין דְעָלְמָא בְּד' אַנְפִּין כָּל חַד וְחַד. תְּרֵין אַנְפִּין מִסְתַּכְּלָן לְגַבֵּי הַהוּא חֵיוָתָא. וּתְרֵין אַנְפִּין מְחַפְיָין בְּגַדְפַיְיהוּ מֵאִנּוּן נְהוֹרִין דְּנָצְצָן דְּלָא יָכְלִין לְאִסְתַּכָּלָא.","בְּכָל זִמְנָא דְּנָטְלֵי אִלֵּין בְּד' גַּלְגַּלִּין (ד\"א ותריסר) (ותרין) סַמְכִין כְּקַדְמָאֵי אִתְעֲבִיד מֵהַהוּא זֵיעָא דִלְהוֹן כַּמָּה חַיָילִין וּמַשִּׁרְיָין דְכֻלְהוּ מְשַׁבְּחִין וּמְזַמְּרֵי דְּלָא מִשְׁתַּכְּכֵי לְעָלְמִין. וּלְאִלֵּין לֵית לוֹן שִׁעוּרָא.","אַרְבַּע פִּתְחִין אִית לְהֵיכָלָא דָא לְאַרְבַּע סִטְרִין דְּעָלְמָא. עֶשֶׂר מְמַנָּן בְּכָל פִּתְחָא וּפִתְחָא. וּבְזִמְנָא דְּכֻלְהוּ דִּי בְּגוֹ הֵיכָלִין דִּלְתַתָּא. וְאִנּוּן הֵיכָלִין סָלְקִין בִּרְעוּ דִצְלוֹתָא דַכְיָיא. כֻּלְהוּ פָּתְחִין פִּתְחִין. עַד דִּכְלִילָן כֻּלְהוּ אִלֵּין בְּאִלֵּין. וּמְשַׁלְּבִין אִלֵּין בְּאִלֵּין. וְעָאלִין כֻּלְהוּ מְמַנָּן גּוֹ מְמַנָּן. מַשִּׁרְיָין גּוֹ מַשִּׁרְיָין. אוֹפַנִּים בְּחַיּוֹת וְחַיּוֹת בְּאוֹפַנִּים. בְּאִלֵּין אוֹפַנִּים, נְהוֹרִין בִּנְהוֹרִין רוּחָא בְּרוּחָא. עַד דְּעָאלוּ בְּרוּחָא דָא.","בְּהֵיכָלָא דָא אִית דּוּכְתָּא חָדָא כְּחֵיזוּ דְּדַהֲבָא דְּנָצִיץ. וְתַמָּן גְּנִיזִין כַּמָּה חַיָּילִין וּמַשִּׁרְיָין דְּלָא סָלְקִין וְלָא מִתְעַטְּרִין לְעֵילָא אֶלָא בְּשַׁעֲתָא דְּכָל אִלֵּין קָשְׁרִין קְשִׁירָן וְהֵיכָל נָטִיל לְאִתְעַטְּרָא כֻּלְהוֹן נָפְקִין מַלְיָין בְּדִינָא. וְאִקְרוּן מָארֵי תְּרֵיסִין. שְׁלִיחָן בְּעָלְמָא מִגּוֹ מָארֵי דִינִין דִּי בְּהֵיכָלָא רְבִיעָאָה. בְּהַאי דוּכְתָּא תַּלְיָין בְּאַרְבַּע סִטְרִין שִׁית מְאָה אֶלֶף רִבְוָון מְגִינִים דְּדַהֲבָא לְכָל סְטַר וּסְטַר. וְכֵן לְתַתָּא מִנַּיְיהוּ שׁוּרִין מַקְּפָן וְאִנּוּן שִׁתִּין.","וְכָל הָנֵי מְגִינִים כֻּלְהוּ מַגִּיחִין קְרָבִין סְיָיפִין וְרוֹמְחִין לְבַר בְּכָל אִנּוּן שְׁלִיחֵי דִינִין דְּעָלְמָא עַד דְּמָטוּ דַּרְגִּין בְּדַרְגִּין לְכֹכָבָא דְּמַאְדִּים. וּכְדֵין הֵיכָלָא סַלְקָא וְאִתְעַטְּרַת בְּהַהוּא רוּחָא בְּכָל אִנּוּן חַיָילִין וְאִשְׁתָּאַר הַהוּא דוּכְתָּא בְּאַתְרֵיהּ. וְהַהוּא דוּכְתָּא אִקְרֵי תָּא הָרָצִים. אִנּוּן שְׁלִיחִין מְרַהֲטֵי לְאַשְׁלָמָא דִינִין וּפֻרְעָנִין בְּכָל סִטְרֵי עָלְמָא.","כַּד סָלְקָא צְלוֹתָא נָטִיל כָּל הָנֵי נְהוֹרִין וּמַשִּׁרְיָין וְקָשַׁר קְשָׁרִין וְאִתְכְּלִילוּ כֻּלְהוּ כְּחֲדָא. עַד דְּאִתְקְשַׁר רוּחָא בְּרוּחָא וְאִנּוּן חַד. וְעָאלוּ גוֹ הַהוּא עַמּוּדָא לְאִתְכְּלָלָא בְּרוּחָא דְּהֵיכָלָא רְבִיעָאָה. זַכָּאָה חוּלָקֵיהּ מַאן דְּיָדַע רָזָא דְמָארֵיהּ וְאָרִים דִּגְלֵיהּ בְּאֲתַר דְּאִצְטְרִיךְ.","וְתָא חֲזֵי כֹּלָּא אִצְטְרִיךְ דָּא לְדָא וְדָא לְדָא לְאַשְׁלָמָא דָא עִם דָּא וּלְאִתְנְהָרָא דָּא בְּדָא עַד דְּסָלִיק כֹּלָּא לְאֲתַר דְּאִצְטְרִיךְ שְׁלִימוּ. מִתַּתָּא בְּקַדְמִיתָא וּמִלְּעֵילָא לְבָתַר. וּכְדֵין אִיהוּ שְׁלִימוּ בְּכָל סִטְרִין וְאִשְׁתְּלִים כֹּלָּא כְּדְקָא יָאוּת.","מָאן דְּיָדַע רָזִין אִלֵּין וְעָבִיד שְׁלִימוּ. דָּא אִיהוּ מִתְדְּבַּק בְּמָארֵיהּ וּבַטִּיל כָּל גְּזֵרִין קָשִׁין. וְאִיהוּ אַעֲטַר לְמָארֵיהּ וּמָשִׁיךְ בִּרְכָאן עַל עָלְמָא. וְדָא אִיהוּ בַּר נָשׁ דְּאִקְרֵי צַדִּיקָא עַמּוּדָא דְעָלְמָא וּצְלוֹתֵיהּ לָא אַהֲדַר רֵיקַנְיָיא וְחוּלָקֵיהּ בְּעָלְמָא דְּאֲתֵי, וְאִיהוּ בְּחוּשְׁבַּן בְּנִי מְהֵימְנוּתָא.","תָּא חֲזֵי כָּל הָנֵי הֵיכָלִין וְכָל הָנֵי חֵיוָתָא וְכָל הָנֵי חַיָלִין וְכָל הָנֵּי נְהוֹרִין וְכָל הָנֵי רוּחִין כֻּלְהוּ אִצְטְרִיכוּ דָא לְדָא. בְּגִין לְאִשְׁתַּלָּמָא מִתַּתָּא. וּלְאִשְׁתַּלָּמָא לְבָתַר מִלְּעֵילָא. אִלֵּין הֵיכָלִין אִנּוּן מִתְדַּבְּקִין דָּא בְּדָא.","וְכֻלְהוּ כְּגוָֹונִין דִּלְּעֵילָא (נ\"א דעינא) מִתְדַּבְּקִין דָּא עִם דָּא. כָּל מַה דִּי בְּגַוַויְיהוּ אִנּוּן כְּהַהוּא חֵיזוּ דְּמִתְחַזְּיָא (צז א, סב) בִּסְתִימוּ כַּד מִתְגַּלְגְּלָא עֵינָא וְאִתְחַזֵּי הַהוּא זָהֲרָא נָצִיץ. וְהַהוּא מַה דְּלָא אִתְחַזֵּי (ביה) בְּהַהוּא גִלְגּוּלָא. אִיהוּ הַהוּא רוּחָא דְּשָׁלְטָא עַל כֹּלָּא. וּבְגִין כָּךְ קָיְימָא דָא בְדָא דַּרְגִּין עַל דַּרְגִּין (ודרגין על דרגין) עַד דְּאִתְעַטַּר כֹּלָּא כְּדְקָא יָאוּת."],[[0,"תחות האי חיוותא אית ד' אופנין עלאין כחיזו דתרשיש מרקמן בכלילו דכל גוונין:","תחת החיה הזו, יש ד' אופנים עליונים, כמראה התרשיש, מרוקמים בכללות מכל ד' הגוונין: לבן אדום ירוק שחור. פירוש, כי אלו ד' האופנים הם בחינת מחזה ולמטה של חיה האחת הנ\"ל וע\"כ אומר תחות \u0003האי חיוותא,\u0004 כי כל מקום שנאמר \u0003תחת\u0004 פירושו מחזה ולמטה של אותו מדרגה, והם ארבעה, להיותם התפשטות מארבע הספירות חו\"ב תו\"מ של החיה, אמנם כל אופן ואופן כלול מכל הד', וע\"כ אומר \u0003מרקמן בכלילו דכל גוונין,\u0004 שכל אחד מהם כלול מכל ארבעה הגוונין חו\"ב תו\"מ."],[0,"ושית מאה אלף רבוא כלהו בגווייהו.","ושש מאות אלף אורות כולם הם בתוכם. והיינו לאפוקי מד' האופנים שבהיכל היסוד (לעיל דף מ\"ד אות ס\"ז) שיש להם י\"ג מאות רבוא שיורה על הארת חכמה המקובלת מי\"ג מדות דא\"א שמקומם בהאופנים שמחזה ולמטה. (ע\"ש בהסולם) אבל בהאופנים שבכאן אע\"פ שהם מחזה ולמטה מ\"מ אינם. מאירים בי\"ג מאות רבוא, דהיינו בהארת חכמה אלא רק בשש מאות אלף רבוא, שיורה על הארת או\"א עלאין בחסדים מכוסים, המאיר בשש הספירות חב\"ד חג\"ת שמחזה ולמעלה, דהיינו בהחיה שעליהם, והם שש מאות להיותם בחינת בינה שספירותיה בסוד מאות, כי היכלות הללו כולם בחינת בינה הם, והם שש מאות אלף להיות מקובלים מאו\"א שספירותיהם בסוד אלף. והם שש מאות רבוא להיות בהם הארת חכמה סתימאה דא\"א (כנ\"ל במראות הסולם דף ל\"ו ד\"ה ולפיכך עש\"ה) וע\"כ הם שש מאות אלף רבוא. והטעם שאינם מאירים במספר י\"ג, הוא, כי כל היכל נצח הוא בחינת ג\"ר ואפילו האופנים נחשבים כבחינת מחזה ולמעלה. אמנם על ידי אור הגלגול מן היכלות התחתונים מתפשטים גם האופנים בעת ההוא למספר י\"ג, וכל אופן יש לו י\"ב סמכין וחד דכליל לון, כמ\"ש לפנינו. ואין זה אלא ע\"י הארת הגלגול, אבל בקביעות אינם מאירים אלא במספר שש מאות אלף רבוא. כמבואר."],[0,"ואלין ד' אופנים בתמניא גדפין כלהו,","ואלו ד' האופנים הם כולם בשמונה כנפים. והטעם יתבאר להלן בדיבור הסמוך. \u0003וכלהו נפקין מגו נהירו דההוא חיוותא דשלטא עלייהו,\u0004 וכל אלו הבחינות שבאופנים יוצאות מאור החיה שעליהם השולטת עליהם, \u0003בשעתא דנציץ ההוא נהורא מפקא חיילין חיילין אלין,\u0004 בעת שאור החיה מתנוצץ, דהיינו בעת שהארת הגלגול מאיר בהם, יוצאים כל הצבאות הללו."],[1,"ואלין ד' דתחותה קיימין בד' סטרין דעלמא, בד' אנפין כל חד וחד,","ואלו ד' האופנים שמתחת החיה, עומדים לד' רוחות העולם. מזרח מערב וכו'. בכל אחד ואחד ד' פנים. \u0003תרין אנפין מסתכלן לגבי ההוא חיוותא ותרין אנפין מחפיין בגדפייהו מאינון נהורין דנצצן דלא יכלין לאסתכלא,\u0004 בב' פנים הם מסתכלים אל החיה שעליהם, וב' פנים מכסים בכנפיהם, משום האורות המתנוצצים עליהם, שאינם יכולים להסתכל בהם."],[1,"","פירוש, כי אלו ג' היכלות מאירים עי\"מ דאחורים, שהיכל היסוד מאיר בחינת עיבור יניקה שהם ו\"ק חסר מוחין דג\"ר, וב' היכלות נצח והוד מאירים המוחין דג\"ר, היכל הוד מאיר הו\"ק דג\"ר, והנצח ג\"ר דג\"ר. כמ\"ש במראות הסולם כאן (דף מ' ד\"ה והנה) ונודע שבחינת ג\"ר דג\"ר אינם מאירים כלל אלא רק הו\"ק דג\"ר בלבד. ועכ\"ז אי אפשר שיצאו ו\"ק דג\"ר בלי הג\"ר דג\"ר, (כנ\"ל בבראשית א' דף פ' ד\"ה אמנם) והנה מקום יציאת המוחין הוא בהיכל הנצח בלבד. ולפיכך יוצאים הג\"ר וו\"ק דג\"ר ביחד בשלמות בהיכל הנצח, אבל רק הו\"ק דג\"ר מקובלים ובאים להיכל ההוד והג\"ר דג\"ר נעלמים. כמ\"ש שם באורך."],[1,"","וזה אמרו \u0003תרין אנפין מסתכלן לגבי ההוא חיוותא,\u0004 כי הפנים הם בחינת ג\"ר, ויש בהם חו\"ב תו\"מ, הנקראים ד' אנפין, שהחו\"ב הם ג\"ר דג\"ר, ותו\"מ הם ו\"ק דג\"ר, ואומר שב' פנים מסתכלים ומקבלים מהחיה שעליה, והיינו תפארת ומלכות שבהם, שהם ו\"ק דג\"ר המקובלים. \u0003ותרין אנפין מחפיין בגדפייהו\u0004 וב' פנים מתכסים בכנפיהם, והיינו חו\"ב שבהם, שהם ג\"ר דג\"ר שאינם מקובלים, וז\"ש, \u0003מאינון נהורין דנצצן דלא יכלין לאסתכלא\u0004 דהיינו הנהורין דג\"ר דג\"ר, שאינם יכולים להסתכל בהם ולקבלם, ע\"כ הם מכסים בכנפיהם את ב' הפנים חו\"ב שבהם שלא יקבלו משם."],[1,"","ומטעם זה, אומר, \u0003ואלין ד' אופנים בתמניא גדפין כלהו,\u0004 כי השרפים שבהיכל ההוד יש להם שית גדפין, בשתים יכסה פניו, ובשתים יכסה רגליו, ובשתים יעופף. ואין להם ד' כנפים בהפנים שלהם אלא ב' כנפים בלבד, כי להיותם בחינת הוד, צריכים לכסות כל ד' הפנים שלהם, ואין להם ב' פנים גלוים כמו האופנים שבהיכל הנצח. אבל האופנים שבכאן שהם במקום יציאת המוחין, וצריכים לקבל הו\"ק דג\"ר שישפיעו להשרפים שבהיכל ההוד, ע\"כ יש להם בהכרח ב' פנים גלוים שהם תו\"מ, ומשום זה יש להם שמונה גדפין. דהיינו ב' גדפין יתירים. אשר בעת התנוצצות הם פתוחים בכדי לקבל הו\"ק דג\"ר בשביל היכל ההוד. ושלא בעת ההתנוצצות גם הם מכוסים."],[2,"בכל זמנא דנטלי אלין בד' גלגלין ותריסר סמכין כקדמאי אתעביד מההוא זיעא דלהון כמה חיילין ומשריין:","בכל פעם שהאופנים האלו נוסעים, בד' גלגלין וי\"ב סמכין בכל אופן ואופן, כמו הראשונים שבהיכל היסוד, דהיינו בעת שאור הגלגול מאיר בהם, נעשה אז מהזיעה שלהם כמה צבאות ומחנות, \u0003דכלהו משבחין ומזמרי דלא משתככי לעלמין, ולאלין לית לון שיעורא,\u0004 שכולם משבחים ומזמרים, ואינם פוסקים שירתם לעולם. וצבאות האלו אין להם שיעור."],[2,"","ביאור הדברים. כי סוד השירה והזמרה היא המשכת המוחין, ולפי שיעור הארת המוחין כן שיעור שירות ותשבחות שמזמרים. ונודע שהמוחין נמשכים בדרך ג' קוין, שקו ימין ה\"ס מים וחסדים, וקו שמאל ה\"ס חכמה בלי חסדים, שאין התחתונים יכולים לקבלו והוא להם אש שורף. ואלו ב' הקוין הם במחלוקת זה עם זה, עד שנמשך קו הג' המקיים את שניהם על ידו שמלביש אותם זה בזה, (כנ\"ל דף מ\"ג ד\"ה וזה אמרו עש\"ה)"],[2,"","וז\"ס הזיעה שהחיות מזיעים בעת שמגיע להם אור הגלגול ונוסעות על ד' הגלגלים וי\"ב הסמכין. כי אז צריכים להזהר מאד לקבל המוחין בבחינת קו אמצעי, ואם נוטים משהו לצד שמאל, תכף נמשך להם משם אש שורף בסבת הנטיה. וכיון שאינם יכולים לצמצם כל כך, נמצאים עושים פעם נטיה יתירה לצר שמאל וממשיכים בזה ניצוץ אש שורף, ואז תכף נוטים עצמם בכח לצד ימין כדי לבא משם לבחינת קו אמצעי. וממשיכים עם נטיה זו אור חסדים. וכן הם מנענעים עצמם תמיד פעם לימין ופעם לשמאל כי קשה להם לצמצם עצמם בקו אמצעי כראוי. והנה אלו הנטיות שמצד שמאל ה\"ס זיעת החיות, שמהם מתקבץ ונמשך נהר דינור. ומאלו הנטיות לצד ימין נבראו מהם אלו צבאות ומחנות מלאכים \u0003דכלהו משבחין ומזמרי דלא משתככי לעלמין,\u0004 כי מתוך שהם נמשכים מהנטיות לצד ימין, שהוא חסד, אין שום כח יוכל להפסיק את שירתם. וכן \u0003ולאלין לית לון שיעורא,\u0004 כי מוחין דחסדים נבחנים לבלי מספר (כנ\"ל בהקדמת הזהר דף ל' ד\"ה וזה)."],[3,"ארבע פתחין אית להיכלא דא לארבע סטרין דעלמא, עשר ממנן בכל פתחא ופתחא,","ד' פתחים יש בהיכל זה לד' רוחות העולם, עשרה ממונים הם בכל פתח ופתח. אשר תפקידם הוא, \u0003ובזמנא דכלהו די בגו היכלין דלתתא, ואינון היכלין סלקין ברעו דצלותא דכיא כלהו פתחין פתחין,\u0004 ובעת, שחנמצאים כולם שבתוך היכלות התחתונים, יסוד והוד, וההיכלות עצמם, עולים להיכל שבכאן, בכח הרצון שבתפלה הטהורה, אז הממונים הנ\"ל פותחים לפניהם את הפתחים שבהיכל הזה. \u0003עד דכלילן כלהו אלין באלין ומשלבין אלין באלין ועאלין כלהו ממנן גו ממנן משריין גו משריין,\u0004 עד שנכללים אלו באלו ומשתלבים אלו באלו, ונכנסים כולם זב\"ז, ממונים בממונים מחנות במחנות \u0003אופנים בחיות וחיות באופנים, באלין אופנים נהורין בנהורין רוחא ברוחא עד דעאלו ברוחא דא,\u0004 אופנים בחיות וכו' ובאלו אופנים נכללים אורות באורות, שהם פנים דאתחזון בפנים דלא אתחזון, ורוח ברוח עד שנכנסים כולם בהרוח שבהיכל זה."],[4,"בהיכלא דא אית דוכתא חדא, כחיזו דדהבא דנציץ, ותמן גניזין כמה חיילין ומשריין דלא סלקין ולא מתעטרין לעילא:","בהיכל הזה יש מקום אחד שמראהו כמראה זהב שמתנוצץ, כלומר ששם מקום קבוץ של הגבורות, הממותקות המכונים זהב. והארת האו\"ח שלו נק' ניצוץ. ושם גנוזים כמה צבאות ומחנות מלאכים שאינם עולים ואינם מתעטרים למעלה, כלומר שאינם עולים לתיכלות העליונות לקבל ג\"ר הנק' עטרות, ונשארים תמיד במקומם בהיכל זה. \u0003אלא בשעתא דכל אלו קשרין קשירן, והיכל נטיל לאתעטרא כלהו נפקן מליין בדינא,\u0004 אלא בשעה שכל המדרגות קושרים קשרים דהיינו שנכללים ומתיחדים זב\"ז, והיכל זה, נצח, נוסע להתעטר בג\"ר, אז כולם, דהיינו כל המלאכים הגנוזים במקום הנ\"ל, יוצאים ממקום גניזתם מלאים בדינים, כלפי המקטרגים על ישראל, ויכולים ישראל לקבל שפע דג\"ר בלי פחד מאחיזת החיצונים. \u0003ואקרון מארי תריסין, שליחן בעלמא, מגו מארי דינין די בהיכלא רביעאה,\u0004 והם נקראים בעלי המגינים, להיותם מגינים על ישראל, והם שליחים בעולם מן בעלי הדין שבהיכל הרביעי. כי שם יושבים ושוקלים מעשי התחתונים אם לכף חובה אם לכף זכות, כמ\"ש להלן במקומו, ואחר שישראל יוצאים זכאים ע\"י הבית דין אשר שם נמסר זה אל השליחים הללו, להגין עליהם."],[4,"בהאי דוכתא תליין בארבע סטרין שית מאה אלף רבבן מגינים דדהבא לכל סטר וסטר:","במקום הזה תלוים בד' צדדיו, שש מאות רבבות מגיני זהב לכל צד וצד. \u0003וכן לתתא מנייהו שורין מקפן ואנון שתין,\u0004 וכן יש למטה מהם, שורות מקיפים במגיני זהב והם ששים. כלומר שמאירים בהם ב' בחי' ו\"ק, א) ו\"ק דישסו\"ת שעלו עם או\"א לראש א\"א, ומבחינתם הם שש מאה אלף רבוא, שש מאה הם ו\"ק דישסו\"ת שספירותיו בסוד מאות, אלף הם מצד או\"א שספירותיו בסוד אלף, ורבבות הם מצד א\"א שספירותיו בסוד רבבות. ב) היינו ו\"ק דז\"א המקבלים מישסו\"ת, ומבחינתו הם רק ששים בלבד, כי ספירות דז\"א הם בסוד עשרות."],[5,"וכל הני מגינים כלהו מגיחין קרבין סייפין ורומחין לבר בכל אנון שליחי דינין דעלמא עד דמטו דרגין בדרגין לככבא דמאדים:","וכל אלו המגינים עושים מלחמה כולם לחוץ מההיכל בחרבות ורמחים, בכל אלו שלוחי הדין שבעולם, ומבערים אותם, עד שמגיע הארת המדרגות בהמדרגות שלמטה ומגיעים לככב לכת הנק' מאדים. שמשם מגיעים הפעולות לעוה\"ז."],[5,"וכדין היכלא סלקא ואתעטרת בההוא רוחא בכל אינון חיילין, ואשתאר ההוא דוכתא באתריה:","ואז עולה ההיכל להיכל הרביעי ומתעטר בהרוח ובכל אלו הצבאות אשר שם, ואותו מקום, עם המארי תריסין ומגיני הזהב, נשאר במקומו ואינו עולה למעלה עם ההיכל. כנ\"ל, \u0003וההוא דוכתא אקרי תא הרצים, אינון שליחין מרהטי לאשלמא דינין ופורענין בכל סטרי עלמא,\u0004 ואותו המקום נקרא תא הרצים, כי אלו השליחים שבו, רצים לגמור הדינים והעונשים לשונאי ישראל שבכל רוחות העולם. פירוש, כי אלו השליחים גנוזים באותו מקום כנ\"ל, \u0003אלא בשעתא\u0004 וכו' \u0003והיכל נטיל לאתעטרא כלהון נפקין\u0004 וכו' הרי ששעת פעולתם להגין על ישראל אינה רק ברגע עלית ההיכל אל ההיכל שלמעלה ממנו, כי אח\"כ שוב נגנזים. ולפיכך הם רצים וממהרים בשליחותם שיספיקו לכלות כל המקטרגים מטרם שיעלה ההיכל. ומטעם זה נק' המקום בשם תא הרצים."],[6,"כד סלקא צלותא נטיל כל הני נהורין ומשריין וקשר קשרין ואתכלילו כלהו כחדא,","עם עליית התפילה, נוסעים כל אלו האורות והמחנות, וקושרים קשרים, ונכללים כולם כאחד, \u0003עד דאתקשר רוחא ברוחא ואינון חד, ועאלו גו ההוא עמודא לאתכללא ברוחא דהיכל רביעאה,\u0004 עד שנקשר רוח של היכל התחתון ברוח של היכל זה ונעשו אחד, ונכנסים כולם תוך העמוד שבאמצע ההיכל, ועולים בכחו להתכלל בהרוח שבהיכל הרביעי העליון עליהם. \u0003זכאה חולקיה מאן דידע רזא דמאריה וארים דגליה באתר דאצטריך,\u0004 אשרי חלקו מי שיודע סוד רבונו, ומרים דגלו במקום שצריך."],[7,"ות\"ח כלא אצטריך דא לדא ודא לדא לאשלמא דא עם דא ולאתנהרא דא בדא:","ובוא וראה כל המדרגות כולם, צריכים זה לזה וזה לזה, להשלים האחד עם חברו, ולהאיר אחד בחברו, \u0003עד דסליק כלא לאתר דאצטריך שלימו, מתתא בקדמיתא ומלעילא לבתר\u0004 עד שכולם עולים להמקום שצריך שלימות, מתחילה עולים מלמטה, להשלים המקום העליון, ואח\"כ יורדים מלמעלה למטה להשלים התחתונים, \u0003וכדין איהו שלימו בכל סטרין ואשתלים כלא כדקא יאות,\u0004 ואז נעשה שלימות מכל הצדדים, וכולם נשלמים כראוי."],[8,"מאן דידע רזין אלין ועביד שלימו, דא איהו מתדבק במאריה ובטיל כל גזרין קשין:","מי שיודע סודות הללו ועושה השלמות הנ\"ל למעלה ולמטה, זה הוא מתדבק ברבונו ומבטל כל גזרות הקשות, \u0003ואיהו אעטר למאריה ומשיך ברכאן על עלמא, ודא הוא בר נש דאקרי צדיקא עמודא דעלמא,\u0004 והוא מעטר לרבונו דהיינו שממשיך ג\"ר לז\"א, וממשיך ברכות אל העולם, וזהו האדם הנקרא צדיק עמוד העולם, כלומר שהעולם עומד ומתקיים בשבילו. \u0003וצלותיה לא אהדר ריקניא, וחולקיה בעלמא דאתי, ואיהו בחושבן בני מהימנותא,\u0004 ותפלתו אינה חוזרת ריקם, כלומר שנענה על כל תפלותיו, וחלקו הוא בעולם הבא, והוא בחשבון בעלי האמונה. כלומר, שהוא נכנס בחשבון בעלי האמונה הנמצאים בעולם."],[9,"ת\"ח בל הני היכלין, וכל הני חיותא וכו' וכל הני נהורין,וכל הני רוחין:","בוא וראה, כל אלו ההיכלות, וכל אלו החיות, וכל אלו הצבאות, וכל אלו האורות, וכל אלו הרוחות, \u0003כלהו אצטריכו דא לדא בגין לאשתלמא מתתא ולאשלמא לבתר מלעילא,\u0004 כולם צריכים זה לזה בכדי שהעליונים ישתלמו ע\"י העלאת מ\"ן מלמטה, ואח\"כ ישתלמו התחתונים ע\"י הורדת מ\"ד מלמעלה, \u0003אלין היכלין אינון מתדבקין דא בדא,\u0004 היכלות האלו מתדבקים זה בזה."],[10,"וכלהו כגוונין דעינא מתדבקין דא עם דא:","וכולם מתדבקים זה עם זה כמו הצבעים שבעין, \u0003כל מה די בגוייהו אינון כהאי חיזו דמתחזיא בסתימו כד מתגלגלא עינא,\u0004 כל מה שבהם הם כמראה הנראה בהסתום שבעין בעת שהעין מתגלגל, \u0003ואתחזי ההוא זהרא נציץ, וההוא מה דלא אתחזי ביה בההוא גלגולא, איהו ההוא רוחא דשלטא על כלא,\u0004 ונראה אז זהר ההוא המתנוצץ, ואותו שאינו נראה בו בגלגול הזה, הוא הרוח ההוא השולט על הכל, דהיינו הרוח שבהיכל זה. וביאור הדברים תמצא לעיל (בדף נ\"ו ד\"ה כד). \u0003ובגין כך קיימא\u0004 כו' \u0003דרגין על דרגין עד דאתעטר כלא כדקא יאות,\u0004 ומשום זה, עומדים כולם מדרגות על מדרגות, כלומר שהאחת תלויה בחברתה, עד שהכל מתעטר כראוי."]],[[0,"","תַּחַת הַחַיָּה הַ את יֵשׁ אַרְבָּעָה אוֹפַנִּים עֶלְיוֹנִים כְּמַרְאֵה תַרְשִׁישׁ מְרֻקָּם בִּכְלִילוּת כָּל הַגְּוָנִים. וְשֵׁשׁ מֵאוֹת אֶלֶף רִבּוֹא (גדולים) כֻּלָּם בְּתוֹכָם. וְאַרְבָּעָה הָאוֹפַנִּים הַלָּלוּ כֻּלָּם בִּשְׁמוֹנֶה כְנָפַיִם, וְכֻלָּם יוֹצְאִים מִתּוֹךְ אוֹר אוֹתָהּ הַחַיָּה שֶׁשּׁוֹלֶטֶת עֲלֵיהֶם. בְּשָׁעָה שֶׁנּוֹצֵץ אוֹתוֹ הָאוֹר, מוֹצִיאָה צְבָאוֹת צְבָאוֹת הַלָּלוּ."],[1,"","וְאַרְבָּעָה אֵלֶּה שֶׁתַּחְתֶּיהָ עוֹמְדִים בְּאַרְבַּעַת צִדְדֵי הָעוֹלָם בְּאַרְבַּע פָּנִים כָּל אֶחָד וְאֶחָד. שְׁתֵּי פָנִים מִסְתַּכְּלוֹת לְאוֹתָהּ הַחַיָּה, וּשְׁתֵּי פָנִים מְכֻסּוֹת בְּכַנְפֵיהֶם מֵאוֹתָם אוֹרוֹת שֶׁנּוֹצְצִים שֶׁלֹּא יְכוֹלִים לְהִסְתַּכֵּל."],[2,"","בְּכָל פַּעַם שֶׁנּוֹסְעִים אֵלֶּה בְּאַרְבָּעָה גַלְגַּלִּים (ד\"א ושנים עשר) (ושנים) עַמּוּדִים כָּרִאשׁוֹנִים נַעֲשֶׂה מֵאוֹתָהּ הַזֵּעָה שֶׁלָּהֶם כַּמָּה צְבָאוֹת וּמַחֲנוֹת שֶׁכֻּלָּם מְשַׁבְּחִים וּמְזַמְּרִים שֶׁלֹּא שׁוֹקְטִים לְעוֹלָמִים. וּלְאֵלֶּה אֵין לָהֶם שִׁעוּר."],[3,"","אַרְבָּעָה פְתָחִים יֵשׁ לַהֵיכָל הַזֶּה לְאַרְבַּעַת צִדְדֵי הָעוֹלָם. עֲשָׂרָה מְמֻנִּים בְּכָל פֶּתַח וּפֶתַח. וּבִזְמַן שֶׁכֻּלָּם שֶׁבְּתוֹךְ הַהֵיכָלוֹת שֶׁלְּמַטָּה, וְאוֹתָם הֵיכָלוֹת עוֹלִים בְּרָצוֹן שֶׁל תְּפִלָּה זַכָּה, כֻּלָּם פּוֹתְחִים פְּתָחִים עַד שֶׁנִּכְלָלִים כֻּלָּם אֵלֶּה בְּאֵלֶּה, וּמְשֻׁלָּבִים אֵלֶּה בְּאֵלֶּה, וְנִכְנָסִים כָּל הַמְמֻנִּים לְתוֹךְ מְמֻנִּים, מַחֲנוֹת בְּתוֹךְ מַחֲנוֹת, אוֹפַנִּים בְּחַיּוֹת וְחַיּוֹת בְּאוֹפַנִּים. בָּאוֹפַנִּים הַלָּלוּ מְאוֹרוֹת בִּמְאוֹרוֹת, רוּחַ בְּרוּחַ, עַד שֶׁנִּכְנָסִים בְּרוּחַ זוֹ."],[4,"","בַּהֵיכָל הַזֶּה יֵשׁ מָקוֹם אֶחָד כְּמַרְאֵה זָהָב שֶׁנּוֹצֵץ, וְשָׁם גְּנוּזִים כַּמָּה צְבָאוֹת וּמַחֲנוֹת שֶׁלֹּא עוֹלִים וְלֹא מִתְעַטְּרִים לְמַעְלָה, אֶלָּא רַק בְּשָׁעָה שֶׁכָּל אֵלֶּה קוֹשְׁרִים קְשָׁרִים, וְהַהֵיכָל נוֹסֵעַ לְהִתְעַטֵּר. כֻּלָּם יוֹצְאִים מְלֵאִים בְּדִין, וְנִקְרָאִם מַחֲזִיקֵי מָגִנִּים. שְׁלוּחִים בָּעוֹלָם מִתּוֹךְ בַּעֲלֵי הַדִּין שֶׁבַּהֵיכָל הָרְבִיעִי. בְּמָקוֹם זֶה תְּלוּיִים בְּאַרְבָּעָה צְדָדִים שֵׁשׁ מֵאוֹת אֶלֶף רִבּוֹא מָגִנִּים שֶׁל זָהָב לְכָל צַד וְצַד. וְכֵן לְמַטָּה מֵהֶם חוֹמוֹת מַקִּיפוֹת, וְהֵם שִׁשִּׁים."],[5,"","וְכָל הַמָּגִנִּים הַלָּלוּ נִלְחָמִים קְרָבוֹת בַּחֲרָבוֹת וּרְמָחִים, פְּרָט לְכָל אוֹתָם שְׁלוּחֵי הַדִּין שֶׁל הָעוֹלָם, עַד שֶׁמַּגִּיעִים דְּרָגוֹת בִּדְרָגוֹת לְכוֹכָב מַאְדִּים. וְאָז הַהֵיכָל עוֹלֶה וּמִתְעַטֵּר בְּאוֹתָהּ רוּחַ בְּכָל אוֹתָם צְבָאוֹת, וְנִשְׁאָר אוֹתוֹ מָקוֹם בִּמְקוֹמוֹ. וְאוֹתוֹ מָקוֹם נִקְרָא תָּא הָרָצִים. אוֹתָם הַשְּׁלוּחִים רָצִים לְהַשְׁלִים דִּינִים וּפֻרְעָנֻיּוֹת בְּכָל צִדְדֵי הָעוֹלָם."],[6,"","כְּשֶׁעוֹלָה תְפִלָּה, נוֹשֵׂאת כָּל הַמְּאוֹרוֹת הַלָּלוּ וְהַמַּחֲנוֹת, וְקוֹשֶׁרֶת קְשָׁרִים וְנִכְלָלִים כֻּלָּם כְּאֶחָד, עַד שֶׁנִּקְשָׁר רוּחַ בְּרוּחַ וְהֵם אֶחָד. וְנִכְנָסִים לְתוֹךְ אוֹתוֹ עַמּוּד לְהִכָּלֵל בָּרוּחַ שֶׁל הַהֵיכָל הָרְבִיעִי. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁיּוֹדֵעַ סוֹד רִבּוֹנוֹ וּמֵרִים דִּגְלוֹ בְּמָקוֹם שֶׁצָּרִיךְ."],[7,"","וּבֹא וּרְאֵה, הַכֹּל צָרִיךְ זֶה לָזֶה וְזֶה לָזֶה לְהַשְׁלִים זֶה עִם זֶה וּלְהָאִיר זֶה בָּזֶה, עַד שֶׁעוֹלֶה הַכֹּל לְמָקוֹם שֶׁצָּרִיךְ שְׁלֵמוּת. מִלְּמַטָּה בַּהַתְחָלָה, וְאַחַר כָּךְ מִלְמַעְלָה, וְאָז הַשְּׁלֵמוּת הִיא בְּכָל הַצְּדָדִים וְנִשְׁלָם הַכֹּל כָּרָאוּי."],[8,"","מִי שֶׁיּוֹדֵעַ הַסּוֹדוֹת הַלָּלוּ וְעוֹשֶׂה שְׁלֵמוּת, זֶהוּ שֶׁמִּתְדַּבֵּק בְּרִבּוֹנוֹ וּמְבַטֵּל כָּל הַגְּזֵרוֹת הַקָּשׁוֹת, וְהוּא מְעַטֵּר אֶת רִבּוֹנוֹ וּמוֹשֵׁךְ בְּרָכוֹת עַל הָעוֹלָם. וְזֶהוּ אָדָם שֶׁנִּקְרָא צַדִּיק עַמּוּד הָעוֹלָם, וּתְפִלָּתוֹ לֹא חוֹזֶרֶת רֵיקָם, וְחֶלְקוֹ בָּעוֹלָם הַבָּא, וְהוּא בְּחֶשְׁבּוֹן בְּנֵי הָאֱמוּנָה."],[9,"","בֹּא רְאֵה, כָּל הַהֵיכָלוֹת הַלָּלוּ וְכָל הַחַיּוֹת הַלָּלוּ וְכָל הַצְּבָאוֹת הַלָּלוּ וְכָל הָאוֹרוֹת הַלָּלוּ וְכָל הָרוּחוֹת הַלָּלוּ צְרִיכִים זֶה לָזֶה, כְּדֵי לְהִשְׁתַּלֵּם מִלְּמַטָּה וּלְהִשְׁתַּלֵּם אַחַר כָּךְ מִלְמַעְלָה. הַהֵיכָלוֹת הַלָּלוּ הֵם מִתְדַּבְּקִים זֶה בָּזֶה."],[10,"","וְכֻלָּם כְּמוֹ הַגְּוָנִים שֶׁלְּמַעְלָה (של העין) דְּבוּקִים זֶה עִם זֶה. כָּל מַה שֶּׁבְּתוֹכָם הֵם כְּאוֹתוֹ מַרְאֶה שֶׁנִּרְאֶה בַּסֵּתֶר כְּשֶׁמִּתְגַּלְגֶּלֶת הָעַיִן וְנִרְאֶה אוֹתוֹ זֹהַר נוֹצֵץ. וְאוֹתוֹ מַה שֶּׁלֹּא נִרְאֶה בְּאוֹתוֹ גִלְגּוּל, הוּא אוֹתָהּ רוּחַ שֶׁשּׁוֹלֶטֶת עַל הַכֹּל. וְלָכֵן עוֹמֵד זֶה בָּזֶה דְּרָגוֹת עַל דְּרָגוֹת עַד שֶׁמִּתְעַטֵּר הַכֹּל כָּרָאוּי."]]],[["וְתָא חֲזֵי אִלְמָלֵא כָּל אִנּוּן גְּוָונִין דְּעֵינָא דְּאִתְחַזְיָין, כַּד אַסְתִּים עֵינָא וְאִתְגַּלְגְּלָא בְּגַלְגַּלָּא לָא אִתְחַזּוּן אִנּוּן גְּוָונִין דְּזָהֲרָן. וְאִלְמָלֵא אִנּוּן גְּוָונִין, לָא אִתְדָּבַּק הַהוּא דְּסָתִים דְּשָׁלְטָא עֲלַיְיהוּ. אִשְׁתְּכַח דְּכֹלָּא תַּלְיָיא דָא בְּדָא וְאִתְקַשַּׁר דָּא בְּדָא","כַּד אִתְכְּלִיל כֹּלָּא כְּחֲדָא בְּהֵיכָלָא תְּלִיתָאָה. וּרְעוּתָא דִצְלוֹתָא סַלְקָא לְאִתְעַטְּרָא בְּהֵיכָלָא רְבִיעָאָה. כְּדֵין כֹּלָּא חַד. וּרְעוּתָא חָדָא וְקִשּׁוּרָא חָדָא. הָכָא הִשְׁתַחֲוָאָה לְאִתְרַצָּאָה בְּמָארֵיהּ:","הֵיכָלָא רְבִיעָאָה, הֵיכָלָא דָא אִיהוּ מְשַׁנְיָא מִכֻּלְהוּ. אַרְבַּע הֵיכָלִין לְדָא. דָּא לְגוֹ מִן דָּא וְכֻלְהוּ חַד הֵיכָלָא. הָכָא אִיהוּ רוּחָא דְּאִקְרֵי זְכּוּת, בְּאֲתַר דָא מִתְהַפֵּךְ זְכוּת דְּכָל בְּנֵי עָלְמָא. רוּחָא דָא נָטִיל כֹּלָּא.","מִנֵּיהּ נָפְקוּ שִׁבְעִין נְהוֹרִין כֻּלְהוּ מְנַצְצָן. וְכֻלְהוּ בְּעִגּוּלָא דְּלָא מִתְפַּשְׁטֵי כְּאִלֵּין אָחֳרָנִין. מִתְדַּבְּקִין דָּא בְּדָא וּנְהִירִין דָּא בְּדָא אֲחִידָן דָּא בְּדָא. כָּל זַכְיָין דְּעָלְמָא קַמֵּי אִלֵּין נְהוֹרִין קַיָּימִין. מִכֻּלְהוּ נָפְקֵי תְּרֵין נְהוֹרִין שְׁקוּלִין כְּחֲדָא דְּקָיְימֵי קַמַּיְיהוּ תְּדִירָא.","לָקֳבֵל אִלֵּין אִנּוּן שִׁבְעִין רַבְרְבָן מְמַנָּן לְבַר דְּסָחֲרִין כָּל (הני) (ד\"א אנון) אַרְבַּע הֵיכָלִין. שִׁבְעִין נְהוֹרִין אִלֵּין וּתְרֵי נְהוֹרִין דְּקָיְימִין קָמַיְיהוּ כֻּלְהוּ פְּנִימָאִין גּוֹ לְגוֹ. וְרָזָא דָא דִּכְתִיב, (שיר השירים ז׳:ג׳) בִּטְנִךְ עֲרֵמַת חִטִּים סוּגָה בַּשּׁוֹשַׁנִּים.","לְקַמֵּי נְהוֹרִין אִלֵּין עָאלִין כָּל זְכוּ. וְכָל עוֹבָדִין דְּעָלְמָא לְאִתְדְּנָא. תְּרֵין נְהוֹרִין אִלֵּין אִנּוּן סָהֲדֵי סָהֲדוּתָא. בְּגִין (דאנון) דְּאִית שִׁבְעָה עֵינֵי יְיָ דִּמְשַׁטְּטֵי בְּכָל אַרְעָא (ס\"א כן כל) כָּל מַה דְּאִתְעֲבִיד בְּעָלְמָא אִתְרְשִׁים בְּהַהוּא עוֹבָדָא מַמָּשׁ וְהַהוּא זְכוּתָא מַמָּשׁ וְקָיְימֵי בְּקִיּוּמַיְיהוּ. וְאִלֵּין תְּרֵין נְהוֹרִין חָמָאן בְּהוּ וּמִסְתַּכְּלָן וְסָהֲדֵי קַמֵּי אִלֵּין ע' נְהוֹרִין. אִלֵּין ע' גִּזְרֵי גִּזְרִין וְדָיְינֵי דִינִין הֵן לְטַב הֵן לְבִישׁ. וְהָכָא אִיהוּ אֲתַר דִּזְכוּתָא.","רוּחָא דָא בֵּיהּ אִתְרְשִׁימוּ אַתְוָון תְּלַת דְּאִנּוּן (קנט ע\"א) יה\"ו, דְּכַד אִלֵּין אַתְוָון מִתְדַּבְּקָן בְּהַאי אֲתַר בְּאִתְדַּבְּקוּתָא דִּדְכוּרָא וְנוּקְבָא כְּדֵין אִתְרְשִׁימוּ בֵּיהּ וְלָא אִתְעֲדוּן מִתַּמָּן. לְבָתַר נָפַק חַד נְהוֹרָא נָהִיר לְאַרְבַּע סִטְרִין. הַאי נְהוֹרָא אַפִּיק תְּלַת אָחֳרָנִין דְּאִנּוּן תְּלַת בָּתֵּי דִינָא דְּדָיְינִין דִּינִין אָחֳרָנִין בְּמִלִּין דְּעָלְמָא בְּעוּתְרָא בְּמִסְכְּנוּ בְּמַרְעִין בִּשְׁלִימוּ בְּכָל אִנּוּן שְׁאָר מִלִּין דְּעָלְמָא אִתְדָּן בְּהוּ. חַד הֵיכָלָא לְאִנּוּן ע' קַדְמָאֵי לְגוֹ. תְּלָתָא לְאִלֵּין תְּלָתָא אָחֳרָנִין.","סָלְקָא הַאי רוּחָא וְכָלִיל כָּל אִנּוּן דִּלְתַתָּא. וְאַפִּיק חַד חֵיוָותָא קַדִּישָׁא מִתְלַהֲטָא וְעַיְילִין לָהּ כְּעֵינִי אֵינָשָׁא לְאַשְׁגָּחָא בְּאֶלֶף אַלְפִין וְרִבּוֹא רִבְוָון חַיָילִין מָארֵיהוֹן דְּדִינָא. כֻּלְהוּ נָטְלִין פִּתְקִין וּפָתְחִין וְסָגְרִין בְּעָלְמָא וְאַשְׁלִימוּ דִינָא.","תְּחוֹת הַאי חֵיוָתָא ד' שְׂרָפִים מְלַהֲטָן כֻּלְהוּ כְּחֵזוּר וְשׁוֹשַׁן וּשְׁבִיבֵי דְּאֶשָׁא. סָלְקִין ע\"ב גַּלְגַּלִּין לְכָל חַד מְלַהֲטָן בְּאֶשָׁא. כַּד נָטְלִין אִתְעֲבִיד נָהָר חָד דִּי נוּרָא. אֶלֶף אַלְפִין מְשַׁמְשִׁין לְהַהוּא נוּרָא, מִתַּמָּן נָפְקֵי כַּמָּה חַיָּילִין. כַּד גַּלְגַּלִּין נָטְלִין. כַּמָּה אִנּוּן רִבּוֹא רִבְוָון דִּיְקוּמוּן מִנַּיְיהוּ בְּגוֹ הַהוּא נוּרָא. תְּחוֹת הֵיכָלָא תִּנְיָינָא נָפְקֵי חַיָּילִין דִּמְזַמְּרִין וְאַתְיָין לְקָרְבָא הָכָא וְאִתּוֹקְדוּן כֻּלְהוּ.","כָּל אִנּוּן (סט א) מְמַנָּן דְּעָלְמָא דְּאִתְמַנּוּן לְשַׁלְטָאָה מֵהָכָא נָפִיק דִּינְהוֹן לְשַׁלְטָאָה מִגּוֹ הַהוּא רוּחָא דְּאִתְרְשִׁים בִּתְלַת אַתְוָון. וּמֵהָכָא מַעְבְּרִין קִיּוּמַיְיהוּ מֵעָלְמָא וְאִתְדְּנוּ בְּהַאי נוּרָא דְּנָגִיד וְנָפִיק. דְּלָּא אִתְמָסַר בְּהַאי הֵיכָלָא. בְּגִין דְּאִתְרְשִׁימוּ בִּתְלַת (ד\"א תלת) אַתְוָון הָכָא הַאי רוּחָא אִתְכְּלִיל בְּהוּ. הַהִיא חֵיוָותָא אַפִּיק חַיָּילִין וּמַשִּׁרְיָין דְּלֵית לְהוֹן חוּשְׁבְּנָא.","כָּל דִּינִין דְּעָלְמָא מֵהַאי הֵיכָלָא נָפְקֵי הֵן לְטַב הֵן לְבִישׁ. בַּר (קפא ע\"א) תְּלַת בָּנֵ\"י חַיֵּ\"י וּמְזוֹנֵ\"י. דְּלָא אִתְיְיהַב רְשׁוּ בְּאֲתַר דָּא. דְּהָא בְּהַהוּא נָהָר עִלָּאָה דְּכָל נְהוֹרִין נַגְדִין מִנֵּיהּ קָיְימָא מִלָּה. בְּאֶמְצָעִיתָא דְּהֵיכָלָא דָא הוּא אֲתַר מְתַקְּנָא לָקֳבֵל רוּחָא דִּלְעֵילָא בְּגוֹ רוּחָא דָּא וְדָא סָלְקָא בְּהוּ."],[[0,"ות\"ח אלמלא כל אינון גוונין דעינא דאתחזיין כד אסתים עינא ואתגלגלא בגלגלא:","ובוא וראה אלמלא כל אלו הצבעים שבעין שנראים בעת שסוגרים העין ומתגלגלת בגלגול \u0003לא אתחזיין אינון גוונין דזהרן,\u0004 לא היו נראים אלו הצבעים המאירים. \u0003ואלמלא אינון גוונין לא אתדבק ההוא דסתים דשלטא עלייהו\u0004 ואלמלא אלו הצבעים המאירים, לא היה מתדבק בהראיה, אותו הסתום שבעין השולט על כולם \u0003אשתכח דכלא תליא דא בדא\u0004 ואתקשר דא בדא, נמצא שכולם תלוים זה בזה ונקשרים זה בזה."],[1,"כד אתכליל כלא כחדא בהיכלא תליתאה, ורעותא דצלותא סלקא ואתעטרא בהיכלא רביעאה","כאשר נכללו כולם כאחד בהיכל השלישי, והרצון שבהתפלה עולה להתעטר בהיכל הרביעי, \u0003כדין כלא חד ורעותא חדא וקישורא חדא,\u0004 אז נעשו כולם אחד, רצון אחד, וקשר אחד. \u0003הכא השתחואה לאתרצאה במאריה,\u0004 כאן הוא בחינת השתחואה להתרצות לרבונו. וענין השתחואה יתבאר בע\"ה להלן."],[2,"היכלא רביעאה: היכלא דא איהו משניא מכלהו, ד' היכלין לדא, דא לגו מן דא וכלהו חד היכלא:","היכל הרביעי, היכל זה הוא משונה מכל ההיכלות, כי ארבעה היכלות בו זה לפנים מזה, וכולם היכל אחד, ומבאר לפנינו שאלו ד' היכלות הם ד' בתי דינים, האחד הפנימי הוא לדיני נפשות, וג' ב\"ד הם שמסביב לו הם לשאר דינים. ומה שהיכל זה הוא גבורה ולא ת\"ת, יתבאר להלן."],[2,"הכא איהו רוחא דאקרי זכות באתר דא מתהפך זכות דכל בני עלמא, רוחא דא נטיל כלא:","כאן הוא הרוח הנקרא זכות, כי במקום הזה מתהפכים חובות של כל בני העולם לזכות, רוח הזה לוקח הכל. כלומר מי שזכה בו זוכה להכריע את עצמו ואת כל העולם כולו לכף זכות."],[3,"מניה נפקו ע' בהורין כלהו מנצצן וכלהו בעגולא דלא מתפשטי כאלין אחרנין:","מן הרוח הזה, זכות, יוצאים ע' אורות, כולם מתנוצצים בבת אחת, וכולם מאירים בבחינת עגולים, כי אינם מתפשטים להאיר ממעלה למטה כמו אורות האחרים. \u0003מתדבקין דא בדא, ונהירין דא בדא, אחידן דא בדא\u0004 האורות מתדבקין זה בזה, ומאירים זה בזה, ונאחזים זה בזה. \u0003מתדבקן\u0004 יורה שיש ביניהם השואת הצורה, כי דבקות הרוחני אינה אלא השואת הצורה. \u0003ונהורין דא בדא,\u0004 יורה אשר האורות מתערבים זה בזה להאיר ביחד כאחד. \u0003ואחידן דא בדא,\u0004 יורה שצריכים זה לזה, שלא יוכלו להאיר זה בלי זה, ואם היה חסר אחד מהם לא היו יכלו להאיר. \u0003כל זכיין דעלמא קמי אלין נהורין קיימין\u0004 כל זכויות העולם נמצאות לפני אורות הללו. כלומר לאורם רואים איך כל חובות העולם מתהפכים לכף זכות."],[3,"","ביאור הדברים כי אמרו חז\"ל לא היה שמחה לפניו כיום שנבראו בו שמים וארץ, משמע שכל בריות העולם הם בתכלית השלמות במדה כזו שלא היה שמחה לפניו וכו'. אמנם אי אפשר לאדם לקחת חלק בשמחתו ית' הגדולה הזו, אלא לאחר שעשה תשובה שלימה מאהבה, אבל מטרם זה, לא ישמח כלל בעצמו ובבריות העולם, אלא להיפך, שמרגיש לפניו עולם מלא צער ומכאובים, עד שאומר ארץ ניתנה ביד רשע, הן מכאובים גופנים, והן מכאובים נפשיים, שהם העברות שעושה. וכל זה הגיע לו מפני שהולך כנגד הטבע של הבריאה, כי לא נברא העולם אלא בסוד השפעה, דהיינו לעסוק בתורה ומעשים טובים בכדי להשפיע נחת רוח ליוצרו ולא להנאת עצמו, כמ\"ש כל פעל ה' למענהו, דהיינו בכדי שהבריות ישפיעו לו נ\"ר. אבל בתחילה עייר פרא אדם יולד, דהיינו שכל ענינו הוא להנאת עצמו ואין בו הרצון להשפיע כלל, והוא טוען, כל פעל ה' למעני ולהנאתי, שהרי רוצה לבלוע העולם ומלואה לטובתו ולתועלתו."],[3,"","ולפיכך הטביע הבורא ית' יסורים קשים ומרים, בענין הקבלה לעצמו הטבוע באדם מעת לידתו, הן מכאובים גופניים והן מכאובים נפשים, באופן שאם יעסוק בתורה ומצות אפילו להנאת עצמו, מ\"מ על ידי המאור שבה ירגיש הפחיתות והשחיתות הנוראה שיש בטבע הקבלה לעצמו, ואז יתן אל לבו לפרוש את עצמו מטבע הקבלה הזו ויתמסר לגמרי לעבוד רק להשפיע נ\"ר ליוצרו, בשיעור הכתוב כל פעל ה' למענהו. ואז יפקח ה' את עיניו ויראה לפניו עולם מלא מתכלית השלימות שאין בו חסרון כל שהוא. ואז לוקח חלק בשמחתו ית' שבעת בריאת העולם. וז\"ש חז\"ל זכה, הכריע את עצמו ואת כל העולם כולו לכף זכות. כי בכל מקום שנותן עיניו הוא רואה רק טוב ורק שלימות, ואינו רואה במעשה הקב\"ה שום חובות כלל אלא הכל זכיות."],[3,"","ובענין היסורים הגשמיים והרוחניים שסבל מטרם שעשה תשובה, יש בהם ב' דרכים: א) הוא בחינת כל מה דעביד רחמנא לטב עביד, כי הוא רואה בעיניו, אשר לולא המכאובים הנוראים ההם, שסבל מכח שהיה משוקע בטבע הקבלה לעצמו, לא היה זוכה לתשובה מעולם, וא\"כ הוא מברך על הרעה כשם שמברך על הטובה, כי לולא הרעה לא היה זוכה להטובה. ונמצא שכל מה דעביד רחמנא לטב עביד, כלומר, גורמים להטוב. ב) היא בחינת גם זו לטובה, דהיינו לא לבד שהרעות נעשו גורמים להטובה, אלא שהרעות עצמם נהפכו ונעשו טובות, והיינו ע\"י אורות גדולים מאד, שהבורא ית' מאיר בכל אלו הרעות, עד שנהפכו ונעשו לטובות, הן היסורין הגופניים, והן היסורים הנפשיים שהם העברות, באופן שהחובות נהפכו וקבלו צורות של זכיות. ואלו האורות המהפכים את החובות לזכיות, הן הע' נהורין שבהיכל הזה שלפנינו. ובשבילם נקרא היכל זה היכל הזכות."],[3,"מכלהו נפקי תרין נהורין שקולין כחדא דקיימו קמייהו תדירא,","מכללות כל ע' האורות, יוצאים ב' אורות שהם שקולים כאחד, העומדים תמיד לפניהם. פירוש, כי נתבאר, שאלו ע' האורות הם מהפכים חובות בני אדם לזכיות כנ\"ל בדיבור הסמוך, והנה אז נבחנים החובות והזכיות לב' אורות שקולים זה לזה, כלומר שמעלת החובות חשובה כמו מעלת הזכיות, ואין זו חשובה מזו משהו. והם עומדים ומאירים לפני ע' האורות תמיד, ומעידים עדות לפניהם כמ\"ש לפנינו בסמוך."],[4,"לקבל אלין, אינון ע' רברבן ממנן לבר דסחרין בל ארבע היכלין,","לעומת אלו ע' האורות, יש ע' שרים ממונים, שמהם כל הדינים שבעולם, העומדים בחוץ, ומסבבים כל ארב ההיכלות הללו מבחוץ, \u0003שבעין נהורין אלין ותרין נהורין דקיימא קמייהו כלהו פנימאין גו לגו,\u0004 אבל ע' האורות וב' האורות העומדים לפניהם הם פנימיים לפני ולפנים, (כמ\"ש להלן באות ק\"ו) \u0003ורזא דא דכתיב בטנך ערמת חטים סוגה בשושנים,\u0004 בטנך, היינו פנימיות, כמו הבני מעים שהם בפנימיות הגוף. חטים, רומז לחטאים, דהיינו החטאים שנעשו לזכיות בסוד ע\"ב נהורין הנ\"ל, שהם לפני ולפנים של ד' ההיכלות כנ\"ל, וע\"כ נאמר עליהם בטנך ערמת חטים. אמנם סוגה מבחוץ בשושנים, הרומזים לדינים, שהם הע' שרים הממונים, שהם פועלים כל הדינים שבעולם. ומה שאומר שהע' שרים הם הלעומת של ע' נהורין. הענין הוא, כי הגם שכל החטאים והעונשים באים מע' שרים, עם כל זה אינם ח\"ו ברשות עצמם אלא שהם משמשים להע' נהורין כי תפקידם להכשיר התחתונים שיהיו ראוים לקבל הגילוי הגדול של ע' האורות. ולפיכך נבחנים, שע' שרים הממונים מסבבים ההיכלות והע' נהורין מבחוץ."],[5,"לקמי נהררין אלין עאלין כל זכו וכל עובדין דעלמא לאתדנא:","לפני ע' האורות האלו באים כל הזכיות וכל מעשי בני העולם למשפט. כלומר שע' האורות הללו, ה\"ס ב\"ד של מעלה, הדנים כל בני העולם. \u0003תרין נהורין אלין אינון סהדי סהדותא,\u0004 ב' האורות העומדים לפניהם, הם המעידים עדות של מעשי בני העולם. \u0003בגין דאית שבעה עיני ה' דמשטטי בכל ארעא,\u0004 משום שיש שבעה עיני ה' המשוטטות בכל הארץ. עינים פירושו השגחה. ויש שבעה מדות בהשגחתו ית' שהם חג\"ת נהי\"מ, והם המכונים שבעה עיני ה', כלומר, ז' מיני השגחה המכשירים את בני העולם לקבל העונג והנועם העליון. \u0003כל מה דאתעביד בעלמא אתרשים בההוא עובדא ממש וההוא זכותא ממש וקיימי בקיומייהו,\u0004 כל מה שנעשה בעולם הן טוב והן רע, נרשם צורתו באותו המעשה ממש ובאותו הזכות ממש ומתקיימים ועומדים לנצח, כלומר, שאין שום דבר נאבד מהעולם הן ממעשים הרעים והן ממעשים הטובים, אלא כל מעשה נרשמת בצורתה בסוד שבעה עיני ה' וגו' וניתן לה בזה קיום נצחי. \u0003ואלין תרין נהורין חמאן בהו ומסתכלן וסהדי קמי אלין ע' נהורין,\u0004 ושני אורות האלו, רואים ומסתכלים בכל מעשה, ומעידים עדות לפני ע' האורות, שהם הב\"ד של מעלה, ואחר שהע' נהורין שומעים עדותם, \u0003אלין ע' גזרי גזרין ודיינין דינין הן לטב והן לביש\u0004 אלו ע' האורות גוזרים גזרות ודנים דינים הן לטובה והן לרעה. דהיינו ע\"פ עדותם של ב' האורות. פירוש כי בעת השלמות נמצאים ב' האורות הללו שה\"ס אור החובות ואור הזכויות, שקולים זה כזה בסוד שזדונות נעשו לו כזכיות כנ\"ל (דף ס\"ד ד\"ה ביאור) ואז ע' האורות שה\"ס ע' סנהדרין של מעלה, דנים לפי עדותם הטובה הזו את כל מעשה לטובה. אבל אם ב' האורות אינם שקולים, אלא אור הזכיות גדול מאור החובות, הנה במדה זו יש חסרון ניכר במעשים הרעים, אשר האדם שעשה אותם, צריך לשוב בתשובה מאהבה עליהם, וזה נבחן שב' האורות מעידים עדות רעה על המעשים שעשה האדם, ואז ע' האורות דנים דינים לרעה, עד שישיב האדם תשובה מאהבה עליהם, ויהפכו לגמרי לזכיות, ויהיו ב' האורות שקולים זה כזה. הרי שהע' נהורין דנים את האדם לפי עדותם של ב' האורות, כלומר אם שקולים או אינם שקולים, ולפי מדת החסרון עד שיהיו שקולים. \u0003והכא איהו אתר דזכותא,\u0004 וכאן בהיכל זה הוא מקום הזכות. כלומר שמה שאומר \u0003ודיינין דינין הן לטב והן לביש,\u0004 אינו מתגלה כאן אלא בהשפע המושפע מע' נהורין המגיע למטה, שם ניכר הרע, אבל כאן הוא הזכות בלבד."],[6,"רוחא דא ביה אתרשימו אתוון תלת, דאנון יה\"ו:","הרוח שבהיכל זה, הנקרא זכות, שממנו ע' נהורין הנ\"ל, נרשמו בו ג' אותיות יה\"ו. פירוש, הע\"ס הם י\"ה ו\"ה: י\"ה הם חו\"ב, ו' הוא ת\"ת הכולל חג\"ת נה\"י, ה\"ת הוא מלכות. ואומר אשר הרוח הזה, שממנו ע' נהורין הנ\"ל, הוא בחינת יה\"ו, דהיינו רק ט' ספירות הראשונות, שה\"ס דכר, ואינו כולל את ה\"ת שה\"ס נוקבא. \u0003דכד אלין אתוון מתדבקן בהאי אתר, באתדבקותא דדכורא ונוקבא, כדין אתרשימו ביה, ולא אתעדון מתמן,\u0004 כאשר האותיות יה\"ו, מתדבקים באותו מקום, דהיינו בהמלכות המכונה מקום, שהיא ה' תתאה, אז נרשמים האותיות יה\"ו בהרוח, ואינם מסתלקים משם. פירוש כי כל מדרגת יוצאת ע\"י זווג דהכאה דאור העליון שה\"ס ט\"ס ראשונות ודכר, על המסך שבמלכות שה\"ס נוקבא, שאז עולה או\"ח מהמלכות ומלביש את אור העליון, שה\"ס ט\"ס ראשונות, ממטה למעלה, וע\"י הלבשה זו נקבעו ונקשרו ט\"ס ראשונות בהמדרגה, וז\"ש \u0003דכד אלין אתוון יה\"ו,\u0004 שה\"ס אור העליון ודכר, \u0003מתדבקן בהאי אתר\u0004 דהיינו בה' תתאה, בהמלכות, שהיא נוקבא, שאז נאצל הרוח הכולל ע' נהורין הנ\"ל \u0003כדין אתרשימו ביה,\u0004 אז נרשמו בהרוח ט\"ס הראשונות שהוא \u0003יה\"ו, ולא אתעדון מתמן\u0004 כי האו\"ח מלביש אותם והם נקשרים בו בכח הלבשה הזאת."],[6,"לבתר נפיק חד נהורא נהיר לארבע סטרין, האי נהורא אפיק תלת אחרנין:","לאחר כך יוצא אור אחד המאיר לד' צדדים, אור זה מוציא ג' אורות אחרים. פירוש, כי אלו הע\"ס הנ\"ל בדבור הסמוך שיצאו ממטה למעלה, הם נבחנים לע\"ס דראש, וה\"ס הרוח הכולל את ע' נהורין וב' סהדי. ונודע שאחר שנעשה הזווג דהכאה ומוציא הע\"ס דראש, מתפשטת אח\"כ המלכות דראש ממעלה למטה ומוציא ב' בחינות שבגוף, שהם חג\"ת עד החזה, שה\"ס ג\"ר דגוף, ונה\"י שמחזה ולמטה עד סיום רגלין. ונודע שחג\"ת שמחזה ולמעלה שלמים בד' הבחינות חו\"ב תו\"מ, שה\"ס ארבע חיות אריה שור נשר אדם. אבל נה\"י, שמחזה ולמטה, אין שם אלא ג' בחינות חו\"ב ות\"ת וחסר שם פני אדם שה\"ס מלכות (כמ\"ש לעיל דף מ\"ו בד\"ה ביאור. ובבראשית א' דף פ\"ו ד\"ה וזה, ע\"ש בכל ההמשך)."],[6,"","וז\"ש \u0003לבתר,\u0004 דהיינו אחר שיצאו יה\"ו דראש בזווג דהכאה, \u0003נפק חד נהורא נהיר לארבע סטרין,\u0004 שאור המלכות דראש נתפשט והאיר ממעלה למטה את החג\"ת שמחזה ולמעלה, ששם יש \u0003ד' סטרין\u0004 חו\"ב תו\"מ, \u0003האי נהורא אפיק תלת אחרנין,\u0004 ומהחג\"ת יצאו ונתפשטו נה\"י שמחזה ולמטה שהם רק ג' \u0003סטרין\u0004 חו\"ב ות\"ת, אבל פני אדם חסרים שם כנ\"ל."],[6,"דאינון תלת בתי דינא, דדיינין דינין אחרנין במלין דעלמא, בעותרא במסכנו במרעין בשלימו","וכו', שאלו ג' נהורין חו\"ב ות\"ת, הם ג' בתי דין הדנים דינים אחרים בעניני העולם, שאינם דיני נפשות, דהיינו בעשירות בעניות במחלות בבריאות השלמה ובשאר ענינים שהעולם נידון בהם. פירוש שהרוח הכולל ע' נהורין וב' סהדי, הוא בחינת יה\"ו שבראש המאירים ממטה למעלה, ואלו ע' נהורין הנמשכים ממנו, ה\"ס ע' סנהדרין הדנים דיני נפשות. והאורות שמחזה ולמטה הנמשכים מה' תתאה שבראש, שהם ג' סטרין, ה\"ס ג' בתי דין הדנים דינים אחרים שאינם דיני נפשות. וה\"ס במותב תלתא כחדא הוינא, (המובא לעיל בבראשית א' דף קנ\"ד אות קע\"ב) אלא שכל אחד מג' סטרין כלול מכל הג', וע\"כ הם ג' בתי דין."],[6,"","ומה שאינו חושב בתי דין בד' הסטרין שמחזה ולמעלה, היינו משום ששם החסדים מכוסים ואין בהם גילוי של הארת החכמה, ואין שום דינים יכולים להאחז שם, כי אין הדינים שורים אלא במקום שיש הארת החכמה. והטעם הוא, כי הצמצום לא היה כלל על אור החסדים כמ\"ש במקומו."],[6,"חד היכלא לאנון ע' קדמאי לגו, תלתא לאנון תלתא אחרנין:","היכל אחד הוא בשביל ע' נהורין הראשונים, שהוא בפנימיות ההיכלות, וג' היכלות החיצונים לו, הם בשביל ג' בתי דינים האחרים. כלומר כי היכל זה כלול מד' היכלות זה לפנים מזה (כנ\"ל באות ק\"ב) והע' נהורין שה\"ס ע' סנהדרין וב' סהדי, הם בהיכל הפנימי מכולם, וג' בתי דין האחרים הם בג' היכלות המסבבים להיכל הפנימי."],[7,"סלקא האי רוחא וכליל כל אינון דלתתא, ואפיק חד חיוותא קדישא מתלהטא:","עולה רוח הזה וכולל בתוכו כל אלו נהורין שלמטה, דהיינו ד' נהורין שמחזה ולמעלה והג' נהורין שמחזה ולמטה, ומוציא חיה אחת קדושה מתלהטת. \u0003ועיינין לה כעיני אינשא לאשגחא באלף אלפין ורבוא רבוון חיילין מאריהון דדינא,\u0004 ויש עינים להחיה כעיני אנוש, כדי להשגיח באלף אלפים ורבוא רבבות חיילות בעלי הדין. \u0003כלהו נטלין פתקין, ופתחין וסגרין בעלמא, ואשלימו דינא,\u0004 כל אלו בעלי הדין לוקחי פסקי דין מהב\"ד, ופותחים או סוגרים צנורות השפע אל העולם ומשלימים הדין, דהיינו שמוציאים אותו לפועל."],[7,"","פירוש, כי הרוח שה\"ס ע' נהורין היא בחינת ג\"ר וראש שה\"ס יה\"ו (כנ\"ל בדיבור הסמוך) והחיה הזאת נמשך בעיקר מן הרוח וע' נהורין שבו, אלא כדי להאצילה בראש וגוף, הוצרך גם הרוח להכלל מבחינת גוף, דהיינו מהד' נהורין וג' נהורין, שהם גוף כנ\"ל. ולפיכך יכולה החיה להשלים ולהוציא לפועל את הדין שהוציאו הע' נהורין להיותם שורשה. וז\"ש \u0003ועיינין לה כעיני אינשא,\u0004 להורות שהעינים של החיה נמשכות מבחינת הג\"ר, ששם ע' נהורין, ושם פני אדם. ועינים פירושו השגחה. וז\"ש \u0003לאשגחא באלף אלפין ורבוא רבוון\u0004 וכו'. כי להיותם מבחינת ראש הם נמשכים מהבחינה שכנגדם באצילות שהוא עתיק, שהוא הראש דאצילות, ונודע שספירות דעתיק הם במספר מאה אלף והע\"ס שלו הם אלף אלפים, שזסו\"ה הנאמר בעתיק (דניאל ז') אלף אלפין ישמשוניה. ומלבד זה יש עוד בעתיק זווג נעלם מסוד המלכות הגנוזה ברדל\"א, ומבחינה זו כל ספירה שבו רבוא אלפין, והע\"ס רבוא רבבן, שזסו\"ה ורבוא רבבן קדמוהי יקומין, (דניאל ז') וכיון שאלו הם המוציאים לפועל את הדינים הנגזרים בע' נהורין שהם בחינת ראש, המקבלים מעתיק, שהוא הבחינה שכנגדם, ע\"כ יש גם בהם אותם ב' המספרים הנוהגים בעתיק, \u0003אלף אלפין,\u0004 מזווג הנגלה, \u0003ורבוא רבוון\u0004 מזווג הנעלם."],[8,"תחות האי חיוותא ד' שרפים, מלהטן כלהו כחזור ושושן ושביבי דאשא סלקין:","תחת חיה הזו יש ד' שרפים שכולם לוהטים ככפתור ופרח, וניצוצי אש עולים. פירוש. ד' השרפים הם ד' בחינות חו\"ב תו\"מ של החיה המאירים לד' סטרין. וענין ההתלהטות ככפתור ופרח ונצוצי אש, ה\"ס זיעת החיות שהן מזיעות בעת נסיעתן לד' הסטרין, (כמ\"ש לעיל דף נ\"ט ד\"ה וז\"ס הזיעה ע\"ש) כי בכל סטרא שנוסעים, הם מכוונים פניהם לקו האמצעי בהקפדה מרובה, שלא לנטות לא לימין ולא לשמאל, וכיון שאינם יכולים לצמצם את עצמם כל כך לאמצעיתא כפי שרוצים, נמצאים עושים פעם נטיה יתרה לצד שמאל וממשיכים בזה תכף ניצוץ אש שורף, ופעם עושים נטיה יתירה לצד ימין וממשיכים בזה אור חסדים, כי המדייק להחזיק עצמו באמצע, דרכו לנענע עצמו פעם לימין ופעם לשמאל עד לקבוע לו האמצע בדיוק. והנטיה היתרה לצד הימין מכונה בשם \u0003כפתור,\u0004 כי הבית קבול של האור מכונה \u0003כף,\u0004 וקומת אור הנמשך מכונה \u0003תור,\u0004 מלשון תורי זהב וגו'. והנטיה היתרה לצד שמאל מכונה בשם \u0003פרח,\u0004 ובשם \u0003נצוצי אש,\u0004 פרח נקרא על שם פריחת אור החסדים כי אור החכמה הנמשך מקו שמאל נמשך בלי אור החסדים, ונבחן שאור החסדים פרח משם. וכן מכונה ניצוצי אש, כי מפאת היות האור בלי חסדים נמצא שורף את התחתונים, כי הנמשכים מבחינת ז\"ת שעיקרם הוא אור חסדים נמצאים מתבטלים על ידי אור בלי חסדים, אבל אלו ד' השרפים להיותם מבחינת ג\"ר אינם נשרפים מחמת חסרון חסדים, כי הג\"ר יכולים לקבל אור חכמה בלי חסדים, ועל שם כך הם נקראים שרפים, להורות שהארתם הנמשך לתחתונים שורפת אותם."],[8,"ע\"ב גלגלין לכל חד מלהטן באשא:","ע\"ב גלגלים לוהטים באש יש לכל אחד, מד' השרפים שהם ד' פעמים ע\"ב שהוא בגי' פר\"ח, שזה יורה שאור החסדים פרח משם, כי אלו הגלגלים התקבצו ועלו אליהם מניצוצי אש הנ\"ל, וע\"כ הם לוהטים."],[8,"כד נטלין אתעביד נהר חד די נורא:","כאשר נוסעים נעשה על ידיהם נהר אחד של אש. כי ענין הנטיה הנ\"ל לצד שמאל נוהגת תמיד בעת הנסיעה, כי בכל פעם שמתאמצים ביותר לכוין פניהם לקו האמצעי, הם מזיעים בהכרח, דהיינו שנוטים לכאן ולכאן, לימין ולשמאל, בכדי לקבוע ביתר דיוק את האמצעי, ובכל נטיה לצד שמאל יוצאים ונמשכים ניצוצי אש, עד שמתקבצים ונעשים לנהר של אש, הנקרא נהר דינור. \u0003אלף אלפין משמשין לההוא נורא,\u0004 אלף אלפים מלאכים משמשים לאש ההוא. פירוש כי המוחין שהשרפים מקבלים בעת נסיעתם נמשכים מעתיק דאצילות שמצד זווג הנגלה הוא במספר אלף אלפים, ומצד זווג הנעלם הוא במספר רבוא רבבן, (כנ\"ל דף ס\"ח ד\"ה סלקא) וע\"כ נבחן שהנהר של אש נעשה ע\"י הארת אלף אלפין הנמשך מעתיק, \u0003מתמן נפקי כמה חיילין,\u0004 מאלו אלף אלפין יוצאים ונולדים כמה צבאות, \u0003כד גלגלין נטלין כמה אינון רבוא רבוון דיקומון מנייהו בגו ההוא נורא,\u0004 כשהגלגלים נוסעים, נולדים ועומדים מהם כמה רבוא רבבות בתוך האש, שהם נמשכים מזווג הנעלם של עתיק שהוא בסוד רבוא רבבן. באופן שהמשמשים העושים את נהר דינור הם בסו\"ה אלף אלפין ישמשוניה, והנולדים ויוצאים בתוך הנהר דינור גופו, הם בסו\"ה רבוא רבבן קדמוהי יקומון."],[8,"תחות היכלא תנינא נפקי חיילין דמזמרין ואתיין לקרבא הכא ואתוקדון כלהו:","תחת היכל השני יוצאים מלאכים המזמרים ובאים להתקרב כאן והם נשרפים כולם. והוא מטעם היותם מבחינת ו\"ק אשר עיקרם הוא אור החסדים, וע\"כ נעשה להם אור החכמה בלי חסדים שבכאן, לאש שורף, ונשרפים ונאבדים מחמתו."],[9,"כל אינון ממנן דעלמא דאתמנון לשלטאה, מהכא נפיק דינהון לשלטאה:","כל אלו הממונים שנתמנו לשלוט בעולם מכאן יוצא התמנותם לשלוט, \u0003מגו ההוא רוחא דאתרשים בתלת אתוון,\u0004 התמנותם יוצא מתוך הרוח זכות שבכאן, שנרשם בג' אותיות יה\"ו (כנ\"ל באות ק\"ו) \u0003ומהכא מעברין קיומייהו מעלמא, ואתדנו בהאי נורא דנגיד ונפיק.\u0004 ומכאן מעבירים אותם מהעולם ונדונים באש הזה היוצא ונמשך בנהר דינור. \u0003כלא אתמסר בהאי היכלא בגין דאתרשימו בתלת אתוון הכא, האי רוחא אתכליל בהו,\u0004 הכל נמסר בהיכל הזה משום שנרשם בג' אותיות יה\"ו שהרוח שבכאן נכלל בהם. \u0003ההוא חיוותא אפיק חיילין ומשריין דלית להון חושבנא,\u0004 חיה זו מוציאה צבאות ומחנות מלאכים שאין להם מספר."],[9,"","פירוש כי שליטת הממונים דקדושה בעולם הוא להכניע את הס\"א, ואינם יכולים לשלוט עליהם ולהכניעם, מפני שזה לעומת זה עשה אלקים, אלא בשעה שמקבלים מוחין דג\"ר מהרוח זכות שבכאן, אז יכולים להכניע הס\"א ולשלוט בעולם, ואומר \u0003ומהכא מעברין קיומייהו מעלמא,\u0004 כי כמו שהמוחין הגדולים מקובלים כאן, כן אם אינם נזהרים, לקבלם בסוד ג' אתוון יה\"ו, שהרוח שבכאן נרשם בהם, שסודם שה\u0003ו'\u0004 שהוא ת\"ת, קו אמצעי, מכריע על י\"ה שהם חו\"ב, ימין ושמאל, אלא נוטים לקו שמאל, מעבירים אותם תכף מהעולם \u0003ואתדנו בהאי נורא דנגיד ונפיק,\u0004 כמ\"ש לעיל. באופן \u0003דכלא אתמסר בהאי היכלא,\u0004 הן המוחין הגדולים והן להאבד מהעולם לגמרי."],[10,"כל דינין דעלמא מהאי היכלא נפקי הן לטב הן לביש בר תלת, בני חיי ומזוני,","כל הדינים שבעולם יוצאים מהיכל הזה, הן לטובה והן לרעה, חוץ מג' הללו, בנים חיים ומזונות, \u0003דלא אתייהב רשו באתר דא, דהא בההוא נהר עלאה, דכל נהורין נגדין מניה, קיימא מלה,\u0004 שלא ניתן רשות לדון אותם במקום הזה, אלא שהם תלוים באותו נהר העליון, דהיינו המכונה דיקנא דא\"א או מזל העליון, שכל האורות, דבני חיי ומזוני, נמשכים ממנו, ורק בו תלוי הדבר, והטעם הוא, כי בהיכל הזכות עיקר השליטה הוא לבחינת אהבה, שהרי אין הזדונות נהפכים לזכיות אלא ע\"י אהבה. כמ\"ש חז\"ל שע\"י תשובה מאהבה זדונות נעשים לו כזכיות (יומא פ\"ו:) אמנם מזל העליון שה\"ס שערות דיקנא דא\"א עיקר השליטה היא שם לבחינת יראה, כי ע\"כ נקראת שערות מלשון סערות. ובני חיי ומזוני אינם נמשכים אלא בכח היראה, וע\"כ לא יוכלו לבא מהיכל הזכות אלא רק משערות דיקנא דא\"א ששם מדת היראה."],[10,"","ואין להקשות הרי אומר לעיל שע' נהורין ה\"ס סנהדרי גדולה הדנים דיני נפשות וא\"כ גם החיים נידון בהיכל הזכות. אמנם כבר עמד בזה הזהר עצמו (בפקודי רנ\"ג ע\"א) ותירץ שם \u0003כד אתדן הכא לחיים כדין נגדין חיים מלעילא ויהבי ליה,\u0004 שאחר שנידון בהיכל הזכות לחיים, נמשך אז החיים ממזלא דא\"א וניתן לו חיים ממנו. וכן אומר להלן באות קי\"ד. \u0003באמצעיתא דהיכלא דא, הוא אתר מתקנא, לקבל רוחא דלעילא בגו רוחא דא, ודא סלקא בהו:\u0004 באמצעו של היכל הזה, יש מקום מתוקן, שיתקבל רוח העליון, שבהיכל החמישי, תוך הרוח שבכאן, ומקום זה עולה בהם, כלומר שמקום זה, שה\"ס העמוד העומד באמצעו של כל היכל והיכל, נכלל בב' הרוחין הללו, וע\"כ הוא מעלה את הרוח שבכאן אל רוח העליון שבהיכל החמישי כמ\"ש באורך לעיל דף מ\"ח ד\"ה באמצעיתא ע\"ש."]],[[0,"","וּבֹא וּרְאֵה, אִלְמָלֵא כָּל אוֹתָם גְּוָנִים שֶׁל הָעַיִן שֶׁנִּרְאִים, כְּשֶׁנִּסְתֶּמֶת הָעַיִן וּמִתְגַּלְגֶּלֶת בְּגַלְגַּל, לֹא נִרְאִים אוֹתָם הַגְּוָנִים שֶׁזּוֹהֲרִים, וְאִלְמָלֵא אוֹתָם גְּוָנִים לֹא נִדְבָּק אוֹתוֹ הַנִּסְתָּר שֶׁשּׁוֹלֵט עֲלֵיהֶם. נִמְצָא שֶׁהַכֹּל תָּלוּי זֶה בָּזֶה וְנִקְשָׁר זֶה בָּזֶה"],[1,"","כְּשֶׁנִּכְלָל הַכֹּל כְּאֶחָד בַּהֵיכָל הַשְּׁלִישִׁי. וּרְצוֹן הַתְּפִלָּה עוֹלֶה לְהִתְעַטֵּר בַּהֵיכָל הָרְבִיעִי. וְאָז הַכֹּל אֶחָד וְרָצוֹן אֶחָד וְקֶשֶׁר אֶחָד. כָּאן הִשְׁתַּחֲוָאָה לְהִתְרַצּוֹת לְרִבּוֹנוֹ."],[2,"","הֵיכָל הָרְבִיעִי. הֵיכָל זֶה הוּא מְשֻׁנֶּה מִכֻּלָּם. אַרְבָּעָה הֵיכָלוֹת לָזֶה, זֶה לִפְנִים מִזֶּה, וְכֻלָּם הֵיכָל אֶחָד. כָּאן הוּא רוּחַ שֶׁנִּקְרָא זְכוּת. בְּמָקוֹם זֶה מִתְהַפֵּךְ הַזְּכוּת שֶׁל כָּל הָעוֹלָם. רוּחַ זוֹ נוֹשֵׂאת הַכֹּל."],[3,"","מִמֶּנָּה יוֹצְאִים שִׁבְעִים אוֹרוֹת כֻּלָּם נוֹצְצִים. וְכֻלָּם בְּעִגּוּל שֶׁלֹּא מִתְפַּשְּׁטִים כְּמוֹ הָאֲחֵרִים הַלָּלוּ. מִתְדַּבְּקִים זֶה בָּזֶה וּמְאִירִים זֶה בָּזֶה, אֲחוּזִים זֶה בָּזֶה. כָּל זְכֻיּוֹת הָעוֹלָם עוֹמְדוֹת לִפְנֵי הַמְּאוֹרוֹת הַלָּלוּ. מִכֻּלָּם יוֹצְאִים שְׁנֵי מְאוֹרוֹת שְׁקוּלִים כְּאֶחָד שֶׁעוֹמְדִים לִפְנֵיהֶם תָּמִיד."],[4,"","כְּנֶגֶד אֵלֶּה שִׁבְעִים מְמֻנִּים גְּדוֹלִים שֶׁבַּחוּץ שֶׁסּוֹבְבִים אֶת כָּל אַרְבַּעַת הַהֵיכָלוֹת הַלָּלוּ. שִׁבְעִים אוֹרוֹת אֵלּוּ וּשְׁנֵי אוֹרוֹת שֶׁעוֹמְדִים לִפְנֵיהֶם, כֻּלָּם פְּנִימִיִּים לִפְנִים וְלִפְנִים, וְזֶה סוֹד הַכָּתוּב (שיר ז) בִּטְנֵךְ עֲרֵמַת חִטִּים סוּגָה בַּשּׁוֹשַׁנִּים."],[5,"","לִפְנֵי הָאוֹרוֹת הַלָּלוּ נִכְנָסִים כָּל הַזְּכֻיּוֹת וְעַל כָּל מַעֲשֵׂי הָעוֹלָם לְהִדּוֹן. שְׁנֵי הָאוֹרוֹת הַלָּלוּ מְעִידִים עֵדוּת, מִשּׁוּם (שהם) שֶׁיֵּשׁ שֶׁבַע עֵינֵי ה' שֶׁמְּשׁוֹטְטִים בְּכָל הָאָרֶץ, (כן כל) וְכָל מַה שֶּׁנַּעֲשֶׂה בָּעוֹלָם נִרְשָׁם בְּאוֹתוֹ מַעֲשֶׂה מַמָּשׁ וְאוֹתָהּ זְכוּת מַמָּשׁ וְעוֹמְדִים בְּקִיּוּמָם. וּשְׁנֵי הָאוֹרוֹת הַלָּלוּ רוֹאִים בָּהֶם וּמִסְתַּכְּלִים וּמְעִידִים לִפְנֵי שִׁבְעִים אוֹרוֹת הָאֵלֶּה. אֵלֶּה שִׁבְעִים גּוֹזְרֵי גְזֵרוֹת וְדָנִים דִּינִים, הֵן לְטוֹב הֵן לְרַע. וְכָאן הוּא מְקוֹם הַזְּכוּת."],[6,"","רוּחַ זוֹ בָּהּ נִרְשְׁמוּ שָׁלֹשׁ אוֹתִיּוֹת שֶׁהֵם יה\"ו. שֶׁכְּשֶׁהָאוֹתִיּוֹת הַלָּלוּ נִדְבָּקוֹת בַּמָּקוֹם הַזֶּה בְּהִדָּבְקוּת שֶׁל זָכָר וּנְקֵבָה, אָז נִרְשָׁמִים בּוֹ וְלֹא מִסְתַּלְּקִים מִשָּׁם. אַחַר כָּךְ יוֹצֵא אוֹר אֶחָד שֶׁמֵּאִיר לְאַרְבָּעָה צְדָדִים. הָאוֹר הַזֶּה מוֹצִיא שְׁלֹשָׁה אֲחֵרִים שֶׁהֵם שְׁלֹשָׁה בָּתֵּי דִין שֶׁדָּנִים דִּינִים אֲחֵרִים בְּדִבְרֵי הָעוֹלָם - בְּעֹשֶׁר, בְּעֹנִי, בְּמַחֲלוֹת, בִּשְׁלֵמוּת בְּכָל אוֹתָם שְׁאָר דְּבָרִים שֶׁהָעוֹלָם נִדּוֹן בָּהֶם. הֵיכָל אֶחָד לְאוֹתָם שִׁבְעִים רִאשׁוֹנִים לֵפְנִים. שְׁלֹשָׁה לְאוֹתָם שְׁלֹשָׁה הָאֲחֵרִים."],[7,"","עוֹלָה הָרוּחַ הַזּוֹ וְכוֹלֶלֶת כָּל אֵלּוּ שֶׁלְּמַטָּה, וּמוֹצִיאָה חַיָּה קְדוֹשָׁה אַחַת מִתְלַהֶטֶת, וְיֵשׁ לָהּ עֵינַיִם כְּמוֹ עֵינֵי אָדָם לְהַשְׁגִּיחַ בְּאֶלֶף אֲלָפִים וְרִבּוֹא רִבְבוֹת צְבָאוֹת בַּעֲלֵי הַדִּין. כֻּלָּם לוֹקְחִים פְּתָקִים וּפוֹתְחִים וְסוֹגְרִים בָּעוֹלָם וּמַשְׁלִימִים דִּין."],[8,"","תַּחַת הַחַיָּה הַזּוֹ אַרְבָּעָה שְׂרָפִים לוֹהֲטִים, כֻּלָּם כְּכַפְתּוֹר וָפֶרַח וּשְׁבִיבֵי אֵשׁ. עוֹלִים שִׁבְעִים וּשְׁנַיִם גַּלְגַּלִּים לְכָל אֶחָד מְלֹהָטִים בְּאֵשׁ. כְּשֶׁנּוֹסְעִים, נַעֲשֶׂה נָהָר אֶחָד שֶׁל אֵשׁ. אֶלֶף אֲלָפִים מְשַׁמְּשִׁים לְאוֹתָהּ הָאֵשׁ, וּמִשָּׁם יוֹצְאִים כַּמָּה צְבָאוֹת. כְּשֶׁהַגַּלְגַּלִּים נוֹסְעִים, כַּמָּה הֵם רִבּוֹא רְבָבוֹת שֶׁיַּעַמְדוּ מֵהֶם בְּתוֹךְ אוֹתָהּ הָאֵשׁ. תַּחַת הַהֵיכָל הַשֵּׁנִי יוֹצְאִים צְבָאוֹת שֶׁמְּזַמְּרִים וּבָאִים לְהִתְקָרֵב כָּאן וְכֻלָּם נִשְׂרָפִים."],[9,"","כָּל אוֹתָם מְמֻנֵּי הָעוֹלָם שֶׁהִתְמַנּוּ לִשְׁלֹט, מִכָּאן יוֹצֵא דִינָם לִשְׁלֹט מִתּוֹךְ אוֹתָהּ הָרוּחַ שֶׁנִּרְשְׁמָה בְּשָׁלֹשׁ אוֹתִיּוֹת. וּמִכָּאן מַעֲבִירִים קִיּוּמָם מֵהָעוֹלָם וְנִדּוֹנִים בָּאֵשׁ הַזּוֹ שֶׁשּׁוֹפַעַת וְיוֹצֵאת. הַכֹּל נִמְסָר בַּהֵיכָל הַזֶּה. מִשּׁוּם שֶׁנִּרְשְׁמוּ בְּשָׁלֹשׁ אוֹתִיּוֹת כָּאן, הָרוּחַ הַזּוֹ נִכְלֶלֶת בָּהֶם. אוֹתָהּ הַחַיָּה מוֹצִיאָה צְבָאוֹת וּמַחֲנוֹת שֶׁאֵין לָהֶם חֶשְׁבּוֹן."],[10,"","כָּל דִּינֵי הָעוֹלָם יוֹצְאִים מֵהַהֵיכָל הַזֶּה, הֵן טוֹב וְהֵן לְרַע, פְּרָט לִשְׁלֹשָׁה - בָּנִים, חַיִּים וּמְזוֹנוֹת, שֶׁלֹּא נִתְּנָה רְשׁוּת בַּמָּקוֹם הַזֶּה. שֶׁהֲרֵי בְּאוֹתוֹ נָהָר עֶלְיוֹן שֶׁכָּל הָאוֹרוֹת שׁוֹפְעִים מִמֶּנּוּ הַדָּבָר עוֹמֵד. בְּאֶמְצַע הַהֵיכָל הַזֶּה הוּא מָקוֹם מְתֻקָּן כְּנֶגֶד הָרוּחַ שֶׁלְּמַעְלָה בְּתוֹךְ הָרוּחַ הַזּוֹ, וְזוֹ עוֹלָה בָהֶם."]]],[["תְּרֵין עֶשֶׂר פָּתְחִין אִנּוּן לְהֵיכָלָא דָא. בְּכָל פִּתְחָא וּפִתְחָא כָּל אִנּוּן סָרְכִין וּמְמַנָּן דְּאִנּוּן מַכְרְזֵי לְאוֹדָעָא לְתַתָּא כָּל אִנּוּן דִּינִין דִּזְמִינִין לְנַחֲתָא לְתַתָּא. כְּמָא דְאַתְּ אָמֵר, (דניאל ד׳:י״א) קָרֵא בְחַיִל וְכֵן אָמַר גּוֹדוּ אִילָנָא וְגו'.","וּמִגּוֹ כָּרוֹזֵי אִלֵּין נָטְלֵי מִלָּה כָּל מָרֵיהוֹן דְּגַדְּפִין עַד דְּאוֹדְעֵי מִלָּה לָרָקִיעַ (קכה א) דְּחַמָּה. וּמִתַּמָּן כַּד נָפִיק שִׁמְשָׁא נָפִיק מִלָּה וְאִתְשַׁטְיָיא בְּעָלְמָא עַד דְּמָטֵי לְהַהוּא חִיוְיָא דִּרְקִיעָא (קכ\"ה א) דְּכָל כֹּכְבֵי דִּרְקִיעָא גְּלִידוּ בֵּיהּ דְּאִיהוּ בְּאֶמְצָעִיתָא דִּרְקִיעָא.","וְשָׁמְעִין מִלָּה וְנַקְטִין לָהּ אִנּוּן סָרְכִין דִּתְחוֹת (שמיא) (ד\"א שמשא) וְאִנּוּן דִּמְמַנָּן עַל הַהוּא חִיוְיָא וּמִתַּמָּן אִתְפַּשַּׁט לְעָלְמָא. וְאֲפִילּוּ רוּחִין וְשֵׁדִין וְאֲפִילּוּ עוֹפֵי שְׁמַיָא מוֹדָעֵי לֵיהּ בְּעָלְמָא. כָּרוֹזִין תָּבִין וְסָתְמִין פִּתְחִין. לָא סָלְקָא (לאסתלקא) רוּחָא בְּרוּחָא עַד דְּכֻלְהוּ רוּחִין תַּתָּאֵי כֻּלְהוּ חַד בַּהֲדֵי (רוחא בתר) הַאי רוּחָא וְכֻלְהוּ אִתְכְּלִילָן וְעָאלִין דָּא בְּדָא עַד דְּאִתְעֲבִיד כֹּלָּא חָד.","בַּר נָשׁ כַּד אִיהוּ בְּבֵי מַרְעֵיהּ הָכָא אִתְדָּן הֵן לְחַיִּים הֵן לַמָּוֶת. חַיִּין תַּלְיָיא לְעֵילָא אִי אִתְדַּן הָכָא לְחַיִּים יַהֲבֵי חַיִּין מִלְּעֵילָא וְאִי לָא, לָא יַהֲבִין. זַכָּאָה חוּלָקֵיהּ מַאן דְּאִתְדְּבַק בְּמָארֵיהּ וְיֵעוּל וְנָפִיק. הָכָא קִידָה בְּאַנְפִּין בְּאַרְעָא לְאִתְגַּבָּרָא עַל דִּינָא. עַל הַאי הֵיכָלָא אִתְּמָר (דברים לכ) אֵל אֱמוּנָה וְאֵין עָוֶל וְגו':","הֵיכָּלָא חֲמִישָׁאָה. הֵיכָלָא דָא הֵיכָלָא דִּבְרָקָא זְהֵיר. דְּאִיהוּ רוּחָא דְּמַזְהִיר נָהִיר לְאִנּוּן תַתָאֵי. רוּחָא דָא אִיהוּ כָּלִיל וּפָתַח וְסָגִיר נָהִיר וְנָצִיץ לְכָּל סִטְרִין. מִנְּצִיצוֹ דָּא נָהִיר חַד נְהוֹרָא כְּעֵין אַרְגְּוָונָא. נְהוֹרָא דָא כָּלִיל כָּל (ד\"א כלל) גְּוָונִין דְּנָהֲרִין. נְהוֹרָא חִוָּור וְאוּכָם סוּמָק וְיָרוֹק. אִתְכְּלִילָן אִלֵּין בְּאִלֵּין. אִתְרְקִים חִוָּור בְּסוּמָק. אוּכָם בְּיָרוֹק. לְבָתַר חִוָּור בְּאוּכָם וְאִתְעֲבִיד חַד חֵיוָותָא מְרֻקָּמָא וְאִתְכְּלִיל בָּהּ יָרוֹק וְסוּמָק. דְּיוֹקְנָהָא כִּדִיוּקְנָא דְּבַר נָשׁ דְּכָלִיל כָּל דִּיוּקְנִין.","מִינָהּ נָפְקוּ ד' סָמְכִין דְּאִנּוּן חֵיוָון רַבְרְבָן עַל אִלֵּין דִּלְתַתָּא. חַד אִקְרֵי אוֹפָן דְּאִיהוּ תְּרֵין. בְּגִין דְּכַד אִתְחַזֵּי הַאי אִתְנְהִיר אָחֳרָא בְּגַוֵויהּ. דָּבִיק דָּא בְּדָא. עָאל דָּא בְּדָא. לְבָתַר עָאל אָחֳרָא דָּא בְּדָא וְאִתְחַזּוּן ד' רֵישִׁין לְד' סִטְרִין דְּעָלְמָא וְכֻלְהוּ חַד גּוּפָא. וְאִלֵּין אִנּוּן דִּכְתִיב בְּהוּ (יחזקאל א׳:ט״ז) כַּאֲשֶׁר יִהְיֶה הָאוֹפָן בְּתוֹךְ הָאוֹפָן, וְכֻלְהוּ אִלֵּין קְשִׁירִין דָּא בְּדָא. כְּחֵיזוּ (נ\"א דחיזון) דְּחֵיוָון עִלָּאִין דְּלָא מִתְפָּרְשָׁן לְעָלְמִין. הַאי חֵיוָתָא דְּאַרְבַּע גְּוָונִין מְרֻקָּמָן אֲחִידָן אִלֵּין בְּאִלֵּין לְד' סִטְרִין. מֵהָכָא כַּד נָטְלָא חֵיוָתָא דָא נָטְלָא לִתְרֵין סִטְרִין.","הַאי רוּחָא דִבְרָקָא אִתְכְּלִיל בִּתְרֵין רוּחִין. רוּחָא דָא דִּבְרָקָא אַפִּיק חַד חֵיוָתָא וְכָל אִנּוּן נְהוֹרִין. רוּחָא אָחֳרָא אִתְנְהִיר מִנֵּיהּ דְּאִקְרֵי רוּחָא מְלַהֲטָא","נָהֲרִין מִנֵּיהּ תְּרֵין נְהוֹרִין דְּאִנּוּן אַרְבַּע. וְאִלֵּין נְהוֹרִין מִתְהַפְּכִין בִּגְוָונִין. וְהָכָא אִיהוּ (בראשית ג׳:כ״ד) לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת. אִלֵּין אִנּוּן נְהוֹרִין דְּמִתְהַפְּכָן שְׁנָנָא דְחַרְבָּא (ואלין גליף) וְאִלֵין קָיְימֵי עַל הֵיכָלָא דִלְתַתָּא. בְּגִין דְּהַאי לַהַט הַחֶרֶב קָיְימָא עַל אִנּוּן ע' נְהוֹרִין דְּבֵי דִינָא. מֵהָכָא כָּל אִנּוּן דַּיָינִין דְּדָיְינֵי דִּינָא חַרְבָּא תָּלְיָיא עַל רֵישַׁיְיהוּ מִלְּעֵילָא.","הַאי לַהַט הַחֶרֶב דְּאִלֵּין אִנּוּן נְהוֹרִין דְּלִסְטַר שְׂמָאלָא אַפִּיקוּ חַד חֵיוָתָא אָחֳרָא דְּקָיְימָא עַל ד' דְּלָא קָיְמֵי בְּקִיּוּמַיְיהוּ תְּרֵי מִימִינָא וּתְרֵי מִשְּׂמָאלָא. כַּד רוּחָא דְחֵיוָתָא הַאי עָאל בְּאִלֵּין. נָצִיץ מִנַיְיהוּ תְּרֵי נִיצוֹצִין מְלַהֲטָן. וְנָפְקֵי מֵהַאי הֵיכָלָא לְבַר וּמִתְהַפְּכֵי תָּדִיר. אִלֵּין נִיצוֹצִין (נג ב) מְלַהֲטָן לְזִמְנִין נוּקְבֵי לְזִמְנִין גּוּבְרֵי לְזִמְנִין רוּחִין לְזִמְנִין עִירִין קַדִּישִׁין.","מַאי טַעְמָא בְּגִין דְּכַד אִתְכְּלִיל הַאי חֵיוָותָא בְּחֵיוָותָא קַדְמָאָה, מִגּוֹ תְּקִיפוּ דְּאִתְכְּלִילָן דָּא בְּדָא, נָפְקָא חַד נִצּוֹצָא מְלַהֲטָא תָּדִיר דְּלָא אִתְדְעַךְ לְעָלְמִין, וְשָׁאטָא וְאָזְלָא אֲבַּתְרַיְיהוּ דְּאִינוּן תְּרֵין נִיצוֹצִין.","וְהַשְׁתָּא אִינוּן גּוּבְרִין וְעָבְדִין שְׁלִיחוּתָא בְּעָלְמָא, וְעַד לָא מְסַיְימֵי מִתְדָּעֲכֵי (כדין) וְהַהוּא נִיצוֹצָא בָּטַשׁ בְּהוּ וְנָהִיר לוֹן וְאִתְחַדְּשׁוּן כְּמִלְּקַדְמִין וְאִינוּן נוּקְבֵי וְאָזְלֵי וְשָׁאטָן וְעַד לָא מְסַיְימֵי מִתְדָּעֲכֵי. וְהַאי נִיצוֹצָא בָּטַשׁ בְּהוּ וְנָהִיר לוֹן וְאִתְהַדְּרָן כְּמִלְּקַדְּמִין, בְּגִין דְּהַהוּא נִיצוֹצָא כָּלִיל מִכֹּלָּא כָּלִיל מִד' גְּוָונִין וּבְגִין דָּא אִינוּן מִתְהַפְּכִין לְכָל הָנֵי גַוְונֵי."],[[0,"תרין עשר פתחין אינון להיכלא דא בכל פתחא ופתחא כל אינון סרכין וממנן דאינון מכרזי:","י\"ב פתחים הם להיכל הזה, בכל פתח ופתח נמצאים כל אלו השוטרים והממונים שהם מכריזים, \u0003לאודעא לתתא כל אינון דינין דזמינין לנחתא לתתא, כד\"א קרא בחיל, וכן אומר גודו אילנא וגו',\u0004 להודיע למטה כל אלו הדינים העתידים לירד למטה, כמ\"ש קרא בחיל, וכן גודו אילנא וגו', שכרוזים הללו באים מכאן."],[0,"","פירוש, כי עצם ההיכל הוא בחינת מחזה ולמעלה, והתחתונים ששורשם מבחינת מחזה ולמטה, אינם ראוים לקבל אלא מבחינת מחזה ולמטה, כי כל בחינה צריכה לקבל רק מהבחינה שכנגדה, כנודע. וז\"ס הפתחים שבהיכל, שהפתחים ההם הם בחינת מחזה ולמטה של ההיכל, שהתחתונים יכולים לקבל שפעם מהם, וע\"כ הם נבחנים כמו פתחים להורות, שאינם יכולים לבא ולקבל מההיכל כי אם דרך שם, שהיא מחזה ולמטה כמו בחינתם, בדומה להיכל גשמי שאי אפשר לבא בו זולת דרך הפתח. וע\"כ עומדים שם בפתחים ההם, כל אלו הממונים המשפיעים משם את פסקי הדין אשר בב\"ד שבהיכלות, אל התחתונים, שה\"ס הכרוזים שמכריזים ונשמעים ונעשים בעולם."],[0,"","וענין י\"ב פתחים שיש בהיכל הזה. הוא, כי ד' היכלות כלולים בהיכל הזה כנ\"ל באות ק\"ב, שהם נגד ד' בחינות חו\"ב תו\"מ של ההיכל, ובכל היכל והיכל יש ג' פתחים, הרי י\"ב פתחים. ומה שלא יש ד' פתחים בכל היכל, הוא מטעם היותם בחינת מחזה ולמטה כנ\"ל שחסר בהם פני אדם, ואין שם אלא ג' פנים, שהם רק ג' בחינות חו\"ב ות\"ת. ע\"ד שנתבאר לעיל (דף מ\"ו ד\"ה ביאור) שלכל חיה ד' גלגלים להיותם מחזה ולמעלה ולכל גלגל ג' סמכין להיותם מחזה ולמטה, ע\"ש, כן כאן כלולים ד' היכלות בהיכל הזה, להיותם בחינת מחזה ולמעלה, אבל בכל היכל רק ג' פתחים להיותם בחינת מחזה ולמטה."],[1,"ומגו כרוזי אלין נטלי מלה כל מאריהון דגדפין עד דאודעי מלה לרקיע דחמה:","ומן כרוזים האלו של השוטרים והממונים שבפתחי היכלות, מקבלים כל בעלי כנפים, עד שמודיעים הדבר אל הרקיע של החמה. דהיינו לרקיע הב' דעולם העשיה, ששם החמה בין ז' ככבי לכת. בעלי כנפים פירושו מלאכים, בסו\"ה כי עוף השמים יוליך את הקול (קהלת י'), ואומר שכל המלאכים שמתחת ההיכלות בבריאה, וכן ביצירה ועשיה מקבלים הכרוזים של השוטרים והממונים שבפתחי ההיכל, דהיינו שכל מלאך עליון נותן להתחתון ממנו, עד שהכרוז מגיע אל החמה, שהוא הרביעי מז' ככבי לכת. אמנם אין הכונה לז' ככבי לכת הגשמיים אלא לז' ספירות שברקיע הב' של עולם העשיה הרוחני, שז' ככבי לכת הגשמיים נבחנים לענפים שלהם. כי כן דרך החכמים לדבר בענפים גשמים ולבאר עמהם את שרשיהם הרוחני."],[1,"ומתמן כד נפיק שמשא נפיק מלה ואתשטייא בעלמא עד דמטי לההוא חיויא דרקיעא,","ומשם כאשר השמש יוצא על הארץ, יוצא דבר הכרוז מהשמש, ומשוטט בהעולם עד שהדבר מגיע אל הנחש שבהרקיע, \u0003דכל ככבי דרקיעא גלידו ביה, דאיהו באמצעיתא דרקיעא,\u0004 שכל ככבי הרקיע מוקפאים בו, והוא עומד באמצע הרקיע \u0003ושמעין מלה ונקטין לה אינון סרכין דתחות, ואינון דממנן על ההוא חיויא, ומתמן אתפשט לעלמא,\u0004 ושומעים הדבר ומקבלים אותו אלו השוטרים של מטה, ואלו הממונים שעל הנחש, ומשם מתפשט הדבר לעולם."],[1,"","ביאור ענין חיויא דרקיע תמצא להלן בזהר (חיי שרה אות ע\"א) וז\"ל, \u0003ותא חזי באמצעות דרקיעא אתקטר חד אורחא קסטרירא, ואיהו חיויא דרקיעא,\u0004 ובוא וראה, באמצע הרקיע נקשר שם אורח אחד מבהיק והוא הנחש שברקיע, \u0003דכל ככבין דקיקין כלהו קטירין ביה וקיימי ביה תלי תלין,\u0004 שכל הככבים הדקים מלראות אותם, כולם קשורים בו תלי תלים. והוא הנקרא אצל התוכנים בשם \u0003קו החלבי,\u0004 שמחמת ריבוי הככבים אשר שם הוא נראה לנו כמו קו אחד לבן כחלב. \u0003ואנון ממנן בסתירו עובדי בני עלמא,\u0004 ואלו ככבים הדקים הם ממונים על המעשים שבסתר של בני העולם. עכ\"ל."],[1,"","וז\"ש כאן \u0003עד דמטי לההוא חיויא דרקיעא דכל ככבי דרקיעא גלידו ביה,\u0004 דהיינו לקו החלבי שהככבים כולם מוקפאים שם, כלומר שאינם זזים ממקומם. פירוש כי ההנהגה בפרטיות מסודרת תחת הככבים, כמ\"ש ז\"ל אין לך עשב מלמטה שאין לו ככב ומזל מלמעלה שמכה אותו ואומר לו גדל. ונודע שכל מדרגה וכן שפע הנמשך ממנה מחולקת לשנים, לבחינת מחזה ולמעלה ולבחינת מחזה ולמטה, ולפיכך גם הככבים מחולקים על פיהם, שיש ככבים שאינם ככבי לכת והם קפואים בקו החלבי שהם בחינת מחזה ולמעלה, ששם החסדים מכוסים ואין השפע מגיע מהם לתחתונים בגלוי. וז\"ש שם \u0003ואנון ממנן בסתירו עובדי בני עלמא,\u0004 כי אינם ממונים רק על מעשים שבסתר. ויש ככבי לכת, שהם שצ\"מ חנכ\"ל, שהם בחינת מחזה ולמטה ששם החסדים מגולים והשפע מגיע מהם לתחתונים בגלוי. וע\"כ הולכים ומסבבים העולם כל אחד בדרכו המיוחד, לחלק השפע המיוחד לו."],[1,"","וז\"ש \u0003עד דמטי לההוא חיויא\u0004 וכו' \u0003ושמעין מלה,\u0004 כי אלו הככבים אינם מקבלים הדבר להשפיע לתחתונים אלא שומעים אותו בלבד, \u0003ונקטין לה אינון סרכין דתחות,\u0004 ומקבלים הדבר, רק השוטרים שמתחת הקו החלבי, שהם מבחינת מחזה ולמטה, שמהם מושפע לתחתונים. וכן \u0003ואנון דממנן על ההוא חיויא,\u0004 דהיינו הממונים שממעל הקו החלבי, גם הם מקבלים הדבר, אבל הככבים עצמם שבקו החלבי אינם מקבלים אלא שומעים בלבד, באופן שיספיק אל הסרכין דתחות, שיקבלו מהם."],[2,"ומתמן אתפשט לעלמא, ואפילו רוחין ושדין ואפילו עופי שמיא מודעי ליה בעלמא כרוזין:","ומשם מן הסרכין שלמטה, מתפשט ונעשה הכרוז בהעולם, ואפילו רוחות ושדים ואפילו עוף השמים מעבירים ומודיעים הכרוזים בהעולם. כלומר , שכל בריות העולם ואפילו שדים ורוחות מוכנים להוציא לפועל את הכרוזים הללו."],[2,"תבין וסתמין פתחין:","הממונים חוזרים וסוגרים הפתחים. פירוש. בעת השפעת ההנהגה אל העולם נפתחים י\"ב הפתחים והכרוזים משתלשלים להעולם דרך המדרגות כנ\"ל. ואחר שיצא לפועל בהעולם חוזרים וסוגרים הפתחים. כי אינם פתוחים רק בשעת השפעה."],[2,"לא סלקא רוחא ברוחא, עד דכלהו רוחין תתאי כלהו חד בהדי האי רוחא,","אין הרוח שבכאן עלה לרוח העליון, שבהיכל החמישי, עד שכל הרוחות שבהיכלות התחתונים נעשו אחד עם הרוח הזה שבכאן, \u0003וכלהו אתכלילן ועאלין דא בדא עד דאתעביד כלא חד,\u0004 וכל הרוחות נכללים ונכנסים זה בזה עד שנעשו כולם אחד. ואחר התכללות הזה עולה הרוח שבכאן עמהם להיכל החמשי ונכלל בהרוח אשר שם."],[3,"בר נש כד איהו בבי מרעיה הכא אתדן הן לחיים הן למות:","כשהאדם מוטל חולה על ערש דוי, הוא נידון כאן הן לחיים והן למות. \u0003חיין תלייא לעילא, אי אתדן הכא לחיים יהבי חיין מלעילא, ואי לא יא יהבין,\u0004 חיים תלוי למעלה בנהר העליון ולא כאן בהיכל זכות, כנ\"ל, אמנם אם נידון כאן לחיים, נותנים לו חיים מלמעלה, מהנהר העליון הנק' מזל, ואם לא, אין החיים ניתנים לו מלמעלה. \u0003זכאה חולקיה מאן דאתדבק במאריה ויעול ונפיק,\u0004 אשרי חלקו מי שנתדבק ברבונו ונכנס ויוצא בהיכל הזה כחפצו."],[3,"הכא קידה באנפין בארעא לאתגברא על דינא:","כאן בהיכל זה נוהג קידה על אפיים, שפניו יגעו בארץ, בכדי להתגבר על הדין. והנה בהיכל הב' אומר שצריכים כריעה, ובהיכל הג' אומר שצריכים השתחואה, דהיינו הרכנת הראש, וכאן אומר שצריכים קידה באנפין על ארעא. ויש להבין זה, והענין הוא, כי ענין הכריעות והשתחויות שעושים הצדיקים להתרצות לרבונם הוא מכוון לפי המוחין שממשיכים, ולפיכך בהיכל הוד שהיא בחינת ו\"ק צריכים לכריעה על ברכים, ובהיכל הג' הנחשב לג\"ר כלפי היכל הב', צריכים להשתחואה, דהיינו הרכנת הראש עד שיראה איסר מכנגד לבו, ואינם צריכים לקידה על אפים, משום שעוד אינו בחינת ג\"ר ממש, להיותו בחינת מחזה ולמטה דהיכלות. אבל בהיכל הרביעי שבכאן להיותו כבר מחזה ולמעלה דהיכלות ששם ג\"ר מבחינת פנים, ע\"כ צריכים לקידה על אפים שיגעו פניו בארץ."],[3,"על האי היכלא אתמר אל אמונה ואין עול וגו',","מרמז על רישא דקרא, שנאמר כי כל דרכיו משפט כי בהיכל זה מקום הבתי דינים ששם מתגלה אשר כל דרכיו משפט, שבזה משיגים אותו ית' בסוד אל אמונה ואין עול כי צדיק וישר הוא."],[4,"היכלא חמישאה, היכלא דא היכלא דברקא זהיר דאיהו רוחא דמזהיר נהיר לאינון תתאי,","היכל החמישי, היכל זה, הוא היכל שהברק מאיר בו, שהוא רוח הנקרא ברק, שמזהיר ומאיר להתחתונים. ומזהיר, פירושו בהארת החכמה הנק' זהר. ומאיר היינו באור החסדים."],[4,"רוחא דא איהו כליל ופתח וסגיר נהיר ונציץ לכל סטרין:","רוח הזה, ברקא, הוא כולל ופותח וסוגר מאיר ומתנוצץ לכל הצדדים. פירוש. בעת שהרוח הזה עושה זווגו להאיר הארתו,הוא \u0003כליל\u0004 לכל התחתונים שעלו אליו בבחינת מ\"ן. \u0003ופתח,\u0004 היינו להארת ו\"ק דג\"ר, \u0003וסגיר,\u0004 היינו להארת ג\"ר דג\"ר, \u0003נהיר,\u0004 היינו באור ישר, \u0003ונציץ,\u0004 היינו באו\"ח, \u0003לכל סטרין,\u0004 היינו מעלה ומטה ולד' רוחות."],[4,"מנציצו דא נהיר חד נהורא כעין ארגוונא:","מהתנוצצות הזה מאיר ויוצא אור אחד שמראהו כעין ארגמן. \u0003נהורא דא כליל כל גוונין דנהרין נהורא חוור ואוכם סומק וירוק,\u0004 אור זה, שהוא כעין הארגמן, הוא אור כולל לכל המראות המאירים דהיינו אור לבן ושחור אדום וירוק שהם חו\"ב תו\"מ כנודע, \u0003אתכלילן אלין באלין אתרקים חוור בסומק אוכם בירוק לבתר חוור באוכם,\u0004 נכללו אלו באלו ונרקם הלבן באדום, והשחור בירוק, ואח\"כ הלבן בשחור, \u0003ואתעביד חד חיוותא מרקמא, ואתכליל בה ירוק וסומק, דיוקנאה כדיוקנא דבר נש דכליל כל דיוקנין.\u0004 ונעשה מהם חיה אחת מרוקמת מכל הגוונין, ונכלל בה בעיקר ירוק ואדום, ודמות פניה כפני אדם, הכולל לכל הצורות."],[5,"מינה נפקו ד' סמכין, דאינון חיוון רברבין על אלין דלתתא,","מן החיה הזו יוצאים ד' אדנים, שהם חיות גדולות כלפי אלו של מטה. כלומר, אע\"פ שהסמכין הם בחינת מחזה ולמטה של כל חיה, שבהיכלות התחתונים אין שם משום זה אלא ג' סמכין מ\"מ כאן בהיכל הזה הוא כולו ג\"ר, וגם הסמכין הם כבחינת מחזה ולמעלה, ונבחנים כחיות גדולות. ומפרש, \u0003חד אקרי אופן, דאיהו תרין, בגין דכד אתחזי האי אתנהיר אחרא בגויה,\u0004 אחד נקרא אופן, דהיינו רק המלכות בלבדה, והוא שנים, משום כשנראה זה, מאיר אחר בתוכו, והם שנים פירוש, כל בחינת מחזה ולמטה של החיה היא בחינת מלכות, וע\"כ נקראים אופנים, כי אופן הוא שם המלכות כנודע. אמנם כיון שהמלכות עלתה ונתמתקה בהבינה, ע\"כ נחשבת המלכות תמיד לב' אופנים, \u0003דכד אתחזי האי אתנהיר אחרא בגויה,\u0004 כאשר נראה המלכות הרי מאיר בתוכה הבינה, וע\"כ נבחנת לב' אופנים, אופן בתוך אופן. \u0003דביק דא בדא, עאל דא בדא, לבתר עאל אחרא דא בדא, ואתחזון ד' רישין לד' סטרין דעלמא,\u0004 ונעשו דבוקים הבינה והמלכות זו בזו, ונכנסה זו בזו, דהיינו המלכות בהבינה, ונעשו ב' אופנים ימין ושמאל במקום בינה, ואח\"כ נכנסה האחרת זו בזו, דהיינו הבינה נכנסה ונכללה במקום המלכות, ונעשו ב' אופנים ימין ושמאל גם במקום המלכות, ונראו עתה ד' ראשים לד' רוחות העולם, כי הימין ושמאל שבמקום בינה נבחנים לדרום צפון, והימין ושמאל שבמקום מלכות, נבחנים למזרח מערב, וכלהו חד גופא, אמנם כל הד' הם רק גוף אחד, דהיינו מלכות, כי כולם נעשו ע\"י התכללות המלכות בהבינה. \u0003ואלין אינון דכתיב בהו כאשר יהיה האופן בתוך האופן\u0004 ואלו הם שכתוב עליהם כאשר יהיה האופן בתוך האופן כמבואר."],[5,"וכלהו אלין קשירין דא בדא כחיזו דחיוון עלאין דלא מתפרשין לעלמין, האי חיוותא:","וכל אלו ד' הסטרין קשורים זה בזה, כמו חיות העליונות דחיה זו, שאינם נפרדים לעולם, \u0003דארבע גוונין מרקמן אחידן אלין באלין לד' סטרין:\u0004 כי הארבע גוונים המרוקמים בהחיה, שהם חו\"ב תו\"מ שלה שמחזה ולמעלה הנק' חיות עליונות, נאחזים אלו באלו, ונמשכים לד' סטרין אלו, שלמטה מחזה של החיה, שעי\"ז נקשרים ד' הסטרין זה בזה, ואינם נפרדים לעולם, \u0003מהכא כד נטלא חיוותא דא נטלא לתרין סטרין,\u0004 מכאן נשמע, שבנסוע חיה הזו היא נוסעת לב' סטרין, שהם בינה ומלכות שהן העיקר של ד' הסטרין, בסו\"ה, כאשר יהיה האופן בתוך האופן. כנ\"ל."],[6,"האי רוחא דברקא אתכליל בתרין רוחין, רוחא דא דברקא אפיק חד חיוותא וכל אינון נהורין:","רוח ברקא הזה נכלל בב' רוחות שרוח ברקא הוציא חיה אחת הנזכרת וכל אלו האורות הנזכרים, \u0003רוחא אחרא אתנהיר מניה דאקרי רוחא מלהטא,\u0004 ורוח אחר נמשך ממנו ומאיר הנקרא רוח לוהט."],[7,"נהרין מניה תרין נהורין דאינון ארבע, ואלין נהורין מתהפכין בגוונין, והכא איהו להט החרב המתהפכת,","מאירים ממנו, מן הרוח הלוהט, ב' אורות שהם ד', שהם בחינת ד' סטרין הנ\"ל, ואלו האורות מתהפכים במראיהם, והם נקראים להט החרב המתהפכת, \u0003אלין אינון נהורין דמתהפכן שננא דחרבא,\u0004 אלו הם האורות המתהפכים ונעשים להט החרב, \u0003ואלין קיימי על היכלא דלתתא, בגין דהאי להט החרב קיימא על אינון ע' נהורין דבי דינא,\u0004 ואלו האורות עומדים על האורות שבהיכל שלמטה מכאן, הנקרא היכל הזכות, משום שלהט החרב הזה עומד על ע' האורות שבבית דין, הנמצאים בהיכל הזכות."],[7,"","ביאור הדברים. כי נתבאר במראות הסולם דף ס\"ה אות י\"ג, שאלו ג' היכלות, דהיינו היכל הזכות והיכל ברקא והיכל הרצון, הם בחינת עי\"מ דפנים, אשר היכל הזכות הוא ו\"ק דפנים, המכונה עיבור יניקה, והיכל ברקא הוא ו\"ק דג\"ר דפנים. והיכל הרצון הוא ג\"ר דג\"ר דפנים, ע\"ש. והזהר מביא להלן בסוף היכל השביעי, אשר אברהם לקח היכל ברקא שבכאן, ויצחק לקח היכל הזכות. כי בהיות כאן בחינת מוחין דפנים, ע\"כ אפילו הו\"ק דג\"ר הצריכים להאיר בהיכל ברקא, שהם נמשכים מסוד בינה החוזרת לחכמה, שה\"ס יצחק, לא יוכלו להאיר בקביעות בהיכל שבכאן, אלא רק בדרך התכללות הרוחין, כמ\"ש להלן, דהיינו רק בעת ההתכללות, ושלא בעת התכללות מאיר כאן רק אברהם בלבד, שהוא קו ימין חסד. ויצחק, שה\"ס בינה ששבה לחכמה, מאיר רק בהיכל הזכות, ובבחינת ו\"ק בלי ג\"ר. שז\"ס ע' נהורין אשר שם, שהם נגד ז\"ס תחתוניות שכל אחת כלולה מעשר, והם ע'. אבל הג\"ר אינם יכולים להאיר שם בהיכל הזכות, כנ\"ל, ונשארו כאן בהיכל ברקא בבחינת גבורות ודינים, בלי האור השייך להם, כי האור שלהם הוא בחינת יצחק, והוא אינו כאן אלא בהיכל הזכות."],[7,"","וכבר ידעת, שאלו ב' רוחין שבהיכל, ה\"ס עי\"מ דפנים ועי\"מ דאחור, הכלולים בכל היכל והיכל, אשר רוח העליון הוא בחינת עי\"מ דפנים שבהיכל, ורוח התחתון הוא בחינת עי\"מ דאחורים שבהיכל. (כמ\"ש לעיל דף מ\"ג ד\"ה ובזה. ע\"ש) ולפי\"ז נמצא, אשר רוח העליון שה\"ס עי\"מ דפנים המקובלים מאו\"א עלאין, היא ממותק כולו ע\"י אברהם, דהיינו אור החסד השולט בהיכל זה, כי מוחין דפנים הם כולם אור החסדים, המכונים \u0003אוירא דכייא\u0004 כנודע. מה שאין כן רוח התחתון שהיא בחינת עי\"מ דאחורים, שה\"ס מוחין המקובלים מישסו\"ת, שבהם ה\u0003י'\u0004 יוצא מאויר, והבינה שב להיות חכמה, (כנ\"ל בבראשית א' דף ט' ד\"ה ועביד) הנחשב כאן לבחינת שמאל, ולבחינת יצחק, אין לרוח הזה שום מיתוק מאברהם, שכולו ימין, ואין בו משמאל ולא כלום, וע\"כ נשאר בבחינת דינים. ולפיכך הוא נקרא בשם \u0003רוחא מלהטא,\u0004 שהוא לוהט תמיד בשלהבת הדינים, וה\"ס להט החרב המתהפכת."],[7,"","וז\"ש \u0003ועלין קיימי על היכלא דלתתא\u0004 וכו', כי אלו האורות שברוחא מלהטא, הם בחינת ג\"ר דיצחק, שלא יכלו לבא בהיכל הזכות ונשארו בהיכל ברקא שבכאן בבחינת דינים, וע\"כ נבחן שהם עומדים על היכל הזכות, כלומר שהם ג\"ר שלהם. וז\"ש \u0003בגין דהאי להט החרב קיימא על אינון ע' נהורין דבי דינא,\u0004 כי ע' נהורין שבהיכל הזכות ה\"ס ז\"ס תחתוניות שכל אחת כלולה מיוד, והאורות להט החרב שבכאן הם ג\"ר שלהם, המשלימם לעשר. \u0003מהכא, כל אינון דיינין דדייני דינא, חרבא תלייא על רישייהו מלעילא:\u0004 מכאן נשמע, שכל הדינים הדנים דין, חרב תלויה על ראשיהם מלמעלה. פירוש. כי אלו ע' נהורין, שומרים את עצמם שלא ימשכו כלום מבחינת האורות שלהם שברוח מלהטא שבכאן, להיותם בבחינת להט החרב, דהיינו שמלאים דינים. וע\"כ נבחן להט החרב לבחינת שומר עליהם, שידונו דין צדק, ולא יקחו יותר ממדרגתם. וצריכים לזכור כאן כל המתבאר לעיל בסוד ע' נהורין אלו."],[8,"האי להט החרב דאלין אנון נהורין דלסטר שמאלא אפיקו חד חיוותא אחרא:","להט החרב הזה, שהוא אורות שבצד שמאל. הוציאו חיה אחת אחרת, \u0003דקיימא על ד' דלא קיימי בקיומייהו, תרי מימינא ותרי משמאלא,\u0004 העומדת על ד' אופנים שאינם עומדים על קיומם, כלומר שאינם יכולים להמשיך בהארתם אלא שמאירים ומתכבים, והוא מטעם שהם ב' לצד ימין וב' לצד שמאל, דהיינו שפעם שולט בהם הימין לבדו, ופעם שולט בהם השמאל לבדו. וע\"כ בעת שליטת השמאל הם מתכבים והטעם הוא, כי היכל זה לקח אברהם, כנ\"ל, שה\"ס ימין, וע\"כ הנוטים לשמאל אין להם ממי לקבל הארתם, והם מתכבים."],[8,"כד רוחא דחיוותא האי עאל באלין, נציץ מנייהו תרי ניצוצין מלהטן ונפקי מהאי היכלא לבר ומתהפכי תדיר:","כאשר הרוח של חיה הזו, נכנס באלו הד' דלא קיימי בקיומייהו, כלומר בעת שהחיה נוסעת על ד' אופנים שלה, מתנוצץ מהם ב' ניצוצין לוהטים, ויוצאים לחוץ מהיכל הזה, והם מתהפכים תמיד. \u0003אלין ניצוצין מלהטן, לזמנין נוקבי ולזמנין גוברי, לזמנין רוחין לזמנין עירין קדישין,\u0004 ניצוצות לוהטות הללו, פעמים הן נקבות ופעמים הם זכרים לפעמים רוחות ולפעמים עירין קדושים. והביאור הוא להלן בדיבור הסמוך."],[9,"מאי טעמא, בגין דכד אתכליל האי חיוותא בחיוותא קדמאה, מגו תקיפו דאתכלילן דא בדא, נפקא חד נצוצא","וכו': שואל מה הטעם, ואומר משום ושבעת שנכללה חיה הזו עם חיה הראשונה, שיצאה מהאורות דרוחא דברקא, הנה מתוך תוקף התכללותן זו בזו יצא מהן ניצוץ אחד הלוהט תמיד ואינו נכבה לעולם, \u0003ושאטא ואזלא אבתרייהו דאינון תרין ניצוצין,\u0004 והניצוץ משוטט והולך אחרי שני הניצוצות הללו."],[10,"והשתא אינון גוברין ועבדין שליחותא בעלמא, ועד לא מסיימי מתדעכי","וכו', ועתה הם זכרים, ועושים שליחותם בעולם, אבל טרם שגמרו את שליחותם הם מתכבים. וכו'."],[10,"","ביאור הדברים. מתוך ששורשיהם של ב' ניצוצות הללו, הם ה\u0003ד' דלא קיימי בקיומייהו,\u0004 שאינם ממשיכים בהארתם, כי להיותם נמשכים מלהט החרב המתהפכת, נחלקה הארתם \u0003תרי מימינא ותרי משמאלא,\u0004 וכשמאירים מבחינת השנים שבימין מתקיימים אבל כשמתחילים להאיר מבחינת השנים שבשמאל הם מתכבים כנ\"ל ע\"כ גם ב' הניצוצין שיצאו מהם נוטים ג\"כ לימין ושמאל ואינם על קיומם. ולפיכך בכדי לתקן אותם נזדווגה ונכללה חיה זו דלהט החרב, עם חיה העליונה הראשונה שיצאה מרוחא דברקא, ואז נמצאים אלו ד' אופנים של חיה התחתונה \u0003דלא קיימי בקיומייהו\u0004 נכללים ונעשו אחד עם ד' האופנים של חיה העליונה, שהם \u0003כחיוון עלאין דלא מתפרשי לעלמין,\u0004 ונולד מהם ניצוץ אחד הכלול גם הוא מב' שהם ד', כמו הד' אופנים של חיה העליונה, \u0003דלא אתדעך לעלמין,\u0004 כמו הד' של חיה העליונה \u0003דלא מתפרשי לעלמין,\u0004 אמנם עדיין נבחן לניצוץ לוהט, להיות בו גם מבחינת ד' אופנים דחיה תחתונה."],[10,"","וכבר נתבאר, שאלו ד' אופנים ה\"ס ד' כחות המלכות אחר שנשתתפה עם הבינה, דהיינו מלכות ובינה שבבינה, ומלכות ובינה שבמלכות (כנ\"ל דף ע\"ה ד\"ה מינה) ותדע שהם בחינת גוברי ונוקבי, כי ב' שבבינה הם זכרים, כי הבינה בדכורא אסתיימת. וב' שבמלכות הם \u0003נוקבין,\u0004 והארת הימין נבחנת ל\u0003רוחין,\u0004 והארת השמאל נבחנת ל\u0003עירין.\u0004"],[10,"","וזה אמרו, \u0003ושאטא ואזלא אבתרייהו דאינון תרין ניצוצין,\u0004 שבהיות הניצוץ מתוקן באופן דלא אתדעך לעלמין, ע\"כ הוא המשפיע והמתקן את ב' הניצוצין, אלא באופן שהם \u0003מתהפכי תדיר,\u0004 וז\"ש \u0003והשתא אינון גוברין,\u0004 דהיינו בעת שהניצוץ משפיע להם הארת הבינה, הנבחנת לאור זכר, \u0003ועבדין שליחותא בעלמא,\u0004 דהיינו שמאירים אל התחתונים, \u0003ועד לא מסיימי מתדעכי,\u0004 דהיינו כל עוד שמאירים בבחינת הימין הם עושים שליחותם בעולם, ואז נבחנים ל\u0003רוחין,\u0004 אבל כשנוטים לבחינת שמאל הם מתכבים, ואינם יכולים להמשיך שליחותם. ואז נבחנים \u0003לעירין. וההוא ניצוצא בטש בהו, ונהיר לון ואתחדשון כמלקדמין, ואינון נוקבי, ואזלי ושאטן,\u0004 וניצוץ ההוא מכה ומאיר אליהם, אחר שנתכבו, והם מתחדשים כמקודם, והם נקבות, כלומר שהניצוץ משפיע להם עתה הארות המלכות הנבחנות לנקבות כנ\"ל, והולכים ומשוטטים. \u0003ועד לא מסיימי מתדעכי,\u0004 וטרם שגמרו שליחותם בעולם הם מתכבים. כלומר, כל עוד שהאירו בבחינת הימין נקראים \u0003רוחין\u0004 והם הולכים ומשוטטים, וכשנוטים לשמאל נקראים \u0003עירין\u0004 והם מתכבים. \u0003והאי ניצוצא בטש בהו ונהיר לון ואתהדרן כמלקדמין,\u0004 והניצוץ חוזר ומכה ומאיר אליהם, אחר שנתכבו, וחוזרים ומתחדשים כמקודם. וכן תמיד, כי בכל פעם שנכבים, מחדש אותם הניצוץ, פעם בימין ושמאל דבינה, דהיינו ברוחין ועירין זכרים. ופעם בימין ושמאל דמלכות, דהיינו ברוחין ועירין נקבות, ונמצאים מתהפכים תמיד על ארבע בחינות הללו. \u0003בגין דההוא ניצוצא כליל מכלא, כליל מד' גוונין ובגין דא אינון מתהפכין לכל הני גווני,\u0004 משום שניצוץ הזה כלול מכולם, וכלול מד' גוונים, ומשום זה ב' הניצוצות המקבלים ממנו מתהפכים לכל אלו הגוונים הנזכרים, דהיינו לזכרים ולנקבות לרוחות ולעירין."]],[[0,"","שְׁנֵים עָשָׂר פְּתָחִים הֵם לַהֵיכָל הַזֶּה. בְּכָל פֶּתַח וּפֶתַח כָּל אוֹתָם שָׂרִים וּמְמֻנִּים שֶׁמַּכְרִיזִים לְהוֹדִיעַ לְמַטָּה כָּל אוֹתָם הַדִּינִים הָעֲתִידִים לָרֶדֶת לְמַטָּה, כְּמוֹ שֶׁנֶּאֱמַר (דניאל ד) קוֹרֵא בְחַיִל וְכֵן אוֹמֵר קַצְּצוּ הָאִילָן."],[1,"","וּמִתּוֹךָ הַכְּרוּזִים הַלָּלוּ לוֹקְחִים דָּבָר כָּל בַּעֲלֵי הַכְּנָפַיִם, עַד שֶׁמּוֹדִיעִים הַדָּבָר לָרָקִיעַ שֶׁל חַמָּה. וּמִשָּׁם, כְּשֶׁיּוֹצֵאת הַשֶּׁמֶשׁ, יוֹצֵא דָבָר וּמְשׁוֹטֵט בָּעוֹלָם עַד שֶׁמַּגִּיעַ לְאוֹתוֹ הַנָּחָשׁ שֶׁל הָרָקִיעַ שֶׁכָּל כּוֹכְבֵי הָרָקִיעַ קְפוּאִים בּוֹ, שֶׁהוּא בְּאֶמְצַע הָרָקִיעַ."],[2,"","וְשׁוֹמְעִים הַדָּבָר, וְלוֹקְחִים אוֹתוֹ הַשָּׂרִים שֶׁתַּחַת (השמים) הַשֶּׁמֶשׁ, וְאוֹתָם שֶׁמְּמֻנִּים עַל אוֹתוֹ הַנָּחָשׁ, וּמִשָּׁם זֶה מִתְפַּשֵּׁט לָעוֹלָם. וַאֲפִלּוּ רוּחוֹת וְשֵׁדִים וַאֲפִלּוּ עוֹפוֹת הַשָּׁמַיִם מוֹדִיעִים אוֹתוֹ בָּעוֹלָם. הַכְּרוּזִים שָׁבִים וְסוֹתְמִים פְּתָחִים. לֹא עוֹלָה (להסתלק) רוּחַ בְּרוּחַ עַד שֶׁכָּל הָרוּחוֹת הַתַּחְתּוֹנוֹת כֻּלָּם אֶחָד יַחַד עִם (הרוח אחרי) הָרוּחַ הַזּוֹ, וְכֻלָּם נִכְלָלִים וְנִכְנָסִים זֶה בָּזֶה עַד שֶׁנַּעֲשָׂה הַכֹּל אֶחָד."],[3,"","כְּשֶׁבֶּן אָדָם נִמְצָא בְּבֵית חָלְיוֹ, כָּאן נִדּוֹן הֵן לְחַיִּים הֵן לְמָוֶת. הַחַיִּים תְּלוּיִים לְמַעְלָה. אִם נִדּוֹן כָּאן לְחַיִּים - נוֹתְנִים חַיִּים מִלְמַעְלָה. וְאִם לֹא - אָז לֹא נוֹתְנִים. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁנִּדְבָּק בְּרִבּוֹנוֹ וְנִכְנָס וְיוֹצֵא. כָּאן קִידָה עַל אַפַּיִם בָּאָרֶץ לְהִתְגַּבֵּר עַל הַדִּין. עַל הַהֵיכָל הַזֶּה נֶאֱמַר (דברים לב) אֵל אֱמוּנָה וְאֵין עָוֶל וְגוֹ'."],[4,"","הֵיכָל הַחֲמִישִׁי. הֵיכָל זֶה הֵיכַל הַבָּרָק שֶׁזּוֹהֵר, שֶׁהוּא רוּחַ שֶׁמַּזְהִיר וּמֵאִיר לְאוֹתָם הַתַּחְתּוֹנִים. רוּחַ זוֹ הִיא כְּלוּלָה וּפוֹתַחַת וְסוֹגֶרֶת, מְאִירָה וְנוֹצֶצֶת לְכָל הַצְּדָדִים. מִנִּצְנוּץ זֶה מֵאִיר אוֹר אֶחָד כְּעֵין הָאַרְגָּמָן. הָאוֹר הַזֶּה כּוֹלֵל כָּל (כלל) הַגְּוָנִים שֶׁמְּאִירִים. אוֹר לָבָן וְשָׁחֹר, אָדֹם וְיָרֹק. נִכְלָלִים אֵלֶּה בְּאֵלֶּה. נִרְקָם לָבָן בְּאָדם, שָׁחֹר בְּיָרֹק. אַחַר כָּךְ לָבָן בְּשָׁחֹר. וְנַעֲשֵׂית חַיָּה אַחַת מְרֻקֶּמֶת, וְנִכְלָל בָּהּ יָרֹק וְאָדם. דְּמוּתָהּ כִּדְמוּת אָדָם שֶׁכּוֹלֵל כָּל הַדְּמֻיּוֹת."],[5,"","מִמֶּנָּה יָצְאוּ אַרְבָּעָה עַמּוּדִים שֶׁהֵם חַיּוֹת גְּדוֹלוֹת עַל אֵלֶּה שֶׁלְּמַטָּה. אֶחָד נִקְרָא אוֹפַן שֶׁהוּא שְׁנַיִם. מִשּׁוּם שֶׁכְּשֶׁנִּרְאֶה זֶה, מֵאִיר אַחֵר בְּתוֹכוֹ. דָּבוּק זֶה בָּזֶה. נִכְנָס זֶה בָּזֶה. אַחַר כָּךְ נִכְנָס אַחֵר זֶה בָּזֶה, וְנִרְאִים אַרְבָּעָה רָאשִׁים לְאַרְבָּעָה רוּחוֹת הָעוֹלָם, וְכֻלָּם גּוּף אֶחָד. וְאֵלֶּה הֵם שֶׁכָּתוּב בָּהֶם (יחזקאל א) כַּאֲשֶׁר יִהְיֶה הָאוֹפַן בְּתוֹךְ הָאוֹפָן. וְכָל אֵלֶּה קְשׁוּרִים זֶה בָּזֶה, כְּמַרְאֵה הַחַיּוֹת הָעֶלְיוֹנוֹת שֶׁלֹּא נִפְרָדוֹת לְעוֹלָמִים. הַחַיָּה הַזּוֹ שֶׁל אַרְבָּעָה גְוָנִים מְרֻקָּמִים אֲחוּזִים אֵלֶּה בְאֵלֶּה לְאַרְבָּעָה רוּחוֹת. מִכָּאן שֶׁכְּשֶׁנּוֹסַעַת הַחַיָּה הַזּוֹ, הִיא נוֹסַעַת לִשְׁנֵי רוּחוֹת."],[6,"","הָרוּחַ הַזּוֹ שֶׁל הַבָּרָק נִכְלֶלֶת בִּשְׁתֵּי רוּחוֹת. רוּחַ זוֹ שֶׁל הַבָּרָק מוֹצִיאָה חַיָּה אַחַת וְכָל אוֹתָם הָאוֹרוֹת. רוּחַ אַחֶרֶת מְאִירָה מִמֶּנָּה, שֶׁנִּקְרֵאת רוּחַ מְלַהֶטֶת,"],[7,"","מְאִירִים מִמֶּנָּה שְׁנֵי אוֹרוֹת שֶׁהֵם אַרְבָּעָה. וְהָאוֹרוֹת הַלָּלוּ מִתְהַפְּכִים בִּגְוָנִים. וְכָאן הוּא (בראשית ג) לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת. אֵלּוּ אוֹתָם מְאוֹרוֹת שֶׁמְּהַפְּכִים שְׁנִינוּת הַחֶרֶב, (ואלה חוקקים) וְאֵלֶּה עוֹמְדִים עַל הַהֵיכָל שֶׁלְּמַטָּה, מִשּׁוּם שֶׁלַּהַט הַחֶרֶב הַזֹּאת עוֹמֶדֶת עַל אוֹתָם שִׁבְעִים אוֹרוֹת שֶׁל בֵּית הַדִּין. מִכָּאן, כָּל אוֹתָם דַּיָּנִים שֶׁדָּנִים דִּין, חֶרֶב תְּלוּיָה עַל רֹאשָׁם מִלְמַעְלָה."],[8,"","לַהַט הַחֶרֶב הַזּוֹ שֶׁל אֵלֶּה הֵם אוֹתָם אוֹרוֹת שֶׁלְּצַד שְׂמֹאל הוֹצִיאוּ חַיָּה אַחַת אַחֶרֶת שֶׁעוֹמֶדֶת עַל אַרְבַּע שֶׁלֹּא עוֹמְדִים בְּקִיּוּמָם, שְׁנַיִם מִיָּמִין וּשְׁנַיִם מִשְּׂמֹאל. כְּשֶׁרוּחַ הַחַיָּה הַזּוֹ נִכְנֶסֶת בְּאֵלֶּה, נוֹצֵץ מֵהֶם שְׁנֵי נִיצוֹצוֹת לוֹהֲטִים, וְיוֹצְאִים מֵהַהֵיכָל הַזֶּה הַחוּצָה וּמִתְהַפְּכִים תָּמִיד. הַנִּיצוֹצוֹת הַלָּלוּ לוֹהֲטִים. לִפְעָמִים נְקֵבוֹת לִפְעָמִים זְכָרִים. לִפְעָמִים רוּחוֹת וְלִפְעָמִים מַלְאָכִים קְדוֹשִׁים."],[9,"","מָה הַטַּעַם? מִשּׁוּם שֶׁכְּשֶׁנִּכְלֶלֶת הַחַיָּה הַזּוֹ בַּחַיָּה הָרִאשׁוֹנָה, מִתּוֹךְ הַחֹזֶק שֶׁנִּכְלָלִים זֶה בָּזֶה יוֹצֵא נִיצוֹץ אֶחָד לוֹהֵט תָּמִיד שֶׁלֹּא דוֹעֵךְ לְעוֹלָמִים, וְשָׁט וְהוֹלֵךְ אַחֲרֵיהֶם שֶׁל אוֹתָם שְׁנֵי נִיצוֹצוֹת."],[10,"","וְעַכְשָׁו הֵם זְכָרִים וְעוֹשִׂים שְׁלִיחוּת בָּעוֹלָם. וְעַד שֶׁלֹּא מְסַיְּמִים, מִתְדַּעֲכִים (אז), וְהַנִּיצוֹץ הַזֶּה מַכֶּה בָהֶם וּמֵאִיר לָהֶם, וּמִתְחַדְּשִׁים כְּמִקֹּדֶם, וְהֵם נְקֵבוֹת, וְהוֹלְכוֹת וּמְשׁוֹטְטוֹת. וְטֶרֶם שֶׁמְּסַיְּמוֹת הֵן דּוֹעֲכוֹת. וְנִיצוֹץ זֶה מַכֶּה בָהֶם וּמֵאִיר לָהֶם וְחוֹזְרִים כְּמִקֹּדֶם, מִשּׁוּם שֶׁאוֹתוֹ נִיצוֹץ כָּלוּל מֵהַכֹּל, כָּלוּל מֵאַרְבָּעָה גְוָנִים, וְלָכֵן הֵם מִתְהַפְּכִים לְכָל הַגְּוָנִים הַלָּלוּ."]]],[["רוּחָא דָא אִתְכְּלִיל בְּרוּחָא אָחֳרָא כִּדְקָאֲמָרָן וְאִתְחַזּוּן תְּרֵין כְּחֲדָא, וְלָא כְּאָחֳרָנִין קַדְמָאִין דְּכַד אִתְכְּלִיל דָּא בְּדָא לָא אִתְחַזֵּי בַּר חָד. וְהָכָא אִתְחַזּוּן תְּרֵין וְקָיְמֵי בַּחֲבִיבוּתָא כְּלִילָן מִכֻּלְהוּ תַּתָּאֵי, וְאַף עַל גַּב דְּאִנּוּן תְּרֵין אִנּוּן חַד. כַּד אִתְפְּשַׁט (נ\"א בר דאתפשטו) רוּחָא בְּרוּחָא וְאִתְחַזּוּן בְּחֲבִיבוּתָא כְּלִילָן מִכֻּלְהוּ תַּתָּאֵי, וְדָּא (ד\"א דא) הוּא רָזָא דִּכְתִיב, (שיר השירים ד׳:ה׳) שְׁנֵי שָׁדַיִךְ כִּשְׁנֵי עָפָרִים תְּאוֹמֵי צְבִיָה הָרוֹעִים בַּשּׁוֹשַׁנִּים.","וְכַד תְּרֵין רוּחִין מִתְפַּשְׁטָן דָּא בְּדָא בְּחֲבִיבוּתָא כְּדֵין אִתְהַדַּר הַאי הֵיכָלָא וְאִקְרֵי הֵיכַל אַהֲבָה הֵיכָלָא דִּרְחִימוּתָא, הֵיכָלָא דָא קָאִים תָּדִיר בְּקִיּוּמֵיהּ, אִתְגְנִיז בְּרָזָא דְרָזִין לְמַאן דְּאִצְטְרִיךְ לְאִתְדַּבְּקָא בֵּיהּ. וְהָכָא כְּתִיב, (שיר השירים ז׳:י״ג) אֶתֵּן אֶת דּוֹדַי לָךְ.","לְבָתַר כַּד נָהֲרִין תְּרֵין רוּחִין דְּאִנּוּן חַד נָפְקֵי כַּמָּה חַיָּילִין לְכַמָּה סִטְרִין אַלְפִין וְרִבְוָון דְּלֵית לוֹן שִׁיעוּרָא, מִנְהוֹן אִקְרוּן דּוּדָאִים. מִנְהוֹן גְּפָנִים. מִנְהוֹן רִמּוֹנִים. עַד דְּמָטוּ כַּמָּה חַיָילִין לְבַר עַד הַהוּא כֹּכָבָא דְאִקְרֵי נֹגַהּ וְכֻלְהוּ בַּחֲבִיבוּ דְּלָא מִתְפָּרְשִׁין לְעָלְמִין, בְּהָכָא כְּתִיב, (שיר השירים ח׳:ז׳) אִם יִתֵּן אִישׁ אֶת כָּל הוֹן בֵּיתוֹ בָּאַהֲבָה בּוֹז יָבוּזוּ לוֹ. הָכָא (ד\"א כתיב) הִשְׁתַחֲוָאָה וּפְרִישׂוּ דְיָדִין לְאִתְדַּבְּקָא בִּרְחִימוּ דְמָארֵיהּ:","הֵיכָלָא שְׁתִיתָאָה הָכָא הוּא רוּחָא דְּאִקְרֵי חוּ\"ט הַשָּׁנִי, רָזָא דִּכְתִיב, (שיר השירים ד׳:ג׳) כְּחוּט הַשָּׁנִי שִׂפְתוֹתַיִךְ, הַאי הֵיכָלָא (היכלא דאקרי) אִקְרֵי הֵיכַּל הָרָצוֹן, הָכָא רוּחָא דְאִיהוּ רַעֲוָא דְּכָל הָנֵי רוּחִין תַּתָּאִין רָהֲטִין אֲבַתְרֵיהּ לְאִתְדַּבְּקָא בֵּיהּ בִּנְשִׁיקָה בִּרְחִימוּתָא.","הַאי רוּחָא אִתְכְּלִיל בְּשִׁית. וְקָיְימָא בְּשִׁית. אִתְכְּלִיל בְּשִׁית דִּלְתַתָּא בַּהֲדֵיהּ. וְקָיְימָא בְּשִׁית עִלָּאִין. וּבְגִין כָךְ הַאי רוּחָא אַפִּיק תְּרֵיסַר נְהוֹרִין כְּלִילָן כֻּלְהוּ מִתַּתָּא וּמִלְּעֵילָא, הָנֵי תְּרֵיסַר נְהוֹרִין אִנּוּן חָדוּן לְסַלְקָא לְעֵילָא וּלְקַבְּלָא כָּל אִנּוּן דִּלְתַתָּא.","הֵיכָלָא דָא דְּאִיהוּ רָצוֹן רַעֲוָא דְּכֹלָּא, מָאן דְּקָשַׁר קִשְׁרִין, וְסָלִיק לוֹן הָכָא, דָּא הוּא דְּאַפִּיק רָצוֹן מֵיְיָ בַּחֲבִיבוּתָא. בְּגוֹ הֵיכָלָא דָּא אִתְכְּנִישׁ משֶׁה בִּרְחִימוּ דְּנָשִׁיק נְשִׁיקֵי רְחִימוּתָא. הַאי הוּא הֵיכָלָא דְּמשֶׁה. רוּחָא דָא רוּחָא דִרְחִימוּתָא, רוּחָא דְיִחוּדָא דְּאַמְשִׁיךְ רְחִימוּ לְכָל סִטְרִין.","וְאִנּוּן (ד\"א אנון) תְּרֵיסַר נְהוֹרִין סָלְקִין וְלָהֲטִין. מִנְּצִיצוּ דִּלְהוֹן נָפְקֵי אַרְבַּע חֵיוָון קַדִּישִׁין רְחִימֵי דְאַהֲבָה, אִלֵּין אִקְרוּן חַיּוֹת גְדוֹלוֹת לְאִתְחַבְּרָא אִנּוּן זוּטֵי לְאִתְכְּלָלָא בְּהוּ, דִּכְתִיב, (תהילים ק״ד:כ״ה) חַיּוֹת קְטַנּוֹת עִם גְּדוֹלוֹת.","אִלֵּין אֲחִידָן דָּא בְּדָא לְד' סִטְרִין, כֶּאֱגוֹזָא דְּמִתְחַבְּרָא לְד' סִטְרִין, וּבְּגִין כָּךְ אִקְרֵי הֵיכָלָא דָא, גִּנַּת אֱגוֹז דִּכְתִיב, (שיר השירים ו׳:י״א) אֶל גִּנַּת אֱגוֹז יָרַדְתִּי, מַאי אֶל גִּנַּת אֱגוֹז, בְּגִינֵיהּ דְּגִנַּת אֱגוֹז יָרַדְתִּי דְּאִיהוּ הֵיכָלָא דִּרְחִימוּ לְאִתְדַּבְּקָא דְּכוּרָא בְּנוּקְבָא.","אִלֵּין אַרְבַּע מִתְפָּרְשָׁן לִתְרֵיסַר, תְּלַת תְּלַת לְכָל סְטַר. כָּל אִנּוּן תַּתָּאֵי כְּלִילָן בְּהוּ. וּבְהוּ קַיָימִין רוּחִין בְּרוּחִין נְהוֹרִין בִּנְהוֹרִין, כֻּלְהוּ אִלֵּין בְּאִלֵּין עַד דְּאִתְעֲבִידוּ חַד. וּכְדֵין הַאי רוּחָא דְּכָלִיל מִכֻּלְהוּ סָלְקָא לְאִתְעַטְּרָא (נ\"א לאתערא) בְּרוּחָא דִּלְעֵילָא הַהוּא דְּאִקְרֵי שָׁמַיִ\"ם וְזַמִּין לֵיהּ לְאִתְחַבְּרָא בַּהֲדֵיהּ, כֵּיוָן דְּאִתְקְשָׁרוּ כֻּלְהוּ דִלְתַתָּא בַּהֲדֵיהּ אָמַר (שיר השירים א׳:ב׳) יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ, וּכְדֵין אִיהוּ חֶדְוָה לְאִתְקַשְּׁרָא רוּחָא בְּרוּחָא וּלְאִשְׁתַּלָּמָא דָא בְּדָא, כְּדֵין אִיהוּ שְׁלִימוּ בְּחִבּוּרָא חָדָא.","כֵּיוָן דְּהַאי רוּחָא אִתְחַבַּר בַּהֲדֵיהּ וְאִשְׁתְּלִים דָּא בְּדָא וְאִתְנְהִירוּ דָּא בְּדָא בְּכָל שְׁלִימוּ כְּדְקָא חָזֵי בְּהַאי רְעוּתָא דְּצַלֵּי בַּר נָשׁ זַכָּאָה דְּסָלִיק כּוֹלָא כְּדְקָא חָזֵי, עַד הַהוּא אֲתַר לְחַבְּרָא רְחִימוּ דָא בְּדָא, כְּדֵין (ד\"א שמיא אתחבר ברוחא דא ברחימו בשלימו באנהרותא מתדבקן דא בדא, כדין) כָּל אִנּוּן הֵיכָלִין וְכָל אִנּוּן רוּחִין דְּאִתְכְּלִילוּ בְּהַאי כָּל חַד וְחַד מֵאִנּוּן רוּחִין וְהֵיכָלִין דְּאִנּוּן בִּכְלָלָא דְשָׁמַיִם כָּל חַד וְחַד נָטִיל הַהוּא הֵיכָלָא וְהַהוּא רוּחָא (באתר) דְּאִתְחַזֵּי לֵיהּ לְאִתְחַבְּרָא בַּהֲדֵיהּ וּלְאִשְׁתַּלָּמָא בַּהֲדֵיהּ כְּדְקָא יָאוּת."],[[0,"רוחא דא אתכליל ברוחא אחרא כדקאמרן, ואתחזון תרין כחדא,","רוח זה התחתון, נכלל ברוח האחר העליון, כמו שאמרנו לעיל (דף מ\"ב אות ס\"ה ע\"ש) ונראים שניהם כאחד, \u0003ולא כאחרנין קדמאין דכד אתכליל דא בדא לא אתחזי בר חד, והכא אתחזון תרין וקיימי בחביבותא כלילן מכלהו תתאי,\u0004 ולא כהאחרים הראשונים, שבעת שנכללו זה בזה לא נראה אלא אחד, (כנ\"ל אות ס\"ה) אבל כאן נראה שנים העומדים באהבה וכלולים מכל היכלות התחתונים. \u0003ואע\"ג דאינון תרין אינון חד, כד אתפשט רוחא ברוחא, ואתחזון בחביבותא כלילן מכלהו תתאי דא הוא רזא דכתיב\u0004 וכו' ואע\"פ שנראים שנים רוחות, הם אחד כשמתפשט רוח ברוח ונראים באהבה כלולים מכל התחתונים. וז\"ס מה שכתוב שני שדיך וגו'. הביאור הוא להלן בדיבור הסמוך."],[1,"וכד תרין רוחין מתפשטן דא בדא בחביבותא, כדין אתהדר האי היכלא ואקרי היכל אהבה:","וכששני הרוחות מתפשטים זה בזה, אז חוזר ההיכל הזה ונעשה להיכל אהבה. \u0003היכלא דרחימותא, היכלא דא קאים תדיר בקיומיה, אתגניז ברזא דרזין למאן דאצטריך לאתדבקא ביה, והכא כתיב\u0004 וכו', היכל האהבה, היכל זה, עומד תמיד בקיומו, ונגנז בסודי סודות, זולת למי שצריך להתדבק בו, וכאן כתוב \u0003אתן את דודי לך.\u0004"],[1,"","ביאור הדברים. כי אלו ב' רוחין ה\"ס עי\"מ דאחור ועי\"מ דפנים, (כנ\"ל דף מ\"ב ד\"ה ולהבין הדברים). וצריכים לכלול אותם זה בזה, מטעם המתבאר במראות הסולם כאן (דף ל\"ט אות יוד) ויש ג' מינים של התכללות. א) שהרוח דמוחין דאחורים נכלל כולו בהרוח דמוחין דפנים עד שלא נודע כי בא אל קרבו (כנ\"ל דף מ\"ב אות ס\"ה) ונמצא שאין כאן רק מוחין דחסדים בלבד, כי הארת החכמה שהיה נמשך בהמוחין דאחורים נכללו בהמוחין דפנים ואינם. ב) הוא שהרוח דמוחין דאחורים נכלל בהרוח דמוחין דפנים ולא נתבטל בו אלא שנראה שם מציאותו, ונראים שם ב' מיני המוחין, אמנם רק מוחין דפנים בלבדם מאירים, ומוחין דאחורים אע\"פ שנמצאים שם לא יוכלו להאיר וז\"ש כאן \u0003והכא אתחזון תרין וכו' ואע\"ג דאינון תרין אינון חד\u0004 כלומר אע\"פ שמציאות הרוח עם המוחין דאחורים נמצאים שם, מ\"מ מבחינת ההארה הם אחד, כי רק הרוח העליון בלבדו הוא המאיר. ג) הוא כשנכללים ב' הרוחות זה בזה, באופן, אשר הרוח העליון כלול ומאיר גם במוחין דאחורים של הרוח התחתון, ורוח התחתון כלול ומאיר גם במוחין דפנים מרוח העליון, כי עתה יש הארות חכמה וחסדים ברוח העליון, וכן ברוח התחתון."],[1,"","וזהו שמביא המקרא \u0003שני שדיך כשני עפרים תאמי צביה הרועים בשושנים,\u0004 בביאור ההתכללות דמין הב'. כי בחינת המלכות בעי\"מ דפנים, שה\"ס מנעולא, נקראת עפר, ובחינת המלכות בעי\"מ דאחורים, שה\"ס מפתחא (עי' לעיל בהקדמת הזהר דף נ\"ט ד\"ה ולא אתרשים) היא נקראת צביה. וזה שיעור הכתוב \u0003שני שדיך,\u0004 היינו ב' הרוחין שבכאן: הרוח דברקא, שהוא בחינת עי\"מ דפנים, והרוח דמלהטא, שהוא בחינת עי\"מ דאחורים הם שניהם \u0003כשני עפרים,\u0004 היינו מחמת התכללות רוח העליון שבו נבחנת המלכות בהשם \u0003עפר,\u0004 בהרוח התחתון, וע\"כ אפילו רוח התחתון נבחן בבחינת עפר, והם שניהם כשני עפרים. וכן נבחנים שניהם בבחינת \u0003תאומי צביה,\u0004 מחמת התפשטות רוח התחתון, שבו נבחנת המלכות בשם \u0003צביה,\u0004 בהרוח העליון, וע\"כ אפילו רוח העליון נבחן בשם צביה. והם שניהם תאומי צביה, באופן, שמעלת ב' הרוחין נראים בכל אחד מהם, מחמת התפשטותם זה בזה, ועכ\"ז מאירים שניחם רק \u0003כרוח אחד,\u0004 דהיינו כבחינת רוח העליון שהיא מוחין דפנים. וע\"כ מסיים הכתוב \u0003הרועים בשושנים,\u0004 שבנין המלכות בסוד מוחין דפנים, נקרא בשם שושנה. לאפוקי שאינם מאירים מבחינת מוחין דאחורים שברוח התחתון. שמבחינה זו נקראת המלכות בשם חבצלת, ולא בשם שושנה."],[2,"לבתר כד נהרין תרין רוחין דאינון חד, נפקי כמה חיילין לכמה סטרין אלפין ורבוון דלית לון שיעורא:","אח\"כ, כשמאירים ב' הרוחות שהם אחד, דהיינו ההתכללות דמין הב' הנ\"ל, יוצאים מהם כמה צבאות לכמה בחינות, לאלפים ולרבבות שאין להם שיעור, \u0003מנהון אקרון דודאים, מנהון גפנים, מנהון רמונים,\u0004 חלק מהם נקראים דודאים, בסו\"ה הדודאים נתנו ריח. ומהם שנקראים גפנים, בסו\"ה אם פרחה הגפן ומהם שנקראים רמונים, בסו\"ה הנצו הרמונים. פירוש, שסובב על מ\"ש לעיל אות קכ\"ג, שבהיכל הזה נאמר \u0003אתן את דודי לך,\u0004 ע\"כ הוא מבאר כאן תשלום המקרא הזה. שכתוב שם נשכימה לכרמים נראה אם פרחה \u0003הגפן,\u0004 פתח הסמדר הנצו \u0003הרמונים\u0004 שם אתן את דודי לך, \u0003הדודאים\u0004 נתנו ריח וגו'. וג' בחינות אלו נמשכים מחג\"ת, שהם מוחין דפנים. דודאים הם בחינת \u0003חסד.\u0004 רמונים הם בחינת \u0003גבורה.\u0004 גפנים הם בחינת \u0003תפארת.\u0004"],[2,"עד דמטו כמה חיילין לבר, עד ההוא ככבא דאקרי נגה:","עד שמגיעים כמה צבאות לחוץ מההיכל, עד אותו הכוכב הנקרא נוגה. שמכוכב הזה מושפע להתחתונים. ועי' לעיל דף מ\"ז ד\"ה תחות."],[2,"וכלהו בחביבו דלא מתפרשין לעלמין,","אחר שנכללו הרוחות זה בזה, הם כולם באהבה, ואינם נפרדים לעולם. בהכא כתיב אם יתן איש את כל הון ביתו באהבה בוז יבוזו לו."],[2,"הכא השתחואה ופרישו דידין לאתדבקא ברחימו דמאריה,","כאן נוהג השתחואה ופישוט ידים כדי להתדבק באהבת רבונו, לעיל בהיכל הנצח נאמר השתחואה בלבד, דהיינו הרכנת הראש עד שיראה איסר מכנגד לבו. ולעיל בהיכל הרביעי נאמר קידה, דהיינו עד שיגע פניו בארץ, שהוא כולל לכל הגוף, ולא הוצרך שם פישוט ידים. והוא מטעם כי שם הוא בחינת ו\"ק דפנים כמ\"ש במראות הסולם כאן, וידים הם בחינת ג\"ר, ורק כאן בהיכל החמישי שהיא בחינת ו\"ק דג\"ר, צריכים לפישוט ידים. ועי' לעיל דף ע\"ד ד\"ה הכא קידה."],[3,"היכלא שתיתאה. הכא הוא רוחא דאקרי חוט השני, רזא דכתיב כחוט וגו':","היכל הששי. כאן הוא הרוח הנקרא חוט השני, בסוד הכתוב כחוט השני שפתותיך וגו' \u0003הכא רוחא, דאיהו רעוא, דכל הני רוחין תתאין רהטין אבתריה,\u0004 כאן הרוח שהוא רצון, אשר כל אלו הרוחות התחתונים רצים אחריו להשיגו. \u0003לאתדבקא ביה בנשיקה ברחימותא,\u0004 להתדבק בו בנשיקה באהבה. והטעם שהרוח נקרא חוט השני, יתבאר להלן בסמוך."],[4,"האי רוחא אתכליל בשית וקיימא בשית, אתכליל בשית דלתתא בהדיה וקיימא בשית עלאין:","רוח הזה נכלל בששה, ועומד בששה, כי נכלל מששה היכלות התחתונים ממנו, ועומד בששה עליונים. כלומר שהעליון כלול בעצמו מכל התחתונים ממנו, וע\"כ יש בו עצמו ששה היכלות מבחינת התכללות. ואלו נבחנים בו להיכלות עליונים. ומלבד זה הרי עולים אליו כל היכלות התחתונים דרך העמודים שבאמצע כל היכל והיכל, כנ\"ל, וע\"כ יש בו ששה היכלות מבחינת מה שמקבל בתוכו את היכלות התחתונים ונכלל מהם, ואלו נבחנים בו לששה היכלות תחתונים. \u0003ובגין כך האי רוחא אפיק תריסר נהורין, כלילן כלהו מתתא ומלעילא.\u0004 ומשום זה הוציא רוח הזה י\"ב אורות, שכל אחד ואחד כלול מלמטה ומלמעלה."],[4,"הני תריסר נהורין, אינון חדון לסלקא לעילא, ולקבלא כל אינון דלתתא:","י\"ב אורות אלו, הם שמחים כולם לעלות למעלה, וכן שמחים כולם לקבל כל אלו שהם למטה. פירוש כי אלו ששה היכלות, אע\"פ שהם ששה מ\"מ נבחנים לעשר ספירות, כי היכל התחתון כולל שתים, יסוד ומלכות, והיכל העליון כולל שלש, כח\"ב, וע\"כ הם עשר. והיכל השביעי ה\"ס ע\"ס בפ\"ע שה\"ס קדש קדשים כמ\"ש להלן. וז\"ש \u0003אתכליל בשית דלתתא בהדיה, וקיימא בשית עלאין\u0004 שלכאורה קשה הרי לא יש למטה ממנו רק חמשה היכלות ולא ששה, ובהאמור מובן, שהכונה הוא, שהוא לבדו כולל ג\"ר כח\"ב, ותחתיו נבחנים לחג\"ת נה\"י שהם ששה. וזה שמביא הכתוב \u0003כחוט השני שפתותיך,\u0004 להורות שהרוח שבכאן היא בחינת ראש, כי השפתים הם בראש, ונקרא \u0003חוט השני,\u0004 שהוא לשון משנה, על שם המלכות דראש, שהם השפתים, להיותה מתוקנת במשנה, דהיינו בב' המלכיות הנק' מנעולא ומפתחא, כנוהג בג\"ר, משא\"כ בו\"ק אין מגולה שם רק מלכות אחת שה\"ס מפתחא בלבדה והמנעולא טמיר ונעלם שם. (כנ\"ל בהקדמת הזהר דף נ\"ט ד\"ה ולא אתרשים עש\"ה) ולפיכך הזווג שבכאן הוא להמשכת אוירא דכיא בסוד אתדבקותא רוחא ברוחא, שה\"ס ד' רוחין דאהבה, כמ\"ש בזהר תרומה אות שע\"ב ע\"ש. שה\"ס \u0003אור הרוח\u0004 של הג\"ר העליונים, דהיינו ו\"ק דג\"ר, כי הג\"ר דג\"ר אינם מתגלים בהעולמות. וז\"ש (בזהר בהיכלות פ' פקודי דף רט\"ז בחילופי גירסאות) \u0003האי היכלא שתיתאה באינון נשיקין, לאתדבקא רוחא ברוחא, כד\"א ישקני מנשיקות פיהו, וכל נשיקה איהו יעקב, דאיהו רוח,\u0004 וכו', הנשיקין שבהיכל הששי הזה, הם לזווג רוח ברוח, כמ\"ש ישקני מנשיקות פיהו, וכל נשיקה היא בחינת יעקב, שהוא בחינת רוח וכו'. שפירושו ו\"ק, דהיינו אור דחסדים, אלא שהוא ו\"ק עליונים דג\"ר עליונים, והוא כל בחינת הג\"ר המאירים בהעולמות."],[4,"","ולפיכך מטרם שהתחתונים נשלמו במוחין דהארת חכמה מסוד המוחין דאחורים, וכן מהיכל החמישי, לא יוכלו לקבל מהזווג דנשיקין שבכאן, כי הגם שהיא אור דחסדים אמנם הוא ו\"ק דג\"ר העליונים, הנבחן לג\"ר ממש, ומטרם שהתחתונים מקבלים הארת החכמה הם בחינת ו\"ק בלי ראש כנודע. ונמצא שהיכל הששי הוא בחינה בפני עצמו, דהיינו ו\"ק דג\"ר מבחינת חסדים, וכנגדו ההיכלות התחתונים ממנו הם בחינה בפני עצמו דהיינו ו\"ק דג\"ר מבחינת המוחין דהארת חכמה."],[4,"","וזה אמרו, \u0003האי רוחא אתכליל בשית וקיימא בשית\u0004 וכו', רוח הזה נכלל בששה, חג\"ת נה\"י, דהיינו ו\"ק דג\"ר, ע\"י ההיכלות התחתונים שעלו אליו, ועומד בפני עצמו ג\"כ בששה חג\"ת נה\"י דהיינו ו\"ק דג\"ר, וכו'. וההפרש ביניהם רב מאד כי חג\"ת נה\"י של עצמו הם בחינת חסדים, דהיינו אוירא דכיא כנ\"ל, אבל חג\"ת נה\"י של התחתונים הם בהארת החכמה, כנ\"ל. וז\"ש \u0003כלילן כלהו מתתא ומלעילא,\u0004 שהי\"ב אורות נכללו כולם זח בזה, מלמטה ומלמעלה, כלומר, החג\"ת נה\"י של מעלה שהם אוירא דכיא, נכללו מהחג\"ת נה\"י של מטה, שהם בהארת חכמה, וכן החג\"ת נה\"י של מטה, שהם הארת חכמה, נכללו מהחג\"ת נה\"י של מעלה שהם אוירא דכיא, חסדים. \u0003הני תריסר נהורין, אנון חדון לסלקא לעילא,\u0004 אלו י\"ב האורות מהתכללות של מעלה בחסדים, שמחים בעליתם למעלה בהתכללותם בהחסדים. \u0003ולקבלא כל אינון דלתתא,\u0004 וכן הם שמחים לקבל ההתכללות של מטה, דהיינו, המוחין דהארת החכמה."],[5,"היכלא דא דאיהו רצון, רעוא דכלא, מאן דקשר קשרין וסליק לון הכא, דא הוא דאפיק רצון מה' בחביבותא:","היכל הזה, שהיא היכל הרצון, להיותו רצון של הכל, מי שקושר קשרים, דהיינו שמייחד יחודים, ומעלה את היכלות התחתונים אל ההיכל הזה, זה הוא אשר יפק רצון מה' באהבה. \u0003בגו היכלא דא אתכניש משה ברחימו, דנשק נשיקי רחימותא,\u0004 בתוך היכל זה נאסף משה אל עמו באהבה, שנשק נשיקי אהבה, שז\"ס מ\"ש וימת משה על פי ה'. שה\"ס מיתת נשיקה כמ\"ש חז\"ל. \u0003האי הוא היכלא דמשה,\u0004 זה הוא ההיכל של משה."],[5,"","ולא יקשה לך מ\"ש בזהר (בהיכלות פקודי דף רט\"ז בחילופי גירסאות ) שזה ההיכל הוא של יעקב. הענין הוא, כי היכלות דפקודי מדברים מן היכלות דז\"א דבריאה, והיכלות שבכאן מדברים מהיכלות דאו\"א דבריאה, והיכלות דאו\"א נבחנים לפנימיות, והיכלות דז\"א נבחנים לחיצוניות אליהם, ונודע, שיעקב ומשה, שניהם בחי' ת\"ת, שהוא אור הרוח, אלא יעקב הוא מלבר, דהיינו בחינת חיצוניות של הת\"ת ומשה הוא מלגו, דהיינו בחינת פנימיות של הת\"ת. ולפיכך כאן בהיכלות דאו\"א, שייך היכל הששי למשה, שהוא פנימיות ת\"ת, שהוא סוד הדעת. ושם בהיכלות דז\"א, שהם חיצוניות לאו\"א, שייך היכל הששי ליעקב, שהוא חיצוניות הת\"ת."],[5,"רוחא דא רוחא דרחימותא, רוחא דיחודא, דאמשיך רחימו לכל סטרין","רוח זה הוא רוח האהבה, רוח היחוד, הממשיך אהבה לכל חבחינות, \u0003ואנון תריסר נהורין סלקין ולהטין,\u0004 ואלו י\"ב האורות שבהרוח, עולים ולוהטים, כלומר, שמבחינת התכללותם בהתכללות של מעלה דאוירא דכיא, הם עולים. ומבחינת התכללותם בהתכללות של מטה, של הארת החכמה, הנמשך מקו שמאל, הם לוהטים."],[6,"מנציצו דלהון נפקי ארבע חיוון קדישין רחימי דאהבה, אלין אקרון חיות גדולות:","מהתנוצצות שלהם יוצאות ארבע חיות קדושות חביבי האהבה, אלו נקראות חיות גדולות, \u0003לאתחברא אינון זוטי לאתכללא בהו דכתיב וכו',\u0004 להתחבר עם חיות הקטנות, ולהכלל בהם, שכתוב, חיות קטנות עם גדולות, פירוש, שאלו י\"ב נהורין שה\"ס שהרוח \u0003אתכליל משית דלתתא, וקיימא בשית עלאין.\u0004 שהם חג\"ת נה\"י של עצמו, שהעליון כלול מכל התחתונים, וחג\"ת נה\"י של היכלות התחתונים העולים אליו, הנה הם הוציאו דוגמתם בבחינת החיות, והם ג\"כ חיות דבחינת עצמו, וחיות דהיכלות העולים אליו. וכיון שכולל כל התחתונים להיותו העליון מכולם, לכן יש בו ד' חיות מבחינת עצמו, והם נבחנים לחיות גדולות, והוא במשונה מהיכלות התחתונים שאין בכל אחד רק חיה אחת. וכן יש בו י\"ב מצד היכלות התחתונים העולים אליו, כמ\"ש להלן. באופן ש\u0003שית נהורין\u0004 של עצמו, הוציאו ד' חיות גדולות, \u0003ושית נהורין דלתתא\u0004 הוציאו י\"ב חיות קטנות. וז\"ש \u0003לאתחברא אנון זוטי לאתכללא בהו,\u0004 שיתחברו החיות גדולות עם י\"ב הקטנות הכלולים בהם."],[7,"אלין אחידן דא בדא לד' סטרין כאגוזא דמתחברא לד' סטרין:","אלו החיות גדולות נכללות זו בזו לד' צדדים, כמו האגוז שד' חלקים מתחברים בהפרי שבו, דהיינו שכל אחת מהד' כוללת בתוכה כל הד'. והוא מטעם היותו מבחינת מחזה ולמעלה, ששם יש פני אדם, ושם מקום הזווג. אבל בבחינת מחזה ולמטה שאין שם רק ג' צדדים, שהם חו\"ב ות\"ת, וחסר שם פני אדם, אין שם מקום זווג, \u0003ובג\"כ אקרי היכלא דא גנת אגוז,\u0004 ומשום זה נקרא היכל זה בשם גנת אגוז, דהיינו על שם ד' סטרין שבכל חיה כמו האגוז, שזה יורה על מקום הזווג. \u0003דכתיב אל גנת אגוז ירדתי, מאי אל גנת אגוז, בגיניה דגנת אגוז ירדתי\u0004 כמ\"ש אל גנת אגוז ירדתי, ומהו אל גנת אגוז שאומר הכתוב, הכונה הוא, שבשביל גנת אגוז ירדתי, \u0003דאיהו היכלא דרחימו לאתדבקא דכורא בנוקבא,\u0004 משום שהוא היכל האהבה לזווג ז\"א בנוקביה."],[7,"","ולא יקשה לך הרי בכל היכל והיכל מהתחתונים יש ד' סטרין מחזה ולמעלה של החיה אשר שם, ולמה דוקא כאן מקום הזווג ולא בהתחתונים. והענין הוא, כי כל היכלות כלולים זה מזה, וע\"כ יש ד' סטרין בכל היכל והיכל, אמנם אינם מבחינת עצתם אלא מבחינת התכללות של היכל זה בתוכם, וע\"כ אין מקום זווג רק בהיכל זה, משום שד' הסטרין שבכאן הם מבחינת עצמו,"],[8,"אלין ארבע מתפרשן לתריסר, תלת תלת לכל סטר, כל אינון תתאי כלילן בהו:","אלו ארבע חיות הגדולות מתחלקים לי\"ב ג' ג' לכל צד שבד' צדדים, כל היכלות התחתונים כלולים בהם. דהיינו כמ\"ש לעיל, שמתוך שיש בהי\"ב נהורין ששה של בחינת היכל בעצמו, וששה מעליות היכלות התחתונים, כן הוציאו דוגמתן בהחיות, שששה נהורין דהיכל עצמו, הוציאו ד' חיות גדולות, שהם חו\"ב תו\"מ של עצמם, שכל אחת מהם כלול מד' סטרין והם ששה עשר. וששה נהורין דהיכלות תחתונים הוציאו י\"ב חיות הקטנות שמחזה ולמטה, שכל אחת מהד' אינה כלולה רק מג'. וז\"ש \u0003כל אינון תתאי כלילן בהו,\u0004 שאלו י\"ב הם מהתכללות היכלות התחתונים שעלו להיכל זה. וכבר נתבאר לעיל (דף מ\"ו ד\"ה ביאור) שמקום גילוי הארת החכמה, אינו בבחינת ד' סטרין, שכל אחד כלול מד', שהם בחינת מחזה ולמעלה אלא בד' סטרין שכל אחד כלול מג' שהם בחינת מחזה ולמטה."],[8,"ובהו קיימין רוחין ברוחין נהורין בנהורין, כלהו אלין באלין עד דאתעבידו חד.","ובאלו י\"ב חיות קטנות, עומדים רוחות ברוחות ואורות באורות, וכולם הם אלו באלו עד שנעשו כולם אחד. כי אלו י\"ב הם נמשכים מששה אורות של היכלות התחתונים שעלו לכאן, כנ\"ל בדיבור הסמוך, וע\"כ עומדים שם כל הרוחות וכל האורות של היכלות התחתונים, ובהם מתיחדים כולם זה בזה עד שנעשו אחד."],[8,"וכדין האי רוחא דכליל מכלהו סלקא לאתעטרא ברוחא דלעילא ההוא דאקרי שמים.","ואז, אחר שכל התחתונים נעשו אחד, הרוח הזה שכלול מכולם, כי הוא כלול מי\"ב נהורין, אשר י\"ב נהורין כלולים מד' החיות הגדולות, ומי\"ב הקטנות, וי\"ב הקטנות כלולים מכל התחתונים, כמבואר, עולה הרוח עם כולם להתעטר באותו רוח העליון הנקרא שמים, שה\"ס ז\"א דאצילות, כי ז\"א ה\"ס רוח דאצילות, והוא נקרא שמים, כנודע. \u0003וזמין ליה לאתחברא בהדיה.\u0004 ומזמין אותו להתחבר עמו."],[8,"כיון דאתקשרו כלהו דלתתא בהדיה, אמר ישקני מנשיקות פיהו:","כיון שנקשרו בו כל אלו שלמטה, אמר ישקני מנשיקות פיהו. פירוש, כי נתבאר לעיל (דף פ\"ב ד\"ה הני) שמזווג הגדול דנשיקין נמשך אוירא דכיא שה\"ס אור דחסדים, ועדיין אינם ראוים לתחתונים, הצריכים להארת חכמה, ע\"כ האורות שבהיכלות התחתונים שבהם הארת החכמה, צריכים להכלל בזווג הזה דנשיקין, ואז הם נשלמים הן מחסדים והן מהארת החכמה, וז\"ש \u0003כיון דאתקשרו כלהו דלתתא בהדיה,\u0004 שבזה נכלל הרוח שבכאן גם מהארת חכמה, אז אמר הרוח ישקני מנשיקות פיהו כי טובים דודיך מיין. כלומר, אחר שכבר טובים דודיך מיין, שה\"ס המוחין דהארת חכמה הנקראים יין המשמח אלקים ואנשים, המקובלים מכל התחתונים, הרי הגיע העת לזווג דנשיקין, ואומר ישקני מנשיקות פיהו, כי עתה יהיה זווג מושלם בין מחסדים ובין מחכמה. וז\"ש \u0003וכדין איהו חדוה לאתקשרא רוחא ברוחא, ולאשתלמא דא בדא.\u0004 ואז הוא בשמחה, להזדווג רוח ברוח דהיינו רוח הרצון הכלול מכל התחתונים, עם הרוח דאצילות שה\"ס ז\"א הנק' שמים, שה\"ס זווג דנשיקין להמשכת חסדים דאוירא דכיא ולהשתלם בהארת חכמה זה מזה, שהוא מבחינת היכלות התחתונים הכלולים בהרוח שבכאן, שה\"ס כי טובים דודיך מיין. \u0003כדין איהו שלימו בחבורא חדא,\u0004 אז הוא שלם, בחיבור אחד מכולם. כלומר,מכח שנתחברו בו כל היכלות התחתונים, ע\"כ נעשה שלם הן בהחסדים הן בחכמה. כמבואר."],[9,"כיון דהאי רוחא אתחבר בהדיה ואשתלים דא בדא, ואתנהירו דא בדא בכל שלימו כדקא חזי:","כיון שרוח הזה שבכאן נתחבר עם הרוח דאצילות הנקרא שמים, ונשלם זה מזה בהארת חכמה, והאירו זה מזה בהארת אוירא דכיא, חסדים, בכל השלימות כראוי \u0003בהאי רעותא דצלי בר נש זכאה דסליק כולא כדקא חזי עד ההוא אתר, לחברא רחימו דא בדא.\u0004 שכל זה נעשה בכח הרצון של אדם צדיק שהתפלל, והעלה כל היכלות שבבריאה עד מקום ההוא, שבעולם האצילות לזווג דנשיקין, לחברם באהבה זה בזה. \u0003כדין כל אינון היכלין וכל אינון רוחין דאתכלילו בהאי, כל חד וחד מאינון רוחין והיכלין דאנון בכללא דשמים,\u0004 אז כל אלו הרוחות וכל אלו ההיכלות שנכללו ברוח הזה הנק' רצון, וכל אחד ואחד מאלו הרוחות והיכלות שהם בכלל ז\"א דאצילות הנקרא שמים. \u0003כל חד וחד נטיל ההוא היכלא וההוא רוחא דאתחזי ליה לאתחברא בהדיה, ולאשתלמא בהדיה כדקא יאות,\u0004 הנה כל אחד ואחד מהם לוקח אותו ההיכל ואותו הרוח הראוי לו, להתחבר עמו ולהשתלם ממנו כראוי. פירוש, כנגד כל אלו הרוחות והאורות הנ\"ל המפורטים בששה היכלות דאו\"א דבריאה, יש ג\"כ כנגדם רוחות ואורות בששה היכלות דז\"א דאצילות, וכל בחינה ובחינה שבז\"א דאצילות מתחבר עם הבחינה שכנגדה בששה היכלות דבריאה שעלו אליו, ואז הם נשלמים זה מזה כראוי, כמו שמבאר הזהר להלן. \u0003בגין דההוא רוחא שתיתאה דאקרי רצון סליק לון לגבייהו בההוא יחודא,\u0004 משום שהרוח הזה שבכאן הנקרא רצון העלה ביחוד הזה כל הרוחות והאורות שבהיכלות דבריאה אל הרוחות והאורות דז\"א דאצילות."]],[[0,"","רוּחַ זֶה נִכְלָל בְּרוּחַ אַחֵר, כְּמוֹ שֶׁאָמַרְנוּ, וְנִרְאִים שְׁנַיִם כְּאֶחָד, וְלֹא כָּאֲחֵרִים הָרִאשׁוֹנִים שֶׁכְּשֶׁנִּכְלָלִים זֶה בָּזֶה לֹא נִרְאִים פְּרָט לְאֶחָד. וְכָאן נִרְאִים שְׁנַיִם, וְעוֹמְדִים בַּחֲבִיבוּת כְּלוּלִים מִכָּל הַתַּחְתּוֹנִים. וְאַף עַל גַּב שֶׁהֵם שְׁנַיִם, הֵם אֶחָד. כַּאֲשֶׁר מִתְפַּשֵּׁט (פרט כשהתפשטו) רוּחַ בְּרוּחַ וְנִרְאִים בַּחֲבִיבוּת כְּלוּלִים מִכָּל הַתַּחְתּוֹנִים, וְזֶהוּ (וזה) סוֹד שֶׁכָּתוּב (שיר ד) שְׁנֵי שָׁדַיִךְ כִּשְׁנֵי עֳפָרִים תְּאוֹמֵי צְבִיָּה הָרֹעִים בַּשּׁוֹשַׁנִּים."],[1,"","וּכְשֶׁשְּׁנֵי רוּחוֹת מִתְפַּשְּׁטִים זֶה בָּזֶה בַּחֲבִיבוּת, אָז חוֹזֵר הֵיכָל זֶה וְנִקְרָא הֵיכַל אַהֲבָה, הֵיכַל הָאַהֲבָה. הֵיכָל זֶה עוֹמֵד תָּמִיד בְּקִיּוּמוֹ, וְנִגְנַז בְּסוֹד הַסּוֹדוֹת לְמִי שֶׁצָּרִיךְ לְהִתְדַּבֵּק בּוֹ. וְכָאן כָּתוּב (שם ז) אֶתֵּן אֶת דֹּדַי לָךְ."],[2,"","אַחַר כָּךְ, כַּאֲשֶׁר מְאִירִים שְׁנֵי רוּחוֹת שֶׁהֵם אֶחָד, יוֹצְאִים כַּמָּה צְבָאוֹת לְכַמָּה רוּחוֹת, אֲלָפִים וּרְבָבוֹת שֶׁאֵין לָהֶם שִׁעוּר. מֵהֶם נִקְרָאִים דּוּדָאִים, מֵהֶם גְּפָנִים, מֵהֶם רִמּוֹנִים, עַד שֶׁמַּגִּיעִים כַּמָּה צְבָאוֹת הַחוּצָה עַד אוֹתוֹ כּוֹכָב שֶׁנִּקְרָא נֹגַהּ. וְכֻלָּם בַּחֲבִיבוּת שֶׁלֹּא נִפְרָדִים לְעוֹלָמִים. וְכָאן כָּתוּב (שם ח) אִם יִתֵּן אִישׁ אֶת כָּל הוֹן בֵּיתוֹ בָּאַהֲבָה בּוֹז יָבוּזוּ לוֹ. כָּאן (כתוב) הִשְׁתַּחֲוָאָה וּפְרִישַׂת יָדַיִם לְהִתְדַּבֵּק בְּאַהֲבַת רִבּוֹנוֹ."],[3,"","הֵיכָל שִׁשִּׁי. כָּאן הוּא רוּחַ שֶׁנִּקְרָא חוּ\"ט הַשָּׁנִי, סוֹד הַכָּתוּב (שם ד) כְּחוּט הַשָּׁנִי שִׂפְתוֹתַיִךְ. הַהֵיכָל הַזֶּה (היכל שנקרא) נִקְרָא הֵיכַל הָרָצוֹן. כָּאן רוּחַ שֶׁהוּא רָצוֹן שֶׁכָּל הָרוּחוֹת הַתַּחְתּוֹנוֹת הַלָּלוּ רָצִים אַחֲרֶיהָ לְהִדָּבֵק בָּהּ בִּנְשִׁיקָה בְּאַהֲבָה."],[4,"","רוּחַ זֶה נִכְלָל בְּשֵׁשׁ, וְעוֹמֵד בְּשֵׁשׁ. נִכְלָל בְּשֵׁשׁ שֶׁלְּמַטָּה יַחַד עִמּוֹ, וְעוֹמֵד בְּשֵׁשׁ עֶלְיוֹנִים. וְלָכֵן רוּחַ זֶה מוֹצִיא שְׁנֵים עָשָׂר אוֹרוֹת כְּלוּלִים כֻּלָּם מִלְּמַטָּה וּמִלְמַעְלָה. שְׁנֵים עָשָׂר הָאוֹרוֹת הַלָּלוּ הֵם שְׂמֵחִים לַעֲלוֹת לְמַעְלָה וּלְקַבֵּל כָּל אֵלּוּ שֶׁלְּמַטָּה."],[5,"","הֵיכָל זֶה שֶׁהוּא רָצוֹן, רְצוֹן הַכֹּל, מִי שֶׁקּוֹשֵׁר קְשָׁרִים וּמַעֲלֶה אוֹתָם לְכָאן, זֶהוּ שֶׁמֵּפִיק רָצוֹן מֵה' בַּחֲבִיבוּת. בְּתוֹךְ הַהֵיכָל הַזֶּה נֶאֱסַף מֹשֶׁה בְּאַהֲבָה, שֶׁנּוֹשֵׁק נְשִׁיקוֹת אַהֲבָה. זֶהוּ הַהֵיכָל שֶׁל מֹשֶׁה. רוּחַ זֶה רוּחַ הָאַהֲבָה. הָרוּחַ שֶׁל הַיִּחוּד שֶׁמַּמְשִׁיךְ אַהֲבָה לְכָל הַצְּדָדִים."],[6,"","וְאוֹתָם שְׁנֵים עָשָׂר אוֹרוֹת עוֹלִים וְלוֹהֲטִים. מֵהַנִּצְנוּץ שֶׁלָּהֶם יוֹצְאוֹת אַרְבַּע חַיּוֹת קְדוֹשׁוֹת אוֹהֲבֵי הָאַהֲבָה. אֵלֶּה נִקְרָאִים חַיּוֹת גְּדוֹלוֹת לְהִתְחַבֵּר אוֹתָם קְטַנּוֹת לְהִכָּלֵל בָּהֶם, שֶׁכָּתוּב (תהלים קד) חַיּוֹת קְטַנּוֹת עִם גְּדוֹלוֹת."],[7,"","אֵלּוּ אֲחוּזוֹת זוֹ בָּזוֹ לְאַרְבָּעָה צְדָדִים, כְּמוֹ אֱגוֹז שֶׁמְּחֻבָּר לְאַרְבָּעָה צְדָדִים, וְלָכֵן נִקְרָא הֵיכָל זֶה גִּנַּת אֱגוֹז, שֶׁכָּתוּב (שיר ו) אֶל גִּנַּת אֱגוֹז יָרַדְתִּי. מַה זֶּה אֶל גִּנַּת אֱגוֹז? מִשּׁוּם גִּנַּת אֱגוֹז יָרַדְתִּי, שֶׁהוּא הֵיכַל הָאַהֲבָה לְהִתְדַּבֵּק זָכָר בִּנְקֵבָה."],[8,"","אֵלֶּה הָאַרְבַּע נִפְרָדִים לִשְׁנֵים עָשָׂר, שָׁלֹשׁ שָׁלֹשׁ לְכָל צַד. כָּל אוֹתָם תַּחְתּוֹנִים כְּלוּלִים בָּהֶם. וּבָהֶם קַיָּמִים רוּחוֹת עִם רוּחוֹת, אוֹרוֹת עִם אוֹרוֹת. כֻּלָּם אֵלֶּה עִם אֵלֶּה עַד שֶׁנַּעֲשִׂים אֶחָד. וְאָז רוּחַ זֶה שֶׁכָּלוּל מִכֻּלָּם עוֹלֶה לְהִתְעַטֵּר (להתעורר) בָּרוּחַ שֶׁל מַעְלָה, אוֹתוֹ שֶׁנִּקְרָא שָׁמַיִם, וּמַזְמִין אוֹתוֹ לְהִתְחַבֵּר עִמּוֹ. כֵּיוָן שֶׁנִּקְשְׁרוּ כֻלָּם שֶׁלְּמַטָּה יַחַד עִמּוֹ, אָמַר (שם א) יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ. וְאָז הַחֶדְוָה הִיא לְהִתְקַשֵּׁר רוּחַ בְּרוּחַ וּלְהִשְׁתַּלֵּם זֶה בָּזֶה, וְאָז הִיא הַשְּׁלֵמוּת בְּחִבּוּר אֶחָד."],[9,"","כֵּיוָן שֶׁרוּחַ זֶה מִתְחַבֵּר עִמּוֹ וְנִשְׁלְמוּ זֶה בָּזֶה וּמְאִירִים זֶה בָּזֶה בְּכָל הַשְּׁלֵמוּת כָּרָאוּי בְּרָצוֹן זֶה שֶׁמִּתְפַּלֵּל בֶּן אָדָם צַדִּיק שֶׁמַּעֲלֶה הַכֹּל כָּרָאוּי עַד אוֹתוֹ מָקוֹם לְחַבֵּר אַהֲבָה זֶה בָּזֶה, אָז (שמים מתחבר ברוח זה באהבה בשלמות בהארה מתדבקים זה בזה, ואז) כָּל אוֹתָם הֵיכָלוֹת וְכָל אוֹתָם רוּחוֹת שֶׁנִּכְלְלוּ בָזֶה, כָּל אֶחָד וְאֶחָד מֵאוֹתָם רוּחוֹת וְהֵיכָלוֹת שֶׁהֵם בִּכְלָל שֶׁל שָׁמַיִם, כָּל אֶחָד וְאֶחָד נוֹטֵל אוֹתוֹ הֵיכָל וְאוֹתוֹ רוּחַ שֶׁרָאוּי לוֹ לְהִתְחַבֵּר עִמּוֹ וּלְהִשְׁתַּלֵּם עִמּוֹ כָּרָאוּי."]]],[["(ד\"א בגין דההוא רוחא שתיתאה דאקרי שמיא רוחא קדישא לעילא נטיל היכלא דא רוחא דא דאקרי רצו\"ן סליק לון לגבייהו בההוא יחודא. והכי אתחברן רצון לאתנשקא) (כן צ\"ל הרש\"ב) (נ\"א בגין דההוא רוחא שתיתאה דאקרי רצון סליק לון לגבייהו בההוא יחודא והכי אתחברן שמים דאיהי רוחא קדישא לעילא נטיל היכלא דא רוחא דא דאקרי רצון לאתנשקא) דָּא בְּדָא. לְאִתְחַבְּרָא דָא בְּדָא לְאִשְׁתַּלָּמָא דָּא בְּדָא. וְרָזָא דָא (בראשית כ״ט:י״א) וַיִּשַּׁק יַעֲקֹב לְרָחֵל וְגו'.","אַבְרָהָם דְּאִיהוּ יְמִינָא לְעֵילָא נָטִיל (ד\"א ל\"ג היכלא דקאמרן) (היכל אהבה) רוּחָא דְאִקְרֵי אַהֲבָ\"ה לְאִתְקַשְּׁרָא דָּא בְּדָא לְאִתְחַבְּרָא דָא בְּדָא לְמֶהוֵי חַד וְסִימָנָיךְ (בראשית י״ב:י״א) הִנֵּה נָא יָדַעְתִּי כִּי אִשָּׁה יְפַת מַרְאֶה אָתּ. וְשַׁפִּירוּ דְּאִתְּתָא בְּאִנּוּן שָׁדַיִם.","יִצְחָק דְּאִיהוּ שְׂמָאלָא נָטִיל הַהוּא הֵיכָלָא (פקודי רנ\"ו א דבי דינא דכל דינין מתערין מתמן רוחא דאקרי זכותא לאתחברא דא בדא ולאשתלמא דא בדא למהוי כלא חד כדקא יאות. שאר נביאים נטלין תרין היכלין (ד\"א דלתתא)), תְּרִין רוּחִין נוֹגַ\"הּ וְזֹהַ\"ר, בְּרָזָא דִכְתִיב, (שיר השירים ז׳:ב׳) חֲמוּקֵי יְרֵכַיִךְ וְגו' לְאִתְקַשְּׁרָא אִלֵּין בְּאִלֵּין לְמֶהֱוֵי חָד.","יוֹסֵף הַצַּדִּיק עַמּוּדָא דְעָלְמָא (פקודי רנח א) נָטִיל הֵיכָלָא דְסַפִּיר רוּחָא דְאִקְרֵי לִבְנַת הַסַּפִּיר, וְאַף עַל גַּב דִּכְתִיב, (שמות כ״ד:י׳) וְתַחַת רַגְלָיו, בְּגִין יְקָרָא דְמַלְכָּא, וְהָכִי הוּא וַדַּאי. וּלְבָתַר עַמּוּדָא דָא נָטִיל יַתִּיר דְּאִיהוּ רָזָא דְרָזִין בְּאֲתַר דְּהֵיכָלָא שְׁבִיעָאָה. עַד הָכָא מִתְחַבְּרָן דַּרְגִּין וּמִתְחַבְּרָן דָּא בְּדָא לְאִשְׁתַּלָּמָא דָּא עִם דָּא לְמֶהֱוֵי כֻּלְהוּ חַד. כֹּלָּא כְּדְקָא חָזֵי. וּכְדֵין (מלכים א י״ח:ל״ט) יְיָ הוּא הָאֱלהִים וְגו'. זַכָּאָה חוּלָקֵיהּ בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאֲתֵי מָאן דְּיָדַע לְקָשְׁרָא לוֹן וּלְאִתְדַּבְּקָא בְּמָארֵיהּ.","הָכָּא הַכְּרָעָה (ד\"א ל\"ג בהכרעה הכא ומוסיף הווי\"ן) וְהִשְׁתַחֲוָאָה, וְקִידָה, וּפְרִישׂוּ דְּכַּפִּין, וּנְפִילָה דְאַפִּין לְאַמְשָׁכָא רְעוּתָא דְּרוּחָא עִלָּאָה נִשְׁמָתָא דְּכָל נִשְׁמָתִין דְּאִיהוּ תַּלְיָא לְעֵילָא עַד אֵין סוֹף. (ד\"א ל\"ג סוף) דְּמִנֵּיהּ נָפְקֵי נְהִירוּ וּבִרְכָאן לְאַשְׁלָמָא כֹּלָּא מִלְּעֵילָא כְּדְקָא יָאוּת. וּלְמֶהֱוֵי כֹּלָּא בִּשְׁלִימוּ מִתַּתָּא וּמִלְּעֵילָא וְכָל אַנְפִּין נְהִירִין בְּכָל סִטְרִין כְּדְקָא יָאוּת. כְּדֵין כָּל גִּזְרֵי דִינִין מִתְבַּטְלִין וְכָל רְעוּתָא אִתְעֲבִיד לְעֵילָא וְתַתָּא. וְעַל דָּא כְּתִיב, (ישעיהו מ״ט:ג׳) וַיֹּאמֶר לִי עַבְדִּי אַתָּה יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאֵר. וּכְתִיב, (תהילים קמ״ד:ט״ו) אַשְׁרֵי הָעָם שֶׁכָּכָה לוֹ אַשְׁרֵי הָעָם שֶׁיְיָ אֱלהָיו:","הֵיכָּלָא שְׁבִיעָאָה הֵיכָּלָא דָא לָאו בֵּיהּ דִיוּקְנָא מַמָּשׁ, כֹּלָּא אִיהוּ בִּסְתִימוּ וְגו' (ד\"א גו) רָזָא דְרָזִין, פָּרוּכְתָּא דִפְרִיסָא (ד\"א פריסא) קָיְימִין כֻּלְהוּ הֵיכָלִין דְּלָא לְאִתְחַזָּאָה תְּרִין כְּרוּבִים (ד\"א ל\"ג דא מן דא קיימין), לְגוֹ מִן דָּא קָיְימָא כַּפּוּרְתָּא דִּיוּקְנָא דְקֹדֶשׁ קוּדְשִׁין, בְּגִין כָּךְ הֵיכָלָא דָא אִקְרֵי קֹדֶשׁ הַקֳּדָשִׁים. הַאי קֹדֶשׁ הַקֳּדָשִׁים אֲתַר מִתְתַּקְנָא לְהַהוּא נִשְׁמָתָא עִלָּאָה כְּלָלָא דְּכֹלָּא עָלְמָא דְּאֲתֵי לְגַבֵּי הַאי (נ\"א עלמא) עִלָּאֵי.","דְּהָא כַּד מִתְחַבְּרָן כֻּלְהוּ רוּחֵי דָא בְּדָא וְאִשְׁתַּלִּימוּ דָּא עִם דָּא כְּדְקָא חָזֵי, כְּדֵין אִתְעַר רוּחָא עִלָּאָה נִשְׁמָתָא דְכֹלָּא לְגַבֵּי עֵילָא סְתִימָא דְּכָל סְתִימִין, לְאַתְעָרָא עַל כֹּלָּא לְאַנְהָרָא לוֹן מֵעֵילָא לְתַתָּא. וּלְאַשְׁלָמָא לוֹן לְאַדְלָקָא בּוֹצִינִין.","וְכַד כֹּלָּא (נ\"א איהו) בִּשְׁלִימוּ בִּנְהִירוּ דְּכֹלָּא וְנָחִית נְהִירוּ עִלָּאָה, כְּדֵין הַאי הֵיכָלָא שְׁבִיעָאָה אִיהוּ הֵיכָלָא סְתִימָאָה בִּסְתִימוּ דְּכֹלָּא לְקַבְּלָא הַהוּא קֹדֶשׁ הַקֳּדָשִׁים נְהִירוּ דְּנָחִית וּלְאִתְמַלְיָיא מִתַּמָּן כְּנוּקְבָא דְּמִתְעַבְּרָא מִן דְּכוּרָא וְאִתְמַלְיָיא, וְלָא אִתְמַלְיָיא אֶלָּא מֵהַאי הֵיכָלָא דְּמִתְתַּקְנָא לְקַבְּלָא הַהוּא נְהִירוּ עִלָּאָה, וְרָזָא דָּא הֵיכָלָא שְׁבִיעָאָה אִיהוּ אֲתַר דְּחִבּוּרָא דְּזִוּוּגָא, לְאִתְחַבְּרָא שְׁבִיעָאָה בִּשְׁבִיעָאָה לְמֶהֱוֵי כֹּלָּא חַד שְׁלִימוּ (ד\"א חד) כְּדְקָא חָזִיִ."],[[0,"והכי אתחברן: שמים, דאיהו רוחא קדישא לעילא, נטיל היכלא דא רוחא דא דאקרי רצון:","וכן מתחברים כל בחינה ובחינה של הז\"א עם הבחינה שכנגדה הנמצאת בהיכלות, והראויה להשתלם ממנו: שמים, דהיינו ז\"א, והיינו רוח הקדוש העליון שבו, לוקח היכל זה העליון ורוח הזה העליון הנקרא רצון, \u0003לאתנשקא דא בדא לאתחברא דא בדא לאשתלמא דא בדא, ורזא דא, וישק יעקב לרחל,\u0004 שיתנשקו זה בזה ויתחברו זה בזה, וישתלמו זה בזה, וזה סוד וישק יעקב, שהוא ז\"א לרחל, שהיא נוקביה, הכלולה מכל ששה היכלות שעלו לאצילות, כנ\"ל. ועל דרך זה, \u0003אברהם דאיהו ימינא לעילא, נטיל היכלא דא דאקרי אהבה\u0004 אברהם שהוא ימין למעלה, בז\"א, דהיינו ספירת החסד דז\"א, לוקח היכל הזה שנק' היכל אהבה, דהיינו היכל החמישי, שאומר לעיל (באות קכ\"ג) \u0003וכד תרין רוחין מתפשטן וכו' אתהדר האי היכלא ואקרי היכל אהבה,\u0004 ועד\"ז כל שאר הספירות של הז\"א, הגבורה שלו לוקח היכל הד', ונצח והוד שלו לוקחים היכל הג' והיכל הב', והיסוד שלו את היכל הא' כמו שמפרש לפנינו."],[0,"","פירוש. כי כשהששה היכלות עולים לאצילות הם נכללים בהנוקבא דז\"א, ואז הז\"א מתאחד עמהם, ובכל בחינה ובחינה משלהם משפיע בחינה אחת משלו ומשלים אותם, כמבואר. ובדרך כלל יש ג' זווגים בזו\"ן, המכונים נשיקין, חיבוק, זווג יסודות, שהזווג דג\"ר דזו\"ן מכונה נשיקין, ומזווג הזה מקבל היכל העליון הכלול בג\"ר דנוקבא הנק' רצון, והזווג דחג\"ת עד החזה דזו\"ן, מכונה חיבוק, בסו\"ה שמאלו תחת לראשי וימינו תחבקני, ומזווג הזה מקבל היכל החמישי הנקרא אהבה, שמקבל מחסד דז\"א המכונה אברהם, והיכל הרביעי הנק' זכות, שמקבל מגבורה דז\"א הנק' יצחק. והזווג דנה\"י שמחזה ולמטה דזו\"ן, מכונה זווג היסודות, ומהם מקבלים ג' היכלות התחתונים שמחזה ולמטה."],[1,"וסימניך הנה בא ידעתי כי אשה יפת מראה את, ושפירו דאתתא באנון שדים:","והסימן על זה, הוא הכתוב הנה נא ידעתי וגו' והיופי של אשה הוא בהשדים. כלומר בהיכל החמישי הוא סוד השדים, כנ\"ל (באות קכ\"ב) \u0003דא הוא רזא דכתיכ שני שדיך\u0004 וגו', ומשם אמר הז\"א בסוד החסד שלו שהוא אברהם, אל נוקביה, הנה וגו' יפת מראה את, שה\"ס השדים."],[2,"יצחק דאיהו שמאלא נטיל ההוא היכלא דבי דינא דכל דינין מתערין מתמן, רוחא דאקרי זכותא:","יצחק שהוא שמאלו של הז\"א, דהיינו גבורה שלו, לקח אותו ההיכל של בית דין, שהוא היכל הרביעי, שכל הדינים מתעוררים משם, דהיינו רוח הנקרא זכות. \u0003לאתחברא דא בדא ולאשתלמא דא בדא למהוי כלא חד כדקא יאות,\u0004 שיתחברו זה בזה וישתלמו זה מזה שיהיו הכל אחד כראוי."],[2,"שאר נביאים נטלין תרין היכלין תרין רוחין נוגה וזהר, ברזא וכו' לאתקשרא אלין באלין למהוי חד:","שאר נביאים חוץ ממשה, דהיינו נצח והוד דז\"א, לקחו שני היכלות שבהם ב' רוחות, ,נוגה וזהר, בסוד הכתוב חמוקי ירכיך וגו', שב' היכלות הללו כלולין בנו\"ה דנוקבא הנקראים ירכין, שיתקשרו אלו באלו להיות אחד."],[3,"יוסף הצדיק עמודא דעלמא נטיל היכלא דספיר, רוחא דאקרי לבנת הספיר,","יוסף הצדיק שהוא עמוד העולם, דהיינו יסוד דז\"א, לקח ההיכל הנקרא ספיר, ואת הרוח הנקרא לבנת הספיר, דהיינו היכל הא', \u0003ואע\"ג דכתיב ותחת רגליו כמעשה לבנת הספיר,\u0004 שמשמע שלבנת הספיר הוא מתחתיו, מחוץ למדרגתו, ולא יסוד דז\"א, היינו \u0003בגין יקרא דמלכא,\u0004 משום כבוד המלך, אומר ומתחת רגליו, \u0003והכי הוא ודאי,\u0004 והוא ודאי יסוד דז\"א שהוא לוקח את היכל לבנת הספיר, \u0003ולבתר עמודא דא נטיל יתיר, דאיהו רזא דרזין, באתר דהיכלא שביעאה,\u0004 ואח\"כ עמוד הזה, דהיינו יסוד דז\"א, לוקח יותר, שהוא סוד הסודות לפרשו, כי הוא לוקח במקום היכל השביעי, שהוא שם בסוד הזווג שביעאה בשביעאה כמ\"ש לפנינו."],[3,"עד הכא מתחברן דרגין, ומתחברן דא בדא לאשתלמא דא עם דא למהוי כלהו חד,","עד כאן מתחברים המדרגות דז\"א, עם המדרגות של ההיכלות, שמתחברים זה בזה כדי להשתלם זה עם זה שיהיו כולם אחד. \u0003כלא כדקא חזי\u0004 הכל כראוי להיות, \u0003וכדין ה' הוא האלקים,\u0004 ואז הוי\"ה הוא אלקים, כלומר, הז\"א הנקרא הויה, נעשה אחד עם הנוקבא הנקראת אלקים, באופן שהויה הוא האלקים. \u0003זכאה חולקיה בעלמא דין ובעלמא דאתי, מאן דידע לקשרא לון ולאתדבקא במאריה,\u0004 אשרי חלקו בעולם הזה ובעולם הבא של כל היודע לייחד אותם, ולהתדבק ברבונו."],[4,"הכא הכרעה והשתחואה וקידה ופרישו דכפין ונפילה דאפין לאמשכא רעותא דרוחא עלאה:","כאן, בהיכל הרצון, נוהג כריעה והשתחויה וקידה, ופישוט ידים ונפילת אפים, דהיינו כל הנוהג בהיכלות תחתונות, ונוסף עליהם נפילת אפים, שהוא נוהג רק בהיכל זה בלבד. והוא מטעם, שכל היכלות התחתונים כלולים כאן. כנ\"ל אות קכ\"ו בתריסר נהורין, וצריכים לזה כדי להמשיך הרצון של רוח העליון, דהיינו ג\"ר דז\"א, ששם סוד הנשיקין כנ\"ל, \u0003נשמתא דכל נשמתין, דאיהו תליא לעילא עד אין סוף,\u0004 שהוא הנשמה של כל הנשמות התלוי למעלה, באו\"א עלאין עד שממשיך מא\"ס, ע\"י זווג דנשיקין האמור לעיל, \u0003דמניה נפקי נהירו וברכאן לאשלמא כלא מלעילא כדקא יאות,\u0004 שממנו, מא\"ס, יוצאים אורות וברכות להשלים הכל מלמעלה כראוי. שה\"ס אור החסדים מבחינת שית עלאין דאו\"א, \u0003ולמהוי כלא בשלימו מתתא ומלעילא וכל אנפין נהירין בכל סטרין כדקא יאות,\u0004 כדי להיות הכל בשלימות, מלמטה, דהיינו בהארת החכמה, ומלמעלה, דהיינו בהארת החסדים, שאז כל הפנים, דהיינו כל בחינות ג\"ר מאירים כל הבחינות כראוי, הן ג\"ר דחסדים והן ג\"ר דהארת חכמה. \u0003כדין כל גזרי דינין מתבטלין, וכל רעותא אתעביד לעילא ותתא ועל דא כתיב\u0004 וכו', אז כל גזרות הדין מתבטלים, כי הג\"ר דהארת החכמה מבטלים כל הדינים, וכל הרצון מתמלא למעלה ולמטה, היינו מכח הג\"ר דאור החסדים. ועל זה כתוב ויאמר לי עבדי אתה, ישראל אשר בך אתפאר. וכן כתיב אשרי העם וגו'."],[5,"היכלא שביעאה: היכלא דא לאו ביה דיוקנא ממש, כלא איהו בסתימו:","היכל השביעי: היכל זה אין בו צורה ממש, הכל סתום בו, \u0003גו רזא דרזין פרוכתא דפריסא, קיימין כלהו היכלין דלא לאתחזאה תרין כרובים,\u0004 תוך סוד הסודות בהפרכת שהופרש, עומדים שם כל היכלות, כדי שלא יראו ב' הכרובים שהם זו\"ן. כלומר, שכל היכלות שלמטה עלו ונכללו בפרכת הזו, כדי לכסות על הזו\"ן בעת הזווג הזה, שמשום זה יפה כחם של היכלות לעלות עד שם. והפרכת הזו היא המבדילה בין הששה היכלות שהם קדשים, ובין היכל השביעי שהוא קדשי קדשים."],[5,"לגו מן דא קיימא כפרותא, דיוקנא דקדש קודשין, בגין כך היכלא דא אקרי קדש הקדשים:","לפנים מזה דהיינו לפנים מהפרכת, נמצאת הכפורת, שהיא צורה דקדש הקדשים, כי שם מקום הזווג, משום זה נקרא ההיכל קדש הקדשים. \u0003האי קדש הקדשים אתר מתתקנא לההוא נשמתא עלאה כללא דכלא עלמא דאתי לגבי האי עלאי,\u0004 קדש הקדשים הזה, הוא מקום מתוקן לקבל נשמה עליונה שהיא כלל של הכל, שהוא עולם הבא של העליונים, פירוש, כי בהיכל קדש הקדשים הזה שהיא היכל הבינה, מקובלת הנשמה העליונה הכוללת הכל, הנקראת יחידה. כי הג' היכלות הראשונים היו לנרנח\"י דנשמה, וג' השניים לנרנח\"י דחיה, והיכל הזה השביעי הוא ליחידה. ומה שאומר שהיכל הזה הוא עולם הבא של העליונים, פירושו, כי כל הז' היכלות הללו הם ז' היכלות של או\"א הנקראים עליונים, וע\"כ היכל הז' אינו בינה סתם, אלא בינה של או\"א דהיינו בינה של עליונים."],[6,"דהא כד מתחברן כלהו רוחי דא בדא ואשתלימו דא עם דא כדקא חזי:","שהרי בעת שמתחברים כל הרוחות של ההיכלות זה בזה, ונשלמו זה מזה כראוי, \u0003אתער רוחא עלאה נשמתא דכלא לגבי עילא, סתימא דכל סתימין לאתערא על כלא,\u0004 נתעורר אז רוח העליון, הנשמה של הכל, אל העליון הסתום מכל סתום, שהיא א\"א, שישפיע על הכל, \u0003לאנהרא לון מעילא לתתא, ולאשלמא לון לאדלקא בוצינין,\u0004 להאיר להם ממעלה למטה בהארת הימין, ולהשלים אותם להדליק את הנרות, בהארת השמאל."],[7,"וכד כלא בשלימו בנהירו דכלא, ונחית נהירו עלאה:","וכאשר הכל הוא בשלימות באור המאיר לכל, ויורד אור העליון, \u0003כדין האי היכלא שביעאה איהו היכלא סתימאה בסתימו דכלא לקבלא ההוא קדש הקדשים נהירו דנחית,\u0004 אז היכל שביעי הזה, שהוא היכל הסתום בסתימה הסותמת על כל, מקבל את קדש הקדשים הזה שהוא אור העליון היורד, \u0003ולאתמליא מתמן כנוקבא דמתעברא מן דכורא, ואתמליא,\u0004 ומתמלא משם, כמו נקבה המתעברת מן דכר ומתמלאת ממנו. \u0003ולא אתמליא אלא מהאי היכלא דמתתקנא לקבלא ההוא נהירו עלאה\u0004 ואינו מתמלא אלא מחמת שאותו ההיכל מתוקן בהסתימה הנ\"ל הסותמת על כל, כדי לקבל אותו אור העליון, כלומר, אם תיקון הסתימה לא היה שם לא היה יכול לקבל את אור העליון ההוא. \u0003ורזא דא היכלא שביעאה, איהו אתר דחבורא דזווגא, לאתחברא שביעאה בשביעאה,\u0004 וזה סוד היכל השביעי. הוא מקום החיבור של הזווג, להתחבר שביעי בשביעי. \u0003למהוי כלא חד שלימו כדקא חזי,\u0004 בכדי שיהיה הכל שלימות אחד כראוי, פירוש, כי היכל הששי, ה\"ס הזווג דששי דהיכלות בהששי דז\"א שה\"ס הזווג דנשיקין. (כנ\"ל באות קכ\"ז) והיכל השביעי ה\"ס זווג של שביעי דהיכלות עם שביעי דז\"א. וצריך שתזכור המתבאר למעלה (בדף פ\"ו ד\"ה פירוש) שבעת עליות ההיכלות לאצילות, נמצא כל בחינה ובחינה של הז\"א מזדווג עם הבחינה שכנגדו בהיכלות. עש\"ה."]],[[0,"","(משום שהרוח הששי הזה שנקרא שמים רוח קדוש למעלה, נוטל היכל זה, הרוח הזה שנקרא רצו\"ן מעלה אותם אליהם באותו יחוד, וכך מתחברים רצון להתנשק) (נ\"א: משום שאותו רוח ששי שנקרא רצון מעלה אותם אליהם באותו יחוד, וכך מתחברים שמים, שהוא רוח קדוש למעלה, נוטל היכל זה רוח זה שנקרא רצון להתנשק) זֶה בָּזֶה, לְהִתְחַבֵּר זֶה בָּזֶה, לְהִשְׁתַּלֵּם זֶה בָּזֶה. וְזֶה סוֹד (בראשית כט) וַיִּשַּׁק יַעֲקֹב לְרָחֵל וְגוֹ'."],[1,"","אַבְרָהָם שֶׁהוּא יָמִין לְמַעְלָה נוֹטֵל (ההיכל שאמרנו) (היכל אהבה) רוּחַ שֶׁנִּקְרָא אַהֲבָ\"ה לְהִתְקַשֵּׁר זֶה בָּזֶה, לְהִתְחַבֵּר זֶה בָּזֶה לִהְיוֹת אֶחָד, וְסִימָן לַדָּבָר - (שם יב) הִנֵּה נָא יָדַעְתִּי כִּי אִשָּׁה יְפַת מַרְאֶה אָתְּ. וְיֹפִי שֶׁל הָאִשָּׁה בְּאוֹתָם שָׁדַיִם."],[2,"","יִצְחָק שֶׁהוּא שְׂמֹאל, נָטַל אוֹתוֹ הֵיכָל (של בית דין שכל הדינים מתעוררים, משם הרוח שנקראת זכות להתחבר זה בזה ולהשתלם זה בזה להיות הכל אחד כראוי, שאר הנביאים נטלו שני היכלות (שלמטה)). שְׁנֵי רוּחוֹת נֹגַ\"הּ וְזֹהַ\"ר, בְּסוֹד הַכָּתוּב (שיר ז) חֲמוּקֵי יְרֵכַיִךְ וְגוֹ', לְהִתְקַשֵּׁר אֵלֶּה בְּאֵלֶּה לִהְיוֹת אֶחָד."],[3,"","יוֹסֵף הַצַּדִּיק עַמּוּד הָעוֹלָם נָטַל הֵיכָל שֶׁל סַפִּיר, הָרוּחַ שֶׁנִּקְרֵאת לִבְנַת הַסַּפִּיר, וְאַף עַל גַּב שֶׁכָּתוּב (שמות כד) וְתַחַת רַגְלָיו, בִּשְׁבִיל כְּבוֹד הַמֶּלֶךְ. וְכָךְ הוּא בְּוַדַּאי. וְאַחַר כָּךְ הָעַמּוּד הַזֶּה נָטַל יוֹתֵר, שֶׁהוּא סוֹד הַסּוֹדוֹת, בַּמָּקוֹם שֶׁל הַהֵיכָל הַשְּׁבִיעִי. עַד כָּאן מִתְחַבְּרוֹת דְּרָגוֹת וּמִתְחַבְּרִים זֶה בָּזֶה לְהִשְׁתַּלֵּם זֶה עִם זֶה לִהְיוֹת כֻּלָּם אֶחָד. הַכֹּל כָּרָאוּי. וְאָז ה' הוּא הָאֱלֹהִים וְגוֹ'. אַשְׁרֵי חֶלְקוֹ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא מִי שֶׁיּוֹדֵעַ לְקָשְׁרָם וּלְהִדָּבֵק בְּרִבּוֹנוֹ."],[4,"","כָּאן הַכְרִיעָה (בהכרעה כאן ומוסיף הווי\"ן) וְהִשְׁתַּחֲוָאָה וְקִידָה וּפְרִישַׂת כַּפַּיִם וּנְפִילַת אַפַּיִם לְהַמְשִׁיךְ רְצוֹן הָרוּחַ הָעֶלְיוֹן, נִשְׁמַת כָּל הַנְּשָׁמוֹת, שֶׁתָּלוּי לְמַעְלָה עַד אֵין סוֹף, שֶׁמִּמֶּנּוּ יוֹצְאִים אוֹרוֹת וּבְרָכוֹת לְהַשְׁלִים הַכֹּל מִלְמַעְלָה כָּרָאוּי וְלִהְיוֹת הַכֹּל בִּשְׁלֵמוּת מִלְּמַטָּה וּמִלְמַעְלָה, וְכָל הַפָּנִים מְאִירוֹת בְּכָל הַצְּדָדִים כָּרָאוּי. וְאָז מִתְבַּטְּלִים כָּל גִּזְרֵי הַדִּין, וְכָל הָרָצוֹן נַעֲשֶׂה לְמַעְלָה וּלְמַטָּה. וְעַל זֶה כָּתוּב (ישעיה מט) וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר. וְכָתוּב (תהלים קמד) אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ אַשְׁרֵי הָעָם שֶׁה' אֱלֹהָיו."],[5,"","הֵיכָל שְׁבִיעִי. בְּהֵיכָל זֶה אֵין בּוֹ דְּמוּת מַמָּשׁ, הַכֹּל הוּא בְּנִסְתָּר וְגוֹ' (תוך) סוֹד הַסּוֹדוֹת, הַפָּרֹכֶת שֶׁפְּרוּסָה (פרוסה), כָּל הַהֵיכָלוֹת עוֹמְדִים שֶׁלֹּא יִתְרָאוּ שְׁנֵי כְרוּבִים (ד\"א זה מזה עומדים). לִפְנִים מִזֶּה עוֹמֶדֶת כַּפֹּרֶת, דְּמוּת שֶׁל קֹדֶשׁ הַקְּדָשִׁים, וְלָכֵן הֵיכָל זֶה נִקְרָא קֹדֶשׁ הַקְּדָשִׁים. קֹדֶשׁ הַקְּדָשִׁים הַזֶּה מָקוֹם מְתֻקָּן לְאוֹתָהּ נְשָׁמָה עֶלְיוֹנָה, כְּלָל שֶׁל כָּל הָעוֹלָם הַבָּא לְגַבֵּי (עולם) הָעֶלְיוֹנִים הַלָּלוּ."],[6,"","שֶׁהֲרֵי כְּשֶׁמִּתְחַבְּרִים כָּל הָרוּחוֹת זֶה בָּזֶה וְנִשְׁלָמִים זֶה בָּזֶה כָּרָאוּי, אָז מִתְעוֹרֵר רוּחַ עֶלְיוֹן נִשְׁמַת הַכֹּל כְּלַפֵּי מַעְלָה נִסְתַּר כָּל הַנִּסְתָּרִים, לְהִתְעוֹרֵר עַל הַכֹּל וּלְהָאִיר לָהֶם מִלְמַעְלָה לְמַטָּה, וּלְהַשְׁלִים אוֹתָם לְהַדְלִיק נֵרוֹת."],[7,"","וּכְשֶׁהַכֹּל (נ\"א: הוא) בִּשְׁלֵמוּת בָּאוֹר שֶׁל הַכֹּל וְיוֹרֵד אוֹר עֶלְיוֹן, אָז הַהֵיכָל הַשְּׁבִיעִי הַזֶּה הוּא הֵיכָל נִסְתָּר בְּסֵתֶר הַכֹּל, לְקַבֵּל אֶת אוֹתוֹ קֹדֶשׁ הַקְּדָשִׁים אוֹר שֶׁיּוֹרֵד, וּלְהִתְמַלֵּא מִשָּׁם כְּמוֹ נְקֵבָה שֶׁמִּתְעַבֶּרֶת מִן הַזָּכָר וּמִתְמַלֵּאת, וְלֹא מִתְמַלֵּאת אֶלָּא מֵהֵיכָל זֶה שֶׁמְּתֻקָּן לְקַבֵּל אוֹתוֹ אוֹר עֶלְיוֹן. וְזֶה סוֹד הַהֵיכָל הַשְּׁבִיעִי, הוּא מָקוֹם שֶׁל חִבּוּר הַזִּוּוּג לְהִתְחַבֵּר שְׁבִיעִי בִּשְׁבִיעִי, לִהְיוֹת הַכֹּל אֶחָד שְׁלֵמוּת (אחת) כָּרָאוּי."]]],[["וּמָאן דְּיָדַע לְקָשְׁרָא יִחוּדָא דָא זַכָּאָה חוּלָקֵיהּ רָחִים לְעֵילָא רָחִים לְתַתָּא קוּדְשָׁא בְּרִיךְ הוּא (איהו) גָּזִיר וְאִיהוּ מְבַטֵּל. סָלְקָא דַעְתִּין דְּאִיהוּ מְקַטְרְגָא בְּמָארֵיהּ, לָאו הָכִי, אֶלָּא בְּגִין דְּכַד אִיהוּ קָשִׁיר קְשִׁירִין וְיָדַע לְיַחֲדָא יִחוּדָא וְכָל אַנְפִּין נְהִירִין וְכָל שְׁלִימוּ אִשְׁתְּכַח וְכֹלָּא אִתְבָּרְכָא כְּדְקָא יָאוּת, כָּל דִּינִין מִתְעַבְּרִין וּמִתְבַּטְּלִין וְלָא אִשְׁתְּכַח דִּינָא בְּעָלְמָא. זַכָּאָה חוּלָקֵיהּ בְּעָלְמָא דֵין וּבְעָלְמָא דְאֲתֵי. דָּא הוּא לְתַתָּא דִּכְתִיב בֵּיהּ (משלי י׳:כ״ה) וְצַדִּיק יְסוֹד עוֹלָם דָּא הוּא קִיּוּמָא דְעָלְמָא. בְּכָל יוֹמָא קָארֵי עֲלוֹי כָּרוֹזָא (ישעיהו מ״א:ט״ז) וְאַתָּה תָּגִיל בַּיְיָ בִּקְדוֹשׁ יִשְׂרָאֵל תִּתְהַלָּל.","כְּגַוְונָא דָא קָרְבָּנָא (ד\"א ל\"ג דא) סָלְקָא תְּנָנָא וּמִסְתַּפְּקִין (ד\"א ביה) כָּל חַד וְחַד כִּדְקָחָזֵי לֵיהּ, וְכַהֲנִי בִּרְעוּתָא וְלֵוָאֵי בִּבְסִימוּ דְּשִׁירָתָא. דָּא אִתְכְּלִיל בְּדָא, וְעַיְילֵי הֵיכָלָא בְּהֵיכָלָא רוּחָא בְּרוּחָא עַד דְּמִתְחַבְּרָן בְּדוּכְתַּיְיהוּ כְּדְקָא חָזֵי לֵיהּ שַׁיְיפָא בְּשַׁיְיפָא וְאִשְׁתַּלִּימוּ דָּא בְּדָא וְאִתְיַיחֲדוּ דָּא בְּדָא עַד דְּאִנּוּן חַד (ד\"א ל\"ג) (ואתנהרין) וְנָהֲרִין דָּא בְּדָא.","כְּדֵין נִשְׁמָתָא עִלָּאָה דְּכֹלָּא אַתְיָא מִלְּעֵילָא וְנָהִיר לוֹן, וְהֲווּ נְהִירִין כֻּלְהוּ בּוֹצִינִין בִּשְׁלִימוּ כְּדְקָא חָזֵי, עַד דְּהַהוּא נְהוֹרָא עִלָּאָה אִתְעַר וְכֹלָּא אָעִיל לְגַבֵּי קֹדֶשׁ הַקֳּדָשִׁים, וְאִתְבָּרְכָא וְאִתְמַלְיָיא כְּבֵירָא דְּמַיִין נָבְעִין וְלָא פָּסְקִין, וְכֻלְהוּ. מִתְבָּרְכָאן לְעֵילָא וְתַתָּא.","הָכָא רָזָא דְּרָזִין, הַהוּא דְּלָא אִתְיְידַע וְלָא אָעִיל בְּחוּשְׁבְּנָא. רְעוּתָא דְּלָא אִתְפַּס לְעָלְמִין בְּסִים לְגוֹ לְגוֹ בְּגַוַּויְיהוּ, וְלָא אִתְיְידַע הַהוּא רְעוּתָא וְלָא אִתְפַּס לְמִנְדַע (ד\"א ל\"ג) (לן) וּכְדֵין כֹּלָּא רְעוּתָא חָדָא עַד אֵין סוֹף וְכֹלָּא אִיהוּ בִּשְׁלִימוּ מִתַּתָּא וּמִלְּעֵילָא וּמִגּוֹ לְגוֹ. עַד דְּאִתְעֲבִיד כֹּלָּא חָד.","הַאי רְעוּתָא לָא אָעִיל לְגוֹ אַף עַל גַּב דְּלָא אִתְיְידַע עַד דְּכֹלָּא אִשְׁתְּלִים וְאִתְנְהִיר בְּקַדְמִיתָא בְּכֻלְהוּ סִטְרִין. כְּדֵין בָּסִים הַהוּא רְעוּתָא (ד\"א ל\"ג) (לכלא) וְלָא (ד\"א דלא) אִתְפַּס לְגוֹ בְּגוֹ בִּסְתִימוּ, וּכְדֵין זַכָּאָה חוּלָקֵיהּ מָאן דְּיִתְדַּבַּק בְּמָארֵיהּ בְּהַהִיא שַׁעֲתָא, זַכָּאָה אִיהוּ לְעֵילָא זַכָּאָה אִיהוּ לְתַתָּא עֲלֵיה כְּתִיב, (משלי כ״ג:כ״ה) יִשְׂמַח אָבִיךָ וְאִמֶּךָ וְתָגֵל יוֹלַדְתֶּךָ.","תָּא חֲזֵי, כֵּיוָן דְּכֻלְהוּ אִשְׁתַּלִּימוּ דָא בְּדָא וְאִתְקַּשְּׁרוּ דָּא בְּדָא בְּקִשּׁוּרָא חָדָא וְנִשְׁמָתָא עִלָּאָה נָהִיר לוֹן מִסִּטְרָא דִלְעֵילָא, וְכֻלְּהוּ נְהוֹרִין אִנּוּן בּוֹצִינָא חָדָא בִּשְׁלִימוּ, כְּדֵין רַעֲוָא חָדָא דְּמַחֲשָׁבָה (ד\"א במחשבה) אִתְפַּס (ד\"א לגו לגו דנהירו דסליק על כלא ובגו לגו בההוא רעותא במחשבה אתפס) נְהִירוּ דְּלָא אִתְפַּס וְלָא אִתְיְידַע בַּר הַהוּא רְעוּ דְּמַחֲשָׁבָה תָּפִיס וְלָא יָדַע מַה תָּפִיס אֶלָּא דְּאִתְנְהִיר וְאִתְבַּסָּם הַהוּא רְעוּ דְּמַחֲשָׁבָה וְאִתְמַלְיָיא כֹּלָּא וְאִשְׁתְּלִים כֹּלָּא וְאִתְנְהִיר וְאִתְבַּסַּם כֹּלָּא כְּדְקָא יָאוּת. וְעַל דָּא כְּתִיב, (תהילים קמ״ד:ט״ו) אַשְׁרֵי הָעָם שֶׁכָּכָה לוֹ וְגו'.","מָאן דְּזָכֵי לְאִתְדַּבְּקָא בְּמָארֵיהּ כְּהַאי גַּוְונָא, יָרִית עָלְמִין כֻּלְהוּ, רְחִימָא לְעֵילָא רְחִימָא לְתַתָּא, צְלוֹתֵיהּ לָא אֲהַדְּרָא רֵיקַנְיָא, דָּא אִתְחַטֵּי קַמֵּי מָארֵיהּ כִּבְרָא קַמֵּי אֲבוֹי וְעָבִיד לֵיהּ רְעוּתָא בְּכָל מַה דְּאִצְטְרִיךְ, וְאֵימְתֵיהּ שַׁלִּיט עַל כָּל בִּרְיָין אִיהוּ גָּזִיר וְקוּדְשָׁא בְּרִיךְ הוּא עָבִיד. עֲלֵיהּ כְּתִיב, (איוב כ״ב:כ״ח) וְתִגְזַר אֹמֶר וְיָקָם לָךְ וְעַל דְּרָכֶיךָ נָגַהּ אוֹר:","(נדפס בריש זהר חדש) וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וַיְהִי אוֹר וְגו'. אָמַר רַבִּי יִצְחָק מִכָּאן דְּעֲקָרָן קוּדְשָׁא בְּרִיךְ הוּא לְהָנִי נְטִיעָן (ד\"א ושתיל לון משמע דכתיב יהי. רבי יהודה אומר אור שכבר היה תנן, משמע דכתיב ויהי אור, והיה לא כתיב אלא ויהי. וכד אסתכל קודשא בריך הוא באנון דרין דרשיעייא. גניז ליה לצדיקייא הדא הוא דכתיב, (תהלים צו) אור זרוע לצדיק ולישרי לב שמחה והא אתמר, ויאמר אלהים יהי אור, הדא הוא דכתיב, (ישעיהו מ״א:ב׳) מי העיר ממזרח וגו'.","וירא אלהים את האור כי טוב. מאי ראה, אמר רבי חייא כדקאמרן חמא בעובדייהו דרשיעייא וגניז ליה. רבי אבא אמר וירא אלהים את האור כי טוב לגנוז אותו. וירא אלהים את האור), (נ\"א ושתיל לון דכתיב ויהי אור מאי משמע אור שכבר היה אור. רבי יהודה אומר אור לא נאמר אלא ויהי לומר שכבר היה וכתיב אור זרוע לצדיק וגו' והאי הוא דכתיב מי העיר ממזרח וגו'. וירא אלהים את האור ויבדל אמר רבי יצחק כדאמרן דחמא בעובדייהון דרשיעייא וגניז ליה. רבי אבא אמר חמא) דְּסָלִיק נְהוֹרֵיהּ מִסְיָיפֵי עָלְמָא עַד סְיָיפֵי עָלְמָא, וְכִי טוֹב הוּא לְאַגְנָזָא לֵיהּ דְּלָא יֶהֱנוּן מִנֵּיהּ חַיָּיבֵי עָלְמָא."],[[0,"ומאן דידע לקשרא יחודא דא זכאה חולקיה, רחים לעילא רחים לתתא, קב\"ה גזיר ואיהו מבטל:","מי שיודע לקשר יחוד הזה אשרי חלקו, הוא אהוב למעלה ואהוב למטה, הקב\"ה גוזר והוא מבטל. \u0003סלקא דעתין דאיהו מקטרגא במאריה,\u0004 שואל, הכי יעלה על הדעת שהצדיק יקטרג על רצון רבונו, כי יבטל רצונו של הקב\"ה ומשיב, \u0003לאו הכי, אלא בגין דכד איהו קשיר קשירין, וידע ליחדא יחודא וכל אנפין נהירין, וכל שלימו אשתכח וכלא אתברכא כדקא יאות, כל דינין מתעברין ומתבטלין ולא אשתכח דינא בעלמא,\u0004 ומשיב, אינו כן, אלא כשהצדיק קושר קשרים ויודע ליחד יחודים, ומאירים כל פנים ונמצא כל השלימות, והכל מתברך כראוי, הרי כל הדינים עוברים ומתבטלים, ולא נמצא שום דין בעולם. \u0003זכאה חולקיה בעלמא דין ובעלמא דאתי,\u0004 אשרי חלקו בעוה\"ז ובעוה\"ב, ונמצא אשר הפירוש של הקב\"ה גוזר והצדיק מבטל, הוא על ידי ריבוי אורות שהצדיק ממשיך ע\"י היחודים שעושה, שהאורות ההם מבטלים את הגזרות והדינים מהעולם."],[0,"דא הוא לתתא, דכתיב ביה וצדיק יסוד עולם, דא הוא קיומא דעלמא:","כל מה שאמרנו בהצדיק, הוא מה שפועל למטה בעוה\"ז, וע\"כ כתיב בו, וצדיק יסוד עולם, כי הצדיק הוא קיום העולם. ולהלן יבאר מה שהצדיק פועל בעולמות העליונים. \u0003בכל יומא קארי עלוי כרוזא, ואתה תגיל\u0004 וגו', בכל יום מכריזים עליו כרוז, ואתה תגיל בה' בקדוש ישראל תתהלל."],[1,"כגוונא דא קרבנא, סלקא תננא, ומסתפקין כל חד וחד כדקחזי ליה:","כעין זה, שנעשה ע\"י תפילת הצדיק נעשה ג\"כ ע\"י הקרבן, העשן של הקרבן עולה, ומספק לכל היכל והיכל מה שהוא צריך כראוי לו, דהיינו על דרך שנתבאר לעיל בתפילת הצדיק והיחודים שעושה, \u0003וכהני ברעותא ולואי בבסימו דשירתא דא אתכליל בדא,\u0004 והכהנים בהרצון שלהם להעלות נחת רוח למעלה והלוים בנעימת השיר שמזמרים בשעת הקרבת הקרבן, זה נכלל בזה, היינו הלוים בכהנים והכהנים בלוים, כי הכהנים הם ממשיכים בחינת ימין והלוים ממשיכים בחינת שמאל, שזה בלי זה אין שלימות, כמ\"ש לעיל. \u0003ועיילי היכלא בהיכלא, רוחא ברוחא עד דמתחברן בדוכתייהו כדקא חזי ליה שייפא בשייפא,\u0004 ונכנסים היכל בהיכל רוח ברוח, עד שמתחברים כולם במקומם, כראוי להם, אבר באבר, דהיינו שעולים לאצילות לזו\"ן, וכל בחינה ובחינה של ז\"א מתחברת בהבחינה שכנגדה בהיכלות, (כנ\"ל דף פ\"ו ד\"ה פירוש) \u0003ואשתלימו דא בדא, ואתייחדו דא בדא עד דאינון חד, ונהרין דא בדא,\u0004 ונשלמים זה מזה, ע\"י זווג דיסודות, ומתייחדים זה בזה עד שנעשים אחד, ע\"י זווג דנשיקין, ומאירים זה בזה, ע\"י החיבוק, כמ\"ש שם."],[2,"כדין, נשמתא עלאה דכלא אתיא מלעילא, ונהיר לון, והוו נהירין כלהו בוצינין בשלימו כדקא חזי,","אז, נשמה העליונה מכולם באה מלמעלה ומאירה עליהם, ומאירים כל הנרות, דהיינו הספירות, בהשלמות כראוי, (כנ\"ל באות קל\"ח) \u0003עד דההוא נהורא עלאה אתער וכלא אעיל לגבי קדש הקדשים,\u0004 עד שאותו אור העליון נתעורר וכל ההיכלות נכנסים לקדש קדשים, דהיינו להיכל השביעי הנקרא קדש קדשים בסוד הזווג דשביעאה בשביעאה, (כנ\"ל באות קל\"ט) \u0003דאתברכא ואתמלייא כבירא דמיין נבעין ולא פסקין, וכלהו מתברכאן לעילא ותתא\u0004 והיכל השביעי מתברך ומתמלא כמו באר מים נובעים ואינם פוסקים, וכל ההיכלות מתברכים למעלה ולמטה."],[3,"הכא רזא דרזין, ההוא דלא אתיידע ולא אעיל בחושבנא, רעותא דלא אתפס לעלמין:","כאן סוד הסודות, אור ההוא דלא אתיידע ולא נכנס בחשבון הע\"ס, הרצון שאינו נתפס לעולם. דהיינו אור היחידה, כי הע\"ס מתחילים מהחכמה, חב\"ד חג\"ת נהי\"מ, בסים לגו לגו בגווייהו, ולא אתיידע ההוא רעותא, ולא אתפס למנדע, נמתק בתוכם לפני ולפנים, ורצון ההוא אינו נודע, ואינו נתפס אפילו במחשבה, לדעת אותו, \u0003וכדין כלא רעותא חדא עד א\"ס,\u0004 ואז כל המדרגות מתיחדים ונעשים רצון אחד עד א\"ס ב\"ה. פירוש שבעת שאור היחידה מתמתק ומתלבש לפני ולפנים של המדרגות, מתיחדים בהארתו כל המדרגות ונעשו רצון אחד מיוחד עד א\"ס \u0003וכלא איהו בשלימו, מתתא ומלעילא, ומגו לגו, עד דאתעביד כלא חד,\u0004 והכל הוא בשלימות מלמטה ומלמעלה, ומפנימי פנימיות עד שנעשו כולם אחד. פירוש, כי בב' דרכים מתחלקות המדרגות זו מזו, או בדרך עליון ותחתון, שהמשובח הוא העליון והגרוע ממנו הוא התחתון ממנו, או בדרך פנימי וחיצון, שכל המשובח מחברו הוא יותר פנימי. ואומר שע\"י התלבשות אור היחידה נעשים כולם אחד, הן המתחלקים בדרך עליון ותחתון, והן המתחלקים בדרך פנימי וחיצון."],[4,"האי רעותא לא אעיל לגו אע\"ג דלא אתיידע, עד דכלא אשתלים ואתנהיר בקדמיתא בכלהו סטרין,","הרצון ההוא, דהיינו אור היחידה הנ\"ל, אינו מתלבש בפנימיות המדרגות, אע\"פ שנשאר בתוכם בלתי נודע, עד שכולם נשלמים מתחילה ומאירים בכל הבחינות הן מבחינת הארת החכמה והן מבחינת אור החסדים, \u0003כדין בסים ההוא רעותא דלא אתפס לגו בגו בסתימו,\u0004 אז מתמתק הרצון ההוא שאינו נתפס ומתלבש בפנימי פנימיות בדרך סתום, וכ\u0003דין זכאה חולקיה מאן דיתדבק במאריה בההיא שעתא,\u0004 ואז אשרי חלקו, מי שיתדבק בשעה ההוא ברבונו \u0003זכאה איהו לעילא זכאה איהו לתתא עליה כתיב\u0004 וכו', הוא שלם למעלה ושלם למטה, עליו כתוב, ישמח אביך ואמך ותגל יולדתך."],[5,"ת\"ח, כיון דכלהו אשתלימו דא בדא, ואתקשרו דא בדא בקשורא חדא,","בוא וראה, כיון שכולם נשלמו זה מזה, ונקשרו זה בזה בקשר אחד, \u0003ונשמתא עלאה נהיר לון מסטרא דלעילא וכלהו נהורין אינון בוצינא חדא בשלימו,\u0004 ונשמה העליונה דהיינו בינה, מאירה להם מלמעלה, וכל המאורות הם נר אחד, בשלימות, \u0003כדין רעוא חדא דמחשבה, אתפס, נהירו דלא אתפס ולא אתיידע,\u0004 אז רצון אחד של המחשבה תופס את האור שאינו נתפס ואינו נודע. \u0003רעוא חדא דמחשבה,\u0004 פירושו אור החיה. \u0003נהירו דלא אתפס,\u0004 פירושו אור היחידה. ואומר שהם מתלבשים זב\"ז. פירוש, כי ממשיך לבאר ענין התלבשות אור היחידה, שאומר, שהוא מתמתק בפנימי פנימיות בדרך סתום כנ\"ל בדיבור הסמוך, ומבאר כאן סדר הלבשתו. ואומר, כי אחר שנשלמו כל ההיכלות, ונשמה העליונה שהיא בינה מאירה בהם, אז מתלבש אור החיה המכונה \u0003רעוא חדא דמחשבה,\u0004 תוך אור הנשמה, ואור היחידה תוך אור החיה. ונמצא אור החיה תופס בתוכו את \u0003נהירו דלא אתפס\u0004 וכו' שהוא אור היחידה. אמנם אע\"פ שאור היחידה מתלבש באור החיה, עדיין הוא מאיר בו בדרך סתום, כנ\"ל בדיבור הסמוך. וז\"ש, \u0003בר ההוא רעו דמחשבה תפיס ולא ידע מה תפיס, אלא דאתנהיר ואתבסם ההוא רעו דמחשבה,\u0004 מלבד, שהרצון דמחשבה ההוא, דהיינו אור החיה המלביש לאור היחידה, תופס ואינו יודע מה שתופס, דהיינו מחמת שמאיר בו בדרך סתום, אלא שהרצון דמחשבה מאיר על ידו ומתמתק הימנו מתוך שמלבישו. \u0003ואתמליא כלא ואשתלים כלא ואתנהיר ואתבסם כלא כדקא יאות וע\"ד\u0004 וכו' וכולם מתמלאים מאורו וכולם נשלמים וכולם מאירים על ידו ומתמתקים כראוי, ועל זה כתיב \u0003אשרי העם שככה לו\u0004 וגו'."],[6,"מאן דזכי לאתדבקא במאריה כהאי גוונא, ירית עלמין כלהו, רחימא לעילא רחימא לתתא:","מי שזוכה להתדבק ברבונו בדרך הזה הנזכר, יורש כל העולמות, הוא אהוב למעלה ואהוב למטה, \u0003צלותיה לא אהדרא ריקניא, דא אתחטי קמי מאריה כברא קמי אבוי, ועביד ליה רעותא בכל מה דאצטריך,\u0004 תפלתו אינו חוזרת ריקם, זהו מתחטא לפני רבונו, כבן המתחטא לפני אביו ועושה לו רצונו בכל מה שצריך. \u0003ואימתיה שליט על כל בריין, איהו גזיר וקב\"ה עביד, עליה כתיב\u0004 וכו' ואימתו מוטלת על כל הבריות, הוא גוזר והקב\"ה מקיים, עליו כתוב \u0003ותגזר אומר ויקם לך ועל דרכיך נגה אור.\u0004 נשלם ביאור ההיכלות."],[7,"ויאמר אלקים יהי אור וגו' א\"ר יצחק מכאן דעקרן קב\"ה להני נטיען ושתיל לון, משמע דכתיב יה\"י:","אמר רבי יצחק, מכאן משמע, שעקר הקב\"ה אלו הנטיעות ממקומם ושתל אותם במקום אחר, וזה משמע ממ\"ש יה\"י. פירוש. כי הזו\"ן מכונים נטיעות, בסוד עץ החיים וכו'. וכל עוד שהיו במקומם, דהיינו מטרם עלית המלכות לבינה, לא היו הזו\"ן ראוים לקבל שום אור, (כנ\"ל בבראשית א' דף ז' ד\"ה וכבר) ולפיכך עקרם ממקומם, והעלה אותם ושתלם במקום בינה, ושם נעשו מוכשרים לקבל אור העליון. ולמד זאת מהמלה יה\"י אור, והיינו כמו שנתבאר לעיל (בבראשית א' דף מ\"ג ד\"ה יה\"י על רזא דאו\"א) אשר י\"ה דיה\"י ה\"ס או\"א וה\u0003י'\u0004 אחרונה דיהי רומזת על כניסת ה\u0003י'\u0004 ל\u0003אור\u0004 או\"א, ונעשו \u0003אויר,\u0004 שבזה נתחברו זו\"ן באו\"א והוכשרו לקבל מהם האור. עש\"ה כי אין להכפיל דברים."],[7,"ר\"י אומר, אור שכבר היה תנן, משמע דכתיב ויהי אור, והיה לא כתיב אלא ויהי:","ר' יהודה אומר, אור שכבר היה, למדנו, וזה משמע ממ\"ש ויהי אור, כי והיה לא נאמר אלא ויהי אור, משמע שכבר היה."],[7,"וכד אסתכל קב\"ה באינון דרין דרשיעיא, גניז ליה לצדיקיא הה\"ד אור זרוע","וגו', וכשנסתכל הקב\"ה בדורות הרשעים, שאינם כדאים להאור, גנז אותו לצדיקים וז\"ש אור זרוע לצדיק וגו', שהאור נגנז ונזרע בשביל שיקבלו אותו רק הצדיקים, ולא הרשעים. \u0003והא אתמר ויאמר אלקים יהי אור,\u0004 וזהו שנאמר ויאמר אלקים יהי אור, אשר המלה יה\"י יורה על גניזת האור, (כמ\"ש לעיל דף מ\"ג ד\"ה יהי עש\"ה), כי י\"ה דיה\"י ה\"ס אור או\"א, ו\u0003י'\u0004 אחרונה דיה\"י רומזת על כניסת ה\u0003י'\u0004 ב\u0003אור\u0004 ונעשה ל\u0003אויר,\u0004 ונבחן זה לגניזה וזריעת האור בשביל הצדיקים. \u0003הה\"ד מ\"י העיר ממזרח\u0004 וגו', פירוש. כי ע\"י כניסת הי' לאור או\"א ירדו אתוון \u0003אל\"ה\u0004 דאלקים מאו\"א לזו\"ן, ולא נשארו באו\"א אלא אתוון \u0003מ\"י\u0004 דאלקים, שעי\"ז נעשו הזו\"ן מוכשרים לקבל אור או\"א, ונמצא שאלו ב' אותיות מ\"י דאו\"א, הן שורש כל המוחין דזו\"ן, (כנ\"ל בראשית א' דף מ\"ג ד\"ה יהי עש\"ה) וז\"ש \u0003מ\"י\u0004 העיר \u0003ממזרח,\u0004 דהיינו ז\"א, \u0003צדק\u0004 היינו מלכות, אשר ב' אותיות מ\"י העירו המוחין לז\"א שה\"ס ממזרח, ולמלכות שה\"ס צדק, ו\u0003העירו,\u0004 הוא לשון התחלת התעוררות מוחין, כי רק התחלת המוחין באים ע\"י \u0003מ\"י,\u0004 כמ\"ש שם."],[8,"וירא אלקים את האור וגו' מה ראה, אר\"ח כדקאמרן, חמא בעובדיהון דרשיעיא וגניז ליה:","וירא אלקים וגו' מה ראה. א\"ר חייא, היינו כמו שאמרנו לעיל, שהקב\"ה ראה במעשיהם של רשעים וגנז אותו, \u0003רבי אבא אמר, וירא אלקים את האור כי טוב לגנוז אותו,\u0004 ר\"א פליג, ואומר, לא שראה במעשיהם של הרשעים, אלא שראה בגדלו של האור גופו כי טוב לגנוז אותו, ולא יהיה מגולה להעולם, \u0003וירא אלקים את האור, דסליק נהוריה מסייפי עלמא עד סייפי עלמא, וכי טוב הוא לאגנזא ליה, דלא יהנון מניה חייבי עלמא,\u0004 וירא אלקים את האור, פירושו, שראה שהוא מאיר מסוף העולם עד סופו, וטוב לגנוז אותו כדי שלא יהנו ממנו רשעי עולם. פירוש, כי אם הרשעים יהנו מאור הגדול הזה לא יבואו עוד לתשובה. בדומה להכתוב פן ישלח ידו ולקח מעץ החיים ואכל וחי לעולם. שכוונת הכתוב הוא, שלא יהיה לו עוד צורך ודחיפה לעשות תשובה ולא יתוקן הפגם שעשה בעצה\"ד, ולכן גירש אותו מג\"ע."]],[[0,"","וּמִי שֶׁיּוֹדֵעַ לִקְשֹׁר יִחוּד זֶה - אַשְׁרֵי חֶלְקוֹ, אָהוּב לְמַעְלָה וְאָהוּב לְמַטָּה, הַקָּדוֹשׁ בָּרוּךְ הוּא גּוֹזֵר וְהוּא מְבַטֵּל. הֲיַעֲלֶה עַל דַּעְתְּךְ שֶׁהוּא מְקַטְרֵג בְּרִבּוֹנוֹ? לֹא כָּךְ! אֶלָּא מִשּׁוּם שֶׁכְּשֶׁהוּא קוֹשֵׁר קְשָׁרִים וְיוֹדֵעַ לְיַחֵד יִחוּד וְכָל הַפָּנִים מְאִירוֹת, וְכָל הַשְּׁלֵמוּת נִמְצֵאת, וְהַכֹּל מִתְבָּרֵךְ כָּרָאוּי, כָּל הַדִּינִים מִסְתַּלְּקִים וּמִתְבַּטְּלִים וְלֹא נִמְצָא דִין בָּעוֹלָם. אַשְׁרֵי חֶלְקוֹ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. זֶהוּ לְמַטָּה, שֶׁכָּתוּב בּוֹ (משלי י) וְצַדִּיק יְסוֹד עוֹלָם. זֶהוּ קִיּוּם הָעוֹלָם. בְּכָל יוֹם קוֹרֵא עָלָיו הַכָּרוֹז, (ישעיה מא) וְאַתָּה תָּגִיל בַּה' בִּקְדוֹשׁ יִשְׂרָאֵל תִּתְהַלָּל."],[1,"","כְּמוֹ זֶה קָרְבָּן (זה) עוֹלֶה עָשָׁן, וּמִסְתַּפְּקִים (בו) כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ, וְכֹהֲנִים בְּרָצוֹן, וּלְוִיִּם בִּנְעִימוּת הַשִּׁירָה. זֶה נִכְלָל בָּזֶה, וְנִכְנָסִים הֵיכָל בְּהֵיכָל, רוּחַ בְּרוּחַ, עַד שֶׁמִּתְחַבְּרִים בִּמְקוֹמָם כָּרָאוּי לוֹ אֵיבָר בְּאֵיבָר וּמִשְׁתַּלְּמִים זֶה בָּזֶה, וּמִתְיַחֲדִים זֶה בָּזֶה, עַד שֶׁהֵם אֶחָד (ונאורים) וּמְאִירִים זֶה בָּזֶה."],[2,"","אָז הַנְּשָׁמָה הָעֶלְיוֹנָה שֶׁל הַכֹּל בָּאָה מִלְמַעְלָה וּמְאִירָה לָהֶם, וְכָל הַנֵּרוֹת מְאִירִים בִּשְׁלֵמוּת כָּרָאוּי, עַד שֶׁאוֹתוֹ אוֹר עֶלְיוֹן מִתְעוֹרֵר, וְהַכֹּל נִכְנָס אֶל קֹדֶשׁ הַקְּדָשִׁים, וּמִתְבָּרֵךְ וּמִתְמַלֵּא כִּבְאֵר שֶׁל מַיִם נוֹבְעִים וְלֹא פוֹסְקִים, וְכֻלָּם מִתְבָּרְכִים לְמַעְלָה וּלְמַטָּה."],[3,"","כָּאן סוֹד הַסּוֹדוֹת אוֹתוֹ שֶׁלֹּא נוֹדָע וְלֹא נִכְנָס בְּחֶשְׁבּוֹן, רָצוֹן שֶׁלֹּא נִתְפָּס לְעוֹלָמִים מַמְתִּיק לִפְנַי וְלִפְנִים בְּתוֹכָם. וְלֹא נוֹדָע אוֹתוֹ רָצוֹן וְלֹא נִתְפָּס לַדַּעַת (לנו). וְאָז הַכֹּל רָצוֹן אֶחָד עַד אֵין סוֹף, וְהַכֹּל הוּא בִּשְׁלֵמוּת מִלְּמַטָּה וּמִלְמַעְלָה וּמִלִּפְנַי וְלִפְנִים, עַד שֶׁנַּעֲשֶׂה הַכֹּל אֶחָד."],[4,"","הָרָצוֹן הַזֶּה לֹא נִכְנָס פְּנִימָה, אַף עַל גַּב שֶׁלֹּא נוֹדָע, עַד שֶׁהַכֹּל נִשְׁלָם וּמֵאִיר בַּהַתְחָלָה בְּכָל הַצְּדָדִים. אָז מַמְתִּיק אוֹתוֹ רָצוֹן (לכל) וְלֹא (שלא) נִתְפָּס לִפְנַי וְלִפְנִים בְּנִסְתָּר. וְאָז אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁנִּדְבָּק בְּרִבּוֹנוֹ בְּאוֹתָהּ שָׁעָה, אַשְׁרָיו לְמַעְלָה וְאַשְׁרָיו לְמַטָּה, עָלָיו כָּתוּב (משלי כג) יִשְׂמַח אָבִיךְ וְאִמֶּךְ וְתָגֵל יוֹלַדְתֶּךְ."],[5,"","בֹּא רְאֵה, כֵּיוָן שֶׁכֻּלָּם נִתְקְנוּ זֶה בָּזֶה וְנִקְשְׁרוּ זֶה בָּזֶה בְּקֶשֶׁר אֶחָד, וְהַנְּשָׁמָה הָעֶלְיוֹנָה מְאִירָה לָהֶם מִצַּד שֶׁל מַעְלָה, וְכָל הָאוֹרוֹת הֵם נֵר אֶחָד בִּשְׁלֵמוּת, אָז רָצוֹן אֶחָד שֶׁל הַמַּחֲשָׁבָה (במחשבה) נִתְפָּס (ד\"א לפני ולפנים, שאור שעולה על הכל ובפני לפנים באותו רצון נתפס במחשבה) אוֹר שֶׁלֹּא נִתְפָּס וְלֹא נוֹדָע, פְּרָט לְאוֹתוֹ רָצוֹן שֶׁהַמַּחֲשָׁבָה תּוֹפֶסֶת וְלֹא יוֹדַעַת מַה תּוֹפֶסֶת, אֶלָּא שֶׁמֵּאִיר וּמִתְמַתֵּק אוֹתוֹ רְצוֹן הַמַּחֲשָׁבָה. וְהַכֹּל מִתְמַלֵּא וְהַכֹּל נִשְׁלָם וּמֵאִיר וּמִתְבַּשֵּׂם הַכֹּל כָּרָאוּי. וְעַל זֶה כָּתוּב (תהלים קמד) אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ וְגוֹ'."],[6,"","מִי שֶׁזּוֹכֶה לְהִדָּבֵק בְּרִבּוֹנוֹ כְּמוֹ זֶה, יוֹרֵשׁ אֶת כָּל הָעוֹלָמוֹת. אָהוּב לְמַעְלָה וְאָהוּב לְמַטָּה. תְּפִלָּתוֹ לֹא חוֹזֶרֶת רֵיקָם. זֶה מִתְחַטֵּא לִפְנֵי רִבּוֹנוֹ כְּמוֹ בֵּן לִפְנֵי אָבִיו וְעוֹשֶׂה לוֹ רָצוֹן בְּכָל מַה שֶּׁצָּרִיךְ, וְאֵימָתוֹ שׁוֹלֶטֶת עַל כָּל הַבְּרִיּוֹת. הוּא גוֹזֵר וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְקַיֵּם. עָלָיו כָּתוּב (איוב כב) וְתִגְזַר אֹמֶר וְיָקָם לָךְ וְעַל דְּרָכֶיךְ נָגַהּ אוֹר."],[7,"","וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וַיְהִי אוֹר וְגוֹ'. אָמַר רַבִּי יִצְחָק, מִכָּאן שֶׁעָקַר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַנְּטִיעוֹת הַלָּלוּ (ושתל אותם, ממשמע שכתוב יהי, רבי יהודה אומר, אור שכבר היה שנינו, ממשמע שכתוב ויהי אור, לא כתוב והיה אלא ויהי, וכשהסתכל הקדוש ברוך הוא באותם דורות של רשעים, גנזו לצדיקים, זהו שכתוב (תהלים צו) אור זרע לצדיק ולישרי לב שמחה, והרי נאמר ויאמר אלהים יהי אור, זהו שכתוב (ישעיה מא) מי העיר ממזרח וגו',"],[8,"","(וירא אלהים את האור כי טוב, מה ראה? אמר רבי חייא כפי שאמרנו, ראה במעשי הרשעים וגנז אותו, רבי אבא אמר, וירא אלהים את האור כי טוב לגנז אותו, וירא אלהים את האור), (נ\"א: ושתל אותם, שכתוב ויהי אור, מה משמיע אור? שכבר היה אור, רבי יהודה אומר, אור לא נאמר אלא ויהי, לומר שכבר היה, וכתוב אור זרע לצדיק וגו', וזהו שכתוב מי העיר ממזרח וגו', וירא אלהים את האור ויבדל, אמר רבי יצחק כמו שאמרנו, שראה במעשי הרשעים וגנז אותו, רבי אבא אמר ראה) שסלק אורו מסוף העולם ועד סוף העולם, וכי טוב הוא לגנזו כדי שלא יהנו ממנו רשעי העולם.)"]]],[["אָמַר רַבִּי שִׁמְעוֹן וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב דְּלָא יִשְׁתְּכַח בֵּיהּ רִתְחָא, כְּתִיב הָכָא כִּי טוֹב וּכְתִיב הָתָם (במדבר כ״ד:א׳) כִּי טוֹב בְּעֵינֵי יְיָ לְבָרֵךְ אֶת יִשְׂרָאֵל, וְסוֹפָא דִקְרָא (ד\"א אוכח) וַיַּבְדֵּל אֱלֹהִים בֵּין הָאוֹר וּבֵין הַחשֶׁךְ, וּבְּגִין כָּךְ לָא אִשְׁתְּכַח בֵּיהּ רִתְחָא וְאַף עַל גַּב דְּשִׁיתֵּף לוֹן קוּדְשָׁא בְּרִיךְ הוּא כְּחֲדָא.","תָּא חֲזֵי, נְהִירוּ עִלָּאָה לְמֶהוֵי נָהִיר הַאי אוֹר. וּמֵהַהוּא נְהִירוּ חַדוּ לְכֹלָּא בֵּיהּ. וְהוּא יָמִינָא לְאִתְעַטְּרָא גּוּלְפוֹי (נ\"א גליפי) גְּלִיפִין בַּהֲדֵיהּ וְהָא אִתְּמָר. כְּתִיב, (תהילים ל״א:כ׳) מָה רַב טוּבְךָ אֲשֶׁר צָפַנְתָּ לִירֵאֶיךָ פָּעַלְתָּ לַחוֹסִים בָּךְ. מָה רַב טוּבְךָ דָּא אוֹר קַדְמָאָה דְּגָנִיז קוּדְשָׁא בְּרִיךְ הוּא, לִירֵאֶיךָ לַצַּדִּיקִים לְאִנּוּן דַּחֲלֵי חַטָּאָה כִּדְקָאֲמָרָן.","וַיְהִי עֶרֶב וַיְהִי בֹקֶר יוֹם אֶחָד. וַיְהִי עֶרֶב מִסִּטְרָא דְחשֶׁךְ, וַיְהִי בֹקֶר מִסִּטְרָא דְאוֹר, וּמִגּוֹ דְּאִנּוּן מִשְׁתַּתְּפֵי כְּחֲדָא כְּתִיב יוֹם אֶחָד. רַבִּי יְהוּדָה אָמַר מַאי טַעֲמָא בְּכָל יוֹמָא וְיוֹמָא כְּתִיב וַיְהִי עֶרֶב וַיְהִי בֹקֶר. לְמִנְדַע דְּהָא לֵית יוֹם בְּלָא לַיְלָה וְלֵית לַיְלָה בְּלָא יוֹם וְלָא אִבְעוּן לְאִתְפְּרָשָׁא.","אָמַר רַבִּי יוֹסֵי הַהוּא יוֹם דְּנָפַק אוֹר קַדְמָאָה אִתְפְּשַׁט בְּכֻלְהוּ יוֹמֵי, דִּכְתִיב בְּכֻלְהוּ יוֹם. אָמַר רַבִּי אֶלְעָזָר מַשְׁמַע דִּכְתִיב בְּכֻלְהוּ בֹּקֶר, וְלָאו בֹּקֶר אֶלָא מִסִּטְרָא דְאוֹר קַדְמָאָה. רַבִּי שִׁמְעוֹן אָמַר יוֹמָא קַדְמָאָה אָזִיל עִם כֻּלְהוּ וְכֻלְהוּ בֵּיהּ, בְּגִין לְאַחֲזָאָה דְּלָאו בְּהוּ פִּירוּדָא וְכֹלָּא חַד.","וַיֹּאמֶר אֱלהִים יְהִי אוֹר, יְהִי (ד\"א ל\"גאור) אִתְפַּשְׁטוּתָא דְהַאי אוֹר לְתַתָּא, וְאִלֵּין אִנּוּן מַלְאָכִין דְּאִתְבְּרִיאוּ בְּיוֹמָא קַדְמָאָה אִית לוֹן קִיּוּמָא לְאִתְקַיְימָא לִסְטַר יָמִינָא. וַיַּרְא אֱלהִים אֶת הָאוֹר כִּי טוֹב. אֶת לְאִתְכְּלָלָא אִסְפַּקְלַרְיָאָה דְּלָא נָהֲרָא עִם אִסְפַּקְלַרְיָאָה דְּנָהֲרָא דְּאִתְּמָר (ד\"א ביה) כִּי טוֹב. אָמַר רַבִּי אֶלְעָזָר אֶת לְאִתְכְּלָלָא (ד\"א לאכללא) וּלְאַסְגָּאָה כֻּלְהוּ מַלְאָכִין דְּאַתְיָין מִסִּטְרָא דְּאוֹר דָּא, וְכֻלְהוֹן נָהֲרִין כְּקַדְמִיתָא בְּקִיּוּמָא שְׁלִים:","יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם, אָמַר רַבִּי יְהוּדָה בְּהַאי אִתְפְּרָשׁוּ (בראשית לב ב, יז ב) מַיִּין עִלָּאִין מִמַּיִין תַּתָּאִין. רָקִיעַ פְּשִׁיטוּתָא דְּמַיִּין וְהָא אִתְּמָר. וִיהִי מַבְדִיל בֵּין מַיִּין עִלָּאִין לְתַתָּאִין:","וַיַּעַשׂ אֱלֹהִים אֶת הָרָקִיעַ. בִּסְגִיאוּ עִלָּאָה. וַיְהִי רָקִיעַ לָא כְּתִיב, אֶלָּא וַיַּעַשׂ, דְּאַסְגֵּי לֵיהּ בִּרְבוּ סַגְיָא.","אָמַר רַבִּי יִצְחָק בַּשֵּׁנִי אִתְבְּרֵי גֵּיהִנֹּם לְחַיָּיבֵי עָלְמָא, בַּשֵּׁנִי אִתְבְּרֵי מַחְלוֹקֶת. בַּשֵּׁנִי לָא אִשְׁתְּלִים בֵּיהּ עֲבִידְתָּא, וּבְּגִין כָּךְ לָא כְּתִיב בֵּיהּ כִּי טוֹב, עַד דְּאֲתָא יוֹם תְּלִיתָאָה וְאִשְׁתְּלִים בֵּיהּ עֲבִידְתָּא, בְּגִין כָּךְ כִּי טוֹב תְּרֵי זִמְנֵי, חַד עַל אַשְׁלָמוּת עֲבִידְתָּא דְּיוֹם שֵׁנִי, וְחַד לְגַרְמֵיהּ. בְּיוֹם תְּלִיתָאֵי אִתְתַּקַּן יוֹם שֵׁנִי וְאִתְפְּרַשׁ בֵּיהּ מַחְלוֹקֶת. וּבֵיהּ אִשְׁתְּלִימוּ רַחֲמֵי עַל חַיָּיבֵי גֵּיהִנֹּם. בְּיוֹמָא תְּלִיתָאָה מִשְׁתַּכְּכִין שְׁבִיבִין דְּגֵיהִנֹּם. בְּגִינֵי כָּךְ אִתְכְּלִיל בֵּיהּ יוֹם שֵׁנִי וְאִשְׁתְּלִים בֵּיהּ.","רַבִּי חִיָּיא הֲוָה יָתִיב קַמֵּיהּ דְּרַבִּי שִׁמְעוֹן, אָמַר לֵיהּ הַאי אוֹר בְּיוֹם רִאשׁוֹן וְחשֶׁךְ בְּיוֹם שֵׁנִי וְאִתְפְּרָשׁוּ מַיָא וּמַחְלוֹקֶת הֲוָה בֵּיהּ, אַמַּאי לָא אִשְׁתְּלִים בְּיוֹם רִאשׁוֹן דְּהַאי יָמִינָא כָּלִיל לִשְׂמָאלָא, אָמַר לֵיהּ עַל דָּא הֲוָה מַחְלוֹקֶת, וּתְלִיתָאָה בָּעֵי לְמֵיעַל בֵּינַיְיהוּ לְאַכְרָעָא וּלְאַסְגָּאָה בְּהוּ שְׁלָם:","תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא, אִתְחַבְּרוּתָא דְּמַיִּין עִלָּאִין בְּתַתָּאִין לְמֶעְבַּד פֵּירִין. מַיִין עִלָּאִין (ד\"א פרין ורבין) וְעַבְדֵי אִיבִּין, וְתַתָּאֵי קָרָאן לוֹן לְעִלָּאִין כְּנוּקְבָא לְגַבֵּי דְכוּרָא, בְּגִין דְּמַיִין עִלָּאִין דְּכוּרִין וְתַתָּאֵי נוּקְבִין.","רַבִּי שִׁמְעוֹן אָמַר כָּל דָּא הוּא לְעֵילָא וְהוּא לְתַתָּא. אָמַר רַבִּי יוֹסֵי אִי הָכִי אֱלהִים דְּקָא אֲמָרָן (ד\"א אמר) מַאן אֱלהִים, (ד\"א ל\"ג אלא אלהים סתם) אֱלֹהִים חַיִּים לְעֵילָא, וְאִי תֵימָא לְתַתָּא אֱלֹהִים סְתָם. אֶלָּא לְתַתָּא אִיהוּ תּוֹלְדוֹת, כְּמָה דְאַתְּ אָמֵר אֵלֶּה תּוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם וְאַמְרִינָן בְּה' בְּרָאָם, וְהַהוּא (ס\"א דלעילא) לְעֵילָא אֲבָהָן דְּכֹלָּא הוּא אִיהִי עֲבִידְתָּא, וְעַל דָּא אַרְעָא עַבְדַת תּוֹלְדוֹת, דְּהָא הִיא מִתְעַבְּרָא כְּנוּקְבָא מִן דְּכוּרָא."],[[0,"אר\"ש וירא אלקים את האור כי טוב, דלא ישתכח ביה רתחא כתיב הכא כי טוב וכתיב התם","וכו': אר\"ש וירא אלקים וגו' פירושו, שראה שלא ימצא בו רוגז ודינים, ויליף גזרה שוה, כתוב כאן כי טוב, וכתוב אצל בלעם, כי טוב בעיני ה' לברך את ישראל, מה התם הפירוש שלא ישרה קללה על ישראל, כן כאן הפירוש הוא, שלא ימצא עוד שום רוגז ודינים \u0003וסופא דקרא אוכח, ויבדל אלקים בין האור ובין החשך, ובג\"כ לא אשתכח ביה רתחא,\u0004 וסופו של הכתוב מוכיח כן, שכתוב ויבדל אלקים בין האור ובין החשך, שהפירוש הוא \u0003אפריש מחלוקת למהוי כלא שלים,\u0004 (כנ\"ל בראשית א' דף נ' אות ל\"ו. ע\"ש) כן תחילת הכתוב סובב ג\"כ על ביטול הכעס והרוגז. \u0003ואע\"ג דשיתף לון קב\"ה כחדא,\u0004 ואע\"פ ששיתף הקב\"ה את האור והחשך שה\"ס ימין ושמאל כאחד על ידי קו אמצעי מ\"מ נתבטל הרוגז והמחלוקת. וע\"כ נאמר וירא אלקים את האור כי טוב, ואין בו שום כעס ורוגז."],[1,"ת\"ח נהירו עלאה, למהוי נהיר האי אור, ומההוא נהירו חדו לכלא ביה, והוא ימינא לאתעטרא גולפוי גליפין בהדיה והא אתמר:","בוא וראה, הארה עליונה, שהיא בינה הוא, שיהיה מאיר אור הזה, ומאור הזה נמשך שמחה לכל והוא בחינת ימין שמתעטר בחקיקי חקיקות, של השמאל. פירוש שבעת שהשמאל האיר בלי שיתוף הימין, האיר ברותחא וכעס ויצא ממנו גיהנם (כנ\"ל בראשית א' דף נ\"ז ד\"ה והנה אחר ע\"ש) וזה נבחן, שנעשו חקיקות בהארת קו שמאל, ומתוך כך השיג קו הימין כח לחבר אליו את קו השמאל ע\"י קו האמצעי, וקו הימין נתעטר בהארת החכמה שבקו שמאל, כמ\"ש שם בארוכה. \u0003כתיב מה רב טובך אשר צפנת ליראיך וגו' מה רב טובך דא אור קדמאה דגניז קב\"ה, ליראיך, לצדיקים דאינון דחלי חטאה כדקאמרן,\u0004 מה רב טובך סובב על אור הראשון שגנז הקב\"ה, ליראיך, היינו הצדיקים שהם יראי חטא, שרק הם יהנו מהאור ולא הרשעים כמו שאמרנו לעיל."],[2,"ויהי ערב וגו' ויהי ערב מסטרא דחשך, ויהי בקר מסטרא דאור, ומגו דאינון משתתפי כחדא כתיב יום אחד:","ויהי ערב שאומר הכתוב, נמשך מצד החשך, דהיינו הנוקבא, ויהי בקר, נמשך מצד האור, שהוא ז\"א, ומתוך שז\"א ונוקביה משתתפים יחד זה עם זה בזווג, ע\"כ כתוב בהם יום אחד. להורות שהערב ובקר הם כגוף אחד, ושניהם עושים את היום. כלומר, שאור היום בא מזווג ז\"א ונוקביה יחד."],[2,"רבי יהודה אמר, מ\"ט בכל יומא ויומא כתיב ויהי ערב ויהי בקר:","שואל כיון שויהי ערב ויהי בוקר יורה על זווג זו\"ן, שמשניהם יוצא אור היום, א\"כ אחר שהכתוב הודיע זה ביום א', מהו הטעם, שבכל יום ויום כתוב ויהי ערב ויהי בוקר. ומשיב \u0003למנדע דהא לית יום בלא לילה, ולית לילה בלא יום, ולא אבעון לאתפרשא,\u0004 לדעת שאין יום בלי לילה ואין לילה בלי יום ולא יבואו להתפרד זה מזה. כלומר ע\"כ חוזר הכתוב להודיענו זה בכל יום ויום, כדי להורות, שאי אפשר שיארע פעם שיהיה אור היום בלי הקדם חשך הלילה, וכן לא יארע חשך הלילה, שלא יביא אחריו אור היום. כי לא יתפרדו זה מזה לעולם."],[3,"א\"ר יוסי, ההוא יום דנפק אור קדמאה, אתפשט בכלהו יומי, דכתיב בכלהו יום, ר\"י אומר, אותו היום שהאור הא' יצא בו, הוא נתפשט בכל ימי בראשית, שהרי בכולם כתוב יום. פירוש. שהשם ","יום,\u0003 הוא על התפשטות אור הא' שיצא ביום א', שה\"ס ספירת החסד. אלא מתוך שאור הזה נתפשט בכל ימי בראשית, דהיינו בכל ספירה וספירה מז' הספירות, ע\"כ נקראים כולם יום כמו יום א'. \u0004אמר רבי אלעזר, משמע, דכתיב בכלהו בקר, ולאו בקר אלא מסטרא דאור קדמאה,\u0003 רבי אלעזר אומר, שהתפשטות האור דיום א' בכל הימים נלמד, מתוך שכתוב בכל הימים השם \u0004בקר,\u0003 כי אין שם זה שייך רק מצד אור הראשון, כלומר, כי השם בקר יורה על התחלת ביאת האור, שהוא רומז על ביאת אור הראשון בהמציאות. וכיון שכתוב השם בקר בבל יום, הרי שהתפשטות יום א' נוהג בכל יום. \u0004ר\"ש אמר, יומא קדמאה אזיל עם כלהו וכלהו ביה, בגין לאחזאה דלאו בהו פרודא וכלא חד: רבי שמעון אמר, יום ראשון הולך עם כל הימים, וכל הימים באים ביום הראשון, כדי להראות, שאין בהם פירוד וכולם הם אחד. כלומר, שז' הספירות חג\"ת נהי\"מ כלולים זה מזה וע\"כ יש בכל אחד מהם חג\"ת נהי\"מ, ונמצא שיש ספירת החסד, שהוא יום א', בכל ספירה, וכן היום א', שהוא ספירת החסד, יש בו עצמו כל חג\"ת נהי\"מ. הרי שיום א' נמצא בכל הימים, וכל הימים נמצאים ביום א', והוא מטעם היותם אחד בלי פירוד ביניהם."],[4,"ויאמר אלקים יהי אור, יהי, אתפשטותא דהאי אור לתתא ואלין אינון מלאכין דאתבריאו ביום א':","ויומר אלקים יהי אור, פירושו, שיהיה נמשך חתפשטותו של אור הזה למטה, ואלה הם המלאכים שנבראו ביום הראשון. \u0003אית לון קיומא לאתקיימא לסטר ימינא,\u0004 יש להם קיום להתקיים בצד ימין. כי יום א' הוא חסד, הנבחן לצד ימין, וע\"כ גם המלאכים הנמשכים בו הם בחינת ימין."],[4,"","פירוש. המלה \u0003יה\"י\u0004 מורה, אשר הי' דסוף המלה \u0003יה\"י,\u0004 נכנסה בי\"ה של המלה, ו\u0003אור\u0004 י\"ה נעשה משום זה ל\u0003אויר,\u0004 כמ\"ש לעיל, (בראשית א' דף מ\"ג ד\"ה יהי על רזא, ע\"ש,) ומסבה זו נתמעטו כל המדרגות עד שתנהי\"מ דזו\"ן נפלו לבי\"ע, (כנ\"ל בהקדמת הזהר דף ט\"ו ד\"ה והענין) ומבחינת התפשטות אור הזו\"ן לבי\"ע דפרודא, נבראו המלאכים. שהם אור נפרד מאצילות ונמצא שמלאכי חסד נבראו מהתמעטות יום א', שהוא חסד דז\"א. ומלאכי גבורה מהתמעטות יום ב', שהוא גבורה דז\"א. ומלאכי רחמים מהתמעטות יום ג', שהוא ת\"ת דז\"א. וכו' עד\"ז. וז\"ש \u0003יה\"י אתפשטותא דהאי אור לתתא,\u0004 דהיינו ע\"י המיעוט שנעשה בהמלה יה\"י, נתפשט חלק מהאור הזה, שהוא אור החסד, למטה בבי\"ע דפרודא. \u0003ואלין אינון מלאכין דאתבריאו ביומא קדמאה,\u0004 דהיינו שנבראו מהתמעטות אור ספירת החסד, שהוא יומא קדמאה, \u0003אית לון קיומא לאתקיימא לסטר ימינא,\u0004 יש להם משום זה קיום להתקיים לצד ימין, דהיינו שהם מלאכי ימין מצד החסד."],[4,"וירא אלקים וגו' את לאתכללא אספקלריאה דלא נהרא עם אספקלריאה דנהרא דאתמר ביה כי טוב:","וירא וגו' המלה א\"ת, של את האור, הוא לרבות ולכלול אספקלריאה דלא נהרא, שהיא הנוקבא, עם אספקלריאה דנהרא שהוא הז\"א, שנאמר בו כי טוב. כלומר, המלה \u0003את,\u0004 הוא לרבות שגם הנוקבא נכללה בהכתוב כי טוב, יחד עם הז\"א. \u0003אר\"א את לאתכללא ולאסגאה כלהו מלאכין דאתיין מסטרא דאור דא,\u0004 ר\"א אומר, שהמלה \u0003את\u0004 בא לכלול ולרבות כל המלאכים הנמשכים מצד אור זה של החסד, שגם הם נכללים בהכתוב כי טוב, \u0003וכלהון נהרין כקדמיתא בקיומא שלים,\u0004 וכולם מאירים כאור הראשון בקיום שלם. כי נכללים בהכתוב כי טוב הנאמר באור הראשון."],[5,"יהי רקיע בתוך המים אר\"י בהאי אתפרשו מיין עלאין ממיין תתאין:","אר\"י בזה, דהיינו בהמאמר יהי רקיע, נפרדו מים עליונים ממים תחתונים, \u0003רקיע פשיטותא דמיין והא אתמר, ויהי מבדיל בין מיין עלאין לתתאין,\u0004 רקיע פירושו התפשטות של מים, וע\"כ נאמר, ויהי מבדיל בין מים למים, דהיינו בין מים עליונים למים תחתונים, והיינו כמ\"ש לעיל (בראשית א' דף ס\"ד אות נ\"ט) \u0003יהי רקיע, אתפשט פשיטו דא מן דא,\u0004 וע\"ש בהסולם שנתבאר זה באורך."],[6,"ויעש אלקים את הרקיע דעביד ביה עבידתא בסגיאו עלאה:","הכתוב ויעש וגו', יורה, שעשה בו פעולה בגדלות שלמעלה, כלומר שהמשיך בו מוחין דגדלות מהבינה. כי בהמלה \u0003יהי רקיע\u0004 נעשה הכנה לקבלת המוחין העליונים דבינה אל הזו\"ן, והמלה ויעש, יורה על השלמת כל הנרצה, דהיינו שכבר נמשכו בהזו\"ן כל המוחין העליונים מהבינה. (כמ\"ש בהזהר לעיל בראשית א' דף ס\"א אות נ\"ג) וז\"ש \u0003ויהי רקיע לא כתיב, אלא ויעש, דאסגי ליה ברבו סגיא,\u0004 לא נאמר יהי רקיע וגו' ויהי רקיע, אלא אומר ויעש וגו' שלשון זה יורה, שהגדיל אותו בגדלות רבה. כמבואר."],[7,"א\"ר יצחק, בשני אתברי גיהנם לחייבי עלמא, בשני אתברי מחלוקת, בשני לא אשתלים ביה עבידתא:","אר\"י, ביום שני נברא הגיהנם לרשעי עולם בשני נברא המחלוקת (כמ\"ש בהזהר לעיל בראשית א' דף נ\"ו אות מ\"ד ונתבאר שם בהסולם) בשני לא נשלם בו המלאכה, אלא ביום ג' (כמ\"ש לעיל בראשית א' דף ס\"ו אות ס\"א) \u0003ובגין כך לא כתיב ביה כי טוב עד דאתא יומא תליתאה ואשתלים ביה עבידתא,\u0004 ומשום זה לא נאמר ביום ב', כי טוב, עד שבא יום הג' ונשלם בו המלאכה, \u0003בג\"כ כי טוב תרי זמני, חד על אשלמות עבידתא דיום ב', וחד לגרמיה,\u0004 ומשום זה נאמר ביום ג' ב' פעמים כי טוב, פעם אחד על השלמת מלאכת יום הב', ופעם אחד על השלמת מלאכתו עצמו. \u0003ביום תליתאי אתתקן יום שני, ואתפרש ביה מחלוקת, וביה אשתלימו רחמי על חייבי גיהנם,\u0004 ביום הג' נתתקן יום הב', והוכרע בו המחלוקת לקיום הארת שניהם (כמ\"ש בהסולם לעיל בראשית א' דף ס\"ו ד\"ה ואע\"ג) \u0003וביה אשתלימו רחמי על חייבי גיהנם,\u0004 ובו נשלם הרחמים על הרשעים שבגיהנם לפטרם מן הדין. \u0003ביומא תליתאה משתככין שביבין דגיהנם,\u0004 ביום הג' שוככים שביבי אש של הגיהנם, דהיינו שבהארת יום ג' הם מצטננים, ואינם שורפים יותר. \u0003בגיני כך, אתכליל ביה יום שני ואשתלים ביה,\u0004 ע\"כ נכלל בו יום הב' ונשלם בו."],[8,"ר' חייא הוה יתיב קמיה דר\"ש, א\"ל האי אור ביום ראשון וחשך ביום שני, ואתפרשו מיא ומחלוקת הוה ביה:","ר' חייא ישב לפני ר\"ש, אמר לו, הרי האור יצא ביום א', והחשך יצא ביום ב', והתחלקות המים והמחלוקת היה בו, \u0003אמאי לא אשתלים ביום ראשון, דהאי ימינא כליל לשמאלא,\u0004 למה לא נשלם כל זה בהארת יום א', שהרי הימין כולל את השמאל. כלומר כיון שאור הימין יצא ביום א', נמצא שהוא שורש אל יום הב' וכל שורש כולל בתוכו את הענף שלו ושולט עליו, וא\"כ היה יום הא' יכול לתקן אותו, ולמה נעשה יום הב' לנצרך אל יום הג' שיתקן אותו. והנפקא מינה גדול ביותר, כי ע\"י התקון של יום ג' נתמעט הארתו שאינו יכול להאיר ממעלה למטה, אלא ממטה למעלה בלבד, הנבחן לבחינת ו\"ק דג\"ר, כמ\"ש לעיל (בראשית א' דף ס' ד\"ה מחלוקת) ואם יום ב' היה מתתקן ע\"י יום א' היה נשאר בבחינתו ולא היה מתמעט כלום."],[8,"אמר ליה, על דא הוה מחלוקת, ותליתאה בעי למיעל בינייהו לאכרעה ולאסגאה בהו שלם,","והשיב לו ר\"ש, הלא על זה היה המחלוקת, דהיינו שבאמת היה יום א' רוצה לתקנו, כשורש המתקן את הענף. אלא שיום ב' לא רצה לקבל עליו שליטת יום הא', וחלק עליו עד שיום הג' היה צריך להכניס עצמו בין יום הא' ויום הב', להכריע המחלוקת, ולהרבות שלום בהם. וענין המחלוקת בין יום א' ליום ב', נתבאר בבראשית א' דף נ\"ז ד\"ה והנה אחר, ע\"ש."],[9,"תדשא הארץ דשא, אתחברותא דמיין עלאין בתתאין, למעבד פרין:","הכ' תדשא הארץ דשא, יורה על התחברות מים העליונים במים התחתונים כדי לעשות פירות, \u0003מיין עלאין ועבדי איבין ותתאי קראן לון לעלאין כנוקבא לגבי דכורא,\u0004 מים העליונים עושים הפירות, ומים התחתונים קוראים אל העליונים לקבל מהם הפירות ולהוציאם בהעולם, כיחס הנקבה אל הזכר, המקבלת ממנו הריון ומוציאה תולדות להעולם, \u0003בגין דמיין עלאין דכורין, ותתאי נוקבין,\u0004 משום שמים עליונים הם זכרים, ומים תחתונים הם נקבות. פירוש, כי נתבאר בהזהר לעיל (בהקדמת הזהר דף קצ\"ו ד\"ה כדין) שהמוחין דגדלות הנקראים פירות לא יוכלו להתגלות בהנוקבא שמחזה ולמעלה דז\"א, וע\"כ היא נקראת יבשה, שאינה ראויה להוצאות פירות. אלא אחר שנעשה הזווג בהנוקבא שמחזה ולמטה דז\"א. \u0003כדין מה דהוית יבשה למעלה מחזה, אתעבידת ארץ למעבד פירין ואיבין\u0004 למטה מחזה דז\"א עש\"ה בטעמו ונימוקו. והנה מחזה ולמעלה דז\"א נקרא מים עליונים, ומחזה ולמטה דז\"א נקרא מים תחתונים, כי הרקיע המבדיל בין מים עליונים לתחתונים עומד במקום החזה, כנ\"ל. ונמצא אע\"פ שהמוחין יוצאים בהנוקבא שלמעלה מחזה דז\"א, בסו\"ה יקוו המים אשר מתחת השמים אל מקום אחד ותראה \u0003היבשה,\u0004 כמ\"ש שם בזהר, ששם מים עליונים, מ\"מ לא יוכלו להתגלות שם, והם שם בבחינת \u0003יבשה,\u0004 ומקום הגילוי הוא רק בהמקום שמחזה ולמטה, ששם מים התחתונים."],[9,"","וזה אמרו כאן \u0003מיין עלאין עבדי אבין,\u0004 שהמוחין המכונים פירות, באים מכח הזווג העליון שלמעלה מחזה דז\"א, בסו\"ה יקוו המים אל מקום אחד, אלא שלא יוכל להתגלות משם, כי שם הם בסוד \u0003יבשה\u0004 כנ\"ל, ולפיכך \u0003ותתאי קראן לון לעלאין כנוקבא לגבי דכורא,\u0004 כמו שזרע הזכר אין לו כח להתגלות בו אלא בהנוקבא, שבה ההריון והלידה, כן המוחין שבמים העליונים לא יוכלו להתגלות במקומם אלא במחזה ולמטה כנ\"ל, הנקרא מים תחתונים ולכן הם קוראים למים העליונים שישפיעו בהם המוחין ויתגלו בעולמות על ידיהם."],[10,"רבי שמעון אמר, כל דא הוא לעילא והוא לתתא:","ר\"ש אומר כל זה הוא למעלה מחזה דז\"א והוא למטה מחזה דז\"א כלומר, שענין מים עליונים ותחתונים נוהג הן מחזה ולמעלה והן מחזה ולמטה. כי יש דכר ונוקבא למעלה מחזה, הנק' ז\"א ולאה, שהדכר הוא מים עליונים, והנוקבא היא מים תחתונים. וכן יש דו\"נ למטה מחזה, הנק' יעקב ורחל שיעקב ה\"ס מים עליונים ורחל ה\"ס מים תחתונים. ולדברי ר\"ש יהיה פירושו של הכ' תדשא הארץ דשא, על התחברות מים עליונים ותחתונים שמחזה ולמטה דז\"א, כי אין לפרש הכתוב על מים עליונים ותחתונים שמחזה ולמעלה, כי שם הוא מקום יבשה, ואינה מוציאה דשא ופירות. כנ\"ל."],[10,"א\"ר יוסי אי הכי, אלקים דקא אמרן מאן אלקים אלקים חיים לעילא, ואי תימא לתתא אלקים סתם:","אר\"י. אם כן, אלקים הנאמר בהכתוב, דהיינו ויאמר אלקים תדשא וגו', מי הוא השם אלקים שבהכתוב, הלא הוא אלקים חיים, בינה שלמעלה, כי כל ל\"ב שמות אלקים שבמעשה בראשית הם בינה, כנודע, ואם תאמר ותפרש הכתוב למטה, דהיינו במים עליונים ותחתונים שלמטה מחזה, כמ\"ש לעיל לדברי ר\"ש, א\"כ יהיה השם אלקים שבהכתוב \u0003אלקים סתם,\u0004 דהיינו הנוקבא לאה שלמעלה מחזה, הנקראת סתם אלקים ולא אלקים חיים, שהיא בינה. שזהו כנגד המקובל שכל ל\"ב אלקים שבמ\"ב הם שמות הבינה שהיא אלקים חיים. פירוש, כי הכ' ויאמר אלקים תדשא, הוא בהכרח מדרגה הקודמת, להמים עליונים הללו ומרומזים בהמלות תדשא הארץ דשא, כי כל מדרגה מתפעלת ונעשית ע\"י העליונה הסמוכה לה, ואם פירושו של תדשא הארץ דשא הוא על הפעלת מים עליונים שלמעלה מחזה שיתחברו עם מים תחתונים אשר שם, הרי השם אלקים שהפעיל אותם היא בינה הנקראת אלקים חיים. אבל אם פירושו של תדשא הארץ דשא הוא על הפעלת מים עליונים שלמטה מחזה, נמצא שהכ' ויאמר אלקים קאי על מדרגה העליונה הסמוכה לה. שהיא הנוקבא שלמעלה מחזה, הנקראת סתם אלקים ולא אלקים חיים כהבינה, שהוא כנגד המקובל שכל השמות אלקים שבמ\"ב הם בינה."],[10,"אלא לתתא איהו תולדות, כד\"א, אלה תולדות וגו' ואמרינן בה' בראם, וההוא לעילא אבהן דכלא הוא, איהי עבידתא:","אלא, אר\"י, למטה מחזה הוא מקום התולדות, כמ\"ש אלה תולדות וגו' ואמרינן בה' בראם דהיינו הנוקבא שמחזה ולמטם שה\"ס רחל שהיא ה' אחרונה דשם הויה, וכל התולדות ממנה הם, ולא מהנוקבא שמחזה ולמעלה, וההוא שלמעלה מחזה, הם אבות של כל המדרגות, דהיינו שהם ג\"ס חג\"ת הנבחנים לאבות ושרשים להעולמות, כי כל המקובל להעולמות באים מהם, והיא, דהיינו הנוקבא שלהם, נבחנת להשלמת המלאכה, של כל התולדות, ולא ליציאת התולדות בפועל להעולמות. כלומר המוחין בעצם וכל מלאכתם נשלמים בדכר ונוקבא שלמעלה מחזה, אשר הדכר, הם חג\"ת הנקראים אבות, והנוקבא שלהם היא לאה. אמנם עדיין אינם מתגלים ובאים מהם להעולמות שיהיו ניכרים בבחינת תולדות, להיות הנוקבא בסוד יבשה כנ\"ל, אלא רק בהנוקבא שלמטה מחזה, הנקראת ה' שעליה נאמר בה' בראם, בה יוצאים התולדות בפועל. ולפי זה מתבאר הכתוב תדשא במים עליונים שלמעלה מחזה, ולא תולדות ממש, אלא להשלמת המלאכה בלבד, כי הנוקבא שלמעלה מחזה עוד אינה מוציאה המוחין בבחינת תולדות ממש. ובזה מתורץ הקושיא, כי השם אלקים שבהכתוב הוא באמת על הבינה, הנקראת אלקים חיים שהיא מדרגה העליונה הסמוכה להם. כנ\"ל בדיבור הסמוך."],[10,"ועל דא ארעא עבדת תולדות, דהא היא מתעברא כנוקבא מן דכורא:","ומשום זה עושה הארץ תולדות, כי היא מתעברת כמו נקבה מן הזכר. משום שהנוקבא העליונה השלימה המלאכה של המוחין, יכולה הנוקבא התחתונה, שלמטה מחזה הנקראת ארץ, לעשות פירות, כי היא מקבלת אותם כמו נקבה המתעברת מהזכר ומוציאה תולדותיו לגילוי. ולפי\"ז יתבאר הכתוב תדשא הארץ דשא, לזווג מים עליונים ותחתונים שלמעלה מחזה, שהוא להשלמת מלאכת המוחין, והכ' ותוצא הארץ דשא, הוא בהזווג של מים עליונים ותחתונים שמחזה ולמטה, להתגלות התולדות ששם מתגלים התולדות ממה שקבלה מהעליונה."]],[[0,"","אָמַר רַבִּי שִׁמְעוֹן, וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב, שֶׁלֹּא יִמָּצֵא בּוֹ רִתְחָה. כָּתוּב כָּאן כִּי טוֹב, וְכָתוּב שָׁם (במדבר כד) כִּי טוֹב בְּעֵינֵי ה' לְבָרֵךְ אֶת יִשְׂרָאֵל, וְסוֹף הַפָּסוּק (מוכיח) - וַיַּבְדֵּל אֱלֹהִים בֵּין הָאוֹר וּבֵין הַחֹשֶׁךְ. וְלָכֵן לֹא נִמְצְאָה בּוֹ רִתְחָה, וְאַף עַל גַּב שֶׁשִּׁתֵּף אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא כְּאֶחָד."],[1,"","בֹּא רְאֵה, הָאוֹר עֶלְיוֹן לִהְיוֹת מֵאִיר הָאוֹר הַזֶּה, וּמֵאוֹתוֹ אוֹר שִׂמְחָה לַכֹּל בּוֹ. וְהוּא יָמִין לְהִתְעַטֵּר חֲקִיקוֹתָיו (חקוקיו) חֲקוּקִים יַחַד אִתּוֹ, וַהֲרֵי נֶאֱמַר. כָּתוּב (תהלים לא) מָה רַב טוּבְךְ אֲשֶׁר צָפַנְתָּ לִּירֵאֶיךְ פָּעַלְתָּ לַחוֹסִים בָּךְ. מָה רַב טוּבְךְ - זֶה אוֹר רִאשׁוֹן שֶׁגָּנַז הַקָּדוֹשׁ בָּרוּךְ הוּא. לִּירֵאֶיךְ - לַצַּדִּיקִים, שֶׁהֵם יִרְאֵי חֵטְא כְּמוֹ שֶׁאָמַרְנוּ."],[2,"","וַיְהִי עֶרֶב וַיְהִי בֹקֶר יוֹם אֶחָד. וַיְהִי עֶרֶב - מִצַּד הַחֹשֶׁךְ. וַיְהִי בֹקֶר - מִצַּד הָאוֹר. וּמִתּוֹךְ שֶׁהֵם מִשְׁתַּתְּפִים כְּאֶחָד, כָּתוּב יוֹם אֶחָד. רַבִּי יְהוּדָה אָמַר, מָה הַטַּעַם בְּכָל יוֹם וָיוֹם כָּתוּב וַיְהִי עֶרֶב וַיְהִי בֹקֶר? לָדַעַת שֶׁהֲרֵי אֵין יוֹם בְּלִי לַיְלָה וְאֵין לַיְלָה בְּלִי יוֹם, וְלֹא צְרִיכִים לְהִפָּרֵד."],[3,"","אָמַר רַבִּי יוֹסֵי, אוֹתוֹ הַיּוֹם שֶׁיָּצָא אוֹר רִאשׁוֹן, הִתְפַּשֵּׁט בְּכָל הַיָּמִים, שֶׁכָּתוּב בְּכֻלָּם יוֹם. אָמַר רַבִּי אֶלְעָזָר, מַשְׁמָע שֶׁכָּתוּב בְּכֻלָּם בּקֶר, וְאֵין בֹּקֶר אֶלָּא מִצַּד שֶׁל אוֹר רִאשׁוֹן. רַבִּי שִׁמְעוֹן אָמַר, יוֹם רִאשׁוֹן הוֹלֵךְ עִם כֻּלָּם, וְכֻלָּם בּוֹ, כְּדֵי לְהַרְאוֹת שֶׁאֵין בָּהֶם פֵּרוּד וְהַכֹּל אֶחָד."],[4,"","וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר, תִּהְיֶה הִתְפַּשְּׁטוּת הָאוֹר הַזֶּה לְמַטָּה, וְאֵלֶּה הֵם הַמַּלְאָכִים שֶׁנִּבְרְאוּ בַּיּוֹם הָרִאשׁוֹן, יֵשׁ לָהֶם קִיּוּם לְהִתְקַיֵּם לְצַד יָמִין. וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב, אֶת - לִכְלֹל אֶת הָאַסְפַּקְלַרְיָה שֶׁלֹּא מְאִירָה עִם אַסְפַּקְלַרְיָה מְאִירָה, שֶׁנֶּאֱמַר (בו) כִּי טוֹב. אָמַר רַבִּי אֶלְעָזָר, אֶת - לִכְלֹל (להכליל) וּלְרַבּוֹת אֶת כָּל הַמַּלְאָכִים שֶׁבָּאִים מִצַּד הָאוֹר הַזֶּה, וְכֻלָּם מְאִירִים כְּבַתְּחִלָּה בְּקִיּוּם שָׁלֵם."],[5,"","יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם. אָמַר רַבִּי יְהוּדָה, בָּזֶה נִפְרְדוּ מַיִם עֶלְיוֹנִים מִמַּיִם תַּחְתּוֹנִים. רָקִיעַ - הִתְפַּשְּׁטוּת הַמַּיִם, וַהֲרֵי נֶאֱמַר. וִיהִי מַבְדִּיל - בֵּין מַיִם עֶלְיוֹנִים לַתַּחְתּוֹנִים."],[6,"","וַיַּעַשׂ אֱלֹהִים אֶת הָרָקִיעַ - בְּמַעֲלָה עֶלְיוֹנָה. וַיְהִי רָקִיעַ לֹא כָתוּב, אֶלָּא וַיַּעַשׂ, שֶׁהִגְדִּיל אוֹתוֹ בְּגַדְלוּת רַבָּה."],[7,"","אָמַר רַבִּי יִצְחָק, בַּשֵּׁנִי נִבְרָא גֵיהִנֹּם לְרִשְׁעֵי הָעוֹלָם. בַּשֵּׁנִי נִבְרְאָה מַחֲלֹקֶת. בַּשֵּׁנִי לֹא נִשְׁלַם בּוֹ הַמַּעֲשֶׂה, וְלָכֵן לֹא כָתוּב בּוֹ כִּי טוֹב, עַד שֶׁבָּא יוֹם שְׁלִישִׁי וְנִשְׁלַם בּוֹ הַמַּעֲשֶׂה. מִשּׁוּם כָּךְ כִּי טוֹב פַּעֲמַיִם, אֶחָד עַל הַשְׁלָמַת הַמַּעֲשֶׂה שֶׁל יוֹם שֵׁנִי, וְאֶחָד לְעַצְמוֹ. בַּיּוֹם הַשְּׁלִישִׁי הִתְתַּקֵּן הַיּוֹם הַשֵּׁנִי וְנִבְדְּלָה בוֹ מַחֲלֹקֶת, וּבוֹ הִשְׁתַּלְּמוּ רַחֲמִים עַל רִשְׁעֵי הַגֵּיהִנֹּם. בַּיּוֹם הַשְּׁלִישִׁי מִשְׁתַּכְּכִים שַׁלְהֲבוֹת הַגֵּיהִנֹּם. מִשּׁוּם כָּךְ נִכְלַל בּוֹ שֵׁנִי וְנִשְׁלַם בּוֹ."],[8,"","רַבִּי חִיָּיא הָיָה יוֹשֵׁב לִפְנֵי רַבִּי שִׁמְעוֹן. אָמַר לוֹ, אוֹר זֶה בְּיוֹם רִאשׁוֹן, וְחֹשֶׁךְ בְּיוֹם שֵׁנִי, וְנִפְרְדוּ הַמַּיִם וּמַחֲלֹקֶת הָיְתָה בּוֹ, לָמָּה לֹא נִשְׁלַם בַּיּוֹם הָרִאשׁוֹן, שֶׁהֲרֵי יָמִין כּוֹלֵל אֶת הַשְּׂמֹאל? אָמַר לוֹ, עַל זֶה הָיְתָה מַחֲלֹקֶת, וּשְׁלִישִׁי רָצָה לְהִכָּנֵס בֵּינֵיהֶם לְהַכְרִיעַ וּלְהַרְבּוֹת בָּהֶם שָׁלוֹם."],[9,"","תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא - הִתְחַבְּרוּת שֶׁל מַיִם עֶלְיוֹנִים בַּתַּחְתּוֹנִים לַעֲשׂוֹת פֵּרוֹת. מַיִם עֶלְיוֹנִים (ד\"א פרים ורבים) וְעוֹשִׂים פֵּרוֹת, וְהַתַּחְתּוֹנִים קוֹרְאִים לָהֶם לָעֶלְיוֹנִים כִּנְקֵבָה לַזָּכָר, מִשּׁוּם שֶׁמַּיִם עֶלְיוֹנִים זְכָרִיִּים, וְתַחְתּוֹנִים נְקֵבִיִּים."],[10,"","רַבִּי שִׁמְעוֹן אָמַר, כָּל זֶה הוּא לְמַעְלָה וְהוּא לְמַטָּה. אָמַר רַבִּי יוֹסֵי, אִם כָּךְ, אֱלֹהִים שֶׁאָמַרְנוּ (ד\"א אמר) מִי הָאֱלֹהִים? (ד\"א אלא אלהים סתם) אֱלֹהִים חַיִּים לְמַעְלָה. וְאִם תֹּאמַר אֱלֹהִים לְמַטָּה סְתָם, אֶלָּא לְמַטָּה הוּא תוֹלָדוֹת, כְּמוֹ שֶׁנֶּאֱמַר אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם. וְאָמַרְנוּ בְּה' בְּרָאָם. וְאוֹתוֹ (שלמעלה) לְמַעְלָה אֲבִיהֶם שֶׁל הַכֹּל הוּא, הִיא הָעֲשִׂיָּה, וְעַל זֶה הָאָרֶץ עוֹשָׂה תוֹלָדוֹת, שֶׁהֲרֵי הִיא מִתְעַבֶּרֶת כִּנְקֵבָה מִן הַזָּכָר."]]],[["רַבִּי אֶלְעָזָר אָמַר כָּל חֵילִין הֲווּ בְּאַרְעָא וְלָא אַפִּיקַת חֵילָהָא וְאִנּוּן תּוֹלְדוֹתֶיהָ עַד יוֹם (חמישי) הַשִּׁשִּׁי דִּכְתִיב תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה, וְאִי תֵימָא וְהָא כְּתִיב וַתּוֹצֵא הָאָרֶץ דֶּשֶׁא. אֶלָּא אֲפִיקַת תִּקּוּן חֵילָהָא לְאִתְיַישְׁבָא כְּדְקָא יָאוּת וְכֹלָּא הֲוָה גָּנִיז בֵּהּ עַד דְּאִצְטְרִיךְ. דְּהָא בְּקַדְמִיתָא כְּתִיב צַדְיָיא וְרֵיקַנְיָא כְּתַרְגּוּמוֹ, וּלְבָתַר אִתְתַּקָּנַת וְאִתְיַישְׁבַת וְקַבִּילַת זַרְעָא וּדְשָׁאִין וְעִשְׂבִין וְאִילָנִין כְּדְקָא יָאוּת, וְאַפִּיקַת לוֹן לְבָתָר. וּמְאוֹרוֹת הָכִי נָמֵי לָא שִׁמְשׁוּ נְהוֹרָא דִּלְהוֹן עַד דְּאִצְטְרִיךְ:","יְהִי מְאֹרֹת בִּרְקִיעַ הַשָּׁמָיִם (ד\"א מארת כתיב חסר), לְאַכְלָלָא חִוְיָא בִישָׁא דְּאַטִּיל זוּהֲמָא וְעֲבַד פִּירוּדָא דְּלָא מְשַׁמֵּשׁ שִׁמְשָׁא בְּסִיהֲרָא. מְאֹרֹת לְוָוטִין, וְעַל דָּא גָּרִים דְּאִתְלַטְיָיא אַרְעָא דִּכְתִיב אֲרוּרָה הָאֲדָמָה, וּבְגִין כָּךְ מְאֹרֹת כְּתִיב, (חד),","יְהִי מְאֹרֹת דָּא סִיהֲרָא. רְקִיעַ הַשָּׁמָיִם דָּא שִׁמְשָׁא, וְתַרְוַויְיהוּ בִּכְלָלָא חָדָא לְאִזְדַּוְוגָא לְאַנְהָרָא עָלְמִין לְעֵילָא וְתַתָּא. מַשְׁמַע דִּכְתִיב עַל הָאָרֶץ וְלָא כְּתִיב בָּאָרֶץ דְּמַשְׁמַע לְעֵילָא וְתַתָּא, חוּשְׁבַּן דְּכֹלָּא בְּסִיהֲרָא הוּא.","רַבִּי שִׁמְעוֹן אָמַר גִּימַטְרִיָּאוֹת וְחֶשְׁבּוֹן תְּקוּפוֹת וְעִבּוּרִין כֹּלָּא הוּא בְּסִיהֲרָא, דְּהָא לְעֵילָא לָאו אִיהוּ. אָמַר לֵיהּ רַבִּי אֶלְעָזָר וְלָא וְהָא כַּמָּה חוּשְׁבְּנִין וְשִׁיעוּרִין קָעָבְדֵי חַבְרַיָיא. אָמַר לֵיהּ לָאו הָכִי, אֶלָּא חוּשְׁבָּנָא קָיְימָא בְּסִיהֲרָא וּמִתַּמָּן יֵעוּל בַּר נָשׁ לְמִנְדַע לְעֵילָא. אָמַר לֵיהּ וְהָא כְּתִיב וְהָיוּ לְאוֹתוֹת וּלְמוֹעֲדִים. אָמַר לֵיהּ לְאֹתֹת כְּתִיב חָסֵר. אָמַר לֵיהּ הָא כְּתִיב וְהָיוּ, אָמַר לֵיהּ הַוְיָין כֻּלְהוֹן דִּיהָווֹן בֵּיהּ, כְּאִסְפּוּקָא דָּא דְּאִתְמַלְיָיא מִכֹּלָּא, אֲבָל חוּשְׁבְּנָא דְּכֹלָּא בְּסִיהֲרָא הוּא.","תָּא חֲזֵי, נְקוּדָה חַד אִית וּמִתַּמָּן שֵׁירוּתָא לְמִמְנֵי, דְּהָא מַה דִּלְגוֹ דְּהַהִיא נְקוּדָה לָא אִתְיְדַע וְלָא אִתְיְיהַב לְמִמְנֵי, וְאִית נְקוּדָה לְעֵילָא סָתִים דְּלָא אִתְגַּלְיָא כְּלַל וְלָא אִתְיְדַע וּמִתַּמָּן שֵׁרוּתָא לְמִמְנִי כָּל סָתִים וְעוּמְקָא. הָכִי נָמֵי אִית נְקוּדָה לְתַתָּא דְּאִתְגַּלְיָא, וּמִתַּמָּן הוּא שֵׁירוּתָא לְכָל חוּשְׁבְּנָא וּלְכָל מִנְיָן, וְעַל דָּא הָכָא הוּא אֲתַר לְכָל תְּקוּפוֹת וְגִימַטְרִיָּאוֹת וְעִבּוּרִין וְזִמְנִין וְחַגֵּי וְשַׁבַּתֵּי. וְיִשְׂרָאֵל דְּדָבְקֵי בְּקוּדְשָׁא בְּרִיךְ הוּא עָבְדֵי חוּשְׁבַּן לְסִיהֲרָא וְאִנּוּן דָּבְקִין בֵּיהּ וְסָלְקִין לֵיהּ לְעֵילָא, דִּכְתִיב, (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּיְיָ אֱלקֵיכֶם וְגו':","יִשְׁרְצוּ הַמַּיִם שֶׁרֶץ נֶפֶשׁ חַיָה, אָמַר רַבִּי אֶלְעָזָר הָא אוּקְמוּהָ דְּאִנּוּן מַיִין רְחִישׁוּ וְאוֹלִידוּ כְּגַוְונָא דִּלְעֵילָא וְהָא אִתְּמָר. וְעוֹף יְעוֹפֵף עַל הָאָרֶץ. יָעוּף מִבָּעֵי לֵיהּ, מַהוּ יְעוֹפֵף.","אָמַר רַבִּי שִׁמְעוֹן רָזָא הוּא. וְעוֹף דָּא מִיכָאֵ\"ל דִּכְתִיב, (ישעיהו ו׳:ו׳) וַיָּעָף אֵלַי אֶחָד מִן הַשְּׂרָפִים. יְעוֹפֵף (ד\"א ל\"ג יעוף מבעי ליה אלא) דָּא גַּבְרִיאֵ\"ל דִּכְתִיב, (דניאל ט׳:כ״א) וְהָאִישׁ גַּבְרִיאֵל אֲשֶׁר רָאִיתִי בֶחָזוֹן בַּתְּחִלָּה מוּעָף בִּיעָף. (ד\"א ל\"ג ודא הוא יעופף), עַל הָאָרֶץ (נ\"א דא אליהו דאשתכח תדיר בארעא ולא מסטרא דאבא ואמא אשתכח דאיהו (ס\"א ואיהו טאס עלמא) בד' טאסין דכתיב, (מלכים א י״ח:י״ב) ורוח ה' ישאך על אשר לא אדע. ורוח ה' חד. ישאך תרין. על אשר תלת, לא אדע ארבע. על פני דא מלאך המות) דְּהוּא (אית דלא גרסי) (חשוך ארעא. על פני) (נ\"א אחשיך פני עלמא וכתיב ביה וחשך על פני תהום), רְקִיעַ הַשָּׁמָיִם. כִּדְאֲמָרָן עוֹלֶה וּמַסְטִין וְכוּ'.","אָמַר רַבִּי אַבָּא וְהָא מַלְאַךְ הַמָּוֶת בַּשֵּׁנִי אִתְבְּרֵי. אֶלָּא עַל הָאָרֶץ דָּא רְפָאֵ\"ל דְּאִיהוּ מְמַנָּא לְאַסְוָותָא דְאַרְעָא דִּבְגִינֵיהּ אִתְרַפִּיאַת אַרְעָא וְקַיָּים בַּר נָשׁ עֲלָהּ וְרָפֵי לְכָל חֵילֵיהּ. עַל פְּנִי רְקִיעַ הַשָּׁמָיִם דָּא אוֹרִיאֵ\"ל, וְכֹלָּא הוּא בַּקְּרָא.","וּבְגִין כָּךְ כְּתִיב בַּתְרֵיהּ וַיִּבְרָא אֱלהִים אֶת הַתַּנִּינִים הַגְּדוֹלִים. אָמַר רַבִּי אֶלְעָזָר (ד\"א הא אוקימנא אלין לויתן ובת זוגו.) אִלֵּין אִנּוּן שִׁבְעִין מְמַנָּן רַבְרְבָן עַל שִׁבְעִין עַמִּין, וּבְגִין כָּךְ אִתְבְּרִיאוּ כֻּלְהוּ לְמֶהֱוֵי שַׁלִּיטָאן עַל אַרְעָא."],[[0,"רבי אלעזר אמר, כל חילין הוו בארעא, ולא אפיקת חילהא ואנון תולדותיה, עד יום הששי דכתיב תוצא הארץ","וגו': ר\"א אמר, כל הכחות היו נגמרים בהארץ, שהיא מלכות, והיא לא הוציאה הכחות, שהם תולדות שלה, כלומר שלא הוציאה אותם מן הכח אל הפועל, עד יום הששי, שאז נאמר תוצא הארץ נפש חיה וגו'. דהיינו שהוציאה הכחות שבה אל הפועל ונעשו נפש חיה וכו'. \u0003ואי תימא והא כתיב ותוצא הארץ דשא, אלא אפיקת תיקון חילהא לאתיישבא כדקא יאות,\u0004 ואם תאמר, הרי כתוב ותוצא הארץ דשא, שמשמע שיצאו ונגלו בפועל ממש אלא הפירוש הוא, שהוציאה תקון הכחות להתישב בה ולהגמר כראוי, באופן שתוכל להוציא אותם ביום הששי \u0003וכלא הוה גניז בה עד דאצטריך,\u0004 והכל היה גנוז בה. ולא נגלו עד שהוצרך לגלות, דהיינו ביום הששי, \u0003דהא בקדמיתא כתיב צדייא וריקניא כתרגומו,\u0004 שהרי בתחילה כתוב, והארץ היתה תהו ובהו, שתרגומו צדיא וריקניא, דהיינו שהיתה חרבה לגמרי, \u0003ולבתר אתתקנת ואתיישבת וקבילת זרעא ודשאין ועשבין ואלנין כדקא יאות,\u0004 ואח\"כ, דהיינו ביום ג', נתקנה הארץ ונתישבה, וקבלה זרע ודשאים ועשב ואילנות כראוי, \u0003ואפיקת לון לבתר,\u0004 והוציאה אותם לעולם לאח\"כ, דהיינו ביום הששי כנ\"ל, \u0003ומאורות הכי נמי, לא שמשו נהורא דלהון עד דאצטריך\u0004 ומאורות גם כן, לא שימש האור שלהם בהעולם עד שהוצרך. פירוש, שהאור נברא ביום א', מ\"מ לא נגלה האור לעולם עד יום ד', שנתלו בו המאורות להאיר על הארץ."],[1,"יהי מארת וגו' לאכללא חויא בישא, דאטיל זוהמא ועבד פרודא דלא משמש שמשא בסיהרא:","הכתוב יהי מארת וגו' בא לכלול את הנחש הרע שהטיל זוהמא ועשה פירוד שלא יזדווג השמש עם הלבנה, פירוש, כי בכל המדרגות הקודמות להנוקבא, יורה \u0003יה\"י,\u0004 ענין מיעוט ונפילת ג' הכלים בינה ותו\"מ להמדרגה שלמטה, אמנם לא נפלו הכלים מחוץ לאצילות. מה שאין כן בהנוקבא, שהיא מדרגה תחתונה מכל המדרגות דאצילות, א\"כ כשנאמר \u0003יה\"י,\u0004 ונפלו הכלים שלה, הרי נפלו למטה מפרסא דאצילות, לבי\"ע דפרודא, וע\"כ נבראו מכח הנפילה הזו הקליפות ונחש הרע (כמ\"ש לעיל בראשית א' דף צ\"ו ד\"ה ביאור ע\"ש)"],[1,"מארת לווטין, וע\"ד גרים דאתלטייא ארעא, דכתיב ארורה האדמה:","וע\"כ כתוב מארת חסר ו', שפירושו קללות, כי הנחש גרם שתתקלל הארץ, שכתוב ארורה האדמה וגו'. כלומר, שהנחש הסית להחטא דעצה\"ד שמחמתו נתקללה הארץ, וע\"כ כתוב מארת חסר ו', שיורה על קללה זו שנתקללה הארץ בסבת הנחש שנברא ע\"י המיעוט דנה\"י, כנ\"ל, \u0003ובגין כך מארת כתיב,\u0004 ומשום זה כתוב בתורה מארת חסר ו', שהוא לשון קללה."],[2,"חד, יהי מארת, דא סיהרא, רקיע השמים דא שמשא:","יהי מארת, משמעותו מאור אחד, להיותו חסר ו', והיא מאור הלבנה, והכ' רקיע השמים, הוא מאור השמש. \u0003ותרווייהו בכללא חדא, לאזדווגא לאנהרא עלמין לעילא ותתא\u0004 וכללם הכתוב שניהם בכלל אחד, כי נאמר יהי מארת ברקיע השמים, להורות, שמזדווגים השמש והלבנה, להאיר העולמות, למעלה מחזה דז\"א. ולמטה מחזה דז\"א. \u0003משמע דכתיב על הארץ, ולא כתיב בארץ דמשמע לעילא ותתא, חושבן דכלא בסיהרא הוא,\u0004 ומשמע, ממ\"ש על הארץ, ואינו כתוב להאיר בארץ, שיהיה נשמע שמאיר למעלה ולמטה, שהוא להורות, שהחשבון של כולם הוא בהלבנה. פירוש. כי לפי מה שביאר הכ' יהי מארת ברקיע השמים, שיורה על זווג השמש ולבנה שהם זו\"ן למעלה מחזה ולמטה מחזה דז\"א, א\"כ היה צריך לומר להאיר בארץ, כמו שאומר, ברקיע השמים, שמשמעותו היה, שמזדווג גם למטה מחזה דז\"א ששם הנוקבא התחתונה הנקראת ארץ, ולמה כתוב על הארץ, שמשמעותו שהזווג הוא רק למעלה ברקיע השמים, דהיינו במקום הפרסא שמחזה ולמעלה דז\"א דוקא, הנק' רקיע, ומשם נמשך ההארה אל הארץ, דהיינו למטה מחזה, אבל בארץ עצמו אין זווג. ואומר, שהוא להורות כי \u0003חושבנא דכלא סיהרא הוא,\u0004 פירוש, כי המוחין דחשבון ומספר של כל המדרגות, יוצאים על ידי זווג שמש ולבנה. כי יש מוחין שהם אור חסדים והם מכונים בשם בלי מספר, ויש מוחין דהארת חכמה, שהם מכונים בשם מספר וחשבון, (כמ\"ש לעיל בהקדמת הזהר דף כ\"ט ד\"ה במספר, עש\"ה) וכן יש לז\"א ב' נוקבין, האחת למעלה מחזה, שהיא הנקראת לבנה, וכן וכן מלכותא דדוד (לעיל בראשית א' דף ק\"י ד\"ה ואלו) והשנית, היא למטה מחזה, והיא נקראת, ארץ, וכן רחל. וז\"ש שזווג הזה המאיר את המוחין דחשבון אינו אלא בלבנה, דהיינו בהזווג זעיר ונוקביה שמחזה ולמעלה, שהנוקבא ההיא נקראת לבנה, ולא בהנוק' שמחזה ולמטה הנקראת ארץ, ומה שאומר \u0003לאנהרא עלמין עילא ותתא,\u0004 הפירוש הוא, שב' הנוקבין, של מעלה שה\"ס הלבנה ושל מטה שה\"ס הארץ, נכללות זו בזו, ואז מגיע ההארה למעלה ולמטה. אבל עיקר הזווג הוא רק בהלבנה, דהיינו בהנוקבא שלמעלה מחזה."],[3,"ר\"ש אמר, גימטריאות וחשבון תקופות ועבורין כלא הוא בסיהרא, דהא לעילא לאו איהו:","ר\"ש אמר גימטריאות, וחשבון של תקופות ועיבורי השנה, שה\"ס המוחין דחשבון ומספר, כולם הם בהלבנה, שהרי למעלה ממנה אינו נמצא הזווג הזה, להארת המוחין דחשבון ומספר. ומביא כאן דברי ר\"ש לסיעתא להנ\"ל, \u0003דחושבן דכלא בסיהרא הוא.\u0004"],[3,"א\"ל ר\"א, ולא, והא כמה חושבנין ושיעורין קעבדי חבריא:","א\"ל ר\"א לר\"ש, ולא, וכי לא יש מוחין דחשבון ומספר בהמדרגות שלמעלה מהלבנה, הרי כמה חשבונות ושיעורים עושים החברים, כלומר, הרי החברים לומדים מוחין דחשבון ושיעורים גם למעלה מהלבנה. \u0003א\"ל לאו הכי, אלא חושבנא קיימא בסיהרא, ומתמן יעול בר נש למנדע לעילא,\u0004 והשיב לו ר\"ש, לא כך היתה כונתי, אלא כונתי היא, שהזווג של המוחין דחשבון נמצא בהלבנה, ולא במדרגה אחרת, אמנם משם, נכנס האדם להשיג מוחין דחשבון גם בהמדרגות שלמעלה מהלבנה."],[3,"","פירוש. אע\"פ שהמוחין דהארת חכמה המכונים מוחין דחשבון, יוצאים בהבינה, אחר שחזרה לראש א\"א ונעשית בו לחכמה, מ\"מ אין המוחין מתגלים שם בהבינה, להיותה תמיד באור חסדים בלבד, ואפילו הז\"ת דבינה הם בעצם רק אור חסדים ואין שם המקום לגילוי המוחין דהארת חכמה, אלא הבינה משפעת המוחין הללו אל הז\"א. אמנם גם הז\"א מתוקן כולו במוחין דאו\"א עלאין שהם חסדים מכוסים, ואין בו מקום לגילוי המוחין הללו, אלא שהז\"א משפיע אותם אל הנוקבא שלו, ובה הם מתגלים. וע\"כ נקראת הנוקבא בשם \u0003חכמה תתאה,\u0004 להורות שאין המוחין דהארת חכמה מתגלים בשום מדרגה אלא בה. באופן שהמוחין הללו יוצאים בהז\"ת דבינה אשר הז\"א מקבלם ממנה ומשפיע אותם להנוקבא. והיינו להנוקבא שלמטה מחזה, בעת שהיא כלולה לגמרי בהנוקבא שלמעלה מחזה הנקראת לבנה. ואז נבחנות שתיהן בהשם לבנה."],[3,"","וזהו שהשיב לו ר\"ש לר\"א \u0003אלא חושבנא קיימא בסיהרא, ומתמן יעול בר נש למנדע לעילא,\u0004 כי מקום גילוי של המוחין דחשבון אינם אלא בהלבנה בלבד ולא כלום במדרגות הקודמות אליה, כנ\"ל, אמנם אחר שיצאו ונתגלו המוחין הללו בהלבנה, מאירים מוחין הללו בהכרח גם בכל המדרגות הקודמות אליה, שהרי מהם קבלה הלבנה את המוחין האלו. אלא מקודם שנגלו בהלבנה אינם מושגים כלל אע\"פ שכבר יצאו במדרגות הקודמות, כי בהן אין מקום לגילוי המוחין הללו כנ\"ל, אבל לאחר שנגלו למטה בהלבנה, נשלמים כולם מכח הגילוי הזו שבה. וז\"ש, \u0003ומתמן יעול בר נש למנדע לעילא,\u0004 כי אחר שנגלו בהלבנה, אפשר להשיגם גם במדרגות הקודמות."],[3,"א\"ל והא כתיב והיו לאותות ולמועדים:","א\"ל ר\"א, הרי כתוב והיו לאותות ולמועדים, שהוא לשון רבים, ומשמע שבשניהם מתגלים המוחין דחשבון, ואפילו בז\"א שה\"ס שמש. \u0003א\"ל לאתת כתיב חסר,\u0004 והשיב לו ר\"ש, כי לאתת בלי ו' כתיב, להורות שהוא לשון יחיד, כי קאי על הלבנה בלבד ולא על השמש. כי בו אין המוחין מתגלים. \u0003א\"ל והא כתיב והיו,\u0004 שהוא לשון רבים, דקאי גם על השמש. \u0003א\"ל הויין כלהון דיהוון ביה כאסקופא דא דאתמליא מכלא,\u0004 א\"ל, והיו אינו קאי על שמש וירח, אלא על הויות המוחין, ופירושו, שכל הויות כולם הם בה בהלבנה, שהיא כמו ספינה או עגלה זו המלאה מכל טוב. אסקופא פירושו ספינה, או עגלה המכוסות עם גג, כמ\"ש במדרש תהלים ג' א', אסקפי של בת שבע מהלכת לפני דוד. ומתוך שהלבנה נוסעת תמיד ע\"כ מדמה לה לאסקפא אבל \u0003חושבנא דכלא בסיהרא הוא,\u0004 אבל חשבון של כולם הוא רק בסיהרא, ולא בהשמש, כנ\"ל."],[4,"ת\"ח נקודה חד אית, ומתמן שירותא לממני דהא מה דלגו דההיא נקודה לא אתיידע:","בוא וראה יש נקודה אחת ומשם החתחלה למוחין דמנין וחשבון, והוא א\"א, הנקרא משום זה ראשית (כנ\"ל בראשית א' דף ו' אות ב', ובהסולם) שהרי מה שמלפנים של אותה הנקודה, דהיינו מה שלמעלה מא\"א, לא נודע כלל, (כמ\"ש שם) \u0003ואית נקודה לעילא סתים דלא אתגליא כלל ולא אתיידע, ומתמן שירותא לממני כל סתים ועומקא,\u0004 ויש נקודה למעלה שהיא סתומה, שאינה נגלית כלל, והיינו בינה דא\"א, מבחינת עצמותה המלובשת באו\"א עלאין, שהי' לא נפיק מאויר שלהם. אבל משם הוא ההתחלה למנות ולגלות כל סתום ועמוק. והיינו ז\"ת דבינה דא\"א, המלובשים בישסו\"ת, שהם עולים לראש א\"א, ומשפיעים הארת החכמה הנקרא מוחין דמנין וחשבון. אמנם עדיין אינם מתגלים כאן בישסו\"ת, להיותם בחינת בינה, שכל עקרה הוא אור החסדים בסו\"ה כי חפץ חסד הוא. \u0003הכי נמי אית נקודה לתתא דאתגלייא, ומתמן הוא שירותא לכל חושבנא ולכל מנין,\u0004 ויש גם כן נקודה למטה המתגלית, דהיינו הנוקבא דז\"א, ומשם הוא התחלת הגלוי לכל מוחין דחשבון ולכל מנין. דהיינו כנ\"ל בדברי ר\"ש, שלמעלה מסיהרא אין שום גילוי למוחין דחשבון. \u0003ועל דא הכא הוא אתר לכל תקופות וגמטריאות ועבורין וזמנין וחגי ושבתי,\u0004 וע\"כ כאן הוא מקום הארת המוחין לכל תקופות וגימט' ועבורים וזמנים וחגים ושבתות, דהיינו כדברי ר\"ש לעיל, \u0003וישראל דדבקי בקב\"ה עבדי חושבן לסיהרא, ואינון דבקין ביה וסלקין ליה לעילא דכתיב\u0004 וכו' וישראל הדבקים בהקב\"ה עושים חשבון, דהיינו שממשיכין מוחין דחשבון להלבנה, דהיינו כמ\"ש חז\"ל ישראל מונים ללבנה ואומ\"ה לחמה (סוכה כ\"ט) והם מעלים אותה למעלה, להלביש את בינה עלאה, כמ\"ש ואתם הדבקים בה' אלקיכם וגו'."],[5,"ישרצו המים וגו' אר\"א הא אוקמוה, דאינון מיין רחישו ואולידו כגוונא דלעילא והא אתמר:","ישרצו המים שרץ נפש חיה, אמר ר\"א, הנה פרשוהו שאלו מים התחתונים שרצו והולידו כמו מים העליונים. כלומר מים התחתונים הולידו את מה שקבלו ממים עליונים, וכבר נתבאר. דהיינו לעיל דף ק' אות קנ\"ח \u0003ועוף יעופף על הארץ, יעוף מבעי ליה, מהו יעופף:\u0004 מקשה על הכתוב, ועוף יעופף, שהיה לו לומר ועוף יעוף, למה אומר יעופף."],[6,"אר\"ש רזא הוא, ועוף דא מיכאל דכתיב ויעף וגו', יעופף דא גבריאל, דכתיב והאיש גבריאל וגו'.","אר\"ש סוד הוא, כי הכתוב רומז על בריאת המלאכים, ועוף זה מיכאל, שכתוב בו לשון ויעף, שכתוב ויעף אלי אחד מן השרפים, שהוא מיכאל. \u0003יעופף, דא גבריאל, דכתיב והאיש גבריאל וגו' מעף ביעף,\u0004 יעופף, זה גבריאל, שנאמר בו מעף ביעף לשון כפול, דכתיב והאיש גבריאל אשר ראיתי בחזון בתחלה מעף ביעף. \u0003על הארץ, דא אליהו דאשתכח תדיר בארעא,\u0004 על הארץ, זה אליהו הנמצא תמיד בארץ. פירוש, הנוקבא דז\"א מכונה ארץ כנ\"ל, ואליהו נמשך מבחינת הנוקבא דז\"א ונמצא עמה תמיד. \u0003ולא מסטרא דאבא ואמא אשתכח, דאיהו בד' טאסין,\u0004 ואליהו אינו נמצא מצד או\"א, שהרי הוא עף בארבע עפיפות. פירוש. כי המלאכים, שהם מסטרא דאו\"א, אומר הזהר (לעיל בראשית א' אות ת\"י) \u0003שהם טאסן ושאטן עלמא בשית,\u0004 דהיינו בשית עפיפות, כי או\"א הם בחינת חב\"ד חג\"ת עד החזה דא\"א, שהם ששה ספירות, וכנגדן שש עפיפות. אמנם אליהו אינו עף בשש עפיפות אלא בד', שזה יורה שהוא מבחינת הנוקבא דהיינו מחזה ולמטה, ששם רק ד' ספירות נהי\"מ. שכנגדן רק ד' עפיפות. \u0003דכתיב ורוח ה' ישאך על אשר לא אדע: ורוח ה', חד. ישאך, תרין. על אשר, תלת. לא אדע, ארבע.\u0004 שכתוב באליהו, ורוח ה' וגו': ורוח ה', יורה על עפיפה אחת, ישאך, הוא עפיפה השניה על אשר, הוא השלישית, לא אדע, הוא עפיפה הד'. הרי שהוא עף בד' עפיפות."],[7,"על פני, דא מלאך המות, דהוא אחשיך פני עלמא, וכתיב ביה וחשך על פני תהום:","הכתוב על פני, יורה על בריאת מלאך המות, ומרומז בהמלות \u0003על פני,\u0004 משום שהוא מחשיך פני העולם, וכן משום שכתוב בו וחשך על פני תהום. \u0003רקיע השמים כדאמרן, עולה ומסטין,\u0004 הכתוב רקיע השמים הוא כמו שאמרו שעולה המלאך המות לשמים ומסטין, דהיינו כמ\"ש (ב\"ב ט\"ז) הוא השטן הוא היצה\"ר הוא מלאך המות. ע\"ש. שנק' שטן משום שעולה לשמים ומסטין, ונק' מלאך המות משום שאח\"כ נוטל את נשמתו. וע\"כ נאמר במה\"מ על פני רקיע השמים. שדרכו להסטין בהשמים."],[7,"אמר רבי אבא, והא מלאך המות בשני אתברי,","הקשה רבי אבא, הרי ביום שני נברא מלאך המות ואיך תאמר, אשר על פני רקיע השמים הנאמר ביום ה' יורה על בריאת מלאך המות \u0003אלא על הארץ דא רפאל דאיהו ממנא לאסוותא דארעא, דבגיניה אתרפיאת ארעא,\u0004 אר\"א, על הארץ, שבהכתוב, יורה על בריאת המלאך רפאל. שהוא ממונה לרפואת הארץ, שבשבילו נרפאה הארץ, \u0003וקיים בר נש עלה, ורפי לכל חיליה,\u0004 והאדם יכול לעמוד עליה, ורופא לכל כחה של הארץ. וכיון שרפואת הארץ בא ממנו, ע\"כ נרמז בריאתו בהמלות \u0003על הארץ,\u0004 והכתוב על פני רקיע השמים דא אוריאל, והכ' על פני רקיע השמים הוא לבריאת המלאך אוריאל."],[7,"","פירוש, המלאך רפאל ה\"ס נושא המסך של הנוקבא, הנקראת ארץ, אשר על המסך הזה יוצא כל קומת האור הצריכה להארץ, כדי שהאדם יוכל לקבל ממנה המוחין, ונמצא שע\"י רפאל, דהיינו המסך שלו, נרפאה הארץ ממה שהיתה תהו ובהו, כי חזרה והשיגה על ידו המוחין. והמלאך אוריאל הוא בחינת ת\"ת, דהיינו ז\"א. כי מיכאל ה\"ס חסד, וגבריאל גבורה ואוריאל ת\"ת, כמ\"ש בת\"ז קכ\"ז. וע\"כ בריאת רפאל מרומזת בהכ' \u0003על הארץ,\u0004 כי המסך הוא בחינת הנוקבא הנקראת ארץ, ואוריאל מרומז בהכתוב \u0003על פני רקיע השמים,\u0004 כי הוא בחינת ז\"א הנקרא רקיע השמים, כנ\"ל באות קס\"ב שאומר, \u0003רקיע השמים דא שמשא,\u0004 דהיינו ז\"א הנקרא שמש. וז\"ש \u0003וכלא הוא בקרא,\u0004 וכולם דהיינו כל ד' המלאכים נושאי המרכבה, מרומזים בהכתוב, כי מיכאל, נרמז בהמלה ועוף. גבריאל, בהמלה יעופף. רפאל, בהמלות ועל הארץ. אוריאל, בהמלות על פני רקיע השמים. מה שאין כן לדברי ר\"ש הנ\"ל, לא היו מרומזים בהכתוב, כי אם ב' מלאכים של המרכבה, שהם מיכאל וגבריאל בלבדם."],[8,"ובג\"כ כתיב בתריה, ויברא אלקים את התנינים הגדולים. אר\"א, אלין אינון ע' ממנן רברבן על ע' עמין:","וע\"כ כתוב אחרי המקרא הנ\"ל, ויברא אלקים את התנינים הגדולים, ואמר ר\"א שהם רומזים על שרי מעלה, שאלו הם שבעים ממונים, שרים של שבעים עמים. \u0003ובגין כך אתכריאו כלהו, למהוי שליטאן על ארעא,\u0004 וע\"כ נבראו כולם שיהיו שולטים על הארץ. כלומר דע\"כ נאמר בהם \u0003הגדולים\u0004 ולא נאמר בהם \u0003הרומשת\u0004 ללמדך שנבראו להיות שולטים בארץ."]],[[0,"","רַבִּי אֶלְעָזָר אָמַר, כָּל הַצְּבָאוֹת הָיוּ בָּאָרֶץ, וְלֹא הוֹצִיאָה אֶת כֹּחָהּ, וְהֵם תּוֹלְדוֹתֶיהָ, עַד יוֹם (חמישי) הַשִּׁשִּׁי, שֶׁכָּתוּב תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה. וְאִם תֹּאמַר, וַהֲרֵי כָּתוּב וַתּוֹצֵא הָאָרֶץ דֶּשֶׁא אֶלָּא? הוֹצִיאָה תִקּוּן כֹּחוֹתֶיהָ כְּדֵי לְהִתְיַשֵּׁב כָּרָאוּי, וְהַכֹּל הָיָה גָנוּז בָּהּ עַד שֶׁהִצְטָרֵךְ. שֶׁהֲרֵי בַּהַתְחָלָה כָּתוּב שׁוֹמֵמָה וְרֵיקָה כְּתַרְגּוּמוֹ, אַחַר כָּךְ נִתְקְנָה וְהִתְיַשְּׁבָה וְקִבְּלָה זֶרַע וּדְשָׁאִים וַעֲשָׂבִים וְאִילָנוֹת כָּרָאוּי, וְהוֹצִיאָה אוֹתָם אַחַר כָּךְ. וְהַמְּאוֹרוֹת גַּם כֵּן לֹא שִׁמְּשׁוּ אוֹרוֹת שֶׁלָּהֶם עַד שֶׁהִצְטָרֵךְ."],[1,"","יְהִי מְאֹרֹת בִּרְקִיעַ הַשָּׁמַיִם (מארת כתוב חסר), לְהַכְלִיל נָחָשׁ הָרָע שֶׁהִטִּיל זֻהֲמָה וְעָשָׂה פֵרוּד שֶׁהַשֶּׁמֶשׁ לֹא מְשַׁמֵּשׁ עִם לְבָנָה. מְאֹרֹת - קְלָלוֹת. וְעַל זֶה גָּרַם שֶׁהִתְקַלְּלָה הָאָרֶץ, שֶׁכָּתוּב אֲרוּרָה הָאֲדָמָה. וְלָכֵן מְאֹרֹת כָּתוּב אֶחָד."],[2,"","יְהִי מְאֹרֹת - זוֹ הַלְּבָנָה. רְקִיעַ הַשָּׁמַיִם - זוֹ הַשֶּׁמֶשׁ. וּשְׁנֵיהֶם בִּכְלָל אֶחָד לְהִזְדַּוֵּג לְהָאִיר הָעוֹלָמוֹת לְמַעְלָה וּלְמַטָּה. מִמַּשְׁמָע שֶׁכָּתוּב עַל הָאָרֶץ וְלֹא כָתוּב בָּאָרֶץ, שֶׁמַּשְׁמָע לְמַעְלָה וּלְמַטָּה, חֶשְׁבּוֹן שֶׁל הַכֹּל בַּלְּבָנָה הוּא."],[3,"","רַבִּי שִׁמְעוֹן אָמַר, גִּימַטְרִיָּאוֹת וְחֶשְׁבּוֹן תְּקוּפוֹת וְעִבּוּרִים - הַכֹּל הוּא בַּלְּבָנָה, שֶׁהֲרֵי לְמַעְלָה אֵינוֹ. אָמַר לוֹ רַבִּי אֶלְעָזָר, וָלֹא!? וַהֲרֵי כַּמָּה חֶשְׁבּוֹנוֹת וְשִׁעוּרִים עוֹשִׂים הַחֲבֵרִים? אָמַר לוֹ, לֹא כָּךְ! אֶלָּא הַחֶשְׁבּוֹן עוֹמֵד בַּלְּבָנָה, וּמִשָּׁם יִכָּנֵס הָאָדָם לָדַעַת לְמַעְלָה. אָמַר לוֹ, וַהֲרֵי כָּתוּב וְהָיוּ לְאֹתֹת וּלְמוֹעֲדִים? אָמַר לוֹ, לְאֹתֹת כָּתוּב חָסֵר. אָמַר לוֹ, הֲרֵי כָּתוּב וְהָיוּ? אָמַר לוֹ, הֲוָיוֹת כֻּלָּם שֶׁיִּהְיוּ בוֹ, כְּאוֹצָר זוֹ שֶׁמִּתְמַלֵּא מֵהַכֹּל. אֲבָל הַחֶשְׁבּוֹן שֶׁל הַכֹּל הוּא בַּלְּבָנָה."],[4,"","בֹּא רְאֵה, יֵשׁ נְקֻדָּה אַחַת וּמִשָּׁם הָרֵאשִׁית לִמְנוֹת, שֶׁהֲרֵי מַה שֶּׁלִּפְנִים שֶׁל אוֹתָהּ נְקֻדָּה לֹא נוֹדָע וְלֹא נִתָּן לִמְנוֹת, וְיֵשׁ נְקֻדָּה לְמַעְלָה נִסְתֶּרֶת שֶׁלֹּא הִתְגַּלְּתָה כְּלָל וְלֹא נוֹדְעָה, וּמִשָּׁם הָרֵאשִׁית לִמְנוֹת כָּל נִסְתָּר וְעֹמֶק. כָּךְ גַּם יֵשׁ נְקֻדָּה לְמַטָּה שֶׁהִתְגַּלְּתָה, וּמִשָּׁם הוּא רֵאשִׁית לְכָל חֶשְׁבּוֹן וּלְכָל מִנְיָן, וְעַל זֶה כָּאן הוּא הַמָּקוֹם לְכָל הַתְּקוּפוֹת וְהַגִּימַטְרִיָּאוֹת וְהָעִבּוּרִים וְהַזְּמַנִּים וְחַגִּים וְשַׁבָּתוֹת. וְיִשְׂרָאֵל שֶׁדְּבֵקִים בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, עוֹשִׂים חֶשְׁבּוֹן לַלְּבָנָה, וְהֵם דְּבֵקִים בּוֹ וּמַעֲלִים אוֹתוֹ לְמַעְלָה, שֶׁכָּתוּב (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם וְגוֹ'."],[5,"","יִשְׁרְצוּ הַמַּיִם שֶׁרֶץ נֶפֶשׁ חַיָּה. אָמַר רַבִּי אֶלְעָזָר, הֲרֵי פֵּרְשׁוּהָ שֶׁאוֹתָם מַיִם רָחֲשׁוּ וְהוֹלִידוּ כְּמוֹ שֶׁלְּמַעְלָה, וַהֲרֵי נֶאֱמַר. וְעוֹף יְעוֹפֵף עַל הָאָרֶץ - יָעוּף צָרִיךְ לִכְתֹּב, מַה זֶה יְעוֹפֵף?"],[6,"","אָמַר רַבִּי שִׁמְעוֹן, סוֹד הוּא, וְעוֹף זֶה מִיכָאֵ\"ל, שֶׁכָּתוּב (ישעיה ו) וַיָּעָף אֵלַי אֶחָד מִן הַשְּׂרָפִים. יְעוֹפֵף - (ד\"א יעוף צריך לו, אלא) זֶה גַבְרִיאֵ\"ל, שֶׁכָּתוּב (דניאל ט) וְהָאִישׁ גַּבְרִיאֵל אֲשֶׁר רָאִיתִי בֶחָזוֹן בַּתְּחִלָּה מֻעָף בִּיעָף. (ד\"א וזהו יעופף). עַל הָאָרֶץ - (זה אליהו שנמצא תמיד בארץ ולא מצד של אבא ואמא הוא, נמצא שהוא (טס את העולם) בארבע טיסות, שכתוב ורוח ה' ישאך על אשר לא אדע, ורוח ה' אחת, ישאך שתים, על אשר שלש, לא אדע ארבע, על פני זה מלאך המות) שֶׁהוּא (מחשיך הארץ, על פני מחשיך פני העולם, וכתוב בו וחשך על פני תהום,) רְקִיעַ הַשָּׁמָיִם - כְּמוֹ שֶׁאָמַרְנוּ עוֹלֶה וּמַסְטִין וְכוּ'."],[7,"","אָמַר רַבִּי אַבָּא, וַהֲרֵי מַלְאַךְ הַמָּוֶת בַּשֵּׁנִי נִבְרָא? אֶלָּא עַל הָאָרֶץ זֶה רְפָאֵ\"ל, שֶׁהוּא מְמֻנֶּה עַל רְפוּאַת הָאָרֶץ, שֶׁבִּגְלָלוֹ נִרְפֵּאת הָאָרֶץ, וְקַיָּם בֶּן אָדָם עָלֶיהָ וּמְרַפֵּא לְכָל כֹּחוֹ. עַל פְּנֵי רְקִיעַ הַשָּׁמָיִם - זֶה אוֹרִיאֵ\"ל. וְהַכֹּל הוּא בַּפָּסוּק."],[8,"","וְלָכֵן כָּתוּב אַחֲרָיו וַיִּבְרָא אֱלֹהִים אֶת הַתַּנִּינִם הַגְּדלִים. אָמַר רַבִּי אֶלְעָזָר (ד\"א הרי בארנו אלו, לויתן ובת זוגו) אֵלֶּה הֵם שִׁבְעִים מְמֻנִּים גְּדוֹלִים עַל שִׁבְעִים הָעַמִּים, וְלָכֵן נִבְרְאוּ כֻלָּם לִהְיוֹת שׁוֹלְטִים עַל הָאָרֶץ."]]],[["וְאֵת כָּל נֶפֶשׁ הַחַיָּה הָרוֹמֶשֶׂת אִלֵּין אִנּוּן יִשְׂרָאֵל דְּאִנּוּן נֶפֶשׁ וַדַּאי דְּהַהוּא חַיָּה וְאִקְרוּן גּוֹי אֶחָד בָּאָרֶץ. אֲשֶׁר שָׁרְצוּ הַמַּיִם לְמִינֵיהֶם דְּאִנּוּן מִשְׁתַּדְּלִין בְּאוֹרַיְיתָא. וְאֵת כָּל עוֹף כָּנָף לְמִינֵהוּ אִלֵּין צַדִּיקַיָּיא דִּבְהוֹן וּבְגִין כָּךְ אִנּוּן נְפֶשׁ חַיָּה. דָּבָר אַחֵר וְאֵת כָּל עוֹף כָּנָף כְּדְקָא אִתְּמָר אִלֵּין אִנּוּן (לעיל לד א) שְׁלוּחֵי עָלְמָא.","אָמַר רַבִּי אַבָּא נֶפֶשׁ חַיָּה דְאִנּוּן (ד\"א אנון) יִשְׂרָאֵל, בְּגִין דְּאִנּוּן בְּנֵי דְּקוּדְשָׁא בְּרִיךְ הוּא (ד\"א בנין לקודשא בריך הוא) וְנִשְׁמַתְהוֹן קַדִּישִׁין מִנֵּיהּ אַתְיָין. נַפְשָׁאן דִּשְׁאָר עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת מְאָן אֲתַר הוּא. אָמַר רַבִּי אֶלְעָזָר מֵאִנּוּן סִטְרֵי שְׂמָאלָא דִּמְסָאֲבֵי לוֹן אִית לוֹן נִשְׁמָתִין. וּבְגִין כָּךְ כֻּלְהוּ מְסָאֲבִין, וּמְסָאֲבִין לְמָאן דְּקָרַב בַּהֲדַיְיהוּ:","וַיֹּאמֶר אֱלֹהִים תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה וְגו' כֻּלְהוֹן שְׁאָר חֵיוָון אָחֳרָנִין כָּל חַד וְחַד כְּפוּם זִינֵיהּ, וְאָמַר רַבִּי אֶלְעָזָר הַאי מְסַיֵּיעַ לְמַה דְּאֲמָרָן נֶפֶשׁ חַיָּה אִלֵּין יִשְׂרָאֵל דְּאִנּוּן נֶפֶשׁ חַיָּה קַדִּישָׁא עִלָּאָה. בְּהֵמָה וָרֶמֶשׂ וְחַיְתוֹ אֶרֶץ אִלֵּין שְׁאָר עַמִין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת דְּלָאו אִנּוּן נֶפֶשׁ חַיָּה אֶלָּא (ד\"א ערלה) כִּדְקָאֲמָרָן:","נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ, דְּאִתְכְּלִיל בְּשִׁית סִטְרִין כָּלִיל מִכֹּלָּא כְּגַוְונָא דִלְעֵילָא, בְּשַׁיְיפֵי מְתַקְנָן בְּרָזָא דְחָכְמְתָא כְּדְקָא יָאוּת כֹּלָּא תִּקּוּנָא עִלָּאָה. נַעֲשֶׂה אָדָם רָזָא דְּכַר וְנוּקְבָא כֹּלָּא בְּחָכְמְתָא קַדִּישָׁא עִלָּאָה. בְּצַלְמֵנוּ כִּדְמוּתֵנוּ לְאִשְׁתַּכְלְלָא דָא בְּדָא לְמֶהֱוִי (ד\"א ל\"ג חד) הוּא יְחִידָאי בְּעָלְמָא שַׁלִּיט עַל כֹּלָּא:","וַיַּרְא אֱלֹהִים אֶת כָּל אֲשֶׁר עָשָׂה (ד\"א כלל) וְהִנֵּה טוֹב מְאֹד, הָכָא אִתְתַּקַּן מַה דְּלָא אִתְּמָר כִּי טוֹב בַּשֵּׁנִי בְּגִין דְּאִתְבְּרֵי בֵּיהּ מוֹתָא, וְהָכָא אִתְּמָר וְהִנֵּה טוֹב מְאֹד. וְאָזְלָא כְּמָה דְּאָמְרֵי חַבְרַיָיא וְהִנֵּה טוֹב מְאֹד זֶה מָוֶת.","וַיַּרְא אֱלֹהִים אֶת כָּל אֲשֶׁר עָשָׂה וְהִנֵּה טוֹב מְאֹד, וְכִי לָא חָמָא לֵיהּ קוֹדֶם. אֶלָּא כֹּלָּא חָמָא לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, וּמַאן דְּאָמַר אֶת כָּל, לְאַסְגָּאָה כָּל דָּרִין דְּיֵיתוּן לְבָתַר כֵּן, וְכֵן כָּל מַה דְּיִתְחַדֵּשׁ בְּעָלְמָא בְּכָל דָּרָא וְדָרָא עַד לָא יֵיתוּן לְעָלְמָא. אֲשֶׁר עָשָׂה, דָּא כָּל עוֹבָדִין דִבְרֵאשִׁית, דְּתַמָּן אִתְבְּרֵי יְסוֹדָא וְעִקְּרָא לְכָל מַה דְּיֵיתֵי וְיִתְחַדֵּשׁ בְּעָלְמָא לְבָתַר כֵּן. וּבְגִין כָּךְ חָמָא לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא עַד לָא הֲוָה וְשַׁוֵּי כֹּלָּא בְּעוֹבָדָא דִּבְרֵאשִׁית.","יוֹם הַשִּׁשִּׁי, מַאי שְׁנָא בְּכֻלְהוּ יוֹמֵי דְּלָא אִתְּמָר בְּהוּ הֵ\"א, אֶלָּא הָכָא כַּד אִשְׁתַּכְלַל עָלְמָא אִתְחַבְּרַת נוּקְבָא בִּדְכוּרָא בְּחִבּוּרָא חַד, ה' בַּשִּׁשִּׁי (ד\"א דאיהו ס\"א יסוד) לְמֶהֱוֵי כֹּלָּא חַד. וַיְכֻלּוּ, אִשְׁתַּכְלְלוּ כֹלָא חַד (ד\"א כחד). אִשְׁתַּכְלְלוּ מִכֹּלָּא וְאִשְׁתַּלִימוּ בְּכֹלָּא:","וַיְכֻלּוּ הַשָּׁמַיִם וְהָאָרֶץ וְכָל צְבָאָם. רַבִּי אֶלְעָזָר פָּתַח (תהילים ל״א:כ׳) מָה רַב טוּבְךָ אֲשֶׁר צָפַנְתָּ לִירֵאֶיךָ פָּעַלְתָּ לַחוֹסִים בָּךְ נֶגֶד בְּנֵי אָדָם. תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא בָּרָא לְבַר נָשׁ בְּעָלְמָא, וְאַתְקִין לֵיהּ לְמֶהוֵי שְׁלִים בְּפוּלְחָנִיהּ וּלְאִתְתַּקָּנָא אָרְחוֹי, בְּגִין דְּיִזְכֵּי לִנְהוֹרָא עִלָּאָה דְּגָנִיז קוּדְשָׁא בְּרִיךְ הוּא לְצַדִּיקַיָּיא כְּמָא דְאַתְּ אָמֵר, (ישעיהו ס״ד:ג׳) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךָ יַעֲשֶׂה לִמְחַכֵּה לוֹ.","וּבְמָּה (ס\"א זכי בר נש) יִזְכֵּי לֵיהּ לְבַר נָשׁ לְהַהוּא נְהוֹרָא, בְּאוֹרַיְיתָא. דְּכָל מַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא בְּכָל יוֹמָא יִזְכֵּי לְמֶהוֵי לֵיהּ חוּלְקָא בְּעַלְמָא דְאָתֵי, וְיִתְחַשֵׁב לֵיהּ כְּאִלּוּ בָאנֵי עָלְמִין, דְּהָא בְּאוֹרַיְיתָא אִתְבְּנֵי עַלְמָא וְאִשְׁתַּכְלַל הֲדָא הוּא דִכְתִיב, (משלי ג׳:י״ט) יְיָ בְּחָכְמָה יָסַד אֶרֶץ כּוֹנִן שָׁמַיִם בִּתְבוּנָה, וּכְתִיב, (משלי ח׳:ל׳) וָאֶהְיֶה אֶצְלוֹ אָמוֹן וָאֶהְיֶה שַׁעֲשׁוּעִים יוֹם יוֹם וְכָל דְּאִשְׁתַּדַּל בָּהּ שַׁכְלִיל עָלְמִין וְקַיִּים לֵיהּ. וְתָּא חֲזֵי, בְּרוּחָא עֲבִיד קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא, וּבְרוּחָא מִתְקַיְימָא, רוּחָא דְּאִנּוּן דְּלָעָאן בְּאוֹרַיְיתָא, וְכָל שֶׁכֵּן רוּחָא דְּהֶבֶל דְּרַבְיֵי דְּבֵי רַב.","מָה רַב טוּבְךָ דָּא טוּבָא דְּאִתְגְּנִיז. לִירֵאֶיךָ לְאִנּוּן דַּחֲלֵי חַטָּאָה. פָּעַלְתָּ לַחוֹסִים בָּךְ. מַאי פָּעַלְתָּ דָּא עוֹבָדָא דִּבְרֵאשִׁית. רַבִּי אַבָּא אָמַר דָּא גַּן עֵדֶן, דְּהָא בְּאוּמָנוּתָא עָבִיד לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא בְּאַרְעָא כְּגַוְונָא דִּלְעֵילָא. לְאִתְתַּקְפָא בֵּיהּ צַדִּיקַיָּיא הֲדָא הוּא דִכְתִיב (תהילים ל״א:כ׳) פָּעַלְתָּ לַחוֹסִים בָּךְ, נֶגֶד בְּנֵי אָדָם, דְּהָא הוּא נֶגֶד (בני) אָדָם. וְאַחֲרָא נֶגֶד עִלָּאִין קַדִּישִׁין. אָמַר רַבִּי שִׁמְעוֹן גַּן עֵדֶן לְעֵילָא וְנֶגֶד בְּנֵי אָדָם הֲוֵי (ואפילו אחרא נגד בני אדם הוי) לְאִתְכַּנְשָׁא בֵּיהּ צַדִּיקַיָּיא דְּעָבְדֵי רְעוּתָא דְּמָארֵיהוֹן."],[[0,"ואת כל נפש חיה הרומשת, אלין אינון ישראל, דאנון נפש ודאי דההוא חיה:","ואת כל נפש חיה הרומשת, יורה על בריאת הנפש של ישראל, שהם ודאי נפש של אותה החיה, דהיינו הנוקבא דז\"א, הנקראת חיה, כי כל עולם האצילות נבחן לאור החיה, וה' פרצופי אצילות נבחנים לנרנח\"י של אור החיה, אשר א\"א היא יחידה דחיה, ואו\"א הוא חיה דחיה, וישסו\"ת הוא נשמה דחיה, וז\"א הוא רוח חיה, והנוקבא היא נפש חיה, וכיון שישראל נמשכים מן הנוקבא דז\"א, נבחנת גם הנפש שלהם לנפש חיה, \u0003ואקרון גוי אחד בארץ,\u0004 ונקראים משום זה גוי אחד בארץ. \u0003אשר שרצו המים למיניהם, דאינון משתדלין באורייתא,\u0004 הכ' אשר שרצו המים וגו' יורה על אלו העוסקים בתורה, כי אין מים אלא תורה, וע\"י עסק התורה זוכים בנפש חיה, כנ\"ל, (בהקדמת הזהר ר\"ד אות רט\"ז) \u0003דכד בר נש לא אתעסק באורייתא לית ליה נפשא קדישא, וכו' וכד אשתדל באורייתא וכו' זכי לההיא נפש חיה.\u0004 אם האדם אינו עוסק בתורה אין לו נפש קדוש, ואם הוא עוסק בתורה זוכה לאותה נפש חיה. \u0003ואת כל עוף כנף למינהו, אלין צדיקיא דבהון,\u0004 הכ' ואת כל עוף כנף למינהו, רומז על הצדיקים שבין העוסקים בתורה, \u0003ובגין כך, אנון נפש חיה,\u0004 ומשום זה, שהם צדיקים, זכו בנפש חיה. \u0003ד\"א ואת כל כנף, כדקא אתמר, אלין אינון שלוחי עלמא,\u0004 פירוש אחר בהכ' ואת כל כנף, הוא כמו שאמרו (לעיל בראשית א' אות ת\"י ) שאלו הם מלאכים שליחי העולם. ע\"ש."],[1,"אר\"א, נפש חיה, אינון ישראל, בגין דאינון בני דקב\"ה, ונשמתהון קדישין מניה אתיין:","אר\"א, הכ' נפש חיה, הוא על ישראל, משום שהם בניו של הקב\"ה, וממנו נשמותיהם הקדושות באות, \u0003נפשאן דשאר עמין עובדי כו\"מ מאן אתר הוא,\u0004 שואל, הנפשות של שאר העמים עובדי ע\"ז, מאיזה מקום הן, \u0003אר\"א, מאנון סטרי שמאלא דמסאבי לון, אית לון נשמתין, ובגין כך כלהו מסאבין, ומסאבין למאן דקרב בהדייהו,\u0004 (כצ\"ל , וכן הוא בכל הדפוסים הראשונים והגירסא, חולין לון וכו' חולין ומיחלין למאן דקרב בהדייהו, הוא תקון סופרים) אר\"א, יש להם נשמות מאותם כחות השמאל המטמאים אותם, וע\"כ כולם טמאים, ומטמאים את כל הקרב אליהם."],[2,"ויאמר אלקים תוצא הארץ וגו' כלהון שאר חיוון אחרנין כל חד וחד כפום זיניה:","הכ' ויאמר אלקים תוצא וגו' בהמה ורמש וחיתו ארץ למינה, כולם הם על שאר חיות האחרות, חוץ מישראל, שכל אחד ואחד מהם מקבל לפי מינו. וקאי על סיפיה דקרא, בהמה ורמש וחיתו ארץ למינה, כמו שמסיים לפנינו. \u0003ואר\"א, האי מסייע למה דאמרן, נפש חיה אלין ישראל, דאינון נפש חיה קדישא עלאה,\u0004 ואר\"א, מכאן ראיה למה שאמרנו, אשר נפש חיה שאומר הכתוב, הוא על ישראל, שיש להם נפש חיה קדושה ועליונה, \u0003בהמה ורמש וחיתו ארץ אלין שאר עמין עובדי כו\"מ, דלאו אינון נפש חיה, אלא כדקאמרן,\u0004 והכ' בהמה ורמש וחיתו ארץ הוא על שאר העמים עובדי ע\"ז, שהם אינם נפש חיה, אלא כמו שאמרנו, שנמשכים מכחות השמאל המטמאים אותם."],[3,"נעשה אדם בצלמנו כדמותנו דאתכליל משית סטרין כליל מכלא, כגוונא דלעילא:","הכתוב נעשה וגו' יורה שהאדם נכלל משש קצוות הכלולים מכל, דהיינו הן מחכמה והן מחסדים, כעין של מעלה, דהיינו ז\"א דאצילות, כי ע\"כ נאמר בצלמנו כדמותנו, אשר צל\"ם יורה על חכמה בינה דעת דמוחין דז\"א, ודמות על מוחין דנוקבא. (כנ\"ל בהקדמת הזהר דף רכ\"ב בהסולם ד\"ה ושורש) \u0003בשייפי מתקנן ברזא דחכמתא כדקא יאות, כלא תקונא עלאה,\u0004 באברים מתוקנים בסוד החכמה כראוי, הכל בתקון העליון, דהיינו כתקון הזו\"ן דאצילות בהכלים דנה\"י דאו\"א, שבהם מקבל המוחין דחכמה מאו\"א, כן נתקן האדם בכלים דנה\"י דזו\"ן דאצילות, שבהם מקבל המוחין דחכמה מזו\"ן, ואלו הכלים דנה\"י מכונים \u0003שייפי מתקנן ברזא דחכמתא,\u0004 והם בחינת בינה ותו\"מ דעליון, שנפלו בעת הקטנות לרשות התחתון, ואינם נעדרים מהתחתון אפילו אחר שחזרו לעליון, כי אין העדר ברוחני, וע\"כ נעשה כל תחתון מוכשר לקבל המוחין של העליון, כי יש לו הכלים דעליון, (וזה נתבאר, לעיל בראשית א' דף ז' ד\"ה וכבר, עש\"ה.) והם המכונים בספרים נה\"י דעליון המתלבשים בתחתון. \u0003נעשה אדם רזא דכר ונוקבא, כלא בחכמתא קדישא עלאה,\u0004 הכ' נעשה אדם ה\"ס זכר ונקבה, כלומר, השם אדם יורה על זכר ונקבה, והכל בחכמה קדושה העליונה. דהיינו שהכל נעשה כדי שיהיה ראוי לקבל חכמה הקדושה העליונה. כי אין החכמה נמשכת רק בכח הנוקבא, (כנ\"ל דף ק\"ד ד\"ה ר\"ש אמר) וע\"כ נברא האדם דכר ונוקבא. \u0003בצלמנו כדמותנו לאשתכלא דא בדא, למהוי הוא יחידאי בעלמא שליט על כלא,\u0004 ואומר הכ' בצלמנו כדמותנו, אשר צל\"ם הם מוחין דדכר, ודמות הם מוחין דנוקבא כנ\"ל, שישתכללו הזכר והנקבה זה בזה, כי החסדים מיוחסים להזכר. והארת החכמה להנקבה (כנ\"ל דף ק\"ה ד\"ה פירוש) והזכר משתכלל בהארת החכמה ע\"י הנקבה, והנקבה משתכללת בחסדים ע\"י הזכר. ואז נעשה האדם יחיד בעולם ומושל בכל, כמו הזו\"ן העליונים. כי אין ממשלה בעולם, דהיינו להכניע כל הקליפות אלא על ידי מוחין שלימים מחכמה ומחסדים."],[4,"וירא אלקים וגו' הכא אתתקן מה דלא אתמר כי טוב בשני, בגין דאתברי ביה מותא:","וירא אלקים וגו', כאן נתתקן מה שלא נאמר כי טוב ביום שני מטעם שנברא בו המות, \u0003והכא אתמר והנה טוב מאד, ואזלא כמה דאמרי חבריא, והנה טוב מאד זה מות,\u0004 וכאן נאמר כי טוב מאד, והולך כפי שפרשו החברים את הכ' והנה טוב מאד, שנאמר על המות. וא\"כ ראוי גם יום שני שיאמר בו כי טוב אע\"פ שנברא בו המות. כי כאן ביום הששי נתגלה שהמות טוב מאד. והטעם, שהמות טוב מאד, נתבאר בזהר תרומה אות תל\"ב תל\"ג"],[5,"וירא אלקים את כל אשר עשה וגו' וכי לא חמא ליה קודם:","וירא וגו' מקשה וכי לא ראה קודם שעשה, כי כתיב וירא אלקים את כל אשר עשה שמשמע שראה רק לאחר שעשה. \u0003אלא כלא חמא ליה קב\"ה,\u0004 ומתרץ, אלא הכל ראה הקב\"ה, הן מה שכבר עשה והן קודם שנעשה, \u0003ומאן דאמר, את כל, לאסגאה כל דרין דייתון לבתר כן, וכן כל מה דיתחדש בעלמא בכל דרא ודרא עד לא ייתון לעלמא,\u0004 ויש מי שפירש, שהכתוב, את כל, בא לרבות שראה כל הדורות העתידים לבא לאחר מכאן, וכן כל מה שיתחדש בעולם בכל דור ודור, עוד מטרם שיבואו לעולם. \u0003אשר עשה, דא כל עובדין דבראשית, דתמן אתברי יסודא ועקרא לכל מה דייתי ויתחדש בעלמא לבתר כן,\u0004 הכתוב, \u0003אשר עשה,\u0004 היינו כל מעשה בראשית, כי שם, במעשה בראשית, נברא היסוד והשורש לכל מה שיבא ויתחדש בעולם, לאחר מכאן, \u0003ובג\"כ חמא ליה קב\"ה עד לא הוה, ושוי כלא בעובדא דבראשית,\u0004 וע\"כ ראה הקב\"ה עוד מקודם שהיה, ושם את הכל במעשה בראשית. פירוש, מתוך שמעשה בראשית הם יסוד ושורש לכל העתיד לבא, ע\"כ כלל הקב\"ה בהם לראות את כל העתיד, לבא בעולם בכל הדורות. כמו שנרמז בהכתוב \u0003את כל,\u0004 כנ\"ל."],[5,"","פנימיות הדברים. כי דרשו חז\"ל בהכתוב ולאמר לציון עמי אתה, עמי אתם בשותפות, אני התחלתי העולמות ואתם גומרים אותם פירוש. כי השי\"ת תקן כל המציאות באופן שיוכלו בני אדם לגמור התקון, וכיון שגמר התיקון נשאר לבני אדם א\"כ הם נמצאים שותפים בהבריאה. ולפיכך יש ב' בחינות שמים וארץ, א) מה שכבר תיקן המאציל, והוא הנקרא מעשה בראשית ב) שמים וארץ החדשים שיתגלו אחר גמר התקון. בסו\"ה כי כאשר השמים החדשים והארץ החדשה וגו'."],[5,"","וזה שהקשה הזהר על הכתוב וירא אלקים את כל אשר עשה, שהמשמעות הוא שראה הקב\"ה רק את כל אשר עשה במעשה בראשית, ולא את השמים וארץ העתידים להתתקן ע\"י מע\"ט של בני אדם. העתידים לעשות בכל דור ודור. וח\"ו לומר כן. וזהו אמרו \u0003וכי לא חמא ליה קודם.\u0004 וכי אינו רואה קודם שעשה דהיינו גם העתיד להתתקן בכל דור ודור על ידי מע\"ט עד גמר התקון שע\"י מע\"ט הללו נבראים שמים וארץ חדשים."],[5,"","וזהו שמתרץ, אשר, את כל, פירושו כל המע\"ט העתידים להתחדש בכל בכל דור ודור ע\"י הצדיקים. \u0003אשר עשה,\u0004 היינו מעשה בראשית אשר כבר עשה. \u0003ובג\"כ חמי ליה קב\"ה עד לא הוה, ושוי כלא בעובדא דבראשית,\u0004 כי בהיות תקון המציאות שנתקן ע\"י הקב\"ה במעשה בראשית, יסוד ושורש להתיקונים של מעשה בני אדם, נמצא לפי זה, אשר מעשה בני אדם כלולים במעשה בראשית, וע\"כ נסמך ראיית העתיד, אל ראיית מעשה בראשית שכבר עשה, דהיינו, \u0003את כל,\u0004 זה ראיית העתיד, \u0003אשר עשה,\u0004 זה מעשה בראשית."],[6,"יום הששי, מאי שנא בכלהו יומי דלא אתמר בהו ה':","מקשה, מהו השינוי אשר בכל ימי בראשית לא נאמר ה' כמו כאן שנאמר יום הששי, כי לא נאמר בהם יום האחד יום השני, \u0003אלח הכא כד אשתכלל עלמא אתחברת נוקבא בדכורא בחבורא חד ה' בששי למהוי כלא חד,\u0004 אלא כאן, שכבר נשתכלל העולם, שהם זו\"ן כי כבר נסתיים מעשה בראשית שה\"ס בנין הזו\"ן. נתחברה הנוקבא בדכר בחיבור אחד, דהיינו \u0003ה' בששי,\u0004 להיות אחד לגמרי. \u0003ויכלו, אשתכללו כלא חד,\u0004 ויכלו השמים וארץ, שהם זו\"ן נשתכללו כאחד, \u0003אשתכללו מכלא ואשתלימו בכלא,\u0004 שהזו\"ן נשתכללו מכל מעשה בראשית ונשלם בכל מלואם."],[7,"ויכלו השמים וגו' ר\"א פתח מה רב טובך וגו'. ת\"ח קב\"ה ברא לב\"נ בעלמא, ואתקין ליה למהוי שלים בפולחניה ולאתתקנא אורחוי:","בוא וראה, הקב\"ה ברא את האדם בעולם, ותקן אותם שיהיה שלם בעבודתו, ושיתקן דרכיו, \u0003בגין דיזכי לנהורא עלאה דגניז קב\"ה לצדיקיא, כד\"א\u0004 וגו' כדי שיזכה לאור העליון שגנז הקב\"ה לצדיקים. כמ\"ש עין לא ראתה וגו'. עין לא ראתה אלקים זולתך, היינו אור הגנוז. יעשה למחכה לו, היינו הצדיקים."],[8,"ובמה יזכי ליה לבר נש לההוא נהורא, באורייתא.","שואל, ובמה יזכה האדם באותו האור הגנוז. ומשיב, כי יזכה בו ע\"י העסק בתורה. \u0003דכל מאן דאשתדל באורייתא בכל יומא יזכי למהוי ליה חולקא בעלמא דאתי ויתחשב ליה כאלו באני עלמין,\u0004 כי כל מי שעוסק בתורה בכל יום, יזכה שיהיה לו חלק לעולם הבא, ויהיה נחשב לו כאלו בנה עולמות."],[8,"דהא באורייתא אתבני עלמא ואשתכלל הה\"ד וכו', וכתיב ואהיה וגו' וכל דאשתדל בה שכליל עלמין וקיים ליה,","כי עם התורה נבנה העולם ונשתכלל, וזה שכתוב, ה' בחכמה יסד ארץ, כונן שמים בתבונה, והיינו בחכמה ותבונה של התורה. וכן כתוב, ואהיה אצלו וגו', דהיינו שהתורה היתה אומנותו לברוא את העולם. כמ\"ש (תרומה אות תרל\"ח.)"],[8,"ות\"ח, ברוחא עביד קב\"ה עלמא, וברוחא מתקיימא, רוחא דאינון דלעאן באורייתא,","ובוא וראה, ברוח עשה הקב\"ה את העולם, וברוח העולם מתקיים, והיינו ברוח פיהם של אותם לומדי התורה, \u0003וכל שכן רוחא דהבל דרביי דבי רב,\u0004 ומכל שכן, הרוח מהבל פיהם של תינוקות בית רבם, שעליו עומד ומתקיים העולם."],[9,"מה רב טובך, דא טובא דאתגניז, ליראיך, לאינון דחלי חטאה:","ועם כל האמור מבאר הכתוב, אשר מה רב טובך, יורה על הטוב שנגנז, דהיינו על האור הגנוז. ליראיך, היינו שנגנז בשביל יראי חטא, העוסקים בתורה כנ\"ל. \u0003פעלת לחוסים בך, מאי פעלת, דא עובדא דבראשית,\u0004 פעלת לחוסים בך, שואל, מה יורה המלה \u0003פעלת,\u0004 ואומר, שיורה על פעולות מעשה בראשית. כלומר, שכל מעשה בראשית לא נעשה ואינה מתקיימת אלא בשביל לומדי התורה, הממשיכים בזכות תורתם את אור הגנוז, כנ\"ל."],[9,"רבי אבא אמר, דא גן עדן, דהא באומנותא עביד ליה קב\"ה בארעא כגוונא דלעילא לאתתקפא ביה צדיקייא.","רא\"א, הכ' פעלת קאי על ג\"ע כי באומנות עשה הקב\"ה את ג\"ע התחתון שבארץ, בשוה למעלת ג\"ע העליון, שיתחזקו שם הצדיקים. \u0003הה\"ד פעלת לחוסים בך נגד בני אדם, דהא הוא נגד בני אדם, ואחרא, נגד עלאין קדישין,\u0004 וז\"ש פעלת וגו' כי ג\"ע התחתון הוא נגד בני אדם, והאחר שהוא ג\"ע העליון, אינו אלא בשביל הקדושים העליונים, ולא בשביל בני אדם."],[9,"אר\"ש ג\"ע לעילא, ונגד בני אדם הוי לאתכנשא ביה צדיקיא דעבדי רעותא דמאריהון:","ר\"ש אומר, שהכתוב פעלת קאי על ג\"ע העליון, ומ\"מ נגד בני אדם נחשב, משום שמתאספים שם הצדיקים העושים רצונו של רבונם, כלומר אע\"פ שהג\"ע העליון אינם בשביל בני אדם, מ\"מ הצדיקים שבג\"ע התחתון עולים באוירא לג\"ע העליון, כנ\"ל (בהקדמת הזהר דף קי\"ג אות ק\"ט) שאומר, \u0003ופרחי באוירא וכו' בההוא ג\"ע דלעילא, ופרחי ואסתחיין בטלי נהרי אפרסמונא דכיא, ונחתי ושראן לתתא\u0004 ע\"ש. ומשום שהצדיקים עולים ומתאספים שמה, אע\"פ שמוכרחין לחזור ולירד למקומם, מ\"מ נחשב משום זה, נגד בני אדם."]],[[0,"","וְאֵת כָּל נֶפֶשׁ הַחַיָּה הָרֹמֶשֶׂת - אֵלֶּה הֵם יִשְׂרָאֵל שֶׁהֵם נֶפֶשׁ וַדַּאי שֶׁל אוֹתָהּ חַיָּה, וְנִקְרָאִים גּוֹי אֶחָד בָּאָרֶץ. אֲשֶׁר שָׁרְצוּ הַמַּיִם לְמִינֵהֶם - שֶׁהֵם מִשְׁתַּדְּלִים בַּתּוֹרָה. וְאֵת כָּל עוֹף כָּנָף לְמִינֵהוּ - אֵלֶּה הַצַּדִּיקִים שֶׁבָּהֶם, וְלָכֵן הֵם נֶפֶשׁ חַיָּה. דָּבָר אַחֵר, וְאֵת כָּל עוֹף כָּנָף - כְּמוֹ שֶׁנֶּאֱמַר, אֵלֶּה הֵם שְׁלוּחֵי הָעוֹלָם."],[1,"","אָמַר רַבִּי אַבָּא, נֶפֶשׁ חַיָּה שֶׁהֵם (הם) יִשְׂרָאֵל, מִשּׁוּם שֶׁהֵם בְּנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא (ד\"א בנים לקדוש ברוךהוא) וּנְשָׁמוֹת הַקְּדוֹשׁוֹת שֶׁלָּהֶם בָּאוֹת מִמֶּנּוּ. נַפְשׁוֹת שְׁאָר הָעַמִּים עוֹבְדֵי עַכּוּ\"ם מֵאֵיזֶה מָקוֹם הֵם? אָמַר רַבִּי אֶלְעָזָר, מֵאוֹתָם צִדְדֵי הַשְּׂמֹאל שֶׁמְּטַמְּאִים אוֹתָם יֵשׁ לָהֶם נְשָׁמוֹת, וְלָכֵן כֻּלָּם טְמֵאִים וּמְטַמְּאִים מִי שֶׁקָּרֵב עִמָּם."],[2,"","וַיֹּאמֶר אֱלֹהִים תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה וְגוֹ' - כָּל שְׁאָר הַחַיּוֹת הָאֲחֵרוֹת כָּל אַחַת וְאַחַת כְּפִי מִינָהּ. וְאָמַר רַבִּי אֶלְעָזָר, זֶה מְסַיֵּעַ לְמַה שֶּׁאָמַרְנוּ שֶׁנֶּפֶשׁ חַיָּה אֵלּוּ יִשְׂרָאֵל, שֶׁהֵם נֶפֶשׁ חַיָּה קְדוֹשָׁה עֶלְיוֹנָה. בְּהֵמָה וָרֶמֶשׂ וְחַיְתוֹ אֶרֶץ - אֵלּוּ שְׁאָר הָעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה שֶׁאֵינָם נֶפֶשׁ חַיָּה, אֶלָּא (ד\"א ערלה) כְּמוֹ שֶׁאָמַרְנוּ."],[3,"","נַעָשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ - שֶׁנִּכְלָל בְּשִׁשָּׁה צְדָדִים כָּלוּל מֵהַכֹּל כְּמוֹ שֶׁלְּמַעְלָה, בְּאֵיבָרִים מְתֻקָּנִים בְּסוֹד הַחָכְמָה כָּרָאוּי, הַכֹּל תִּקּוּן עֶלְיוֹן. נַעֲשֶׂה אָדָם - סוֹד שֶׁל זָכָר וּנְקֵבָה, הַכֹּל בְּחָכְמָה קְדוֹשָׁה עֶלְיוֹנָה. בְּצַלְמֵנוּ כִּדְמוּתֵנוּ - לְהִתְתַּקֵּן זֶה בָּזֶה לִהְיוֹת (אחד) הוּא יְחִידִי בָּעוֹלָם שַׁלִּיט עַל הַכֹּל."],[4,"","וַיַּרְא אֱלֹהִים אֶת כָּל אֲשֶׁר עָשָׂה (ד\"א כלל) וְהִנֵּה טוֹב מְאֹד - כָּאן נִתְקַן מַה שֶּׁלֹּא נֶאֱמַר כִּי טוֹב בַּשֵּׁנִי, מִשּׁוּם שֶׁבּוֹ נִבְרָא הַמָּוֶת. וְכָאן נֶאֱמַר וְהִנֵּה טוֹב מְאֹד, וְהוֹלְכִים כְּמוֹ שֶׁאָמְרוּ הַחֲבֵרִים, וְהִנֵּה טוֹב מְאֹד - זֶה הַמָּוֶת."],[5,"","וַיַּרְא אֱלֹהִים אֶת כָּל אֲשֶׁר עָשָׂה וְהִנֵּה טוֹב מְאֹד, וְכִי לֹא רָאָה אוֹתוֹ קֹדֶם? אֶלָּא הַכֹּל רָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא. וּמַה שֶּׁאָמַר אֶת כָּל - לְרַבּוֹת כָּל הַדּוֹרוֹת שֶׁיָּבוֹאוּ אַחַר כָּךְ, וְכֵן כָּל מַה שֶּׁיִּתְחַדֵּשׁ בָּעוֹלָם בְּכָל דּוֹר וָדוֹר בְּטֶרֶם שֶׁיָּבוֹאוּ לָעוֹלָם. אֲשֶׁר עָשָׂה - זֶה כָּל מַעֲשֵׂי בְרֵאשִׁית שֶׁשָּׁם נִבְרָא יְסוֹד וְעִקָּר לְכָל מַה שֶּׁיָּבֹא וְיִתְחַדֵּשׁ בָּעוֹלָם לְאַחַר מִכֵּן. וּמִשּׁוּם כָּךְ רָאָה אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא עַד שֶׁלֹּא הָיָה, וְשָׂם אֶת הַכֹּל בְּמַעֲשֵׂה בְרֵאשִׁית."],[6,"","יוֹם הַשִּׁשִּׁי - מַה שּׁוֹנֶה בְּכָל הַיָּמִים שֶׁלֹּא נֶאֱמַר בָּהֶם הֵ\"א? אֶלָּא כָּאן כַּאֲשֶׁר נִתְקַן הָעוֹלָם, הִתְחַבְּרָה הַנְּקֵבָה בַּזָּכָר בְּחִבּוּר אֶחָד. ה' בַּשִּׁשִּׁי (שהוא) (יסוד) לִהְיוֹת הַכֹּל אֶחָד. וַיְכֻלּוּ - נִתְקְנוּ הַכֹּל אֶחָד (כאחד). נִתְקְנוּ מֵהַכֹּל וְהִשְׁתַּלְּמוּ בַּכֹּל."],[7,"","וַיְכֻלּוּ הַשָּׁמַיִם וְהָאָרֶץ וְכָל צְבָאָם. רַבִּי אֶלְעָזָר פָּתַח, (תהלים לא) מָה רַב טוּבְךְ אֲשֶׁר צָפַנְתָּ לִּירֵאֶיךְ פָּעַלְתָּ לַחוֹסִים בָּךְ נֶגֶד בְּנֵי אָדָם. בּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא בָּרָא אָדָם בָּעוֹלָם וְהִתְקִין אוֹתוֹ לִהְיוֹת שָׁלֵם בַּעֲבוֹדָתוֹ וּלְתַקֵּן אֶת דְּרָכָיו כְּדֵי שֶׁיִּזְכֶּה לָאוֹר הָעֶלְיוֹן שֶׁגָּנַז הַקָּדוֹשׁ בָּרוּךְ הוּא לַצַּדִּיקִים, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה סד) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ יַעֲשֶׂה לִמְחַכֵּה לוֹ."],[8,"","וּבַמֶּה יִזְכֶּה הָאָדָם לְאוֹתוֹ הָאוֹר? בַּתּוֹרָה. שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה בְּכָל יוֹם, יִזְכֶּה לִהְיוֹת לוֹ חֵלֶק בָּעוֹלָם הַבָּא, וְיֵחָשֵׁב לוֹ כְּאִלּוּ בָּנָה עוֹלָמוֹת, שֶׁהֲרֵי בַּתּוֹרָה נִבְנָה הָעוֹלָם וְנִתְקַן. זֶהוּ שֶׁכָּתוּב (משלי ג) ה' בְּחָכְמָה יָסַד אֶרֶץ כּוֹנֵן שָׁמַיִם בִּתְבוּנָה, וְכָתוּב (שם ח) וָאֶהְיֶה אֶצְלוֹ אָמוֹן וָאֶהְיֶה שַׁעֲשׁוּעִים יוֹם יוֹם. שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בָּהּ, מְתַקֵּן עוֹלָמוֹת וּמְקַיֵּם אוֹתָם. וּבֹא וּרְאֵה, בָּרוּחַ עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם וּבָרוּחַ הוּא עוֹמֵד, רוּחַ שֶׁל אֵלּוּ שֶׁעוֹסְקִים בַּתּוֹרָה, וְכָל שֶׁכֵּן רוּחַ שֶׁל הֶבֶל תִּינוֹקוֹת שֶׁל בֵּית רַבָּן."],[9,"","מָה רַב טוּבְךְ - זֶה הַטּוּב שֶׁנִּגְנַז. לִּירֵאֶיךְ - לְאוֹתָם יִרְאֵי חֵטְא. פָּעַלְתָּ לַחוֹסִים בָּךְ - מַה זֶּה פָּעַלְתָּ? זֶה מַעֲשֵׂה בְרֵאשִׁית. רַבִּי אַבָּא אָמַר, זֶה גַּן עֵדֶן, שֶׁהֲרֵי בְּאֻמָּנוּת עָשָׂה אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בָּאָרֶץ כְּמוֹ שֶׁלְּמַעְלָה, לְחַזֵּק בּוֹ אֶת הַצַּדִּיקִים. זֶהוּ שֶׁכָּתוּב (תהלים לא) פָּעַלְתָּ לַחוֹסִים בָּךְ נֶגֶד בְּנֵי אָדָם. שֶׁהֲרֵי הוּא נֶגֶד (בני) אָדָם, וְהָאַחֵר נֶגֶד עֶלְיוֹנִים קְדוֹשִׁים. אָמַר רַבִּי שִׁמְעוֹן, גַּן הָעֵדֶן לְמַעְלָה וְנֶגֶד בְּנֵי אָדָם הוּא, (ואפלו האחר הוא נגד בני אדם) לְהִתְכַּנֵּס בּוֹ צַדִּיקִים שֶׁעוֹשִׂים רְצוֹן רִבּוֹנָם."]]],[["וַיְכֻלּוּ, דְּכָלוּ עוֹבָדִין דִּלְעֵילָא וְעוֹבָדִין דִּלְתַתָּא. הַשָּׁמַיִם וְהָאָרֶץ לְעֵילָא וְתַתָּא. רַבִּי שִׁמְעוֹן אָמַר עוֹבָדָא וְאוּמָנוּתָא דְּאוֹרַיְיתָא שֶׁבִּכְתָב וְעוֹבָדָא וְאוּמָנוּתָא דְּתוֹרָה שֶׁבְּעַל פֶּה. וְכָל צְבָאָם אִלֵּין פְּרָטֵי דְאוֹרַיְיתָא אַפִּין דְּאוֹרַיְיתָא שִׁבְעִים פָּנִים לַתּוֹרָה. וַיְכֻלּוּ, דְּאִתְקַיְּימוּ וְאִשְׁתַּכְלְלוּ דָּא בְּדָא. שָׁמַיִם וָאָרֶץ פְּרַט וּכְלַל. וְכָל צְבָאָם, רָזֵי דְאוֹרַיְיתָא דַּכְיָאן דְּאוֹרַיְיתָא מְסָאֲבָן דְּאוֹרַיְיתָא.","וַיְכַל אֱלהִים בַּיּוֹם הַשְּׁבִיעִי דָּא תּוֹרָה שֶׁבְּעַל פֶּה דְּאִיהוּ יוֹם שְׁבִיעִי, וּבֵיהּ אִשְׁתַּכְלַל עָלְמָא דְּאִיהוּ קִיּוּמָא דְּכֹלָּא. מְלַאכְתּוֹ אֲשֶׁר עָשָׂה וְלֹא כָּל מְלַאכְתּוֹ, דְּהָא תּוֹרָה שֶׁבִּכְתָב אַפִּיק כֹּלָּא בְּתוּקְפָא דִּכְתַב דְּנָפִיק מֵחָכְמְתָא.","תְּלַת זִמְנִין הָכָא בַּיּוֹם הַשְּׁבִיעִי. וַיְכַל אֱלהִים בַּיּוֹם הַשְּׁבִיעִי. וַיִּשְׁבּוֹת בַּיּוֹם הַשְּׁבִיעִי. וַיְבָרֶךְ אֱלֹהִים אֶת יוֹם הַשְּׁבִיעִי. הָא תְּלַת. וַיְכַל אֱלהִים בַּיּוֹם הַשְּׁבִיעִי, דָּא תּוֹרָה שֶׁבְּעַל פֶּה, דְּעִם יוֹם הַשְּׁבִיעִי דָא אִשְׁתַּכְלַל עָלְמָא כְּדְקָא אֲמָרָן.","וַיִּשְׁבּוֹת בַּיּוֹם הַשְּׁבִיעִי, דָּא יְסוֹדָא דְעָלְמָא. בְּסִפְרָא דְּרַב יֵיבָא סָבָא דָּא יוֹבְלָא וְעַל כָּךְ כְּתִיב הָכָא מִכָּ\"ל מְלַאכְתּוֹ דְּכֹלָּא נָפִיק מִנֵּיהּ. וְאֲנַן דָּא יְסוֹדָא כִּדְקָאֲמָרָן דְּהָא נַיְיחָא בֵּיהּ הֲוָה יַתִּיר מִכֹּלָּא.","וַיְבָרֶךָ אֱלֹהִים אֶת יוֹם הַשְּׁבִיעִי. דָּא כֹּהֵן גָּדוֹל דִּמְבָרֵךְ לְכֹלָּא וְהוּא נָטִיל בְּרֵישָׁא דִּתְנַן כֹּהֵן נוֹטֵל בָּרֹאשׁ, וּבִרְכָאן בֵּיהּ שַׁרְיָין לְבָרְכָא וְאִקְרֵי שְׁבִיעִי. רַבִּי יֵיסָא סָבָא אָמַר הָנִי תְּרֵי חַד בִּיסוֹדָא דְּעָלְמָא אִיהוּ, וְחַד בְּעַמּוּדָא דְּאֶמְצָעִיתָא. (ד\"א ל\"ג) (אבל הני תלת חד במעלי שבתא דליליא וחד דיומא וחד דעלמא דאתי דאיהו שבת הגדול).","וְכֵן (ד\"א ל\"ג ויקדש) אוֹתוֹ, לְמָאן, לְהַהוּא אֲתַר דְּאָת קַיָּימָא בֵּיהּ שַׁרְיָא כְּמָא דְאַתְּ אָמֵר, (שמואל ב ט״ו:כ״ה) וְהִרְאַנִי אוֹתוֹ וְאֶת נָוִהוּ. וּבְהַאי אֲתַר שַׁרְיָין כָּל קִדוּשִׁין לְעֵילָא (ד\"א דלעילא), וְנָפְקֵי מִנֵּיהּ לִכְנְסֶת יִשְׂרָאֵל לְמֵיהַב לָהּ תַּפְנוּקָא לֶחֶם פַּנָּג, וְאָזְלָא הָא כְּמָה דִכְתִיב, (בראשית מ״ט:כ׳) מֵאָשֵׁר שְׁמֵנָה לַחְמוֹ וְהוּא יִתֵּן מַעֲדַנֵּי מֶלֶךְ, מֵאָשֵׁר דָּא קְיָים שְׁלִים דְּהֲוָה (ד\"א ל\"ג) (ליה) לֶחֶם עוֹנִי אִתְהַדַּר לְמֶהוֵי לֶחֶם פַּנָּג. וְהוּא יִתֵּן מַעֲדַנֵּי מֶלֶךְ. מַאן מֶלֶךְ, דָּא כְּנְסֶת יִשְׂרָאֵל. הוּא יָהִיב (ד\"א לה) כָּל תַּפְנוּקִין דְּעָלְמִין, וְכָל קִדּוּשִׁין דְּנָפְקִין מִלְּעֵילָא מֵהַאי אֲתַר נָפְקִין. וְעַל דָּא וַיְקַדֵּשׁ אוֹתוֹ, הַהוּא אָת קַיָּימָא.","כִּי בוֹ שָׁבַת. בֵּיהּ נַיְיחָא דְכֹלָּא, (ד\"א ביה נייחא) דְּעִלָּאִין וְתַתָּאִין. בֵּיהּ שַׁבַּתָּא (ד\"א אתייא) לְנַיְיחָא. אֲשֶׁר בָּרָא אֱלֹהִים מִכְּלָלָא דְּזָכוּר נַפְקָא שָׁמוֹר לְאַתְקָנָא עֲבִידְתָּא דְעָלְמָא. לַעֲשׂוֹת דָּא אוֹמָנָא דְעָלְמָא. לְמֶעְבַּד עֲבִידְתָּא דְּכֹלָּא. (ס\"א אשר ברא אומנא אצטריך לעלמא וכל עבידתא דכלא).","תּוּ פָּרִישׁ רַבִּי שִׁמְעוֹן מִלָּה וְאָמַר, כְּתִיב, (דברים ז׳:ט׳) שׁוֹמֵר הַבְּרִית וְהַחֶסֶד. שׁוֹמֵר דָּא כְּנֶסֶת יִשְׂרָאֵל. הַבְּרִית דָּא יְסוֹדָא דְעָלְמָא. וְהַחֶסֶד דָּא אַבְרָהָם, דִּכְנֶסֶת יִשְׂרָאֵל הִיא שׁוֹמֵר הַבְּרִית וְהַחֶסֶד, וְאִקְרֵי שׁוֹמֵר יִשְׂרָאֵל, דָּא הוּא נָטִיר פִּתְחָא דְכֹלָּא, בֵּיהּ תַּלְיָין כָּל עֲבִידָן דְּעָלְמָא וַדַּאי, אֲשֶׁר בָּרָא אֱלהִים לַעֲשׂוֹת, לְשַׁכְלְלָא לְאַתְקָנָא כֹּלָּא כָּל יוֹמָא וְיוֹמָא וּלְאַפָּקָא רוּחִין וְנִשְׁמָתִין (קדישין לעלמא), וְאֲפִילּוּ רוּחִין וְשֵׁדִין.","וְאִי תֵימָא דְּלָאו אִנּוּן תִּקּוּנָא דְעָלְמָא. לָאו הָכִי. דְּהָא אִנּוּן לְתִקּוּנָא דְּעָלְמָא הֲווּ וּלְאַלְקָאָה בְּהוּ לְחַיָּיבֵי עָלְמָא דְּאִנּוּן אָזְלִין לְקִבְלַיְיהוּ לְאוֹכָחָא לְהוּ. וּמַאי דְּאֲזִיל לִשְׂמָאלָא אִתְאַחִיד בְּסִטְרָא שְׂמָאלָא לְקִבְלַיְיהוּ (ס\"א לקי בהו) בְּגִינֵי כָךְ לְתִקּוּנָא הֲווּ. תָּא חֲזֵי, מַה כְּתִיב בִּשְׁלֹמֹה (שמואל ב ז׳:י״ד) וְהוֹכַחְתִּיו בְּשֵׁבֶט אֲנָשִׁים וּבְנִגְעֵי בְּנֵי אָדָם. מַאן (קסט ע\"ב) נִגְעֵי בְּנִי אָדָם. אִלֵּין אִנּוּן מַזִּיקִין."],[[0,"ויכלו, דכלו עובדין לעילא ועובדין דלתתא, השמים וארץ לעילא ותתא,","ויכלו, פירושו שכלו ונגמרו המלאכות של מעלה והמלאכות של מטה, כי השמים וארץ יורו למעלה ולמטה. השמים, פירושו למעלה בעולמות עליונים, וארץ, פירושו למטה בעולם התחתון."],[0,"ר\"ש אמר, עובדא ואומנותא דאורייתא שבכתב, ועובדא ואומנותא דתורה שבעל פה:","ר\"ש אומר שהכ' \u0003השמים,\u0004 יורה שנגמרו הפעולות והאומנות שבתורה שבכתב, דהיינו של בנין ז\"א המכונה תורה שבכתב, והכ' \u0003והארץ,\u0004 יורה, שנגמרו הפעולות והאומנות שבתורה שבעל פה, דהיינו של בנין הנוקבא, המכונה תורה שבע\"פ. \u0003עובדא,\u0004 פירושו בחינת ו\"ק, \u0003ואומנותא,\u0004 פירושו ג\"ר. \u0003וכל צבאם, אלין פרטי דאורייתא, אפין דאורייתא, שבעים פנים לתורה,\u0004 וכל צבאם, פירושו פרטי התורה, הפנים שבתורה, דהיינו השבעים פנים שבתורה. שהם פרטי בנין של ז\"א המכונה תורה. \u0003ויכלו דאתקיימו ואשתכללו דא בדא,\u0004 ויכלו השמים וארץ, יורה ששניהם, ז\"א ונוקביה המכונים שמים וארץ, נתקיימו ונשתכללו זה מזה, \u0003שמים וארץ, פרט וכלל,\u0004 זו\"ן הנק' שמים וארץ, הם פרט וכלל, כי הז\"א הוא בחינת פרט, כי המוחין יוצאים בו בפרטות בזה אחר זה, ומשפיע אותם להנוק' בדרך כלל, דהיינו בבת אחת. ונצרכים זה לזה, ונשתכללו זה מזה כנ\"ל, בסוד פרט הצריך לכלל וכלל הצריך לפרט. \u0003וכל צבאם, רזי דאורייתא, דכיאן דאורייתא מסאבן דאורייתא,\u0004 וכל צבאם, היינו סודות התורה, והטהרות שבתורת והטומאות שבתורה, כלומר דיני טהרה וטומאה הכתובים בהתורה. כי \u0003צבא\u0004 נוטריקון \u0003צא בא\u0004 אשר \u0003צא\u0004 רומז על הטומאות ו\u0003בא,\u0004 על הטהרות. וביאור ענין פרט וכלל הוא להלן."],[1,"ויכל אלקים ביום השביעי דא תורה שבעל פה, דאיהו יום שביעי, וביה אשתכלל עלמא, דאיהו קיומא דכלא:","הכתוב, ויכל אלקים ביום השביעי, היינו תורה שבעל פה דהיינו המלכות שהיא יום השביעי. כי ז\"א כולל ששת ימים, שהם חג\"ת נה\"י, והנוקבא, היא מלכות יום השביעי. ובו נשתכלל העולם, כי הוא הקיום של הכל. \u0003מלאכתו אשר עשה, ולא כל מלאכתו, דהא תורה שבכתב אפיק כלא בתוקפא דכתב דנפק מחכמתא,\u0004 נאמר מלאכתו אשר עשה, ולא נאמר כאן ויכל אלקים ביום השביעי את כל מלאכתו אשר עשה, הוא משום שהתורה שבכתב, שהוא ז\"א, הוציא וגמר הכל בתוקף הכתב, שהם המוחין, היוצאים ונמשכים מהחכמה, שהוא או\"א עלאין. ונמצא שעוד לא נגמר כל מלאכתו ביום השביעי שהיא מלכות אלא ע\"י הז\"א. וע\"כ נאמר בו רק מלאכתו אשר עשה, ולא כל מלאכתו. וביאור הדברים להלן בדיבור הסמוך."],[2,"תלת זמנין הכא ביום השביעי, ויכל וגו', וישבות וגו', ויברך וגו' הא תלת:","שלש פעמים נאמר כאן ביום השביעי, ויכל אלקים ביום השביעי, וישבות וגו', ויברך וגו', הרי נאמר שלש פעמים. \u0003ויכל אלקים ביום השביעי דא תורה שבעל פה, דעם יום השביעי דא אשתכלל עלמא כדקא אמרן,\u0004 ויכל אלקים ביום השביעי, היינו תורה שבעל פה, שהיא מלכות, נוקבא דז\"א, ומדה השביעית לחג\"ת נה\"י דז\"א, כי עם יום השביעי הזה, נשתכלל ונגמר העולם כמו שאמרנו."],[2,"","ביאור הדברים. כי מעשה בראשית הוא \u0003יסודא ועקרא לכל מה דייתי ויתחדש בעלמא לבתר כן,\u0004 (כנ\"ל באות קע\"ד) ונמצא סו\"ה ויכל אלקים ביום השביעי מלאכתו אשר עשה, הוא יסוד ושורש של גמר התקון העתיד לבא אחר השתא אלפי שני. ונודע שענין גמר התקון סובב רק על המלכות דמלכות שה\"ס עצם המלכות, שאין לה תקון בשתא אלפי שני, (כנ\"ל דף מ\"ו ד\"ה ביאור) ונמצא שמלכות דמלכות זו, ה\"ס התכלית שבשביל גילויה נבראו כל מעשה בראשית שבששת ימים, וז\"ס שז\"א ונוקביה ה\"ס פרט וכלל, כי הז\"א שה\"ס ששת ימי בראשית, וכן בחינת שתא אלפי שני הוא פרט, דהיינו שבו יוצאים כל פרטי המציאות בלי חסרון כל שהוא, והם מתגלים בשתא אלפי שני בזה אחר זה, והנוקבא, שה\"ס יום השביעי, מלכות, היא מקבלת ממנו בחינת כלל, דהיינו שכל אלו הפרטים שבשתא אלפי שני, מגלים את שלימותה בגמר התקון, דהיינו באלף השביעי, ומבחינת יסודא ועקרא להעתיד לבא נמצא, יום השביעי, שהוא בחינת גמר התקון שנתקבל מכל פרטי הבריאה שבששת ימי בראשית. וז\"ס \u0003אתה קדשת את יום השביעי לשמך,\u0004 דהיינו בשביל המלכות הנק' שם,\u0003תכלית מעשה שמים וארץ,\u0004 היא בחינת התכלית המקובל מכל פרטי הבריאה שבשמים וארץ שבששת ימי בראשית. כמו שמסיים, \u0003וברכת מכל הימים וקדשתו מכל הזמנים,\u0004 הרי שששת ימים הם פרט, ויום השביעי הוא כלל, דהיינו התכלית של ששת הימים. ומבחינה זו נאמר ויכל אלקים ביום השביעי מלאכתו אשר עשה. כי יום השביעי היא קבלת התכלית שמים וארץ. וז\"ש \u0003דעם יום השביעי דא אשתכלל עלמא,\u0004 שקיבל התכלית ונשתכללו."],[2,"","ומלבד האמור מבחינת התכלית המרומז בויכל, הרי נוהג גם בחיבת מוחין ביום השביעי, ומוחין באים תמיד בסוד ג' קוין הנמצאים מג' נקודות חולם שורק חירק כנ\"ל (בראשית א' דף ט\"ז ד\"ה וזה) ועליהם נאמר, וישבות ויברך ויקדש. וישבות ה\"ס קו שמאל ויברך ה\"ס קו ימין, ויקדש ה\"ס קו אמצעי. כמו שהזהר מבאר לפנינו."],[2,"","וזה אמרו \u0003תלת זמנין הכא ביום השביעי, ויכל\u0004 וגו' \u0003וישבות\u0004 וגו' \u0003ויברך\u0004 וגו'. ויכל ה\"ס אור התכלית, וישבות ה\"ס הארת המוחין בבחינת קו שמאל, ויברך ה\"ס קו ימין של המוחין. וכל אלו הג' נקראים שביעי, להיותם סוד הג\"ר. אבל הארת קו אמצעי של המוחין, המרומז בויקדש וגו', אינו נקרא שביעי להיותו מכריע בסוד מסך דחירק, וע\"כ לא נאמר ויקדש את יום השביעי, אלא \u0003ויקדש אותו,\u0004 שה\"ס אות ברית, כמו שמבאר הזהר לפנינו."],[3,"וישבות ביום השביעי דא יסודא דעלמא:","וישבות ביום השביעי הוא יסוד העולם. \u0003בספרא דרב ייבא סבא דא יובלא, ועל כך כתיב הכא מכל מלאכתו, דכלא נפיק מניה,\u0004 בספרו של רבי ייבא הזקן כתוב, שוישבות וגו' הוא על יובל, דהיינו הארת השמאל שבבינה, שה\"ס נקודת השורק, וע\"כ כתוב כאן מכל מלאכתו, משום שהכל יוצא ממנו, פירוש. כי בהכ' ויכל, אומר לעיל (באות ק\"פ) \u0003מלאכתו אשר עשה ולא כל מלאכתו, דהא תורה שבכתב אפיק כלא בתוקפא דכתב דנפק מחכמתא,\u0004 כי בויכל, שה\"ס תכלית שמים וארץ, לא היה יכול לומר, כל \u0003מלאכתו,\u0004 כי עדיין לא נגמר אלא בבחינת \u0003יסודא ועקרא\u0004 בלבד, ורק תושב\"כ, שה\"ס ז\"א, מוציא וגומר כל המלאכה בתוקף המוחין דכתב היוצאים מחכמה, דהיינו ע\"י הארת החכמה, הנמשכת בתוקף ובגבורות מהשמאל שבבינה החוזרת להיות חכמה. אבל כאן בוישבות, שה\"ס הארת השמאל הנמשך מהבינה הנקראת יובלא, הרי מכאן יוצאים כל המוחין המביאים את גמר התקון, ע\"כ נאמר כאן \u0003מכל מלאכתו אשר עשה,\u0004 כי מכאן נגמרת כל המלאכה. \u0003ואנן, דא יסודא כדקאמרן, דהא נייחא ביה, הוה יתיר מכלא,\u0004 ואנו אומרים, שוישבות קאי על יסוד, ולא על יובלא, כי המנוחה שבו הוא יותר מכל, כלומר, השביתה שבהארת יסוד, הוא מגולה יותר מהשביתה שבהארת יובלא, ע\"כ מוכיח ר\"ש, אשר וישבות, זה יסוד, ולא יובלא. פירוש. ר\"ש אינו חולק על רבי ייבא סבא, אלא מוסיף על דבריו, כי גם ר\"ש מודה שסוד השביתה ה\"ס הארת יובלא, דהיינו קו שמאל אשר בבינה, אלא שאומר, שהכתוב וישבות, קאי על היסוד המאיר הארת יובלא הזו אל המלכות, כי הארת שמאל אינו נשלם רק בהיסוד, שבו סוד השביתה והמנוחה הגמורה."],[4,"ויברך אלקים את יום השביעי דא כהן גדול דמברך לכלא והוא נטיל ברישא,","הכ' ויברך וגו' קאי על כהן גדול שהוא מברך לכל, והוא לוקח בראש, \u0003דתנן כהן נוטל בראש\u0004 דתנן, כהן לוקח חלקו בראש כל המסובים. \u0003וברכאן ביה שריין לברכא ואקרי שביעי,\u0004 והברכות שורים בו, לברך לכל, והוא נקרא שביעי, פירוש ויברך ה\"ס הארת קו ימין, הנמשך מאו\"א עלאין, הנק' כהן גדול, והם בחינת חסדים בסוד זווג דלא פסיק, וז\"ש \u0003וברכאן ביה שריין לברכא,\u0004והוא בחינת \u0003ראש,\u0004 (כמ\"ש לעיל דף ל\"ו במראות הסולם ד\"ה ולפיכך ע\"ש) וע\"כ בא עליהם הרמז \u0003כהן נוטל בראש,\u0004 וכן אומר הזהר (להלן ויצא אות ו') דאבא עלאה ואמא עלאה ה\"ס תפילין שבראש וה\"ס כהן נוטל בראש ע\"ש. והנה נתבארו ב' הקוין המאירים בסוד שביעי קו ימין בויברך וגו', קו שמאל בוישבות וגו'."],[4,"רבי ייסא סבא אמר, הני תרי, חד ביסודא דעלמא איהו וחד בעמודא דאמצעיתא:","רי\"ס אמר, אלו השנים, דהיינו ויכל וגו' ויברך וגו', אחד קאי על יסוד העולם ואחד על עמוד האמצעי שהוא ת\"ת. פירוש. כי מובא לעיל שרבי ייסא סבא ביאר הכ' וישבות על יובלא, וכמ\"ש בדיבור הסמוך, ועתה מבאר שני הכתובים הנשארים, אשר ויכל וגו' קאי על הארת היסוד, והוא מלשון כל, כי היסוד נק' כל והכתוב ויברך קאי על עמוד האמצעי, כלומר על הארת קו אמצעי המכריע בין הקוין ימין ושמאל. ונמצא שרבי ייסא סבא מבאר את ג' שביעי בג' הקוין, ויכל שהוא הארת יסוד לקו ימין וישבות לקו שמאל, ויברך לקו אמצעי."],[5,"וכן ויקדש אותו, למאן, לההוא אתר דאת קיימא ביה שריא, כד\"א והראני וגו':","וכן, אר\"ש, שהכ' ויקדש אותו קאי ג\"כ על היסוד, כי נאמר ויקדש אותו, ואינו אומר למי, כמו שאומר בויכל ובוישבות ובויברך, והוא דקאי על אותו מקום שאות הברית שורה בו, דהיינו יסוד, כי המלה אותו הוא מלשון אות ברית, וכמ\"ש והראני אותו ואת נוהו, שאותו קאי על יסוד, ונוהו על המלכות כנודע, כן אותו שבכאן קאי על היסוד. פירוש, כי ב' בחינות יש ביסוד א) היא הארת השביתה שמקבל מיובלא, וע\"ז אומר לעיל אשר וישבות וגו' הוא יסוד. ב) שהוא הנושא אל המסך דחירק, שהת\"ת מכריע על ידו בב' הקוין ימין ושמאל, ומבחינה זו אומר כאן אשר ויקדש אותו הוא ג\"כ יסוד, כי הוא מכריע בין ב' הקוין הנרמזים בוישבות ובויברך."],[5,"ובהאי אתר שריין כל קדושין לעילא, ונפקי מניה לכנסת ישראל למיהב לה תפנוקא לחם פנג:","ובמקום ההוא, דהיינו בהיסוד, שורות כל חקדושות למעלה, ומשם יוצאים לכנסת ישראל, דהיינו להנוקבא, ליתן לה תענוגים ולחם ענג, \u0003ואזלא הא כמה דכתיב מאשר שמנה לחמו וגו', מאשר דא קיים שלים,\u0004 וזהו הולך כמו שכתוב, מאשר שמנה לחמו וגו' מאשר היינו ברית השלם, שהוא יסוד, \u0003שמנה לחמו, מאן דהוה לחם עוני אתהדר למהוי לחם פנג,\u0004 שמנה לחמו, יורה, שמה שהיה, מטרם תקון היסוד, בבחינת לחם עוני, חזר עתה ונעשה ללחם ענג. \u0003והוא יתן מעדני מלך, מאן מלך, דא כנסת ישראל, הוא יהיב לה כל תפנוקין דעלמא,\u0004 שואל, מי הוא המלך שבהכ' והוא יתן מעדני מלך, ואומר שהוא כנסת ישראל דהיינו הנוקבא דז\"א, אשר היסוד נותן לה כל מעדני עולם \u0003וכל קדושין דנפקין מלעילא מהאי אתר נפקין ועל דא ויקדש אותו, ההוא את קיימא,\u0004 וכל הקדושות היוצאות מלמעלה, יוצאות ממקום הזה, דהיינו יסוד, וע\"כ נאמר ויקדש אותו, שהוא אות ברית הזה, דהיינו יסוד, כנ\"ל."],[6,"כי בו שבת, ביה נייחא דכלא, דעלאין ותתאין, ביה שבתא לנייחא:","הכתוב כי בו שבת יורה, כי בו, דהיינו בהיסוד, נמצא המנוחה לכל, הן לעליונים, והן לתחתונים, בו השבת למנוחה. פירוש. כי ב' בחינות יש ביסוד, א' בחינת השביתה שמקבל מיובלא, וב' מה שהוא נושא אל המסך דחירק, שבו מכריע ועושה שלום ומנוחה, הן בב' קוין ימין ושמאל העליונים אשר בישסו\"ת, והן בב' קוין ימין ושמאל התחתונים אשר בז\"א. ולפיכך בחינת השביתה שמקבל מיובלא נמצא אצלו במנוחה, וז\"ש \u0003ביה שבתא לנייחא,\u0004 שהארת השביתה שמקבל נמצאת אצלו בסוד המנוחה."],[6,"אשר ברא אלקים, מכללא דזכור נפקא שמור לאתקנא עבידתא דעלמא:","אשר ברא אלקים, יורה, שמכלל זכור יצא שמור, כדי לתקן מלאכת העולם. פירוש. ברא יורה על קטנות, כנ\"ל (בהקדמת הזהר דף ס' אות מ\"ה) שאומר \u0003דמלה סתימאה איהו, ברא.\u0004 וע\"כ ה\"ס שמור, והשם אלקים שבכאן יורה על גדלות הבינה, שאז נקראת אלקים, וה\"ס זכור, ואומר אשר מכלל הגדלות יצא הקטנות, כדי לתקן מלאכת העולם, שהיא מלכות, כלומר שמתוך שקבלה הנוקבא, שהיא העולם, קטנות הזאת של הבינה, נעשית מוכשרת בזה שתוכל לקבל גם את הגדלות דבינה, שה\"ס שם הקדוש אלקים שבבינה, כי סוד אלקים שבמעשה בראשית הוא בינה. ונמצא קבלת הקטנות המרומזת בהמלה \u0003ברא,\u0004 הוא לתקון העולם. \u0003לעשות, דא אומנא דעלמא, למעבד עבידתא דכלא,\u0004 לעשות, זהו אומנות העולם, דהיינו המוחין דגדלות הנק' אומנות. כי לעשות יורה על מלאכה השלמה. לעשות עשיה המשלמת הכל."],[7,"תו פריש ר\"ש מלה ואמר, כתיב שומר הברית והחסד, שומר, דא כנסת ישראל. הברית, דא יסודא דעלמא. והחסד, דא אברהם:","עוד פירש ר\"ש הדבר, דהיינו את הכ' אשר ברא אלקים לעשות. ואמר, כתוב שומר הברית והחסד. שומר, זה כנסת ישראל, דהיינו מלכות. הברית זה יסוד העולם, דהיינו היסוד דז\"א, והחסד זה אברהם, דהיינו חסד דז\"א. \u0003דכנסת ישראל היא שומר הברית והחסד ואקרי שומר ישראל,\u0004 כי כנסת ישראל, שהיא המלכות, היא שומרת את הברית והחסד, שפירושו יסוד וחסד דז\"א, וע\"כ נקראת המלכות שומר ישראל, כי ז\"א נק' ישראל והמלכות השומרת את הספירות שלו הרי היא שומר ישראל. \u0003דא הוא נטיר פתחא דכלא,\u0004 זו שומרת הפתח דכל הספירות דז\"א, כי יסוד היא ספירה שלו התחתונה, והחסד היא העליונה, וכיון ששומרת עליהם, היא נמצאת שומרת על כל הספירות שלו מיסוד עד החסד. \u0003ביה תליין כל עבידן דעלמא,\u0004 בה, בהמלכות, תלוים כל העשיות שבעולם. כלומר מלבד שהיא השומרת על כל ספירותיו של הז\"א שלא יתאחזו החיצונים בהם, שה\"ס מצות הלא תעשה, הרי גם כל התקונים והעשיות שבעולם תלויה בה, שה\"ס מצות עשה. \u0003ודאי, אשר ברא אלקים לעשות, לשכללא ולאתקנא כלא, כל יומא ויומא,\u0004 נמצא ודאי, אשר ברא אלקים לעשות, דהיינו לשכלל ולתקן הכל, כל יום ויום, דהיינו לכל יום ויום מששת ימי בראשית. שהם שש ספירות חג\"ת נה\"י דז\"א, \u0003ולאפקא רוחין ונשמתין, ואפילו רוחין ושדין,\u0004 ולהוליד רוחות ונשמות קדושות, ואפילו הרוחות והשדים הם בכלל אשר ברא אלקים לעשות, פירוש. ר\"ש דורש לשון לעשות שהוא לשון שכלול וגמר, ומשמיענו הכ' שכל מה שברא אלקים בששת ימי בראשית צריך עוד שכלול ותקון, וע\"כ אומר הכ' ברא אלקים לעשות, לשכלל ולתקן אותו."],[8,"ואי תימא דלאו אינון תקונא דעלמא, לאו הכי דהא אינון לתקונא דעלמא הוו,","אם תאמר, שהם, דהיינו הרוחות והשדים, אינם לתקון העולם, אינו כן, אלא גם הם נבראו לתקון העולם. \u0003ולאלקאה בהו לחייבי עלמא דאינון אזלין לקבלייהו לאוכחא להו,\u0004 דהיינו להלקות על ידיהם את רשעי עולם להוכיח להם שילכו בדרך הישר, \u0003ומאי דאזיל לשמאלא אתאחיר בסטרא שמאלא לקבלייהו,\u0004 ומי שהולך לשמאל, נמצא מתדבק בהשדים ורוחות שהם צד השמאל ומתענש על ידיהם. \u0003בגיני כך לתקונא הוו,\u0004 משום זה גם השדים ורוחות הם לתקון העולם, דהיינו להחזיר את הרשעים למוטב. \u0003תא חזי מה כתיב בשלמה והוכחתיו בשבט אנשים ובנגעי בני אדם מאן נגעי בני אדם אלין אנון מזיקין,\u0004 בוא וראה מה כתיב בשלמה והוכחתיו וגו', ושואל, מהו נגעי בני אדם, ואומר שאלו הם המזיקים, דהיינו רוחות ושדים. הרי שהם נבראו לענוש את עוברי עבירה, ובני אדם מפחדים ושומרים עצמם מהחטא."]],[[0,"","וַיְכֻלּוּ - שֶׁכָּלוּ מַעֲשִׂים שֶׁלְּמַעְלָה וּמַעֲשִׂים שֶׁלְּמַטָּה. הַשָּׁמַיִם וְהָאָרֶץ - לְמַעְלָה וּלְמַטָּה. רַבִּי שִׁמְעוֹן אָמַר, מַעֲשֵׂה וְאֻמָּנוּת הַתּוֹרָה שֶׁבִּכְתָב וּמַעֲשֵׂה וְאֻמָּנוּת תּוֹרָה שֶׁבְּעַל פֶּה. וְכָל צְבָאָם - אֵלֶּה פְּרָטֵי הַתּוֹרָה, פָּנִים שֶׁל הַתּוֹרָה, שִׁבְעִים פָּנִים לַתּוֹרָה. וַיְכֻלּוּ - שֶׁהִתְקַיְּמוּ וְנִתְקְנוּ זֶה בָּזֶה. שָׁמַיִם וָאָרֶץ - פְּרָט וּכְלָל. וְכָל צְבָאָם - סוֹדוֹת הַתּוֹרָה, טְהָרוֹת שֶׁבַּתּוֹרָה וְטֻמְאוֹת שֶׁבַּתּוֹרָה."],[1,"","וַיְכַל אֱלֹהִים בַּיּוֹם הַשְּׁבִיעִי - זוֹ תוֹרָה שֶׁבְּעַל פֶּה שֶׁהוּא יוֹם שְׁבִיעִי, וּבָהּ נִתְקַן הָעוֹלָם שֶׁהוּא קִיּוּם שֶׁל הַכֹּל. מְלַאכְתּוֹ אֲשֶׁר עָשָׂה, וְלֹא כָּל מְלַאכְתּוֹ, שֶׁהֲרֵי תּוֹרָה שֶׁבִּכְתָב הוֹצִיאָה הַכֹּל בְּתֹקֶף שֶׁל כְּתָב שֶׁיּוֹצֵא מֵחָכְמָה."],[2,"","שָׁלֹשׁ פְּעָמִים כָּאן בַּיּוֹם הַשְּׁבִיעִי: וַיְכַל אֱלֹהִים בַּיּוֹם הַשְּׁבִיעִי. וַיִּשְׁבּוֹת בַּיּוֹם הַשְּׁבִיעִי. וַיְבָרֶךְ אֱלֹהִים אֶת יוֹם הַשְּׁבִיעִי. הֲרֵי שָׁלֹשׁ. וַיְכַל אֱלֹהִים בַּיּוֹם הַשְּׁבִיעִי - זוֹ תוֹרָה שֶׁבְּעַל פֶּה, שֶׁעִם יוֹם הַשְּׁבִיעִי הַזֶּה נִתְקַן הָעוֹלָם כְּמוֹ שֶׁאָמַרְנוּ."],[3,"","וַיִּשְׁבּוֹת בַּיּוֹם הַשְּׁבִיעִי - זֶה יְסוֹד הָעוֹלָם. בְּסִפְרוֹ שֶׁל רַבִּי יֵיבָא הַזָּקֵן זֶה יוֹבֵל. וְעַל כָּךְ כָּתוּב כָּאן מִכָּל מְלַאכְתּוֹ, שֶׁהַכֹּל יָצָא מִמֶּנּוּ. וְאָנוּ זֶה יְסוֹד, כְּמוֹ שֶׁאָמַרְנוּ, שֶׁהֲרֵי מְנוּחָה בוֹ הָיְתָה יוֹתֵר מֵהַכֹּל."],[4,"","וַיְבָרֶךָ אֱלֹהִים אֶת יוֹם הַשְּׁבִיעִי - זֶה כֹּהֵן גָּדוֹל שֶׁמְּבָרֵךְ אֶת הַכֹּל וְהוּא נוֹטֵל בָּרֹאשׁ, שֶׁשָּׁנִינוּ כֹּהֵן נוֹטֵל בָּרֹאשׁ, וּבוֹ הַבְּרָכוֹת שׁוֹרוֹת לְבָרֵךְ, וְנִקְרָא שְׁבִיעִי. רַבִּי יֵיסָא הַזָּקֵן אָמַר, הַשְּׁנַיִם הַלָּלוּ - אֶחָד הוּא בִּיסוֹד הָעוֹלָם וְאֶחָד בָּעַמּוּד הָאֶמְצָעִי (ד\"א אבל שלשת אלה אחד בערב שבת של לילה, ואחד של היום, ואחד של העולם הבא שהוא שבת הגדול),"],[5,"","וְכֵן (ויקדש) אֹתוֹ, אֶת מִי? אֶת אוֹתוֹ מָקוֹם שֶׁאוֹת הַבְּרִית בּוֹ שׁוֹרָה, כְּמוֹ שֶׁנֶּאֱמַר (שמואל ב טו) וְהִרְאַנִי אֹתוֹ וְאֶת נָוֵהוּ. וּבְמָקוֹם זֶה שׁוֹרִים כָּל הַקִּדּוּשִׁים לְמַעְלָה (שלמעלה) וְיוֹצְאִים מִמֶּנּוּ לִכְנֶסֶת יִשְׂרָאֵל לָתֵת לָהּ תַּפְנוּק לֶחֶם עֹנֶג, וְהוֹלֵךְ זֶה כְּמוֹ שֶׁכָּתוּב (בראשית מט) מֵאָשֵׁר שְׁמֵנָה לַחְמוֹ וְהוּא יִתֵּן מַעֲדַנֵּי מֶלֶךְ. מֵאָשֵׁר - זֶה קִיּוּם שָׁלֵם. שְׁמֵנָה לַחְמוֹ - (מה) שֶּׁהָיָה (לו) לֶחֶם עֹנִי, חוֹזֵר לִהְיוֹת לֶחֶם עֹנֶג. וְהוּא יִתֵּן מַעֲדַנֵּי מֶלֶךְ - מִי הַמֶּלֶךְ? זוֹ כְּנֶסֶת יִשְׂרָאֵל, הוּא נוֹתֵן לָהּ כָּל תַּפְנוּקֵי הָעוֹלָם, וְכָל הַקִּדּוּשִׁים שֶׁיּוֹצְאִים מִלְמַעְלָה, מֵהַמָּקוֹם הַזֶּה יוֹצְאִים. וְלָכֵן וַיְקַדֵּשׁ אֹתוֹ, אֹתוֹ - אוֹת הַבְּרִית."],[6,"","כִּי בוֹ שָׁבַת - בּוֹ מְנוּחַת הַכֹּל (ד\"א בו מנוחה) שֶׁלָּעֶלְיוֹנִים וְתַחְתּוֹנִים. בּוֹ שַׁבָּת (ד\"א באה) לִמְנוּחָה. אֲשֶׁר בָּרָא אֱלֹהִים - מִכְּלָל שֶׁל זָכוֹר יוֹצֵא שָׁמוֹר לְהַתְקִין מַעֲשֵׂה הָעוֹלָם. לַעֲשׂוֹת - זֶה אֻמַּן הָעוֹלָם, לַעֲשׂוֹת מַעֲשֶׂה שֶׁל הַכֹּל. (ס\"א אשר ברא אמן צריך לעולם וכל המעשה של הכל)."],[7,"","עוֹד פֵּרַשׁ רַבִּי שִׁמְעוֹן אֶת הַדָּבָר וְאָמַר, כָּתוּב (דברים ז) שׁוֹמֵר הַבְּרִית וְהַחֶסֶד. שׁוֹמֵר - זוֹ כְּנֶסֶת יִשְׂרָאֵל. הַבְּרִית - זֶה יְסוֹד הָעוֹלָם. וְהַחֶסֶד - זֶה אַבְרָהָם, שֶׁכְּנֶסֶת יִשְׂרָאֵל הִיא שׁוֹמֵר הַבְּרִית וְהַחֶסֶד. וְנִקְרֵאת שׁוֹמֵר יִשְׂרָאֵל, זֶהוּ שׁוֹמֵר הַפֶּתַח שֶׁל הַכֹּל, בּוֹ תְּלוּיִים כָּל מַעֲשֵׂי הָעוֹלָם וַדַּאי. אֲשֶׁר בָּרָא אֱלֹהִים לַעֲשׂוֹת - לְשַׁכְלֵל לְהַתְקִין הַכֹּל כָּל יוֹם וָיוֹם וּלְהוֹצִיא רוּחוֹת וּנְשָׁמוֹת, וַאֲפִלּוּ רוּחוֹת וְשֵׁדִים."],[8,"","וְאִם תֹּאמַר שֶׁאֵינָם תִּקּוּן הָעוֹלָם - לֹא כָּךְ! שֶׁהֲרֵי הֵם הָיוּ לְתִקּוּן הָעוֹלָם וּלְהַלְקוֹת בָּהֶם רִשְׁעֵי הָעוֹלָם, שֶׁהֵם הוֹלְכִים כְּנֶגְדָּם לְהוֹכִיחַ אוֹתָם. וּמִי שֶׁהוֹלֵךְ לִשְׂמֹאל, נֶאֱחָז בְּצַד הַשְּׂמֹאל כְּנֶגְדָּם (לוקה בהם), לָכֵן הֵם לְתִקּוּן. בֹּא רְאֵה מַה כָּתוּב בִּשְׁלֹמֹה, (שמואל ב ז) וְהוֹכַחְתִּיו בְּשֵׁבֶט אֲנָשִׁים וּבְנִגְעֵי בְּנֵי אָדָם. מִי הֵם נִגְעֵי בְּנֵי אָדָם? אֵלֶּה אוֹתָם הַמַּזִּיקִים."]]],[["תָּא חֲזֵי, בִּשְׁעָתָא דְּאִתְבְּרִיאָן אִתְקַדַּשׁ יוֹמָא וְאִשְׁתָּאֲרוּ רוּחָא בְּלָא גוּפָא. וְאִלֵּין אִנּוּן בָּרְיָין דְּלָא אִשְׁתַּכְלָלוּ (ד\"א ל\"ג) (ולא אתייסדו) וּמִסְטַר שְׂמָאלָא אִנּוּן זוּהֲמָא דְּדַהֲבָא, וְעַל דָּא בְּגִין דְּלָא אִשְׁתַּכְלְלוּ וְאִנּוּן פְּגִימִין, שְׁמָא קַדִּישָׁא לָא שַׁרְיָא בְּהוּ וְלָא אִתְדַּבְּקוּ בֵּיהּ, וּדְחִילוּ דִּלְהוֹן מִשְׁמָא קַדִּישָׁא אִיהוּ וְזָעִין וְדַחֲלִין מִנֵּיהּ, וּשְׁמָא קַדִּישָׁא לָא שַׁרְיָא בְּאֲתַר פָּגִים.","וְתָא חֲזֵי הַאי בַּר נָשׁ דְּאִתְפְּגִים דְּלָא שָׁבַק בַּר בְּהַאי עָלְמָא, כַּד נָפַק מִנֵּיהּ לָא אִתְדַּבָּק בִּשְׁמָא קַדִּישָׁא (לעיל יג א) וְלָא עָאלִין לֵיהּ בְּפַרְגּוֹדָא, בְּגִין דְּאִיהוּ פָּגִים וְלָא אִשְׁתְּלִים, וְאִילָנָא דְּאִתְעַקֵּר בָּעְיָא נְטִיעָא זִמְנָא אָחֳרָא, בְּגִין דִּשְׁמָא קַדִּישָׁא אִשְׁתְּלִים בְּכָל סִטְרִין. וּפְגִימוֹ לָא אִתְדַּבָּק בֵּיהּ לְעָלְמִין.","וְתָּא חֲזֵי הָנֵי בָּרְיָין פְּגִימִין אִנּוּן מֵעֵילָא וּמִתַּתָּא, וּבְגִינִי כָךְ לָא מִתְדַּבְּקָן לְעֵילָא וְלָא מִתְדַּבְּקָן לְתַתָּא. וְאִלֵּין דִּכְתִיב בְּהוּ אֲשֶׁר בָּרָא אֱלֹהִים לַעֲשׂוֹת דְּלָא אִשְׁתַּלִּימוּ עֵילָא וְתַתָּא. וְאִי תֵימָא הָא רוּחִין אִנּוּן אַמַּאי לָאו (ד\"א אשתלימו) לְעֵילָא, אֶלָּא כֵּיוָן דְּלָא אִשְׁתְּלִימוּ לְתַתָּא בְּאַרְעָא לָא אִשְׁתְּלִימוּ לְעֵילָא. וְכֻלְהוּ מִסְּטַר שְׂמָאלָא קָא אַתְיָין וּמִתְכַּסְיָין מֵעֵינָא דִּבְנֵי נְשָׁא וְקָיְימֵי לְקִבְלַיְיהוּ לְאַבְאָשָׁא לוֹן. תְּלַת לוֹן כְּמַלְאֲכֵי הַשָּׁרֵת. וּתְלַת לוֹן כִּבְנֵי נְשָׁא. (לעיל כה א) וְהָא אוּקְמוּהָ.","בָּתַר דְּאִתְבְּרִיאוּ רוּחִין (ד\"א ל\"ג אטמרו) אִשְׁתָּאֲרוּ אִנּוּן רוּחִין בָּתַר רֵחַיָּיא דְנוּקְבָא דִתְהוֹמָא רַבָּא לֵילְיָא דְשַׁבַּתָּא וְיוֹמָא דְשַׁבַּתָּא, כֵּיוָן דְּנָפַק קְדוּשָׁתָא דְיוֹמָא וְלָא אִשְׁתַּלִּימוּ, נָפְקוּ לְעָלְמָא וְשָׁטָאן לְכָל סִטְרִין, וּבָעְיָא עָלְמָא לְאִתְנַטְּרָא מִנַּיְיהוּ. דְּהָא כְּדֵין כָּל סְטַר שְׂמָאלָא אִתְעָר, וְאֶשָּׁא דְּגֵיהִנֹּם מְלַהֲטָא, וְכָל אִנּוּן דְּבִסְטַר שְׂמָאלָא אָזְלִין וְשָׁטָאן בְּעָלְמָא. וּבָעָאן לְאִתְלַבְּשָׁא בְּגוּפָא וְלָא יָכְלִין. כְּדֵין בָּעֵינָא לְאִסְתַּמְּרָא מִנַּיְיהוּ, וְאַתְקִינוּ שִׁיר דִּפְגָעִים בְּכָל שַׁעֲתָא דִּדְחִילוּ דִלְהוֹן שַׁרְיָא בְּעָלְמָא.","תָּא חֲזֵי, כַּד אִתְקַדַּשׁ יוֹמָא בְּמַעֲלֵי שַׁבַּתָּא סוּכַּת שָׁלוֹם שַׁרְיָא וְאִתְפְּרִיסַת בְּעָלְמָא. מָאן סוּכַּת שָׁלוֹם, דָּא שַׁבַּתָּא, וְכָל רוּחִין וְעִלְעוּלִין וְשֵׁדִין וְכָל סִטְרָא דִּמְסָאֲבֵי כֻּלְהוּ טְמִירִין וְעָאלִין בְּעֵינָא דְּרֵיחַיָּיא דְנוּקְבָא דִתְהוֹמָא רַבָּא. דְּהָא כֵּיוָן דְּאִתְעַר קְדוּשָׁתָא עַל עָלְמָא, רוּחַ מְסָאֲבָא לָא אִתְעַר בַּהֲדֵיהּ. וְדָא עָרִיק מִקַּמֵּיהּ דְּדָא.","וּכְדֵין עָלְמָא בִּנְטִירוּ עִלָּאָה וְלָא בָּעֵינָן לְצַלָּאָה עַל נְטִירוּ כְּגוֹן שׁוֹמֵר אֶת עַמּוֹ יִשְׂרָאֵל לָעַד אָמֵן. דְּהָא דָּא בְּיוֹמָא דְחוֹל אִתְתַּקַּן דְּעָלְמָא בָּעְיָא נְטִירוּ. אֲבָל בְּשַׁבָּת סוּכַּת שָׁלוֹם אִתְפְּרִיסָא עַל עָלְמָא וְאִתְנְטִיר בְּכָל סִטְרִין. וְאֲפִילּוּ חַיָּיבֵי גֵּיהִנֹּם נְטִירִין אִנּוּן, וְכֹלָּא בִּשְׁלָמָא אִשְׁתַּכְּחָא עִלָּאִין וְתַתָּאִין, וּבְּגִין כָּךְ בְּקִדּוּשָׁא דְיוֹמָא מְבָרְכִינָן הַפּוֹרֵס סֻכַּת שָׁלוֹם עָלֵינוּ וְעַל כָּל עַמוֹ יִשְׂרָאֵל וְעַל יְרוּשָׁלָם.","אַמַּאי עַל יְרוּשָׁלָם, אֶלָּא דָא הִיא מְדוֹרָא דְהַהִיא סֻכָּה. וּבָעֵינָא לְזַמְּנָא לְהַהִיא סֻכָּה דְּאִתְפְּרָסַת עֲלָנָא וּלְמֵשְׁרָא עִמָּנָא וּלְמֶהֱוֵי (ד\"א מגינא) עֲלָנָא כְּאִמָּא דְּשַׁרְיָיא עַל בְּנִין, וּבְגִין דָא לָא דָּחֲלִין מִכָּל סִטְרִין, וְעַל דָּא הַפּוֹרֵס סוּכַּת שָׁלוֹם עָלֵינוּ.","תָּא חֲזֵי, בְּשַׁעֲתָא דְיִשְׂרָאֵל מְבָרְכִין וּמְזַמְּנִין לְהַאי סֻכַּת שָׁלוֹם אוּשְׁפִּיזָא קַדִישָׁא וְאָמְרֵי הַפּוֹרֵס סֻכַּת שָׁלוֹם, כְּדֵין קְדוּשָׁתָא עִלָאָה נָחֲתָא וּפְרִיסַת גַּדְפָהָא עֲלַיְיהוּ דְיִשְׂרָאֵל וּמְכַסְיָא לוֹן כְּאִמָּא עַל בְּנִין, וְכָל זִינִין בִּישִׁין אִתְכַּנִּישׁוּ מֵעָלְמָא, וְיַתְבֵי יִשְׂרָאֵל תְּחוֹת קְדוּשָׁתָא דְמָארֵיהוֹן, וּכְדֵין דָּא סֻכַּת שָׁלוֹם יָהִיב נִשְׁמָתִין חַדְתִּין לִבְנָהָא, מַאי טַעֲמָא בְּגִין דְבֵּיהּ נִשְׁמָתִין שַׁרְיָין (ס\"א דכדין זמן זווגא ונטלת נשמתין ובה שריין) וּמִנֵּיהּ נָפְקִין. וְכֵיוָן דְּשַׁרְיָא וּפְרִיסַת גַּדְפָהָא עַל בְּנָהָא. אֲרִיקַת נִשְׁמָתִין חַדְתִּין לְכָל חַד וְחַד.","תּוּ אָמַר רַבִּי שִׁמְעוֹן עַל דָּא תָּנֵינָן שַׁבָּת דּוּגְמָא דְּעָלְמָא דְאָתֵי אִיהוּ, הָכִי הוּא וַדַּאי, וְעַל דָּא שְׁמִיטָה וְיוֹבֵל דּוּגְמָא דָּא בְּדָא. וְשַׁבָּת וְעָלְמָא דְּאָתֵי הָכִי הוּא. וְהַהוּא תּוֹסֶפֶת דְּנִשְׁמְתָא מֵרָזָא דְּזָכוּר קָא אַתְיָא עַל הַאי סֻכַּת שָׁלוֹם דְּנָטִיל מֵעָלְמָא דְאָתֵי וְדָא תּוֹסֶפֶת יַהֲבַת לְעַלְמָּא קַדִּישָׁא. וּבְהַהוּא תּוֹסֶפֶת חָדָאן וְיִתְנְשֵׁי מִנַּיְיהוּ כָּל מִלִּין דְּחוֹל וְכָל צַעֲרִין וְכָל עָאקִין כְּמָא דְאַתְּ אָמֵר (ישעיהו י״ד:ג׳) בְּיוֹם הָנִיחַ יְיָ לְךָ מֵעָצְבְּךָ וּמֵרָגְזֶךָ וּמִן הָעֲבֹדָה הַקָּשָׁה וְגו'."],[[0,"תא חזי בשעתא דאתבריאו אתקדש יומא, ואשתארו רוחא בלא גופא,","בוא וראה, בשעה שנבראו הרוחות והשדים, קידש היום, ולא הספיק לעשות להם גופים, ונשארו רוחות בלי גוף, \u0003ואלין אינון בריין דלא אשתכללו ומסטר שמאלא אינון, זוהמא דדהבא,\u0004 ואלו הם בריות שלא נגמרו, ומצד שמאל הם, והם פסולת הזהב. פירוש כי בסוד שבירת הכלים של ז\"ת חג\"ת נהי\"מ, נתערבה הקליפה בהקדושה, ובעולם התקון חזרה ונתבררה הקדושה מן הקליפה, ומהם באו כל הפרצופים דאבי\"ע דקדושה, אמנם נשאר פסולת שאינו ראוי עוד לברר משם שום קדושה מטרם גמר התקון, ומהפסולת ההיא נעשו הס\"א והקליפות ויש בזה ימין ושמאל, והפסולת מבחינת ימין נקראת \u0003התוכא דכספא,\u0004 דהיינו פסולת הנשאר אחר התוך הכסף, והפסולת מצד שמאל נקראת \u0003התוכא דדהבא\u0004 או \u0003זוהמא דדהבא,\u0004 דהיינו פסולת הנשאר אחר התוך הזהב. כי צד ימין מכונה כסף. וצד שמאל זהב, כנודע. וז\"ש שלהיותם מצד שמאל הם פסולת הזהב וענין שלא הספיק הקב\"ה לעשות להם גופים עד דאתקדש יומא, כבר נתבאר לעיל (בהקדמת הזהר דף רל\"ג ד\"ה וכי לא ידע) ע\"ש."],[0,"ועל דא בגין דלא אשתכללו ואינון פגימין שמא קדישא לא שריא בהו ולא אתדבקו ביה:","ועל כן כיון שלא נשלמו והם פגומים, השם הקדוש אינו שורה בהם, והם אינם מתדבקים בהשם הקדוש. \u0003ודחילו דלהון משמא קדישא איהו וזעין ודחלין מניה, ושמא קדישא לא שריא באתר פגים,\u0004 והיראה שלהם הוא מהשם הקדוש, וזעים ומפחדים מפניו, וע\"כ לא יוכלו להתדבק בו. וכן השם הקדוש אינו שורה במקום פגום, וע\"כ אינו שורה בהם."],[1,"ות\"ח האי בר נש דאתפגים, דלא שבק בר בהאי עלמא:","ובוא וראה, אדם הזה שנפגם, כי לא הניח אחריו בן בעוה\"ז, \u0003כד נפק מניה לא אתדבק בשמא קדישא, ולא עאלין ליה בפרגודא, בגין דאיהו פגים ולא אשתלים,\u0004 כשיוצא ממנו, דהיינו כשנפטר מעוה\"ז, לא יוכל להתדבק בהשם הקדוש, ואין מכניסין אותו בפרגודו של הקב\"ה משום שהוא פגום, ואינו נשלם, \u0003ואילנא דאתעקר בעיא נטיעא זמנא אחרא, בגין דשמא קדישא אשתלים בכל סטרין,\u0004 והאילן שנעקר, דהיינו האדם שמת בלא בן, צריכים ליטע אותו פעם שנית, דהיינו שצריך לחזור ולהתגלגל בעולם, משום שהשם הקדוש הוא מושלם מכל הצדדים, וע\"כ לא יוכל הפגום להתדבק בו. כי ענין הדבקות הרוחני הוא השואת הצורה, והפגום כלפי השלם הוא רחוק כרחוק מזרח ממערב."],[2,"ות\"ח הני בריין פגימין אינון מעילא ומתתא, ובג\"כ, לא מתדבקן לעילא, ולא מתדבקן לתתא:","בוא וראה, אשר בריות האלו, דהיינו הרוחות והשדים, פגומים הם מלמעלה ומלמטה, וע\"כ אינם מתדבקים למעלה ואינם מתדבקים למטה. מלמעלה פירושו מצד הבינה, ומלמטה, פירושו מצד המלכות. \u0003ואלין דכתיב בהו, אשר ברא אלקים לעשות, דלא אשתלימו עילא ותתא,\u0004 ואלו הם שכתוב בהם אשר ברא אלקים לעשות, שפירושו שברא בריות שצריכים לעשותם ולהשלימם, כנ\"ל, כי הם לא נשלמו למעלה ולמטה, לא מצד הבינה ולא מצד המלכות. \u0003ואי תימא, הא רוחין אינון, אמאי לאו לעילא,\u0004 ואם תאמר הרי, רוחות הם בלי גופין א\"כ למה לא נשלמו מצד הבינה. פירוש. כי כל אחיזת הס\"א הוא רק בגופין שהם בחינת כלים, ולא ברוחות שהם בחינת אורות, וע\"כ מקשה, למה אינם נשלמים מצד הבינה, כיון שאין להם מבחינת מלכות כלום. \u0003אלא כיון דלא אשתלימו לתתא בארעא לא אשתלימו לעילא,\u0004 אלא כיון שלא נשלמו הרוחות למטה בארץ, דהיינו שיהיה להם גוף, אינם שלמים גם למעלה בבחינת האורות. כלומר, כי באמת הם נמשכים מהמלכות, והם צריכים משום זה לגופים להתלבש בהם, וכיון שאין להם גופים הרי זה פגם גם בהרוחות ולא יוכלו לקבל תקונם מלמעלה בהבינה."],[2,"וכלהו מסטר שמאלא קא אתיין ומתכסיין מעינא בני נשא וקיימי לקבלייהו לאבאשא לון:","וכולם באים מצד שמאל ונעלמים מעין האדם, ועומדים לנגדם להזיק אותם, \u0003תלת לון כמלאכי השרת, תלת לון כבני נשא, והא אוקמוה.\u0004 ג' דברים להם כמלאכי השרת וג' כבני אדם, וכבר פרשוהו. כמ\"ש (חגיגה ט\"ז ע\"א) כי יש להם כנפים, וטסים מסוף העולם עד סופו, ויודעים העתיד להיות כמו מלאכי השרת, וג' כבני אדם, שאוכלים ושותים, ופרים ורבים, ומתים, (ועי' לעיל בהקדמת הזהר דף קנ\"ט ד\"ה ובזה תבין ע\"ש)."],[3,"בתר דאתבריאו רוחין אשתארו אינון רוחין בתר רחייא דנוקבא דתהומא רבא ליליא דשבתא ויומא דשבתא:","אחר שנבראו הרוחות נשארו הרוחות ההם אחר הרחים של הנוקבא דתהום הגדול. פירוש. הקליפה כנגד הבינה נקראת תהומא רבא. והקליפה שכנגד המלכות נקראת תהומא זוטא. ובכל אחת מהן זכר ונקבה, שהזכר נקרא רכב, והנקבה נק' רחים. ואחר שנבראו הרוחות והשדים, תכף קידש היום, שהרי לא הספיק לעשות להם גופים. ובשבת כל דינין מתעברין מינה, שאז עולה המלכות לבינה ונעשית כמוה, לכן נמשך כח שליטה מהבינה שהכניס אלו הרוחות הפגומים למקום הנוקבא דבינה דקליפה, דהיינו \u0003בתר רחייא דנוקבא דתהומא רבא,\u0004 אשר קליפה זו נכנעת לגמרי תחת המלכות דקדושה, וע\"כ נעלם כל הפגם שבהרוחות, כל זמן היותם תחתיהם. \u0003כיון דנפק קדושתא דיומא ולא אשתלימו, נפקו לעלמא, ושטאן לכל סטרין, ובעיא עלמא לאתנטרא מנייהו,\u0004 כיון שיצא קדושת היום, דהיינו במוצאי שבת, והרוחות לא נשלמו, הם יוצאים לעולם ומשוטטים לכל רוח, ובני העולם צריכים להשמר מהם. \u0003דהא כדין כל סטר שמאלא אתער, ואשא דגיהנם מלהטא,\u0004 שהרי אז נתעורר כל צד השמאל והגיהנם אש לוהט, \u0003וכל אינון דבסטר שמאלא אזלין ושטאן בעלמא ובעאן לאתלבשא בגופא ולא יכלין, כדין בעינא לאסתמרא מנייהו,\u0004 וכל אלו שמצד שמאל הולכים ומשוטטים בעולם, ורוצים להתלבש בגוף ואינם יכולים, אז צריכים להשמר מהם. (והביאור עי' בהקדמת הזהר דף רל\"ג ד\"ה ומקשה) \u0003ואתקינו שיר דפגעים, בכל שעתא דדחילו דלהון שריא בעלמא.\u0004 ותקנו חז\"ל, לומר שיר של פגעים, דהיינו יושב בסתר, בכל שעה שיראה שלהם שורה בעולם."],[4,"ת\"ח, כד אתקדש יומא במעלי שבתא, סוכת שלום שריא ואתפריסת בעלמא:","בוא וראה, בשעה שקידש היום בליל שבת, שורה סוכת השלום בעולם, והיא נפרשת בהעולם, \u0003מאן סוכת שלום דא שבתא,\u0004 שואל מי הוא סוכת השלום, ואומר שהיא שבת. והוא מטעם, \u0003וכל רוחין ועלעולין ושדין וכל סטרא דמסאבי כלהו טמירין ועאלין בעינא דריחייא דנוקבא דתהומא רבא.\u0004 וכל הרוחות, ורוח סערות, ושדים וכל צד הטומאה, כולם מסתתרים ונכנסים בעין הרחים דנוקבא דתהומא רבה. (ופירושו עי' לעיל דף קכ\"ג ד\"ה בתר) \u0003דהא כיון דאתער קדושתא על עלמא, רוח מסאבא לא אתער בהדיה ודא עריק מקמיה דדא,\u0004 שהרי מאחר שהקדושה נתעוררה לשרות בעולם, רוח הטומאה לא יתעורר עמה, כי זה בורח מפני זה. שהקדושה בורחת מפני הטומאה, והטומאה בורחת מפני הקדושה."],[5,"וכדין עלמא בנטירו עלאה, ולא בעינן לצלאה על נטירו כגון שומר את עמו","וכו' ואז, בשבת, נמצא העולם בשמירה עליונה, ואין צריכים להתפלל על שמירה, כגון לומר שומר את עמו ישראל לעד אמן, \u0003דהא דא ביומא דחול אתתקן, דעלמא בעיא נטירו,\u0004 כי זה הברכה, שומר את עמו וכו', נתקנה רק בימות החול, שהעולם צריך שמירה, \u0003אבל בשבת סוכת שלום אתפריסא על עלמא ואתנטיר בכל סטרין\u0004 אבל בשבת הופרש סוכת השלום בעולם, ונשמרת מכל הצדדים. \u0003ואפילו חייבי גיהנם נטירין אינון וכלא בשלמא אשתכחא עלאין ותתאין\u0004 ואפילו הרשעים שבגיהנם הם משומרים והכל נמצא בשלום, העליונים והתחתונים. \u0003ובג\"כ, בקדושא דיומא מברכינן הפורס סוכת שלום וגו'\u0004"],[6,"אמאי על ירושלם,","וע\"כ בקדושת היום מברכים, במקום שומר עמו ישראל, הפורס סוכת שלום וגו' ועל ירושלם. ושואל למה אומרים ועל ירושלם. \u0003אלא דא היא מדורא דהאי סוכה,\u0004 אלא ירושלם הוא המדור של סוכה זו, ששם עומדת, סוכת השלום."],[6,"","פירוש. סוכת שלום ה\"ס הבינה. ונקראת כן משום שהוא סוככת על בניה הזו\"ן ומגינה עליהם מפני החיצונים, וסוד השבת הוא, כי המלכות נעשה אחת עם הסוכת שלום, ונבחן אשר מדור סוכת שלום הוא בתוך ירושלם, שהיא המלכות, וע\"כ אומרים ועל ירושלם."],[6,"ובעינא לזמנא לההיא סכה דאתפרסת עלנא ולמשרא עמנא ולמהוי עלנא כאמא דשריא על בנין:","וצריכים להתפלל ולהזמין לסוכת שלום זו, שתתפרש עלינו, ותשרה עמנו, ושתהיה עלינו כמו אם החופפת על הבנים. \u0003ובג\"ד לא דחלין מכל סטרין, ועל דא הפורס סוכת שלום עלינו,\u0004 ומשום זה אין מפחדים בשבת משום צד שבעולם, ועל כן אומרים אז הפורס סוכת שלום וגו', ואין צריכים לומר השומר את עמו ישראל לעד אמן."],[7,"ת\"ח בשעתא דישראל מברכין ומזמנין להאי סכת שלום אושפיזא קדישא:","בוא וראה, בשעה שישראל מברכים ומזמינים לסוכת שלום זו, האורח הקדוש, כי בא רק בשבת, כמו ארח שאינו תמידי, \u0003ואמרי הפורס סכת שלום,\u0004 ואומרים הפורס סוכת שלום, \u0003כדין קדושתא עלאה נחתא ופריסת גדפהא עלייהו דישראל ומכסיא לון כאמא על בנין,\u0004 אז קדושה העליונה יורדת ופורשת כנפיה על ישראל ומכסה אותם כמו אם על הבנים, \u0003וכל זינין בישין אתכנישו מעלמא ויתבי ישראל תחות קדושתא דמאריהון,\u0004 וכל מיני הרע מסתלקים מהעולם, וישראל יושבים תחת הקדושה של רבונם. \u0003וכדין דא סוכת שלום יהיב נשמתין חדתין לבנהא,\u0004 ואז סוכת שלום זו נותנת נשמה חדשה לבניה, \u0003מאי טעמא, בגין דביה נשמתין שריין ומניה נפקין, וכיון דשריא ופריסת גדפהא על בנהא, אריקת נשמתין חדתין לכל חד וחד,\u0004 שואל, מהו הטעם שסוכת שלום נותנת נשמות חדשות לישראל. ואומר, משום שבה שורות נשמות, כי היא בינה, כנ\"ל, והנשמות הם בבינה וממנה הן יוצאות, וכיון שהסוכת שלום שורה ופורשת כנפיה על בניה, היא משפעת נשמות חדשות לכל אחד ואחד."],[8,"תו אמר ר\"ש, על דא תנינן שבת דוגמא לעלמא דאתי איהו, הכי הוא ודאי,","עוד אמר ר\"ש, ע\"כ למדנו, אשר שבת הוא כעין עולם הבא, כן הוא ודאי, \u0003ועל דא, שמיטה ויובל דוגמא דא בדא, ושבת ועלמא דאתי הכי הוא,\u0004 וע\"כ שמיטה ויובל שוים הם זה לזה, ושבת ועולם הבא כן הוא, כלומר. כי שבת הוא מלכות, כמו שמיטה, ועוה\"ב הוא בינה, כמו יובל. וכיון שלמדנו ששבת ועוה\"ב שוים זה לזה, נמצא שאז השמטה ויובל שוים זה לזה. וטעם הדבר, כי סוד השבת הוא, אשר המלכות עולה אל הבינה ונעשית עמה כאחת. וההפרש בין שבת ועוה\"ב לבין שמיטה ויובל, הוא, כי הבינה נקראת יובל בסוד שליטת השמאל, וכשהמלכות נכללת בה מבחינה זו אז נקראת המלכות שמטה, אמנם בעת שהמלכות נכללת מכל ג' קוין של הבינה, נקראת המלכות שבת או סוכת שלום, והבינה עוה\"ב, \u0003וההוא תוספת דנשמתא מרזא דזכור קא אתייא על האי סוכת שלום דנטיל מעלמא דאתי,\u0004 ותוספת נשמה ההיא שסוכת שלום משפיע לבניה, בא מסוד זכור שהוא ז\"א, אל סוכת שלום הנמשך מעוה\"ב, \u0003ודא תוספת יהבת לעמא קדישא, ובההוא תוספת חדאן ויתנשי מנייהו כל מלין דחול וכל צערין וכל עאקין כד\"א וכו'.\u0004 וזה התוספת נשמה, שסוכת שלום מקבלת מז\"א, היא נותנת לעם הקדוש. והם שמחים בתוספת נשמה זו, ונשכח מהם כל דברי חול, וכל דברי צער, וכל רע, וכן הוא אומר,ביום הניח ה' לך וגו'. שהכונה הוא בעת השגת תוספת נשמה מסוכת שלום זו."]],[[0,"","בֹּא רְאֵה, בְּשָׁעָה שֶׁנִּבְרְאוּ, הִתְקַדֵּשׁ הַיּוֹם וְנִשְׁאֲרוּ רוּחַ בְּלִי גוּף, וְאֵלּוּ הֵם בְּרִיּוֹת שֶׁלֹּא נִתְקְנוּ (ולא התיסדו), וּמִצַּד שְׂמֹאל הֵם זֻהֲמַת הַזָּהָב. וְעַל זֶה, מִשּׁוּם שֶׁלֹּא נִתְקְנוּ וְהֵם פְּגוּמִים, הַשֵּׁם הַקָּדוֹשׁ לֹא שׁוֹרֶה בָהֶם וְלֹא נִדְבְּקוּ בּוֹ, וְהַפַּחַד שֶׁלָּהֶם הוּא מֵהַשֵּׁם הַקָּדוֹשׁ וְזָעִים וּפוֹחֲדִים מִמֶּנּוּ, וְהַשֵּׁם הַקָּדוֹשׁ לֹא שׁוֹרֶה בְּמָקוֹם פָּגוּם."],[1,"","וּבֹא וּרְאֵה, הָאָדָם הַזֶּה שֶׁנִּפְגַּם, שֶׁלֹּא הִשְׁאִיר בֵּן בָּעוֹלָם הַזֶּה, כְּשֶׁיּוֹצֵא מִמֶּנּוּ, לֹא נִדְבָּק בַּשֵּׁם הַקָּדוֹשׁ וְלֹא מַכְנִיסִים אוֹתוֹ לַפַּרְגּוֹד, מִשּׁוּם שֶׁהוּא פָגוּם וְלֹא נִשְׁלָם. וְעֵץ שֶׁנֶּעֱקַר צָרִיךְ נְטִיעָה פַּעַם אַחֶרֶת כְּדֵי שֶׁהַשֵּׁם הַקָּדוֹשׁ יֻשְׁלַם בְּכָל הַצְּדָדִים, וְחִסָּרוֹן לֹא יִדְבַּק בּוֹ לְעוֹלָמִים."],[2,"","וּבֹא וּרְאֵה, הַבְּרִיּוֹת הַלָּלוּ פְּגוּמִים הֵם מִלְמַעְלָה וּמִלְּמַטָּה, וְלָכֵן לֹא נִדְבָּקִים לְמַעְלָה וְלֹא נִדְבָּקִים לְמַטָּה. וְאֵלֶּה שֶׁכָּתוּב בָּהֶם אֲשֶׁר בָּרָא אֱלֹהִים לַעֲשׂוֹת, שֶׁלֹּא נִשְׁלְמוּ לְמַעְלָה וּלְמַטָּה. וְאִם תֹּאמַר, הֲרֵי רוּחוֹת הֵם, לָמָּה לֹא נִשְׁלְמוּ לְמַעְלָה? אֶלָּא כֵּיוָן שֶׁלֹּא נִשְׁלְמוּ לְמַטָּה בָּאָרֶץ, לֹא נִשְׁלְמוּ לְמַעְלָה. וְכֻלָּם בָּאִים מִצַּד שְׂמֹאל וּמְכֻסִּים מֵעֵינֵי בְּנֵי אָדָם, וְעוֹמְדִים כְּנֶגְדָּם לְהָרַע לָהֶם. בְּשָׁלֹשׁ הֵם כְּמוֹ מַלְאֲכֵי הַשָּׁרֵת, וּבְשָׁלֹשׁ הֵם כְּמוֹ בְּנֵי אָדָם, וַהֲרֵי בֵּאֲרוּהָ."],[3,"","אַחַר שֶׁנִּבְרְאוּ רוּחוֹת (ד\"א נטמנו), נִשְׁאֲרוּ אוֹתָם רוּחוֹת אַחַר הָרֵחַיִם שֶׁל נֶקֶב תְּהוֹם רַבָּה לֵיל הַשַּׁבָּת וְיוֹם הַשַּׁבָּת. כֵּיוָן שֶׁיָּצְאָה קְדֻשַּׁת הַיּוֹם וְלֹא הֻשְׁלְמוּ, יָצְאוּ לָעוֹלָם וּמְשׁוֹטְטִים לְכָל הָרוּחוֹת, וְצָרִיךְ הָעוֹלָם לְהִשָּׁמֵר מֵהֶם, שֶׁהֲרֵי אָז מִתְעוֹרֵר כָּל צַד שְׂמֹאל, וְאֵשׁ הַגֵּיהִנֹּם לוֹהֶטֶת, וְכָל אוֹתָם שֶׁבְּצַד שְׂמאֹל הוֹלְכִים וּמְשׁוֹטְטִים בָּעוֹלָם. וְרוֹצִים לְהִתְלַבֵּשׁ בְּגוּף וְלֹא יְכוֹלִים, וְאָז צְרִיכִים לְהִשָּׁמֵר מֵהֶם, וְהִתְקִינוּ שִׁיר שֶׁל פְּגָעִים בְּכָל שָׁעָה שֶׁפַּחַד שֶׁלָּהֶם שָׁרוּי בָּעוֹלָם."],[4,"","בֹּא רְאֵה, כְּשֶׁמִּתְקַדֵּשׁ הַיּוֹם בְּעֶרֶב שַׁבָּת, סֻכַּת שָׁלוֹם שׁוֹרָה וְנִפְרֶסֶת בָּעוֹלָם. מִי זוֹ סֻכַּת שָׁלוֹם? זוֹ שַׁבָּת. וְכָל רוּחוֹת וּסְעָרוֹת וְשֵׁדִים וְכָל רוּחוֹת הַטֻּמְאָה, כֻּלָּם נִטְמָנִים וְנִכְנָסִים בְּעֵין הָרֵחַיִם שֶׁל נֶקֶב תְּהוֹם רַבָּה. שֶׁהֲרֵי כֵּיוָן שֶׁמִּתְעוֹרֶרֶת קְדֻשָּׁה עַל הָעוֹלָם, רוּחַ הַטֻּמְאָה לֹא מִתְעוֹרֶרֶת אִתּוֹ, וְזֶה בּוֹרֵחַ מִלִּפְנֵי זֶה."],[5,"","וְאָז הָעוֹלָם בִּשְׁמִירָה עֶלְיוֹנָה, וְלֹא צָרִיךְ לְהִתְפַּלֵּל עַל שְׁמִירָה כְּמוֹ שׁוֹמֵר אֶת עַמּוֹ יִשְׂרָאֵל לָעַד אָמֵן, שֶׁהֲרֵי זֶה הֻתְקַן לְיוֹם חֹל כְּשֶׁהָעוֹלָם צָרִיךְ שְׁמִירָה. אֲבָל בְּשַׁבָּת נִפְרֶסֶת סֻכַּת שָׁלוֹם עַל הָעוֹלָם, וְנִשְׁמָר בְּכָל הָרוּחוֹת, וַאֲפִלּוּ רִשְׁעֵי הַגֵּיהִנֹּם שְׁמוּרִים הֵם, וְהַכֹּל נִמְצָאִים בְּשָׁלוֹם - הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים. וְלָכֵן בְּקִדּוּשׁ הַיּוֹם מְבָרְכִים הַפּוֹרֵס סֻכַּת שָׁלוֹם עָלֵינוּ וְעַל כָּל עַמּוֹ יִשְׂרָאֵל וְעַל יְרוּשָׁלַיִם."],[6,"","לָמָּה עַל יְרוּשָׁלַיִם? אֶלָּא זֶהוּ מָדוֹר שֶׁל אוֹתָהּ סֻכָּה, וְצָרִיךְ לְזַמֵּן אֶת אוֹתָהּ סֻכָּה שֶׁנִּפְרְסָה עָלֵינוּ וְלִשְׁרוֹת עִמָּנוּ, לִהְיוֹת (מגנה) עָלֵינוּ כְּמוֹ אֵם שֶׁשּׁוֹרָה עַל הַבָּנִים, וְלָכֵן לֹא פוֹחֲדִים מִכָּל הָרוּחוֹת, וְלָכֵן הַפּוֹרֵס סֻכַּת שָׁלוֹם עָלֵינוּ."],[7,"","בֹּא רְאֵה, בְּשָׁעָה שֶׁיִּשְׂרָאֵל מְבָרְכִים וּמַזְמִינִים אֶת סֻכַּת הַשָּׁלוֹם הַ את אוֹרַחַת קְדוֹשָׁה, וְאוֹמְרִים הַפּוֹרֵס סֻכַּת שָׁלוֹם, אָז קְדֻשָּׁה עֶלְיוֹנָה יוֹרֶדֶת וּפוֹרֶסֶת כְּנָפֶיהָ עַל יִשְׂרָאֵל, וּמְכַסָּה אוֹתָם כְּמוֹ אֵם עַל הַבָּנִים. וְכָל הַמִּינִים הָרָעִים מִתְכַּנְּסִים מֵהָעוֹלָם, וְיִשְׂרָאֵל יוֹשְׁבִים תַּחַת קְדֻשַּׁת רִבּוֹנָם. וְאָז סֻכַּת הַשָּׁלוֹם הַזּוֹ נוֹתֶנֶת נְשָׁמוֹת חֲדָשׁוֹת לְבָנֶיהָ. מָה הַטַּעַם? מִשּׁוּם שֶׁבָּהּ שְׁרוּיוֹת הַנְּשָׁמוֹת (ס\"א שאז זמן הזווג, ונוטלת נשמות והן שורות בה) וּמִמֶּנָּה יוֹצְאוֹת. וְכֵיוָן שֶׁשּׁוֹרָה וּפוֹרֶסֶת כְּנָפֶיהָ עַל בָּנֶיהָ, מוֹרִיקָה נְשָׁמוֹת חֲדָשׁוֹת לְכָל אֶחָד וְאֶחָד."],[8,"","עוֹד אָמַר רַבִּי שִׁמְעוֹן, עַל זֶה שָׁנִינוּ, שַׁבָּת דֻּגְמָא שֶׁל עוֹלָם הַבָּא הִיא. כָּךְ זֶה וַדַּאי. וְעַל זֶה שְׁמִטָּה וְיוֹבֵל דֻּגְמָא זֶה בָּזֶה. וְשַׁבָּת וְעוֹלָם הַבָּא כָּךְ הוּא. וְאוֹתָהּ תּוֹסֶפֶת נְשָׁמָה, מִסּוֹד שֶׁל זָכוֹר הִיא בָאָה עַל סֻכַּת הַשָּׁלוֹם הַזֹּאת שֶׁלּוֹקַחַת מֵהָעוֹלָם הַבָּא. וְהַתּוֹסֶפֶת הַ את נוֹתֶנֶת לָעָם הַקָּדוֹשׁ. וּבְאוֹתָהּ תּוֹסֶפֶת הֵם שְׂמֵחִים, וְנִשְׁכָּחִים מֵהֶם כָּל דִּבְרֵי הַחֹל, וְכָל צַעַר וְכָל הַצָּרוֹת, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה יד) בְּיוֹם הָנִיחַ ה' לְךְ מֵעָצְבְּךְ וּמֵרָגְזֶךְ וּמִן הָעֲבֹדָה הַקָּשָׁה וְגוֹ'."]]],[["וּבְלֵילְיָא דְשַׁבַּתָּא בָּעֵי בַּר נָשׁ לְאַטְעָמָא מִכֹּלָּא, בְּגִין לְאַחֲזָאָה דְּהַאי סֻכַּת שָׁלוֹם מִכֹּלָּא אִתְכְּלִילַת, וּבִלְבָד דְּלָא יַפְגִּים מֵיכְלָא חָדָא לְיוֹמָא, וְאִית דְּאָמְרֵי תְּרֵין, לִתְרֵין סְעוּדָתֵי אָחֳרָנִין דְּיוֹמָא, וְשַׁפִּיר. וְכָל שֶׁכֵּן אִי סָלִיק יַתִּיר לְיוֹמָא וְיָכִיל לְמִטְעַם מִמֵּיכְלִין אָחֳרָנִין וְלִזְעִירֵי בִּתְרֵי תַּבְשִׁילִין סַגְיָא, וְאוּקְמוּהָ חַבְרַיָא.","נֵר שֶׁל שַׁבָּת לִנְשֵׁי עַמָּא קַדִּישָׁא אִתְיְיהִיבַת לְאַדְלָקָא, וְחַבְרַיָיא הָא אָמְרוּ דְּאִיהִי כִּבְּתָה בּוֹצִינָא דְעָלְמָא וְאַחֲשִׁיכַת לֵיהּ כו' וְשַׁפִּיר. אֲבָל רָזָא דְמִלָּה. הַאי סֻכַּת שָׁלוֹם מַטְרוֹנִיתָא דְּעָלְמָא הִיא וְנִשְׁמָתִין דְּאִנּוּן בּוֹצִינָא עִלָּאָה בָּהּ שַׁרְיָין. וְעַל דָּא מַטְרוֹנִיתָא בַּעֲיָא לְאַדְלָקָא, דְּהָא בְּדוּכְתָּהָא אִתְאַחְדַת וַעֲבָדַת עוֹבָדָא.","וְאִתְּתָא בַּעֲיָא בְּחֶדְוָה דְלִבָּא וּרְעוּתָא לְאַדְלָקָא בּוֹצִינָא דְשַׁבָּת, דְּהָא יְקָרָא עִלָּאָה הִיא לָהּ וּזְכוּ רַב לְגַרְמָהּ לְמִזְכֵּי לִבְנִין קַדִּישִׁין דִּיהוֹן בּוֹצִינָא דְעָלְמָא בְּאוֹרַיְיתָא וּבְדַחַלְתָּא, וְיִסְגוֹן שְׁלָמָא בְּאַרְעָא, וִיהֵיבַת לְבַעֲלָהּ אוֹרְכָּא דְחַיִּין, בְּגִין כָּךְ בַּעֲיָא לְאִזְדַּהֲרָא בָּהּ.","תָּא חֲזֵי, שַׁבָּת לֵילְיָא וְיוֹמָא זָכוֹר וְשָׁמוֹר אִיהוּ כְּחֲדָא, וְעַל דָּא כְּתִיב זָכוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְשׁוֹ וּכְתִיב שָׁמוֹר אֶת יוֹם הַשַּׁבָּת, זָכוֹר לִדְכוּרָא שָׁמוֹר לְנוּקְבָא וְכֹלָּא חַד. זַכָּאִין אִנּוּן יִשְׂרָאֵל חוּלָקֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא עַדְבֵיהּ וְאַחֲסַנְתֵּיהּ עֲלַיְיהוּ כְּתִיב, (תהילים קמ״ד:ט״ו) אַשְׁרֵי הָעָם שֶׁכָּכָה לוֹ אַשְׁרֵי הָעָם שֶׁיְיָ אֱלקָיו.","וַיִּבֶן יְיָ אֱלהִים אֶת הַצֵּלָע אֲשֶׁר לָקַח מִן הָאָדָם וְגו'. אָמַר רַבִּי שִׁמְעוֹן כְּתִיב, (איוב כ״ח:כ״ג-כ״ד) אֱלֹהִים הֵבִין דַּרְכָּהּ וְהוּא יָדַע אֶת מְקוֹמָהּ. הַאי קְרָא גְוָונִין סַגִּיאִין אִית בֵּיהּ. אֶלָּא מַהוּ אֱלֹהִים הֵבִין דַּרְכָּהּ. כְּמָא דְאַתְּ אָמֵר וַיִּבֶן יְיָ אֱלהִים אֶת הַצֵּלָע דָּא תּוֹרָה שֶׁבַּעַל פֶּה דְּאִית בָּהּ דֶּרֶךְ, כְּמָא דְאַתְּ אָמֵר, (ישעיהו מ״ג:ט״ז) הַנּוֹתֵן בַּיָּם דֶּרֶךְ, בְּגִינֵי כָּךְ אֱלֹהִים הֵבִין דַּרְכָּהּ.","וְהוּא יָדַע אֶת מְקוֹמָהּ. מָאן מְקוֹמָהּ, דָּא תּוֹרָה שֶׁבִּכְתָב דְּאִית בָּהּ דַּעַת. (דעת ותבונה כחד אזלו) יְיָ אֱלֹהִים שֵׁם מָלֵא לְאַתְקָנָא לָהּ בְּכֹלָּא. וְעַל דָּא אִתְקְרִיאַת חָכְמָה וְאִתְקְרִיאַת בִּינָה. בְּגִין דְּהֲוָה בְּשֵׁם מָלֵא יְיָ אֱלהִים בְּכֹלָּא בִּשְׁלִימוּ בִּתְרֵי שְׁמָהָן.","אֶת הַצֵּלָע דָּא אַסְפַּקְלַרְיָאה דְּלָא נָהֲרָא כְּמָא דְאַתְּ אָמֵר, (תהילים ל״ה:ט״ו) וּבְצַלְעִי שָׂמְחוּ וְנֶאֱסָפוּ. אֲשֶׁר לָקַח מִן הָאָדָם, בְּגִין דְּהָא מִתּוֹרָה שֶׁבִּכְתָב נָפְקַת. לְאִשָּׁה, לְאִתְקַשְּׁרָא בְּשַׁלְהוֹבָא דִּסְטַר שְׂמָאלָא, דְּהָא אוֹרַיְיתָא מִסִּטְרָא דִגְבוּרָה אִתְיְהִיבַת. לְאִשָּׁה, לְמֶהֱוֵי (נח ע' א) אֵשׁ ה' קָטִיר כְּחֲדָא.","וַיְבִאֶהָ אֶל הָאָדָם. בְּגִין דְּלָא בַּעֲיָא לְאִשְׁתַּכָּחָא בִּלְחוּדָהָא אֶלָּא לְאִתְכְּלָלָא וּלְאִתְחַבְּרָא בַּתּוֹרָה שֶׁבִּכְתָב. כֵּיוָן דְּאִתְחַבְּרַת בַּהֲדֵיהּ הוּא יָזוּן לָהּ וִיתַקֵּן לָהּ וְיִתֵּן לָהּ מַה דְּאִצְטְרִיךְ הַיְינוּ דִכְתִיב וְאֶת הָאָרֶץ וְהָא אוֹקִימְנָא. מִכָּאן אוֹלִיפְנָא מָאן דְּאַנְסִיב בְּרַתֵּיהּ עַד לָא תֵיעוּל לְבַעֲלָהּ, אֲבוּהָ וְאִמָּהּ מְתַקְּנִין לָהּ וְיָהֲבִין לָהּ כָּל מַה דְּאִצְטְרִיךְ, כֵּיוָן דְּאִתְחַבְּרַת בְּבַעֲלָהּ הוּא יָזוּן לָהּ וְהוּא יִתֵּן לָהּ מַה דְּבָעְיָא.","תָּא חֲזֵי, בְּקַדְמִיתָא כְּתִיב וַיִּבֶן יְיָ אֱלהִים אֶת הַצֵּלָע. דְּאַבָּא וְאִמָּא אַתְקִינוּ לָהּ (בכ\"ד קשוטין. ויבאה בגי' כ\"ד) וּלְבָתַר וַיְבִיאֶהָ אֶל הָאָדָם (ועאלא ליה בחמש קלין (ירמיהו כ״ה:י׳) קול ששון וקול שמחה קול חתן וקול כלה קול מצהלות חתנים) לְאִתְקַשְּׁרָא כֹּלָּא כְּחֲדָא וּלְאִתְחַבְּרָא חַד בְּחַד. וְהוּא יָהִיב (ליה) מַה דְּאִצְטְרִיךְ.","דָּבָר אַחֵר אֱלֹהִים הֵבִין דַּרְכָּהּ, כַּד בְּרַתָּא בְּבֵי אִמָּא, הִיא אִסְתַּכְּלָא בְּכָל יוֹמָא בְּכָל מַה דְּבַעֲיָא בְּרַתָּהּ דִּכְתִיב, (איוב כ״ח:כ״ג) אֱלֹהִים הֵבִין דַּרְכָּהּ, כֵּיוָן דְּחַבְרַת לָהּ בְּבַעֲלָהּ הוּא יָהִיב לָהּ כָּל מַה דְּבַעֲיָא וִיתַקֵּן עוֹבָדָהָא, הֲדָא הוּא דִכְתִיב וְהוּא יָדַע אֶת מְקוֹמָהּ (והאי קרא ברזין עלאין אתקשר) (ד\"א האי קרא על חכמתא עלאה אתמר ואתקשר ברזין עלאין, דהא נקודה קדמאה לית מאן דידע בה כלל, אבל אלהים הבין דרכה דא עלמא דאתי, והו\"א דא טמירא דכל טמירין סתימא דאקרי הו\"א ולא ידיע בשמא)."],[[0,"ובליליא דשבתא, בעי בר נש לאטעמא מכלא, בגין לאחזאה דהאי סוכת שלום מכלא אתכלילת:","ובליל שבת, צריך האדם לטעום מכל המאכלים שיש לו, כדי להראות בזה, שסוכת שלום זו האמורה, אז, היא ג\"כ כלולה מכל. דהיינו מכל ג' הקוין של הבינה. (כנ\"ל בדיבור הסמוך). \u0003ובלבד דלא יפגים מיכלא חדא ליומא,\u0004 ובלבד שלא יחסר סעודה אחת הצריך לו ליום השבת. כלומר שע\"י טעימתו בליל שבת מכל המאכלים לא יחסר מעט מסעודת יום השבת כי כבוד היום עדיף מכבוד לילה. \u0003ואית דאמרי תרין, לתרין סעודתי אחרנין דיומא, ושפיר.\u0004 ויש שאומרים ובלבד שלא יחסר משנים, דהיינו, משני סעודות האחרות של יום השבת. וטוב להזהר בזה, \u0003וכל שכן אי סליק יתיר ליומא ויכיל למטעם ממיכלין אחרנין, ולזעירי בתרין תבשילין סגיא, והא אוקמוה חבריא.\u0004 ואין צריך לומר, אם יש לו יותר מב' סעודות ליום השבת, שיכול לטעום מכל מאכל, ולמצער מספיק, אם ישאר לו ב' תבשילים ליום השבת. וכבר פרשוהו החברים. (ועי' בזהר יתרו מאות תקכח )"],[1,"נר של שבת לנשי עמא קדישא אתייהיבת לאדלקא, וחברייא הא אמרו, דאיהי כבתה בוצינא דעלמא וכו' ושפיר:","נר של שבת, ניתן לנשי עם קדוש להדליק והחברים אמרו הטעם, כי חוה כבתה נרו של העולם, שהביאה המיתה בעולם, ע\"י עצה\"ד שהאכילה לאדה\"ר, והחשיכה העולם, לכן ניתן מצות הדלקת הנרות לנשים, כדי לתקן את מעשה חוה, האשה הראשונה, וטעם טוב הוא. \u0003אבל רזא דמלה האי סוכת שלום מטרוניתא דעלמא היא, ונשמתין דאינון בוצינא עלאה בה שריין,\u0004 אבל סוד הדבר הוא, כי סוכת שלום זה, המאירה בשבת, היא אם העולם, והנשמות, שהם נרות העליונים, שורים בה, מטרוניתא היא אם, מלשון חז\"ל עקר בית \u0003מטרין\u0004 לא היה לה, \u0003ועל דא מטרוניתא בעיא לאדלקא, דהא בדוכתהא אתאחדת ועבדת עובדא,\u0004 וע\"כ אמא, כלומר אשה, צריכה להדליק הנרות, כי עומדת במקום אם הבנים העליונה, שהיא סוכת שלום, ועושה המעשה. ובמעשה זו גורמת שאם הבנים למעלה תשפיע נשמות קדושות לבניה, שה\"ס נרות הרוחניים העליונים. כמ\"ש לפנינו."],[2,"ואתתא בעיא בחדוה דלבא ורעותא לאדלקא בוצינא דשבת:","ומטעם הנזכר, צריכה האשה בלב שמח ובכונה להדליק נר של שבת, \u0003דהא יקרא עלאה היא לה, וזכו רב לגרמה, למזכי לבנין קדישין דיהון בוצינא דעלמא באורייתא ובדחלתא,\u0004 שהרי כבוד העליון הוא לה, וזכות גדול לעצמה, לזכות, ע\"י הדלקות הנרות, לבנים קדושים, שיהיו נרו של העולם בתורה וביראה \u0003ויסגון שלמא בארעא, וירבו שלום בעולם. ויהיבת לבעלה אורכא דחיין בגין כך בעיא לאזדהרא בה,\u0004 ונותנת לבעלה חיים ארוכים ומשום זה צריכה להזהר בהדלקת הנרות, שתהיה בכונה גדולה."],[3,"ת\"ח, שבת ליליא ויומא, זכור ושמור איהו כחדא:","בוא וראה, הלילה והיום של שבת, הוא זכור ושמור כאחד. \u0003וע\"ד כתיב זכור את יום השבת לקדשו, וכתיב שמור את יום השבת, זכור לדכורא שמור לנוקבא,\u0004 וע\"כ כתוב בלוחות הראשונות זכור את יום וגו' ובלוחות אחרונות, שמור את יום כי זכור ושמור כאחד הם, כי זכור הוא לבחינת הדכר, שהוא ז\"א, ושמור הוא לבחינת הנוקבא דז\"א. \u0003וכלא חד\u0004 והכל אחד הוא. \u0003זכאין אינון ישראל חולקיה דקב\"ה, עדביה ואחסנתיה, עלייהו כתיב אשרי וגו',\u0004 אשרי הם ישראל שהם חלק הקב\"ה, גורל שלו ונחלתו, עליהם כתוב, אשרי העם שככה לו אשרי העם שה' אלקיו."],[4,"ויבן וגו' את הצלע אשר לקח מן האדם. אר\"ש, כתיב אלקים הבין דרכה וגו' האי קרא גוונין סגיאין ביה:","ויבן וגו' אר\"ש, הכתוב הזה אלקים הבין דרכה יש פנים מרובים להבין אותו. \u0003אלא מהו אלקים הבין דרכה, כד\"א ויבן ה' אלקים את הצלע.\u0004 אלא מהו פירושו העקרי של אלקים הבין דרכה, הוא כמ\"ש ויבן ה' אלקים את הצלע. \u0003דא תורה שבעל פה דאית בה דרך, כד\"א הנותן בים דרך, בגיני כך אלקים הבין דרכה,\u0004 צלע, פירושו תורה שבעל פה, דהיינו המלכות, שיש בה דרך כמ\"ש הנותן בים דרך, \u0003ים\u0004 זה המלכות, ובה נתן דרך, ע\"כ אלקים הבין דרכה."],[4,"","פירוש, כי יש ב' בחינות מסכים הא' נק' מנעולא הב' נק' מפתחא, ובבחינת ג\"ר שמחזה ולמעלה נתקנה המנעולא, ובבחינת ו\"ק שמחזה ולמטה נתקנה המפתחא, (כנ\"ל בהקדמת הזהר דף נ\"ה ד\"ה וטעם) ולעיל (בראשית א' דף רנ\"ב ד\"ה ורזא) אומר בסו\"ה בים דרכך ושבילך במים רבים, אשר מחזה ולמעלה , דז\"א הנק' זו\"ן הגדולים, נתקן במנעולא הנקרא שביל, וע\"כ ה\"ס לא אתיידע, והחסדים אינם מתגלים בו. ומחזה ולמטה נתקן במפתחא הנק' \u0003דרך,\u0004 וע\"כ אתידע והחסדים מתגלים על ידי הארת החכמה. עש\"ה."],[4,"","וז\"ש כאן שהפירוש של אלקים הבין דרכה הוא בסו\"ה ויבן ה' אלקים את הצלע, \u0003שהיא תשבע\"פ דאית בה דרך,\u0004 דהיינו הנוקבא שמחזה ולמטה דז\"א הנק' תורה שבע\"פ שעליה נאמר ויבן ה' אלקים, דהיינו שבנאה במוחין דג\"ר, משום שהיא נתקנה במפתחא בסוד \u0003בים דרכך,\u0004 וע\"כ אלקים הבין דרכה, \u0003אלקים\u0004 היינו בינה שחזרה להיות חכמה, \u0003הבין,\u0004 היינו השפעת של הבינה הזו, \u0003דרכה\u0004 היינו המפתחא שהיא נעשית מוכשרת על ידה לקבלת הג\"ר. אבל \u0003והוא ידע את מקומה מאן מקומה דא תורה שבכתב, דאית בה דעת,\u0004 והוא ידע את מקומה, ושואל מי הוא מקומה, ואומר, שהוא תורה שבכתב, דהיינו ז\"א, שה\"ס זו\"ן הגדולים שלמעלה מחזה שיש בו דעת. פירוש. כי ז\"א לא נתקן ב\u0003דרך\u0004 אלא ב\u0003שביל,\u0004 שה\"ס מנעולא, וע\"כ ה\"ס קו אמצעי, הנקרא \u0003דעת,\u0004 המכריע בין חכמה ובינה ברוב שפע החסדים שלו."],[5,"ה' אלקים. שם מלא, לאתקנא לה בכלא, וע\"ד אתקריאת חכמה ואתקריאת בינה, בגין דהוה בשם מלא ה' אלקים, בכלא בשלימו בתרי שמהן.","הויה אלקים ה\"ס שם מלא, בכדי לתקן את הנוקבא בכל. וע\"כ נקראים המוחין של הנוקבא חכמה ובינה, משום שנבנה בשם מלא בכל, בהשלימות שבשני שמות, שהויה ה\"ס החכמה ואלקים הוא הבינה, שעל ידיהם נתקנה בכל, בשלימות, דהיינו בין בהארת החכמה הנמשכת מהשם \u0003אלקים,\u0004 ובין בהארת החסדים הנמשכת משם \u0003הויה.\u0004 וז\"ס \u0003שלימו בתרי שמהן.\u0004 וכן ז\"ס הכתוב \u0003אלקים הבין דרכה,\u0004 ה\"ס הארת חכמה הנמשכת מהבינה הנק' \u0003אלקים. והוא ידע את מקומה,\u0004 ה\"ס הארת החסדים הנמשך מאבא ע\"י הז\"א הנק' \u0003דעת,\u0004 שה\"ס \u0003הויה.\u0004"],[6,"את הצלע, דא אספקלריאה דלא נהרא, כד\"א ובצלעי שמחו ונאספו:","את הצלע, זהו מנורה שאינה מאירה, שהיא מלכות, כמ\"ש ובצלעי שמחו וגו' שצלע הוא לשון שבר ואסון, כן הצלע שבכאן, רומז על אספקלריאה שאינה מאירה, הצריכה תיקון. \u0003אשר לקח מן האדם, בגין דהא מתורה שבכתב נפקת,\u0004 הכתוב אשר לקח מן האדם היינו שלקח המלכות מתורה שבכתב, שהוא ז\"א, כי היא יוצאת מהמלכות שבתושב\"כ, \u0003לאשה. לאתקשרא בשלהובא דסטר שמאלא,\u0004 הכ' לאשה, יורה לקשו אותה בשלהבת של צד השמאל, \u0003דהא אורייתא מסטרא דגבורה אתיהיבת, לאשה, למהוי אש ה' קטיר כחדא,\u0004 כי התורה, שהוא ז\"א, ניתנה מצד הגבורה, וגבורה זו קשורה בהנוקבא. וז\"ש לאשה, שהיא נוטריקון א\"ש ה', יורה שאש הגבורה יהיה קשור בה' שהיא הנוקבא."],[7,"ויביאה אל האדם. בגין דלא בעיא לאשתכחא בלחודהא, אלא לאתכללא ולאתחברא בתושב\"כ:","ויביאה אל האדם. הוא משום שאין לה להנוקבא להיות בלבדה, אלא היא צריכה להכלל ולהתחבר עם תושב\"כ. שהוא ז\"א. \u0003כיון דאתחברת בהדיה הוא יזון לה ויתקן לה ויתן לה מה דאצטריך היינו דכתיב ואת הארץ\u0004 וכו'. כיון שהנוקבא נתחברה עם ז\"א, הוא יזון ויתקן אותה ויתן לה מה שהיא צריכה. וז\"ש ואת הארץ. אשר הו' של ואת, יורה על ז\"א המשפיע לה שפע הנק' מזונות והרי בארנוהו. (כנ\"ל בבראשית א' דף רנ\"ד אות שי\"א)"],[8,"מכאן אוליפנא, מאן דאנסיב ברתיה עד לא תיעול לבעלה או\"א מתקנין לה ויהבין לה כל מה דאצטריך:","מכאן למדנו, שהמשיא את בתו, כל עוד שלא נכנסה לבעלה, אביה ואמה מתקנים אותה ונותנים לה כל מה שהיא צריכה, \u0003כיון דאתחברת בבעלה, הוא יזון לה והוא יתן לה מה דבעיא\u0004 ואחר שנתחברה עם בעלה, הבעל מזין אותה ונותן לה מה שצריכה. \u0003ת\"ח בקדמיתא כתיב, ויבן ה' אלקים את הצלע, דאו\"א אתקינו לה ולבתר ויביאה אל האדם.\u0004 בוא וראה, תחלה כתוב ויבן ה' וגו' אשר או\"א תקנו אותה, ואח\"כ כתוב ויביאה אל האדם \u0003לאתקשרא כלא כחדא, ולאתחברא חד בחד והוא יהיב לה מה דאצטריך,\u0004 היינו שיתקשרו זה בזה ויתחברו אחד באחד, והבעל יתן לה מה שצריכה."],[9,"ד\"א, אלקים הבין דרכה, כד ברתא בבי אמא, היא אסתכלא בכל יומא, בכל מה דבעיא ברתה, דכתיב","וכו': פירוש אחר בהפ', אלהים הבין דרכה, הוא, כשהבת בבית אמה, האם מסתכלת בכל יום בכל מה שבתה צריכה. וז\"ש אלקים, שהיא אמא, הבין דרכה, של הנוקבא. \u0003כיון דחברת לה בבעלה, הוא יהיב לה כל מה דבעיא, ויתקן עובדהא הה\"ד\u0004 וכו': אחר שבעלה נשא אותה, הוא נותן לה כל מה שהיא רוצה, ומתקן צרכיה. וז\"ש והוא, דהיינו הבעל, ידע את מקומה. כלומר שמשגיח עליה אחר שנשאת לו."]],[[0,"","וּבְלֵיל שַׁבָּת צָרִיךְ אָדָם לִטְעֹם מֵהַכֹּל כְּדֵי לְהַרְאוֹת שֶׁסֻּכַּת שָׁלוֹם הַ את נִכְלְלָה מֵהַכֹּל, וּבִלְבַד שֶׁלֹּא יִפְגֹּם מַאֲכָל אֶחָד לְיוֹם, וְיֵשׁ אוֹמְרִים שְׁנַיִם, לִשְׁתֵּי הַסְּעוּדוֹת הָאֲחֵרוֹת שֶׁל הַיּוֹם, וְיָפֶה. וְכָל שֶׁכֵּן אִם מַעֲלֶה יוֹתֵר לַיּוֹם וְיָכוֹל לִטְעֹם מִמַּאֲכָלִים אֲחֵרִים. וְלִקְטַנִּים בִּשְׁנֵי תַבְשִׁילִים מַסְפִּיק. וּבֵאֲרוּהָ הַחֲבֵרִים."],[1,"","נֵר שֶׁל שַׁבָּת נִתָּן לְהַדְלָקָה לִנְשׁוֹת הָעָם הַקָּדוֹשׁ. וַהֲרֵי אָמְרוּ הַחֲבֵרִים, שֶׁהִיא כִבְּתָה נֵרוֹ שֶׁל עוֹלָם וְהֶחְשִׁיכָה אוֹתוֹ וְכוּ', וְיָפֶה. אֲבָל סוֹד הַדָּבָר - סֻכַּת שָׁלוֹם זוֹ הִיא גְּבִירַת הָעוֹלָם, וּנְשָׁמוֹת שֶׁהֵם נֵרוֹת עֶלְיוֹנִים בָּהּ הֵם שׁוֹרוֹת. וְעַל זֶה הַגְּבִירָה צְרִיכָה לְהַדְלִיק, שֶׁהֲרֵי בִּמְקוֹמָהּ נֶאֱחֶזֶת וְעוֹשָׂה מַעֲשֶׂה."],[2,"","וְאִשָּׁה צְרִיכָה בְּחֶדְוַת הַלֵּב וְרָצוֹן לְהַדְלִיק נֵר שַׁבָּת, שֶׁהֲרֵי כָּבוֹד עֶלְיוֹן הוּא לָהּ, וּזְכוּת גְּדוֹלָה לְעַצְמָהּ לִזְכּוֹת לְבָנִים קְדוֹשִׁים שֶׁיִּהְיוּ נֵר הָעוֹלָם בְּתוֹרָה וּבְיִרְאָה וְיַרְבּוּ שָׁלוֹם בָּאָרֶץ, וְנוֹתֶנֶת לְבַעְלָהּ חַיִּים אֲרֻכִּים. לָכֵן צְרִיכָה לְהִזָּהֵר בָּהּ."],[3,"","בֹּא רְאֵה, שַׁבָּת לַיְלָה וָיוֹם, זָכוֹר וְשָׁמוֹר הוּא כְּאֶחָד, וְעַל זֶה כָּתוּב זָכוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְּשׁוֹ, וְכָתוּב שָׁמוֹר אֶת יוֹם הַשַּׁבָּת. זָכוֹר לְזָכָר, שָׁמוֹר לִנְקֵבָה, וְהַכֹּל אֶחָד. אַשְׁרֵיהֶם יִשְׂרָאֵל חֶלְקוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, גּוֹרָלוֹ וִירֻשָּׁתוֹ, עֲלֵיהֶם כָּתוּב (תהלים קמד) אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ אַשְׁרֵי הָעָם שֶׁה' אֱלֹהָיו."],[4,"","וַיִּבֶן ה' אֱלֹהִים אֶת הַצֵּלָע אֲשֶׁר לָקַח מִן הָאָדָם וְגוֹ'. אָמַר רַבִּי שִׁמְעוֹן, כָּתוּב (איוב כח) אֱלֹהִים הֵבִין דַּרְכָּהּ וְהוּא יָדַע אֶת מְקוֹמָהּ. בַּפָּסוּק הַזֶּה יֵשׁ גְּוָנִים רַבִּים, אֶלָּא מַה זֶּה אֱלֹהִים הֵבִין דַּרְכָּהּ? כְּמוֹ שֶׁנֶּאֱמַר וַיִּבֶן ה' אֱלֹהִים אֶת הַצֵּלָע, זוֹ תוֹרָה שֶׁבְּעַל פֶּה שֶׁיֵּשׁ בָּהּ דֶּרֶךְ, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה מג) הַנּוֹתֵן בַּיָּם דָּרֶךְ. מִשּׁוּם כָּךְ אֱלֹהִים הֵבִין דַּרְכָּהּ."],[5,"","וְהוּא יָדַע אֶת מְקוֹמָהּ, מִי מְקוֹמָהּ? זוֹ תוֹרָה שֶׁבִּכְתָב שֶׁיֵּשׁ בָּהּ דַּעַת. (דעת ותבונה הולכים כאחד), ה' אֱלֹהִים, שֵׁם מָלֵא לְהַתְקִין לָהּ בַּכֹּל, וְעַל זֶה נִקְרְאָה חָכְמָה וְנִקְרְאָה בִּינָה, מִשּׁוּם שֶׁהָיָה בְשֵׁם מָלֵא - ה' אֱלֹהִים, בַּכֹּל בִּשְׁלֵמוּת בִּשְׁנֵי הַשֵּׁמוֹת."],[6,"","אֶת הַצֵּלָע - זוֹ אַסְפַּקְלַרְיָה שֶׁלֹּא מְאִירָה, כְּמוֹ שֶׁנֶּאֱמַר (תהלים לה) וּבְצַלְעִי שָׂמְחוּ וְנֶאֱסָפוּ. אֲשֶׁר לָקַח מִן הָאָדָם - מִשּׁוּם שֶׁהֲרֵי מִתּוֹרָה שֶׁבִּכְתָב יָצְאָה. לְאִשָּׁה - לְהִתְקַשֵּׁר בְּשַׁלְהֶבֶת שֶׁל צַד שְׂמֹאל, שֶׁהֲרֵי הַתּוֹרָה מִצַּד הַגְּבוּרָה נִתְּנָה. לְאִשָּׁה - לִהְיוֹת אֵשׁ ה' קְשׁוּרָה כְּאֶחָד."],[7,"","וַיְבִאֶהָ אֶל הָאָדָם - מִשּׁוּם שֶׁלֹּא צְרִיכָה לְהִמָּצֵא לְבַדָּהּ, אֶלָּא לְהִתְכַּלֵּל וּלְהִתְחַבֵּר בַּתּוֹרָה שֶׁבִּכְתָב. כֵּיוָן שֶׁהִתְחַבְּרָה עִמּוֹ, הוּא יָזוּן אתָהּ וִיתַקֵּן אוֹתָהּ וְיִתֵּן לָהּ מַה שֶּׁצָּרִיךְ, הַיְנוּ מַה שֶּׁכָּתוּב וְאֵת הָאָרֶץ, וַהֲרֵי בֵּאַרְנוּ. מִכָּאן לָמַדְנוּ, שֶׁמִּי שֶׁמַּשִּׂיא אֶת בִּתּוֹ, עַד שֶׁלֹּא תִכָּנֵס לְבַעְלָהּ, אָבִיהָ וְאִמָּהּ מְתַקְּנִים אוֹתָהּ וְנוֹתְנִים לָהּ כָּל מַה שֶּׁצָּרִיךְ. כֵּיוָן שֶׁהִתְחַבְּרָה בְּבַעְלָהּ, הוּא יָזוּן אוֹתָהּ וְיִתֵּן לָהּ מַה שֶּׁצָּרִיךְ."],[8,"","בֹּא רְאֵה, בַּתְּחִלָּה כָּתוּב וַיִּבֶן ה' אֱלֹהִים אֶת הַצֵּלָע, שֶׁאַבָּא וְאִמָּא הִתְקִינוּ לָהּ (בעשרים וארבעה קשוטים, ויבאה בגימטריא עשרים וארבע). וְאַחַר כָּךְ וַיְבִאֶהָ אֶל הָאָדָם. (והכניס אותה בחמשה קולות, ' (ירמיה כה) קול ששון וקול שמחה קול חתן וקול כלה קול מצהלות חתנים) לְהִתְקַשֵּׁר הַכֹּל כְּאֶחָד וּלְהִתְחַבֵּר אֶחָד בְּאֶחָד. וְהוּא נוֹתֵן (לה) מַה שֶּׁצָּרִיךְ."],[9,"","דָּבָר אַחֵר אֱלֹהִים הֵבִין דַּרְכָּהּ - כְּשֶׁהַבַּת בְּבֵית אִמָּא, הִיא מִסְתַּכֶּלֶת בְּכָל יוֹם בְּכָל מַה שֶּׁבִּתָּהּ צְרִיכָה, שֶׁכָּתוּב (איוב כח) אֱלֹהִים הֵבִין דַּרְכָּהּ. כֵּיוָן שֶׁהִתְחַבְּרָה בְּבַעְלָהּ, הוּא נוֹתֵן לָהּ כָּל מַה שֶּׁצָּרִיךְ וִיתַקֵּן מַעֲשֶׂיהָ. זֶהוּ שֶׁכָּתוּב וְהוּא יָדַע אֶת מְקוֹמָהּ (ופסוק זה נקשר בסודות עליונים) (ד\"א פסוק זה נאמר על חכמה העליונה ונקשר בסודות עליונים, שהרי בנקדה הראשונה אין מי שיודע בה כלל, אבל אלהים הבין דרכה, זה העולם הבא, והו\"א זה הטמיר מכל הטמירים, הנסתר שנקרא הו\"א ולא ידוע בשם)."]]],[["כְּתִיב וַיִּיצֶר יְיָ אֱלהִים אֶת הָאָדָם. הָכָא אִשְׁתַּכְלַל בְּכֹלָּא בְּיָמִינָא וּבִשְׂמָאלָא, וְהָא אוֹקִימְנָא דְּאִתְכְּלִיל בְּיֵצֶר הַטּוֹב, אֲבָל וַיִּיצֶר יְיָ אֱלהִים בְּיֵצֶר טוֹב וּבְיֵצֶר רָע. אַמַּאי, אֶלָּא יֵצֶר טוֹב לֵיהּ לְגַרְמֵיהּ. יֵצֶר הָרָע לְאַתְעָרָא לְגַבֵּי נוּקְבֵיה. (ס\"א ומסטר שמאלא אתער תדיר לגבי נוקבא), רָזָא דְמִלָּה מִכָּאן אוֹלִיפְנָא דְּצָפוֹן אִתְעַר תָּדִיר לְגַבֵּי נוּקְבָא וְאִתְקַשַּׁר בַּהֲדָהּ וּבְגִין כָּךְ אִתְקְרִיאַת אִשָּׁה.","וְתָּא חֲזֵי, יֵצֶר טוֹב וְיֵצֶר הָרָע בְּגִין דְּאִתְיַיהֲבַת נוּקְבָא בֵּינַיְיהוּ (נ\"א דנוקבא אתכלילת בהו) וְאִתְקַשְּׁרָא בַּהֲדַיְיהוּ, וְלָא מִתְקַשְּׁרָא עַד דְּיֵצֶר הָרָע אִתְעַר לְגַבָּהּ וּמִתְקַשְּׁרָן דָּא בְּדָא. וְכֵיוָן דְּמִתְקַשְּׁרָן דָּא בְּדָא, כְּדֵין אִתְעַר יֵצֶר טוֹב דְּאִיהוּ חֶדְוָה וְאַיְיתֵי לָהּ לְגַבֵּיהּ (וכדין אתייהבת בינייהו לאתקנא, ועל דא וייצר יי אלהים שם מלא לגביה יצר טוב ויצר רע) (ד\"א ולעילא סטרא דצפון ממש דאיהי חדוה בלא זוהמא דיצר הרע אחיד בה בקדמיתא, דכתיב, (שיר השירים ב׳:ו׳) שמאלו תחת לראשי ולבתר וימינו תחבקני, ואתייהיבת בין ימינא ושמאלא לאתזנא, ועל דא וייצר יי אלהים שם מלא לגבי תרין סטרין אלין).","אֶת הָאָדָם הָא אוֹקִימְנָא. אֲבָל דְּכַר וְנוּקְבָא כְּחֲדָא (ד\"א ולא הוו) מִתְפָּרְשָׁן לְמֶהוֵי אַפִּין בְּאַפִּין. מַה כְּתִיב עָפָר מִן הָאֲדָמָה הַשְׁתָּא קָיְימָא לְאַתְקָנָא. תָּא חֲזֵי אִתְּתָא כַּד אִתְחַבְּרַת בְּבַעֲלָהּ, אִתְקְרִיאַת עַל שֵׁם בַּעֲלָהּ, אִישׁ אִשָּׁה, צַדִּי\"ק צֶדֶ\"ק, אִיהוּ עוֹפֶר וְאִיהִי עָפָר. (ד\"א ל\"ג) (וכדין) אִיהוּ צְבִי וְאִיהִי צְבִיָה (ד\"א כמא דאת אמר) (יחזקאל כ׳:ו׳) צְבִי הִיא לְכָל הָאֲרָצוֹת.","כְּתִיב, (דברים ט״ז:כ״א) לֹא תִטַּע לְךָ אֲשֵׁרָה כָּל עֵץ אֵצֶל מִזְבַּח יְיָ אֱלֹהֶיךָ אֲשֶׁר תַּעֲשֶׂה לָּךְ. אֵצֶל מִזְבַּח, וְכִי לְעֵילָא מִנֵּיהּ אוֹ בְּאֲתַר אָחֳרָא מָאן שַׁרְיָיה. אֶלָּא הָא אוֹקִימְנָא (קפ\"ב ע\"ב) אֲשֶׁר דָּא בַּעֲלָהּ דְּאִתְּתָא (ד\"א ה\"א) אִתְקְרִיאַת עַל שׁוּם בַּעֲלָהּ אֲשֵׁרָה. (נ\"א הה הם אשר ה\"א) וְעַל דָּא כְּתִיב, (מלכים ב כ״ג:ד׳) לַבַּעַל וְלָאֲשֵׁרָה. בְּגִין כָּךְ כְּתִיב לא תִטַּע לְךָ אֲשֵׁרָה כָּל עֵץ אֵצֶל מִזְבַּח יְיָ אֱלקֶיךָ. לָקֳבֵל (נ\"א אשרה) אֲתַר דְּהַהוּא מִזְבַּח יְיָ, דְּהָא מִזְבַּח יְיָ אִיהוּ קָיְימָא עַל דָּא, וְעַל דָּא לָקֳבְלָה לֹא תִטַּע לְךָ אֲשֵׁרָה אָחֳרָא.","תָּא חֲזֵי, בְּכָל אֲתַר כָּל אִנּוּן פָּלְחֵי שִׁמְשָׁא אִקְרוּן עוֹבְדִין לַבַּעַל, וְאִנּוּן דְּפָלְחִין לְסִיהֲרָא אִיקְרוּן עוֹבְדֵי אֲשֵׁרָה, וְעַל דָּא לַבַּעַל וְלָאֲשֵׁרָה, וַאֲשֵׁרָה אִתְקְרֵי עַל שׁוּם בַּעֲלָהּ אָשֵׁ\"ר. אִי הָכִי אַמַּאי אִתְעֲבַר שְׁמָא דָא. אֶלָּא אֲשֵׁרָה עַל שׁוּם דִּכְתִיב (בראשית ל׳:י״ג) בְּאָשְׁרִי כִּי אִשְׁרוּנִי בָנוֹת וְהוּא (ד\"א הא) דְּלָא אַשְׁרוּהָ שְׁאָר עַמִּין וְקָיְימָא אָחֳרָא תְּחוֹתָהּ, וְלָא עוֹד אֶלָּא דִכְתִיב (איכה א׳:ח׳) כָּל מְכַבְּדֶיהָ הִזִּילוּהָ, וּבְּגִין כָּךְ (נ\"א אתעביד) אִתְעֲבַר שְׁמָא דָא, וּבְגִין דְּלָא יִתְתַּקְּפוּן אִנּוּן דְּעָבְדֵי שְׁאָר עַמִין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, וְקָרֵינָן מִזְבֵּחַ דְּאִיהוּ מֵאֲדָמָה, דִּכְתִיב, (שמות כ׳:כ״א) מִזְבַּח אֲדָמָה וְגו' בְּגִינֵי כָּךְ עָפָר מִן הָאֲדָמָה.","וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים. (מלה אתכליל אבל ויפח באפיו) אִתְכְּלִיל נִשְׁמַת חַיִּים בְּהַהוּא עָפָר, כְּנוּקְבָא דְּמִתְעַבְּרָא מִן דְּכוּרָא דְּהָא מִתְחַבְּרָן וְאִתְמַלְיָיא הַאי עָפָר מִכֹּלָּא, וּמַאי אִיהוּ, רוּחִין וְנִשְׁמָתִין. וַיְהִי הָאָדָם לְנֶפֶשׁ חַיָּה, הַשְׁתָּא אִתְתַּקַּן וְקַיָּים אָדָם לְאַתְקָנָא וּלְמֵיזַן לְנֶפֶשׁ חַיָּה.","וַיִּבֶן יְיָ אֱלֹהִים, אוּף הָכִי נָמֵי בְּשֵׁם מָלֵא, דְּהָא אַבָּא וְאִמָּא אַתְקִינוּ לָהּ עַד לָא אָתַת לְבַעֲלָהּ. אֶת הַצֵּלָע כְּמָא דְאַתְּ אָמֵר, (שיר השירים א׳:ה׳) שְׁחוֹרָה אֲנִי וְנָאוָה בְּנוֹת יְרוּשָׁלָם, אַסְפַּקְלָרְיָאה דְּלָא נָהֲרָא, אֲבָל אַבָּא וְאִמָּא אַתְקִינוּ לָהּ לְאִתְפַּיָיסָא בַּעֲלָהּ בַּהֲדָהּ.","וַיְבִאֶהָ אֶל הָאָדָם. מֵהָכָא אוֹלִיפְנָא דְּבָעָאן אַבָּא וְאִמָּא דְכַלָּה לְאָעֳלָה בִּרְשׁוּתֵיהּ דְּחָתָן. כְּמָא דְאַתְּ אָמֵר, (דברים כ״ב:ט״ז) אֶת בִּתִּי נָתַתִּי לָאִישׁ הַזֶּה וְגו'. מִכָּאן וָאֵילָךְ בַּעֲלָהּ יֵיתֵי לְגַבָּהּ, דְּהָא בֵּיתָא דִילָהּ הוּא דִּכְתִיב, (בראשית כ״ט:ל׳) וַיָּבֹא אֵלֶיהָ. וַיָּבֹא גַּם אֶל רָחֵל, בְּקַדְמִיתָא וַיְבִאֶהָ אֶל הָאָדָם דְּעַד הָכָא אִית לְאַבָּא וּלְאִמָּא לְמֶעֱבַד, לְבָתַר אִיהוּ יֵיתֵי לְגַבָּהּ וְכָל בֵּיתָא דִילָהּ הוּא, וְיִטּוֹל רְשׁוּת מִינָהּ.","וְעַל דָּא אִתְעַרְנָא דִּכְתִיב, (בראשית כ״ח:י״א) וַיִּפְגַּע בַּמָּקוֹם וַיָּלֶן שָׁם, דְּנָטִיל רְשׁוּ בְּקַדְמִיתָא. מִכָּאן אוֹלִיפְנָא דְּמָאן דְּמִתְחַבֵּר בְּאִנְתְּתֵיהּ בָּעֵי לְמִפְגַע לָהּ וּלְבַסְמָא לָהּ בְּמִלִּין, וְאִי לָאו לָא (קמח ב) יָבִית לְגַבָּהּ. בְּגִין דִּיהֵא רְעוּתָא דִלְהוֹן כְּחֲדָא בִּדְלָא אֲנִיסוּ."],[[0,"וייצר ה' אלקים וגו' הכא אשתכלל בכלא בימינא ובשמאלא:","וייצר וגו' שכתוב עם ב' יודין יורה, שכאן נשתכלל האדם בכל, בימין ובשמאל \u0003והא אוקימנא, דאתכליל ביצה\"ט, אבל וייצר וגו' ביצר טוב וביצר רע,\u0004 ובארנו, כי נכלל ביצה\"ט מעת בריאותו ולא מיצה\"ר, אבל אח\"כ בהכ' וייצר וגו' הוא נכלל גם ביצה\"ר. שז\"ס ב' יודין דוייצר, האחת רומזת על יצה\"ט, והשניה על יצה\"ר. \u0003אמאי, אלא יצר טוב ליה לגרמיה, יצה\"ר, לאתערא לגבי נוקבי,\u0004 שואל, למה ניתן לו כאן ב' יצרים, ואומר, היצר טוב ניתן לו לעצמו, ויצה\"ר, לעורר אותו אל נוקביה. \u0003רזא דמלה, מכאן אוליפנא דצפון אתער תדיר לגבי נוקבא ואתקשר בהדה ובג\"כ אתקריאת אשה.\u0004 סוד הדבר הוא, מכאן למדנו, שהצפון דהיינו צד השמאל, מעורר תמיד להנקבה, ומתקשר עמה, וע\"כ נקראת אשה, שהוא נוטריקון אש ה', כי השמאל שהוא אש קשור בה' שהיא הנקבה. כי הנוקבא נבנית ויוצאת מצד השמאל (כנ\"ל בבראשית א' דף נ\"ב אות ל\"ט)."],[1,"ות\"ח, יצר טוב ויצר הרע, בגין דאתייהבת נוקבא בינייהו, ואתקשרא בהדייהו:","ובוא וראה, היצר טוב ויצר הרע שניתנו לאדם, הוא משום שהנוקבא ניתנה ביניהם, ונקשרה עמהם. \u0003ולא מתקשרא עד דיצה\"ר אתער לגבה, ומתקשרן דא בדא,\u0004 ואינה נקשרת ביניהם, מטרם שהיצה\"ר נתעורר אצלה ונקשרים זה בזה. \u0003וכיון דמתקשרן דא בדא, כדין אתער יצ\"ט דאיהו חדוה ואייתי לה לגביה.\u0004 ואחר שנקשרו זב\"ז, אז נתעורר יצה\"ט, שהיא חדוה, ומביא את הנוקבא אצלו."],[1,"","פירוש. היצה\"ט ה\"ס קו ימין ויצה\"ר קו שמאל, ונודע שהנוקבא צריכה להתקשר בקו האמצעי המכריע ביניהם, אבל תחילה מתעורר הקו שמאל אליה, ונקשרת בו, כי היא בחינת שמאל (כנ\"ל בראשית א' נ\"ב אות לט) ואח\"כ מקבלת חסדים מז\"א, שהוא בחינת ימין, ואז אחר שכבר כלולה מימין ושמאל, היא מתקשר באמצעי שבין ימין ושמאל."],[2,"את האדם, הא אוקימנא, אבל דכר ונוקבא כחדא, ולא הוו מתפרשן למהוי אפין באפין.","את האדם, הרי פרשנוה, אבל את האדם כולל דכר ונוקבא יחד, דהיינו דו פרצופין, ולא היו נפרדים זה מזה להיות פנים בפנים. \u0003מה כתיב, עפר מן האדמה, השתא קיימא לאתקנא,\u0004 מה כתוב בהם, עפר מן האדמה, עתה הוא עומד להתתקן, דהיינו שיפרדו זה מזה, ויהיו פב\"פ. ובכדי לבאר ענין התקון המרומז בהכ' עפר מן האדמה, מביא הזהר לפנינו את המאמר הסמוך."],[2,"ת\"ח אתתא כד אתחברת בבעלה אתקריאת על שם בעלה, איש אשה, צדיק צדק:","בוא וראה, אשה כאשר נשאת לבעלה, היא נקראת על שם בעלה, כמו איש אשה, צדיק צדק. \u0003איהו עופר ואיהי עפר, איהו צבי ואיהי צביה כד\"א צבי היא\u0004 וגו', הוא נקרא עופר והיא נקראת עפר. הוא נקרא צבי, והיא נק' צביה כמ\"ש צבי היא לכל הארצות. פירוש, כמו שהקב\"ה נק' צבי או עופר, כי מטרם שז\"א נמתק בבינה, הוא נקרא עופר. ואחר שנמתק בהבינה, נקרא צבי. כמ\"ש דומה דודי לצבי או לעופר וגו' כן הנוקבא נקראת בשמות אלו, ומביא ראיה מהכתוב צבי היא לכל הארצות, שהארץ שהיא הנוקבא נקראת ג\"כ בשם \u0003צבי\u0004 כמו בעלה, ועד\"ז מטרם שהנוקבא נמתקת בבינה, היא נקראת \u0003עפר,\u0004 כמו בעלה שנקרא אז \u0003עופר,\u0004 ובזה ביארו לנו השם עפר, שבהכתוב עפר מן האדמה."],[3,"כתיב לא תטע לך אשרה כל עץ אצל מזבח וגו'. אצל מזבח, וכי לעילא או באתר אחרא מאן שרייה","כתיב לא תטע וגו', שכתוב \u0003אצל מזבח,\u0004 דמשמע שרק אצל המזבח אסור ליטע אשרה, ומקשה וכי למעלה מהמזבח או במקום אחר, מי התיר ליטע אשרה. \u0003אלא הא אוקימנא, אשר, דא בעלה, דאתתא אתקריאת על שום בעלה, אשרה,\u0004 אלא ביארנו, \u0003אשר,\u0004 הוא שם בעלה, שהאשה נקראת על שמו, \u0003אשרה.\u0004 כלומר אשר הוא ז\"א, כי השמות אהיה אשר אהיה, הנה ב' אהיה ה\"ס חו\"ב, ואש\"ר, הוא ז\"א בסוד הדעת, המכריע בין חו\"ב. אשרה היא נוקבא דז\"א \u0003ועל דא כתיב לבעל ולאשרה,\u0004 וע\"כ כתוב לבעל ולאשרה, שהם הלעומת של זו\"ן דקדושה, בעל כנגד ז\"א, ואשרה, כנגד הנוקבא. \u0003בגין כך כתיב לא תטע לך אשרה כל עץ אצל מזבח וגו' לקבל אתר דההוא מזבח ה', דהא מזבח ה' איהו קיימא על דא,\u0004 וע\"כ כתוב לא תטע וגו' אצל מזבח וגו', כלומר, בזה מיושב קושיא הנ\"ל, למה כתוב אצל מזבח. כי אצל הוא כמו במקום, ואומר הכתוב לא תטע לך אשרה של ע\"ז, במקום מזבח ה' אלקיך, שהרי מזבח ה' עומד על זה, כלומר שעומד לבטל קליפה זו דאשרה, כמ\"ש לפנינו. \u0003וע\"ד לקבלה לא תטע אשרה אחרא,\u0004 וע\"כ, כנגד המזבח, לא תטע אשרה אחרת דע\"ז."],[4,"ת\"ח, בכל אתר, כל אינון פלחי שמשא, אקרון עובדין לבעל, ואינון דפלחין לסיהרא אקרון עובדי אשרה:","בוא וראה, כל אלו העובדים לחמה, נקראים בכל מקום עובדי הבעל, וכל אלו העובדים ללבנה נקראים עובדי אשרה. \u0003ועל דא לבעל ולאשרה, ואשרה אתקרי על שום בעלה, אשר,\u0004 וע\"כ כתוב לבעל ולאשרה, אשר בעל הוא חמה שהוא הזכר, ואשרה היא לבנה, שהיא הנוקבא, ונקראת \u0003אשרה,\u0004 על שם בעלה שנקרא \u0003אשר.\u0004"],[4,"אי הכי אמאי אתעבר שמא דא, אלא אשרה על שום דכתיב באשרי כי אשרוני בנות:","שואל א\"כ שהיא נקראת על שם בעלה, \u0003אשר,\u0004 למה ניטל מהנוקבא שם זה, כי לא מצאנו שהנוקבא דקדושה תהיה נקראת אשרה. ואומר, אלא שהיא נקראת אשרה של שם הכתוב באשרי כי אשרוני בנות, דהיינו על שם, שאחרים מאשרים ומשבחים אותה. כי עליה נאמר יפה נוף משוש כל הארץ וגו', \u0003דלא אשרוה שאר עמין, וקיימא אחרא תחותה.\u0004 ולא אשרו אותה שאר האומות והעמידו אשרה אחרת של ע\"ז תחתיה. \u0003ולא עוד אלא דכתיב כל מכבדיה הזילוה,\u0004 ולא עוד אלא שזלזלו בה, שכתוב כל מכבדיה הזילוה. \u0003ובג\"כ אתעבר שמא דא,\u0004 ובשביל זה, ניטל ממנה שם הזה, כי אינם עוד מאשרים אותה. \u0003ובגין דלא יתתקפון אינון שאר עמין דעבדי עבודת כוכבים ומזלות קרינן לה מזבח, דאיהו מאדמה.\u0004 (כצ\"ל) וכדי שלא יתחזקו שאר האומות, העובדים עכו\"ם, קוראים אותה מזבח, שהוא נעשה מאדמה. פירוש, \u0003מזבח,\u0004 הוא השם הניתן לה תחת השם, \u0003אשרה,\u0004 שהוא נעשה מאדמה, שה\"ס הבינה הנקראת אדמה, מלשון ארץ אדום הרומז על בינה, כנודע. ועל ידי המיתוק הזה דבינה מקבלת מוחין דפב\"פ, המבטל את הכחות של האומות עובדי ע\"ז. \u0003דכתיב מזבח אדמה\u0004 וגו', כמ\"ש מזבח אדמה תעשה לי \u0003בגיני כך עפר מן האדמה,\u0004 בשביל זה נאמר ג\"כ באדם הראשון וייצר ה' אלקים את האדם עפר מן האדמה. אשר עפר הוא שם המלכות, האדמה ה\"ס בינה כנ\"ל, ועל ידי המיתוק של עפר באדמה, זכה לקבל המוחי דנשמת חיים, כמ\"ש לפנינו."],[5,"ויפח באפיו נשמת חיים, אתכליל נשמת חיים בההוא עפר כנוקבא דמתעברא מן דכורא:","ואחר שהעפר נמתק באדמה, כתוב, ויפח באפיו נשמת חיים, שנכללה נשמת חיים בעפר הזה שנמתק, שהוא הגוף של אדה\"ר, כמו נקבה המקבל הריון מן דכר. כלומר אחר שהגוף נכלל באדמה, שהיא בינה, עלה הגוף דאדה\"ר להנוקבא דאצילות המלבשת את הבינה, ועלה שם בסוד העיבור, ושם קבל את נשמת חיים בסדר עבור יניקה מוחין, כנודע. \u0003דהא מתחברן ואתמליא האי עפר מכלא,\u0004 שהרי עתה מתחברים הנשמה והגוף. כי אור הבינה נקרא נשמה, וכיון שהגוף נמתק ונעשה לכלי דבינה, נעשה ראוי לקבל אור הבינה ומתחברים אור וכלי. ונתמלא עפר הזה, שהוא הגוף, מכל האורות, \u0003ומאי איהו רוחין ונשמתין,\u0004 ושואל מה הם האורות הללו, ואומר, שהם רוחות ונשמות. \u0003ויהי האדם לנפש חיה, השתא אתתקן וקיים אדם לאתקנא ולמיזן לנפש חיה\u0004 ואז נאמר ויהי האדם לנפש חיה, שפירושו, כי עתה נתקן האדם בגוף ונשמה, והוא עומד לתקן וליזון את הנפש חיה, שהיא הנוקבא שלו."],[6,"ויבן ה' אלקים אוף הכי נמי בשם מלא, דהא או\"א אתקינו לה עד דלא אתת לבעלה:","ויבן ה' אלקים. הנה גם כאן בבנין הצלע כתוב שם מלא כמו בהכ' וייצר ה' אלקים את האדם. דהיינו הויה אלקים הנבחן לשם מלא. כי או\"א תקנו אותה בסוד בנין הצלע מטרם שהנוקבא באה לבית בעלה, ז\"א, וע\"כ כתוב כאן שם מלא, כי הוי\"ה ה\"ס אבא, אלקים ה\"ס אמא."],[6,"את הצלע. כד\"א שחורה אני ונאוה וגו' אספקלריאה דלא נהרא:","את הצלע, הוא כמ\"ש שחורה אני ונאוה וגו',כי בנו אותה, בסוד מנורה שאינה מאירה \u0003אבל או\"א אתקינו לה לאתפייסא בעלה בהדה, ויביאה אל לאדם\u0004 אבל אח\"כ תקנו אותה או\"א באופן שיתפייס עמה בעלה, וז\"ש ויביאה אל האדם."],[6,"","ביאור הדברים כי ב' פעולות מובאים כאן בהכתוב, א) בנין הצלע, שכ' ויבן ה' אלקים את הצלע. ב) הוא ההבאה אל האדם. שנאמר, ויביאה אל האדם. והוא כי מתחילה בונים או\"א את הנוקבא מבחינת קו שמאל בלבד, ונבחן לבנין הצלע, ואז היא שחורה, כי בקו שמאל נמצאת החכמה בלבדה בלי חסדים, ואין הנוקבא יכולה לקבל אפילו את אור החכמה, מבלי לבוש של אור חסדים, והיא חשכה. וע\"כ נקראת אז בשם אספקלריאה דלא נהרא. ועכ\"ז אומר הכתוב עליה על עת ההיא, שאומרת אז, שחורה אני ונאוה. כי אע\"פ שהיא שחורה בלי אור מ\"מ היא נאוה, להיותה נמצאת בהיכל או\"א, וקומתה שוה אל ז\"א, כי אז נבחן שז\"א מלביש קו ימין של המוחין דאו\"א שהם חכמה וחסד. והנוקבא מלבשת הקו שמאל של המוחין דאו\"א, שהם בינה וגבורה. ואינה צריכה משום זה לז\"א שיתקן אותה, כי היא שלימה כמוהו. שאז נאמר עליהם שהם ב' מאורות הגדולים (כנ\"ל בבראשית א' דף ק\"ד ד\"ה את ע\"ש) וע\"כ אומרת אז, שחורה אני ונאוה. אע\"פ שהיא אספקלריאה שאינה מאירה. וכשהנוקבא נמצאת במצב הזה דהיינו בבנין הצלע שהיא מקו שמאל, היא במחלוקת עם ז\"א, כמו הקו שמאל שהיא במחלוקת עם קו הימין. ולפיכך צריכים או\"א לתקן אותה \u0003לאתפייסא בעלה בהדה,\u0004 ועל זה צריכים פעולה ב), שהיא ויביאה אל האדם דהיינו שתקנו אותה או\"א במסך כזה שתהיה ראויה לקבל חסדים מז\"א, שתקון המסך הזה נבחן, שהביא אותה אל הז\"א בעלה. כי עתה יכול ז\"א להשפיע לה חסדים, \u0003ואתפייסא בעלה בהדה.\u0004 אמנם מחמת תקון המסך הזה, נעשית הנוקבא בבחינת \u0003דלית לה מגרמה ולא מידי,\u0004 כי עתה צריכה לקבל הכל מז\"א בעלה. (כנ\"ל בבראשית א' דף ק\"ח ד\"ה וכבר ע\"ש) והנה נתבאר היטב ב' הפעולות של או\"א המובאות כאן בהכ', א) הוא בנין הצלע, שהנוקבא נעשית אז בבחינת אספקלריאה שאינה מאירה ב) ויביאה אל האדם שהנוקבא נעשית אז בבחינת דלית לה מגרמה ולא מידי. וזכור זה לכל ההמשך של המאמר הזה."],[7,"מהכא אוליפנא דבעאן או\"א דכלה לאעלה ברשותיה דחתן כד\"א את בתי וגו':","מכאן למדנו שאו\"א של הכלה צריכים להכניס את הכלה ברשות החתן, כמ\"ש את בתי נתתי לאיש הזה. \u0003מכאן ואילך, בעלה ייתי לגבה, דהא ביתא דילה הוא דכתיב ויבא אליה, ויבא גם אל רחל.\u0004 מכאן ואילך בעלה יבוא אליה כי הבית שלה הוא, ולא שלו, ועי\"כ צריך הוא לבוא אליה, כמ\"ש ויבא אליה, ויבא גם אל רחל. פירוש, הארת החכמה מכונה בשם בית, בסו\"ה בחכמה יבנה בית (כנ\"ל בראשית א' דף י\"ב ד\"ה פירוש) ואין הארת החכמה נמשכת בשום פרצוף שמא\"א עד הנוקבא רק בהנוקבא בלבדה, (כנ\"ל בראשית א' דף רע\"ו ד\"ה ועוד) בסוד ב' ראשית. וע\"כ \u0003ביתא דילה הוא\u0004 שאין ז\"א יכול להאיר בהארת חכמה, זולת בעת הזווג עם הנוקבא, וע\"כ הוא מוכרח מבחינה זו לבא אליה. וז\"ס ויבא אליה, ויבא גם אל רחל."],[7,"בקדמיתא ויביאה אל האדם, דעד הכא אית לאו\"א למעבד, לבתר איהו ייתי לגבה,","בתחילה כתיב ויביאה אל האדם כי עד כאן צריכים או\"א לתקן אותה, דהיינו שתקנו אותה במסך כזה, שתהיה ראויה לקבל חסדים בזווגה עם ז\"א (כנ\"ל בדבור הסמוך), ואח\"כ, ז\"א יבא אליה, \u0003וכל ביתא דילה הוא.\u0004 וכל הבית הוא של הנוקבא. כמ\"ש לעיל בדבור הסמוך."],[8,"ויטול רשות מינה, וע\"ד אתערנא דכתיב ויפגע במקום וילן שם, דנטיל רשו בקדמיתא:","ויטול רשות ממנה קודם הזווג, ועל זה הערנו, שכתוב ויפגע במקום וגו' שפירושו שיטול רשות בתחילה. \u0003מכאן אוליפנא, דמאן דמתחבר באנתתיה, בעי למפגע לה ולבסמא לה במלין:\u0004 מכאן למדנו מי שמתחבר עם אשתו צריך לפייס אותה ולהמתיקה בדיבורים. \u0003ואי לאו לא יבית לגבה בגין דיהא רעותא דלהון כחדא בדלא אניסו,\u0004 ואם אינו מפייסה, לא ילין אצלה, משום שהרצון שלהם צריך להיות כאחד באין אונס."],[8,"","פנימיות הדברים. כי כל הנוהג בסדר בנין המדרגה, נוהג ג\"כ בהכרח בסדרי קיומה של המדרגה, ולפיכך, אותם ב' פעולות הנ\"ל המבוארות באו\"א לבנין הנוקבא, נוהגות ג\"כ בסדר הזווג של הנוקבא עם ז\"א. שמתחילה צריך להמשיך לה הארת השמאל, שהיא דוגמת פעולה א' דאו\"א, שה\"ס בנין הצלע. ואח\"כ מזדווג עמה ונותן לה אור החסדים מקו האמצעי שלו, שהיא דוגמת פעולה ב' דאו\"א, שה\"ס ויביאה אל האדם, שפירושו תקון המסך שתהיה ראויה לקבלת אור חסדים כנ\"ל."],[8,"","ופעולה הא' נקרא כאן נטילת רשות או פיוסא, מטעם שמטרם זה היא במחלוקת עם ז\"א, כי להיותה בעיקר מקו שמאל, וז\"א מקו ימין בעיקר, ע\"כ נוהג ביניהם אותו המחלוקת שהיה בין קו שמאל לימין (כנ\"ל בראשית א' דף נ\"ו אות מ\"ד) ולפיכך צריך ז\"א לפייסה קודם הזווג, והיא אינה מתפייסת אלא בהמשכת הארת השמאל, שהיא עיקר בחינתה."],[8,"","ועם זה תבין היטב מ\"ש לעיל (באות ר\"ח) \u0003ולא מתקשרא עד דיצה\"ר אתער לגבה\u0004 וכו' כי היצה\"ר רומז לקו שמאל כמ\"ש שם בהסולם, וכיון שהיא במחלוקת עמו, ע\"כ אינה מתקשרת עמו מטרם שממשיך לה מהארת השמאל, שה\"ס התעוררות היצה\"ר. כמ\"ש שם. וז\"ש כאן, \u0003ואי לאו לא יבית לגבה בגין דיהא רעותא דלהון כחדא בדלא אניסן,\u0004 כי מטרם שממשיך לה הארת השמאל אינה מתפייסת, והיה צריך לאנוס אותה."],[8,"","והאדם המעלה מ\"ן ליחוד ז\"א ונוקביה, צריך ג\"כ לעורר אלו ב' הפעולות דאו\"א. וזסו\"ה אצל יעקב אבינו, שפעולה הא', דהיינו הארת השמאל מרומז בהכתוב \u0003ויפגע במקום,\u0004 כי אין פגיעה אלא פיוסא, מלשון ואל תפגע בי. ופיוסא משמעותו המשכת הארת השמאל. ופעולה ב' דאו\"א דהיינו תקון המסך להכשירה לקבלת החסדים, מרומז בהכ' ויקח מאבני המקום וישם מראשותיו, כי המסך מכונה בשם אבן, כנודע. וע\"י ב' פעולות הללו נעשה היחוד העליון, וז\"ש, והנה ה' נצב עליו וגו'. ולפיכך מביא הזהר כאן ראיה מהכ' ויפגע במקום, וכן שאר הכתובים כמ\"ש לפנינו."]],[[0,"","כָּתוּב וַיִּיצֶר ה' אֱלֹהִים אֶת הָאָדָם. כָּאן נִתְקַן הַכֹּל בְּיָמִין וּבִשְׂמֹאל, וַהֲרֵי בֵּאַרְנוּ שֶׁנִּכְלַל בַּיֵּצֶר הַטּוֹב, אֲבָל וַיִּיצֶר ה' אֱלֹהִים - בְּיֵצֶר טוֹב וְיֵצֶר רָע. לָמָּה,? אֶלָּא יֵצֶר טוֹב לוֹ לְעַצְמוֹ, יֵצֶר הָרָע לְעוֹרֵר אֵלָיו אֶת נְקֵבָתוֹ (ס\"א ומצד שמאל מתעורר תמיד לנקבה). סוֹד הַדָּבָר, מִכָּאן לָמַדְנוּ שֶׁצָּפוֹן מִתְעוֹרֵר תָּמִיד לִנְקֵבָה וְנִקְשָׁר עִמָּהּ, וְלָכֵן נִקְרֵאת אִשָּׁה."],[1,"","וּבֹא וּרְאֵה, יֵצֶר טוֹב וְיֵצֶר הָרָע, מִשּׁוּם שֶׁהַנְּקֵבָה נִתְּנָה בֵּינֵיהֶם (נ\"א שנקבה נכללת בהם) וְהִתְקַשְּׁרָה עִמָּם, וְלֹא מִתְקַשֶּׁרֶת עַד שֶׁיֵּצֶר הָרָע מִתְעוֹרֵר אֵלֶיהָ וּמִתְקַשְּׁרִים זֶה בָּזֶה. וְכֵיוָן שֶׁמִּתְקַשְּׁרִים זֶה בָּזֶה, אָז מִתְעוֹרֵר יֵצֶר הַטּוֹב שֶׁהוּא חֶדְוָה וּמֵבִיא אוֹתָהּ אֵלָיו, (ואז נתנת ביניהם לתקן, ועל זה וייצר ה' אלהים שם מלא אליו יצר טוב ויצר רע) (ד\"א ולמעלה צד הצפון ממש שהיא חדוה בלי זהמה, שיצר הרע אוחז בה בתחלה, שכתוב (שיר ב) שמאלו תחת לראשי, ואחר כך וימינו תחבקני, ונתנה בין ימין ושמאל להזון, ועל זה וייצר ה' אלהים, שם מלא לגבי שני הצדדים הללו)."],[2,"","אֶת הָאָדָם, הֲרֵי בֵּאַרְנוּ, אֲבָל זָכָר וּנְקֵבָה כְּאֶחָד, (ולא היו) נִפְרָדִים לִהְיוֹת פָּנִים בְּפָנִים. מַה כָּתוּב? עָפָר מִן הָאֲדָמָה. עַכְשָׁו עוֹמֵד לְהַתְקִין. בּא תִרְאֶה, כְּשֶׁאִשָּׁה מִתְחַבֶּרֶת בְּבַעְלָהּ, הִיא נִקְרֵאת עַל שֵׁם בַּעְלָהּ. אִישׁ אִשָּׁה. צַדִּי\"ק צֶדֶ\"ק. הוּא עֹפֶר וְהִיא עָפָר. (ואז) הוּא צְבִי וְהִיא צְבִיָּה, כְּמוֹ שֶׁנֶּאֱמַר (יחזקאל כ) צְבִי הִיא לְכָל הָאֲ רָצוֹת."],[3,"","כָּתוּב (דברים טז) לֹא תִטַּע לְךְ אֲשֵׁרָה כָּל עֵץ אֵצֶל מִזְבַּח ה' אֱלֹהֶיךְ אֲשֶׁר תַּעֲשֶׂה לָּךְ. אֵצֶל מִזְבַּח - וְכִי לְמַעְלָה מִמֶּנּוּ אוֹ בְּמָקוֹם אַחֵר מִי הִתִּיר? אֶלָּא הֲרֵי בֵּאַרְנוּ, אָשֵׁר זֶה בַּעְלָהּ, שֶׁהָאִשָּׁה הִיא נִקְרֵאת עַל שֵׁם בַּעְלָהּ אֲשֵׁרָה (נ\"א: הרי הם אשר ה\"א), וְעַל זֶה כָּתוּב (מלכים ב כג) לַבַּעַל וְלָאֲשֵׁרָה. מִשּׁוּם כָּךְ כָּתוּב לֹא תִטַּע לְךְ אֲשֵׁרָה כָּל עֵץ אֵצֶל מִזְבַּח ה' אֱלֹהֶיךְ, כְּנֶגֶד הַמָּקוֹם שֶׁל אוֹתוֹ מִזְבַּח ה', שֶׁהֲרֵי מִזְבַּח ה' הוּא עוֹמֵד עַל זֶה, וְעַל זֶה כְּנֶגְדָּהּ לֹא תִטַּע לְךְ אֲשֵׁרָה אַחֶרֶת."],[4,"","בֹּא רְאֵה, בְּכָל מָקוֹם, כָּל אוֹתָם עוֹבְדֵי הַשֶּׁמֶשׁ נִקְרָאִים עוֹבְדִים לַבַּעַל, וְאֵלּוּ שֶׁעוֹבְדִים לַלְּבָנָה נִקְרָאִים עוֹבְדֵי אֲשֵׁרָה. וְלָכֵן לַבַּעַל וְלָאֲשֵׁרָה. וַאֲשֵׁרָה נִקְרֵאת עַל שֵׁם בַּעְלָהּ אָשֵׁ\"ר. אִם כָּךְ, לָמָּה נִתְבַּטֵּל הַשֵּׁם הַזֶּה? אֶלָּא אֲשֵׁרָה עַל שֵׁם שֶׁכָּתוּב (בראשית ל) בְּאָשְׁרִי כִּי אִשְּׁרוּנִי בָּנוֹת, וְהוּא (הרי) שֶׁלֹּא אִשְּׁרוּהָ שְׁאָר הָעַמִּים וְעוֹמֶדֶת אַחֶרֶת תַּחְתֶּיהָ. וְלֹא עוֹד, אֶלָּא שֶׁכָּתוּב (איכה א) כָּל מְכַבְּדֶיהָ הִזִּילוּהָ, וְלָכֵן (נעבד) נִתְבַּטֵּל הַשֵּׁם הַזֶּה, וּכְדֵי שֶׁלֹּא יִתְחַזְּקוּ אוֹתָם שֶׁעוֹשִׂים שְׁאָר עַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה, וְקוֹרְאִים מִזְבֵּחַ שֶׁהוּא מֵאֲדָמָה, שֶׁכָּתוּב (שמות כ) מִזְבַּח אֲדָמָה וְגוֹ'. מִשּׁוּם כָּךְ עָפָר מִן הָאֲדָמָה."],[5,"","וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים - (דבר נכלל, אבל ויפח באפיו) נִכְלְלָה נִשְׁמַת חַיִּים בְּאוֹתוֹ עָפָר, כִּנְקֵבָה שֶׁמִּתְעַבֶּרֶת מִן הַזָּכָר, שֶׁהֲרֵי מִתְחַבְּרִים וּמִתְמַלֵּא הֶעָפָר הַזֶּה מֵהַכֹּל, וּמַהוּ? רוּחוֹת וּנְשָׁמוֹת. וַיְהִי הָאָדָם לְנֶפֶשׁ חַיָּה - כָּאן הִתְתַּקֵּן וְקַיָּם אָדָם לְהַתְקִין וְלָזוּן אֶת הַנֶּפֶשׁ חַיָּה."],[6,"","וַיִּבֶן ה' אֱלֹהִים. אַף כָּאן גַּם כֵּן בְּשֵׁם מָלֵא, שֶׁהֲרֵי אַבָּא וְאִמָּא הִתְקִינוּ אוֹתָהּ עַד שֶׁלֹּא בָאָה לְבַעְלָהּ. אֶת הַצֵּלָע, כְּמוֹ שֶׁנֶּאֱמַר (שיר א) שְׁחוֹרה אֲנִי וְנָאוָה בְּנוֹת יְרוּשָׁלָיִם, אַסְפַּקְלַרְיָה שֶׁלֹּא מְאִירָה. אֲבָל אַבָּא וְאִמָּא הִתְקִינוּ לָהּ שֶׁיִּתְפַּיֵּס בַּעְלָהּ עִמָּהּ."],[7,"","וַיְבִאֶהָ אֶל הָאָדָם, מִכָּאן לָמַדְנוּ שֶׁצְּרִיכִים אַבָּא וְאִמָּא שֶׁל הַכַּלָּה לְהַכְנִיסָהּ בִּרְשׁוּתוֹ שֶׁל הֶחָתָן, כְּמוֹ שֶׁנֶּאֱמַר (דברים כב) אֶת בִּתִּי נָתַתִּי לָאִישׁ הַזֶּה וְגוֹ'. מִכָּאן וְאֵילָךְ בַּעְלָהּ יָבוֹא אֵלֶיהָ, שֶׁהֲרֵי הַבַּיִת הוּא שֶׁלָּהּ, שֶׁכָּתוּב (בראשית כט) וַיָּבֹא אֵלֶיהָ. וַיָּבֹא גַּם אֶל רָחֵל. בַּהַתְחָלָה וַיְבִאֶהָ אֶל הָאָדָם, שֶׁעַד כָּאן יֵשׁ לְאַבָּא וּלְאִמָּא לַעֲשׂוֹת, אַחַר כָּךְ הוּא יָבא אֵלֶיהָ, וְכָל הַבַּיִת שֶׁלָּהּ הוּא, וְיִטֹּל רְשׁוּת מִמֶּנָּה."],[8,"","וְעַל זֶה הֵעַרְנוּ, שֶׁכָּתוּב (שם כח) וַיִּפְגַּע בַּמָּקוֹם וַיָּלֶן שָׁם, שֶׁנָּטַל רְשׁוּת בַּהַתְחָלָה. מִכָּאן לָמַדְנוּ, שֶׁמִּי שֶׁמִּתְחַבֵּר בְּאִשְׁתּוֹ, צָרִיךְ לְבַקֵּשׁ מִמֶּנָּה וּלְשַׂמֵּח אוֹתָהּ בִּדְבָרִים, וְאִם לֹא - שֶׁלֹּא יָלוּן אֶצְלָהּ, כְּדֵי שֶׁיִּהְיֶה רָצוֹן שֶׁלָּהֶם כְּאֶחָד בְּלֹא אֹנֶס."]]],[["וַיָּלֶן שָׁם כִּי בָא הַשֶּׁמֶשׁ, לְאַחֲזָאָה דְּאֲסִיר לֵיהּ לְבַר נָשׁ לְשַׁמְשָׁא עַרְסֵיהּ בִּימָמָא. וַיִּקַּח מֵאַבְנֵי הַמָּקוֹם וַיָּשֶׂם מֵרַאֲשׁוֹתָיו, הָכָא אוֹלִיפְנָא דַּאֲפִילוּ יְהוֹן לְמַלְכָּא עַרְסֵי דְדַהֲבָא וּלְבוּשֵׁי יְקָר לְמֵיבַת בְּהוּ וּמַטְרוֹנִיתָא תַּתְקֵין לֵיהּ עַרְסָא מִתְתַּקַּן בְּאַבְנִין, יִשְׁבּוֹק דִּילֵיהּ וְיָבֵית בַּמֶּה דְּאִיהִי תַּתְקִין דִּכְתִיב וַיִּשְׁכַּב בַּמָּקוֹם הַהוּא.","תָּא חֲזֵי, מַה כְּתִיב הָכָא וַיֹּאמֶר הָאָדָם זֹאת הַפַּעַם וְגו'. הָא בְּסִימוּ דְּמִלִּין לְאַמְשְׁכָא עִמָּהּ חֲבִיבוּתָא, וּלְאַמְשָׁכָא לָהּ (עמה) לִרְעוּתֵיהּ לְאַתְעָרָא עִמָּהּ רְחִימוּתָא. חָמֵי כַּמָּה בְּסִימִין אִנּוּן מִלִּין, כַּמָּה מִלֵּי דִרְחִימוּתָא אִנּוּן, עֶצֶם מֵעֲצָמַי וּבָשָׂר מִבְּשָׂרִי, בְּגִין לְאַחֲזָאָה לָהּ דְּאִנּוּן חַד וְלָא אִית פִּירוּדָא בֵּינַיְיהוּ בְּכֹלָּא.","הַשְׁתָּא שָׁרֵי לְשַׁבָּחָא לָהּ. לְזֹאת יִקָּרֵא אִשָּׁה דָּא הִיא דְּלָא יִשְׁתַּכַּח כַּוָּותָהּ. דָּא הִיא יְקָרָא דְּבֵיתָא כֻּלְּהוֹן נָשִׁין גַּבָּהּ כְּקוֹפָא בִּפְנֵי בְּנִי נָשָׁא. אֲבָל לְזֹאת יִקָּרֵא אִשָּׁה שְׁלִימוּ דְּכֹלָּא לְזֹאת וְלָא לְאַחֲרָא. כֹּלָּא הוּא מָלֵי רְחִימוּתָא כְּמָא דְאַתְּ אָמֵר, (משלי ל״א:כ״ט) רַבּוֹת בָּנוֹת עָשׂוּ חָיִל וְאַתְּ עָלִית עַל כֻּלָּנָה:","עַל כֵּן יַעֲזָב אִישׁ אֶת אָבִיו וְאֶת אִמּוֹ וְדָבַק בְּאִשְׁתּוֹ וְהָיוּ לְבָשָׂר אֶחָד, כֹּלָּא לְאַמְשָׁכָא לָהּ בִּרְחִימוּ וּלְאִתְדַּבְּקָא בַּהֲדָהּ, כֵּיוָן דְּאִתְעַר לְגַבָּהּ כָּל מִלִּין אִלֵּין, מַה כְּתִיב וְהַנָּחָשׁ הָיָה עָרוּם וְגו'. הָא אִתְעַר יֵצֶר הָרָע לְאַחֲדָא בָּהּ בְּגִין לְקָשְׁרָא לָהּ בְּתִיאוּבְתָּא דְגוּפָא וּלְאַתְעָרָא לְגַבָּהּ מִלִּין אָחֳרָנִין דְּיֵצֶר הָרָע אִתְעַנַּג בְּהוּ.","עַד לְבָתַר מַה כְּתִיב וַתֵרֶא הָאִשָּׁה כִּי טוֹב הָעֵץ לְמַאֲכָל וְכִי תַאֲוָה הוּא לָעֵינַיִם וַתִּקַּח מִפִּרְיוֹ וַתֹּאכַל, קְבֵילַת לֵיהּ בִּרְעוּתָא וַתִּתֵּן גַּם לְאִישָׁהּ עִמָּהּ (ויאכל) הָא כְּדֵין הִיא אִתְעֲרָא לְגַבֵּיהּ בְּתִיאוּבְתָּא (נ\"א בתאובתא) לְאַתְעָרָא (נ\"א למיהב) לֵיהּ רְעוּתָא וּרְחִימוּ, דָּא מִלָּה לְאַחֲזָאָה עוֹבָדָא לִבְנֵי נָשָׁא כְּגַוְונָא דִלְעֵילָא.","אָמַר רַבִּי אֶלְעָזָר אִי הָכִי בְּמַאי נוֹקִים לֵיהּ לְעֵילָא יֵצֶר הָרָע דְּאָחִיד בָּהּ בְּנוּקְבָא, אָמַר לֵיהּ, הָא אִתְעֲרָא אִלֵּין לְעֵילָא וְאִלֵּין לְתַתָּא יֵצֶר טוֹב וְיֵצֶר רָע. יֵצֶר טוֹב מִיָּמִינָא וְיֵצֶר רָע מִשְׂמָאלָא, וּשְׂמָאלָא לְעֵילָא אָחִיד בְּנוּקְבָא לְקַשְׁרָא לָהּ כְּחֲדָא (נ\"א לאתקשרא ביה) בְּגוּפָא כְּמָא דְאַתְּ אָמֵר, (שיר השירים ב׳:ו׳) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וְגו', וְעַל דָּא מִלִּין אִתְפַּרְשָׁן לְעֵילָא וְתַתָּא עַד הָכָא, מִכָּאן וּלְהָלְאָה מִלִּין בְּזוּטְרָא (נ\"א בזוטא) דְּזִיפְתָא לִזְעִירֵיהּ דְּטִינְקִין לְפָרְשָׁא מִלָּה, וְהָא אִתְעָרוּ בֵּיהּ חַבְרַיָּיא.","רַבִּי שִׁמְעוֹן הֲוָה אָזִיל לִטְבֶרְיָה, וְהֲווּ עִמֵּיהּ רַבִּי יוֹסֵי וְרַבִּי יְהוּדָה וְרַבִּי חִיָּיא. אַדְּהָכִי חָמוּ לֵיהּ לְרַבִּי פִּנְחָס דְּהֲוָה אָתֵי. כֵּיוָן דְּאִתְחַבָּרוּ כְּחֲדָא, נַחֲתוּ וְיָתְבוּ תְּחוֹת אִילָנָא חַד מֵאִילָנֵי טוּרָא. אָמַר רַבִּי פִּנְחָס הָא יָתִיבְנָא, מֵאִלֵּין מִלֵּי מַעַלְיָיתָא דְּאַתְּ אָמֵר בְּכָל יוֹמָא בְּעֵינָא לְמִשְׁמַע.","פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר (בראשית י״ג:ג׳) וַיֵּלֶךְ לְמַסָּעָיו מִנֶּגֶב וְעַד בֵּית אֵל עַד הַמָּקוֹם אֲשֶׁר הָיָה שָׁם אָהֳלֹה בַּתְּחִלָּה בֵּין בֵּית אֵל וּבֵין הָעָי. וַיֵּלֶךְ לְמַסָּעָיו, לְמַסָּעוֹ מִבָּעֵי לֵיהּ. מַאי לְמַסָּעָיו. אֶלָּא תְּרֵין מַטְלָנִין אִנּוּן. חַד דִּידֵיהּ וְחַד דִּשְׁכִינְתָּא. דְּהָא כָּל בַּר נָשׁ בָּעֵי לְאִשְׁתַּכְּחָא דְּכַר וְנוּקְבָא בְּגִין לְאַתְקָפָא מְהֵימְנוּתָא. וּכְדֵין שְׁכִינְתָּא לָא אִתְפָּרְשָׁא מִנֵּיהּ לְעָלְמִין.","וְאִי תֵימָא מָאן דְּנָפִיק לְאוֹרְחָא דְּלָא אִשְׁתְּכַח דְּכַר וְנוּקְבָא, שְׁכִינְתָּא אִתְפָּרְשָׁא מִנִּיהּ. תָּא חֲזֵי, הַאי מַאן דְּנָפִיק לְאָרְחָא (קסח א) יְסַדֵּר צְלוֹתָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא. בְּגִין לְאַמְשָׁכָא עֲלֵיהּ שְׁכִינְתָּא דְּמָרֵיהּ עַד לָא יִפּוּק לְאָרְחָא בְּזִמְנָא דְּאִשְׁתְּכַח דְּכַר וְנוּקְבָא. כֵּיוָן דְּסַדַּר צְלוֹתֵיהּ וְשִׁבְחֵיהּ וּשְׁכִינְתָּא שָׁרְיָיא עֲלֵיהּ יִפּוּק. דְּהָא שְׁכִינְתָּא אִזְדַּוְוגַת בַּהֲדֵיהּ. בְּגִין דְּיִשְׁתְּכַח דְּכַר וְנוּקְבָא. דְּכַר וְנוּקְבָא בְּמָתָא. דְּכַר וְנוּקְבָא בְּחַקְלָא. הֲדָא הוּא דִכְתִיב, (תהילים פ״ה:י״ד) צֶדֶק לְפָנָיו יְהַלֵּךְ וְיָשֵׂם לְדֶרֶךְ פְּעָמָיו."],[[0,"וילן שם כי בא השמש. לאחזאה דאסיר ליה לבר נש לשמשא ערסיה ביממא:","וילן שם כי בא השמש הוא להורות שאסור לו לאדם לשמש מטחו ביום. פירוש. כי \u0003ויפגע במקום\u0004 פירושו שהמשיך הארת השמאל, הנק' פיוסא (כנ\"ל בדיבור הסמוך) ונודע שבעת הארת השמאל נחשכת הנוקבא ונעשית בסוד אספקלריא שאינה מאירה, שמטעם חוסר חסדים אינה יכולה לקבל אפילו אור החכמה, וע\"כ \u0003וילן שם כי בא השמש,\u0004 כי עם המשכת הארת השמאל נסתלק תכף אור היום ונחשך הלילה. וז\"ש \u0003לאחזאה דאסיר\u0004 וכו', כי קודם הזווג צריכים לסוד פיוסא, שהוא המשכת הארת השמאל, ואין הארת השמאל נוהג ביום. כי עם הופעת הארת השמאל מסתלק תכף אור היום ונעשה חשכת לילה. וזסו\"ה ותקם בעוד לילה וגו'. באופן שהמשמש ביום אי אפשר לו להמשיך את הפיוסא. ובלי פיוסא אסור הזווג."],[0,"ויקח מאבני המקום הכא אוליפנא דאפילו יהון למלכא ערסי דדהבא ולבושי יקר למיבת בהו:","ויקח מאבני המקום וגו' מכאן למדנו, שאפילו יהיה למלך מטות זהב ולבושי כבוד, ללון בהם, \u0003ומתרוניתא תתקין ליה ערסא מתתקן באבנין, ישבוק דיליה ויבית במה דאיהי תתקין, דכתיב וישכב במקום ההוא,\u0004 והמטרוניתא הכינה לו מטה העשויה מאבנים. יעזב את שלו וילן במה שהיא הכינה לו, דכתיב וישכב במקום ההוא, היינו בהאבנים. פירוש אע\"פ שיש לז\"א מוחין שלמים בעטרה שעטרה לו אמו, כלולים מימין ושמאל, בפני עצמו, מ\"מ כדי להזדווג עם הנוקבא עוזב בחינת עצמו ומזדווג עמה בבחינתה. והטעם הוא, משום \u0003דביתא דידה הוא,\u0004 כנ\"ל דף קל\"ה אות רי\"ד ע\"ש בהסולם."],[1,"ת\"ח מה כתיב הכא, ויאמר האדם זאת הפעם וגו' הא בסימו דמלין לאמשכא עמה חביבותא:","בוא וראה, מה כתוב כאן, ויאמר האדם וגו', הנה זה דברי מתיקות להמשיך אהבה עמה, \u0003ולאמשכא לה לרעותיה לאתערא עמה רחימותא.\u0004 ולהמשיכה לרצונו לעורר אצלה אהבה. \u0003חמי כמה בסימין אינון מלין, כמה מלי דרחימותא אינון, עצם מעצמי ובשר מבשרי\u0004 ראה כמה ערבים הם דברים אלו, כמה מעוררי אהבה הם, אלו המלות, עצם מעצמי בשר מבשרי, \u0003בגין לאחזאה לה דאינון חד ולא אית פרודא בינייהו בכלא,\u0004 כדי להראות לה שהם אחד ואין ביניהם שום פירוד."],[1,"","פירוש ד' בחינות הן בהמוחין, הנקראות עצמות גידין בשר ועור, שהם חו\"ב תו\"מ, ומתחלקים לימין ושמאל, אשר חכמה ות\"ת הוא לימין, ובינה ומלכות הוא לשמאל. ומטרם הזווג היה לה להנוקבא רק צד שמאל של המוחין שהם בינה ומלכות, הנבחנים לגידין ועור של המוחין. וע\"י הזווג קנתה מז\"א הצד ימין שהם חכמה ות\"ת. וז\"ש \u0003זאת הפעם\u0004 דהיינו ע\"י זווג של עתה, נעשית הנוקבא \u0003עצם מעצמי ובשר מבשרי,\u0004 כי השיגה ממנו גם צד הימין הנק' עצם ובשר, שהם חכמה ות\"ת, ואז כשהיא כלולה בחו\"ב תו\"מ כמו הז\"א נעשית עמו אחד בלי פירוד."],[2,"השתא שרי לשבחא לה לזאת יקרא אשה דא היא דלא ישתכח כוותה דא היא יקרא דביתא,","עתה חתחיל לשבח אותה, לזאת יקרא אשה שהמשמעות היא, זו היא שאין עוד כמותה, זו היא הכבוד של הבית. \u0003כלהון נשין גבה כקופא בפני בני נשא אבל לזאת יקרא אשה, שלימו דכלא, לזאת ולא לאחרא\u0004 כל הנשים בפניה הן כקוף בפני אדם, אבל לזאת יקרא אשה, לזאת ולא לאחרת. פירוש כי השם אשה יורה אש ה', דהיינו שלימות הארת שמאל שנקרא א\"ש, הקשורה באות ה', שהיא הנוקבא. וזהו ששיבח אותה לזאת יקרא אשה, כי מסבת הארת החכמה המאירה בה אחר שנכללה בהחסדים של בעלה, ניתן לה השם אשה, שה\"ס הארת החכמה המכונה, אש, בסו\"ה והיה אור ה' לאש. וז\"ש לעיל בסוד השם אש\"ה כי \u0003אש קטיר בה'.\u0004 וז\"ש \u0003דא היא דלא ישתכח כוותה,\u0004 כי הארת החכמה אינה מגולה בשום מדרגה זולתה, (כנ\"ל באות רי\"ד) וז\"ש \u0003אשה, שלימו דכלא, לזאת ולא לאחרא,\u0004 כי אחרת אינו נקראת אש\"ה כי הארת החכמה אינה באחרת. וז\"ש \u0003כלא הוא מלי רחימותא כד\"א רבות בנות עשו חיל\u0004 וגו', הכל הוא דפניי אהבה, כמ\"ש רבות בנות וגו'. פירוש כי הנוקבא דז\"א היא דרגא אחרונה שבאצילות ומ\"מ אין גילוי החכמה בשום מדרגה זולתה, אע\"פ שהם עליונות ממנה כמ\"ש לעיל (בראשית א' דף רע\"ח אות שמ\"ד) \u0003עזקא דא בתרייתא אתעבידת ראשית,\u0004 וזשה\"כ רבות בנות עשו חיל, ואע\"פ שהן עליונות ממנה, מ\"מ ואת עלית על כלנה, כי בה מתגלה הארת החכמה ונעשית \u0003ראשית,\u0004 כמ\"ש שם."],[3,"ע\"כ יעזוב איש את אביו וגו', כלא לאמשכא לה ברחימו ולאתדבקא בהדה:","על כן יעזוב וגו' כל זה הוא כדי להמשיכה באהבה ולהדבק בה. \u0003כיון דאתער לגבה כל מלין אלין, מה כתיב, והנחש היה ערום\u0004 וגו' כיון שנתעורר אליה בכל הדברים האלה, מה כתוב, והנחש היה ערום, \u0003הא אתער יצה\"ר לאחדא בה, בגין לקשרא לה בתיאובתא דגופא ולאתערא לגבה מלין אחרנין דיצה\"ר אתענג בהו,\u0004 כי היצה\"ר נתעורר להאחז בה, כדי לקשרה בתאות הגוף, ולעוררה לדברים אחרים שהיצה\"ר מתענג בהם."],[4,"עד לבתר מה כתיב, ותרא האשה כי טוב העץ למאכל וגו', קבילת ליה ברעותא:","עד שבאה למה שכתוב אח\"כ, ותרא האשה וגו' שקבלה את היצה\"ר ברצון ובתאוה, \u0003ותתן גם לאישה עמה, הא כדין היא אתערא לגביה בתיאובתא, לאתערא ליה רעותא ורחימו,\u0004 ותתן גם לאשה עמה, כי נתעוררה אז לבעלה בתאוה, להתעורר אליו ברצון ובאהבה, \u0003דא מלה לאחזאה עובדא לבני נשא כגוונא דלעילא,\u0004 דבר זה דהיינו הכתובים הללו, הוא להורות המעשה לבני אדם, כפי שהוא למעלה, דהיינו בזו\"ן העליונים. כלומר אע\"פ שהכתובים מדברים למטה באדם וחוה, מ\"מ רומזים בעיקר על זו\"ן העליונים, אשר בני אדם צריכים לכוון מעשיהם אליהם."],[5,"אר\"א, אי הכי במאי נוקים ליה לעילא יצה\"ר דאחיד בה בנוקבא,","אר\"א אם כן, שהכתובים מדברים בזו\"ן העליונים, במה נבאר למעלה, אשר היצה\"ר נתאחז בהנוקבא, כי ענין יצה\"ר ודאי אינו נוהג ח\"ו בהנוקבא של מעלה \u0003א\"ל הא אתערא, אלין לעילא ואלין לתתא,\u0004 א\"ל הרי הערתי, שאלו למעלה ואלו למטה, כלומר, שהדברים שלמעלה מכוונים להדברים שלמטה, שהם ענפיהם, כי אין לך דבר למטה שאין לו שורש למעלה, שמשם נמשך ומתגדל, \u0003יצר טוב ויצר רע, יצר טוב מימינא ויצר הרע משמאלא, ושמאלא לעילא אחיד ביה בגופא לאתקשרא ביה כחדא, כד\"א\u0004 וכו', (כצ\"ל עי' בחלופי גרסאות). יצר טוב ויצה\"ר, נמשכים ג\"כ משרשיהם מלעלה, שיצה\"ט נמשך מימין של מעלה, ויצה\"ר נמשך משמאל של מעלה. והשמאל של מעלה נאחז בו בהגוף, שהיא הנוקבא, להתקשר עמו כאחד, כמ\"ש שמאלו תחת לראשי וגו' ולפיכך כל המדובר כאן בביאור הכתובים בענין יצה\"ר, הכונה הוא לבחינת קו שמאל של מעלה שממנו נמשך היצה\"ר. \u0003ועל דא מלין אתפרשן לעילא ותתא עד הכא,\u0004 ולפיכך מבוארים עד כאן הכתובים הן למעלה בזו\"ן, והן למטה באדם וחוה. \u0003מכאן ולהלאה מלין בזוטרא דזיפתא לזעיריה דטינקין לפרשא מלה.\u0004 מכאן ואילך מכוסים הדברים במעט זפת, כלומר שלא קשה לפענח אותם איך הם נוהגים למעלה, ואפילו קטן שבתנוקות יוכל לבאר הדבר."],[6,"ר\"ש הוה אזיל לטבריה והוו עמיה רבי יוסי ור' יהודה ור' חייא, אדהכי המו ליה לר' פנחס דהוה אתי:","רבי שמעון הלך לטבריה, והיה עמו ר' יוסי ור' יהודה ור' חייא, בינתים ראו את רבי פנחס בא אליהם. \u0003כיון דאתחברו כחדא, נחתו ויתבו תחות אלנא חד מאלנא טורא,\u0004 כיון שנתחברו יחד, ירדו מחמוריהם, וישבו תחת אילן אחד מאילני ההר. \u0003אר\"פ, הא יתיבנא, מאלין מלי מעלייתא דאת אמר בכל יומא בעינא למשמע,\u0004 אר\"פ: הנה ישבנו, כלומר שמוכנים אנחנו לשמוע דברי תורה, מאלו דברים טובים שאתה אומר בכל יום אני רוצה לשמוע."],[7,"פתח ר\"ש ואמר, וילך למסעיו מנגב וגו' וילך למסעיו למסעו מבעי ליה מאי למסעיו","פתח ר\"ש ואמר, כתיב וילך למסעיו שהוא לשון רבים היה צריך לומר למסעו, לשון יחיד, למה אומר למסעיו לשון רבים. \u0003אלא תרין מטלנין אינון חד דידיה וחד דשכינתא,\u0004 אלא שני מסעות הם, א' מסעו עצמו, ב' מסע השכינה. \u0003דהא כל בר נש בעי לאשתכחא דכר ונוקבא בגין לאתקפא מהימנותא, וכדין שכינתא לא אתפרשא מניה לעלמין,\u0004 שהרי כל אדם צריך להמצא תמיד זכר ונקבה, כדי לחזק האמונה, ואז אין השכינה מסתלקת ממנו לעולם."],[8,"ואי תימא, מאן דנפיק לאורחא דלא אשתכח דכר ונוקבא, שכינתא אתפרשא מניה:","ואם תאמר, מי שיצא לדרך, שאינו נמצא אז בזכר ונקבה, השכינה מסתלקת הימנו. \u0003ת\"ח האי מאן דנפיק לארחא, יסדר צלותא קמי קב\"ה בגין לאמשכא עליה שכינתא דמאריה עד לא יפוק לארחא, בזמנא דאשתכח דכר ונוקבא,\u0004 בוא וראה, כל מי שיוצא לדרך יסדר תפלתו לפני הקב\"ה טרם שיוצא לדרך, כדי להמשיך על עצמו שכינת רבונו בעודו בבית, כל עוד שנמצא בזכר ונקבה. \u0003כיון דסדר צלותיה ושבחיה, ושכינתא שרייא עליה, יפוק,\u0004 כיון שסידר תפלתו ותשבחותיו, והשכינה שורה עליו, יצא לדרך, \u0003דהא שכינתא אזדווגת בהדיה, בגין דישתכח דכר ונוקבא, דכר ונוקבא במתא דכר ונוקבא בחקלא הה\"ד\u0004 וכו', שהרי השכינה נתחברה עמו, כדי שימצא זכר ונקבה בעיר, דהיינו בביתו, וזכר ונקבה בשדה, ביציאתו לדרך. כי השכינה נתחברה עמו. וז\"ש צדק לפניו יהלך, דהיינו השכינה הנקראת צדק, ואז, וישם לדרך פעמיו."]],[[0,"","וַיָּלֶן שָׁם כִּי בָא הַשֶּׁמֶשׁ, לְהַרְאוֹת שֶׁאָסוּר לוֹ לָאָדָם לְשַׁמֵּשׁ מִטָּתוֹ בַּיּוֹם. וַיִּקַּח מֵאַבְנֵי הַמָּקוֹם וַיָּשֶׂם מְרַאֲשּתָיו, כָּאן לָמַדְנוּ שֶׁאֲפִלּוּ יִהְיוּ לַמֶּלֶךְ מִטּוֹת זָהָב וּלְבוּשֵׁי כָבוֹד לָלוּן בָּהֶם, וְהַמַּלְכָּה תַּתְקִין לוֹ מִטָּה מְתֻקֶּנֶת מֵאֲבָנִים - יַעֲזֹב אֶת שֶׁלּוֹ וְיָלוּן בְּמַה שֶּׁהִיא תַתְקִין, שֶׁכָּתוּב וַיִּשְׁכַּב בַּמָּקוֹם הַהוּא."],[1,"","בֹּא רְאֵה מַה כָּתוּב כָּאן, וַיֹּאמֶר הָאָדָם זֹאת הַפַּעַם וְגוֹ'. הֲרֵי עֲרֵבוּת שֶׁל הַדְּבָרִים לְהַמְשִׁיךְ עִמָּהּ חֲבִיבוּת וּלְהַמְשִׁיךְ אוֹתָהּ (עמה) לִרְצוֹנוֹ לְעוֹרֵר עִמָּהּ אַהֲבָה. רְאֵה כַּמָּה עֲרֵבִים אוֹתָם דְּבָרִים, כַּמָּה דִּבְרֵי אַהֲבָה הֵם, עֶצֶם מֵעֲצָמַי וּבָשָׂר מִבְּשָׂרִי, כְּדֵי לְהַרְאוֹת לָהּ שֶׁהֵם אֶחָד וְאֵין פֵּרוּד בֵּינֵיהֶם בַּכֹּל."],[2,"","עֵכְשָׁו מַתְחִיל לְשַׁבֵּחַ אוֹתָהּ - לְזאת יִקָּרֵא אִשָּׁה. זוֹ הִיא שֶׁלֹּא יִמְצָא כְמוֹתָהּ, זוֹהִי כְּבוֹד הַבַּיִת, כָּל הַנָּשִׁים לְפָנֶיהָ כְּקוֹף בִּפְנֵי אָדָם. אֲבָל לְזאת יִקָּרֵא אִשָּׁה - שְׁלֵמוּת הַכֹּל. לְזֹאת וְלֹא לְאַחֶרֶת. הַכֹּל הוּא דִּבְרֵי אַהֲבָה, כְּמוֹ שֶׁנֶּאֱמַר (משלי לא) רַבּוֹת בָּנוֹת עָשׂוּ חָיִל וְאַתְּ עָלִית עַל כֻּלָּנָה."],[3,"","עַל כֵּן יַעֲזָב אִישׁ אֶת אָבִיו וְאֶת אִמּוֹ וְדָבַק בְּאִשְׁתּוֹ וְהָיוּ לְבָשָׂר אֶחָד, הַכֹּל לְהַמְשִׁיכָהּ בְּאַהֲבָה וּלְהִדָּבֵק עִמָּהּ. כֵּיוָן שֶׁעוֹרֵר אֵלֶיהָ כָּל הַדְּבָרִים הַלָּלוּ, מַה כָּתוּב? וְהַנָּחָשׁ הָיָה עָרוּם וְגוֹ'. הֲרֵי הִתְעוֹרֵר יֵצֶר הָרָע לֶאֱחֹז בָּהּ כְּדֵי לְקָשְׁרָהּ בְּתַאֲוַת הַגּוּף וּלְעוֹרֵר אֵלֶיהָ דְּבָרִים אֲחֵרִים שֶׁיֵּצֶר הָרָע מִתְעַנֵּג בָּהֶם."],[4,"","עַד שֶׁלְּאַחַר כָּךְ מַה כָּתוּב, וַתֵּרֶא הָאִשָּׁה כִּי טוֹב הָעֵץ לְמַאֲכָל וְכִי תַאֲוָה הוּא לָעֵינַיִם, וַתִּקַּח מִפִּרְיוֹ וַתֹּאכַל. קִבְּלָה אוֹתוֹ בְּרָצוֹן, וַתִּתֵּן גַּם לְאִישָׁהּ עִמָּהּ (ויאכל). הֲרֵי אָז הִיא הִתְעוֹרְרָה אֵלָיו בְּתַאֲוָה לְהִתְעוֹרֵר (לתת) לוֹ רָצוֹן וְאַהֲבָה, זֶה דָּבָר לְהַרְאוֹת מַעֲשֶׂה לִבְנֵי אָדָם כְּמוֹ שֶׁלְּמַעְלָה."],[5,"","אָמַר רַבִּי אֶלְעָזָר, אִם כָּךְ, בַּמֶּה נַעֲמִיד אוֹתוֹ לְמַעְלָה יֵצֶר הָרָע שֶׁאוֹחֵז בִּנְקֵבָה? אָמַר לוֹ, הֲרֵי הִתְעוֹרְרוּ אֵלּוּ לְמַעְלָה וְאֵלּוּ לְמַטָּה, יֵצֶר טוֹב וְיֵצֶר רַע. יֵצֶר טוֹב מִיָּמִין, וְיֵצֶר רַע מִשְּׂמֹאל. וּשְׂמֹאל לְמַעְלָה אוֹחֵז בַּנְּקֵבָה לְקָשְׁרָהּ (להתקשר בה) כְּאֶחָד בַּגּוּף, כְּמוֹ שֶׁנֶּאֱמַר (שיר ב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי. וְעַל זֶה דְּבָרִים הִתְפָּרְשׁוּ לְמַעְלָה וּלְמַטָּה עַד כָּאן. מִכָּאן וָהָלְאָה מִלִּים שֶׁל קַטְנוּת (נ\"א: בשרף) שֶׁל זֶפֶת לִקְטַנִּים שֶׁבָּעֲרִיסוֹת לְפָרֵשׁ הַדָּבָר, וַהֲרֵי נִתְעוֹרְרוּ בוֹ הַחֲבֵרִים."],[6,"","רַבִּי שִׁמְעוֹן הָיָה הוֹלֵךְ לִטְבֶרְיָה, וְהָיוּ עִמּוֹ רַבִּי יוֹסֵי וְרַבִּי יְהוּדָה וְרַבִּי חִיָּיא. בֵּין כָּךְ רָאוּ אֶת רַבִּי פִּנְחָס שֶׁהָיָה בָּא. כֵּיוָן שֶׁהִתְחַבְּרוּ כְּאֶחָד, יָרְדוּ וְיָשְׁבוּ תַּחַת אִילָן אֶחָד מֵאִילָנֵי הָהָר. אָמַר רַבִּי פִּנְחָס, הֲרֵי יָשַׁבְנוּ, מֵאוֹתָם דְּבָרִים מְעֻלִּים שֶׁאַתָּה אוֹמֵר בְּכָל יוֹם אָנוּ רוֹצִים לִשְׁמֹעַ."],[7,"","פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (בראשית יג) וַיֵּלֶךְ לְמַסָּעָיו מִנֶּגֶב וְעַד בֵּית אֵל עַד הַמָּקוֹם אֲשֶׁר הָיָה שָׁם אָהֳלֹה בַּתְּחִלָּה בֵּין בֵּית אֵל וּבֵין הָעָי. וַיֵּלֶךְ לְמַסָּעָיו? לְמַסָּעוֹ צָרִיךְ לִהְיוֹת! מַה זֶּה לְמַסָּעָיו? אֶלָּא שְׁנֵי מַסָּעוֹת הֵם, אֶחָד שֶׁלּוֹ וְאֶחָד שֶׁל הַשְּׁכִינָה, שֶׁהֲרֵי כָּל בֶּן אָדָם צָרִיךְ לְהִמָּצֵא זָכָר וּנְקֵבָה כְּדֵי לְחַזֵּק הָאֱמוּנָה, וְאָז הַשְּׁכִינָה לֹא נִפְרֶדֶת מִמֶּנּוּ לְעוֹלָמִים."],[8,"","וְאִם תֹּאמַר, מִי שֶׁיּוֹצֵא לַדֶּרֶךְ שֶׁלֹּא נִמְצָא זָכָר וּנְקֵבָה, הַשְּׁכִינָה נִפְרֶדֶת מִמֶּנּוּ? בּא רְאֵה, מִי שֶׁיּוֹצֵא לַדֶּרֶךְ יְסַדֵּר תְּפִלָּה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּדֵי לְהַמְשִׁיךְ עָלָיו שְׁכִינַת רִבּוֹנוֹ עַד שֶׁלֹּא יֵצֵא לַדֶּרֶךְ, בִּזְמַן שֶׁנִּמְצָא זָכָר וּנְקֵבָה. כֵּיוָן שֶׁסִּדֵּר תְּפִלָּתוֹ וּשְׁבָחָיו וּשְׁכִינָה שׁוֹרָה עָלָיו - יֵצֵא, שֶׁהֲרֵי הַשְּׁכִינָה הִזְדַּוְּגָה עִמּוֹ, כְּדֵי שֶׁיִּמָּצֵא זָכָר וּנְקֵבָה. זָכָר וּנְקֵבָה בָּעִיר, זָכָר וּנְקֵבָה בַּשָּׂדֶה. זֶהוּ שֶׁכָּתוּב (תהלים פה) צֶדֶק לְפָנָיו יְהַלֵּךְ וְיָשֵׂם לְדֶרֶךְ פְּעָמָיו."]]],[["תָּא חֲזֵי, כָּל זִמְנָא דְּבַר נָשׁ אִתְעַכַּב בְּאוֹרְחָא (בכל חיליה) בָּעֵי לְנַטְרָא עוֹבָדוֹי. בְּגִין דְּזִוּוּגָא עִלָּאָה לָא יִתְפְּרַשׁ מִנֵּיהּ וְיִשְׁתְּכַח פָּגִים בְּלָא דְּכַר וְנוּקְבָא. בְּמָתָא אִצְטְרִיךְ כַּד נוּקְבֵיהּ עִמֵּיהּ, כָּל שְׁכֵּן הָכָא דְּזִוּוּגָא עִלָּאָה אִתְקַשְּׁרַת בֵּיהּ. וְלָא עוֹד אֶלָּא דְּהָא זִוּוּגָא עִלָּאָה נָטִיר לֵיהּ בְּאָרְחָא וְלָא מִתְפָּרְשָׁא מִנֵּיהּ עַד דְּיִתוֹב לְבֵיתֵיהּ.","בְּשַׁעֲתָא דְּעָאל לְבֵיתֵיהּ בָּעָא לְחַדְתָּא דְּבִיתְהוּ (ביתיה). בְּגִין דִּדְבִיתְהוּ גָּרְמָא לֵיהּ הַהוּא זִוּוּגָא עִלָּאָה. כֵּיוָן דְּאָתָא לְגַבָּהּ בָּעֵי לְחַדְתָּא לָהּ בְּגִין תְּרֵין גַּוְונֵי. חַד בְּגִין חֶדְוָתָא דְּהַהִיא זִוּוגָא חֶדְוָותָא דְמִצְוָה הִיא וְחֶדְוָותָא דְּמִצְוָה חֶדְוָותָא דִשְׁכִינְתָּא אִיהוּ.","וְלָא עוֹד אֶלָּא דְאַסְגֵי שָׁלוֹם סְתָם (לתתא) (נ\"א לאתתא) הֲדָא הוּא דִכְתִיב, (איוב ה׳:כ״ד) וְיָדַעְתָּ כִּי שָׁלוֹם אָהֳלֶךָ, וּפָקַדְתָּ נָוֶךָ וְלֹא תֶחטָא. וְכִי אִי לָא פָּקִיד לְאִתְּתֵיהּ חֵטְא אִיהוּ. הָכִי הוּא וַדַּאי. בְּגִין דְּגָרַע יְקַר זִוּוּגָא עִלָּאָה דְּאִזְדַּוְוגַת בֵּיהּ וּדְבִיתְהוּ גָּרְמָא לֵיהּ.","וְחַד דְּאִי מִתְעַבְּרָא אִתְּתֵיהּ זִוּוּגָא עִלָּאָה אֲרִיקַת בָּהּ נִשְׁמָתָא קַדִּישָׁא דְּהַאי בְּרִית אִקְרֵי בְּרִית דְּקוּדְשָׁא בְּרִיךְ הוּא. וְעַל דָּא בָּעֵי לְכַוְונָא בְּחֶדְוָותָא דָא כְּמָה דְבָעֵי בְּחֶדְוָותָא דְשַׁבָּת (דאנון חכימין) דְּאִיהוּ זִוּוּגָא דְחֲכִּימִין. וְעַל דָּא וְיָדַעְתָּ כִּי שָׁלוֹם אָהֳלֶךָ דְּהָא שְׁכִינְתָּא אַתְיָא עִמָּךְ וְשָׁרְיָא בְּבֵיתָךְ. וְעַל דָּא (איוב ה׳:כ״ד) וּפָקַדְתָּ נָוֶךָ וְלֹא תֶחטָא. מַאי וְלֹא תֶחטָא. לְשַׁמָּשָׁא קַמֵּי שְׁכִינְתָּא חֶדְוָותָא דְמִצְוָה.","כְּגַוְונָא דָא תַּלְמִידֵי חֲכָמִים דְּמִתְפָּרְשָׁן מִנְּשַׁיְיהוּ כָּל אִנּוּן יוֹמִין דְּשַׁבַּתָּא בְּגִין לְאִתְעַסְּקָא בְּאוֹרַיְיתָא. זִוּוּגָא עִלָּאָה אִזְדַּוַּוג בְּהוּ וְלָא מִתְפָּרְשָׁא מִנַּיְיהוּ בְּגִין דְּיִשְׁתְּכַח דְּכַר וְנוּקְבָא. כֵּיוָן דְּעָאל שַׁבָּת בָּעְיָין תַּלְמִידֵי חֲכָמִים לְחַדְתָּא לִדְבִיתְהוּ בְּגִין יְקַר זִוּוּגָא עִלָּאָה. וּלְכַוְּונָא לִבַּיְיהוּ בִּרְעוּתָא דְּמָארֵיהוֹן כְּמָה דְּאִתְּמָר.","כְּגַוְונָא דָא, הַאי מַאן דְּאִתְּתֵיהּ בְּיוֹמֵי מְסָאֲבוּ דִילָהּ וְנָטִיר לָהּ כְּדְקָא יְאוּת. כָּל אִנּוּן יוֹמִין זִוּוּגָא עִלָּאָה אִזְדַּוַּוג בַּהֲדֵיהּ דְּיִשְׁתְּכַח דְּכַר וְנוּקְבָא. כֵּיוָן דְּאִתְדְּכִיאַת אִתְּתֵיהּ בָּעֵי לְחַדְתָּא לָהּ חֶדְוָה דְמִצְוָה חֶדְוָה עִלָּאָה. וְכֻלְהוּ טַעֲמֵי דְּקָא אֲמָרָן בְּחַד דַּרְגָא סָלְקִין. סְתָמָא דְמִלָּה כָּל אִנּוּן בְּנִי מְהֵימְנוּתָא בָּעֳיָין לְכַוְּונָא לִבָּא וּרְעוּתָא בְּהַאי.","וְאִי תֵימָא אִי הָכִי שְׁבָחָא הוּא דְּבַר נָשׁ כַּד נָפִיק לְאָרְחָא יַתִּיר מִן בֵּיתֵיהּ בְּגִין זִוּוּגָא עִלָּאָה דְאִזְדַּוְוגַת בַּהֲדֵיהּ. תָּא חֲזֵי, בְּזִמְנָא דְבַר נָשׁ הוּא בְּבֵיתֵיהּ, עִקְּרָא דְּבֵיתָא דְּבִיתְהוּ. בְּגִין דִּשְׁכִינְתָא לָא אִתְעַדֵּי מִן בֵּיתָא בְּגִין דְּבִיתְהוּ. כְּמָה דְּתָנִינָן דִּכְתִיב, (בראשית כ״ד:ס״ז) וַיְבִיאֶהָ יִצְחָק הָאֹהלָה שָׂרָה אִמּוֹ, דִּשְׁרַגָּא אִתְדְּלָקַת, מַאי טַעְמָא בְּגִין דִּשְׁכִינְתָא אָתַת לְבֵיתָא.","רָזָא דְּמִלָּה אִמָּא עִלָּאָה לָא אִשְׁתַּכְּחַת גַּבֵּי דְכוּרָא אֶלָּא בְּזִמְנָא דְּאִתְתַּקְנַת בֵּיתָא וְאִתְחַבְּרוּ דְּכַר וְנוּקְבָא, כְּדֵין אִמָּא עִלָּאָה אֲרִיקַת בִּרְכָאן לִבָרוּכֵּי לוֹן. כְּגַוְונָא דָא אִמָּא תַּתָּאָה לָא אִשְׁתַּכְּחַת לְגַבֵּי דְכוּרָא אֶלָּא בְּזִמְנָא דְּאִתְתַּקְנַת בֵּיתָא וְאָתֵי דְכַר לְגַבָּהּ דְּנוּקְבֵיהּ וְאִתְחַבָּרוּ כְּחֲדָא כְּדֵין אִמָּא תַּתָּאָה אֲרִיקַת בִּרְכָאן לְבָרְכָא לוֹן.","וְעַל דָּא בִּתְרֵי נוּקְבִין אִתְעַטַּר דְּכוּרָא בְּבֵיתֵיהּ כְּגַוְונָא דִּלְעֵילָא. וְהַיְינוּ רָזָא דִכְתִיב, (בראשית מ״ט:כ״ו) עַד תַּאֲוַת גִּבְעוֹת עוֹלָם. הַאי ע\"ד תִּיאוּבְתָּא דְּגִבְעוֹת עוֹלָם בֵּיהּ. נוּקְבָא עִלָּאָה לְאַתְקָנָא לֵיהּ וּלְאַעַטְּרָא לֵיהּ וּלְבָרְכָא לֵיהּ. נוּקְבָא תַּתָּאָה לְאִתְחַבְּרָא בֵּיהּ וּלְאִתְזְנָא מִנֵּיהּ.","וּכְגַוְונָא דָא לְתַתָּא כַּד דְּכוּרָא אִינְסִיב, תַּאֲוַת גִּבְעוֹת עוֹלָם לְגַבֵּיהּ וְאִתְעַטַּר בִּתְרֵי נוּקְבֵי חַד עִלָּאָה וְחַד תַּתָּאָה. עִלָּאָה לְאַרְקָא עֲלֵיהּ בִּרְכָאן. תַּתָּאָה לְאִתְזְנָא מִנֵּיהּ וּלְאִתְחַבְּרָא בַּהֲדֵיהּ. וּבַּר נָשׁ בְּבֵיתֵיהּ תַּאֲוַת גִּבְעוֹת עוֹלָם לְגַבֵּיהּ וְאִתְעַטַּר בְּהוּ.","כַּד נָפִיק בְּאָרְחָא לָאו הָכִי. אִימָּא עִלָּאָה אִתְחַבְּרַת בַּהֲדֵיהּ וְתַתָּאָה אִשְׁתְּאָרַת. כַּד תָּב לְבֵיתֵיהּ בָּעֵי לְאִתְעַטְּרָא בִּתְרֵי נוּקְבֵי כִּדְקָאֲמָרָן. אָמַר רַבִּי פִּנְחָס אֲפִילּוּ בִּקְלִיפֵּי סַנְפּוֹרֵי קִטְרָא לָא פַּתְחֵי עִטְּרָא קַמָּךְ."],[[0,"ת\"ח כל זמנא דבר נש אתעכב באורחא, בעי לנטרא עובדוי, בגין דזווגא עלאה לא יתפרש מניה, וישתכח פגים בלא דכר ונוקבא:","בוא וראה, כל זמן שהאדם שוהא בדרך, צריך לשמור מעשיו שלא יחטא, כדי שהזווג העליון לא יסתלק ממנו, דהיינו השכינה, וישאר פגום, כי לא יהיה זכר ונקבה. \u0003במתא אצטריך כד נוקביה עמיה כל שכן הכא דזווגא עלאה אתקשרת ביה,\u0004 גם בעיר צריך לשמור מעשיו כשהנוקבא שלו עמו, ומכל שכן כאן כשהוא בדרך, אשר זווג עליון, דהיינו השכינה, נתחברה בו. \u0003ולא עוד, אלא דהא זווגא עלאה נטיר ליה באורחא, ולא מתפרשא מניה עד דיתוב לביתיה,\u0004 ולא עוד, אלא שהזווג העליון, דהיינו השכינה, שומרת עליו בדרך ואינה עוזבת אותו עד שיחזור לביתו. ולפיכך ודאי צריך לשמור מעשיו שלא יגרום הסתלקות השכינה ממנו."],[1,"בשעתא דעאל לביתיה בעא לחדתא דביתהו, בגין דדביתהו גרמא ליה ההוא זווגא עלאה:","בשעה שבא לביתו, צריך לשמח את אשתו, משום שאשתו גרמה לו זווג העליון ההוא. כי ע\"י תפילת הדרך שהתפלל בעודו בביתו, שהיה בשלמות משום שהיה שרוי בדכר ונוקבא, זכה לזווג העליון בדרך, (כנ\"ל באות רכ\"ד) הרי שאשתו גרמה לו זווג העליון שבדרך, דהיינו השראת השכינה כנ\"ל."],[1,"כיון דאתא לגבה, בעא לחדתא לה בגין תרין גווני, חד בגין חדוותא, דההיא זווגא חדוותא דמצוה הוא:","כיון שבא אצלה, צריך לשמח אותה בשביל ב' טעמים, א' משום שמחת הזווג, כי זווג ההוא הוא שמחה של מצוה \u0003וחדוותא דמצוה חדוותא לשכינתא איהו,\u0004 ושמחת המצוה הוא שמחת השכינה."],[2,"ולא עוד, אלא דאסגי שלום סתם הה\"ד וידעת וגו' וכי אי לא פקיד לאתתיה חטא איהו, הכי הוא ודאי וכו' ודביתהו גרמא ליה.","ולא עוד, אלא שמרבה שלום בבית סתם, הה\"ד וידעת כי שלום אהלך ופקדת נוך ולא תחטא, ושואל, ואם אינו פוקד לאשתו, הכי הוא חטא, שהכתוב אומר, ופקדת נוך ולא תחטא. ומשיב, כן הוא ודאי, שהוא חטא, משום שגורע כבוד זווג העליון דהיינו השכינה שנזדווגה בו בדרך, שאשתו גרמה לו, ואם אינו מכיר טובה לה' הרי הוא מגלה דעתו, שזווג העליון אינו חשוב לו כל כך, ונמצא גורע כבודו."],[3,"וחד, דאי מתעברא אתתיה, זווגא עלאה אריקת בה נשמתא קדישא","וא' (היינו טעם ב' למה שצריך לשמח את אשתו) שאם אשתו מתעברת מאותו הזווג, הרי זווג העליון משפיע בה נשמה קדושה. \u0003דהאי ברית אקרי ברית דקב\"ה\u0004 כי ברית הזה, של זווג העליון המשפיע את הנשמה, הוא ברית של הקב\"ה, ונמצא שבפקידה זו שפוקד את אשתו גורם זווג קב\"ה ושכינתיה, \u0003ועל דא בעי לכוונא בחדוותא דא, כמה דבעי בחדוותא דשבת, דאיהו זווגא דחכימין,\u0004 ועל כן צריך לכוון בשמחה זו כמו שצריכים לכוון בהזווג של שבת, שהוא זווג של חכמים. כלומר, דקדושת הזווג הזה בביאתו מן הדרך, שוה לקדושת הזווג של ליל שבת. \u0003ועל דא וידעת כי שלום אהלך, דהא שכינתא אתיא עמך ושריא בביתך, וע\"ד ופקדת נוך וגו' מאי ולא תחטא, לשמשא קמי שכינתא חדוותא דמצוה,\u0004 וע\"כ אומר הכ' וידעת כי שלום אהלך, שהרי השכינה באה עמך ושורה בביתך. וע\"כ ופקדת נוך ולא תחטא ומה הפירוש, ולא תחטא, היינו שלא תחטא מלשמש לפני השכינה שמחה של מצוה. כלומר, שלא ימנע הזווג דקב\"ה ושכינתיה לארקא בו נשמתא, שהוא חטא גדול."],[4,"כגוונא דא תלמידי חכמים דמתפרשן מנשייהו כל אינון יומין דשבתא בגין לאתעסקא באורייתא:","על דרך זה הם התלמידי חכמים שנפרשים מנשותיהם כל ימות השבוע, כדי שלא יתבטלו מעסק התורה. \u0003זווגא עלאה אזדווג בהו ולא מתפרשא מנייהו בגין דישתכח דכר ונוקבא.\u0004 זווג העליון מזדווג בהם, והשכינה אינה מסתלקת מהם, כדי שיהיו זכר ונקבה. \u0003כיון דעאל שבת בעיין תלמידי חכמים לחדתא לדביתהו בגין יקר זווגא עלאה ולכוונא לבייהו ברעותא דמאריהון כמה דאתמר,\u0004 כיון שנכנס השבת, צריכים תלמידי חכמים לשמח לנשותיהם בשביל כבוד זווג העליון, כי גורמים זווג עליון להשפעת נשמות כנ\"ל, וצריכים לכוון לבם ברצון רבונם, כמו שאמרו."],[4,"","פירוש, כמו שנתבאר לעיל ב' דרכים בסתם בני אדם, שבהיותם בדרך הם אז בבחי' זווג העליון, ובביתם הם בבחינת זווג התחתון, כן נבחן אצל תלמידי חכמים אותם ב' הדרכים, אלא בהפרש מימות החול לשבת. שבימות החול שהם נפרשים מנשותיהם מסבת עסק התורה, הם אז כמו היוצא לדרך, דהיינו בזווג עליון, ובליל שבת דומים להחוזרים לבית, שפוקדים את אשתם וממשיכים נשמה עליונה מזווג קב\"ה ושכינתיה."],[5,"כגוונא דא, האי מאן דאתתיה ביומי מסאבו דילה, ונטיר לה כדקא יאות:","על דרך זה הוא, מי שאשתו בימי טומאה שלה, ושומר מצות נדה כראוי, \u0003כל אינון יומין, זווגא עלאה אזדווג בהדיה דישתכח דכר ונוקבא,\u0004 כל אותם הימים, זווג עליון מתחבר בו, כדי שיהיה זכר ונקבה. \u0003כיון דאתדכיאת אתתיה בעי לחדתא לה חדוה דמצוה חדוה עלאה,\u0004 כיון שנטהרה אשתו, צריך לשמחה בשמחת מצוה בשמחה עליונה. \u0003וכלהו טעמי דקאמרן בחד דרגא סלקין,\u0004 וכל אלו הטעמים שאמרנו עולים בקנה אחד. \u0003סתמא דמלה, כל אינון בני מהימנותא, בעיין לכוונא לבא ורעותא בהאי.\u0004 עיקר הדבר, הוא, כל אלו בני האמונה צריכים לכוון לבם ורצונם בזה."],[6,"ואי תימא, אי הכי שבחא הוא דבר נש כד נפיק לארחא, יתיר מן ביתיה, בגין זווגא עלאה דאזדווגת בהדיה:","ואם תאמר, ששבחו של האדם היוצא לדרך, חשוב יותר מכשהוא בביתו, משום זווג העליון המזדוג עמו, בהיותו בדרך."],[6,"ת\"ח, בזמנא דבר נש הוא בביתיה, עקרא דביתא דביתהו, בגין דשכינתא לא אתעדי מן ביתא בגין דביתהו,","בוא וראה, בעת שאדם הוא בביתו, עיקר הבית הוא אשתו, משום שהשכינה אינה מסתלקת מביתו בזכות אשתו. \u0003כמה דתנינן, דכתיב ויביאה יצחק האהלה שרה אמו, דשרגא אתדלקת, מ\"ט בגין דשכינתא אתת לביתא,\u0004 כמו שלמדנו, שכתוב ויביאה יצחק האהלה שרה אמו, שחזר ונדלק, הנר, כמו שהיה בזמן שרה אמו, משום שהשכינה באה לבית, בזכות רבקה. הרי שהשכינה שורה בבית בזכות אשתו."],[7,"רזא דמלה, אמא עלאה, לא אשתכחת גבי דכורא אלא בזמנא דאתתקנת ביתא ואתחברו דכר ונוקבא.","סוד הדבר הוא, כי אמא עלאה, בינה, אינה נמצאת אצל הדכר, דהיינו ז\"א, אלא בעת שהבית נתתקן. ונתחברו דכר ונוקבא, דהיינו זו\"ן. \u0003כדין אמא עלאה אריקת ברכאן לברוכי לון,\u0004 אז אמא עלאה משפעת ברכות לברך את זו\"ן. \u0003כגוונא דא אמא תתאה לא אשתכחת לגבי דכורא אלא בזמנא דאתתקנת ביתא,\u0004 כעין זה, אמא תתאה, דהיינו השכינה אינה נמצאת אצל הדכר, דהיינו באדם למטה, אלא בשעה שנתקן הבית, \u0003ואתי דכר לגבה דנוקביה ואתחברו כחדא,\u0004 והדכר בא אצלה להנוקבא ונתחברו יחד. \u0003כדין אמא תתאה אריקת ברכאן לברכא לון,\u0004 אז אמא תתאה, דהיינו השכינה, משפעת ברכות לברך אותם."],[8,"ועל דא, בתרי נוקבין אתעטר דכורא בביתיה כגוונא דלעילא, והיינו רזא דכתיב וכו',","וע\"כ בב' נוקבין מתעטר הדכר בביתו, כעין ז\"א של מעלה, והוא סוד שכתוב, עד תאות גבעות עולם, \u0003האי ע\"ד תיאובתא דגבעות עולם ביה, נוקבא עלאה לאתקנא ליה ולאעטרא ליה ולברכא ליה,\u0004 ע\"ד הזה, שבכתוב ע\"ד תאות גבעות עולם שה\"ס מוחין דעד\"ן העליון, תאותם של גבעות עולם בו, שהם ב' הנוקבין, הנקראות גבעות עולם, נוקבא העליונה, שהוא בינה, חושקת לתקן את הדכר, ולעטר אותו במוחין דג\"ר, ולברכו בחסדים. \u0003נוקבא תתאה לאתחברא ביה ולאתזנא מניה,\u0004 ונוקבא תתאה חושקת להתחבר בהדכר וליזון ממנו, מהמוחין דע\"ד. כלומר, בשביל שנוקבא תתאה חושקת להדכר לקבל המוחין דע\"ד, ע\"כ נוקבא עלאה, דהיינו אמא, חושקת להשפיע להדכר המוחין הללו. וע\"כ הדכר מתעטר ע\"י ב' נוקבין, כי לולא נוקבא תתאה הצריכה למוחין דע\"ד, שה\"ס מוחין דחכמה, לא היתה אמא עלאה משפעת המוחין הללו להדכר, כי הדכר אינו צריך להם אלא לחסדים מכוסים, כנודע."],[9,"וכגוונא דא לתתא, כד דכורא אנסיב תאות גבעות עולם לגביה,","וכעין זה שנתבאר בדכר של מעלה, הוא ג\"כ בדכר של מטה, באדם בעוה\"ז, כשהדכר נושא אשה, נמצאים אצלו תאות גבעות עולם, \u0003ואתעטר בתרי נוקבי חד עלאה וחד תתאה,\u0004 ואתעטר בב' נוקבין, הנקראות גבעות עולם (כנ\"ל בדיבור הסמוך) אחת עליונה, דהיינו השכינה, ואחת תחתונה, דהיינו אשתו. \u0003עלאה, לארקא עליה ברכאן. תתאה, לאתזנא מניה ולאתחברא בהדיה,\u0004 העליונה, שהיא השכינה, היא להשפיע לו ברכות. התחתונה, שהיא אשתו, היא ליזון ממנו ולהתחבר בו."],[10,"כד נפיק בארחא, לאו הכי, אמא עלאה אתחברת בהדיה, ותתאה אשתארת:","כשהוא יוצא לדרך אינו כן, שאינו מתעטר בב' נוקבין, אלא אמא עליונה, כלומר השכינה, מתחברת עמו בהיותו בדרך, והתחתונה, שהיא אשתו, נשארת בבית. \u0003כד תב לביתיה בעי לאתעטרא בב' נוקבי, כדקאמרן.\u0004 כשהוא חוזר לביתו צריך שוב להתעטר בב' נוקבין כמו שאמרנו. הרי שהיושב בביתו חשוב הרבה יותר מהיוצא לדרך. כי היושב בביתו מתעטר בב' נוקבין, בסו\"ה עד תאות גבעות עולם. משא\"כ היוצא לדרך, אין לו אלא נוקבא העליונה בלבדה. \u0003א\"ר פנחס, אפילו בקליפי סנפורי קטרא, לא פתחי עטרא קמך.\u0004 א\"ר פנחס לר\"ש, אפילו בסבך של קשקשת וסנפיר לא יפתחו פה להתעטר לפניך. כלומר אפילו בדברים פשוטים וקלים כשאלות בקשקשת וסנפיר שהם סימני טהרה דדגים, לא יעיז אדם לדבר לפניך. כי נתפלא על מאמרו העמוק שפירש, בענין היוצא לדרך, שהיה נראה לכאורה כדבר פשוט ומובן לכל אדם. קליפי, פירושו קשקשת. כי על קשקשת מתרגמינן קליפין (ויקרא י\"א). סנפורי, הוא סנפיר. קטרא, פירושו קשר וסבך כלומר, שאלה וספק שצריכים להתירו."]],[[0,"","בֹּא רְאֵה, כָּל זְמַן שֶׁבֶּן אָדָם מִתְעַכֵּב בַּדֶּרֶךְ, (בכל כחו) צָרִיךְ לִשְׁמֹר מַעֲשָׂיו כְּדֵי שֶׁהַזִּוּוּג הָעֶלְיוֹן לֹא יִפָּרֵד מִמֶּנּוּ, וְיִמָּצֵא פָגוּם בְּלִי זָכָר וּנְקֵבָה. בָּעִיר צָרִיךְ כְּשֶׁנְּקֵבָתוֹ עִמּוֹ, כָּל שֶׁכֵּן כָּאן שֶׁזִּוּוּג הָעֶלְיוֹן נִקְשָׁר בּוֹ. וְלֹא עוֹד, אֶלָּא שֶׁהַזִּוּוּג הָעֶלְיוֹן הַזֶּה שׁוֹמֵר אוֹתוֹ בַּדֶּרֶךְ וְלֹא נִפְרָד מִמֶּנּוּ עַד שֶׁיָּשׁוּב לְבֵיתוֹ."],[1,"","בְּשָׁעָה שֶׁנִּכְנָס לְבֵיתוֹ צָרִיךְ לְשַׂמֵּחַ אֶת אִשְׁתּוֹ (ביתו), מִשּׁוּם שֶׁאִשְׁתּוֹ גָּרְמָה לוֹ אוֹתוֹ זִוּוּג עֶלְיוֹן. כֵּיוָן שֶׁבָּא אֵלֶיהָ, צָרִיךְ לְשַׂמֵּחַ אוֹתָהּ מִשּׁוּם שְׁנֵי טְעָמִים. אֶחָד מִשּׁוּם חֶדְוַת אוֹתוֹ זִוּוּג, חֶדְוַת הַמִּצְוָה הִיא, וְחֶדְוַת הַמִּצְוָה חֶדְוַת הַשְּׁכִינָה הִיא."],[2,"","וְלֹא עוֹד, אֶלָּא שֶׁמַּרְבֶּה שָׁלוֹם סְתָם (למטה) (נ\"א: לאשה). זֶהוּ שֶׁכָּתוּב (איוב ה) וְיָדַעְתָּ כִּי שָׁלוֹם אָהֳלֶךְ וּפָקַדְתָּ נָוְךְ וְלֹא תֶחֱטָא. וְכִי אִם לֹא פוֹקֵד אֶת אִשְׁתּוֹ זֶה חֵטְא? כָּךְ זֶה בְּוַדַּאי! מִשּׁוּם שֶׁגּוֹרֵעַ כְּבוֹד זִוּוּג הָעֶלְיוֹן שֶׁהִזְדַּוְּגָה בּוֹ וְאִשְׁתּוֹ גָּרְמָה לוֹ."],[3,"","וְאֶחָד - שֶׁאִם אִשְׁתּוֹ מִתְעַבֶּרֶת, הַזִּוּוּג הָעֶלְיוֹן מֵרִיק בָּהּ נְשָׁמָה קְדוֹשָׁה, שֶׁהֲרֵי הַבְּרִית הַזּוֹ נִקְרֵאת בְּרִית הַקָּדוֹשׁ בָּרוּךְ הוּא. וְעַל זֶה צָרִיךְ לְכַוֵּן בְּחֶדְוָה זוֹ כְּמוֹ שֶׁצָּרִיךְ בְּחֶדְוַת הַשַּׁבָּת (של אותם חכמים), שֶׁהוּא זִוּוּג הַחֲכָמִים. וְעַל זֶה וְיָדַעְתָּ כִּי שָׁלוֹם אָהֳלֶךְ, שֶׁהֲרֵי הַשְּׁכִינָה בָּאָה עִמְּךְ וְשׁוֹרָה בְּבֵיתְךְ. וְעַל זֶה (שם) וּפָקַדְתָּ נָוְךְ וְלֹא תֶחֱטָא. מַה זֶּה וְלֹא תֶחֱטָא? לְשַׁמֵּשׁ לִפְנֵי הַשְּׁכִינָה חֶדְוַת הַמִּצְוָה."],[4,"","כְּמוֹ זֶה תַּלְמִידֵי חֲכָמִים שֶׁפּוֹרְשִׁים מִנְּשׁוֹתֵיהֶם כָּל אוֹתָם יְמֵי הַשָּׁבוּעַ כדי להתעסק בתורה, הזווג העליון נזדוג בהם ולא נפרד מהם כדי שימצא זכר ונקבה. כיון שנכנסת שבת, צריכים תלמידי חכמים לשמח את נשותיהם משום כבוד הזווג העליון, ולכון לבם ברצון רבונם כמו שנאמר."],[5,"","כְּמוֹ זֶה מִי שֶׁאִשְׁתּוֹ בִּימֵי טֻמְאָתָהּ וְשׁוֹמֵר אוֹתָהּ כָּרָאוּי, כָּל אוֹתָם הַיָּמִים הַזִּוּוּג הָעֶלְיוֹן מִזְדַּוֵּג עִמּוֹ שֶׁיִּמָּצֵא זָכָר וּנְקֵבָה. כֵּיוָן שֶׁאִשְׁתּוֹ נִטְהֶרֶת, צָרִיךְ לְשַׂמֵּחַ אוֹתָהּ שִׂמְחַת מִצְוָה חֶדְוָה עֶלְיוֹנָה. וְכָל הַטְּעָמִים שֶׁאָמַרְנוּ עוֹלִים בְּדַרְגָּה אַחַת. סְתָמוֹ שֶׁל דָּבָר - כָּל אוֹתָם בְּנֵי הָאֱמוּנָה צְרִיכִים לְכַוֵּן לֵב וְרָצוֹן בָּזֶה."],[6,"","וְאִם תֹּאמַר, אִם כָּךְ, שֶׁבַח הוּא שֶׁל הָאִישׁ כְּשֶׁיּוֹצֵא לַדֶּרֶךְ יוֹתֵר מֵאֲשֶׁר בְּבֵיתוֹ, מִשּׁוּם הַזִּוּוּג הָעֶלְיוֹן שֶׁמִּזְדַּוֶּגֶת עִמּוֹ - בֹּא רְאֵה, בִּזְמַן שֶׁבֶּן אָדָם הוּא בְּבֵיתוֹ, עִקַּר הַבַּיִת אִשְׁתּוֹ, מִשּׁוּם שֶׁשְּׁכִינָה לֹא זָזָה מֵהַבַּיִת מִשּׁוּם אִשְׁתּוֹ, כְּמוֹ שֶׁשָּׁנִינוּ, שֶׁכָּתוּב (בראשית כד) וַיְבִאֶהָ יִצְחָק הָאֹהֱלָה שָׂרָה אִמּוֹ, שֶׁנֵּר הִדְלִיקָה. מָה הַטַּעַם? מִשּׁוּם שֶׁהַשְּׁכִינָה בָּאָה לַבַּיִת."],[7,"","סוֹד הַדָּבָר - הָאֵם הָעֶלְיוֹנָה לֹא נִמְצֵאת אֵצֶל הַזָּכָר אֶלָּא בִּזְמַן שֶׁנִּתְקַן הַבַּיִת וְהִתְחַבְּרוּ זָכָר וּנְקֵבָה, וְאָז הָאֵם הָעֶלְיוֹנָה מוֹרִיקָה בְרָכוֹת כְּדֵי לְבָרֵךְ אוֹתָם. כְּמוֹ זֶה הָאֵם הַתַּחְתּוֹנָה לֹא נִמְצֵאת אֵצֶל הַזָּכָר אֶלָּא בִּזְמַן שֶׁהִתְתַּקֵּן הַבַּיִת, וּבָא הַזָּכָר לַנְּקֵבָה שֶׁלּוֹ וְהִתְחַבְּרוּ כְּאֶחָד. אָז הָאֵם הַתַּחְתּוֹנָה מוֹרִיקָה בְרָכוֹת לְבָרֵךְ אוֹתָם."],[8,"","וְעַל זֶה הַזָּכָר מִתְעַטֵּר בְּבֵיתוֹ בִּשְׁתֵּי נְקֵבוֹת כְּמוֹ שֶׁלְּמַעְלָה. וְזֶהוּ סוֹד הַכָּתוּב (שם מט) עַד תַּאֲוַת גִּבְעֹת עוֹלָם. הָעַ\"ד הַזֶּה, תַּאֲוַת שֶׁל גִּבְעוֹת עוֹלָם בּוֹ. נְקֵבָה עֶלְיוֹנָה לְתַקֵּן אוֹתוֹ וּלְעַטֵּר אוֹתוֹ וּלְבָרֵךְ אוֹתוֹ, נְקֵבָה הַתַּחְתּוֹנָה לְהִתְחַבֵּר בּוֹ וּלְהִזּוֹן מִמֶּנּוּ."],[9,"","וּכְמוֹ זֶה לְמַטָּה, כְּשֶׁזָּכָר נִשָּׂא, תַּאֲוַת גִּבְעוֹת עוֹלָם אֵלָיו, וּמִתְעַטֵּר בִּשְׁתֵּי נְקֵבוֹת - אַחַת עֶלְיוֹנָה וְאַחַת תַּחְתּוֹנָה. הָעֶלְיוֹנָה לְהוֹרִיק עָלָיו בְּרָכוֹת, וְהַתַּחְתּוֹנָה לְהִזּוֹן מִמֶּנּוּ וּלְהִתְחַבֵּר עִמּוֹ. וּבֶן אָדָם בְּבֵיתוֹ תַּאֲוַת גִּבְעוֹת עוֹלָם אֵלָיו וּמִתְעַטֵּר בָּהֶם."],[10,"","כְּשֶׁיּוֹצֵא לַדֶּרֶךְ לֹא כָּךְ. הָאֵם הָעֶלְיוֹנָה מִתְחַבֶּרֶת עִמּוֹ, וְהַתַּחְתּוֹנָה נִשְׁאֶרֶת. כְּשֶׁשָּׁב לְבֵיתוֹ, רוֹצֶה לְהִתְעַטֵּר בִּשְׁתֵּי נְקֵבוֹת כְּפִי שֶׁאָמַרְנוּ. אָמַר רַבִּי פִּנְחָס, אֲפִלּוּ בִּקְלִפּוֹת בְּקֶשֶׁר שֶׁל סַפִּירִים לֹא פוֹתְחִים פִּתְחוֹן לְפָנֶיךְ."]]],[["אָמַר רַבִּי שִׁמְעוֹן כְּגַוְונָא דָא אוֹרַיְיתָא קָאִים בֵּין תְּרֵי בָּתִּים, כְּמָה דִכְתִיב, (ישעיהו ח׳:י״ד) לִשְׁנֵי בָּתֵּי יִשְׂרָאֵל וְגו'. חַד סְתִימָא עִלָּאָה. וְחַד אִתְגַּלְיָא יַתִּיר. (סתימא) עִלָּאָה (דא) קוֹל גָּדוֹל דִּכְתִיב, (דברים ה׳:י״ט) קוֹל גָדוֹל וְלא יָסָף.","וְהַאי קוֹל פְּנִימָאָה אִיהוּ דְּלָא אִשְׁתְּמַע וְלָא אִתְגַּלְּיָא. וְדָא הוּא כַּד נְבִיעַ בֵּי גָרוֹן אַפִּיק (ביה) ה' בְּחֲשַׁאי וּנְבִיעַ תָּדִיר וְלָא פָּסַק. וְאִיהוּ דַּקָּה פְּנִימָאָה דְּלָא אִשְׁתְּמַע לְעָלְמִין.","וּמֵהָכָא נָפְקָא אוֹרַיְיתָא דְּאִיהוּ קוֹל יַעֲקֹב. וְהַאי אִשְׁתְּמַע (ד\"א דאשתמע) דְּנָפְקָא (ד\"א נפקא) מֵהַהִיא דְּלָא אִשְׁתְּמַע. וּלְבָתַר אִתְאַחִיד דִּבּוּר בַּהֲדֵיהּ וְנָפַק לְבַר מֵחֵילֵיהּ וּמִתָּקְפֵּיהּ. וְקוֹל דְּיַעֲקֹב דְּאִיהוּ אוֹרַיְיתָא אָחִיד בֵּין תְּרֵי נִקְבֵי. אָחִיד בְּהַאי פְּנִימָאָה דְּלָא אִשְׁתְּמַע. וְאָחִיד בְּהַאי דִלְבַר דְּאִשְׁתְּמַע.","תְּרֵין אִנּוּן דְּלָא אִשְׁתָּמְעוּ וּתְרֵין אִנּוּן דְּאִשְׁתָּמְעוּ. תְּרֵין דְּלָא אִשְׁתָּמְעוּ, דָּא הוּא חָכְמָה עִלָּאָה סְתִימָאָה דְּקָיְימָא בְּמַחֲשָׁבָה דְּלָא אִתְגַּלְיָא וְלָא אִשְׁתְּמַע. לְבָתַר נָפְקָא וְאִתְגַּלְּיָא זְעֵיר בַּחֲשַׁאי דְּלָא אִשְׁתְּמַע הַהוּא דְּאִקְרֵי קוֹל גָּדוֹל דְּהוּא דַּק וְנָפִיק בַּחֲשַׁאי.","תְּרֵין אִנּוּן דְּאִשְׁתָּמְעוּ, אִנּוּן דְּנָפְקֵי מֵהָכָא קוֹל דְּיַעֲקֹב וְדִבּוּר דְּאִתְאֲחִיד בַּהֲדֵיהּ. הַאי קוֹל גָּדוֹל דְּאִיהוּ בַּחֲשַׁאי וְלָא אִשְׁתְּמַע. אִיהִי בַּיִ\"ת לַחָכְמָה עִלָּאָה. וְכָל נוּקְבָא בַּיִ\"ת אִקְרֵי. וְהַאי דִּבּוּר בַּתְרָאָה אִיהוּ בַּיִת לַקּוֹל דְּיַעֲקֹב דְּאִיהוּ אוֹרַיְיתָא. וְעַל דָּא אוֹרַיְיתָא שַׁרְיָא בְּבֵי\"ת. בֵּי\"ת רֵאשִׁית.","פַּתַח וְאָמַר בְּרֵאשִׁית בָּרָא אֱלֹהִים, הַיְינוּ דִכְתִיב וַיִּבֶן יְיָ אֱלֹהִים אֶת הַצֵּלָע. אֶת הַשָּׁמַיִם הַיְינוּ דִכְתִיב וַיְבִיאֶהָ אֶל הָאָדָם. וְאֶת הָאָרֶץ כְּמָא דְאַתְּ אָמֵר וְעֶצֶם מֵעֲצָמַי. וַדַּאי הַאי אִיהִי אֶרֶץ הַחַיִּים.","תּוּ פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר (תהלים ק) נְאֻם יְיָ לַאדוֹנִי שֵׁב לִימִינִי עַד אָשִׁית אוֹיְבֶיךָ הֲדוֹם לְרַגְלֶיךָ. נְאֻם יְיָ לַאדוֹנִי, דַּרְגָּא עִלָּאָה לְדַרְגָּא תַּתָּאָה קָאָמַר שֵׁב לִימִינִי, לְאִתְקַשְּׁרָא מַעֲרָבִית בִּדְרוֹמִית שְׂמָאלָא בְּיָמִינָא. בְּגִין לְתַבְּרָא חֵילֵיהוֹן דִּשְׁאָר עַמִין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת. נְאֻם יְיָ לַאדוֹנִי, נְאֻם יְיָ דָּא יַעֲקֹב. לַאֲדוֹנִי דָּא (יהושע ג׳:י״א) אֲרוֹן הַבְּרִית אֲדוֹן כָּל הָאָרֶץ.","דָּבָר אַחֵר נְאֻם יְיָ דָּא יוֹבְלָא. לַאֲדוֹנִי דָּא שְׁמִיטָה. דִּכְתִיב בָּהּ (שמות כ״א:ה׳) אָהַבְתִּי אֶת אֲדוֹנִי. שֵׁב לִימִינִי דְּהָא יְמִינָא בְּיוֹבְלָא שָׁרְיָא. וּשְׁמִיטָה בָּעֵי לְאִתְקַשְּׁרָא בְּיָמִינָא.","תָּא חֲזֵי, שְׁמִיטָה דָא לָא אִתְקְשַׁר בְּקִיּוּמָא שְׁלִים בְּיָמִינָא ובִשְׂמָאלָא מִיּוֹמָא דְּאִשְׁתַּכְּחַת, כַּד בָּעְיָא לְאִתְקַשְּׁרָא אוֹשִׁיט דְּרוֹעָא שְׂמָאלָא לְקֳבְלָהּ וּבָרָא עָלְמָא דֵין. וּבְגִין דְּהוּא מִסִּטְרָא דִּשְׂמָאלָא לֵית בֵּיהּ קִיּוּמָא עַד זִמְנָא דְּאֶלֶף שְׁבִיעָאָה. דִּבְהַהוּא יוֹמָא לְחוּד אִתְקַשַּׁר כְּדֵין בְּיָמִינָא. וּכְדֵין תֶּהוֵי בֵּין יָמִינָא וּשְׂמָאלָא בְּקִיּוּמָא שְׁלִים וְיִשְׁתַּכְּחוּן שָׁמַיִם חֲדָשִׁים וְאֶרֶץ חֲדָשָׁה וּכְדֵין לָא תַעֲדֵי מִתַּמָּן לְעָלְמִין.","אִי הָכִי בְּמַאי נוֹקִים שֵׁב לִימִינִי. אֶלָּא עַד זִמְנָא יְדִיעָא דִּכְתִיב עַד אָשִׁית אוֹיְבֶיךָ הֲדוֹם לְרַגְלֶיךָ וְלָא תָדִיר. אֲבָל בְּהַהוּא זִמְנָא לָא תַעֲדֵי מִתַּמָּן לְעָלְמִין דִּכְתִיב, (ישעיהו נ״ד:ג׳) כִּי יָמִין וּשְׂמֹאל תִּפְרוֹצִי לְמֶהוֵי כֹּלָּא חַד.","תָּא חֲזֵי, אֶת הַשָּׁמַיִם דָּא שְׁכִינְתָּא עִלָּאָה. וְאֶת הָאָרֶץ דָּא שְׁכִינְתָּא דִּלְתַתָּא בְּאִתְחַבְּרוּתָא דִּדְכַר וְנוּקְבָא כְּחֲדָא. וְהָא אִתְּמָר כְּמָה דְּאִתְעָרוּ בֵּיהּ חַבְרַיָיא עַד כְּעָן.","בָּעוּ (ד\"א בעא) לְמֵיזַל. קָמוּ. אָמַר רַבִּי שִׁמְעוֹן מִלָּה הָכָא גַּבָּן. פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, תְּרֵי קְרָאֵי כְּתִיבֵי, (דברים ד׳:כ״ד) כִּי יְיָ אֱלֹהֶיךָ אֵשׁ אוֹכְלָה הוּא. וּכְתִיב הָתָם (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּיְיָ אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם. הָנֵי קְרָאֵי אוֹקִימְנָא לְהוּ בְּכַמָּה אֲתַר וְאִתְעָרוּ בְּהוּ חַבְרַיָיא. תָּא חֲזֵי, כִּי יְיָ אֱלהֶיךָ אֵשׁ אוֹכְלָה הוּא, הָא אִתְּמָר מִלָּה דָא בְּגוֹ חַבְרַיָיא דְּאִית אֶשָׁא אָכְלָא אֶשָׁא (ואיתאשא) וְאָכִיל לָהּ וְשָׁצֵי לָהּ. בְּגִין דְּאִית אֶשָׁא תַּקִּיפָא מֵאֶשָׁא וְאוּקְמוּהָ.","אֲבָל תָּא חֲזֵי, מָאן דְּבָעֵי לְמִנְדַע חָכְמְתָא דְּיִחוּדָא קַדִּישָׁא. יִסְתַּכַּל בְּשַׁלְהוֹבָא דְּסָלְקָא מִגּוֹ גַּחֶלְתָּא. אוֹ מִגּוֹ בּוֹצִינָא דְּדָלִיק. דְּהָא שַׁלְהוֹבָא לָא סָלְקָא אֶלָּא כַּד אִתְאַחִיד בְּמִלָּה גַּסָּה (נ\"א אחרא)."],[[0,"אר\"ש כגוונא דא אורייתא קאים בין תרי בתים כמ\"ד לשני בתי ישראל:","אר\"ש כעין זה עומדת התורה, שהוא ז\"א, בין שני בתים, דהיינו בין ב' נוקבין, כי נוקבא נקראת בית, כמ\"ש לשני בתי ישראל, \u0003חד סתימא עלאה, וחד אתגליא יתיר,\u0004 בית אחד הוא סתום העליון, אמא עלאה, בינה. ובית אחד מגולה יותר. \u0003סתימא עלאה דא קול גדול, דכתיב קול וגו',\u0004 סתום העליון, בינה, זהו קול גדול, שכתוב עליו, קול גדול ולא יסף. וכאן חוזר ר\"ש על דבריו לעיל, בהרחבת דברים."],[1,"והאי קול, פנימאה איהו, דלא אשתמע ולא אתגליא, ודא הוא כד נביע בי גרון אפיק ה' בחשאי,","וקול הזה, הוא פנימי, שאינו נשמע ואינו מתגלה. אינו נשמע, היינו בקול. אינו מתגלה, היינו בדבור. וזה הוא כשהחיבור, של חיך וגרון מוציא \u0003ה'\u0004 בלחש שאין בה שום קול, \u0003ונביע תדיר ולא פסק,\u0004 וזווג הזה נובע תמיד ואינו נפסק. \u0003ואיהו דקה פנימאה דלא אשתמע לעלמין.\u0004 והוא קול דק פנימי שאינו נשמע לעולם. פירוש, כשיש הארת חכמה בהמוחין היוצאים ונולדים מהזווג, הם נבחנים שהם נשמעים לחוץ, והם מתגלים על ידי זווג קול ודבור. אבל בשעה שהמוחין הם חסדים מכוסים ונעלמים מהארת חכמה, הם נבחנים, שהם אינם נשמעים לחוץ ואינם מתגלים. וזווג או\"א עלאין הוא על ידי חיך וגרון דא\"א, שאבא ה\"ס חיך ואמא ה\"ס גרון. ולפי שאו\"א הם תמיד בחסדים מכוסים בסוד כי חפץ חסד הוא, נבחן זווגם בסוד \u0003ה' בחשאי,\u0004 כמו הביטוי של אות \u0003ה'\u0004 היוצאת מזווג חיך וגרון, שאינה נשמעת לחוץ. וקול זה של אות \u0003ה'\u0004 הוא אמא המקבלת מאבא, והוא נוקבא עלאה דז\"א, ועליה אומר הכתוב \u0003קול גדול ולא יסף,\u0004 כי זווג זה דאו\"א הוא זווג תמידי שאינו נפסק לעולם, וע\"כ הוא גדול."],[2,"ומהכא נפקא אורייתא, דאיהו קול דיעקב, והאי אשתמע דנפקא מההיא דלא אשתמע:","ומכאן, מאו\"א שה\"ס קול גדול, יוצאת התורה, שהוא קול יעקב, דהיינו ז\"א, וקול זה הנשמע, יוצא מקול ההיא שאינו נשמע. דהיינו מאו\"א, \u0003ולבתר אתאחיד דיבור בהדיה, ונפק לבר מחיליה ומתקפיה,\u0004 ואח\"כ מזדווג עמו הדבור, דהיינו הנוקבא שלו, ויוצא הדיבור ומתגלה לחוץ מכחו ועוזו של קול יעקב. \u0003וקול דיעקב דאיהו אורייתא אחיד בין תרי נקבי, אחיד בהאי פנימאה דלא אשתמע ואחיד בהאי דלבר דאשתמע,\u0004 וקול יעקב, שהוא התורה, דהיינו ז\"א, נאחז בין שתי נקבות, אחוז בפנימית הזו שאינו נשמעת, דהיינו באמא, ואחוז בזו שבחוץ, שהיא נשמעת, דהיינו בהנוקבא. כמו שנתבאר לעיל אשר נוקבא הפנימית שהיא אמא, משפעת לו המוחין והברכות, והנוקבא החיצונית, שהיא נוקבא שלו, היא מקבלת ממנו המוחין והברכות."],[3,"תרין אינון דלא אשתמעו ותרין אינון דאשתמעו:","שנים הם שאינם נשמעים לחוץ, שהם חסדים מכוסים, ושנים הם נשמעים לחוץ, שהם בחסדים מגולים בהארת חכמה. ומפרש \u0003תרין דלא אשתמעו, דא הוא חכמה עלאה סתימאה דקיימא במחשבה דלא אתגליא ולא אשתמע,\u0004 שנים שאינם נשמעים, זהו חכמה עליונה הסתומה, דהיינו א\"א, העומד ומלובש במחשבה, דהיינו אבא עלאה, שאינו מתגלה בדבור, ואפילו בבחינת קול אינו נשמע. \u0003לבתר, נפקא ואתגליא זעיר בחשאי דלא אשתמע, ההוא דאקרי קול גדול, דהוא דק ונפיק בחשאי.\u0004 אח\"כ יוצא ומתגלה מעט בלחש שאינו נשמע, דהיינו בסוד הברת אות ה' כנ\"ל, אותו שנקרא קול גדול, שהוא קול דק ויוצא בחשאי. דהיינו אמא עלאה. ושנים אלו שהם אבא ואמא אינם נשמעים. כמ\"ש לעיל."],[4,"תרין אינון דאשתמעו, אינון דנפקי מהכא, קול דיעקב ודבור דאתאחיד בהדיה:","שנים הם שנשמעים, הם יוצאים מכאן, היינו שיוצאים מהשנים שאינם נשמעים, והם קול של יעקב, דהיינו ז\"א, והדבור המתיחד עמו, שהיא הנוקבא דז\"א. \u0003האי קול גדול דאיהו בחשאי ולא אשתמע, איהי בית לחכמה עלאה, וכל נוקבא בית אקרי.\u0004 קול גדול זה שהוא בלחש ואינו נשמע, דהיינו בינה כנ\"ל, הוא בית לחכמה עלאה, שהוא אבא, כי כל נקבה נקראת בשם בית. וע\"כ נקראת הבינה שהיא נקבה בשם בית. \u0003והאי דבור בתראה איהו בית לקול דיעקב, דאיהו אורייתא,\u0004 ודבור זה האחרון, שהיא הנוקבא דז\"א, הוא בית לקול יעקב, שהוא התורה, דהיינו ז\"א. \u0003וע\"ד אורייתא שריא בב', בי\"ת ראשי\"ת,\u0004 וע\"כ התורה מתחלת עם \u0003ב\u0004 דהיינו בראשית."],[5,"פתח ואמר בראשית ברא אלקים היינו דכתיב, ויבן וגו'. את השמים, היינו דכתיב ויביאה וגו'.","פתח ר\"ש ואמר, בראשית ברא אלקים היינו שכתוב ויבן ה' אלקים את הצלע. כלומר שכאן מרומז בנין הנוקבא ע\"י או\"א. את השמים, שה\"ס זו\"ן הגדולים, היינו שכתוב ויביאה אל האדם. \u0003ואת הארץ, כד\"א ועצם מעצמי\u0004 ואת הארץ, שה\"ס זו\"ן הקטנים, הוא כמ\"ש עצם מעצמי."],[5,"","פירוש. כי נתבאר לעיל (בראשית א' דף י' ד\"ה בהאי) כי \u0003ברא\u0004 לשון סתימא היא, וה\"ס אשר דנפיק מראשית, דהיינו סוד הורדת אתוון אל\"ה דבינה לתוך הזו\"ן, שנשארה הבינה בו\"ק, בסוד ב' אתוון מ\"י. ואח\"כ חזרו והעלו אתוון אל\"ה אליהם וחזרה והשיגה הג\"ר, ונשתלם השם \u0003אלקים,\u0004 שז\"ס \u0003בראשית ברא אלקים.\u0004 ונודע שעם אתוון אל\"ה שהבינה מעלה, עולים עמהם גם זו\"ן, להיותם דבוקים עליהם (כנ\"ל ב\"א דף י' ד\"ה אי) והם משיגים שם המוחין דבינה. הרי שסוד בנין הנוקבא, שהוא ע\"י עליתה לאו\"א, שה\"ס בינה, הוא בסוד \u0003בראשית ברא אלקים,\u0004 שבמלות הללו מרומז עליות זו\"ן לאו\"א והשגת הבנין מהם, דהיינו המוחין. וז\"ש \u0003בראשית ברא אלקים היינו דכתיב ויבן ה' אלקים את הצלע.\u0004"],[5,"","ונתבאר לעיל (דף קכ\"ח ד\"ה וז\"ש) בביאור הכתוב \u0003ויביאה אל האדם,\u0004 שה\"ס תקון המסך בהנוקבא להכשירה לקבל חסדים מז\"א, נמצא מזה, שהכתוב \u0003ויביאה,\u0004 קאי על הנוקבא הגדולה שמחזה ולמעלה דז\"א, המרומזת בהמלה \u0003את,\u0004 של את השמים, כנ\"ל (בראשית א' דף רנ\"ה ד\"ה ואת) וז\"ש \u0003את השמים, היינו דכתיב ויביאה אל האדם.\u0004 כלומר שהמלה \u0003את,\u0004 שה\"ס נוקבא הגדולה של השמים, שהוא ז\"א, עליה נאמר, ויביאה אל האדם, שפירושו שהכשיר אותה לקבלת חסדים."],[5,"","ונודע שהע\"ס כח\"ב תו\"מ נקראים, מוחא עצמות גידין בשר עור. ונמצא שעצמות הוא חכמה, וז\"ש \u0003ואת הארץ,\u0004 אשר רומז על הנוקבא הקטנה שלמטה מחזה, (כמ\"ש שם), שהיא לבדה נתקנה לקבלת חכמה (כנ\"ל דף ט\"ז ד\"ה אמר) היינו \u0003ועצם מעצמי,\u0004 עליה נאמר עצם מעצמי, שפירושו שמקבלת חכמה. וז\"ש \u0003ודאי האי איהי ארץ החיים,\u0004 שהנוקבא הקטנה המרומזת בואת הארץ, היא נקראת ארץ החיים, כי אור החכמה נקראת אור חיה, וע\"כ הנוקבא בעת שיש לה אור החכמה נקראת ארץ החיים. שז\"ס החכמה תחיה בעליה."],[6,"תו פתח ר\"ש ואמר נאם וגו', נאם ה' לאדוני, דרגא עלאה לדרגא תתאה קאמר, שב לימיני.","עוד פתח ר\"ש ואמר וכו' הכ', נאם ה' לאדוני, פירושו, שמדרגה העליונה, שהוא ז\"א אומרת למדרגה התחתונה, שהיא הנוקבא, שב לימיני, \u0003לאתקשרא מערבית בדרומית שמאלא בימינא בגין לתברא חיליהון דשאר עמין עעכו\"ם.\u0004 ליחד מערב, שהיא הנוקבא, בדרומית, שהוא חסד דז\"א, השמאל שהיא הנוקבא, בימינא דז\"א, כדי לשבר כחם של האומות עובדי ע\"ז. דהיינו כמו שהכתוב ממשיך, עד אשית אויביך הדום לרגליך. כי, \u0003נאם ה' דא יעקב,\u0004 דהיינו ז\"א, \u0003לאדוני דא ארון הברית אדון כל הארץ\u0004 שהיא הנוקבא, (כנ\"ל בראשית א' דף ש\"ז ד\"ה כתיב)."],[6,"","פירוש. הנוקבא, היא חכמה בעיקרה, כמ\"ש לעיל (אות רמ\"א) שעליה אומר הכתוב, ועצם מעצמי. וכל עוד שאין לה חסדים להתלבש בהם, יכולים החצונים לאחוז בה, ע\"כ אומר אליה ז\"א, שב לימיני דהיינו לקבל חסדים מספירת החסד שהוא ימין ז\"א, ואז תוכל להכניע כל כוחות הדין."],[7,"ד\"א, נאם ה' דא יובלא, לאדוני, דא שמיטה, דכתיב בה אהבתי את אדוני:","פירוש אחר, נאם ה' היינו יובל, שהוא בינה. לאדוני, היינו שמיטה, שהיא הנוקבא, שכתוב בה אהבתי את אדוני. \u0003שב לימיני, דהא ימינא ביובלא שריא, ושמיטה בעי לאתקשרא בימינא,\u0004 היובל אומר לשמיטה שב לימיני, כי ימין, דהיינו חסדים, שורה ביובל, דהיינו בבינה, ושמיטה שהיא הנוקבא, צריכה להתקשר בימין. כמו שמבאר לפנינו."],[8,"ת\"ח שמיטה דא, לא אתקשר בקיומא שלים, בימינא ובשמאלא, מיומא דאשתכחת:","בוא וראה, שמיטה זו, דהיינו הנוקבא, לא נקשרה בקיום שלם בימין ובשמאל. מיום מציאותה. \u0003כד בעיא לאתקשרא אושיט דרועא שמאלא לקבלה וברא עלמא דין.\u0004 כאשר הנוקבא רוצה להתקשר בימין ושמאל, פושט, ז\"א, את זרוע השמאל שלו, לנגדה, דהיינו שמשפיע לה תחילה המוחין שבנקודת השורק, שהם שמאל בלי ימין, ואז ברא עולם הזה. דהיינו הנוקבא מבחינת השמאל שבה, הנקראת עולם הזה. \u0003ובגין דהוא מסטרא דשמאלא לית ביה קיומא עד זמנא דאלף שביעאה,\u0004 ומשום שהוא עתה מבחינת השמאל לבד, אין לה קיום, דהיינו מוחין שלמים, עתה בשתא אלפי שני, עד הזמן של אלף השביעי, \u0003דבההוא יומא לחוד אתקשר כדין בימינא,\u0004 כי ביום ההוא בלבדו, הנוקבא נקשרת בימין, דהיינו בחסדים, \u0003וכדין תהוי בין ימינא ושמאלא בקיומא שלים, וישתכחון שמים חדשים וארץ חדשה, וכדין לא תעדי מתמן לעלמין,\u0004 ואז תהיה הנוקבא ממוזגת בין ימין ושמאל בקיום שלם, דהיינו במוחין שלמים, ויהיו אז שמים חדשה וארץ חדשה, ואז לא תסור עוד משם לעולם, כי תהיה ממוזגת בימין ושמאל לנצחיות."],[9,"אי הכי במאי נוקים שב לימיני, אלא עד זמנא ידיעא, דכתיב עד אשית וגו':","מקשה אם כן, שאתה אומר שרק באלף הז' תתקשר הנוקבא בימין, במה נפרש הכתוב, שב לימיני, שהמשמעות הוא בשתא אלפי שני, ולאו דוקא באלף הז', ומתרץ שכוונת הכתוב, שב לימיני, הוא רק לזמן מסוים, כי כתוב, עד אשית אויביך הדום לרגליך, אבל לא תמיד, \u0003אבל בההוא זמנא לא תעדי מתמן לעלמין, דכתיב כי ימין ושמאל תפרוצי, למהוי כלא חד,\u0004 אבל בזמן ההוא, דהיינו באלף הז', לא תסור עוד משם לעולם, שכתוב עליה אז, כי ימין ושמאל תפרוצי וגו', דהיינו שתכלול אז את עצמה בקו ימין ובקו שמאל, ויהיו בה הכל אחד."],[10,"תא חזי, את השמים דא שכינתא עלאה, ואת הארץ דא שכינתא דלתתא באתחברותא דדו\"נ כחדא:","בוא וראה, הכתוב את השמים, יורה על שכינה עלאה, דהיינו הנוקבא שמחזה ולמעלה, ואת הארץ, דא שכינתא תתאה, דהיינו הנוקבא שמחזה ולמטה דז\"א, בתתחברות דכר ונוקבא כאחד, כלומר, שנוקבא עלאה מחוברת בדכר, שהוא ז\"א הגדול, וגם נוקבא תתאה מחוברת בדכר, שהוא ז\"א הקטן. \u0003והא אתמר כמה דאתערו ביה חבריא עד כען,\u0004 וכבר נתבאר זה כמו שהעירו בו החברים עד עתה."],[11,"בעו למיזל קמו, אר\"ש מלה הכא גבן.","רצו ללכת וקמו ממקומם, אמר להם ר\"ש דבר אצלנו כאן, כלומר, שיש לו כאן דבר שרוצה לומר להם, \u0003פתח ר\"ש ואמר, תרי קראי כתיבי, כי ה' אלקיך אש וגו' ואתם הדבקים וגו', הני קראי אוקימנא להו בכמה אתר ואתערו בהו חברייא,\u0004 פתח ר\"ש ואמר, ב' כתובים נאמרו: אחד, כי ה' אלקיך אש אוכלה הוא, שהמשמעות שאי אפשר להדבק בו, כמו שאי אפשר להדבק באש. והכתוב השני, ואתם הדבקים וגו' הרי שאפשר להדבק בו. כתובים הללו ביארנו אותם בכמה מקומות, וגם נתעוררו החברים בהם. אבל \u0003ת\"ח כי ה' אלקיך אש אוכלה הוא, הא אתמר מלה דא בגו חברייא, דאית אשא אכלא אשא ואכיל לה ושצי לה,\u0004 אבל בוא וראה, כתיב כי ה' אלקיך אש אוכלה אש הוא, כבר נאמר דבר זה בין החברים, שיש אש אוכלת אש, דהיינו שאוכלת אותה ומשמידה אותה. \u0003בגין דאית אשא תקיפא מאשא ואוקמוה,\u0004 משום שיש אש שהיא חזקה יותר מאש רגילה, וכבר בארוה."],[12,"אבל ת\"ח מאן רבעי למנדע חכמתא דיחודא קדישא יסתכל בשלהובא דסלקא מגו גחלתא או מגו בוצינא דדליק:","אבל בוא וראה, כל הרוצה לדעת חכמת היחוד הקדוש, יסתכל בשלהבת העולה מתוך הגחלת או העולה מן הנר הדלוק, \u0003דהא שלהובא לא סלקא, אלא כד אתאחיד במלה גסה\u0004 כי השלהבת אינו עולה, אלא כשנאחז בדבר עב."]],[[0,"","אָמַר רַבִּי שִׁמְעוֹן, כְּמוֹ זֶה הַתּוֹרָה עוֹמֶדֶת בֵּין שְׁנֵי בָתִּים, כְּמוֹ שֶׁכָּתוּב (ישעיה ח) לִשְׁנֵי בָּתֵּי יִשְׂרָאֵל וְגוֹ'. אֶחָד נִסְתָּר עֶלְיוֹן, וְאֶחָד גָּלוּי יוֹתֵר. (הנסתר) הָעֶלְיוֹן (זה) קוֹל גָּדוֹל, שֶׁכָּתוּב (דברים ה) קוֹל גָּדוֹל וְלֹא יָסָף."],[1,"","וְהַקּוֹל הַפְּנִימִי הַזֶּה הוּא שֶׁלֹּא נִשְׁמָע וְלֹא מִתְגַּלֶּה. וְזֶהוּ כְּשֶׁנּוֹבֵעַ בֵּית הַגָּרוֹן, יוֹצֵאת (בו) ה' בַּחֲשַׁאי, וְתָמִיד נוֹבֵעַ וְלֹא פוֹסֵק. וְהוּא דַּק פְּנִימִי שֶׁלֹּא נִשְׁמַע לְעוֹלָמִים."],[2,"","וּמִכָּאן יוֹצֵאת הַתּוֹרָה שֶׁהִיא קוֹל יַעֲקֹב. וְזֶה נִשְׁמָע (שנשמע) שֶׁיּוֹצֵא (יוצא) מֵאוֹתָהּ שֶׁלֹּא נִשְׁמַעַת, וְאַחַר כָּךְ הַדִּבּוּר נֶאֱחָז עִמּוֹ וְיוֹצֵא הַחוּצָה מִכֹּחוֹ וּמִתָּקְפּוֹ. וְקוֹל שֶׁל יַעֲקֹב שֶׁהוּא תּוֹרָה, אוֹחֵז בֵּין שְׁתֵּי נְקֵבוֹת. אוֹחֵז בַּפְּנִימִי הַזֶּה שֶׁלֹּא נִשְׁמָע, וְאוֹחֵז בָּזֶה שֶׁבַּחוּץ שֶׁנִּשְׁמָע."],[3,"","שְׁנַיִם הֵם שֶׁלֹּא נִשְׁמָעִים, וּשְׁנַיִם שֶׁנִּשְׁמָעִים. שְׁנַיִם שֶׁלֹּא נִשְׁמָעִים זוֹהִי חָכְמָה הָעֶלְיוֹנָה הַנִּסְתֶּרֶת שֶׁעוֹמֶדֶת בַּמַּחֲשָׁבָה שֶׁלֹּא מִתְגַּלָּה וְלֹא נִשְׁמַעַת. אַחַר כָּךְ יוֹצֵאת וּמִתְגַּלָּה מְעַט בַּחֲשַׁאי, שֶׁלֹּא נִשְׁמָע אוֹתוֹ שֶׁנִּקְרָא קוֹל גָּדוֹל, שֶׁהוּא דַּק וְיוֹצֵא בַּחֲשַׁאי."],[4,"","שְׁנַיִם הֵם שֶׁנִּשְׁמָעִים, אוֹתָם שֶׁיּוֹצְאִים מִכָּאן הַקּוֹל שֶׁל יַעֲקֹב וְדִבּוּר שֶׁנֶּאֱחָז עִמּוֹ. הַקּוֹל הַגָּדוֹל הַזֶּה שֶׁהוּא בַּחֲשַׁאי שֶׁלֹּא נִשְׁמָע, הִיא בַּיִת לַחָכְמָה הָעֶלְיוֹנָה, וְכָל נְקֵבָה נִקְרֵאת בַּיִ\"ת. וְהַדִּבּוּר הָאַחֲרוֹן הַזֶּה הוּא בַּיִת לַקּוֹל שֶׁל יַעֲקֹב שֶׁהוּא תּוֹרָה. וְעַל כֵּן הַתּוֹרָה מַתְחִילָה בְּבֵי\"ת, בֵּי\"ת רֵאשִׁית."],[5,"","פָּתַח וְאָמַר, בְּרֵאשִׁית בָּרָא אֱלֹהִים, הַיְנוּ שֶׁכָּתוּב וַיִּבֶן ה' אֱלֹהִים אֶת הַצֵּלָע. אֵת הַשָּׁמַיִם, הַיְנוּ שֶׁכָּתוּב וַיְבִאֶהָ אֶל הָאָדָם. וְאֵת הָאָרֶץ, כְּמוֹ שֶׁנֶּאֱמַר עֶצֶם מֵעֲצָמַי. וַדַּאי זוֹהִי אֶרֶץ הַחַיִּים."],[6,"","עוֹד פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (תהלים ק) נְאֻם ה' לַאדנִי שֵׁב לִימִינִי עַד אָשִׁית אֹיְבֶיךְ הֲדם לְרַגְלֶיךְ. נְאֻם ה' לַאדנִי - הַדַּרְגָּה הָעֶלְיוֹנָה לַדַּרְגָּה הַתַּחְתּוֹנָה אוֹמֶרֶת שֵׁב לִימִינִי, לְקַשֵּׁר מַעֲרָבִית בִּדְרוֹמִית, שְׂמֹאל בְּיָמִין, כְּדֵי לִשְׁבֹּר אֶת כֹּחָם שֶׁל שְׁאָר הָעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת. נְאֻם ה' לַאדנִי - נְאֻם ה' זֶה יַעֲקֹב. לַאדנִי - זֶה (יהושע ג) אֲרוֹן הַבְּרִית אֲדוֹן כָּל הָאָרֶץ."],[7,"","דָּבָר אַחֵר נְאֻם ה' - זֶה יוֹבֵל. לַאדנִי - זוֹ שְׁמִטָּה, שֶׁכָּתוּב בָּהּ (שמות כא) אָהַבְתִּי אֶת אֲדנִי. שֵׁב לִימִינִי - שֶׁהֲרֵי הַיָּמִין מַתְחִיל בַּיּוֹבֵל, וּשְׁמִטָּה צָרִיךְ לְקַשֵּׁר בְּיָמִין."],[8,"","בֹּא רְאֵה, שְׁמִטָּה זוֹ לֹא נִקְשֶׁרֶת בְּקִיּוּם שָׁלֵם בְּיָמִין וּבִשְׂמֹאל מִיּוֹם שֶׁנִּבְרֵאת. כְּשֶׁרוֹצֶה לְהִתְקַשֵּׁר, הוֹשִׁיט זְרוֹעַ שְׂמֹאל כְּנֶגְדָּהּ וּבָרָא אֶת הָעוֹלָם הַזֶּה. וּבִגְלַל שֶׁהוּא מִצַּד שְׂמֹאל, אֵין בּוֹ קִיּוּם עַד הַזְּמַן שֶׁל הָאֶלֶף הַשְּׁבִיעִי, שֶׁבְּאוֹתוֹ יוֹם לְחוּד מִתְקַשֵּׁר אָז בְּיָמִין. וְאָז תִּהְיֶה בֵּין הַיָּמִין וְהַשְּׂמֹאל בְּקִיּוּם שָׁלֵם, וְיִמָּצְאוּ שָׁמַיִם חֲדָשִׁים וְאֶרֶץ חֲדָשָׁה, וְאָז לֹא תָזוּז מִשָּׁם לְעוֹלָמִים."],[9,"","אִם כָּךְ, בַּמֶּה נַעֲמִיד שֵׁב לִימִינִי? אֶלָּא עַד זְמַן יָדוּעַ, שֶׁכָּתוּב עַד אָשִׁית אֹיְבֶיךְ הֲדם לְרַגְלֶיךְ, וְלֹא תָמִיד. אֲבָל בְּאוֹתוֹ זְמַן לֹא תָזוּז מִשָּׁם לְעוֹלָמִים, שֶׁכָּתוּב (ישעיה נד) כִּי יָמִין וּשְׂמֹאול תִּפְרֹצִי, לִהְיוֹת הַכֹּל אֶחָד."],[10,"","בֹּא רְאֵה, אֵת הַשָּׁמַיִם - זוֹ שְׁכִינָה עֶלְיוֹנָה (בינה). וְאֵת הָאָרֶץ - זוֹ שְׁכִינָה שֶׁלְּמַטָּה בְּהִתְחַבְּרוּת שֶׁל זָכָר וּנְקֵבָה כְּאֶחָד, וַהֲרֵי נֶאֱמַר כְּמוֹ שֶׁהֵעִירוּ בוֹ הַחֲבֵרִים עַד עַכְשָׁו."],[11,"","רָצוּ (רצה) לָלֶכֶת. קָמוּ. אָמַר רַבִּי שִׁמְעוֹן, דָּבָר כָּאן אֶצְלֵנוּ. פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, שְׁנֵי פְסוּקִים כְּתוּבִים, (דברים ד) כִּי ה' אֱלֹהֶיךְ אֵשׁ אֹכְלָה הוּא, וְכָתוּב שָׁם (שם) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם. אֶת הַפְּסוּקִים הַלָּלוּ בֵּאַרְנוּ אוֹתָם בְּכַמָּה מְקוֹמוֹת, וְהַחֲבֵרִים הֵעִירוּ בָהֶם. בּא תִרְאֶה, כִּי ה' אֱלֹהֶיךְ אֵשׁ אֹכְלָה הוּא, הֲרֵי נֶאֱמַר הַדָּבָר הַזֶּה בְּתוֹךְ הַחֲבֵרִים שֶׁיֵּשׁ אֵשׁ אוֹכֶלֶת אֵשׁ, (ויש אש) וְאוֹכֶלֶת אוֹתָהּ וּמַשְׁמִידָה אוֹתָהּ, הֱיוֹת שֶׁיֵּשׁ אֵשׁ חֲזָקָה מֵאֵשׁ, וּפֵרְשׁוּהָ."],[12,"","אֲבָל בּא רְאֵה, מִי שֶׁרוֹצֶה לָדַעַת חָכְמַת הַיִּחוּד הַקָּדוֹשׁ, יִסְתַּכֵּל בַּשַּׁלְהֶבֶת שֶׁעוֹלָה מִתּוֹךְ הַגַּחֶלֶת אוֹ מִתּוֹךְ נֵר שֶׁדּוֹלֵק. שֶׁהֲרֵי הַשַּׁלְהֶבֶת לֹא עוֹלָה אֶלָּא כְּשֶׁנֶּאֱחֶזֶת בְּדָבָר גַּס (אחר)."]]],[["תָּא חֲזֵי, בְּשַׁלְהוֹבָא דְּסָלְקָא אִית תְּרֵין נְהוֹרִין. חַד נְהוֹרָא חִוְורָא דְּנָהִיר. וְחַד נְהוֹרָא דְּאִתְאַחִיד בָּהּ אוּכְמָא אוֹ תִּכְלָא. הַהוּא נְהוֹרָא חִוְורָא אִיהוּ לְעֵילָא וְסָלְקָא בְאוֹרַח מִישׁוֹר. וּתְחוֹתֵיהּ הַהוּא נְהוֹרָא תִּכְלָא אוֹ אוּכְמָא דְּאִיהוּ כָּרְסַיָא לְהַהוּא חִוְורָא.","וְהַהוּא נְהוֹרָא חִוְורָא שָׁארֵי עִלָוֵּיהּ וְאִתְאֲחִידוּ דָא בְּדָא לְמֶהוֵי כֹּלָּא חַד. וְהַהוּא נְהוֹרָא אוּכְמָא אוֹ גַּוָון תִּכְלָא דְּאִיהוּ לְתַתָּא הוּא כָּרְסַיָא דִיקָר לְהַהוּא חִוָּורָא. וְעַל דָּא רָזָא דִּתְכֶלְתָּא.","וְהַאי כָּרְסַיָא תִּכְלָא (או) אוּכְמָא אִתְאֲחַד בְּמִלָּה אָחֳרָא לְאִתְדַּלְּקָא דְּהוּא מִתַּתָּא וְהַהוּא אִתְעַר לֵיהּ לְאִתְאַחֲדָא בִּנְהוֹרָא חִוְּורָא (ס\"א עלאה).","וְדָא תִּכְלָא אוּכְמָא לְזִמְנִין אִתְהֲדַר סוּמְקָא. וְהַהוּא נְהוֹרָא חִוְּורָא דְּעֲלֵיהּ לָא אִשְׁתַּנֵּי לְעָלְמִין דְּהָא חִוְּורָא הוּא תָּדִיר. אֲבָל הַאי תִּכְלָא אִשְׁתַּנֵּי לִגְוָונִין אִלֵּין. לְזִמְנִין תִּכְלָא אוֹ אוּכְמָא. וּלְזִמְנִין סוּמְקָא.","וְהַאי אִתְאֲחִיד לִתְרִין סִטְרִין. אִתְאֲחִיד לְעֵילָא בְּהַהוּא נְהוֹרָא (ס\"א עילאה) חִוְּורָא. אִתְאֲחִיד לְתַתָּא בְּהַהוּא מִלָּה דִּתְחוֹתוֹי דִּמְתַקְנָא בֵּיהּ לְאַנְהָרָא (מלין דשויין ליה לאדלקא) וּלְאִתְאַחֲדָא בֵּיהּ.","וְדָא אָכְלָא תָּדִיר וְשָׁצֵי לְהַהוּא מִלָּה דְּשַׁוְיָין לֵיהּ. דְּהָא בְּכָל מַה דְּאִתְדָּבַּק בֵּיהּ לְתַתָּא וְשַׁרְיָא עֲלוֹי הַהוּא נְהוֹרָא תִּכְלָא שָׁצֵי לֵיהּ וְאָכִיל לֵיהּ. בְּגִין דְּאוֹרְחוֹי הוּא לְשֵׁיצָאָה וּלְמֶהֱוֵי אָכִיל. דְּהָא בֵּיהּ תַּלְיָא שֵׁצוּ דְּכֹלָּא מוֹתָא דְכֹלָּא. וּבְגִינֵי כָךְ אִיהִי אָכִיל כָּל מַה דְּאִתְדָּבַּק בֵּיהּ לְתַתָּא.","וְהַהוּא נְהוֹרָא חִוְּורָא דְּשַׁרְיָא עֲלוֹי לָא אָכִיל וְלָא שָׁצֵי לְעָלְמִין וְלָא אִשְׁתַּנֵּי נְהוֹרֵיהּ. וְעַל דָּא אָמַר משֶׁה כִּי יְיָ אֱלֹהֶיךָ אֵשׁ אוֹכְלָה הוּא. אוֹכְלָה וַדַּאי. אָכִיל וְשָׁצֵי כָּל מַה דְּשַׁרְיָא תְּחוֹתוֹי. וְעַל דָּא אָמַר יְיָ אֱלֹהֶיךָ וְלֹא אֱלהֵינוּ. בְּגִין דְּמשֶׁה בְּהַהוּא נְהוֹרָא חִוְּורָא דִלְעֵילָא הֲוָה דְּלָא שָׁצֵי וְלָא אָכִיל.","תָּא חֲזֵי, לֵית לֵיהּ אִתְעֲרוּתָא לְאִתְדַּלְּקָא הַאי נְהוֹרָא תִּכְלָא לְאִתְאַחֲדָא בִּנְהוֹרָא חִוְּורָא, אֶלָּא עַל יְדֵי יִשְׂרָאֵל דְּאִנּוּן מִתְדַּבְּקָן בֵּיהּ תְּחוֹתוֹי.","וְתָּא חֲזֵי, אַף עַל גַּב דְּאָרְחֵיהּ דְּהַאי נְהוֹרָא תִּכְלָא אוּכְמָא לְשֵׁיצָאָה כָּל מַה דְּאִתְדָּבַּק בֵּיהּ תְּחוֹתוֹי. יִשְׂרָאֵל מִתְדַּבְּקָן בֵּיהּ תְּחוֹתוֹי וְקָיְימָן בְּקִיּוּמָא הֲדָא הוּא דִכְתִיב, (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּיְיָ אֱלהֵיכֶם חַיִּים. בַּיְיָ אֱלהֵיכֶם וְלָא אֱלהֵינוּ (אלא ביי אלהיכם). בְּהַהוּא נְהוֹרָא תִּכְלָא אוּכְמָא דְּאָכִיל וְשָׁצֵי כָּל מַה דְּאִתְדָּבַּק בֵּיהּ תְּחוֹתֵיהּ. וְאַתּוּן מִתְדַּבְּקָן בֵּיהּ וְקָיְימֵי. דִּכְתִיב חַיִּים כֻּלְּכֶם הַיּוֹם.","וְעַל נְהוֹרָא חִוְּורָא, שַׁרְיָיא לְעֵילָא נְהוֹרָא סְתִימָא דְּאַקִּיף לֵיהּ. וְרָזָא עִלָּאָה הָכָא. וְכֹלָּא תִשְׁכַּח בְּשַׁלְהוֹבָא דְּסָלִיק וְחָכְמְתִין דְּעֶלְיוֹנִין בֵּיהּ. אֲתָא רַבִּי פִּנְחָס וּנְשָׁקֵיהּ. אָמַר בְּרִיךְ רַחֲמָנָא דְּאִיעַרְעָנָא הָכָא. אֲזְלוּ עִמֵּיהּ דְּרַבִּי פִּנְחָס תְּלַת מִילִין.","אֲהַדְּרוּ רַבִּי שִׁמְעוֹן וְחַבְרַיָיא. אָמַר רַבִּי שִׁמְעוֹן הָא דְּאֲמָרָן רָזָא דְחָכְמְתָא אִיהוּ בְּיִחוּדָא קַדִּישָׁא. דִּבְגִין כָּךְ ה\"א בַּתְרָאָה דִּשְׁמָא קַדִּישָׁא אִיהוּ נְהוֹרָא תִּכְלָא אוּכְמָא דְּאִתְאֲחִיד בְּיה\"ו דְּהוּא נְהוֹרָא חִוְּורָא דְּנָהִיר.","תָּא חֲזֵי, לְזִמְנִין הַאי נְהוֹרָא תִּכְלָא ד'. וּלְזִמְנִין ה'. אֶלָּא בְּזִמְנָא דְּלָא מִתְדַּבְּקָן בֵּיהּ יִשְׂרָאֵל לְתַתָּא לְאַדְלָקָא לֵיהּ לְאִתְאַחֲדָא בִּנְהוֹרָא חִוְּורָא, אִיהוּ ד'. וּלְזִמְנָא דְּמִתְעָרֵי לֵיהּ לְאִתְחַבְּרָא עִם נְהוֹרָא חִוְּורָא כְּדֵין אִקְרֵי ה'.","מְנָלָן דִּכְתִיב, (דברים כ״ב:כ״ג) כִּי יִהְיֶה נַעֲרָה בְּתוּלָה, נַעַר כְּתִיב בְּלָא ה'. מַאי טַעְמָא בְּגִין דְּלָא אִתְחַבְּרַת בִּדְכוּרָא. וּבְכָל אֲתַר דְּלָא אִשְׁתַּכְּחוּ דְּכַר וְנוּקְבָא, ה\"א לָא אִשְׁתְּכַח וְסָלְקָא מִתַּמָּן וְאִשְׁתָּאַר ד'.","דְּהָא אִיהִי כָּל זִמְנָא דְּאִתְחַבַּר בִּנְהוֹרָא חִוְּורָא דְּנָהִיר אִקְרֵי ה'. דְּהָא כְּדֵין כֹּלָּא אִתְחַבַּר כְּחֲדָא. אִיהִי אִתְדַּבְּקַת בִּנְהוֹרָא חִוְּורָא, וְיִשְׂרָאֵל מִתְדַּבְּקָן בָּהּ (ד\"א ל\"ג לתתא) וְקַיְימָא תְּחוֹתָהּ לְאַדְלָקָא לָהּ. וּכְדֵין כֹּלָּא חַד.","וְדָא הוּא רָזָא דְקָרְבָּנָא. דִּתְנָנָא דְּסָלִיק אַתְעַר לֵיהּ לְהַאי נְהוֹרָא תִּכְלָא לְאַדְלָקָא. וְכַד אִתְדְּלַק אִתְחַבַּר בִּנְהוֹרָא חִוְּורָא וּשְׁרַגָּא דָּלִיק בְּיִחוּדָא חַד."],[[0,"ת\"ח, בשלהובא דסלקא אית תרין נהורין, חד, נהורא חוורא דנהיר, וחד, נהורא דאתאחיד בה אוכמא או תכלא:","בוא וראה, בשלהבת העולה, יש ב' אורות. אחד, הוא אור הלבן המאיר. ואחד, הוא האור, שאור הלבן נאחז בו, והוא אור שחור או תכלת. \u0003ההוא נהורא חוורא איהו לעילא וסלקא באורח מישר, ותחותיה ההוא נהורא תכלא או אוכמא דאיהו כרסיא לההוא חוורא,\u0004 אור הלבן ההוא, שמאיר, הוא למעלה, והאור עולה בדרך יושר, ומתחתיו אור התכלת או השחור, שהוא כסא לאור הלבן."],[1,"וההוא נהורא חוורא שארי עלויה ואתאחידו דא בדא למהוי כלא חד:","ואותו אור הלבן המאיר שורה על אור התכלת, ונאחזים ומתיחדים זה בזה, להיות אחד לגמרי. \u0003וההוא נהורא אוכמא או גוון תכלא דאיהו לתתא הוא כרסיא דיקר לההוא חוורא,\u0004 ואותו אור השחור או מראה התכלת שהוא למטה ממנו הוא כסא הכבוד לאור הלבן, \u0003ועל דא רזא דתכלתא,\u0004 וע\"כ מראהו בסוד התכלת. כלומר להיותו בחינת כסא הכבוד, וכסא הכבוד דומה לתכלת, כנודע."],[2,"והאי כרסיא תכלא אוכמא, אתאחד במלה אחרא לאתדלקא, דהוא מתתא:","וכסא זו של אור תכלת או שחור, נאחז בדבר אחר להדלק, שהוא מתחתיו, \u0003וההוא אתער ליה לאתאחדא בנהורא חוורא,\u0004 ודבר ההוא מעורר אותו להאחז באור הלבן."],[3,"ודא תכלא אוכמא, לזמנין אתהדר סומקא, וההוא נהורא חוורא דעליה לא אשתני לעלמין דהא חוורא הוא תדיר:","ואור התכלת ואוכם, חוזר לפעמים להיות אדום, ואור הלבן שעליו, אינו משתנה לעולם ותמיד הוא לבן, \u0003אבל האי תכלא אשתני לגוונין אלין, לזמנין תכלא או אוכמא ולזמנין סומקא,\u0004 אבל התכלת משתנה לצבעים אלו, שלפעמים היא תכלת או שחור, ולפעמים הוא אדום."],[4,"והאי אתאחיד לתרין סטרין. אתאחיד לעילא בההוא נהורא חוורא, אתאחיד לתתא בההוא מלה דתחותוי דמתקנא ביה לאנהרא ולאתחדא ביה:","ואור זה התכלת, נאחז בשני צדדים, נאחז למעלה באותו אור הלבן, ונאחז למטה בדבר הגס שמתחתיו, דהיינו בהפתילה, שמתוקן בעדו, להאיר ולהאחז בו, כי הפתילה נותנת לו אחיזה, שעי\"ז מתדבק באור הלבן המאיר."],[4,"","ביאור הדברים. אור הלבן פירושו אור החסדים, דהיינו אור ז\"א, שה\"ס יה\"ו דשם הוי\"ה, ואור התכלת או השחור, הוא אור הנוקבא, שה\"ס ה' אחרונה של שם הוי\"ה. כמ\"ש ר\"ש (להלן באות רנ\"ט) ויש להבין הדברים משורשם. כי \u0003נהורא חוורא דנהיר,\u0004 ה\"ס אור נקודת החולם, שה\"ס אור החסדים, וקו ימין, ואור או\"א עלאין. \u0003ונהורא תכלא או אוכמא,\u0004 ה\"ס אור נקודת השורק, שה\"ס אור החכמה וקו שמאל, ואור ישסו\"ת. ונודע שב' הקוין ימין ושמאל הנמשכים מב' הנקודות חולם ושורק, הם במחלוקת, ואינם יכולים להאיר עד שיוצאת קומת חסדים על המסך דנקודת החירק, שה\"ס מסך דז\"א, שהוא בחי\"א, ונעשה לקו אמצעי המכריע על ב' הקוין ימין ושמאל, ונכללים זה מזה והשמאל מקבל הארת חסדים מימין והימין מקבל הארת החכמה משמאל. כנודע. וכח המסך הזה שבנקודת החירק, נבחן \u0003לדבר גס\u0004 המדליק \u0003לאור התכלת,\u0004 שה\"ס קו שמאל, ומחברו עם \u0003נהורא חוורא דנהיר,\u0004 שה\"ס קו ימין. ולולא דבר גס הזה, היו ב' הקוין ימין ושמאל נשארים במחלוקת ולא היו מאירים, (כמ\"ש לעיל ב\"א דף מ\"ח ד\"ה ונפק ע\"ש) ואלו ג' הנקודות הם יוצאים כן בתחלה בהבינה, בסוד \u0003תלת נפקי מחד,\u0004 (כנ\"ל ב\"א דף רפ\"ז ד\"ה תלת) ואח\"כ הם יוצאים ג\"כ בזו\"ן, בסוד חד בתלת קיימא ויש לדעת שבעת שזו\"ן מקבלים מוחין הללו בשלמות הם מלבישים על או\"א וישסו\"ת, ואז נעשה ז\"א לבחינת אור נקודת החולם, כאו\"א, והנוקבא לבחינת אור נקודת השורק כמו ישסו\"ת, ואינם יכולים להזדווג זה בזה, עד שיוצאת קומת חסדים על מסך דבחי\"א המכריע על ב' הנקודות, כמ\"ש בבינה, אמנם כאן נמצא המסך דבחינת החירק בנשמות ישראל, כי כמו שאתוון אל\"ה דבינה מעלים אליהם את הזו\"ן, והמסך שלהם משמש לקו המכריע שבבינה, כך אתוון אל\"ה דזו\"ן, מעלים אליהם את נשמות ישראל, והמסך שלהם משמש לקו המכריע בזו\"ן. הרי שדבר הגס הגורם, שהנוקבא, שה\"ס נקודת השורק ושמאל, תתחבר עם הז\"א שה\"ס החולם, הוא כח המסך שבנשמות ישראל. (וז\"ש להלן באות רנ\"ו) \u0003לית ליה אתערותא לאתדלקא וכו' אלא על ידי ישראל.\u0004 דהיינו מטעם שהם הנושא לסוד המסך דחירק, שזולתו, אין יחוד בין ז\"א ונוקביה כמבואר."],[5,"ודא אכלא תדיר ושצי לההוא מלה דשויין ליה:","ואור התכלת שבנר, אוכל תמיד ומכלה לאותו הדבר גס שתקנו לו, דהיינו הפתילה. \u0003דהא בכל מה דאתדבק ביה לתתא ושריא עלוי ההוא נהורא תכלא שצי ליה ואכיל ליה,\u0004 כי בכל מה שאור התכלת נתדבק בו מלמטה, ושורה עליו, הוא מכלה אותו ושורף אותו. \u0003בגין דאורחוי הוא לשיצאה ולמהוי אכיל, דהא ביה תליא שצו דכלא מוחא דכלא,\u0004 משום שדרכו הוא לכלות ולאכול, כי בו תלוים, הכליון של הכל והמות של הכל. כי אור התכלת ה\"ס הנוקבא, ועץ הדעת, שהמות והשמדה נמשכים ממנה."],[6,"וההוא נהורא חוורא דשריא עלוי, לא אכיל ולא שצי לעלמין, ולא אשתני נהוריה:","ואותו אור הלבן השורה עליו, על אור התכלת, אינו אוכל ואינו משחית לעולם, ואורו אינו משתנה לשום צבע. כי אור הלבן הוא אור החסדים כנ\"ל, ואור החסדים אינו משתנה ואינו מתעבה לעולם. גם אין בו שום אחיזה לדינים, וע\"כ אינו שורף ואינו מכלה לעולם."],[6,"וע\"ד אמר משה כי ה' אלקיך אש אוכלה הוא. אוכלה ודאי, אכיל ושצי כל מה דשריא תחותוי,","וע\"כ אמר משה כי ה' אלקיך הוא אש אוכלה, כי ודאי הוא אש אוכלה, ששורף ומכלה כל מה ששורה תחתיו. \u0003וע\"ד אמר ה' אלקיך ולא אלקינו, בגין דמשה, בההוא נהורא, חוורא דלעילא הוה, דלא שצי ולא אכיל,\u0004 וע\"כ אמר משה ה' אלקיך אש אוכלה הוא, ולא אמר ה' אלקינו, משום שמשה היה מרכבה לאור הלבן ההוא שלמעלה, שהוא אינו שורף ואינו מכלה, שהוא מטעם הנ\"ל שאין בו אחיזה לדינים."],[7,"ת\"ח לית ליה אתערותא, לאתדלקא האי נהורא תכלא לאתאחדא בנהורא חוורא, אלא ע\"י ישראל,","בוא וראה, אין לו התעוררות לאור התכלת הזה, להדלק ולהתחבר באור הלבן, כי אם על ידי ישראל, \u0003דאינון מתדבקן ביה תחותוי,\u0004 שהם מתדבקים בו מתחתיו. דהיינו כמו הפתילה המתדבקת באור התכלת מתחתיו."],[8,"ות\"ח אע\"ג דאורחיה דהאי נהורא תכלא אוכמא לשיצאה כל מה דאתדבק ביה תחותוי:","ובוא וראה, אע\"פ שדרכו של אור תכלת שחור הזה, לכלות כל שנתדבק בו מתחתיו, עכ\"ז, \u0003ישראל מתדבקן ביה תחותוי וקיימן בקיומא, הה\"ד ואתם הדבקים וגו',\u0004 ישראל נדבקים בו מתחתיו ונמצאים בחיים, וז\"ש ואתם הדבקים בה' אלקיכם, \u0003בה' אלקיכם ולא אלקינו, בההוא נהורא תכלא אוכמא דאכיל ושצי כל מה דאתדבק ביה תחותיה, ואתון מתדבקן ביה וקיימי,\u0004 בה' אלקיכם כתיב, דהיינו בהנוקבא, ולא כתוב בה' אלקינו, שאז היה המשמעות בז\"א, שמשה מרכבה אליו כנ\"ל, והיינו שאמר להם, ואתם הדבקים באותו אור התכלת והשחור, השורף ומכלה כל מה שנדבק בו מתחתיו. ועכ\"ז, אתם דבקים בו ואתם חיים, \u0003דכתיב, חיים כלכם היום.\u0004 כי אור התכלת לא שרף ולא כלה אתכם."],[9,"ועל נהורא חוורא שרייא לעילא נהורא סתימא דאקיף ליה, ורזא עלאה הכא,","ועל אור הלבן שורה למעלה אור סתום המקיף אותו, ויש כאן סוד עליון. שזה רומז על אור עליון המקיף על ז\"א שהוא אור הלבן, שבו אין השגה תפיסא כלל. \u0003וכלא תשכח בשלהובא דסליק, וחכמתין דעליונין ביה,\u0004 ותמצא הכל, דהיינו אור התכלת, והלבן, ואור הסתים המקיף בשלהבת העולה מהנר, וחכמות העליונים מרומזות בו. \u0003אתא רבי פנחס ונשקיה, אמר בריך רחמנא דאיערענא הכא, אזלו עמיה דר' פנחס תלת מלין.\u0004 אתא רבי פנחס ונשקיה, אמר בריך רחמנא דאיערענא הכא, אזלו עמיה דר' פנחס תלת מלין."],[10,"אהדרו ר\"ש וחברייא, אר\"ש, הא דאמרן רזא דחכמתא איהו ביחודא קדישא:","חזרו ר\"ש והחברים אחר שלוו לר' פנחס. אר\"ש, זה שאמרנו הוא סוד החכמה ביחוד הקדוש, \u0003דבג\"כ ה\"א בתראה דשמא קדישא, איהו נהורא תכלא אוכמא, דאתאחיד ביה\"ו, דהוא נהורא חוורא דנהיר.\u0004 כי כמו כן, ה' אחרונה של השם הקדוש, שהיא הנוקבא, היא אור התכלת והשחור, המתחברת ביה\"ו דהיינו ז\"א, שהוא אור הלבן המאיר."],[11,"ת\"ח, לזמנין האי נהורא תכלא ד', ולזמנין ה':","בוא וראה, לפעמים אור התכלת הוא \u0003ד',\u0004 ולפעמים הוא \u0003ה'. אלא בזמנא דלא מתדבקן ביה ישראל לתתא לאדלקא ליה, לאתאחדא בנהורא חוורא איהו ד':\u0004 בעת שישראל אינם דבקים בה למטה, להדליק אותה ולחבר אותה באור הלבן, היא נבחנת לאות \u0003ד', ולזמנא דמתערי ליה לאתחברא עם נהורא חוורא כדין אקרי ה',\u0004 ובעת שישראל מעוררים אותה דהיינו שמעלים מ\"ן להתחבר עם אור הלבן, אז נקראת \u0003ה'.\u0004"],[12,"מנלן, דכתיב כי יהיה נערה בתולה, נער כתיב בלא ה', מאי טעמא, בגין דלא אתחברת בדכורא:","מאין לנו זה, משכתוב כי יהיה נערה וגו' וכתוב נער במסורה, בלי ה', מהו הטעם, הוא משום שלא נתחברה בזכר, \u0003ובכל אתר דלא אשתכחו דכר ונוקבא, ה', לא אשתכח, וסלקא מתמן ואשתאר ד'\u0004, ובכל מקום שאין שם זכר ונקבה, אין שם \u0003ה',\u0004 וע\"כ כתוב נער בלי ה', וה\u0003ה'\u0004 עלתה משם ונשארת הנוקבא אז באות \u0003ד',\u0004 המורה דלות ועניות."],[13,"דהא איהי כל זמנא דאתחברבנהורא חוורא דנהיר אקרי ה' דהא כדין כלא אתחבר כחדא:","שהרי כל זמן שמתחברת באור הלבן המאיר, היא נקראת \u0003ה',\u0004 כי אז הכל מחובר כאחד, \u0003איהי אתדבקת בנהורא חוורא, וישראל מתדבקן בה וקיימא תחותה לאדלקא לה וכדין, כלא חד,\u0004 הנוקבא מתדבקת באור הלבן, וישראל מתדבקים בה ועומדים מתחתיה להדליק אותה, דהיינו ע\"י המ\"ן שמעלים אל\"ה, ואז הכל אחד, כי ז\"א והנוקבא נתחברו, וישראל המעלים מ\"ן אל הנוקבא להדליק אותה, (כנ\"ל דף קנ\"ב ד\"ה והאי אתאחיד).אי את ולחברה עם הז\"א, שלולא המ\"ן שלהם לא היתה מתחברת, נמצאים מתחברים גם הם בהם, כי כל השיעור שהתחתון גורם בעליון זוכה בו גם הוא, ואז נעשו קב\"ה ושכינתיה וישראל אחד."],[14,"ודא הוא רזא דקרבנא, דתננא דסליק אתער ליה להאי נהורא תכלא לאדלקא:","וזה הוא סוד הקרבן. העשן העולה מהמערכה, מעורר את אור התכלת להדלק, \u0003וכד אתדלק אתחבר בנהורא חוורא, ושרגא דליק ביחודא חד,\u0004 וכשנדלק, נתחבר באור הלבן, והנר דהיינו השכינה, דולק ביחוד אחד. שהיא מתדבקת באור הלבן ובהעשן ונעשו שלשתם אחד."]],[[0,"","בֹּא רְאֵה, בַּשַּׁלְהֶבֶת שֶׁעוֹלָה יֵשׁ שְׁנֵי אוֹרוֹת. אֶחָד אוֹר לָבָן שֶׁמֵּאִיר, וְאֶחָד אוֹר שֶׁנֶּאֱחָז בָּהּ שָׁחֹר אוֹ תְכֵלֶת. אוֹתוֹ אוֹר לָבָן הוּא לְמַעְלָה וְעוֹלֶה בְּדֶרֶךְ יָשָׁר, וְתַחְתָּיו אוֹתוֹ אוֹר תְּכֵלֶת אוֹ שָׁחֹר שֶׁהוּא כִּסֵּא לְאוֹתוֹ לָבָן."],[1,"","וְאוֹתוֹ אוֹר לָבָן שׁוֹרֶה עָלָיו, וְנֶאֱחָזִים זֶה בָּזֶה לִהְיוֹת הַכֹּל אֶחָד. וְאוֹתוֹ אוֹר שָׁחֹר אוֹ גָוֶן תְּכֵלֶת שֶׁהוּא לְמַטָּה הוּא כִּסֵּא כָבוֹד לְאוֹתוֹ לָבָן, וְעַל זֶה סוֹד הַתְּכֵלֶת."],[2,"","וְכִסֵּא זֶה תְּכֵלֶת שָׁחֹר נֶאֱחָז בְּדָבָר אַחֵר לְהִדָּלֵק, שֶׁהוּא מִלְּמַטָּה, וְהַהוּא מְעוֹרֵר אוֹתוֹ לְהֵאָחֵז בָּאוֹר הַלָּבָן (העליון)."],[3,"","וְהַתְּכֵלֶת הַשָּׁחֹר הַזֶּה לִפְעָמִים חוֹזֵר לִהְיוֹת אָדם. וְאוֹתוֹ אוֹר לָבָן שֶׁעָלָיו לֹא מִשְׁתַּנֶּה לְעוֹלָמִים, שֶׁהֲרֵי הוּא תָּמִיד לָבָן, אֲבָל תְּכֵלֶת זֶה מִשְׁתַּנֶּה לַגְּוָנִים הַלָּלוּ. לִפְעָמִים תְּכֵלֶת אוֹ שָׁחֹר,"],[4,"","וְלִפְעָמִים אָדם, וְזֶה נֶאֱחָז לִשְׁנֵי צְדָדִים. נֶאֱחָז לְמַעְלָה בְּאוֹתוֹ אוֹר (עליון) לָבָן. נֶאֱחָז לְמַטָּה בַּדָּבָר הַהוּא שֶׁתַּחְתָּיו שֶׁמְּתֻקָּן בּוֹ לְהָאִיר (דברים ששמים לו להדליק) וּלְהֵאָחֵז בּוֹ."],[5,"","וְזוֹ אוֹכֶלֶת תָּמִיד וּמַשְׁמִידָה לְאוֹתוֹ דָבָר שֶׁשָּׂמִים לָהּ. שֶׁהֲרֵי בְּכָל מַה שֶּׁנִּדְבָּק בּוֹ לְמַטָּה וְשׁוֹרֶה עָלָיו, אוֹתוֹ אוֹר תְּכֵלֶת מַשְׁמִיד אוֹתוֹ וְאוֹכֵל אוֹתוֹ, מִשּׁוּם שֶׁדַּרְכּוֹ הִיא לְהַשְׁמִיד וְלִהְיוֹת אוֹכֵל, שֶׁהֲרֵי בּוֹ תְּלוּיָה הַשְׁמָדַת הַכֹּל, מָוֶת שֶׁל הַכֹּל. וְלָכֵן הִיא אוֹכֶלֶת כָּל מַה שֶּׁנִּדְבָּק בָּהּ לְמַטָּה."],[6,"","וְאוֹתוֹ אוֹר לָבָן שֶׁשּׁוֹרֶה עָלָיו לֹא אוֹכֵל וְלֹא מַשְׁמִיד לְעוֹלָמִים וְלֹא מִשְׁתַּנֶּה אוֹרוֹ, וְעַל זֶה אָמַר מֹשֶׁה כִּי ה' אֱלֹהֶיךְ אֵשׁ אֹכְלָה הוּא. אֹכְלָה וַדַּאי. אוֹכֵל וּמַשְׁמִיד כָּל מַה שֶּׁשּׁוֹרֶה תַחְתָּיו. וְעַל זֶה אָמַר ה' אֱלֹהֶיךְ וְלֹא אֱלֹהֵינוּ, מִשּׁוּם שֶׁמֹּשֶׁה בְּאוֹתוֹ אוֹר לָבָן שֶׁלְּמַעְלָה הָיָה שֶׁלֹּא הִשְׁמִיד וְלֹא אָכַל."],[7,"","בֹּא רְאֵה, אֵין לוֹ הִתְעוֹרְרוּת לְהִדָּלֵק הָאוֹר הַתְּכֵלֶת הַזֶּה לְהִתְאַחֵד בְּאוֹר לָבָן אֶלָּא עַל יְדֵי יִשְׂרָאֵל שֶׁהֵם נִדְבָּקִים בּוֹ תַּחְתָּיו."],[8,"","וּבֹא וּרְאֵה, אַף עַל פִּי שֶׁדֶּרֶךְ שֶׁל הָאוֹר תְּכֵלֶת וְשָׁחֹר הַזֶּה לְהַשְׁמִיד כָּל מַה שֶּׁנִּדְבָּק בּוֹ תַּחְתָּיו, יִשְׂרָאֵל נִדְבָּקִים בּוֹ תַּחְתָּיו וְעוֹמְדִים בְּקִיּוּם. זֶהוּ שֶׁכָּתוּב (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים. בַּה' אֱלֹהֵיכֶם וְלֹא אֱלֹהֵינוּ (אלא בה' אלהיכם), בְּאוֹתוֹ אוֹר תְּכֵלֶת שָׁחֹר שֶׁאוֹכֵל וּמַשְׁמִיד כָּל מַה שֶּׁנִּדְבָּק בּוֹ תַּחְתָּיו, וְאַתֶּם מִתְדַּבְּקִים בּוֹ וְקַיָּמִים, שֶׁכָּתוּב חַיִּים כֻּלְּכֶם הַיּוֹם."],[9,"","וְעַל הָאוֹר הַלָּבָן שָׁרוּי לְמַעְלָה אוֹר נִסְתָּר שֶׁמַּקִּיף אוֹתוֹ, וְסוֹד עֶלְיוֹן כָּאן. וְהַכֹּל תִּמְצָא בַּשַּׁלְהֶבֶת שֶׁעוֹלָה וְחָכְמוֹת שֶׁל הָעֶלְיוֹנִים בָּהּ. בָּא ר' פִּנְחָס וּנְשָׁקוֹ. אָמַר, בָּרוּךְ הָרַחֲמָן שֶׁנִּפְגַּשְׁנוּ כָּאן. הָלְכוּ עִם רַבִּי פִּנְחָס שְׁלֹשָׁה מִילִין."],[10,"","חָזְרוּ רַבִּי שִׁמְעוֹן וְהַחֲבֵרִים. אָמַר רַבִּי שִׁמְעוֹן, זֶה שֶׁאָמַרְנוּ סוֹד הַחָכְמָה הוּא בַּיִּחוּד הַקָּדוֹשׁ שֶׁמִּשּׁוּם כָּךְ הֵ\"א אַחֲרוֹנָה שֶׁל הַשֵּׁם הַקָּדוֹשׁ הוּא אוֹר תְּכֵלֶת שָׁחֹר שֶׁנֶּאֱחָז בְּיה\"ו, שֶׁהוּא אוֹר לָבָן שֶׁמֵּאִיר."],[11,"","בֹּא רְאֵה, לִפְעָמִים הָאוֹר הַתְּכֵלֶת ד', וְלִפְעָמִים ה'. אֶלָּא בִּזְמַן שֶׁלֹּא נִדְבָּקִים בּוֹ יִשְׂרָאֵל לְמַטָּה לְהַדְלִיק אוֹתוֹ לְהֵאָחֵז בָּאוֹר הַלָּבָן הוּא ד', וְלִפְעָמִים שֶׁמְּעוֹרְרִים אוֹתוֹ לְהִתְחַבֵּר עִם הָאוֹר הַלָּבָן, אָז נִקְרָא ה'."],[12,"","מִנַּיִן לָנוּ? שֶׁכָּתוּב (שם כב) כִּי יִהְיֶה נַעֲרָה בְתוּלָה. נַעֲרָ כָּתוּב בְּלִי ה', מָה הַטַּעַם? מִשּׁוּם שֶׁלֹּא הִתְחַבְּרָה בְּזָכָר, וּבְכָל מָקוֹם שֶׁלֹּא נִמְצָאִים זָכָר וּנְקֵבָה, הֵ\"א לֹא נִמְצֵאת וְעוֹלָה מִשָּׁם, וְנִשְׁאָר ד'."],[13,"","שֶׁהֲרֵי הִיא כָּל זְמַן שֶׁמִּתְחַבֶּרֶת בָּאוֹר הַלָּבָן שֶׁמֵּאִיר נִקְרֵאת ה', שֶׁהֲרֵי אָז הַכֹּל מִתְחַבֵּר כְּאֶחָד. הִיא נִדְבֶּקֶת בָּאוֹר הַלָּבָן, וְיִשְׂרָאֵל נִדְבָּקִים בָּהּ (למטה) וְעוֹמְדִים תַּחְתֶּיהָ לְהַדְלִיק אוֹתָהּ, וְאָז הַכֹּל אֶחָד."],[14,"","וְזֶהוּ סוֹד הַקָּרְבָּן, שֶׁהֶעָשָׁן שֶׁעוֹלֶה מְעוֹרֵר אוֹתוֹ לָאוֹר הַתְּכֵלֶת הַזֶּה לְהַדְלִיק. וּכְשֶׁנִּדְלָק, מִתְחַבֵּר בָּאוֹר הַלָּבָן, וְהַנֵּר דּוֹלֵק בְּיִחוּד אֶחָד."]]],[["וּבְגִין דְּאָרְחֵיהּ דְּהַאי נְהוֹרָא תִּכְלָא לְשֵׁיצָאָה וּלְמֶהוֵי אָכִיל כָּל מַה דְּאִתְדָּבַּק בֵּיהּ תְּחוֹתֵיהּ. כַּד רַעֲוָא אִשְׁתַּכַּח וּשְׁרַגָּא דָּלִיק בְּחִבּוּרָא חַד כְּדֵין כְּתִיב, (מלכים א י״ח:ל״ח) וַתִּפּוֹל אֵשׁ ה' וַתֹּאכַל אֶת הָעוֹלָה וְגו'. וּכְדֵין אִתְיְידַע דְּהַהִיא שְׁרַגָּא דָּלִיק בְּחִבּוּרָא חַד וְקִשּׁוּרָא חַד. נְהוֹרָא תִּכְלָא אִתְדַּבָּק בִּנְהוֹרָא חִוְּורָא וְאִיהוּ חַד. אָכִיל תְּחוֹתֵיהּ תַּרְבִּין וְעִלַּוָּון. דְּמַשְׁמַע דְּהָא לָא אָכִיל (נ\"א ואיהו ועלוון דהא לא אכיל) תְּחוֹתֵיהּ, אֶלָּא בְּזִמְנָא דְאִיהוּ סָלִיק (נ\"א דליק) וְכֹלָּא אִתְקַשַּׁר וְאִתְחַבַּר בִּנְהוֹרָא חִוְּורָא. וּכְדֵין שְׁלָמָא דְּעָלְמִין כֻּלְהוּ, וְכוֹלָּא אִתְקַשַּׁר בְּיִחוּדָא חַד.","וּלְבָתַר דְּסִיֵּים לְשֵׁיצָאָה תְּחוֹתֵיהּ הַאי נְהוֹרָא תִּכְלָא, מִתְדַּבְּקָן בֵּיהּ תְּחוֹתֵיהּ כַּהֲנֵי וְלֵיוָאֵי וְיִשְׂרָאֵל. אִלֵּין בְּחֶדְוָה דְשִׁיר. וְאִלֵּין בִּרְעוּתָא דְלִבָּא וְאִלֵּין בִּצְלוֹתָא. וְשָׁרְגָּא דָּלִיק עֲלַיְיהוּ. וְאִתְדַּבְּקוּ נְהוֹרִין כְּחַד וּנְהִירִין עָלְמִין וּמִתְבָּרְכִין עִלָּאִין וְתַתָּאִין.","וּכְדֵין וְאַתֶּם הַדְּבֵקִים בַּיְיָ אֱלהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם. וְאַתֶּם, אַתֶּם מִבָּעֵי לֵיהּ. אֶלָּא ו' לְאוֹסָפָא עַל תַּרְבִּין וְעִלַּוָּון דְּאִנּוּן מִתְדַּבְּקִין בֵּיהּ וְאָכְלִין וְשָׁצָאן. וְאַתּוּן מִתְדַּבְּקָן בֵּיהּ בְּהַהוּא נְהוֹרָא תִּכְלָא אוּכְמָא דְאָכְלָא וְאַתּוּן קַיָּמִין הֲדָא הוּא דִכְתִיב חַיִּים כֻּלְּכֶם הַיּוֹם.","(ס\"א ותכלת וארגמן), כָּל גְּוָונִין טָבִין לְחֶלְמָא, בַּר מִתִּכְלָא דְּאִיהוּ אָכִיל וְשָׁצֵי תָּדִיר. וְאִיהוּ אִילָנָא דְּבֵיהּ מוֹתָא וְשַׁרְיָא עַל עָלְמָא תַּתָּאָה. וּבְגִין דְכֹלָּא שָׁרְיָא תְּחוֹתֵיהּ אִיהוּ אָכִיל וְשָׁצֵי.","וְאִי תֵימָא הָכִי נָמֵי שָׁרְיָא בִּשְׁמַיָא לְעֵילָא וְכַמָּה חַיָּלִין אִנּוּן לְעֵילָא וְכֻלְהוּ (שצי ואכיל) קָיְימֵי. תָּא חֲזֵי, כָּל אִנּוּן דִּלְעֵילָא בְּהַהוּא נְהוֹרָא תִּכְלָא אִתְכַּלְּלָן. אֲבָל תַּתָּאֵי לָאו הָכִי דְּאִנּוּן מִלָּה גַּסָּה עָלְמָא (נ\"א אחרא לתתא על מה) דְּקָיְימָא וְשָׁרְיָא עֲלֵיהּ. וּבְגִין כָּךְ אָכִיל וְשָׁצֵי לוֹן. וְלֵית לָהּ מִלָּה אָחֳרָא לְתַתָּא בְּעָלְמָא דְּלָא אִשְׁתְּצֵי. בְּגִין דִּנְהוֹרָא תִּכְלָא שָׁצֵי לְכָל מַה דְּקָיְימָא עֲלֵיהּ.","בְּאַרְבְּעִין וְחָמֵשׁ גַּוְונֵי זִינֵי נְהוֹרִין אִתְפְּלִיג עָלְמָא. שִׁבְעָה מִתְפַּלְּגִין לְשִׁבְעָה תְּהוֹמִין. כָּל חַד בָּטַשׁ בִּתְהוֹמָא דִילֵיהּ וְאֲבָנִין מִתְגַּלְגְּלִין בְּגוֹ תְּהוֹמָא. וְעָיִיל הַהוּא נְהוֹרָא בְּאִנּוּן אֲבָנִין וּנְקַב לוֹן. וּמַיָא נָפְקוּ בְּהוּ וְשָׁקְעִין כָּל חַד וְחַד עַל תְּהוֹמָא וְחַפְיָיא לִתְרֵין סִטְרִין.","נָפְקוּ מַיָא בְּאִנּוּן נוּקְבִין וְעָאל נְהוֹרָא וּבָטַשׁ לְאַרְבַּע סִטְרֵי תְהוֹמָא. מִתְגַּלְגְּלָא נְהוֹרָא בַּחֲבֶרְתָּהּ וְאִעָרְעוּ בְּחַד וּפַלְגִין מַיִין","וְאֲחִידָן כָּל אִנּוּן שִׁבְעָה בְּשִׁבְעָה תְּהוֹמֵי. וְכָרָאן (ס\"א שראן) בַּחֲשׁוֹכֵי תְהוֹמָא. וְחֲשׁוּכֵי אִנּוּן אִתְעָרְבֵי בְּהוֹן. וְסָלְקִין מַיָא וְנָחֲתִין וּמִתְגַלְגְּלִין בְּאִנּוּן נְהוֹרִין. וְאִתְעָרְבוּ כְּחֲדָא נְהוֹרִין וַחֲשׁוֹכִין וּמַיִין וְאִתְעֲבִידוּ מִנַּיְיהוּ נְהוֹרִין דְּלָא אִתְחַזָּאן חֲשׁוֹכָאן.","בָּטַשׁ כָּל חַד בְּחַבְרֵיהּ. וּמִתְפַּלְּגִין לְשִׁבְעִין וְחָמֵשׁ צִנוֹרֵי תְּהוֹמָא וּבְהוּ נָגְדָן מַיָא. כָּל צִנּוֹרָא וְצִנּוֹרָא סָלִיק בְּקָלֵיהּ (ואתזעזען) וְאִזְדַּעְזְעָן תְּהוֹמִין. וְכַד הַהוּא קָלָא אִשְׁתְּמַע, כָּל תְּהוֹמָא קָרֵי לְחַבְרֵיהּ וְאָמַר פַּלִּיג מֵימָךְ וְאֵעוּל בָּךְ. הֲדָא הוּא דִכְתִיב, (תהילים מ״ב:ח׳) תְּהוֹם אֶל תְּהוֹם קוֹרֵא לְקוֹל צִנּוֹרֶיךָ.","תְּחוֹת אִלֵּין תְּלַת מְאָה (נ\"א ושתין) וּתְמָנִין (וחמשה) גִּידִין. מִנְהוֹן חִוְּורִין מִנְהוֹן אוּכְמִין מִנְהוֹן סוּמְקִין. אִתְכְּלִילוּ דָּא בְּדָא וְאִתְעֲבִידוּ גַּוָּון חָד. אִנּוּן גִּידִין אִתְרְקִימוּ בִּשְׁבַע עֶשְׂרֵה רְשָׁתוֹת. וְכָל חַד רֶשֶׁת גִּידִין אִקְרֵי (אתקיימו) אִתְרְקִימוּ דָּא בְּדָא וְנַחֲתִין בְּשִׁפּוּלֵי תְּהוֹמֵי. תְּחוֹת אִלֵּין. תְּרֵין רִשְׁתִּין קָיְימִין כְּחֵיזוּ דְּפַרְזְלָא. וּתְרֵין רִשְׁתִּין אָחֳרָנִין כְּחֵיזוּ דִּנְחָשָׁא.","תְּרֵין כָּרְסְוָון קָיְימֵי עֲלַיְיהוּ חַד מִיָּמִינָא וְחַד מִשְּׂמָאלָא. כָּל אִנּוּן רִשְׁתִין מִתְחַבְּרָן כְּחֲדָא וּמַיִין נָחֲתִין מֵאִנּוּן צִנּוֹרִין וְעָאלִין בְּאִלֵּין רִשְׁתִּין. אִנּוּן תְּרֵי כָּרְסְוָון חַד כֻּרְסְיָיא דִרְקִיעָא אוּכְמָא, וְחַד כֻּרְסְיָיא דִּרְקִיעָא סַסְגוֹנָא.","אִלֵּין תְּרֵין כָּרְסְוָון כַּד אִנּוּן סָלְקִין סָלְקִין (בחד) בְּהַהוּא כֻּרְסְיָיא דִּרְקִיעָא אוּכְמָא. וְכַד נָחֲתִין נָחֲתִין בְּהַהוּא כֻּרְסְיָיא דִּרְקִיעָא סַסְגוֹנָא.","אִלֵּין תְּרֵין כָּרְסְוָון חַד מִיָּמִינָא וְחַד מִשְּׂמָאלָא. וְהַהוּא כֻּרְסְיָיא דִּרְקִיעָא אוּכְמָא מִיָּמִינָא. וְהַהוּא כֻּרְסְיָיא דִּרְקִיעָא סַסְגוֹנָא מִשְּׂמָאלָא. כַּד סָלְקִין בְּכֻּרְסְיָיא דִרְקִיעָא אוּכְמָא, מָאִיךְ כֻּרְסְיָיא דִּרְקִיעָא שְׂמָאלָא וְנָחֲתִין בֵּיהּ."],[[0,"ובגין דארחיה דהאי נהורא תכלא לשיצאה ולמהוי אכיל כל מה דאתדבק ביה תחותיה כד רעוא אשתכח ושרגא דליק בחבורא חד:","ומשום שדרכו של אור תכלת הזה לכלות ולשרוף כל מה שנתדבק בו מתחתיו, אז כאשר נמצא עת רצון והנר דולק ביחוד אחד, \u0003כדין כתיב ותפול אש ה' וגו' וכדין אתיידע דההיא שרגא דליק בחבורא חד וקשורא חד,\u0004 אז כתוב ותפול אש ה' ותאכל את העולה וגו'. ואז, כאשר נשרף הכל מתחתיו, נודע שהנר, דהיינו השכינה, דולק בחיבור אחד. ויחוד אחד. כי \u0003נהורא תכלא אתדבק בנהורא חוורא ואיהו חד.\u0004 מבאר איך הם אחד, ואומר אור התכלת שהיא הנוקבא, נתחבר עם אור הלבן, שהוא ז\"א, ונעשו שניהם אחד. וכן אור התכלת \u0003אכיל תחותיה תרבין ועלוון, דמשמע דהא לא אכיל תחותיה אלא בזמנא דאיהו סליק,\u0004 וכן אור התכלת אוכל ושורף מתחתיו חלבים ועולות, שמשמע שאינו אוכל ושורף מתחתיו אלא דוקא בזמן שהיא עולה לאור הלבן. נמצא, \u0003וכלא אתקשר ואתחבר בנהורא חוורא, וכדין שלמא דעלמין כלהו, וכלא אתקשר ביחודא חד,\u0004 ונמצא שהכל, דהיינו העשן ואור התכלת, נקשר ונתחבר באור הלבן, ואז נמשך השלום בכל העולמות, והכל נקשר ביחוד אחד."],[1,"ולבתר דסיים לשיצאה תחותיה, האי נהורא תכלא, מתדבקן ביה תחותיה כהני וליואי וישראל:","ואחר שאור התכלת גמר לשרוף ולכלות הכל מתחתיו, באים ומתדבקים בו אז, כהנים ולוים וישראלים, \u0003אלין בחדוה דשיר, ואלין ברעותא דלבא, ואלין בצלותא,\u0004 אלו בחדוה של שירים, שהם הלוים המשוררים. ואלו בכוונת הלב, הם הכהנים. ואלו בתפלה, הם ישראל, \u0003ושרגא דליק עלייהו, ואתדבקו נהורין כחד, ונהירין עלמין ומתברכין עלאין ותתאין,\u0004 והנר דהיינו השכינה דולק עליהם ומאירה. ומתדבקים האורות כאחד, כנ\"ל, והעולמות מאירים, והעליונים ותחתונים מתברכים."],[2,"וכדין, ואתם הדבקים וגו' ואתם אתם מבעי ליה, אלא ו' לאוספא על תרבין ועלוון:","ואז נאמר על ישראל, ואתם הדבקים בה' אלקיכם חיים כלכם היום, ושואל, כתוב ואתם, עם ו' בתחלת המלה, הלא אתם, צריך לומר, דהיינו בלי ו'. ומשיב, אלא \u0003ו'\u0004 הוא להוסיף על מעלת החלבים והעולות, \u0003דאינון מתדבקין ביה ואכלין ושצאן, ואתון מתדבקן ביה בההוא נהורא תכלא אוכמא דאכלא, ואתון קיימין הה\"ד חיים כלכם היום,\u0004 כי החלבים ועולות המתדבקים באור התכלת ונאכלים ונשרפים, ואתם מתדבקים באור התכלת שחור, השורף ואוכל, ואתם חיים. וז\"ש חיים כלכם היום. והוספה זו מרומזת בה\u0003ו'\u0004 של ואתם."],[3,"כל גוונין טבין לחלמא בר מתכלא, דאיהו אכיל ושצי תדיר, ואיהו אילנא דביה מותא:","כל הצבעים הנראים בחלום סימן טוב הם, לבד מצבע התכלת, שהוא אוכל ומכלה תמיד, והוא האילן שבו המות, דהיינו הנוקבא, שהיא עץ הדעת טו\"ר, כנ\"ל. \u0003ושריא על עלמא תתאה, ובגין דכלא שריא תחותיה, איהו אכיל ושצי,\u0004 והוא שורה על עולם התחתון, דהיינו עוה\"ז, ומשום שהכל שורה מתחתיו, הוא אוכל ומכלה אותם."],[4,"ואי תימא, הכי נמי שריא בשמיא לעילא, וכמה חיילין אינון לעילא וכלהו קיימי.","ואם תאמר, היא דהיינו הנוקבא דז\"א, שורה ג\"כ בשמים ממעל, דהיינו בעולם האצילות, וכמה צבאות הם בבי\"ע המתפשטים מהנוקבא, ועכ\"ז הם חיים וקיימים, ואיך אתה אומר, שאור התכלת, שהיא הנוקבא דז\"א, אוכל ומכלה כל מה שמתחתיה. \u0003ת\"ח כל אינון דלעילא בההוא נהורא תכלא אתכללן, אבל תתאי לאו הכי דאינון מלה גסה, עלמא דקיימא ושריא עליה:\u0004 ומתרץ. בוא וראה, כל אלו הצבאות של מעלה, דהיינו בג' עולמות בי\"ע שלמעלה מעוה\"ז, הם נכללים באור התכלת עצמו, ואינם מתחתיו, אבל התחתונים מעוה\"ז, אינם כן, אינם נכללים באור התכלת עצמו, כי הם דבר הגס, שהעולם עומד ושורה עליו, כלומר שנאחז בו ומתקיים על ידו כהאור בהפתילה כנ\"ל, וזולתו לא היה העולם מתקיים. \u0003ובג\"כ אכיל ושצי לון, ולית לה מלה אחרא לתתא בעלמא דלא אשתצי, בגין דנהורא תכלא שצי לכל מה דקיימא עליה.\u0004 וע\"כ, אוכל ומכלה אותם, ואין לך דבר למטה בעולם התחתון, שלא יכלהו משום שאור התכלת מכלה כל מה שמתחתיו."],[5,"בארבעין וחמש גווני זיני נהורין אתפליג עלמא:","במ\"ה צבעים ומיני אורות נחלק העולם, שהיא הנוקבא דז\"א. פירוש. הבינה נקראת מ\"י, והנוקבא נקראת מ\"ה. כנ\"ל (בהקדמת הזהר דף י\"ח אות יוד) שאומר מ\"י קצה השמים לעילא ומ\"ה קצה השמים לתתא. והטעם שהנוקבא נקראת מ\"ה. הוא להורות שחסרים לה ה' שערים האחרונים מנ' שערי בינה, ואין לה אלא מ\"ה שערים. כי סוד נ' שערי בינה, הם ה' ספירות כח\"ב תו\"מ, שכל אחת מהן כלולה מעשר, שה\"ס ה' פרצופין שלימים, המלבישים זה על זה. אבל הנוקבא, אין לה רק חציה של פרצוף המלכות שלה, דהיינו מחזה ולמעלה, וחצי פרצוף התחתון של המלכות, דהיינו מחזה ולמטה, אין לה, ונבחן, שיש לה ארבעים שערים מד' הפרצופין, כח\"ב ות\"ת, וחמשה שערים מפרצוף המלכות, שהם מחזה ולמעלה, והם ביחד רק מ\"ה בלבד, כי חסר לה חצי פרצוף התחתון של המלכות. גם נודע שד' הספירות חו\"ב תו\"מ ה\"ס ד' צבעים לבן אדום ירוק שחור, וז\"ש \u0003במ\"ה גווני זיני נהורין אתפליג עלמא,\u0004 דהיינו הנוקבא, כי חסרים לה ה' גוונין תתאין. ומ\"ש \u0003זיני,\u0004 ואינו מסתפק לומר \u0003במ\"ה גווני,\u0004 הוא משום שגם עשרה כתרים נכללים במ\"ה נהורין הללו, והכתר הוא למעלה מכל צבע, ועל בחינת הכתרים שבהם, אומר \u0003זיני נהורין,\u0004 כי אינם בכלל גוונים."],[5,"","ולא יקשה לך מ\"ש לעיל (בהקדמת הזהר דף נ\"ח ד\"ה אגליפו) שהם מ\"ט שערים בהנוקבא, ורק שער א', מלכות דמלכות, חסר לה, וכאן אומר שאין לה רק \u0003מ\"ה גווני זיני נהורין\u0004 וה' בחינות חסרות לה. והענין הוא, כי ב' בחינות עקריות הם בהמלכות, שהן ט\"ס ראשונות שבה והמלכות שבה. הט\"ס ראשונות שבה נבחנות למדת הרחמים, להיותן באות מהתכללות העליונים ממנה, ואינן שלה. אבל המלכות שבה נבחנת למדת הדין להיותה בחינתה עצמה, שמדת הדין שורה עליה מצמצום הראשון. ונודע שסוד הפרסא שבמקום החזה דכל פרצוף, ה\"ס עלית המלכות מסיום הפרצוף למקום החזה שבו. (כמ\"ש בפתיחה לחכמת הקבלה אות ס\"ז ובפרטיות כן הוא בכל פרצוף עש\"ה) ולפיכך כל חציו התחתון של הפרצוף נבחן לבחינת מלכות שלו, כי המלכות שבהפרסא שולטת עליו. ולפי\"ז נמצא שמחזה ולמטה דפרצוף מלכות שבה, אפשר לחשבו לה' ספירות תחתוניות שבה דהיינו ב\"ש ת\"ת ונהי\"מ. וע\"כ אומר כאן שחסרים לה ה' גווני נהורין. ואפשר לחשבם לספירה אחת, כי המלכות דמלכות כבר שולטת במקום הפרסא שבחזה, וכל ה\"ס הללו כאחת הן, וע\"כ אומר שם שחסר לה רק שער אחד. והנה נתבאר שבפרצוף המלכות אין שם אלא מ\"ה נהורין, מה\"פ כח\"ב תו\"מ שבה המלבישים זה על זה. מטעם שבפרצוף החמישי שלה חסר מדת הדין, שהם ה\"ס תנהי\"מ שמחזה ולמטה, ואין שם אלא מבחינת מדת הרחמים שלו, שה\"ס מחזה ולמעלה. אבל הבינה יש לה נ' שערים. כי גם מחזה ולמטה דפרצוף החמישי שלה נבחן ג\"כ למדת הרחמים, כי הבינה כולה הוא רחמים וכן ז\"א, כי מדת הדין דצמצום א' לא היה אלא בהמלכות."],[5,"","ודע שמטרת המאמר שלפנינו הוא לבאר בדיוק, מקום חטאו של אדה\"ר בעץ הדעת, וענין פיתוי הנחש מה הוא. ולפיכך מציין בתחילת המאמר בדרך כלל מקום חסרונה של המלכות, דהיינו החסרון של חצי פרצוף התחתון של מלכות שלה, שאין לה רק \u0003מ\"ה גווני זיני נהורין,\u0004 ואח\"ז מבאר שז\"א יש לו נ' בחינות אורות בשלמות, כי יש לו ה' פרצופים כח\"ב תו\"מ בשלמות, שאפילו פרצוף המלכות שלו יש לה ע\"ס, דהיינו שיש לו מלכות \u0003דב' סטרין,\u0004 הן סטרא דרחמים שמחזה ולמעלה והן סטרא דדין שמחזה ולמטה, כמ\"ש בדיבור הסמוך. ואח\"ז הולך ומבאר פרטי בנין הנוקבא, וסדרי זווגה עם ז\"א, ומציין בכל פרט את התוצאות המגיעות מכח חסרון מדת הדין של פרצוף המלכות שלה. שמזה בא לבחר מקום החטא של עצה\"ד, וטעמו, כמ\"ש באות רפ\"ה ואילך."],[5,"שבעה מתפלגין לשבעה תהומין, כל חד בטש בתהומא דיליה:","ז' ספירות מתחלקים לז' תהומות, כל אחד הכה בתהום שלו. פירוש. ז\"א מכונה בשם שבעה, או ז' תחתונות, דהיינו חג\"ת נהי\"מ, כי אפילו בעת גדלות שמשיג חב\"ד, אינם ג\"ר אמיתיים, אלא החג\"ת שלו נעשו לחב\"ד כנודע. ונמצא בגדלות שיש לו עשר ספירות, עוד אין בו יותר מז' ספירות חג\"ת נהי\"מ, אלא החג\"ת נעשו לחב\"ד, ונה\"י לחג\"ת, ובאו לו נה\"י חדשים, והם ע\"ס. גם נודע שדרך יציאת כל מדרגה הוא, שאור העליון הכולל ט\"ס, מכה על המסך שבהמלכות ומעלה או\"ח המלביש את אור העליון ממטה למעלה, ואלו נבחנים לע\"ס דראש המדרגה, ואח\"כ מתהפך המסך שבמלכות והע\"ס דאו\"י ואו\"ח שבראש מתפשטים ממעלה למטה אל הגוף."],[5,"","וז\"ש \u0003שבעה,\u0004 דהיינו חג\"ת נהי\"מ דז\"א, \u0003מתפלגין לז' תהומין,\u0004 כי נכללים זה מזה, ויוצאים ז' פרצופין חג\"ת נהי\"מ, שיש בכל אחד מהם ז' ספירות חג\"ת נהי\"מ, ונמצא שיש בכל פרצוף בחינת מלכות הנקראת תהום, ומהם ז' מלכיות, המכונות ז' תהומות. \u0003כל חד בטש בתהומא דיליה,\u0004 כל אחד מכה בתהום שלו, דהיינו בהמלכות, ומעלים ע\"ס דאו\"ח ומלבישים הע\"ס דיושר, והם הנקראים ע\"ס דראש. ואח\"ז, \u0003ואבנין מתגלגלין בגו תהומא, ועייל ההוא נהורא באינון אבנין ונקב לון ומיא נפקו בהו,\u0004 והאבנים דהיינו המסכים שבז' המלכיות מתהפכים תוך המלכות, דהיינו שמתהפכים להאיר ממעלה למטה כנ\"ל, ונכנס האור באלו האבנים, שהן המסכים, ונוקב אותן, והמים יוצאים דרך הנקבים. וענין התהפכות האור להאיר ממעלה למטה, נבחן, כמו שהאור נוקב את המסך המעכב עליו שלא יתפשט למטה \u0003ושקעין כל חד וחד על תהומא,\u0004 והמים יורדים ושוקעים כל אחד על תהום שלו. פירוש. שהתהום של כל אחד ואחד שהיא המלכות, מתפשט מניה וביה לעשר ספירות ממעלה למטה, והמים, שהם האור, יורדים ושוקעים בהם עד שבאים להמלכות שלהם, ומסתיים האור שם. (כמ\"ש בפתיחה לחכמת הקבלה אות כ\"ז בא\"ק, וכן הוא בכל המדרגות) \u0003וחפייא לתרין סטרין,\u0004 והמסך מכסה לב' צדדים של התהום, שהוא המלכות, דהיינו לסטרא דחסד של המלכות שהוא מחזה ולמעלה שלה, ולסטרא דמדת הדין של המלכות שהוא מחזה ולמטה שלה כנ\"ל בדבור הסמוך, וע\"כ יש לו לז\"א \u0003נ' זיני נהורין,\u0004 אבל הנוקבא, חסרה מסטרא דמדת הדין שלה ואין לה אלא \u0003חד סטרא,\u0004 שהוא סטרא דחסד, שמחזה ולמעלה, כמ\"ש לעיל בדבור הסמוך, וע\"כ אין לה אלא \u0003מ\"ה זיני נהורין.\u0004 ונתבאר סדר אצילות של ז\"א, שהוא בב' סטרין של המלכות."],[6,"נפקו מיא באינון נוקבין ועאל נהורא ובטש לארבע סטרי תהומא:","עתה מביא סדר אצילות הנוקבא, שהוא על חד סטרא. ואומר, המים יוצאים דרך אותם הנקבים שבאבנים דז\"א הנ\"ל, שהאורות מאירים דרך שם ממעלה למטה (כנ\"ל בדיבור הסמוך) ואור העליון מא\"ס נכנס בהם ומכה לד' הבחינות שבתהום. שהוא תהום הכולל, דהיינו שמכה לד' הבחינות חו\"ב תו\"מ שבהמלכות הכוללת, שהיא הנוקבא דז\"א. ועל ידי הכאה זו נאצלות הע\"ס חו\"ב תו\"מ, של הנוקבא. \u0003מתגלגלא נהורא בחברתה, ואערעו בחד, ופלגין מיין,\u0004 כל אור מד' הבחינות, נכלל בחבירו, בשעת ההכאה ונעשו בה ד' פרצופים שבכל אחד חו\"ב תו\"מ, המלבישים זה על זה (כמ\"ש לעיל בדיבור הסמוך בזווג דהכאה לצורך בנין ז\"א ע\"ש) ונפגשים בצד אחד של המלכות, דהיינו רק בהמלכות דמדת הרחמים המספקת לחצי פרצוף שמחזה ולמעלה, (כנ\"ל דף קנ\"ח ד\"ה בארבעין) ולפיכך, \u0003ופלגין מיין,\u0004 המים, שהם האורות המושפעות לה מן ז\"א, מתחלקים בה, ואינה מקבלת אלא החלק מחזה ולמעלה של כל פרצוף. כי מטעם שחסר בה צד המלכות דמדת הדין, אינה יכולה לקבל את החלק שמחזה ולמטה מן ז\"א, כי אינו מאיר אלא על המלכות דמדת הדין. כנ\"ל ע\"ש."],[6,"","והטעם שבאצילות ז\"א אומר \u0003שבעה,\u0004 שהם חג\"ת נהי\"מ, וכאן בהנוקבא אומר רק \u0003ארבע סטרי,\u0004 הענין הוא, כי ב' ירידות יש בד' הבחינות חו\"ב תו\"מ. כי חו\"ב תו\"מ ממש, אינם אלא בג\"ר, אבל בז\"א ירדו חו\"ב ונעשו בו לחסד וגבורה, דהיינו לבחינת חסדים, ונבחנים ד' הבחינות שבו לחו\"ג תו\"מ. ובהנוקבא, יורדים ירידה שניה, כי חו\"ג דז\"א נעשו בה לנצח והוד, והת\"ת דז\"א ליסוד, וע\"כ ד' בחינות שבה נבחנים לנצח הוד יסוד ומלכות. באופן שבג\"ר הם חו\"ב תו\"מ. ובז\"א הם חו\"ג תו\"מ. ובהנוקבא הם נהי\"מ וההפרש ביניהם רב מאד. כי חו\"ב הם חכמה ממש ובינה ממש, אבל בז\"א שנעשו לחו\"ג, ירדה החכמה ובינה ונעשו לחסדים וגבורות, כי הכלים שלו אינם מקבלים עוד חכמה. אבל חסדים יש בהם בשפע גדול, שז\"ס שמכנים את החג\"ת לכלים רחבים. כי מדת הרוחב רומזת על החסדים, ומדת האורך על חכמה, וכשירדו להנוקבא ונעשו לנצח והוד, כבר נתקצרו הכלים, כלומר שנצטמצמו משפע החסדים, אבל נבחנים לכלים ארוכים, כלומר שראוים לקבל הארת החכמה, המכונה ארוכה. באופן, שבג\"ר שבהם חו\"ב תו\"מ, יש אור החכמה ממש, דהיינו חכמה דאור ישר. אבל בחו\"ג תו\"מ דז\"א, אין שם אלא חסדים ובהנוקבא, יש רק הארת חכמה, הנמשכת מבינה שחזרה להיות חכמה ע\"י עלייתה לא\"א, ואינה חכמה ממש כמו בג\"ר."],[6,"","ונודע שהעליון כולל בתוכו את כל התחתונים ממנו, להיותם עוברים על ידו ומושפעים להתחתונים, וכיון שעברו דרכו, נשארים בו, כי אין העדר ברוחני, וע\"כ נמצאים שורשי כל תחתון בהעליון ממנו. (כמ\"ש בתלמוד ע\"ס חלק ב' בהסתכלות פנימי דף ע\"ה ד\"ה וטעם ע\"ש) ולפיכך נבחנות כל אחד מהנ\"ר, שיש בו עשר ספירות שלימות, כח\"ב חג\"ת נהי\"מ, כח\"ב יש להם מעצמם, כי ד' בחינות שלהם הם חו\"ב תו\"מ, וחג\"ת יש בהם מד' בחינות חו\"ג תו\"מ דז\"א, ונהי\"מ מד' בחינות חו\"ב תו\"מ של הנוקבא. אבל ז\"א כבר חסר כח\"ב, כי ד' בחינותיו הם חו\"ג תו\"מ הנקראות חג\"ת, אלא להיותו כולל את הנוקבא, הרי יש לו ג\"כ נהי\"מ דנוקבא, וע\"כ נבחן \u0003לשבעה\u0004 ספירות חג\"ת נהי\"מ. אבל הנוקבא, כבר חסרה החסדים המרובים שבחג\"ת, כי חו\"ג דז\"א נתמעטו אצלה לנו\"ה, וע\"כ אין בה אלא נהי\"מ בלבד, והוא נקרא משום זה \u0003ד',\u0004 להורות שאין בה אלא ד' ספירות נהי\"מ, וחסרה מו\"ס ראשונות כח\"ב חג\"ת. ולפיכך מכנה הזהר כאן את ז\"א במספר \u0003שבעה,\u0004 ואת הנוקבא במספר ארבע."],[7,"ואחידן כל אינון שבעה בשבעה תהומי וכראן בחשוכי תהומא:","ואוחזים כל שבעה הספירות דז\"א בשבע מלכיות שלהם, כי כל אחת כלולה מז' וע\"כ יש בכל אחת מהם ספירת המלכות, וז' מלכיות הללו נבחנות לקו שמאל דז\"א, והן כורים בחשך את התהום שהיא הנוקבא דז\"א. כלומר שממשיכים אליה הארת השמאל מנקודת השורק שבאמא, שה\"ס חשך (כנ\"ל ב\"א דף מ\"ז ד\"ה נפק)ובזה נחקקה הנוקבא בסוד החשך דאמא. שהסו\"ה ב'אר ח'פרוה ש'רים כ'רוה, וגו' שהר\"ת של מלות הללו הוא אותיות בחש\"ך. כי \u0003באר\u0004 היא הנוקבא \u0003חפרוה שרים,\u0004 היינו חג\"ת דז\"א המכונים שרים, ונבחנים לז\"ס כנ\"ל. והמשכת החשך דאמא ה\"ס החפירה והחקיקה של ז\"א. \u0003וחשוכי אינון אתערבי בהון\u0004 וחשכות הללו נתערבו בכל ספירות הנוקבא. \u0003וסלקין מיא\u0004 והמים עולים ממטה למעלה, כלומר אור החסדים הנקרא מים, שה\"ס קו ימין, מאיר תחילה ממטה למעלה בסוד נקודת החולם. \u0003ונחתין ומתגלגלין באינון נהורין,\u0004 ואח\"כ יורדים החסדים לקו שמאל, ומתחברים שם בהאורות דשמאל, דהיינו באור החכמה שבסוד נקודת השורק. ואע\"פ שאור זה הוא חשך שם, אבל הוא מטעם, שאין החכמה יכולה להאיר בלי לבוש החסדים, ונמצא עתה בעת שהחסדים יורדים לקו שמאל, חוזר ונתעורר שם הארת החכמה ומתגלגלים זה בזה. \u0003ואתערבו כחדא נהורין וחשוכין ומיין, ואתעבידו מנייהו נהורין דלא אתחזאן, חשוכאן.\u0004 ומתערבים ביחד, אורות וחשכות ומים, ונעשה מהם האורות שאינם נראים, שהם חשכים. כלומר, שמהתכללות הזו של האורות והחשכות והמים זה בזה, נבנה פרצוף הנוקבא דגדלות, הנבחנת משום זה, לאורות שאינם נראים וחשכים, ונקראת בשם \u0003אספקלריא שאינה מאירה.\u0004"],[8,"בטש כל חד בחבריה, ומתפלגין לשבעין וחמש צנורי תהומא ובהו נגדן מיא:","הכה כל אחד מז' תהומות דז\"א, בהבחינה שכנגדו בהתהום דנוקבא, ומתחלקים לע\"ה צנורות התהום, ובהם נמשכים מים, שהם האורות. פירוש. הקומה היוצאת מזווג הזה, מתחלקת על החזה, שמחזה ולמעלה הוא מבחינת ז\"א בעיקר, וע\"כ נבחן שהם ע\"ה צנורות. ומחזה ולמטה הוא בחינת הנוקבא בעיקר, וע\"כ הם שס\"ה גידין. וטעם המספרים הוא, כי כל זווג נוסף מכפיל בעשרה (כמ\"ש להלן באות רפ\"א ד\"ה שבעה) וע\"כ הם מתחלקים לע\"ה צנורות התהום, כי הז' תהומות, שהם ז' מלכיות דז\"א נעשים ע' וכן נכפלה כל ספירה שלו, והם שבע מאות. והתהום דנוקבא לא נעשה עשרה, אלא חמשה. והוא מטעם שחסר לה חצי המלכות דמדת הדין, וחסרה משום זה, חמשה צנורי תהומא, השייכים לחצי המלכות הזו דמדת הדין. ובהם נמשכים המים, דהיינו האורות. כי מע' צנורות התהום דז\"א מושפע לחמשה צנורות התהום של הנוקבא, ומחמשה צנורות התהום של הנוקבא מושפע לכל המציאות. והטעם שנקראים צנורות, הוא כי כל מדרגה אינה משפעת רק בהתהום שלה, דהיינו בהמלכות, וע\"כ נקראים התהומות בשם צנורות, דהיינו מושכי השפע מעליון לתחתון. וטעם מספר שס\"ה יתבאר להלן."],[8,"כל צנורא וצנורא סליק בקליה ואזדעזען תהומין.","כל צנור וצנור עולה בקולו ומזדעזעים התהומות, דהיינו התהומות של המקבל. פירוש כי נותן טעם למה אין בהנוקבא רק חמשה תהומות, ואומר, שכל צנור וצנור של ע' צנורות דז\"א עולה להשפיע בקול שלו המיוחד. פי' המשפיע, שהוא ז\"א, נקרא קול, והנוקבא המקבלת, נקראת דיבור. וב' מיני השפעות יש בז\"א, שהם מכונים ב' קולות, א) קול דמדת הרחמים, דהיינו בינה, המשפיע בחצי המלכות דמדה\"ר, הנקראת דיבור. ב) קול דמדת הדין, דהיינו מלכות דמה\"ד הנכללת בו, המשפיע בחצי המלכות דמה\"ד. כי בז\"א יש ב' בחינות המלכיות (כנ\"ל דף קנ\"ט ד\"ה וז\"ש ע\"ש) ולפיכך יש בז\"א צנורות אשר הקול שלהם הוא ממדה\"ר, ויש בו צנורות שהקול שלהם הוא ממדה\"ד. וז\"ש \u0003כל צנורא וצנורא סליק בקליה,\u0004 מהם בקול דמדת הרחמים, ומהם בקול דמדת הדין, ולפיכך, \u0003ואזדעזען תהומין,\u0004 היינו התהומין של הנוקבא, שחסרים מחצי המלכות דמדת הדין, הם מזדעזעים, כי אין להם מקום לקבל אותם הקולות דמדה\"ד. \u0003וכד ההוא קלא אשתמע כל תהומא קרי לחבריה ואמר, פליג מימך ואעול בך, הה\"ד\u0004 וכו', וכשנשמע קול ההוא דמדה\"ד, כל תהום קורא לחברו ואומר, חלוק את מימיך ואכנס בך. פירוש. כי ע' תהומות דז\"א כלולים זה מזה, ויש בכל אחד ב' מיני קולות, וכן העשרה תהומות של הנוקבא כלולים זה מזה, ולפיכך כל תהום מע' צנורות התהום דז\"א, קורא לתהום שכנגדו בהנוקבא, שיחלוק את השפע שהוא יתן לו דהיינו שיקבל רק לחצי התהום שמחזה ולמעלה, ששם שולטת חצי המלכות דמדת הרחמים, ולא יקבל השפע השייך לחצי התהום שמחזה ולמטה. ששם אין המלכות מתוקנת, כי חסר לה תקון הצי המלכות דמה\"ד, השייכת להמקום שמחזה ולמטח, וע\"כ חלק הזה הוא בחסרון אצלה, כנ\"ל, וז\"ש \u0003תהום אל תהום קורא,\u0004 דהיינו תהום של הז\"א קורא להתהום שכנגדו בהנוקבא, \u0003לקול צנוריך,\u0004 בעת שנשמע קול הצנורות דמדת הדין, והוא קורא לו ואומר \u0003פליג מימך ואעול בך,\u0004 כנ\"ל. ונמצא שעשרה תהומות של הנוקבא נתחלקו, שהחמשה שמחזה ולמעלה של הנוקבא קבלו את שפעם, משום שיש לה שם כלי קבלה מתוקנים, והחמשה שמחזה ולמטה לא יוכלו לקבל שפעם, שאין שם כלי קבלה מתוקנים. וע\"כ נמצא שמספר הצנורות הם ע\"ה, ע' לז\"א ורק ה' להנוקבא, דהיינו רק החמשה שמחזה שלה ולמעלה. כמבואר."],[9,"תחות אלין, תלת מאה ושתין וחמשה גידין, מנהון חוורין מנהון אוכמין מנהון סומקין:","תחת אלו ע\"ה צנורות, יוצאים שס\"ה גידים, מהם שהם לבנים, מהם שחורים, ומהם אדומים. \u0003אתכלילו דא בדא ואתעבידו גוון חד.\u0004 נכללו זה בזה ונעשו לצבע אחד. פירוש. כי כבר נתבאר לעיל ד\"ה בטש, שבחינת מחזה ולמטה דקומת הזווג הנ\"ל, הוא כולו מבחינת הנוקבא בעיקר, אלא רק שבו התכללות מז\"א. ומטרם הזווג היה בה ד' פרצופין מסוד ד' סטרי תהומי, שכל אחד היה בו עשרה ספירות, אלא פרצוף הד' לא היה בו אלא ה' ספירות שמחזה ולמעלה בלבד. כנ\"ל ע\"ש. וע\"כ עתה שכל ספירה נכפלה לעשרה בסוד הזווג, הרי נעשו ש\"נ, והתכללות שבו מז\"א, דהיינו מחזה ולמעלה, ששם מאיר י\"ה של הקומה, שהיא בגי' ט\"ו, היא נוספת על מספר ש\"נ והם שס\"ה. ומה שחושב רק ג' גוונין שהם לבן אדום שחור, הוא להורות שחסר כאן, גוון ירוק שהוא גוון של ז\"א. והוא מטעם, כי אין מקומו כאן אלא מחזה ולמעלה כנ\"ל."],[9,"אנון גידין אתרקימו בשבע עשרה רשתות, וכל חד רשת גידין אקרי:","אלו שס\"ה גידין נרקמו בי\"ז רשתות, שכל אחד מהם נקרא רשת גידין. \u0003אתרקימו דא בדא ונחתין בשפולי תהומי,\u0004 נרקמו זה בזה ויורדים בסוף התהום, כלומר שנעשו לבחינת יסוד שהוא המסיים את הקומה. \u0003תחות אלין, תרין רשתין קיימין כחיזו דפרזלא, ותרין רשתין אחרנין כחיזו דנחשא,\u0004 תחת אלו, י\"ז רשתות, עומדים עוד ד' רשתות, שנים כמראה ברזל ושנים כמראה נחשת. פירוש. ב' יסודות הן בהנוקבא, א) מהתכללות יסוד הדכר ביסודה, והוא מכונה יוסף. ב) בחינתה עצמה, והוא מכונה בנימין. ולפיכך נחלקו הארת שס\"ה גידין לב' בחינות יסודות הללו, י\"ז רשתות לבחינות יוסף שבו, בסו\"ה יוסף בן שבע עשרה שנה. והוא בגימט' טו\"ב, להורות, כי \u0003טוביה גניז בגווה.\u0004 וד' רשתות לבחינת בנימין שהוא הנוקביות שבהיסוד, ונחלק לד' כנגד הנקבה, שאין בה אלא ד' ספירות תנה\"י מהזכר. ויש בו פנימיות וחיצוניות, ושנים הפנימים הם כמראה הנחשת, שהוא גוון ממותק. ושנים החיצונים הם כמראה ברזל, שהוא בלתי ממותק ברחמים."],[10,"תרין כרסוון, קיימי עלייהו, חד מימינא וחד משמאלא:","ב' כסאות עומדים עליהם, על כל אלו הבחינות הנ\"ל, כסא אחד מימין וכסא אחד משמאל. \u0003כל אינון רשתין מתחברן כחדא, ומיין נחתין מאינון צנורין ועאלין באינון רשתין,\u0004 כל אלו הרשתות מתחברים כאחד, והמים, שהם האורות, יורדים מהצנורות ונכנסים בהרשתות. \u0003אינון תרין כרסוון, חד כרסייא דרקיעא אוכמא, וחד כרסייא דרקיעא ססגונא,\u0004 הם הצנורות וחרשתות ואורותיהם. נכללים בתוך שני הכסאות, כסא אחד הוא של רקיע השחור, וכסא אחד של רקיע כעין תחש."],[10,"","פירוש. כי סוד היחוד הוא לד' רוחות השמים, מעלה ומטה. שד' רוחות פירושו חו\"ב תו\"מ, ומעלה מטה ה\"ס נצח והוד, שפירושו, שהארת הנצח מאיר את ד' הרוחות חו\"ב תו\"מ ממטה למעלה, וע\"כ נבחן הנצח לבחינת מעלה. והארת ההוד מאיר את ד' הרוחות חו\"ב תו\"מ ממעלה למטה, וע\"כ נבחן ההוד לבחינת מטה. (כמ\"ש לעיל דף ח' ד\"ה ואומרו) וב' מיני הארות הללו נוהגות בכל מדרגה. ולפיכך גם בעניננו, יש בקומת הזווג ב' מיני הארות הללו, וה\"ס ב' כסאות שאומר כאן, שהארת הנצח ה\"ס כסא הימין, שמגלה ההארת הקומה רק ממטה למעלה. והארת ההוד, הוא כסא השמאל המגלה הארת הקומה ממעלה למטה. וכסאות אלו עומדים במקום החזה דזו\"ן, כי למטה מחזה אין זווג נוהג שם, כנודע. ויש שם במקום החזה ב' פרסאות המכונים רקיעים. רקיע אחד מיוחס לג\"ר, ששם יש פני אדם שה\"ס מנעולא, וגוון שחור. ורקיע אחד מיוחס לו\"ק וה\"ס מפתחא וגוון תחש, שחסר כאן פני אדם. וכסא הימין עומד על רקיע השחור שהוא בחינת ג\"ר. וכסא השמאל על רקיע כעין תחש, שהיא בחינת ו\"ק. וביאור ב' כסאות הללו בסוד מרכבה עלאה ותתאה הרשומים בהם, כבר נתבארו באורך לעיל (בראשית א' דף צ' אות צ' ובהסולם שם) ואין להאריך."],[11,"אלין תרין כרסוון כד אינון סלקין, סלקין בההוא כרסיא דרקיעא אוכמא:","אלו ב' כסאות, כשהאורות של קומת הזווג עולים, דהיינו שמאירים ממטה למעלה, עולים בהכסא של רקיע השחור. דהיינו בהכסא דנצח, המאיר ממטה למעלה. כנ\"ל בדיבור הסמוך. \u0003וכד נחתין, נחתין בההוא כרסייא דרקיעא ססגונא,\u0004 וכשהם יורדים, הם יורדים בהכסא של הרקיע כעין ססגונא. דהיינו בהכסא דהוד המאיר ממעלה למטה."],[12,"אלין תרין כרסוון חד מימינא וחד משמאלא וההוא כרסייא דרקיעא אוכמא מימינא, וההוא כרסייא דרקיעא ססגונא משמאלא:","אלו ב' הכסאות שהם אחד מימין, ואחד משמאל, הכסא העומד על רקיע השחור, הוא מימין, והכסא העומד על הרקיע שהוא כעין ססגונא הוא משמאל, כמו שנתבאר לעיל."],[12,"כד סלקין בכרסייא דרקיעא אוכמא מאיך כרסייא דרקיעא שמאלא ונחתין ביה:","כשהאורות עולים בהכסא דרקיע השחור, יורד כנגדו הכסא של רקיע השמאלי והאורות יורדים בו. כלומר, שאלו ב' מיני הארות של הכסאות, אינם בזה אחר זה, אלא בבת אחת, והכסא הימני משפיע על כסא השמאלי, ולפיכך באותו העת שכסא הימין מעלה האורות ממטה למעלה, והאורות עולים בו, יורד כנגדו באותו העת כסא השמאל, וממשיך האורות ממעלה למטה, והאורות יורדים בתוכו."]],[[0,"","וּמִשּׁוּם שֶׁדַּרְכּוֹ שֶׁל הָאוֹר הַתְּכֵלֶת הַזֶּה לְהַשְׁמִיד וְלִהְיוֹת אוֹכֵל כָּל מַה שֶּׁנִּדְבָּק בּוֹ תַּחְתָּיו. כְּשֶׁרָצוֹן נִמְצָא וְנֵר דּוֹלֵק בְּחִבּוּר אֶחָד, אָז כָּתוּב (מלכים א יח) וַתִּפֹּל אֵשׁ ה' וַתֹּאכַל אֶת הָעֹלָה וְגוֹ'. וְאָז נוֹדָע שֶׁאוֹתוֹ נֵר דּוֹלֵק בְּחִבּוּר אֶחָד וְקֶשֶׁר אֶחָד. אוֹר תְּכֵלֶת נִדְבָּק בְּאוֹר לָבָן וְהוּא אֶחָד. אוֹכֵל תַּחְתָּיו חֲלָבִים וְעוֹלוֹת שֶׁמַּשְׁמָע שֶׁזֶּה לֹא אוֹכֵל (נ\"א: והוא ועולות שהרי לא אוכל) תַּחְתָּיו, אֶלָּא בִּזְמַן שֶׁהוּא עוֹלֶה (דולק) וְהַכֹּל נִקְשָׁר וּמִתְחַבֵּר בָּאוֹר הַלָּבָן, וְאָז הוּא שְׁלוֹם הָעוֹלָמִים כֻּלָּם, וְהַכֹּל נִקְשָׁר בְּיִחוּד אֶחָד."],[1,"","וְאַחַר שֶׁסִּיֵּם לְהַשְׁמִיד תַּחְתָּיו אוֹר תְּכֵלֶת זֶה, מִתְדַּבְּקִים בּוֹ תַּחְתָּיו כֹּהֲנִים לְוִיִּם וְיִשְׂרָאֵל. אֵלֶּה בְּחֶדְוַת הַשִּׁיר, וְאֵלֶּה בִּרְצוֹן הַלֵּב, וְאֵלֶּה בִּתְפִלָּה. וְנֵר דּוֹלֵק עֲלֵיהֶם. וְנִדְבָּקִים הָאוֹרוֹת כְּאֶחָד וּמְאִירִים הָעוֹלָמוֹת, וּמִתְבָּרְכִים עֶלְיוֹנִים וְתַחְתּוֹנִים."],[2,"","וְאָז וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם. וְאַתֶּם? אַתֶּם צָרִיךְ לִכְתֹּב! אֶלָּא ו' - לְהוֹסִיף עַל חֲלָבִים וְעוֹלוֹת שֶׁהֵם נִדְבָּקִים בּוֹ וְאוֹכְלִים וּמַשְׁמִידִים, וְאַתֶּם מִתְדַּבְּקִים בּוֹ בְּאוֹתוֹ אוֹר תְּכֵלֶת שָׁחֹר שֶׁאוֹכֶלֶת וְאַתֶּם קַיָּמִים. זֶהוּ שֶׁכָּתוּב חַיִּים כֻּלְּכֶם הַיּוֹם."],[3,"","(ס\"א ותכלת וארגמן) כָּל הַגְּוָנִים טוֹבִים לַחֲלוֹם, חוּץ מִתְּכֵלֶת שֶׁהוּא אוֹכֵל וּמַשְׁמִיד תָּמִיד, וְהוּא אִילָן שֶׁבּוֹ מָוֶת וְשׁוֹרֶה עַל הָעוֹלָם הַתַּחְתּוֹן. וּמִשּׁוּם שֶׁהַכֹּל שׁוֹרֶה תַחְתָּיו, הוּא אוֹכֵל וּמַשְׁמִיד."],[4,"","וְאִם תֹּאמַר כָּךְ, גַּם שׁוֹרֶה בַּשָּׁמַיִם לְמַעְלָה, וְכַמָּה צְבָאוֹת הֵם לְמַעְלָה, וְכֻלָּם (משמידים ואוכלים) קַיָּמִים. בֹּא רְאֵה, כָּל אוֹתָם שֶׁלְּמַעְלָה בְּאוֹתוֹ אוֹר תְּכֵלֶת נִכְלָלִים, אֲבָל הַתַּחְתּוֹנִים לֹא כָּךְ, שֶׁהֵם דָּבָר גַּס, הָעוֹלָם (נ\"א: אחר למטה על מה) שֶׁעוֹמֵד וְשׁוֹרֶה עָלָיו. וְלָכֵן אוֹכֵל וּמַשְׁמִיד אוֹתָם. וְאֵין לָהּ דָּבָר אַחֵר לְמַטָּה בָּעוֹלָם שֶׁלֹּא יֻשְׁמַד, מִשּׁוּם שֶׁאוֹר הַתְּכֵלֶת מַשְׁמִיד כָּל מַה שֶּׁעוֹמֵד עָלָיו."],[5,"","בְּאַרְבָּעִים וַחֲמִשָּׁה גְוָנִים שֶׁל מִינֵי אוֹרוֹת נֶחֱלָק הָעוֹלָם. שִׁבְעָה נֶחֱלָקִים לְשִׁבְעָה תְהוֹמוֹת. כָּל אֶחָד מַכֶּה בַּתְּהוֹם שֶׁלּוֹ, וַאֲבָנִים מִתְגַּלְגְּלוֹת בְּתוֹךְ הַתְּהוֹם, וְנִכְנָס אוֹתוֹ אוֹר בְּאוֹתָם אֲבָנִים וְנוֹקֵב אוֹתָם, וּמַיִם יוֹצְאִים בָּהֶם, וְשׁוֹקְעִים כָּל אֶחָד וְאֶחָד עַל הַתְּהוֹם וּמְכַסֶּה לִשְׁנֵי צְדָדִים."],[6,"","יוֹצְאִים מַיִם בְּאוֹתָם נְקָבִים, וְנִכְנָס אוֹר וּמַכֶּה לְאַרְבַּעַת צִדְדֵי הַתְּהוֹם. מִתְגַּלְגֵּל הָאוֹר בְּחֶבְרָתוֹ, וּפוֹגְשִׁים בְּאֶחָד, וְנֶחֱלָקִים הַמַּיִם,"],[7,"","וְאוֹחֲזִים כָּל אוֹתָם שִׁבְעָה בְּשִׁבְעָה תְהוֹמוֹת, וְכוֹרִים (שורים) בַּחֲשָׁכִים שֶׁל הַתְּהוֹם. וְהַחֲשָׁכִים הַלָּלוּ מִתְעָרְבִים בָּהֶם, וְעוֹלִים הַמַּיִם וְיוֹרְדִים וּמִתְגַּלְגְּלִים בְּאוֹתָם מְאוֹרוֹת. וּמִתְעָרְבִים כְּאֶחָד אוֹרוֹת וְחֹשֶׁךְ וּמַיִם, וְנַעֲשׂוּ מֵהֶם אוֹרוֹת שֶׁלֹּא נִרְאִים חֲשׁוּכִים."],[8,"","כָּל אֶחָד מַכֶּה בַּחֲבֵרוֹ, וְנֶחֱלָקִים לְשִׁבְעָה וַחֲמִשָּׁה צִנּוֹרוֹת שֶׁל הַתְּהוֹם, וּבָהֶם זוֹרְמִים מַיִם. כָּל צִנּוֹר וְצִנּוֹר עוֹלֶה בְקוֹלוֹ, וְהַתְּהוֹמוֹת מִזְדַּעְזְעִים. וּכְשֶׁאוֹתוֹ קוֹל נִשְׁמָע, כָּל תְּהוֹם קוֹרֵא לַחֲבֵרוֹ וְאוֹמֵר: חֲלֹק מֵימֶיךְ וְאֶכָּנֵס בְּךְ. זֶהוּ שֶׁכָּתוּב (תהלים מב) תְּהוֹם אֶל תְּהוֹם קוֹרֵא לְקוֹל צִנּוֹרֶיךְ."],[9,"","תַּחַת אֵלֶּה שְׁלֹשׁ מֵאוֹת (וששים) וּשְׁמוֹנִים (וחמשה) גִּידִים. מֵהֶם לְבָנִים וּמֵהֶם שְׁחֹרִים וּמֵהֶם אֲדֻמִּים. נִכְלְלוּ זֶה בָּזֶה וְנַעֲשׂוּ גָוֶן אֶחָד. אוֹתָם גִּידִים נִרְקְמוּ בִּשְׁבַע עֶשְׂרֵה רְשָׁתוֹת, וְכָל אַחַת נִקְרֵאת רֶשֶׁת גִּידִים. (התקימו) נִרְקְמוּ זֶה בָּזֶה וְיוֹרְדִים בְּתַחְתִּית הַתְּהוֹם. תַּחַת אֵלֶּה עוֹמְדוֹת שְׁתֵּי רְשָׁתוֹת כְּמַרְאֵה הַבַּרְזֶל, וּשְׁתֵּי רְשָׁתוֹת אֲחֵרוֹת כְּמַרְאֵה הַנְּחֹשֶׁת."],[10,"","שְׁנֵי כִסְאוֹת עוֹמְדִים עֲלֵיהֶם, אֶחָד מִיָּמִין וְאֶחָד מִשְּׂמֹאל. כָּל אוֹתָן רְשָׁתוֹת מְחֻבָּרוֹת כְּאֶחָד, וּמַיִם יוֹרְדִים מֵאוֹתָם צִנּוֹרוֹת וְנִכְנָסִים בָּרְשָׁתוֹת הָאֵלֶּה. אוֹתָם שְׁנֵי כִסְאוֹת, אֶחָד כִּסֵּא שֶׁל רָקִיעַ שָׁחֹר, וְאֶחָד כִּסֵּא שֶׁל רָקִיעַ תַּחַשׁ."],[11,"","שְׁנֵי הַכִּסְאוֹת הַלָּלוּ, כְּשֶׁהֵם עוֹלִים, עוֹלִים (באחד) בְּאוֹתוֹ כִּסֵּא שֶׁל הָרָקִיעַ הַשָּׁחֹר. וּכְשֶׁיּוֹרְדִים, יוֹרְדִים בְּאוֹתוֹ כִּסֵּא שֶׁל רְקִיעַ הַתַּחַשׁ."],[12,"","שְׁנֵי הַכִּסְאוֹת הַלָּלוּ, אֶחָד מִיָּמִין וְאֶחָד מִשְּׂמֹאל. וְאוֹתוֹ כִּסֵּא שֶׁל הָרָקִיעַ הַשָּׁחֹר מִיָּמִין, וְאוֹתוֹ כִּסֵּא שֶׁל רְקִיעַ הַתַּחַשׁ מִשְּׂמֹאל. כְּשֶׁעוֹלִים בַּכִּסֵּא שֶׁל הָרָקִיעַ הַשָּׁחֹר, מַנְמִיךְ הַכִּסֵּא שֶׁל רָקִיעַ שְׂמֹאל וְיוֹרְדִים בּוֹ."]]],[["מִתְגַּלְגְּלִין כָּרְסְוָון חַד בְּחַד (ס\"א נחתי ונקטין) נָקְטִין כָּל אִנּוּן רִשְׁתִּין בְּגַוַויְיהוּ וְעָאלִין לוֹן בְּשִׁפּוֹלָא דִּתְהוֹמָא תַּתָּאָה. קָאִים חַד כֻּרְסְיָיא וְסָלִיק לְעֵילָא מִכָּל אִנּוּן תְּהוֹמֵי. וְקָאִים כֻּרְסְיָיא אָחֳרָא לְתַתָּא דְּכָל תְּהוֹמֵי. בֵּין תְּרֵין כָּרְסְוָון אִלֵּין מִתְגַּלְגְּלִין כָּל אִנּוּן תְּהוֹמֵי. וְכָל אִנּוּן צִנּוֹרִין אִתְנְעָצוּ בֵּין תְּרֵין כָּרְסְוָון אִלֵּין.","שִׁבְעִין וְחָמֵשׁ (ד\"א ל\"ג נהורין) צִנּוֹרִין אִנּוּן. שִׁבְעָה אִנּוּן עִלָּאֵי דְּכֹלָּא. וְכָל אִנּוּן אָחֳרָנִין אֲחִידָן בְּהוּ. וְכֻלְהוּ נְעִיצֵי בְּגַלְגְּלוֹי דְּהַאי כֻּרְסְיָיא בְּסִטְרָא דָא. וּנְעִיצִין בְּגַלְגְּלוֹי דְהַאי כֻּרְסְיָיא בְּסִטְרָא דָא.","בְּהוֹן מַיִין (נ\"א בתהומיא) סָלְקִין וְנַחֲתִין. אִנּוּן דְּנַחֲתִין כָּרָאן בִּתְהוֹמֵי וּבָקְעֵי לוֹן. אִנּוּן דְּסָלְקִין עִלָּאִין בְּאִנּוּן נוּקְבֵי אַבְנִין וְסָלְקִין וּמַלְיָין לִשְׁבַע יַמִּין. עַד כָּאן שִׁבְעָה גְּוָונֵי נְהוֹרִין בְּרָזָא עִלָּאָה.","שִׁבְעָה נְהוֹרִין אָחֳרָנִין מִתְפַּלְּגִין לְשִׁבְעָה יַמִּים. וְיַמָּא חַד כָּלִיל לוֹן. הַהוּא יַמָּא חָד, אִיהוּ יַמָּא עִלָּאָה דְּכֻלְהוּ שְׁבַע יַמִין כְּלִילָן בֵּיהּ.","שִׁבְעָה נְהוֹרִין אִלֵּין עָאלִין לְגוֹ הַהוּא יַמָּא וּמָחָאן לֵיהּ לְיַמָּא (לשבעין) לְשִׁבְעָה סִטְרִין. וְכָל סִטְרָא וְסִטְרָא אִתְפְּלַג לְשִׁבְעָה נַחֲלִין. כְּדִכְתִיב, (ישעיהו י״א:ט״ו) וְהִכָּהוּ (שמות רמב ב) לְשִׁבְעָה נְחָלִים וְגו' וְכָל נַחֲלָא וְנַחֲלָא אִתְפְּלַג לְשִׁבְעָה נְהָרִין. וְכָל נַהֲרָא וְנַהֲרָא אִתְפְּלַג לְשִׁבְעָה אָרְחִין. וְכָל אוֹרְחָא וְאוֹרְחָא אִתְפְּלַג לְשִׁבְעָה שְׁבִילִין. וְכָל מֵימוֹי דְיַמָּא כֻּלְהוֹן עָאלִין לְגַוַּויְהוּ.","שִׁבְעָה נְהוֹרִין סָלְקִין וְנָחֲתִין לְשִׁבְעָה סִטְרִין. שִׁבְעָה נְהוֹרִין עִלָּאִין עָאלִין לְגוֹ יַמָּא. שִׁתָּא אִנּוּן וּמֵחַד עִלָּאָה נָפְקֵי. כְּמָה דְּנָטִיל יַמָא הָכִי פָּלִיג מֵימוֹי לְכָל אִנּוּן יַמִּין. לְכָל אִנּוּן נְהָרִין.","חַד תַּנִינָא לְתַתָּא בִּסְטַר שְׂמָאלָא שָׁאַט בְּכָל אִנּוּן נְהָרִין אָתֵי בִּסְטַר קַשְׂקְשׂוֹי כֻּלְהוֹן תַּקִּיפִין כְּפַרְזְלָא וּמָטֵי לְשָׁאֲבָא וְשָׁאִיב אַתְרָהּ. וְכָל אִנּוּן נְהוֹרִין אִתְחַשְׁכָן קַמֵּיהּ. פּוּמֵיהּ וְלִישְׁנֵיהּ מְלַהֲטָא אֶשָׁא (חדוד דלישניה) חָדוּד לִישְׁנִיהּ כְּחַרְבָּא תַּקִּיפָא.","עַד דְּמָטֵי לְמֵיעַל לְמַקְדְּשָׁא גּוֹ יַמָּא וּכְדֵין סָאִיב מַקְדְּשָׁא וְאִתְחַשְּׁכָן נְהוֹרִין. וּנְהוֹרִין עִלָּאִין סָלְקִין מִן יַמָא. כְּדֵין יַמָּא מִתְפַּלְגִין מֵימוֹי בִּסְטַר שְׂמָאלָא וְיַמָּא קָאפֵי וְלָא נָגְדִין מֵימוֹי.","וְעַל דָּא רָזָא דְמִלָּה כְּמָה דִכְתִיב וְהַנָּחָשׁ הָיָה עָרוּם מִכָּל חַיַּת הַשָּׂדֶה אֲשֶׁר עָשָׂה יְיָ אֱלהִים. רָזָא דְחִוְיָא בִישָׁא נָחִית מֵתַתָּא לְעֵילָא (ס\"י מעילא לתתא) וְהוּא שָׁאַט עַל אַפֵּי מַיִין מְרִירָן. וְנָחִית לְאַפְתֵּי לְתַתָּא עַד דְּיִפְּלוּן גּוֹ רִשְׁתּוֹי.","הַאי חִוְיָא הִיא מוֹתָא דְעָלְמָא. וְהוּא עָאל בְּמֵעוֹי דְּסָתִים דְּבַר נָשׁ, הוּא לִסְטַר שְׂמָאלָא. וְאִית חִוְיָא אַתְרָא דְחַיֵּי בִּסְטַר יָמִינָא. תַּרְוַויְיהוּ אָזְלֵי עִמֵּיהּ דְּבַר נָשׁ. כְּמָה דְּאוּקְמוּהָ.","מִכָּל חַיַּת הַשָּׂדֶה דְּהָא כָּל שְׁאָר חֵיוָן דְּחַקְלָא לֵית בְּהוּ חַכִּים לְאַבְאָשָׁא כְּהַאי. בְּגִין דְּאִיהוּ זוּהֲמָא דְדַהֲבָא. וַוי לְמַאן דְּאִתְמְשִׁיךְ אֲבַתְרֵיהּ. דְּאִיהוּ גָרִים לֵיהּ מוֹתָא וּלְכָל דְּאַתְיָין אֲבַתְרֵיהּ. וְהָא אוּקְמוּהָ. אָדָם אִמְשִׁיךְ אֲבַתְרֵיהּ לְתַתָּא וְנָחִית לְמִנְדַע בְּכָל מַה דִּלְתַתָּא. כְּמָה דְּנָחִית, הָכִי אִתְמְשִׁיךְ רְעוּתֵיהּ וְאָרְחוֹי אֲבַּתְרַיְיהוּ עַד דְּמָטִין לְהַאי חִוְיָא וְחָמוּ תֵּיאוּבְתֵּיהּ דְּעָלְמָא וְשָׁטוּ אָרְחוֹי בְּאֲתַר דָּא. כְּדֵין קָם וְאִתְמְשִׁיךְ אִיהוּ אֲבַּתְרַיְיהוּ דְּאָדָם וְאִתְּתֵיהּ וְאִתְדָּבַּק בְּהוּ וְגָרִים לְהוּ מוֹתָא וּבְכָל דָּרֵי דְּאָתוּ אֲבַתְרֵיהּ. עַד דְּמָטוּ יִשְׂרָאֵל לְטוּרָא דְסִינַי לָא פָּסַק זוּהֲמָא דִילֵיהּ מֵעָלְמָא. וְהָא אִתְּמָר. כֵּיוָן דְּחָטוּ וְאִתְדַּבְּקוּ בְּאִילָנָא דְּשָׁרְיָא בֵּיהּ מוֹתָא לְתַתָּא. מַה כְּתִיב וַיִּשְׁמְעוּ אֶת קוֹל יְיָ אֱלהִים מִתְהַלֵּךְ בַּגָּן. מְהַלֵּךְ אֵין כְּתִיב כָּאן. אֶלָּא מִתְהַלֵּךְ.","תָּא חֲזֵי, עַד לָא חָטָא אָדָם, הֲוָה סָלִיק וְקָאִים בְּחָכְמָה דִנְהִירוּ עִלָּאָה. וְלָא הֲוָה מִתְפָּרֵשׁ מֵאִילָנָא דְחַיֵּי. כֵּיוָן דְּאַסְגֵי תִּיאוּבְתָּא לְמִנְדַע וּלְנַחֲתָא לְתַתָּא, אִתְמְשַׁךְ אֲבַּתְרַיְיהוּ, עַד דְּאִתְפְּרַשׁ מֵאִילָנָא דְחַיֵּי. וְיָדַע רָע וְשָׁבַק טוֹב. וְעַל דָּא כְּתִיב (תהילים ה׳:ה׳) כִּי לא אֵל חָפֵץ רֶשַׁע אַתָּה לא יְגוּרְךָ רָע. מַאן דְּאִתְמְשַׁךְ בָּתַר רָע, לֵית לֵיהּ דִּירָה עִם אִילָנָא דְחַיֵּי."],[[0,"מתגלגלין כרסוון חד בחד, נקטין כל אינון רשתין בגווייהו ועאלין לון בשפולי דתהומא תתאה:","הכסאות נכללים זה בזה, ואוחזים בתוכם כל אלו הרשתות, ומכניסים אותם בסיומו של תהום התחתון. פירוש. כי הרשתות, ה\"ס חלק המחזה ולמטה של קומת הזווג, וע\"כ בעת שהכסאות נכללים זה מזה, מקבלות הרשתות הארת שניהם, עד שמורידים אותם למטה ומאירים ומשלימים עד סוף התהום התחתון."],[0,"קאים חד כרסיא וסליק לעילא מכל אינון תהומי, וקאים כרסייא אחרא לתתא דכל תהומי:","ואז, כסא אחד עומד ועולה למעלה מכל אלו התהומות, וכסא השני עומד למטה מכל התהומות. היינו אחר שהורידו הארת הרשתות עד סוף תהום התחתון כנ\"ל, שאומר לעיל, שאין האורות יורדים אלא בתוך הכסא השמאל, ונמצא בהכרח, שהכסא עצמו נשאר עומד מתחת התהום התחתון. אבל כסא הימני נשאר למעלה ולא ירד, כנ\"ל, וע\"כ נמצא, שכסא הימני למעלה מכל התהומות, והשמאלי למטה מכל התהומות."],[0,"בין תרין כרסוון אלין מתגלגלין כל אינון תהומי, וכל אינון צנורין אתנעצו בין תרין כרסוון אלין:","בין שני כסאות הללו מתגלגלים ונשלמים כל אלו התהומות, וכל אלו הצנורות ננעצו בין אלו ב' הכסאות. פירוש. כי הארת ההוד הוא על ידי גלגול (כמ\"ש לעיל דף מ\"ט ד\"ה דא לאו ע\"ש.) ולפיכך על השלמת התהומין הבאה ממעלה למטה, דהיינו מכסא ההוד, אומר \u0003מתגלגלין.\u0004 ועל הצנורות, שהם בחינת מחזה ולמעלה (כנ\"ל דף קס\"א ד\"ה בטש) אומר \u0003אתנעצו.\u0004 דהיינו שיונקים הארתם מב' הכסאות יחד."],[1,"שבעין וחמש צנורין אינון, שבעה אינון עלאי דכלא, וכל אינון אחרנין אחידן בהו:","שבעים וחמשה צנורות הם, אבל שבעה, שהם שבעה תהומין דז\"א, הם עליונים מכולם וכל אלו האחרים נאחזים בהם. כי בסוד הזווג נכפלו אלו ז' תהומין דז\"א ונעשו ע', (כנ\"ל דף קס\"א ד\"ה בטש) הרי ששבעה דז\"א הם עליונים ושרשים לכל ע\"ה צנורות ע\"ש. וכלהו נעיצי בגלגלוי דהאי כרסייא בסטרא דא, ונעיצין בגלגלוי דהאי כר\u0003סייא בסטרא דא,\u0004 וכל ע\"ה צנורות נעוצים בהגלגלים של כסא חזה שבצד הימין ובהגלגלים של כסא הזה שבצד שמאל. פירוש. מחזה ולמעלה של כל כסא נקראים גלגלים, ומחזה ולמטה נקראים סמכין (כנ\"ל דף מ\"ו ד\"ה ביאור). ומשמיענו, אשר הצנורות נעוצים בבחינת מחזה ולמעלה של הכסאות המכונים גלגלים. והיינו (כמ\"ש לעיל דף קס\"א ד\"ה בטש כל חד) אשר הצנורות הם מבחינת מחזה ולמעלה של קומת הזווג, ושס\"ה גידין, הם מחזה ולמטה של הקומה. ע\"ש."],[2,"בהון, מיין סלקין ונחתין:","באלו ז' תהומין דז\"א, שהם עלאי דכלא, המים, שהם האורות, עולים ויורדים, פירוש. כי אחר שכבר ביאר כל ההתפשטות של קומת הזווג בהמקום שמחזה ולמעלה, בא עתה למצות כל הדברים כדי להתקרב למטרת המאמר, דהיינו לבאר ענין פיתוי הנחש וחטאו של עצה\"ד מה היא. וז\"ש \u0003שבעה אינון עלאי דכלא,\u0004 שהם כוללים כל ההתפשטות כולו, והולך ומבאר ענין הזווג הנעשה בשבעה תהומין הללו שה\"ס שבע המלכיות דז\"ס חג\"ת נהי\"מ דז\"א. ואומר \u0003בהון מיין סלקין ונחתין,\u0004 שבמלכיות הללו, עולה אור חוזר ויורד אור ישר. כי אין לך מציאות מדרגה שלא תצא מזווג דהכאה של אור ישר בהמסך שבמלכות המעלה אור חוזר, כנודע. ואומר, \u0003אינון דנחתין כראן בתהומי ובקעי לון,\u0004 אלו היורדים דהיינו אור העליון היורד מלמעלה אל המסכים שבהמלכיות, הם חופרים בהתהומות שהם המלכיות, דהיינו שמכה ורוצה להתלבש בהם, והם בוקעים אותם, כלומר שהמסכים המעכבים על הופעת האור, נבחנים עתה, כמו נבקעים ומעלים אור חוזר, העולה ומלביש לאור העליון, כמו שממשיך, \u0003אלין דסלקין עאלין באלין נוקבי אבנין וסלקין ומליין לשבע ימין,\u0004 אלו האורות העולים דהיינו האו\"ח, נכנסים באלו הנקבים שנבקעו בהאבנים שהם המסכים, ועולים ומלבישים את אור העליון ממטה למעלה ועל ידי כך הם ממלאים לשבע הספירות חג\"ת נהי\"מ, המכונים כאן, שבע ימים. כי אור העליון הנמשך אל ז' התהומות ומכה בהם, נבחן לז\"ס חג\"ת נהי\"מ, שעי\"ז יוצאים על ידי זווג דהכאה הזה, ז' קומות שבכל אחת מהן יש בה חג\"ת נהי\"מ. \u0003עד כאן שבעה גווני נהורין ברזא עלאה,\u0004 עד כאן נתבארו, שבעה מיני אורות, דהיינו שבעה הימים חג\"ת נהי\"מ, שיצאו בסוד העליון, דהיינו בהמקום שמחזה ולמעלה."],[3,"שבעה נהורין אחרנין מתפלגין לשבעה ימים, וימא חד כליל לון:","שבעה אורות אחרים מתחלקים לשבעה ימים, וים אחד כולל אותם. \u0003ההוא ימא חד, איהו ימא עלאה, דכלהו שבע ימין כלילן ביה,\u0004 ים האחד ההוא, הוא ים העליון שכל שבעה הימים כלולים בו. פירוש. אחר שנעשה הזווג מחזה ולמעלה, ויצאו שם שבעה ימים עליונים מחזה ולמעלה, נתפשטה המלכות שבהם, דהיינו ים התחתון שבהם, לז' ימים אחרים מלמעלה למטה, דהיינו למטה מחזה. וע\"כ נמצא שים התחתון שלמעלה מחזה, נעשה לים העליון אל למטה מחזה, כי ממנה נתפשטו כולם, והיא כוללת אותם משום זה. ולהלן מבאר שרק ששה ימים נתפשטו מחזה ולמטה, דהיינו רק לפי ששה הספירות חג\"ת נה\"י, כי המלכות חסרה שם. ומה שאומר כאן שבעה, הוא בצירוף עם ים העליון, השייך להשבע ימים שלמעלה מחזה. כי הוא ים התחתון שלהם, כמבואר."],[4,"שבעה נהורין אלין עאלין לגו ההוא ימא ומחאן ליה לימא לשבעה סטרין:","ז' אורות הללו, דהיינו אור העליון הכולל בתוכו חג\"ת נהי\"מ, נכנסים לתוך ים ההוא, שהיא המלכות שלמעלה מחזה כנ\"ל, ומכים להים, דהיינו בסוד זווג דהכאה של אור העליון עם הים שהיא המלכות, ונעשה הים לשבע צדדים, דהיינו שנתפשט מחזה ולמטה, לשבע ספירות חג\"ת נהי\"מ. כי הזווג דהכאה העלה או\"ח מהמלכות שהלביש את אור העליון, כמ\"ש לעיל בשבע ימים שלמעלה מחזה. \u0003וכל סטרא וסטרא אתפליג לשבע נחלין, כדכתיב, והכהו לשבע נחלים וכל נחלא ונחלא אתפליג לשבעה נהרין וכו'\u0004 וכל צד וצד מז' הצדדים נחלק לז' נחלים. ככתוב, והכהו לשבעה נחלים וכל נחל ונחל נחלק לז' נהרות, וכל נהר ונהר נחלק לז' אורחות, וכל אורח ואורח לז' שבילים. \u0003וכל מימוי דימא, כלהון עאלין לגווייהו,\u0004 וכל מי הים, כולם נכנסים לתוכם."],[4,"","ביאור הדברים. כי כל מדרגה שלימה יוצאת בה' קומות כח\"ב תו\"מ זה למטה מזה, המכונים כאן: \u0003סטרין, נחלין, נהרין, אורחין, שבילין.\u0004 והן יוצאות על דרך שיצאו ה' קומות גלגלתא ע\"ב ס\"ג מ\"ה וב\"ן באדם קדמון, (ע\"ד שנתבאר בפתיחה לחכמת הקבלה מאות ל' עד אות מ\"ב עש\"ה) כי כל הכחות הנמצאים בהעליון, מוכרחים הם בהתחתון. והן יוצאות בד' זווגים, אשר בכל זווג נכפלות הספירות דעליון בעשר פעמים. והטעם, כי כל תחתון יוצא רק ממלכות דעליון, כמ\"ש בפתיחה לחכמת הקבלה מאות ל\"ה עד אות מ\"ב עש\"ה. באופן שהע\"ס דתחתון הן רק עשר מלכיות של ע\"ס דעליון, אשר כתר דתחתון הוא רק המלכות של כתר דעליון, וכן חכמה דתחתון הוא רק המלכות של חכמה דעליון וכו' על דרך זה. ונמצא בעת שהעליון מאציל את התחתון, מוכרח העליון להכפיל כל ספירה יחידה שלו לעשר ספירות, כדי ליתן להתחתון את המלכות שלה. כי אחר שהוא מכפיל הכתר שלו לע\"ס כח\"ב תו\"מ, יכול להשפיע המלכות דכתר להתחתון. וכן אחר שמכפיל הספירה דחכמה שלו לע\"ס כח\"ב תו\"מ, יכול ליתן המלכות דחכמה להתחתון וכולם על דרך זה. הרי שבכל זווג להוציא מדרגה תחתונה מוכרח העליון להכפיל העשר ספירות שלו לעשר פעמים. וכאן הזהר מדבר מזווג זו\"ן, שהע\"ס נעשו בהם לז' ספירות חג\"ת נה\"מ, (מטעם שנתבאר לעיל דף ק\"ס ד\"ה ונודע ע\"ש) נמצא שבכל זווג מכפיל העליון ז' פעמים את הז' ספירות שלו."],[4,"","וזהו אמרו \u0003שבעה נהורין אלין עאלין לגו האי ימא\u0004 וכו' \u0003לשבעה סטרין,\u0004 והוא זווג הא' לאותו התפשטות שמחזה ולמעלה, והיינו קומת כתר המיוחס להתפשטות הזה. \u0003וכשהשבעה סטרין\u0004 מזדווגין להוציא \u0003קומת חכמה\u0004 שהיא \u0003ז' נחלין,\u0004 נמצא בהכרח אשר קומה העליונה מתכפלת לז\"פ ז' ספירות כדי להאציל הקומה התחתונה מהמלכות שבכל אחת, ומתחלק החסד דז' סטרין לז\"ס חג\"ת נהי\"מ והמלכות דחסד היא נותנת לקומה תחתונה שנעשית לחסד של התחתונה כנ\"ל. וכן מתחלקת ספירת הגבורה של ז' סטרין, לז\"ס חג\"ת נהי\"מ, שנותנת לקומה תחתונה את המלכות דז\"ס ההן, שנעשתה בה לגבורה. וכו' עד\"ז וז\"ש \u0003וכל סטרא וסטרא אתפלג לז' נחלין,\u0004 דהיינו כדי ליתן נחל האחרון שבאותו סטרא אל הקומה דז' נחלים כמבואר. ועד\"ז קומת החכמה שהיא נקראת ז' נחלים כשבאה להוציא קומה התחתונה ממנה. שהיא קומת בינה הנקראת \u0003ז' נהרין,\u0004 מתכפלת גם היא לזפ\"ז, כנ\"ל. וז\"ש \u0003וכל נחלא ונחלא אתפלג לשבעה נהרין,\u0004 כי החסד דנחלין נתחלק לז' נהרות חג\"ת נהי\"מ כדי ליתן נהר האחרון אל קומת בינה הנקראת ז' נהרין, שהיא תהיה לחסד דקומה זו. וכן הגבורה דנחלין נחלקה לז' נהרין, כדי ליתן נהר האחרון לקומת בינה. וכן הת\"ת דנחלין וכו' עד\"ז. וכן \u0003וכל נהרא ונהרא אתפליג לשבעה ארחין\u0004 כדי ליתן אורח האחרון דכל ספירה אל קומת ז\"א המכונה \u0003ז' ארחין.\u0004 וכן \u0003וכל אורחא ואורחא אתפלג לשבעה שבילין,\u0004 כדי ליתן את שביל האחרון דכל ספירה, אל קומת המלכות, הנקראת ז' שבילין."],[4,"","ומכאן תבין את הכלל המובא בכ\"מ, שע\"ס של המלכות הם יחידות, ודז\"א עשרות, ודבינה מאות, ודחבמה אלפים, ודכתר רבבות. והוא, כי אין להתחתון משהו מה שאינו מקבל מהעליון ממנו, והעליון מעלי עליון וכו' עד א\"ס ב\"ה. ולפי\"ז נמצא, מה שהוכחנו, שבעת שהעליון מאציל את התחתון, מוכרח העליון להתכפל למאה, דהיינו עשר פעמים ממה שהוא, כדי להשפיע עשר מלכיות מהם להתחתון ממנו, הנה יחד עם זה נבחן בהכרח, אשר העלי עליון מתכפל בעת ההוא ג\"כ לעשר פעמים ממה שהוא, דהיינו לאלף ספירות, כדי שיוכל להשפיע מאה מלכיות מהם להתחתון שלו, כדי שהתחתון שלו יוכל להשפיע עשרה מהם לתחת התחתון. באופן בעת שקומת ז\"א מתכפלת למאה כדי להאציל את קומת המלכות בעשרה מהם, נמצא קומת בינה מתכפלת בעת ההוא לאלפים ספירות, כי כדי שתוכל להשפיע מאה מלכיות מהם לז\"א. וקומת חכמה מתכפלת לעשרת אלפים ספירות, כי כדי שתוכל להשפיע אלף מלכיות מהם לבינה. וקומת כתר מתכפלת למאה אלף, כדי שתוכל להשפיע עשרת אלפים מלכיות מהם לחכמה. הרי שהעשר ספירות שבקומת כתר הן כאו\"א בת עשרת אלפים, דהיינו מאה אלף ספירות. והע\"ס שבקומת חכמה הן כאו\"א בת אלף. והע\"ס שבקומת בינה, הן כאו\"א בת מאה, והע\"ס שבקומת ז\"א הן כאו\"א בת עשרה. והע\"ס שבקומת מלכות הן כאו\"א רק יחידות. (ועי' בפמ\"ס דף ר\"ז ד\"ה והטעם. ובתע\"ס חלק י\"ג דף אלף שצ\"ט ד\"ה וטעם המספרים.)"],[5,"שבעה נהורין סלקין ונחתין לשבעה סטרין, שבעה נהורין עלאין עאלין לגו ימא, שתא אינון ומחד עלאה נפקי:","ז' אורות עולים ויורדים לז' סטרין, דהיינו לההתפשטות שמחזה ולמטה, שקומת כתר שלהם נקראת ז' סטרין. כי ז' אורות עליונים נכנסים לזווג דהכאה, תוך ים התחתון של ז' ימים העליונים, שהיא מלכות שמחזה ולמעלה, כנ\"ל. ועם כל זה, ששה הם ולא שבעה, ומאחד העליון יצאו, דהיינו מים התחתון שלמעלה מחזה, הנבחן לים העליון להששה המתפשטים למטה מחזה, ועמו הם נחשבים לשבעה. כלומר, שלא נתפשטו למטה מחזה אותם שבעה נהורין, שהכו בים העליון, שהם חג\"ת נהי\"מ, אלא רק ששה מהם נתפשטו, שהם חג\"ת נה\"י, אבל המלכות חסרה בההתפשטות הזה שמחזה ולמטה, אלא שנחשבים לשבעה משום שים העליון, שהיא המלכות שמחזה ולמעלה, שממנה יצאו, היא מצטרפת אל חג\"ת נה\"י הללו והם עמה שבעה. ומסקנא זו של חסרון המלכות למטה מחזה, היא תמצית כל המאמר שלפנינו, הנרצה לענין הבנת החטא דעצה\"ד, המובא לפנינו. \u0003כמה דנטיל ימא הכי פליג מימוי לכל אינון ימין לכל אינון נהרין,\u0004 כמו שהים מקבל כן הוא מחלק מימיו לכל אלו הימים ולכל אלו הבחינות. כלומר כל אלו ד' הזווגים הנ\"ל של ההתפשטות שלמטה מחזה, מקבל ים העליון למעלה מחזה וכמו שהוא מקבל שם, כן הוא מחלק אותם להמקום שלמטה מחזה. לאפוקי, שלא נעשה שום זווג מהם למטה מחזה."],[6,"חד תנינא לתתא בסטר שמאלא, שאט בכל אינון נהרין, אתי בסטר:","נחש אחד למטה, בצד שמאל, שוחה בכל אלו הנהרות הנמשכים מחזה ולמטה, (כנ\"ל באות רפ\"ב) ובא אל הצד, דהיינו לצד שמאל. כלומר, שלא יוכל לינק מכל בחינות הנהרות רק מצד שמאל שבהם. \u0003קשקשוי כולהון תקיפין כפרזלא\u0004 קשקשותיו, כולן חזקות כמו ברזל. כלומר, שהדינים שבו קשים מאד."],[6,"","פירוש. כי כל אחיזת הקליפות היא במקום חסרון של הקדושה, ואומר לעיל (באות רפ\"ב) שמחזה ולמטה רק \u0003שתא אינון,\u0004 דהיינו חג\"ת נה\"י, והמלכות חסרה. שז\"ס מ\"ש בתחילת המאמר, \u0003במ\"ה גווני זיני נהורין אתפליג עלמא\u0004 ע\"ש בהסולם. וע\"כ נאחז הנחש במקום הזה בהמלכות. וז\"ש \u0003חד תנינא לתתא,\u0004 שנחש אחד נאחז למטה, דהיינו במקום שחסרה המלכות, \u0003בסטר שמאלא,\u0004 בצד שמאל אשר שם, כי אין קליפות נאחזות רק בצד שמאל. \u0003שאט בכל אינון נהרין,\u0004 דהיינו בשבעה נהרין הנ\"ל באות רפ\"ב הנמשכים מחזה ולמטה אתי בסטר, ובא לצד שמאל שבנהרות. וז\"ש \u0003ומטי לשאבא ושאיב אתרה,\u0004 והוא מגיע, ע\"י חטאי התחתונים, לשאוב שפע ושואב מקומה דהיינו מקומה של המלכות החסרה שמה. ואז, \u0003וכל אינון נהורין אתחשכן קמיה,\u0004 וכל אלו האורות שבנהרות נחשכים לפניו, כי הזווג נפסק תכף ומיד עם נגיעתו של הנחש במקום המלכות הנ\"ל, כי, \u0003פומיה ולישניה מלהטא אשא, חדוד לישניה כחרבא תקיפא,\u0004 פיו ולשונו אש לוהט, לשונו חדה כחרב קשה. כלומר, שהדינים קשים בו מאד ואין הצלה ממנו."],[7,"עד דמטי למיעל למקדשא, גו ימא, וכדין סאיב מקדשא, ואתחשכן נהורין, ונהורין עלאין סלקין מן ימא:","עד שהנחש מגיע לכנוס אל המקדש, בתוך הים, ואז נטמא המקדש, שהיא המלכות, והאורות נחשכים, ואורות העליונים מסתלקים מן הים. דהיינו האורות דג\"ר."],[7,"","פירוש. המלכות המזדווגת עם ז\"א מבחינתה שלמעלה מחזה, המשותפת שם עם הבינה, היא מכונה מקדש, וכן ים. כנ\"ל אות ר\"פ ונודע, שמבחינתה של המלכות עצמה אינה ראויה לזווג ולקבל מוחין, כי עליה היה צמצום א' שלא תקבל לתוכה אור ישר, (כנ\"ל בראשית א' דף ז' ד\"ה וכבר עש\"ה) וכל הכשרתה לזווג ולמוחין הוא מחמת שיתופה עם מדת הרחמים, שהיא בינה. ולפיכך, אחר שהנחש נאחז במקום המלכות החסרה בבחינת מחזה ולמטה, כנ\"ל (באות רפ\"ג) ושאיב אתרה, שהיא מקום של בחינת המלכות בעצמותה, בלי שיתופה עם הבינה, כי היא חסרה שם, ורק מקומה נמצא, הרי נגלה בזה מדת הדין שבמלכות, שאינה ראויה לזווג ולמוחין, ונמצא שמכח אחיזת הנחש במקום מלכות דמדת הדין למטה, נתפרק שיתוף המלכות בבינה, שבמלכות העליונה הנקראת \u0003ים,\u0004 ונבחן זה, שהמלכות העליונה נטמאה, דהיינו, שאינה ראויה עוד לזווג כמו אשה טמאה האסורה לבעלה. כי לאחר שנגלה בחינתה עצמה נאסרה לז\"א בעלה, ואינה ראויה לזווג ומוחין. וז\"ש, \u0003וכדין סאיב מקדשא, גו ימא, וכו'\u0004 דהיינו שנפסק הזווג מהמלכות הנקראת מקדש וים וכו'. \u0003ונהורין עלאין סלקין מן ימא.\u0004 ואורות העליונים, אורות דג\"ר, שהם אור ישר, מסתלקים מהים, שהיא המלכות העליונה. מכח שנגלה מדת הדין שבה מצמצום א' שנצטמצמה שלא לקבל לתוכה אור ישר. כנ\"ל. וז\"ש לעיל (בהקדמת הזהר, דף קכ\"ג אות קכ\"ב) שב' נקודין הם בהמלכות, שהם ב' המלכיות שבכאן, שהמלכות שלמעלה מחזה היא ממותקת בהבינה, והמלכות שלמטה מחזה היא בלתי ממותקת, והיא חסרה, כלומר שנגנזה ואינה נודעת, וע\"כ ראויה המלכות שלמעלה מחזה לקבל מוחין מכח הבינה שבה, כי כח הדין והצמצום שבה נגנז ואינו. אלא בשעה שהנחש \u0003מטי לשאבא ושאיב אתרה,\u0004 ומגלה מדת הדין שבה, אז נגלה כח הדין גם בהמלכות שמחזה ולמעלה. כמבואר. וז\"ס שאומר שם, \u0003זכי הא טוב לא זכי הא רע,\u0004 כי בעת שהתחתונים זוכים, אין הנחש יכול להאחז במקום המלכות למטה ולגלות מדת הדין שבה, וע\"כ \u0003הא טוב,\u0004 שהיא בזווג עם ז\"א ומשפעת כל טוב להתחתונים. אלא אם התחתונים מקלקלים מעשיהם, אז קונה הנחש כח להאחז במקום המלכות למטה, ומגלה מדת הדין שבה, והיא נטמאה, ואורות עליונים מסתלקים מהים. וזהו \u0003לא זכי הא רע,\u0004 עש\"ה. וזה היה סוד החטא של עצה\"ד, כמו שמבאר לפנינו."],[7,"כדין, ימא מתפלגין מימוי בסטר שמאלא, וימא קאפי ולא נגדין מימוי:","ואז מימי הים מתחלקים ובאים מצד השמאל, והים נקפא, ומימיו אינם נוזלים. פירוש. שמימי הים, שהם האורות שבהמלכות, נחלקו, כי הג\"ר נסתלקו משם, והו\"ק שנשארו באו לצד שמאל ונקפאו. כלומר, שאפילו האורות שנשארו אינם נמשכים ממנה להתחתונים, וכמו שנקפאו בה דומים."],[8,"ועל דא רזא דמלה, כמה דכתיב, והנחש היה ערום וגו' רזא דחויא בישא נחית מעילא לתתא והוא שאט על אפי מיין מרירן:","ועל כן, סוד הדבר הוא כמו שכתוב, והנחש היה ערום וגו' הסוד הוא, שנחש הרע יורד ממעלה למטה. כלומר, שדרכו להמשיך הארת השמאל ממעלה למטה, והוא שוחה על פני מים המרים, שהם סוד מדת הדין שבה. וע\"כ הוא בא לצד שמאל, ורוצה להמשיך הארת השמאל מהים העליון שלמעלה מחזה, אל מקום המלכות שלמטה מחזה, שבזה הוא מגלה מדת הדין שבה. (כנ\"ל בדיבור הסמוך) \u0003לא זכי הא רע.\u0004 וזהו כל הסוד של עץ הדעת, וע\"כ, \u0003ונחית לאפתי לתתא עד דיפלון גו רשתוי,\u0004 וירד למטה לפתות את חוה, שתאכל מעץ הדעת, דהיינו שתמשיך בעדו הארת השמאל ממעלה למטה, שבזה נופלים תוך הרשת שלו. שקונה כח לעלות למעלה ולגלות מדת הדין שבה, כנ\"ל."],[9,"האי חויא היא מותא דעלמא, והוא עאל במעוי דסתים דבר נש, הוא לסטר שמאלא:","נחש זה הוא המות שבעולם, כלומר, שהסית את חוה בעצה\"ד, והביא המות לעולם. והוא נכנס במעי הסתום של האדם, הנקרא מעי העור, והוא לצד שמאל. כלומר שיניקתו רק מהארת קו השמאל. וענין מעי העור הסתום, הוא מאברים היתרים שנכנסו בגוף האדם אחר אכילת עצה\"ד, שמצדם מוכרח הגוף למות. כמו שנתבאר בהקדמתי לספר פנים מאירות ופנים מסבירות על עץ חיים להאריז\"ל, דף ז' אות כ' ע\"ש ואין להאריך כאן. וז\"ש \u0003היא מותא דעלמא והוא עאל במעוי דסתים,\u0004 דהיינו שנכנס ונתלבש שם, וכן בשאר האברים היתרים. כלומר, שמשם מביא המות על גוף האדם. כמ\"ש שם בהקדמה. \u0003ואית חויא אחרא דחיי בסטר ימינא, תרוייהו אזלי עמיה דבר נש כמה דאוקמוה.\u0004 ויש נחש אחר של חיים, בצד ימין, דהיינו יצר הטוב, המביא חיים להאדם. ושניהם הולכים עם האדם, שהם יצה\"ר ויצה\"ט, כמו שבארוהו."],[10,"מכל חית השדה. דהא כל שאר חיון דחקלא לית בהו חכים לאבאשא כהאי, בגין דאיהו זוהמא דדהבא:","ואומר עליו הכתוב, ערום מכל חית השדה. כי בכל שאר חיות השדה. שהם כל הקליפות, אין בהם חכם להרע כמוהו, משום שהוא פסולת הזהב. הארת השמאל הנקרא צפון, הוא מכונה בשם זהב. בסו\"ה מצפון זהב יאתה (איוב ל\"ז כ\"ב) ונחש הזה הוא הפסולת מהארת השמאל, ע\"כ נבחן ל\u0003זוהמא דדהבא.\u0004 והשמאל הוא שורש הארת החכמה שמשם כל הדינין, וע\"כ הוא חכם להרע מכל חית השדה. כלומר, שכחו להזיק הוא גדול מכל חית השדה, שהם שאר הקליפות."],[10,"ווי למאן דאתמשיך אבתריה, דאיהו גרים ליה מותא ולכל דאתיין אבתריה, והא אוקמוה.","ווי למי שנמשך אחריו, דהיינו לאדם הראשון, שהוא גרם המות, לו ולכל הבאים אחריו. וכבר בארוהו."],[10,"אדם אתמשיך אבתריה לתתא, ונחית למנדע בכל מה דלתתא:","אדם הראשון, נמשך אחר הנחש למטה, וירד לדעת בכל מה שלמטה. כלומר שירד להמשיך הארת השמאל ממעלה לכל מה שלמטה, דהיינו עד מקום המלכות החסרה, כמו הנחש. כנ\"ל (באות רפ\"ה ד\"ה ועל דא ע\"ש) ובזה נמצא שנמשך אחר הנחש. \u0003כמה דנחית הכי אתמשיך רעותיה ואורחוי אבתרייהו,\u0004 כמו שירד, דהיינו, שירד להמשיך ממעלה למטה, כן נמשכו רצונו ודרכיו אחריהם, דהיינו אחרי הקליפות, כי המשכת הארת הזווג ממעלה למטה, ה\"ס איסור עצה\"ד, כנ\"ל (באות רפ\"ד ד\"ה עד) וע\"כ כיון שבא להמשיך ממעלה למטה, תכף נתדבק בהקליפות, אע\"פ שעוד לא המשיך בפועל. \u0003עד דמטין להאי חויא וחמו תיאובתיה דעלמא,\u0004 עד שבאו לאותו הנחש, וראו תשוקתו של העולם, פירוש. המלכות נקראת עולם, ונתבאר לעיל (באות רפ\"ד ד\"ה עד) שבחינתה עצמה חסרה בהתפשטות שלמטה מחזה, אשר חסרון הזה לא יוכל להמנות מטרם גמר התקון, ולפיכך כל תשוקת המלכות היא להשלמה הזאת. וז\"ש \u0003וחמו תיאובתיה דעלמא,\u0004 דהיינו שראו מקום החסרון של המלכות הנקראת עולם שתשוקתה גדולה להשלמה. \u0003ושטו אורחוי באתר דא,\u0004 ונטו ונלוזו דרכיו במקום הזה, דהיינו מקום המלכות הנ\"ל, שה\"ס אכילת עץ הדעת, (כנ\"ל באות רפ\"ד ד\"ה עד) \u0003כדין קם ואתמשיך איהו אבתרייהו דאדם ואתתיה, ואתדבק בהו וגרים להו מותא,\u0004 אז קם ונמשך הנחש אחרי אדם ואשתו ונתדבק בהם בזוהמתו, וגרם להם המות. \u0003ובכל דרי דאתו אבתריה עד דמטו ישראל לטורא דסיני, לא פסק זוהמא דיליה מעלמא, והא אתמר.\u0004 ובכל הדורות הבאים אחריו, עד שעמדו ישראל בהר סיני, לא נפסק זוהמא שלו מהעולם. וכבר נאמר זה."],[10,"כיון דחטו ואתדבקו באילנא דשריא ביה מותא לתתא, מה כתיב, וישמעו את קול ה' אלקים וגו', מהלך אין כתיב כאן אלא מתהלך:","כיון שחטאו ונתדבקו בהאילן שהמות שורה בו למטה, מה כתוב, וישמעו וגו' מתהלך בגן, מהלך לא כתוב כאן, שהוא לשון זכר, אלא שכתוב מתהלך, שהוא לשון נקבה כי \u0003ת'\u0004 הנוספת הוא לשון נקבה."],[11,"ת\"ח עד לא חטא אדם, הוה סליק וקאי בחכמה דנהירו עלאה, ולא הוה מתפרש מאילנא דחיי,","בוא וראה, מטרם שחטא האדם, היה עולה במדרגותיו, והיה עומד בחכמה העליונה, ולא היה נפרד מעץ החיים. \u0003כיון דאסגי תיאובתא למנדע ולנחתא לתתא, אתמשך אבתרייהו, עד דאתפרש מאילנא דחיי,\u0004 כיון שהרבה תשוקה לדעת ולירד למטה, דהיינו להמשיך ממעלה למטה, כנ\"ל (באות רפ\"ד ד\"ה עד) נמשך בזה אחריהם, עד שנפרד מעץ החיים \u0003וידע רע ושבק טוב,\u0004 וידע את הרע ועזב את הטוב, דהיינו כנ\"ל (באות רפ\"ד ד\"ה עד) לא זכי הא רע עש\"ה. \u0003ועל דא כתיב כי לא אל וגו' מאן דאתמשך בתר רע לית ליה דירה עם אילנא דחיי.\u0004 וע\"כ כתוב, כי לא אל וגו' לא יגורך רע, כי מי שנמשך אחר הרע, אין לו דירה ביחד עם עץ החיים."]],[[0,"","מִתְגַּלְגְּלִים הַכִּסְאוֹת אֶחָד בְּאֶחָד, (יורדים ולוקחים) לוֹקְחִים כָּל אוֹתָן הָרְשָׁתוֹת לְתוֹכָם וּמַכְנִיסִים אוֹתָם לְתַחְתִּית הַתְּהוֹם הַתַּחְתּוֹנָה. עוֹמֵד כִּסֵּא אֶחָד וְעוֹלֶה לְמַעְלָה מִכָּל אוֹתָם הַתְּהוֹמוֹת, וְעוֹמֵד כִּסֵּא אַחֵר לְמַטָּה שֶׁל כָּל הַתְּהוֹמוֹת. בֵּין שְׁנֵי כִסְאוֹת אֵלּוּ מִתְגַּלְגְּלִים כָּל אוֹתָם תְּהוֹמוֹת. וְכָל אוֹתָם צִנּוֹרוֹת נִנְעֲצוּ בֵּין שְׁנֵי הַכִּסְאוֹת הַלָּלוּ."],[1,"","שִׁבְעִים וַחֲמִשָּׁה (אורות) צִנּוֹרוֹת הֵם. שִׁבְעָה הֵם עֶלְיוֹנִים שֶׁל הַכֹּל, וְכָל אוֹתָם אֲחֵרִים אֲחוּזִים בָּהֶם, וְכֻלָּם נְעוּצִים בְּגַלְגַּלֵּי הַכִּסֵּא הַזֶּה בַּצַּד הַזֶּה, וּנְעוּצִים בְּגַלְגַּלֵּי הַכִּסֵּא הַזֶּה בַּצַּד הַזֶּה."],[2,"","בָּהֶם (נ\"א: בתהומות) מַיִם עוֹלִים וְיוֹרְדִים. אוֹתָם שֶׁיּוֹרְדִים כּוֹרִים בַּתְּהוֹמוֹת וּבוֹקְעִים אוֹתָם. אוֹתָם שֶׁעוֹלִים נִכְנָסִים בְּאוֹתָם נִקְבֵי הָאֲבָנִים, וְעוֹלִים וּמְמַלְּאִים לְשִׁבְעַת הַיַּמִּים. עַד כָּאן שִׁבְעָה גְוָנִים שֶׁל אוֹרוֹת בְּסוֹד עֶלְיוֹן."],[3,"","שִׁבְעָה אוֹרוֹת אֲחֵרִים נֶחֱלָקִים לְשִׁבְעָה יַמִּים, וְיָם אֶחָד כּוֹלֵל אוֹתָם. אוֹתוֹ הַיָּם הָאֶחָד הוּא יָם הָעֶלְיוֹן שֶׁכָּל שִׁבְעַת הַיַּמִּים כְּלוּלִים בּוֹ."],[4,"","שִׁבְעָה אוֹרוֹת הַלָּלוּ נִכְנָסִים לְתוֹךְ אוֹתוֹ הַיָּם וּמַכִּים בּוֹ לַיָּם (לשבעים) לְשִׁבְעָה צְדָדִים. וְכָל צַד וְצַד נֶחֱלָק לְשִׁבְעָה נְחָלִים, כַּכָּתוּב (ישעיה יא) וְהִכָּהוּ לְשִׁבְעָה נְחָלִים וְגוֹ'. וְכָל נַחַל וְנַחַל נֶחֱלָק לְשִׁבְעָה נְהָרוֹת, וְכָל נָהָר וְנָהָר נֶחֱלָק לְשֶׁבַע דְּרָכִים, וְכָל דֶּרֶךְ וְדֶרֶךְ נֶחֱלֶקֶת לְשִׁבְעָה שְׁבִילִים, וְכָל מֵימֵי הַיָּם כֻּלָּם נִכְנָסִים לְתוֹכָם."],[5,"","שִׁבְעָה אוֹרוֹת עוֹלִים וְיוֹרְדִים לְשִׁבְעָה צְדָדִים. שִׁבְעָה אוֹרוֹת עֶלְיוֹנִים נִכְנָסִים לְתוֹךְ הַיָּם. שִׁשָּׁה הֵם, וּמֵעֶלְיוֹן אֶחָד יוֹצְאִים. כְּמוֹ שֶׁנּוֹטֵל הַיָּם, כָּךְ מְחַלֵּק מֵימָיו לְכָל אוֹתָם יַמִּים, לְכָל אוֹתָם נְהָרוֹת."],[6,"","תַּנִּין אֶחָד לְמַטָּה בְּצַד שְׂמֹאל שָׁט בְּכָל אוֹתָם נְהָרוֹת בָּא בַּצַּד. קַשְׂקַשָּׂיו כֻּלָּם חֲזָקִים כְּבַרְזֶל, וּמַגִּיעַ לִשְׁאֹב, וְשׁוֹאֵב מְקוֹמָהּ. וְכָל אוֹתָם הָאוֹרוֹת נֶחְשָׁכִים לְפָנָיו. פִּיו וּלְשׁוֹנוֹ לוֹהֲטִים אֵשׁ. (חד לשונו) מְחֻדֶּדֶת לְשׁוֹנוֹ כְּחֶרֶב חֲזָקָה."],[7,"","עֵד שֶׁמַּגִּיעַ לְהִכָּנֵס לַמִּקְדָּשׁ לְתוֹךְ הַיָּם, וְאָז מְטַמֵּא אֶת הַמִּקְדָּשׁ וְהָאוֹרוֹת נֶחְשָׁכִים, וְאוֹרוֹת עֶלְיוֹנִים עוֹלִים מֵהַיָּם. וְאָז נֶחֱלָקִים מֵימֵי הַיָּם בְּצַד שְׂמֹאל, וְהַיָּם קוֹפֵא וּמֵימָיו לֹא זוֹרְמִים."],[8,"","וְעַל זֶה סוֹד הַדָּבָר, כְּמוֹ שֶׁכָּתוּב וְהַנָּחָשׁ הָיָה עָרוּם מִכֹּל חַיַּת הַשָּׂדֶה אֲשֶׁר עָשָׂה ה' אֱלֹהִים. סוֹד הַנָּחָשׁ הָרָע יוֹרֵד מִלְּמַטָּה לְמַעְלָה (ס\"י מלמעלה למטה), וְהוּא שָׁט עַל פְּנֵי הַמַּיִם הַמְּרִירִים, וְיוֹרֵד לְפַתּוֹת לְמַטָּה עַד שֶׁיִּפְּלוּ לְתוֹךְ רִשְׁתּוֹ."],[9,"","הַנָּחָשׁ הַזֶּה הוּא מָוֶת שֶׁבָּעוֹלָם, וְהוּא נִכְנָס בְּמֵעָיו הַנִּסְתָּרִים שֶׁל הָאָדָם. הוּא לְצַד שְׂמֹאל. וְיֵשׁ נָחָשׁ אַחֵר שֶׁל הַחַיִּים בְּצַד יָמִין. שְׁנֵיהֶם הוֹלְכִים עִם בֶּן הָאָדָם כְּמוֹ שֶׁבֵּאַרְנוּהָ."],[10,"","מִכֹּל חַיַּת הַשָּׂדֶה, שֶׁהֲרֵי כָּל שְׁאָר חַיּוֹת הַשָּׂדֶה אֵין בָּהֶם חָכָם לְהָרַע כְּמוֹ זֶה, מִשּׁוּם שֶׁהוּא זֻהֲמַת הַזָּהָב. אוֹי לְמִי שֶׁנִּמְשָׁךְ אַחֲרָיו, שֶׁהוּא גוֹרֵם לוֹ מָוֶת וּלְכָל מִי שֶׁהוֹלֵךְ אַחֲרָיו, וַהֲרֵי בֵּאַרְנוּהָ. אָדָם נִמְשָׁךְ אַחֲרָיו לְמַטָּה וְיוֹרֵד לָדַעַת בְּכָל מַה שֶּׁלְּמַטָּה. כְּמוֹ שֶׁיּוֹרֵד, כָּךְ נִמְשָׁךְ רְצוֹנוֹ וְדַרְכּוֹ אַחֲרֵיהֶם, עַד שֶׁמַּגִּיעִים לַנָּחָשׁ הַזֶּה וְרוֹאִים תַּאֲוַת הָעוֹלָם וּדְרָכָיו שָׁטִים בְּמָקוֹם זֶה. אָז קָם, וְהוּא נִמְשַׁךְ אַחַר אָדָם וְאִשְׁתּוֹ וְנִדְבַּק בָּהֶם, וְגָרַם לָהֶם מָוֶת וּלְכָל הַדּוֹרוֹת שֶׁבָּאוּ אַחֲרָיו. עַד שֶׁהִגִּיעוּ יִשְׂרָאֵל לְהַר סִינַי, לֹא פָסְקָה זֻהַמְתּוֹ מֵהָעוֹלָם, וַהֲרֵי נִתְבָּאֵר. כֵּיוָן שֶׁחָטְאוּ וְנִדְבְּקוּ בָּעֵץ שֶׁשּׁוֹרֶה בּוֹ מָוֶת לְמַטָּה, מַה כָּתוּב? וַיִּשְׁמְעוּ אֶת קוֹל ה' אֱלֹהִים מִתְהַלֵּךְ בַּגָּן. מְהַלֵּךְ אֵין כָּתוּב כָּאן, אֶלָּא מִתְהַלֵּךְ."],[11,"","בֹּא רְאֵה, עַד שֶׁאָדָם לֹא חָטָא, הָיָה עוֹלֶה וְעוֹמֵד בְּחָכְמַת הָאוֹר הָעֶלְיוֹן וְלֹא הָיָה נִפְרָד מֵעֵץ הַחַיִּים. כֵּיוָן שֶׁהִגְדִּיל תַּאֲוָתוֹ לָדַעַת וְלָרֶדֶת לְמַטָּה, נִמְשַׁךְ אַחֲרֵיהֶם עַד שֶׁנִּפְרַד מֵעֵץ הַחַיִּים, וְיָדַע רָע וְעָזַב הַטּוֹב. וְעַל זֶה כָּתוּב (תהלים ה) כִּי לֹא אֵל חָפֵץ רֶשַׁע אָתָּה לֹא יְגֻרְךְ רָע. מִי שֶׁנִּמְשָׁךְ אַחַר רָע, אֵין לוֹ דִּירָה עִם עֵץ הַחַיִּים."]]],[["וְעַד לָא חָטְאוּ הֲווּ שָׁמְעִין קָלָא מִלְּעֵילָא וְהֲווּ יָדְעֵי חָכְמְתָא עִלָּאָה וְקָיְימֵי בְּקִיּוּמָא דְזִיהֲרָא עִלָּאָה וְלָא דָחֲלֵי. כֵּיוָן דְּחָטְאוּ אֲפִילּוּ קָלָא דִּלְתַתָּא לָא הֲוֵי יָכְלִין לְמֵיקַם בֵּיהּ.","כְּגַוְונָא דָא עַד לָא חָבוּ יִשְׂרָאֵל בְּשַׁעֲתָא דְּקָיְימוּ יִשְׂרָאֵל עַל טוּרָא דְסִינַי אִתְעֲבַר מִנַּיְיהוּ זוּהֲמָא דְּהַאי חִיוְיָא. דְּהָא כְּדֵין בִּטּוּל יֵצֶר הָרָע הֲוָה מֵעָלְמָא וְדָחוּ לֵיהּ מִנַּיְיהוּ. וּכְדֵין אִתְאֲחִידוּ בְּאִילָנָא דְחַיֵּי וְסָלְקוּ לְעֵילָא וְלָא נָחֲתוּ לְתַתָּא.","כְּדֵין הֲווּ יָדְעִין וְחָמָאן אִסְפַּקְלַרְיָאן עִלָּאִין וְאִתְנָהֲרִין עֵינַיְיהוּ וְחָדָאן לְמִנְדַע וּלְמִשְׁמַע. וּכְדֵין חָגַר לוֹן קוּדְשָׁא בְּרִיךְ הוּא חֲגוֹרִין דְאַתְוָון דִּשְׁמֵיהּ קַדִּישָׁא דְּלָא יֵיכוּל לְשַׁלְטָאָה עֲלַיְיהוּ הַאי חִוְיָא וְלָא יְסָאַב לוֹן כְּקַדְמִיתָא.","כֵּיוָן דְּחָטְאוּ בָּעֵגֶל אִתְעֲבַר מִנַּיְיהוּ כָּל אִנּוּן דַּרְגִּין וּנְהוֹרִין עִלָּאִין. וְאִתְעַבְּרוּ מִנַּיְיהוּ אִנּוּן חֲגִירוּ מְזַיְינִין דְּאִתְעַטְּרוּ מִשְׁמָא עִלָּאָה קַדִּישָׁא. וְאַמְשִׁיכוּ עֲלַיְיהוּ חִוְיָא בִישָׁא כְּמִלְקַדְּמִין וְגָרְמוּ מוֹתָא לְכָל עַלְמָא. וּלְבָתַר מַה כְּתִיב (שמות לג) וַיַּרְא אַהֲרֹן וְכָל בְּנֵי יִשְׂרָאֵל אֶת משֶׁה וְהִנֵּה קָרַן עוֹר פָּנָיו וַיִּירְאוּ מִגֶּשֶׁת אֵלָיו.","תָּא חֲזֵי, מַה כְּתִיב בְּקַדְמִיתָא (שמות י״ד:ל״א) וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדוֹלָה וְכֻלְהוּ חָמָאן זָהֲרִין עִלָּאִין וּמִתְנַהֲרִין בְּאִסְפַּקְלַרְיָא דְּנָהֲרָא דִּכְתִיב, (שמות כ׳:ט״ו) וְכָל הָעָם רוֹאִים אֶת הַקּוֹלוֹת. וְעַל יַמָּא הֲווּ חָמָאן וְלָא דָחֲלִין דִּכְתִיב, (שמות ט״ו:ב׳) זֶה אֵלִי וְאַנְוֵהוּ. לְבָתַר דְּחָטוּ, פְּנֵי הַסַּרְסוּר לָא הֲווּ יָכְלִין לְמֶחֱמֵי דִּכְתִיב (שמות לה) וַיִּירְאוּ מִגֶּשֶׁת אֵלָיו.","תָּא חֲזֵי, מַה כְּתִיב בְּהוּ (שמות ל״ג:ו׳) וַיִּתְנַצְּלוּ בְּנֵי יִשְׂרָאֵל אֶת עֶדְיָם מֵהַר חוֹרֵב. דְּאִתְעֲבַר מִנַּיְיהוּ אִנּוּן מְזַיְינָן (דאתחברו בהו ד\"א דאתחגרו בהון) בְּטוּרָא דְסִינַי בְּגִין דְּלָא יִשְׁלוֹט בְּהוּ הַהוּא חִוְיָא בִישָׁא. כֵּיוָן דְּאִתְעֲבַר מִנַּיְיהוּ מַה כְּתִיב, (שמות ל״ג:ז׳) וּמשֶׁה יִקַּח אֶת הָאֹהֶל וְנָטָה לוֹ מִחוּץ לַמַּחֲנֶה הַרְחֵק מִן הַמַּחֲנֶה.","אָמַר רַבִּי אֶלְעָזָר מַאי הַאי קְרָא לְגַבֵּי הַאי. אֶלָּא כֵּיוָן דְּיָדַע משֶׁה דְּאִתְעֲבָרוּ מִנַּיְיהוּ דְיִשְׂרָאֵל אִנּוּן זַיְינִין עִלָּאִין, אָמַר הָא וַדַּאי מִכָּאן וּלְהָלְאָה חִוְיָא בִישָׁא יֵיתֵי לְדַיְירָא בֵּינַיְיהוּ, וְאִי יָקוּם מַקְדְּשָׁא הָכָא בֵּינַיְיהוּ, יִסְתָּאַב. מִיָּד וּמשֶׁה יִקַּח אֶת הָאֹהֶל וְנָטָה לוֹ מִחוּץ לַמַּחֲנֶה הַרְחֵק מִן הַמַּחֲנֶה. בְּגִין דְּחָמָא משֶׁה דְּהָא כְּדֵין יִשְׁלוֹט חִוְיָא בִישָׁא מַה דְּלָא הֲוָה מִקַּדְמַת דְּנָא.","וְקָרָא לוֹ אֹהֶל מוֹעֵד, וְכִי לָא הֲוָה בְּקַדְמִיתָא אֹהֶל מוֹעֵד. אֶלָּא בְּקַדְמִיתָא אֹהֶל סְתָם, הַשְׁתָּא אֹהֶל מוֹעֵד. מַאי מוֹעֵד. רַבִּי אֶלְעָזָר אָמַר לְטַב. וְרַבִּי אַבָּא אָמַר לְבִישׁ. רַבִּי אֶלְעָזָר אָמַר לְטַב מַה מּוֹעֵד דְּאִיהוּ יוֹם חֶדְוָה דְּסִיהֲרָא דְּאִתּוֹסְפָא בֵּיהּ קְדוּשָׁה (מה מועד) לָא שָׁלְטָא בֵּיהּ פְּגִימוּתָא. אוּף הָכָא קָרָא לָהּ בִּשְׁמָא דָא לְאַחֲזָאָה דְּהָא אִתְרַחֵיק (חויא) אֹהֶל מִבֵּינַיְיהוּ וְלָא אִתְפְּגִים וְעַל דָּא וְקָרָא לוֹ אֹהֶל מוֹעֵד כְּתִיב.","וְרַבִּי אַבָּא אָמַר לְבִישׁ דְּהָא בְּקַדְמִיתָא הֲוָה אֹהֶל סְתָם כְּמָא דְאַתְּ אָמֵר, (ישעיהו ל״ג:כ׳) אֹהֶל בַּל יִצְעָן בַּל יִסַּע יְתֵדוֹתָיו לָנֶצַח. וְהַשְׁתָּא אֹהֶל מוֹעֵד. בְּקַדְמִיתָא לְמֵיהַב חַיִּין אֲרוּכִּין לְעָלְמִין דְּלָא יִשְׁלוֹט בְּהוּ מוֹתָא. מִכָּאן וּלְהָלְאָה אֹהֶל מוֹעֵד כְּמָא דְאַתְּ אָמֵר, (איוב ל׳:כ״ג) וּבֵית מוֹעֵד לְכָל חָי. הַשְׁתָּא אִתְיְיהִיב בֵּיהּ זִמְנָא וְחַיִּין קְצוּבִין לְעָלְמָא. בְּקַדְמִיתָא לָא אִתְפְּגִים, וְהַשְׁתָּא אִתְפְּגִים. בְּקַדְמִיתָא חַבְרוּתָא וְזִוּוּגָא דְסִיהֲרָא בְּשִׁמְשָׁא דְלָא יַעֲדוּן. הַשְׁתָּא אוֹהֶל מוֹעֵד זִוּוּגָא דִלְהוֹן מִזְמַן לִזְמַן. וּבְגִינֵי כָךְ וְקָרָא לוֹ אֹהֶל מוֹעֵד מַה דְּלָא הֲוָה קוֹדֶם.","רַבִּי שִׁמְעוֹן הֲוָה יָתִיב לֵילְיָא חַד וְלָעֵי בְּאוֹרַיְיתָא. וְהֲווּ יַתְבֵי קַמֵּיהּ רַבִּי יְהוּדָה וְרַבִּי יִצְחָק וְרַבִּי יוֹסֵי. אָמַר רַבִּי יְהוּדָה הָא כְּתִיב, (שמות ל״ג:ו׳) וַיִּתְנַצְּלוּ בְּנֵי יִשְׂרָאֵל אֶת עֶדְיָם מֵהַר חוֹרֵב, וְקָאַמְרִינָן דְּגָרְמוּ מוֹתָא עֲלַיְיהוּ מֵהַהוּא זִמְנָא וּלְעֵילָא, וְשַׁלִּיט בְּהוּ הַהוּא חִוְיָא בִישָׁא דְּאַעָדוּ לֵיהּ מִנַּיְיהוּ בְּקַדְמִיתָא. יִשְׂרָאֵל תֵּינַח. יְהוֹשֻׁעַ דְּלָא חָטָא, אַעֲדֵי (ד\"א אתעדי) מִנֵּיהּ הַהוּא זַיְינָא עִלָּאָה דְּקַבִּיל עִמְּהוֹן בְּטוּרָא דְסִינַי אוֹ לָא."],[[0,"ועד לא חטאו הוו שמעין קלא מלעילא והוו ידעי חכמתא עלאה, וקיימי בקיומא דזיהרא עלאה ולא דחלי:","ועד שלא חטאו היו שומעים הקול של מעלה, והיו יודעים חכמה העליונה, והיו נמצאים בהמוחין של זהר העליון, ולא יראו, \u0003כיון דחטאו תפילו קלא דלתתא לא הוי יכלין למיקם ביה,\u0004 כיון שחטאו, אפילו קול של מטה, לא היו יכולים לעמוד בו, פירוש, קול ז\"א הוא קול של מעלה, ושל הנוקבא הוא קול של מטה. והכתוב קול ה' אלקים מתהלך בגן, הוא קול הנוקבא, כי הת' של מתהלך יורה על לשון נקבה, כנ\"ל. ומ\"מ לא יכול לעמוד בו, כי נאמר ויתחבא וגו'."],[1,"כגוונא דא, עד לא חבו ישראל בשעתא דקיימו ישראל על טורא דסיני אתעבר מנייהו זוהמא דהאי חיויא:","כעין זה, כל עוד שלא חטאו ישראל, מעת שעמדו ישראל על הר סיני, הוסרה מהם הזוהמא של נחש הזה. \u0003דהא כדין בטול יצר הרע הוה מעלמא, ודחו ליה מנייהו,\u0004 כי אז היה ביטול יצר הרע מהעולם, שדחו אותו מהם, \u0003וכדין אתאחידו באילנא דחיי, וסלקו לעילא ולא נחתו לתתא,\u0004 ואז נאחזו בעץ החיים, ועלו למעלה ולא ירדו למטה, כלומר שהעלו האור דשמאל ממטה למעלה, ולא המשיכו אותם ממעלה למטה, שזהו בחינת עץ החיים, (כנ\"ל ב\"א דף ר\"כ ד\"ה ויפח ע\"ש)."],[2,"כדין הוו ידעין וחמאן אספקלריאן עלאין, אתנהרו עינייהו וחדאן למנדע ולמשמע:","אז היו יודעים ורואים את אספקלריות העליונות, והאירו עיניהם והיו שמחים לדעת ולשמוע. אספקלריאן, פירושו מנורות של זכוכית, וסובב על השגת ז\"א ונוקביה, כי ז\"א מכונה אספקלריאה המאירה, והנוקבא מכונה אספקלריאה שאינה מאירה. \u0003וכדין חגר לון קוב\"ה חגורין דאתוון דשמיה קדישא, דלא ייכול לשלטאה עלייהו האי חויא ולא יסאב לון כקדמיתא,\u0004 ואז חגר אותם הקב\"ה חגורות מהאותיות של שמו הקדוש, שלא יוכל לשלוט עליהם נחש הזה, ולא יטמא אותם כבתחילה. שה\"ס \u0003עדיים\u0004 שקבלו בהר חורב."],[3,"כיון דחטאו בעגל אתעבר מנייהו כל אינון דרגין ונהורין עלאין:","כיון שחטאו בעגל נעברו מהם כל אלו המדרגות ואורות העליונים. \u0003ואתעברו מנייהו אינון חגירו מזיינין דאתעטרו משמא עלאה,\u0004 ונעברו מהם אלו חגורות המזוינות, שנעטרו מהשם העליון, \u0003ואמשיכו עלייהו חויא בישא כמלקדמין, וגרמו מותא לכל עלמא,\u0004 והמשיכו עליהם את הנחש הרע כבתחילה, וגרמו המות לכל העולם."],[4,"ולבתר מה כתיב, וירא אהרן וגו' ת\"ח מה כתיב בקדמיתא וירא ישראל וגו' וכלהו חמאן זהרין עלאין:","ואחר זה מה כתוב, וירא אהרן וגו' ויראו מגשת אליו, בוא וראה בתחילה מה כתוב, וירא ישראל את היד הגדולה, וכולם ראו האורות העליונים. \u0003ומתנהרין באספקלריא דנהרא, דכתיב וכל העם רואים וגו', ועל ימא הוו חמאן ולא דחלין דכתיב זה אלי ואנוהו,\u0004 ונאורו באספקלריא המאירה, שהוא ז\"א, שכתוב וכל העם רואים וגו', וכן על הים ראו ולא יראו, שכתוב שם, זה אלי ואנוהו. \u0003לבתר דחטו, פני הסרסור לא הוו יכלין למחמי דכתיב וייראו מגשת אליו,\u0004 אחר שחטאו, אפילו את פני הסרסור, שהוא משה, לא היו יכולים לראות שכתוב, ויראו מגשת אליו."],[5,"ת\"ח מה כתיב בהו, ויתנצלו וגו' דאתעבר מנייהו אינון מזיינן דאתחגרו בהון בטורא דסיני, בנין דלא וכו':","בוא וראה מה כתיב בהם, בישראל, ויתנצלו בני ישראל את עדיים וגו' שנעבר מהם הזיון שנחגרו בהם בהר סיני, כדי שלא ישלוט בהם נחש הרע. כנ\"ל באות רצ\"א, \u0003כיון דאתעבר מנייהו מה כתיב, ומשה יקח וגו'\u0004"],[6,"אמר רבי אלעזר, מה האי קרא לגבי האי:","כיון שנעבר מהם עדיים, מה כתוב, ומשה יקח את האהל וגו', אר\"א, מהו הסמיכות של מקרא הזה לענין הזה, של הסרת עדיים. ומשיב, \u0003אלא כיון דידע משה דאתעברו מנייהו דישראל אינון זיינין עלאין,\u0004 אלא מאחר שידע משה שנעברו מהם זיונים אלו העליונים, דהיינו שנתנצלו את עדים, \u0003אמר, הא ודאי מכאן ולהלאה, חויא בישא ייתי לדיירא בינייהו, ואי יקום מקדשא הכא בינייהו יסתאב,\u0004 אמר, הרי ברור שמכאן והלאה, יבא נחש הרע לדור ביניהם, וע\"כ אם יקום כאן בית המקדש הוא יטמא. \u0003מיד ומשה יקח את האהל וגו' בגין דחמא משה דהא כדין ישלוט חויא בישא, מה דלא הוה מקדמת דנא.\u0004 מיד, ומשה יקח את האהל וגו', משום שמשה ראה, כי עתה ימשול עליהם נחש הרע, מה שלא היה זה מקודם לכן."],[7,"וקרא לו אהל מועד. וכי לא הוה בקדמיתא אהל מועד. אלא בקדמיתא אהל סתם השתא אהל מועד.","כתוב, וקרא לו אהל מועד. ומקשה וכי בתחילה לא היה נקרא אהל מועד. ומשיב אלא מתחילה היה נקרא סתם אהל, ועתה קרא לו אהל מועד. \u0003מאי מועד. רבי אלעזר אמר לטב, רבי אבא אמר לביש.\u0004 שואל מה פירושו של מועד. ואומר, שר' אלעזר מפרשו לשבח לטוב, ור' אבא מפרשו לרע לגנאי. ומפרש \u0003ר' אלעזר אמר לטב מה מועד דאיהו יום חדוה דסיהרא, דאתוספא ביה קדושה, לא שלטא ביה פגימותא,\u0004 רבי אלעזר מבאר המלה מועד לטוב, כי, מה מועד דהיינו יום טוב, שהוא שמחת הלבנה, דהיינו השכינה, כי נתוסף קדושה בהשכינה, ואין שום פגם שולט בה ביום הזה. \u0003אוף הכא קרא לה בשמא דא לאחזאה דהא אתרחיק אהל מבינייהו ולא אתפגים, וע\"ד וקרא לו אהל מועד כתיב,\u0004 אף כאן קרא לה להשכינה בשם הזה, \u0003מועד,\u0004 להראות כי האהל, שהיא השכינה, נתרחק מהם בשעת חטא העגל, ולא נפגם, וע\"כ וקרא לו אהל מועד כתיב."],[8,"ורבי אבא אמר לביש. דהא בקדמיתא הוה אהל סתם, כד\"א אהל בל יצען וגו', והשתא אהל מועד:","ורבי אבא מפרש המלה מועד לרע. כי מקודם לכן לאחר מתן תורה, היתה השכינה סתם אהל. כמו שאתה אומר, אהל בל יצען בל יסע יתדותיו לנצח, דהיינו בהארה תמידית. ועתה, אחר החטא של העגל, נעשה אהל מועד, דהיינו שמאיר מזמן לזמן ואינו תמידי. \u0003בקדמיתא, למיהב חיין ארוכין לעלמין, דלא ישלוט בהו מותא, מכאן ולהלאה אהל מועד, כד\"א ובית מועד לכל חי,\u0004 מקודם לכן, היה האהל נותן חיים ארוכים להעולם, שלא ישלוט בהם המות, כי לאחר מתן תורה נעשה חרות ממלאך המות, ומחטא העגל והלאה נעשה השכינה אהל מועד, כמו שאתה אומר ובית מועד לכל חי, \u0003השתא אתייהיב ביה זמנא וחיין קצובין לעלמא,\u0004 עתה ניתן בו זמן, והחיים קצובים להעולם."],[8,"בקדמיתא לא אתפגים והשתא אתפגים:","בתחילה, מטרם חטא העגל, לא נפגם האהל, ועתה נפגם בחטא העגל. \u0003בקדמיתא חברותא וזווגא דסיהרא בשמשא דלא יעדון, השתא אהל מועד זווגא דלהון מזמן לזמן,\u0004 בתחילה החיבור והזווג של לבנה עם השמש, שהם זו\"ן, היה בלתי נפסק, ועתה נקרא אהל מועד, כי הזווג שלהם הוא מזמן לזמן, מחמת שנפסק הזווג מכח קרבת הנחש לינק, כמ\"ש לפנינו. \u0003ובגיני כך וקרא לו אהל מועד, מה דלא הוה קודם,\u0004 ומשום זה נאמר עתה וקרא לו אהל מועד, שפירושו שהזווג נעשה מזמן לזמן, מה שלא היה כן מקודם לכן, כי אז, לאחר מתן תורה, כבר היו זו\"ן בזווג דלא פסיק לעלמין, וע\"כ היתה נקראת אהל סתם כנ\"ל."],[9,"רבי שמעון הוה יתיב ליליא חד ולעי באורייתא, והוו יתבי קמיה. ר' יהודה ור' יצחק ור' יוסי:","רבי שמעון ה\"ה יושב לילה אחד ועוסק בתורה, והיו יושבים לפניו ר' יהודה ור' יצחק ור' יוסי. \u0003אמר ר\"י הא כתיב ויתנצלו בני ישראל את עדים מהר חורב, וקאמרינן דגרמו מותא עלייהו מההוא זמנא ולעילא,\u0004 אר\"י הרי כתוב ויתנצלו וגו' ואמרינן, שע\"י חטא העגל, גרמו המות לעצמם מזמן ההוא ולמעלה, \u0003לשליט בהו ההוא חויא בישא דאעדו ליה מנייהו בקדמיתא,\u0004 ומשל בהם אותו נחש הרע שכבר הסירו אותו מקודם. כמ\"ש חרות על הלוחות שהיה להם חירות ממלאך המות. \u0003ישראל תינח, יהושע דלא חטא אעדי מניה ההוא זיינא עלאה דקביל עמהון בטורא דסיני, או לא.\u0004 ושואל, ישראל נכון, כי חטאו, אבל יהושע שלא חטא, ישאל, אם הוסר ממנו אותו עדי העליון שקבל עם ישראל בהר סיני או לא."]],[[0,"","וְעַד שֶׁלֹּא חָטְאוּ, הָיוּ שׁוֹמְעִים קוֹל מִלְמַעְלָה וְהָיוּ יוֹדְעִים חָכְמָה עֶלְיוֹנָה וְעוֹמְדִים בַּקִּיּוּם שֶׁל זהַר הָעֶלְיוֹן וְלֹא פוֹחֲדִים. כֵּיוָן שֶׁחָטְאוּ, אֲפִלּוּ קוֹל שֶׁלְּמַטָּה לֹא יָכְלוּ לַעֲמֹד בּוֹ."],[1,"","כְּמוֹ זֶה, עַד שֶׁלֹּא חָטְאוּ יִשְׂרָאֵל, בְּשָׁעָה שֶׁעָמְדוּ יִשְׂרָאֵל עַל הַר סִינַי נִתְבַּטְּלָה מֵהֶם זֻהֲמַת הַנָּחָשׁ הַזֶּה, שֶׁהֲרֵי אָז בִּטּוּל יֵצֶר הָרָע הָיָה מֵהָעוֹלָם וְדָחוּ אוֹתוֹ מֵהֶם, וְאָז נֶאֶחְזוּ בְּעֵץ הַחַיִּים וְעָלוּ לְמַעְלָה וְלֹא יָרְדוּ לְמַטָּה."],[2,"","אָז הָיוּ יוֹדְעִים וְרוֹאִים אַסְפַּקְלַרְיוֹת עֶלְיוֹנוֹת, וְעֵינֵיהֶם אוֹרוּ וּשְׂמֵחִים לָדַעַת וְלִשְׁמֹעַ. וְאָז חָגַר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא חֲגוֹרוֹת שֶׁל אוֹתִיּוֹת שְׁמוֹ הַקָּדוֹשׁ שֶׁלֹּא יוּכַל לִשְׁלֹט עֲלֵיהֶם הַנָּחָשׁ הַזֶּה וְלֹא יְטַמֵּא אוֹתָם כְּמוֹ קֹדֶם."],[3,"","כֵּיוָן שֶׁחָטְאוּ בָּעֵגֶל, בָּטְלוּ מֵהֶם כָּל אוֹתָן דְּרָגוֹת וְאוֹרוֹת עֶלְיוֹנִים, וּבָטְלוּ מֵהֶם אוֹתָן חֲגוֹרוֹת מְזֻיָּנוֹת שֶׁהִתְעַטְּרוּ מֵהַשֵּׁם הָעֶלְיוֹן הַקָּדוֹשׁ, וְהִמְשִׁיכוּ עֲלֵיהֶם נָחָשׁ הָרָע כְּמוֹ מִקֹּדֶם וְגָרְמוּ מָוֶת לְכָל הָעוֹלָם. וְאַחַר כָּךְ מַה כָּתוּב? (שמות לד) וַיַּרְא אַהֲרֹן וְכָל בְּנֵי יִשְׂרָאֵל אֶת מֹשֶׁה וְהִנֵּה קָרַן עוֹר פָּנָיו וַיִּירְאוּ מִגֶּשֶׁת אֵלָיו."],[4,"","בֹּא רְאֵה מַה כָּתוּב בַּתְּחִלָּה (שמות יד), וירא ישראל את היד הגדלה. וכלם רואים אורות עליונים ומאירים באספקלריה שמאירה, שכתוב, (שם כ) וכל העם ראים את הקולת. ועל הים היו רואים ולא פוחדים, שכתוב (שם טו) זה אלי ואנוהו. אחר שחטאו, פני הסרסור לא היו יכולים לראות, שכתוב (שם לד) וייראו מגשת אליו."],[5,"","בֹּא רְאֵה מַה כָּתוּב בָּהֶם, (שם לג) וַיִּתְנַצְּלוּ בְנֵי יִשְׂרָאֵל אֶת עֶדְיָם מֵהַר חוֹרֵב, שֶׁבָּטְלוּ מֵהֶם אוֹתָם כְּלֵי זַיִן (שהתחברו בהם) (שהתחגרו בהם) בְּהַר סִינַי כְּדֵי שֶׁלֹּא יִשְׁלֹט בָּהֶם נָחָשׁ רָע. כֵּיוָן שֶׁבָּטְלוּ מֵהֶם מַה כָּתוּב? (שם) וּמֹשֶׁה יִקַּח אֶת הָאֹהֶל וְנָטָה לוֹ מִחוּץ לַמַּחֲנֶה הַרְחֵק מִן הַמַּחֲנֶה."],[6,"","אָמַר רַבִּי אֶלְעָזָר, מָה הַפָּסוּק הַזֶּה אֶל זֶה? אֶלָּא כֵּיוָן שֶׁיָּדַע מֹשֶׁה שֶׁבָּטְלוּ מִיִּשְׂרָאֵל אוֹתָם כְּלֵי זַיִן עֶלְיוֹנִים, אָמַר, הֲרֵי וַדַּאי מִכָּאן וָהָלְאָה נָחָשׁ רָע יָבֹא לָדוּר בֵּינֵיהֶם, וְאִם יָקוּם כָּאן מִקְדָּשׁ בֵּינֵיהֶם - יִטְמָא. מִיָּד - וּמֹשֶׁה יִקַּח אֶת הָאֹהֶל וְנָטָה לוֹ מִחוּץ לַמַּחֲנֶה הַרְחֵק מִן הַמַּחֲנֶה. כִּי רָאָה מֹשֶׁה שֶׁהֲרֵי אָז יִשְׁלֹט נָחָשׁ רָע מַה שֶּׁלֹּא הָיָה מִקֹּדֶם לָזֶה."],[7,"","וְקָרָא לוֹ אֹהֶל מוֹעֵד, וְכִי לֹא הָיָה בַּהַתְחָלָה אֹהֶל מוֹעֵד? אֶלָּא בַּהַתְחָלָה אֹהֶל סְתָם, וְכָעֵת אֹהֶל מוֹעֵד. מַה זֶּה מוֹעֵד? רַבִּי אֶלְעָזָר אָמַר לְטוֹב, וְרַבִּי אַבָּא אָמַר לְרַע. רַבִּי אֶלְעָזָר אָמַר לְטוֹב - מַה מּוֹעֵד שֶׁהוּא יוֹם חֶדְוָה שֶׁל הַלְּבָנָה שֶׁנִּתּוֹסְפָה בּוֹ קְדֻשָּׁה. (מה מועד) לֹא שׁוֹלֶטֶת בּוֹ חִסָּרוֹן, גַּם כָּאן קָרָא לָהּ בְּשֵׁם זֶה, לְהַרְאוֹת שֶׁהֲרֵי הִתְרַחֵק (נחש) אֹהֶל מִבֵּינֵיהֶם וְלֹא נִפְגַּם, וְעַל זֶה וְקָרָא לוֹ אֹהֶל מוֹעֵד כָּתוּב."],[8,"","וְרַבִּי אַבָּא אָמַר לְרַע - שֶׁהֲרֵי בַּהַתְחָלָה הָיָה אֹהֶל סְתָם, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה לג) אֹהֶל בַּל יִצְעָן בַּל יִסַּע יְתֵדתָיו לָנֶצַח, וְעַכְשָׁו אֹהֶל מוֹעֵד. בַּהַתְחָלָה לָתֵת חַיִּים אֲרֻכִּים לְעוֹלָמִים שֶׁלֹּא יִשְׁלֹט בָּהֶם מָוֶת, מִכָּאן וָהָלְאָה אֹהֶל מוֹעֵד, כְּמוֹ שֶׁנֶּאֱמַר (איוב ל) וּבֵית מוֹעֵד לְכָל חָי. עַכְשָׁו נִתָּן בּוֹ זְמַן וְחַיִּים קְצוּבִים לָעוֹלָם. בַּהַתְחָלָה לֹא נִפְגַּם, וְעַכְשָׁו נִפְגָּם. בַּהַתְחָלָה חַבְרוּתָא וְזִוּוּג שֶׁל הַלְּבָנָה בַּשֶּׁמֶשׁ שֶׁלֹּא יָסוּרוּ, עַכְשָׁו אֹהֶל מוֹעֵד, הַזִּוּוּג שֶׁלָּהֶם מִזְּמַן לִזְמַן. וְלָכֵן קָרָא לוֹ אֹהֶל מוֹעֵד מַה שֶּׁלֹּא הָיָה קֹדֶם."],[9,"","רַבִּי שִׁמְעוֹן הָיָה יוֹשֵׁב לַיְלָה אֶחָד וְעוֹסֵק בַּתּוֹרָה, וְהָיוּ יוֹשְׁבִים לְפָנָיו רַבִּי יְהוּדָה וְרַבִּי יִצְחָק וְרַבִּי יוֹסֵי. אָמַר רַבִּי יְהוּדָה, הֲרֵי כָּתוּב (שמות לג) וַיִּתְנַצְּלוּ בְנֵי יִשְׂרָאֵל אֶת עֶדְיָם מֵהַר חוֹרֵב, וְאָמַרְנוּ שֶׁגָּרְמוּ מָוֶת עֲלֵיהֶם מֵאוֹתוֹ זְמַן וָמַעְלָה, וְשׁוֹלֵט בָּהֶם אוֹתוֹ נָחָשׁ רָע שֶׁהֵסִירוּ אוֹתוֹ מֵהֶם בַּתְּחִלָּה. נַנִּיחַ יִשְׂרָאֵל, אֲבָל יְהוֹשֻׁעַ שֶׁלֹּא חָטָא, בָּטַל (יתבטל) מִמֶּנּוּ אוֹתוֹ כְּלִי זַיִן עֶלְיוֹן שֶׁקִּבֵּל עִמָּם בְּהַר סִינַי אוֹ לֹא."]]],[["אִי תֵימָא דְּלָא אַעֲדֵי (ד\"א אתעדי) מִנֵּיהּ, אִי הָכִי אַמַּאי מִית כִּשְׁאָר בְּנֵי נָשָׁא. אִי תֵימָא דְּאִתְעַדֵּי מִנֵּיהּ, אַמַּאי. וְהָא לָא חָטָא. דְּהָא אִיהוּ עִם משֶׁה הֲוָה בְּשַׁעֲתָא דְּחָבוּ יִשְׂרָאֵל. וְאִי תֵימָא (ד\"א ל\"ג דהא) דְּלָא קַבִּיל הַהוּא עִטְרָא בְּטוּרָא דְסִינַי כְּמָה דְּקַבִּילוּ יִשְׂרָאֵל, אַמַּאי.","פָּתַח וְאָמַר, (תהילים י״א:ז׳) כִּי צַדִּיק יְיָ צְדָקוֹת אָהֵב יָשָׁר יֶחזוּ פָנֵימוֹ. הַאי קְרָא אָמְרוּ בֵּיהּ חַבְרַיָיא מַאי דְּקָאֲמְרוּ. אֲבָל כִּי צַדִּיק יְיָ, צַדִּיק הוּא וּשְׁמֵיהּ צַדִּיק, וּבְגִינֵי כָךְ צְדָקוֹת אָהֵב.","יָשָׁר, אִיהוּ יָשָׁר. כְּמָא דְאַתְּ אָמֵר צַדִּיק וְיָשָׁר. וְעַל דָּא יֶחזוּ פָנֵימוֹ כָּל בְּנֵי עָלְמָא וִיתַקְנוּ אָרְחַיְיהוּ לְמֵיהַךְ בְּאֹרַח מֵישָׁר כְּדְקָא יָאוּת. תָּא חֲזֵי, כַּד דָּאִין קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא לָא דָן לֵיהּ אֶלָּא לְפוּם רוּבָּן דִּבְנֵי נָשָׁא.","וְתָּא חֲזֵי, כַּד חָב אָדָם בְּאִילָנָא דְּאֲכַל מִנֵּיהּ, גְּרַם לְהַהוּא אִילָנָא דְּשָׁרֵי בֵּיהּ מוֹתָא לְכָל עָלְמָא. וְגָרִים פְּגִימוּ לְאַפְרָשָׁא אִתְּתָא מִבַּעֲלָהּ. וְקָאִים חוֹבָה דִּפְגִימוּ דָא בְּסִיהֲרָא עַד דְּקָיְימוּ יִשְׂרָאֵל בְּטוּרָא דְסִינַי. כֵּיוָן דְּקָיְימוּ יִשְׂרָאֵל בְּטוּרָא דְסִינַי אִתְעֲבַר הַהוּא פְּגִימוּ דְּסִיהֲרָא וְקָיְימָא לְאַנְהָרָא תָּדִיר.","כֵּיוָן דְּחָבוּ יִשְׂרָאֵל בָּעֶגְלָא, תָּבַת כְּמִלְקַדְּמִין סִיהֲרָא לְאִתְפָּגְמָא. וְשָׁלְטָא חִוְיָא בִישָׁא וְאָחִיד בָּהּ וּמָשִׁיךְ לָהּ לְגַבֵּיהּ. וְכַד יָדַע משֶׁה דְּחָבוּ יִשְׂרָאֵל וְאִתְעֲבַר מִנַיְיהוּ אִנּוּן זַיְינִין קַדִּישִׁין עִלָּאִין, יָדַע וַדַּאי דְּהָא חִוְיָא אָחִיד בֵּיהּ בְּסִיהֲרָא לְאַמְשָׁכָא לָהּ לְגַבֵּיהּ וְאִתְפְּגִימַת. כְּדֵין אַפִּיק לָהּ לְבַר.","וְכֵיוָן דְּקָיְימָא לְאִתְפָּגְמָא אַף עַל גַּב דִּיהוֹשֻׁעַ קָאִים בְּעִטְרָא דְזַיְינִין דִּילֵיהּ, כֵּיוָן דִפְּגִימֵי שַׁרְיָא בָּהּ וְאִתְהַדְּרַת כְּמָה דְּאִתְפְּגִימַת בְּחוֹבָא דְאָדָם, לָא יָכִיל בַּר נָשׁ לְאִתְקָיְימָא. בַּר משֶׁה דְּהֲוָה שַׁלִּיט בָּהּ וּמוֹתֵיהּ הֲוָה בְּסִטְרָא אָחֳרָא עִלָּאָה. וְעַל דָּא לָא הֲוָה רְשׁוּ בָהּ לְקָיְימָא לִיהוֹשֻׁעַ תָּדִיר וְלָא לְאָחֳרָא. וְעַל כָּךְ אֹהֶל מוֹעֵד קָרֵי לֵיהּ. אֹהֶל דְּהָא שַׁרְיָא בֵּיהּ זְמַן קָצִיב לְכָל עָלְמָא.","וְעַל דָּא רָזָא דְמִלָה, אִית יָמִינָא לְעֵילָא וְאִית יָמִינָא לְתַתָּא. אִית שְׂמָאלָא לְעֵילָא וְאִית שְׂמָאלָא לְתַתָּא. אִית יָמִינָא לְעֵילָא בִּקְדֻשָּׁה עִלָּאָה. וְאִית יָמִינָא לְתַתָּא דְּאִיהוּ בְּסִטְרָא אָחֳרָא.","אִית שְׂמָאלָא לְעֵילָא בִּקְדֻשָּׁה עִלָּאָה לְאַתְעָרָא רְחִימוּתָא לְאִתְקַשְּׁרָא סִיהֲרָא בְּאֲתַר קַדִּישָׁא לְעֵילָא לְאִתְנַהֲרָא. וְאִית שְׂמָאלָא לְתַתָּא דְּאַפְרִישׁ רְחִימוּתָא דִלְעֵילָא וְאַפְרִישׁ לָהּ מִלְּאַנְהָרָא בְּשִׁמְשָׁא וּלְאִתְקְרָבָא בַּהֲדֵיהּ. וְדָא הוּא סִטְרָא דְחִוְיָא בִישָׁא.","דְּכַד שְׂמָאלָא דָא דִלְתַתָּא אִתְעָרַת כְּדֵין מָשִׁיךְ לָהּ לְסִיהֲרָא וְאַפְרִישׁ לָהּ מִלְּעֵילָא וְאִתְחַשְׁכַת נְהוֹרָאָה וְאִתְדַּבְּקַת בְּחִוְיָא בִישָׁא. וּכְדֵין שְׁאִיבַת מוֹתָא לְתַתָּא לְכֹלָּא וְאִתְדַּבְּקַת בְּחִוְיָא וְאִתְרַחְקַת מֵאִילָנָא דְּחַיָּיא.","וְעַל דָּא גָּרִים מוֹתָא לְכָל עָלְמָא. וְדָא הוּא דִּכְדֵין אִסְתְּאָבַת מַקְדְּשָׁא עַד זְמַן קָצִיב דְּאַתְקָנַת סִיהֲרָא וְתָבַת לְאַנְהָרָא וְדָא הוּא אֹהֶל מוֹעֵד. וְעַל דָּא יְהוֹשֻׁעַ לָא מִית אֶלָּא בְּעִיטָא שֶׁל נָחָשׁ דָּא דְּקָרִיב וּפְגִים מַשְׁכְּנָא כִּדְקַדְמִיתָא.","וְדָא הוּא רָזָא דִּכְתִיב, (שמות ל״ג:י״א) וִיהוֹשֻׁע בִּן נוּן נַעַר לא יָמִישׁ מִתּוֹךְ הָאֹהֶל. דְּאַף עַל גַּב דְּאִיהוּ נַעַר לְתַתָּא לְקַבְּלָא נְהוֹרָא, לֹא יָמִישׁ מִתּוֹךְ הָאֹהֶל. כְּמָה דְּאִתְפְּגִים דָּא הָכִי נָמֵי אִתְפְּגִים דָּא. אַף עַל גַּב דְּזַיְינָא קַדִּישָׁא הֲוָה לֵיהּ. כֵּיוָן דְּאִתְפְּגִים סִיהֲרָא הָכִי הוּא וַדַּאי לָא אִשְׁתְּזִיב בִּלְחוֹדוֹי מִנֵּיהּ מֵהַהוּא גַּוְונָא מַמָּשׁ.","תָּא חֲזֵי, כְּגַוְונָא דָא כֵּיוָן דְּחָב אָדָם נָטַל קוּדְשָׁא בְּרִיךְ הוּא מִנֵּיהּ אִנּוּן זַיְינֵי אַתְוָון נְהִירִין קַדִּישִׁין דְּאַעְטַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא. וּכְדֵין דָּחֲלוּ וְיָדְעוּ דְּהָא אִתְפַּשְׁטוּ מִנַּיְיהוּ הֲדָא הוּא דִכְתִיב וַיֵּדְעוּ כֵּי עֵרוּמִים הֵם. בְּקַדְמִיתָא הֲווּ מִתְלַבְּשָׁן בְּאִנּוּן כִּתְרֵי יְקָר מְזַיְינִין דְּאִנּוּן חֵירוּ מִכֹּלָּא. כֵּיוָן דְּחָבוּ אִתְפַּשְׁטוּ מִנַּיְיהוּ. וּכְדֵין יָדַע דְּהָא מוֹתָא קָרֵי לוֹן. וְיָדְעוּ דְּאִתְפְּשִׁיטוּ מֵחֵירוּ דְּכֹלָּא. וְגָרְמוּ מוֹתָא לוֹן וּלְכָל עָלְמָא,"],[[0,"אי תימא דלא אעדי מניה אי הכי אמאי מית כשאר בני נשא:","אם תאמר שלא הוסר ממנו, אם כן למה מת ככל אדם, \u0003אי תימא דאתעדי מניה, אמאי והא לא חטא דהא איהו עם משה הוה בשעתא דחבו ישראל\u0004 ואם תאמר, שהוסר ממנו, קשה, למה הוסר ממנו, הרי לא חטא, כי הוא היה עם משה בשעה שחטאו ישראל. \u0003ואי , תימא דלא קביל ההוא עטרא בטורא דסיני כמה דקבילו ישראל, אמאי.\u0004 ואם תאמר, שיהושע לא קיבל אותו העטרה בהר סיני כמו שקבלו ישראל. יש לשאול, למה. מה נשתנה יהושע מכל ישראל."],[1,"פתח ואמר, כי צדיק ה' וגו'. האי קרא אמרו ביה חברייא מאי דקאמרו:","פתח ואמר כתוב כי צדיק וגו' במקרא הזה אמרו בו החברים מה שאמרו. \u0003אבל כי צדיק ה', צדיק הוא ושמיה צדיק, ובגיני כך צדקות אהב,\u0004 אבל כי צדיק הוא ה', פירושו שהוא צדיק, היינו ז\"א, ושמו צדיק, היינו הנוקבא דז\"א, הנקראת שמו והנקראת צדיק, ומשום זה צדקות אהב, כלומר אוהב היחוד דצדיק וצדק. להשפיע בצדקה."],[2,"ישר: איהו ישר, וכד\"א צדיק וישר, ועל דא, יחזו פנימו, כל בני עלמא, ויתקנו ארחייהו למיהך בארח מישר כדקא יאות.","ישר הוא, כמו שאתה אומר, צדיק וישר הוא, וע\"כ כל בני העולם יראו אור פניו ית', ויתקנו דרכיהם ללכת בדרך הישר כראוי. ומתוך שסופם של כל בני העולם הוא להגיע לידי כך, \u0003ת\"ח כד דאין קב\"ה עלמא לא דן ליה אלא לפום רובן דבני נשא,\u0004 בוא וראה, לפי זה, כאשר הקב\"ה דן את העולם אינו דן אותו אלא לפי רובו של בני האדם. פירוש, כי ענין הדין שהקב\"ה דן את העולם היינו להעניש או להשכיר עד להבטיח שכל בני העולם יזכו לאור פניו ית', וללכת בדרך הישר, כנ\"ל, ולפי זה, הכרח הוא לדון את העולם לפי רובו של כל בני אדם, ולהכשירם לסופם, ואפילו יש ביניהם יחידים שראויים להנהגה אחרת אינו משנה את דין הצבור בשבילם."],[3,"ות\"ח כד חב אדם באילנא דאכיל מניה, גרם להאי אילנא דשרי ביה מותא לכל עלמא:","ובוא וראה, כאשר חטא האדם בהעץ שאכל ממנו, גרם לאותו העץ, שהיא הנוקבא שהמות ישרה בתוכו לכל העולם כולו, \u0003וגרים פגימו לאפרשא אתתא מבעלה,\u0004 וגרם פגם להפריד אשה מבעלה, דהיינו להפריד הנוקבא מז\"א, \u0003וקאים חובא דפגימו דא בסיהרא, עד דקיימו ישראל בטורא דסיני,\u0004 ועמד החטא והפגם הזה בהלבנה, שהיא הנוקבא, עד שעמדו ישראל בהר סיני. \u0003כיון דקיימו ישראל בטורא דסיני אתעבר ההוא פגימו דסיהרא, וקיימא לאנהרא תדיר.\u0004 כיון שעמדו ישראל בהר סיני, נעבר אותו הפגם של הלבנה, ועומדת להאיר תמיד. כלומר, שאחר שעבר הפגם של חטא דעצה\"ד חזרה להזדווג עם ז\"א, ובזווג דלא פסיק לעלמין, ונמצא שהיתה אז מאירה תמיד, בלי שום מיעוט, שז\"ס חירות ממלאך המות, שזכו אז."],[4,"כיון דחבו ישראל בעגלא, תבת כמלקדמין סיהרא לאתפגמא:","כיון שישראל חטאו בעגל, חזרה הלבנה להפגם כמקודם מתן תורה. \u0003ושלטא חויא בישא ואחיד בה ומשיך לה לגביה,\u0004 ושלט בה נחש הרע ונאחז בה, ומשך אותה אליו. \u0003וכד ידע משה דחבו ישראל, ואתעבר מנייהו אינון זיינין קדישין עלאין,\u0004 וכאשר ידע משה שחטאו ישראל, ונעבר מהם אותם עדיים הקדושים העליונים, \u0003ידע ודאי דהא חויא אחיד בה בסיהרא לאמשכא לה לגביה ואתפגימת,\u0004 ידע בבירור, אשר הנחש נאחז בה בהלבנה, שהיא הנוקבא, להמשיכה אליו, ונפגמה, \u0003כדין אפיק לה לבר,\u0004 אז הוציא אותה לחוץ. דהיינו כמ\"ש ומשה יקח את האהל ונטה לו מחוץ למחנה וגו'. ואהל היא השכינה כנ\"ל."],[5,"וכיון דקיימא לאתפגמא, אע\"ג דיהושע קאים בעטרא דזיינין דיליה:","וכיון שעומדת להפגם, אע\"פ שיהושע עודנו עומד בעטרת עדיים שלו, מ\"מ \u0003כיון דפגימו שריא בה, ואתהדרת כמה דאתפגימת בחובא דאדם, לא יכול בר נש לאתקיימא בר משה דהוה שליט בה\u0004 וכו', כיון ששורה בה פגם, וחזרה לפגמה כמו שנפגמה בחטאו של אדם הראשון, ע\"כ לא יכול עוד בן אדם להתקיים בנצחיות, זולת משה, שמותו היה בצד אחר עליון, דהיינו מיתת נשיקה מז\"א, כמ\"ש וימת משה על פי הויה. והוא מטעם, שהוא היה משפיע אל הנוקבא, ולא מקבל, כשאר בני העולם, וע\"כ אין פגם הנוקבא נוגע לו. \u0003ועל דא, לא הוה רשו בה לקיימא ליהושע תדיר, ולא לאחרא,\u0004 וע\"כ לא היה להנוקבא רשות לקיים את יהושע תמיד לנצחיות. וכן לא לאחר ממנו. \u0003ועל כך אהל מועד קרי ליה, אהל, דהא שריא ביה זמן קציב לכל עלמא.\u0004 וע\"כ קראו לו אהל מועד, שפירושו, אהל, ששורה בו זמן קצוב לכל העולם, דהיינו שכל אחד מוכרח למות."],[6,"ועל דא רזא דמלה, אית ימינא לעילא ואית ימינא לתתא, אית שמאלא לעילא ואית שמאלא לתתא:","וע\"כ סוד הדבר, שיש ימין למעלה ויש ימין למטה, יש שמאל למעלה ויש שמאל למטה. ומפרש \u0003אית ימינא לעילא בקדושה עלאה, ואית ימינא לתתא דאיהו בסטרא אחרא,\u0004 יש ימין למעלה היינו בקדושה העליונה, דהיינו זו\"ן. ויש ימין למטה, שהיא בסטרא אחרא, דהיינו בקליפות."],[7,"אית שמאלא לעילא בקדושה עלאה, לאתערא רחימותא, לאתקשרא סיהרא באתר קדישא לעילא לאתנהרא","וכו', יש שמאל למעלה בקדושה העליונה, לעורר אהבה שתתקשר הלבנה במקום קדוש למעלה, להאיר משם. דהיינו כנ\"ל (דף קל\"ו ד\"ה פנימיות) שעי\"ז שז\"א משפיע להנוקבא הארת קו שמאל, היא מתפייסת עמו להזדווג ולקבל ממנו אור. ע\"ש. \u0003ואית שמאלא לתתא דאפריש רחימותא דלעילא ואפריש לה מלאנהרא בשמשא ולאתקרבא בהדיה, ודא הוא סטרא דחויא בישא,\u0004 ויש שמאל למטה בס\"א, המפריד האהבה שלמעלה, ומפריד את הלבנה, שהיא הנוקבא, מלהאיר בהשמש, שהוא ז\"א, ומלקרב אליו, לזווג. וזה הוא בחינת נחש הרע."],[8,"דכד שמאלא דא דלתתא אתערת כדין משיך לה לסיהרא, ואפריש לה מלעילא:","כי כאשר שמאל זה שלמטה, שהיא הנחש, מתעורר, הוא מושך אז אליו את הלבנה, שהיא הנוקבא דז\"א, ומפריד אותה מלמעלה, מן ז\"א, \u0003ואתחשבת נהוראה, ואתדבקת בחויא בישא, וכדין שאיבת מותא לתתא לכלא,\u0004 ונחשכה הארתה, ומתדבקת בנחש הרע, ואז שואבת מות למטה לכל העולם. כי \u0003ואתדבקת בחויא ואתרחקת מאילנא דחיי.\u0004 שנתדבקה בהנחש, ונתרחקה מעץ החיים שהוא ז\"א, דהיינו שאין זווגה עם עץ החיים בתמידות אלא בזווגא דפסיק. וע\"כ גם החיים שמקבלת ממנו, ג\"כ פסיק."],[8,"","ביאור הדברים. כי נתבאר לעיל (בראשית א' דף פ\"ה ד\"ה ביאור)כי רק מחזה ולמעלה של המלכות יש פני אדם וראויה לזווג עם ז\"א, אבל מחזה שלה ולמטה היא חסרה פני אדם, ואין שם מקום זווג, אלא ע\"י עליה והתכללות בבחינת מחזה שלה ולמעלה ע\"ש. וכן נתבאר לעיל (בהקדמת הזהר דף קצ\"ט ד\"ה ודא) שענין חטא דעצה\"ד היה \u0003חבר לתתא ואתפרש לעילא\u0004 שהנחש פיתה להמשיך הזווג לבחינת מחזה ולמטה, שמשם מגיע השפע להנחש ולכל הקליפות, וע\"כ תכף נפרש גם זווג העליון שלמעלה מחזה, ונחשכה הנוקבא. ע\"ש. וכן לעיל (בהקדמת הזהר דף קכ\"ד אות קכ\"ג ד\"ה אמאי) \u0003זכי הא טוב\u0004 דהיינו אם ממשיך הזווג שמחזה ולמעלה דזו\"ן, ונזהר מלהמשיך הזווג שמחזה ולמטה, אז נבחנת הנוקבא לעץ הדעת טוב ולא רע, כי אז נקודה דמדה\"ד מצמצום א' היא בגניזא, ונקודה דמדת הרחמים באתגליא, שמנקודה זו היא מוכשרת לקבל מוחין העליונים. \u0003ואם לא זכי הא רע,\u0004 דהיינו אם ממשיך מזווג שמחזה ולמטה דזו\"ן, מתגלה תכף הנקודה דמדת הדין מצמצום א'. שמבחינתה אין המלכות ראויה לקבל שום אור ישר מלמעלה, וע\"כ נפסק תכף זווג שלה עם ז\"א, והיא נחשכה מכל אור, ע\"ש. באופן שענין גילוי של נקודה דמדת הדין דומה לאשה שראתה דם טמא, שנטמאת ואסורה לבעלה."],[8,"","וזה אמרו \u0003אית ימינא לעילא בקדושה עלאה ואית ימינא לתתא\u0004 וכו' \u0003אית שמאלא לעילא\u0004 וכו' ואית שמאלא לתתא. כי הימין ושמאל הנמשכים מבחינת הזווג שמחזה ולמעלה הם בקדושה עליונה, כמבואר. אבל הימין ושמאל הנמשכים מבחינת הזווג שמחזה ולמטה, הם בסטרא אחרא. וז\"ש \u0003אית שמאלא לתתא דאפריש רחימותא דלעילא ואפריש לה מלאנהרא בשמשא,\u0004 כי בעת שממשיך השמאל מבחינת הזווג שמחזה ולמטה, שהוא נמשך אל הקליפות, נפסק תכף גם זווג העליון שלמעלה מחזה, והנוקבא נפרדת מז\"א ונחשכת. כנ\"ל, וז\"ש \u0003דכד שמאלא דא דלתתא אתערת, כדין משיך לה לסיהרא, ואפריש לה מלעילא,\u0004 דהיינו מזווג העליון שלמעלה מחזה, \u0003ואתחשכת נהוריה,\u0004 דהיינו כמבואר. וז\"ש \u0003וכדין שאיבת מותא לתתא לכלא, ואתדבקת בחויא\u0004 וכו', כי אז מתגלה בהנוקבא, הנקודה דמדת הדין מצמצום א', שמצדה אין הנוקבא ראויה לקבל שום אור מעץ החיים, ונמשך המות להעולם. וז\"ש \u0003ודא הוא סטרא דחויא בישא,\u0004 דהיינו כמ\"ש לעיל, (בהקדמת הזהר דף קס\"ב אות ר\"י) שהנחש \u0003חבר לתתא ואתפרש לעילא,\u0004 ע\"ש."],[9,"ועל דא גרים מותא לכל עלמא, ודא הוא, דכדין אסתאבת מקדשא עד זמן קציב:","ועל כן גרם מות לכל העולם וזהו הטעם, כי אז נטמא המקדש, שהיא הנוקבא, עד זמן קצוב, \u0003דאתקנת סיהרא, ותבת לאנהרא\u0004 עד שנתקנה הלבנה, שהיא הנוקבא, וחוזרת להאיר. פירוש. כי על ידי המשכת השמאל מהזווג שמחזה ולמטה, נתגלה הנקודה דצמצום א' בהנוקבא, שעם גילויה מסתלקים ממנה כל האורות, והיא דומה לאשה שנטמאה ונפרדה מבעלה עד זמן קצוב, דהיינו אחר שתטהר, וכן כאן היא נפרדת מז\"א עד שהתחתונים יעשו תשובה, ויתקנו בזה את הנוקבא. \u0003ודא הוא אהל מועד,\u0004 וזה היא שנקראת עתה, אהל מועד. כי מועד פירושו זמן קצוב, כי זווגה נפסק ע\"י קרבת הנחש. כנ\"ל. \u0003ועל דא יהושע לא מית אלא בעיטא של נחש דא, דקריב ופגים משכנא כדקדמיתא,\u0004 וע\"כ יהושע לא מת אלא בהעצה של נחש הזה שקרב ופגם את המשכן, שהיא הנוקבא, כבתחילה, כמקודם מתן תורה. פירוש. כי על ידי חטא העגל, חזרה השליטה להנחש לפתות התחתונים, שימשיכו לו מבחינת הזווג שמחזה ולמטה, שאז נקרב הנחש לינק מאורות הנוקבא, שמסבת קרבתו לינק, נפסק תכף זווג העליון, והיא נפרדת מז\"א. וכן היא נפגמת ע\"י גילוי הנקודה דצמצום א' כנ\"ל, ומיושב קושיא הנ\"ל, שהקשה כיון שיהושע לא חטא למה לא נשאר בחירות ממלאך המות. כי הטעם הוא, משום שהנוקבא נפרדה מז\"א בסבת חטא העגל, ולא נתקנה אח\"כ אלא בזווג דפסיק, מחמת שליטת הנחש לקרב ולהפסיק הזווג, וע\"כ גם יהושע לא יכול לקבל עוד מהנוקבא חיים נצחיים כמקודם העגל, וע\"כ מת כמו האחרים."],[10,"ודא הוא רזא דכתיב ויהושע בן נון נער וגו', דאע\"ג דאיהו נער לתתא לקבלא נהורא:","וזה הוא סוד שכתוב, ויהושע בן נון נער וגו', שאע\"פ שהוא נער למטה, לקבל אור מהנוקבא, דהיינו, שגדלה מעלתו להיות בבחינת מלאך מטטרון, שנקרא נער למטה מאצילות, מ\"מ \u0003לא ימיש מתוך האהל, כמה דאתפגים דא ה\"נ אתפגים דא,\u0004 מ\"מ לא ימיש מתוך האהל, כלומר שאינו טוב יותר מבחינת האהל עצמו, שהיא הנוקבא, וכמו שנפגם האהל, כן נפגם יהושע. \u0003אע\"ג דזיינא קדישא הוה ליה, כיון דאתפגים סיהרא הכי הוא ודאי לא אשתזיב בלחודוי מניה, מההוא גוונא ממש.\u0004 אע\"פ שהיה לו עדי הקדוש, מ\"מ כיון שנפגמה הלבנה ודאי כן הוא, שלא ניצל יהושע בלבדו מהפגם, מאותו הפגם ממש. כלומר, אותו הפגם עצמו שהשיגה הלבנה מחמת חטא ישראל, השיגו ג\"ב יהושע."],[11,"ת\"ח כגוונא דא, כיון דחב אדם, נטל קב\"ה מניה אינון זייני אתוון נהירין קדישין, דאעטר ליה קב\"ה:","בוא וראה, כעין זה, כיון שחטא אדם בעצח\"ד, לקח ממנו הקב\"ה אלו עדיים, שהם אותיות מאירות קדושות, שהעטיר אותו הקב\"ה. דהיינו האותיות של השם הקדוש, (כנ\"ל דף קע\"ג אות רצ\"א) \u0003וכדין דחלו וידעו דהא אתפשטו מנייהו, הה\"ד וידעו וגו',\u0004 אז יראו וידעו כי נתפשטו מעדים. כמ\"ש וידעו כי ערומים הם. \u0003בקדמיתא הוו מתלבשן באינון כתרי יקר מזיינין דאינון חירו מכלא,\u0004 בתחילה היו מתלבשים בכתרי יקר מזוינים הללו שהם חרות מכל. כיון שחטאו, נתפשטו מהם אלו כתרי יקר, ואז ידעו כי המות קורא להם, וידעו שנתפשטו מאותה החירות מכל, וגרמו המות להם ולכל העולם."]],[[0,"","אִם תֹּאמַר שֶׁלֹּא בָטַל מִמֶּנּוּ, אִם כָּךְ, לָמָּה מֵת כִּשְׁאָר בְּנֵי אָדָם? אִם תֹּאמַר שֶׁהוּסַר מִמֶּנּוּ - לָמָּה? וַהֲרֵי לֹא חָטָא, שֶׁהֲרֵי הוּא הָיָה עִם מֹשֶׁה בְּשָׁעָה שֶׁחָטְאוּ יִשְׂרָאֵל? וְאִם תֹּאמַר שֶׁלֹּא קִבֵּל אוֹתָהּ עֲטָרָה בְּהַר סִינַי כְּמוֹ שֶׁקִּבְּלוּ יִשְׂרָאֵל - לָמָּה?"],[1,"","פָּתַח וְאָמַר, (תהלים י) כִּי צַדִּיק ה' צְדָקוֹת אָהֵב יָשָׁר יֶחֱזוּ פָנֵימוֹ. בְּפָסוּק זֶה אָמְרוּ הַחֲבֵרִים מַה שֶּׁאָמְרוּ. אֲבָל כִּי צַדִּיק ה', צַדִּיק הוּא וּשְׁמוֹ צַדִּיק, וְלָכֵן צְדָקוֹת אָהֵב."],[2,"","יָשָׁר - הוּא יָשָׁר, כְּמוֹ שֶׁנֶּאֱמַר צַדִּיק וְיָשָׁר. וְעַל זֶה יֶחֱזוּ פָנֵימוֹ, כָּל בְּנֵי הָעוֹלָם, וִיתַקְנוּ דַרְכֵיהֶם לָלֶכֶת בְּדֶרֶךְ יְשָׁרָה כָּרָאוּי. בֹּא רְאֵה, כְּשֶׁדָּן הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, אֵינוֹ דָן אוֹתוֹ אֶלָּא לְפִי רֹב בְּנֵי הָאָדָם."],[3,"","וּבֹא וּרְאֵה, כְּשֶׁחָטָא אָדָם בָּעֵץ שֶׁאָכַל מִמֶּנּוּ, גָּרַם לְאוֹתוֹ עֵץ שֶׁשּׁוֹרֶה בּוֹ הַמָּוֶת לְכָל הָעוֹלָם, וְגָרַם פְּגָם לְהַפְרִיד אִשָּׁה מִבַּעְלָהּ, וְעָמַד חֵטְא הַפְּגָם הַזֶּה בַּלְּבָנָה עַד שֶׁעָמְדוּ יִשְׂרָאֵל בְּהַר סִינַי. כֵּיוָן שֶׁעָמְדוּ יִשְׂרָאֵל בְּהַר סִינַי, בָּטַל מֵהֶם אוֹתוֹ פְּגַם הַלְּבָנָה, וְעָמְדָה לְהָאִיר תָּמִיד."],[4,"","כֵּיוָן שֶׁחָטְאוּ יִשְׂרָאֵל בָּעֵגֶל, שָׁבָה הַלְּבָנָה לְהִפָּגֵם כְּמוֹ מִקֹּדֶם, וְשָׁלַט הַנָּחָשׁ הָרָע וְאָחַז בָּהּ וּמָשַׁךְ אוֹתָהּ אֵלָיו. וּכְשֶׁיָּדַע מֹשֶׁה שֶׁחָטְאוּ יִשְׂרָאֵל וְהוּסַר מֵהֶם אוֹתָם כְּלֵי זַיִן קְדוֹשִׁים עֶלְיוֹנִים, יָדַע וַדַּאי שֶׁהֲרֵי הַנָּחָשׁ אָחַז בַּלְּבָנָה לְהַמְשִׁיכָהּ אֵלָיו וְנִפְגְּמָה, וְאָז הוֹצִיא אוֹתָהּ הַחוּצָה."],[5,"","וְכֵיוָן שֶׁעָמְדָה לְהִפָּגֵם, אַף עַל גַּב שֶׁיְּהוֹשֻׁעַ עָמַד בָּעֲטָרָה שֶׁל כְּלִי הַזַּיִן שֶׁלּוֹ, כֵּיוָן שֶׁהַפְּגָם שָׁרָה בָהּ וְחָזְרָה כְּמוֹ שֶׁנִּפְגְּמָה בַּחֵטְא שֶׁל אָדָם, לֹא יָכוֹל אָדָם לְהִתְקַיֵּם, פְּרָט לְמֹשֶׁה שֶׁהָיָה שׁוֹלֵט בָּהּ, וּמוֹתוֹ הָיָה בְּצַד אַחֵר עֶלְיוֹן. וְעַל זֶה לֹא הָיָה רְשׁוּת בָּהּ לְקַיֵּם אֶת יְהוֹשֻׁעַ תָּמִיד וְלֹא אַחֵר. וְעַל כָּךְ אֹהֶל מוֹעֵד קָרְאוּ לוֹ. אֹהֶל, שֶׁהֲרֵי שׁוֹרֶה בּוֹ זְמַן קָצוּב לְכָל הָעוֹלָם."],[6,"","וְעַל זֶה סוֹד הַדָּבָר - יֵשׁ יָמִין לְמַעְלָה וְיֵשׁ יָמִין לְמַטָּה. יֵשׁ שְׂמֹאל לְמַעְלָה וְיֵשׁ שְׂמֹאל לְמַטָּה. יֵשׁ יָמִין לְמַעְלָה בִּקְדֻשָּׁה עֶלְיוֹנָה, וְיֵשׁ יָמִין לְמַטָּה שֶׁהוּא בַּצַּד הָאַחֵר."],[7,"","יֵשׁ שְׂמֹאל לְמַעְלָה שֶׁהוּא בִּקְדֻשָּׁה עֶלְיוֹנָה לְעוֹרֵר אַהֲבָה לְקַשֵּׁר אֶת הַלְּבָנָה בְּמָקוֹם קָדוֹשׁ לְמַעְלָה לְהָאִיר, וְיֵשׁ שְׂמֹאל לְמַטָּה שֶׁמַּפְרִיד אַהֲבָה שֶׁלְּמַעְלָה, וּמַפְרִיד אוֹתָהּ מִלְּהָאִיר בַּשֶּׁמֶשׁ וּלְהִתְקָרֵב אֵלָיו, וְזֶהוּ צַד שֶׁל הַנָּחָשׁ הָרָע."],[8,"","שֶׁכְּשֶׁשְּׂמֹאל הַזֶּה שֶׁלְּמַטָּה מִתְעוֹרֵר, אָז מוֹשֵׁךְ אֶת הַלְּבָנָה וּמַפְרִיד אוֹתָהּ מִלְמַעְלָה וְנֶחְשָׁךְ אוֹרָהּ וְנִדְבֶּקֶת בַּנָּחָשׁ הָרָע, וְאָז שׁוֹאֶבֶת מָוֶת לְמַטָּה לַכֹּל וְנִדְבֶּקֶת בַּנָּחָשׁ וּמִתְרַחֶקֶת מֵעֵץ הַחַיִּים."],[9,"","וְעַל זֶה גָּרַם מָוֶת לְכָל הָעוֹלָם. וְזֶהוּ שֶׁאָז נִטְמָא הַמִּקְדָּשׁ עַד זְמַן קָצוּב שֶׁנִּתְקְנָה הַלְּבָנָה וְשָׁבָה לְהָאִיר, וְזֶהוּ אֹהֶל מוֹעֵד. וְעַל זֶה יְהוֹשֻׁעַ לֹא מֵת אֶלָּא בְּעֶטְיוֹ שֶׁל הַנָּחָשׁ הַזֶּה שֶׁקָּרַב וּפָגַם אֶת הַמִּקְדָּשׁ כְּמוֹ קֹדֶם."],[10,"","וְזֶהוּ סוֹד הַכָּתוּב (שמות לג) וִיהוֹשֻׁעַ בִּן נוּן נַעַר לֹא יָמִישׁ מִתּוֹךְ הָאֹהֶל. שֶׁאַף עַל גַּב שֶׁהוּא נַעַר לְמַטָּה לְקַבֵּל אוֹר, לֹא יָמִישׁ מִתּוֹךְ הָאֹהֶל. כְּמוֹ שֶׁנִּפְגָּם זֶה - כָּךְ גַּם נִפְגָּם זֶה, אַף עַל גַּב שֶׁכְּלִי זַיִן קָדוֹשׁ הָיָה לוֹ. כֵּיוָן שֶׁנִּפְגְּמָה הַלְּבָנָה, כָּךְ הוּא וַדַּאי לֹא נִצָּל לְבַדּוֹ מִמֶּנּוּ מֵאוֹתוֹ גָוֶן מַמָּשׁ."],[11,"","בֹּא רְאֵה, כְּמוֹ זֶה, כֵּיוָן שֶׁחָטָא אָדָם, נָטַל הַקָּדוֹשׁ בָּרוּךְ הוּא מִמֶּנּוּ אוֹתָם כְּלֵי זַיִן, אוֹתִיּוֹת מְאִירוֹת קְדוֹשׁוֹת שֶׁעִטֵּר אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא. וְאָז פָּחֲדוּ, וְיָדְעוּ שֶׁהֲרֵי הִתְפַּשְּׁטוּ מֵהֶם. זֶהוּ שֶׁכָּתוּב וַיֵּדְעוּ כִּי עֵירֻמִּם הֵם. בַּהַתְחָלָה הָיוּ מִתְלַבְּשִׁים בְּאוֹתָם כִּתְרֵי כָבוֹד מְזֻיָּנִים שֶׁהֵם חֵרוּת מֵהַכֹּל. כֵּיוָן שֶׁחָטְאוּ, הִתְפַּשְּׁטוּ מֵהֶם, וְאָז יָדְעוּ שֶׁהֲרֵי הַמָּוֶת קוֹרֵא לָהֶם, וְיָדְעוּ שֶׁהֻפְשְׁטוּ מֵחֵרוּת הַכֹּל, וְגָרְמוּ מָוֶת לָהֶם וּלְכָל הָעוֹלָם."]]],[["וַיִתְפְּרוּ עֲלֵה תְאֵנָה הָא (לו ב) אוֹקִימְנָא דְּאוֹלִיפוּ כָּל זַיְינִי חָרְשִׁין וְקוֹסְמִין וַאֲחִידוּ בְּהַאי דִלְתַתָּא כְּמָה דְּאִתְּמָר. וְהַהִיא שַׁעֲתָא אִתְגְּרַע זְקִיפוּ וְקוֹמָה דְאָדָם מֵאָה אַמִּין. וּכְדֵין אִתְעֲבִיד פִּרוּדָא וְקָאִים אָדָם בְּדִינָא וְאִתְלַטְיָא אַרְעָא וְהָא אוֹקִימְנָא:","וַיְגָרֶשׁ אֶת הָאָדָם. אָמַר רַבִּי אֶלְעָזָר לָא יְדַעְנָא מָאן עָבִיד תֵּרוּכִין לְמָאן. אִי קוּדְשָׁא בְּרִיךְ הוּא עָבַד תֵּרוּכִין לְאָדָם אִי לָא. אֲבָל מִלָּה אִתְהַפִּיךְ וַיְגָרֶשׁ אֶת, אֶ\"ת דַּיְיקָא. וּמָאן גֵּרַשׁ אֶת, הָאָדָם. הָאָדָם וַדַּאי גֵּרַשׁ אֶת.","וּבְגִין דָּא כְּתִיב וַיְשַׁלְּחֵהוּ יְיָ אֱלהִים מִגַּן עֵדֶן. אַמַּאי וַיְשַׁלְּחֵהוּ, בְּגִין דְּגֵרַשׁ אָדָם אֶת כִּדְקָאֲמָרָן. וַיַּשְׁכֵּן, אִיהוּ אַשְׁרֵי לוֹן בְּאֲתַר דָּא דְּאִיהוּ גָּרִים וְסָתִים אוֹרְחִין וּשְׁבִילִין וְאַשְׁרֵי דִּינִין עַל עָלְמָא וְאַמְשִׁיךְ לְוָוטִין מֵהַהוּא יוֹמָא וּלְעֵילָא.","וְאֶת לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת, כָּל אִנּוּן דְּשָׁרְיָין בְּקוֹזְפֵי דִינִין עַל עָלְמָא, דְּמִתְהַפְּכִין לִגְוָונִין סַגִּיאִין בְּגִין לְאִתְפְּרָעָא מֵעָלְמָא. לְזִמְנִין גּוּבְרִין לְזִמְנִין נָשִׁין לְזִמְנִין אֶשָׁא מְלַהֲטָא וּלְזִמְנִין רוּחִין דְּלֵית מָאן דְּקָאִים בְּהוּ. וְכָל דָּא לִשְׁמוֹר אֶת דֶּרֶךְ עֵץ הַחַיִּים דְּלָא יוֹסִיפוּן לְאַבְאָשָׁא כְּקַדְמִיתָא.","לַהַט הַחֶרֶב, אִנּוּן דִּמְלַהֲטָאן אֶשָׁא וְקוֹסְטִירִי עַל רָאשֵׁיהוֹן דְּרַשִּׁיעַיָא וְחַיָּיבַיָא. וּמִתְהַפְּכִין גְּוָונִין לְכַמָּה זַיְינִין לְפוּם אָרְחַיְיהוּ דִּבְנִי נָשָׁא. וְעַל דָּא לַהַט כְּמָא דְאַתְּ אָמֵר (מלאכי ג׳:י״ט) וְלִהֵט אוֹתָם הַיּוֹם הַבָּא וְגו' וְהָא אִתְּמָר. הַחֶרֶב דָּא חֶרֶב לַה' כְּמָא דְאַתְּ אָמֵר, (ישעיה לה) חֶרֶב לַה' מְלֵאָה דָּם וְגו'.","אָמַר רַבִּי יְהוּדָה לַהַט הַחֶרֶב (אפילו) כָּל אִנּוּן קַסְטְרִין דִּלְתַתָּא דְּמִתְהַפְּכִין מִדְּיוֹקְנָא לִדְיוֹקָנָא כֻּלְהוֹן מְמַנָּן עַל עָלְמָא לְאַבְאָשָׁא וּלְאַסְטָאָה לוֹן לְחַיָּיבֵי עָלְמָא דְּעָבְרִין עַל פִּקּוּדֵי דְּמָארֵיהוֹן.","תָּא חֲזֵי, כֵּיוָן דְּחָב אָדָם אַמְשִׁיךְ עֲלֵיהּ כַּמָּה זַיְינִין בִּישִׁין וְכַמָּה גַּרְדִינִי נִמּוּסִין וְדָחִיל מִכֻּלְהוּ וְלָא יָכִיל לְקָיְימָא עֲלַיְיהוּ. שְׁלמֹה יָדַע חָכְמְתָא עִלָּאָה וְשַׁוֵּי לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא עִטְרָא דְמַלְכוּתָא וְהֲווּ דָּחֲלוּ מִנֵּיהּ כָּל עָלְמָא. כֵּיוָן דְּחָב אַמְשִׁיךְ עֲלֵיהּ כַּמָּה זַיְינִין בִּישִׁין וְכַמָּה גַרְדִינֵי נִמּוּסִין וְדָחִיל מִכֻּלְהוּ וּכְדֵין יָכִילוּ לְאַבְאָשָׁא לֵיהּ וּמַה דְּהֲוָה בִּידֵיהּ נְטָלוּ מִנֵּיהּ.","וְעַל דָּא בְּמָּה דְאָזִיל בַּר נָשׁ וּבְהַהוּא אָרְחָא דְּאִתְדָּבַּק בֵּיהּ, הָכִי מָשִׁיךְ עֲלֵיהּ חֵילָא מְמַנָּא דְּאָזִיל לְקֳבְלֵיהּ. כָּךְ אָדָם הֲוָה מָשִׁיךְ עֲלֵיהּ חֵילָא אָחֳרָא מְסָאַב. דְּסָאִיב לֵיהּ וּלְכָל בְּנֵי עָלְמָא.","תָּא חֲזֵי, כַּד חָב אָדָם מָשִׁיךְ עֲלֵיהּ חֵילָא מְסָאֲבָא וְסָאִיב לֵיהּ וּלְכָל בְּנֵי עָלְמָא. וְהַאי הוּא חִוְיָא בִישָׁא דְּאִיהוּ מְסָאָב וְסָאִיב עָלְמָא. דְּתָנִינָן כַּד אַפִּיק נִשְׁמָתִין מִבְּנִי נְשָׁא, אִשְׁתָּאַר מִנֵּיהּ גּוּפָא מְסָאָב וְסָאִיב בֵּיתָא. וְסָאִיב לְכָל אִנּוּן דִּמְקָרְבִין בֵּיהּ. הֲדָא הוּא דִכְתִיב, (במדבר י״ט:י״א) הַנּוֹגֵעַ בְּמֵת וְגו'.","וְעַל דָּא כֵּיוָן דְּאִיהוּ נָטִיל נִשְׁמְתָא וְסָאִיב גּוּפָא כְּדֵין אִתְיְיהִיב רְשׁוּ לְכָל אִנּוּן סִטְרֵי מְסָאֲבָן לְשָׁרְיָא עֲלוֹי. דְּהָא הַהוּא גּוּפָא אִסְתָּאַב מִסִּטְרָא דְּהַהוּא חִוְיָא בִישָׁא דְּשַׁרְיָא עֲלוֹי. וְעַל דָּא בְּכָל אֲתַר דְּהַהוּא חִוְיָא בִישָׁא שָׁארֵי מְסָאַב לֵיהּ וְאִסְתָּאַב.","וְתָּא חֲזֵי, כָּל בְּנֵי עָלְמָא בְּשַׁעֲתָא דְּנַיְימֵי עַל עַרְסַיְיהוּ בְּלֵילְיָא, וְלֵילְיָא פָּרִישׂ גַּדְפָהָא עַל כָּל בְּנֵי עָלְמָא טָעֲמֵי טַעֲמָא דְמוֹתָא. וּמִגּוֹ דְּטָעֲמֵי טַעֲמָא דְמוֹתָא הַאי רוּחָא מְסָאֲבָא שַׁטְיָא עַל עָלְמָא וְסָאִיב (על) עָלְמָא (ד\"א ל\"ג בגו קפטרא דיליה) וְשַׁרְיָא עַל יְדוֹי דְּבַר נָשׁ וְאִסְתָּאַב.","וְכַד אִתְעַר וְאִתְהַדַּר לֵיהּ נִשְׁמָתֵיהּ, בְּכָל מַה דְּיִקְרַב בִּידוֹי כֻּלְהוּ מְסָאֲבֵי, בְּגִין דְּשָׁרְיָא עֲלַיְיהוּ רוּחַ מְסָאֳבָא. וְעַל דָּא לָא יִסַּב בַּר נָשׁ מָנוֹי לְאַלְבָּשָׁא מִמָּאן דְּלָא נָטִיל יְדוֹי. דְּהָא אַמְשִׁיךְ עֲלֵיהּ הַהוּא רוּחַ מְסָאֲבָא וְאִסְתָּאַב. וְאִית לֵיהּ רְשׁוּ לְהַאי רוּחַ מְסָאֲבָא לְשָׁרְיָא בְּכָל אֲתַר דְּאִשְׁתְּכַח רְשִׁימוּ מִסִּטְרֵיהּ.","וְעַל דָּא לָא יִטּוֹל יְדוֹי בַּר נָשׁ מִמָּאן דְּלָא נָטִיל יְדוֹי בְּגִין דְּאַמְשִׁיךְ עֲלֵיהּ הַהוּא רוּחַ מְסָאֳבָא וְקַבִּיל לֵיהּ הַאי דְּנָטַל מַיָא מִנֵּיהּ וְאִית לֵיהּ רְשׁוּ לְשַׁרְיָא עֲלוֹי דְּבַר נָשׁ. בְּגִין כָּךְ בָּעֵי בַּר נָשׁ לְאִסְתַּמְּרָא בְּכָל סִטְרוֹי מִסִּטְרָא דְהַאי חִוְיָא בִישָׁא דְּלָא יִשְׁלוֹט עֲלוֹי. וְזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְעָלְמָא דְאָתֵי לְאַעֲבָרָא לֵיהּ מֵעָלְמָא. הֲדָא הוּא דִכְתִיב, (זכריה י״ג:ב׳) וְאֶת רוּחַ הַטּוּמְאָה אַעֲבִיר מִן הָאָרֶץ (וכדין) (ד\"א וכתיב) (ישעיה כב) בִּלַע הַמָּוֶת לָנֶצַח וְגו':"],[[0,"ויתפרו עלי תאנה. הא אוקימנא, דאוליפו כל זייני חרשין וקוסמין, ואחידו בהאי דלתתא כמה דאתמר:","הנה בארנו, שלמדו כל מיני כשפים וקסמים, ונאחזו בזה שלמטה, דהיינו הס\"א, כמו שנתבצר. והוא לעיל (בראשית א' דף של\"ו אות תנ\"ב) שביאר שם הזהר, וז\"ל. \u0003ויתפרו עלה תאנה, אתדבקו לאתחפאה באינון צולמין דההוא אילנא דאכלו מניה, דאקרון טרפי דאילנא.\u0004 ע\"ש. ושם בהסולם ביארתי בקיצור, אבל הדברים צריכים ביאור. וצריך שתדע, אשר צללים פירושו, העלמות על אור פניו ית'. כדמיון צל הנעשה מכח המכסה על אור השמש. כי אור העליון נמשל לאור השמש, שהוא השורש לכל האורות שבעולם הזה, כן אור העליון הוא שורש לכל האורות שבהמציאות, וזה סוד הכתוב, עד שיפוח היום ונסו הצללים סוב דמה לך דודי וגו'."],[0,"","אמנם יש צל דקדושה, דהיינו הבא מחמת השגת רוממות השי\"ת. אכן צל הזה, יש לו פעולה הפוכה, כי הוא הממשיך את אור העליון, על דרך שאמרו חז\"ל במשה רבינו, (ברכות ז.) בשכר ויסתר משה פניו, זכה ודבר ה' אל משה פא\"פ. הרי שהצל הזה שהמשיך משה על עצמו, דהיינו שהסתיר פניו, כי ירא מהביט אל האלקים, זכה על ידי העלמה הזו, לפב\"פ ולתמונת ה' יביט. הרי שצל הזה נעשה הכנה ולבוש על כל אור הגדול שהשיג משה. אבל זה דוקא בצל דקדושה, דהיינו הבא מחמת מצוה כמו במשה, אבל בצל הבא מחמת עבירה אינו כן, אלא שהוא שורש החשך המחשיך פניהם של בני אדם, והוא הנקרא \u0003צל מות.\u0004"],[0,"","ולפני החטא דעצה\"ד, לא היה בחינת צל הזה דס\"א בהעולם, אלא בחינת צל דקדושה בלבד. וזה היה הטעות של אדם הראשון. כי אחר החטא של עצה\"ד, שבסבתו פרחו ממנו כל האורות העליונים שהשיג בסוד זיהרא עלאה, וידעו כי עירומים הם מכל האורות, ונפל עליהם הצל דס\"א, דהיינו ההעלמה והצל הבא מחמת עבירה, אז ויתפרו עלי תאנה ויעשו להם חגורות, \u0003עלים\u0004 פירושו צל, כי עלי האילן עושים צל. \u0003תאנה\u0004 היינו החטא דעצה\"ד, כמו שאמרו חז\"ל שעצה\"ד תאנה היתה. והם טעו וחשבו שצל הזה דעלי תאנה, דהיינו הצל שנפל עליהם מחמת העבירה דעצה\"ד, דומה כמו הצל דקדושה, שסגולתו להמשיך האורות כולם כנ\"ל אצל משה רבינו, וע\"כ עשו להם מהצל הזה חגורות, דהיינו בסו\"ה כאשר ידבק האזור אל מתני איש כן הדבקתי אלי את כל בית ישראל וגו' (ירמיה י\"ג) שפירושו דבקות מתוך העלמה. אמנם שם מדבר הכתוב באזור הנעשה מסבת הצל דקדושה, משא\"כ אזור הנעשה מעלי תאנה, שהוא צל מחמת עבירה, הוא סו\"ה (ירמיה י\"ג) כאזור הזה אשר לא יצלח לכל עש\"ה. ועל פי הטעות הזה, נתחבא אדה\"ר בתוך עצי הגן, והתנצל לפני השי\"ת, וטען, את קולך, שמעת ואירא וגו', דהיינו שהתפאר לפניו ית' ( במעשהו, ודימה את עצמו למשה שהסתיר פניו, מהביט אל האלקים וחשב שעל ידי הצל הזה יחזור ויזכה תכף לכל האורות שפרחו ממנו. אבל הקב\"ה השיב לו, מי הגיד לך כי עירום אתה, בסבת מה הפסדת האורות שלך ונפלת בצל, המן העץ אשר צויתיך וגו', הכי הגיע לך מחמת מצוה, הלא צל זה הגיע לך מחמת עבירה והוא צל מות, צל דס\"א. וע\"כ, לא לבד שלא ברכו מחמת זה, אלא עוד קללו. וז\"ש שם בזהר, \u0003אתדבקו לאתחפאה באינון צולמין דההוא אילנא דאכלו מניה,\u0004 שנתדבקו להתכסות בהצללים של האילן שאכלו ממנו. שהוא צל הבא מחמת עבירה. ונתדבקו בזה בצל מות."],[0,"","וזה אמרו כאן, \u0003דאוליפו כל זייני חרשין וקוסמין,\u0004 כי ענין הכשפים ביארו חז\"ל (בסנהדרין ס\"ז ע\"ב) למה נקרא שמן כשפים מפני שמכחישים פמליא של מעלה. פירוש, כי לולא הכשפים היו הצדיקים יכולים להמשיך אותות ומופתים מעולמות העליונים לקרב העולם להשי\"ת, ע\"ד שהיה ביציאת מצרים ובימי יהושע והנביאים, אבל ע\"י החטא דעצה\"ד, נעשה בנין ד' עולמות אבי\"ע דס\"א, לעומת ד' עולמות אבי\"ע דקדושה, בסו\"ה זה לעומת זה עשה אלקים. שפירושו, שכל הכחות שישנם באבי\"ע דקדושה לקרב העולם להשי\"ת, ניתנו כנגדם באבי\"ע דטומאה, לרחק העולם מהשי\"ת. והענין הוא, כי כמו שהעבירה דעץ הדעת היתה לשורש שממנה נמשכים כל העבירות שבעולם עד גמר התקון. כן ה\u0003הצל,\u0004 דהיינו כח ההעלמה על קדושתו ית' כנ\"ל, הנמשך מעבירה דעצה\"ד, הנקרא \u0003עלי תאנה,\u0004 נעשה לשורש שממנו נמשכים כל מיני כחות ההעלמה על קדושתו ית', שבכללם הם נקראים ד' עולמות אבי\"ע דטומאה. שנבנו בסו\"ה, זה לעומת זה עשה אלקים, שה\"ס ד' עולמות אבי\"ע דטומאה לעומת ד' עולמות אבי\"ע דקדושה. כנ\"ל. והקרובים ביותר לשורש הזה הם הכשפים, שניתן להם כח שקול נגד הקדושה להכחיש את הפמליא של מעלה, ע\"ד שעשו המכשפים כנגד האותות והמופתים של משה רבינו, כמ\"ש ויעשו גם הם חרטומי מצרים בלהטיהם כן (שמות ז' י\"א) וכן אליהו שהתפלל שלא יאמרו מעשה כשפים הם (ברכות ט:) וע\"כ מלבד בהמקרים היוצאים מן הכלל, דהיינו ביציאת מצרים ובימי הנביאים, לא יוכלו הצדיקים להמשיך אותות ומופתים לקרב העולם להשי\"ת מחמת שיודעים בעליל, שאבי\"ע דטומאה יתנו כח להמכשפים שיוכלו לעשות גם הם בלהטיהם כן, וז\"ס שנאמר בגמר התקון, כימי צאתך מארץ מצרים אראנו נפלאות, שהפירוש הוא, כי אז, יתבטל רוח הטומאה מהארץ, ולא יהיה עוד פחד מאבי\"ע דטומאה, וימשיכו הצדיקים אותות ונפלאות כמו שהיה ביציאת מצרים."],[0,"","וזה אמרו \u0003דאוליפו כל זייני חרשין וקוסמין,\u0004 כי מכח \u0003עלי תאנה\u0004 שה\"ס הצל שנעשה ע\"י העבירה דעצה\"ד, נמשכו כל הכשפים, כנ\"ל, וע\"כ עם הסתכלותם ב\u0003עלי תאנה\u0004 הללו, היו לומדים כל מיני כשפים וקסמים שיהיו נמשכים מהם בהעולם."],[0,"וההיא שעתא אתגרע זקיפו וקומה דאדם מאה אמין:","ובאותה שעה נתמעט הרום והקומה של אדם למאה אמות. \u0003וכדין אתעביד פרודא, וקאים אדם בדינא, ואתלטיא ארעא.\u0004 ואז נעשה פירוד, בין ז\"א ונוקביה, ואדם קם בדין והארץ נתקללה,"],[0,"","פירוש, כמו שאמרו חז\"ל אדם הראשון מן הארץ עד לרקיע היה וכו' (חגיגה י\"ב.) דהיינו עד הרקיע שמתחת האצילות, והיה כולל ג' העולמות בי\"ע, שבכל עולם ד' פרצופין או\"א וזו\"ן, ובכל פרצוף עשרה ספירות. אבל לאחר שחטא, פרחו ממנו ט\"ס דאורות שבכל פרצוף ונסתלקו לשורשם. וט\"ס תחתונות דכלים שבכל פרצוף נפלו לקליפות, ונשארו לו רק הכלים דכתר מכל פרצוף באור הנפש. חוץ מב' פרצופי הראשונים דבריאה, שנסתלקו ממנו לגמרי באופן שנשארו לו עשר כתרים מעשר פרצופי דבי\"ע, שכל אחד כלול מכולם, והם מאה כתרים וה\"ס מאה אמה. וז\"ש \u0003וההיא שעתא אתגרע זקיפו וקומה דאדם מאה אמין\u0004 דהיינו מאה כתרים, כמבואר. (ועי' בספרי תלמוד עשר הספירות {חלק ט\"ז} דף אלף תתקנ\"ח בד\"ה וזה אמרו עד דף אלף תתקס\"ב אות קכ\"ח שנתבאר שם ענין זה במלואו)."],[1,"ויגרש את האדם וגו', אר\"א, מאן עביד תרוכין למאן, אי קב\"ה עביד תרוכין לאדם אי לא:","אמר רבי אלעזר מי עשה גירוש למי, אם הקב\"ה עשה גירוש אל האדם, או לא. שהרי לא כתוב ויגרש ה' את האדם, אלא, ויגרש את האדם, סתם. \u0003אבל מלה אתהפיך, ויגרש את, את דייקא, ומאן גרש את, האדם, האדם ודאי גרש את,\u0004 אבל המלה \u0003את,\u0004 שבהכתוב, נתהפך שהיה צריך לומר, ויגרש האדם את ומה שכתוב, ויגרש את, המלה \u0003את\u0004 הוא בדיוק, לרמז על השכינה שנקראת את, ומי גרש \u0003את,\u0004 שהיא חשכינה, האדם ודאי גרש \u0003את,\u0004 אלא שהמלות נתהפכו, שהיה צריך לכתוב ויגרש האדם את."],[2,"ובגין דא כתיב, וישלחהו ה' מג\"ע. אמאי וישלחהו, בגין דגרש אדם את.","ומשום זה כתוב וישלחהו ה' מג\"ע, למה כתוב וישלחהו, אלא משום שגרש האדם \u0003את,\u0004 שהיא השכינה, ע\"כ וישלחהו ה' מג\"ע פירוש שהוקשה לו למה הלשון כפול, שכתוב וישלחהו ה' מג\"ע ותכף אחר זה כתוב ויגרש את האדם וגו'. ומוכיח מכאן שא\"ת היא השכינה. והכתוב ויגרש את האדם הוא פירוש על הכתוב וישלחהו ה' מג\"ע. שעל כן שלחו מג\"ע, משום שבחטאו גרש את השכינה ממקומה."],[2,"וישכן, איהו אשרי לון באתר דא, דאיהו גרים וסתים אורחין ושבילין, ואשרי דינין על עלמא:","כתוב וישכן, סתם, ולא כתוב וישכן ה', הוא משום דקאי על אדה\"ר, שהוא השכין אותם, את הכרובים, במקום הזה, שהוא גרם וסתם הדרכים והשבילים העליונים, ונפסק השפע, והשרה דינים על העולם. \u0003ואמשיך לווטין מההוא יומא ולעילא,\u0004 והמשיך קללות להעולם מיום ההוא ואילך."],[3,"ואת להט החרב המתהפכת, כל אינון דשריין בקוזפי דינין על עלמא:","ואת להט החרב המתהפכת, פירושו כל אלו הנמצאים בדינים דולגים בהעולם, דהיינו שדולגים מצורה לצורה, שפושטים צורה ולובשים צורה. קופזי הוא כמו קופצי שפירושו דולגים. \u0003דמתהפכין לגוונין סגיאין בגין לאתפרעא מעלמא\u0004 שמתהפכים לצורות רבות, כדי להפרע מהעולם."],[3,"לזמנין גוברין לזמנא נשין, לזמנין אשא מלהטא ולזמנין רוחין. דלית מאן דקאים בהו:","לפעמים הם בצורות אנשים ולפעמים בצורות נשים. ולפעמים הם אש לוהט, ולפעמים הם רוחות. ואין מי שיעמוד עליהם. \u0003וכל דא לשמור את דרך עץ החיים דלא יוסיפון לאבאשא כקדמיתא.\u0004 וכל זה הוא לשמור את דרך עץ החיים שלא יוסיפו להרע כבתחילה. פירוש, כי ב' הנקודות בינה ומלכות שהיא מחזה ולמטה של המלכות, (כנ\"ל בהקדמת הזהר דף קכ\"ג אות קכ\"ב ד\"ה ב' תרין) נכללות זו בזו, ויש בינה ומלכות בנקודת הבינה, ויש בינה ומלכות בנקודת המלכות, ונמשך מהם ד' שליטות. ונבחנת בינה ומלכות שבבינה לזכרים דהיינו אנשים, כי הבינה בדכורא אסתיימת. ובינה ומלכות שבמלכות לנקבות דהיינו נשים. והארת הימין שבכל אחד נבחנת לרוחין. והארת השמאל שבכל אחד נבחנת לאשא מלהטא. וכבר נתבאר ענין זה באורך (לעיל דף ע\"ח מאות קי\"ט עד אות קכ\"ב ובהסולם שם) ואין להכפיל דברים."],[4,"להט החרב, אלין דמלהטאן אשא וקוסטירי על ראשיהון דרשיעיא וחייביא:","להט החרב. היינו, אלו הלוהטים אש ועונשים קשים על ראשיהם של הרשעים והפושעים. \u0003ומתהפכין גוונין לכמה זיינין לפום ארחייהו דבני נשא.\u0004 והצורות מתהפכים לכמה מינים של דינים, לפי דרכיהם של בני אדם. \u0003ועל דא להט כד\"א ולהט וגו'. החרב, דא חרב לה' כד\"א חרב לה' וגו'.\u0004 ועל כן נקראים, להט, כמו שאתה אומר ולהט אותם יום הבא. וע\"כ נקראים החרב, כי הוא חרב לה', כמו שאתה אומר, חרב לה' מלאה דם."],[5,"א\"ר יהודה להט החרב אפילו כל אינון קסטרין דלתתא דמתהפכין מדיוקנא לדיוקנא:","אר\"י, להט החרב הוא אפילו כל אלו המענישים של מטה, שבעוה\"ז, המתהפכים מצורה לצורה, \u0003כלהון ממנן על עלמא לאבאשא ולאסטאה לון לחייבי עלמא דעברין על פקודי דמאריהון.\u0004 כולם הם ממונים על העולם להרע ולהשטין לרשעי עולם העוברים על מצות רבונם. פירוש. ר\"י פליג על מה שרומז הזהר על סו\"ה ולהט אותם יום הבא, מפני שהכתוב הזה מדבר מעונשים עליונים, וממונים עליונים. והוא אומר \u0003אפילו כל אינון קסטרין דלתתא,\u0004 הוא בכלל להט החרב המתהפכת."],[6,"ת\"ח כיון דחב אדם אמשיך עליה כמה זיינין בישין וכמה גרדיני נמוסין:","בוא וראה כיון שחטא אדם, המשיך על עצמו כמה מיני מזיקים רעים וכמה מדייני דינים, \u0003ודחיל מכלהו ולא יכיל לקיימא עלייהו,\u0004 והיה ירא מכולם, ולא יכול להתגבר עליהם."],[6,"שלמה ידע חכמתא עלאה, ושוי ליה קב\"ה עטרא דמלכותא, והוו דחלי מניה כל עלמא:","שלמה ידע חכמה העליונה, והקב\"ה שם עליו כתר מלכות, והוו יראים מפניו כל בני העולם. \u0003כיון דחב אמשיך עליה כמה זיינין בישין, וכמה גרדיני נמוסין, ודחיל מכלהו,\u0004 כיון שחטא, המשיך על עצמו, כמה מיני מזיקים רעים, וכמה אורגי דינים כלומר נוכלי דינים, והיה ירא מכולם. גרדיני פירושו אורגים. כמנור אורגים תרגומו כאכסן דגרדאין. (שמואל א' י\"ז), נמוסין פירושו חוקים דינים. ומשפט הכהנים תרגומו ונימוסא דכהניא. (שמואל א' ב). \u0003וכדין יכילו לאבאשא ליה, ומה דהוה בידיה נטלו מניה,\u0004 ואז יכלו להרע לו, וכל מה שהיה בידו לקחו ממנו."],[7,"ועל דא, במה דאזיל בר נש, ובההוא ארחא דאתדבק ביה, הכי משיך עליה חילא ממנא דאזיל לקבליה:","ועל כן, במה שהאדם הולך, ובאותו הדרך שנתדבק בו, כן הוא ממשיך על עצמו כח ממונה ההולך לעומתו. פירוש, אם הולך בדרך טוב הוא ממשיך עליו כח ממונה מסטרא דקדושה המסייע אותו. ואם הולך בדרך רע, ממשיך עליו כח רע מצד הטומאה המזיק אותו. \u0003כך אדם, הוה משיך עליה חילא אחרא מסאב, דסאיב ליה ולכל בני עלמא.\u0004 כן אדם הראשון בחטאו, היה מושך על עצמו כח אחר טמא, שטימא אותו ולכל בני העולם."],[8,"ת\"ח כד חב אדם משיך עליה חילא מסאבא, וסאיב ליה ולכל בני עלמא, והאי הוא חויא בישא, דאיהו מסאב וסאיב עלמא:","בוא וראה, כאשר חטא אדם הראשון, המשיך על עצמו כח הטומאה, וטימא אותו ולכל בני העולם. וזה הוא נחש הרע, שהוא טמא וטימא העולם. \u0003דתנינן כד אפיק נשמתין מבני נשא אשתאר מניה גופא מסאב,\u0004 שלמדנו כאשר המלאך המות מוציא נשמות מבני אדם, נשאר ממנו גוף טמא, \u0003וסאיב ביתא וסאיב לכל אינון דמקרבין ביה, הה\"ד, הנוגע במת יטמא.\u0004 ומטמא הבית ומטמא לכל הקרבים אליו, וז\"ש הנוגע במת וגו', והוא משום שהמיתה מסובב מנחש הרע הטמא."],[9,"וע\"ד כיון דאיהו נטיל נשמתא, וסאיב גופא, כדין אתייהיב רשו לכל אינון סטרי מסאבן לשריא עלוי,","וכו'. ועל כן כיון שמלאך המות לקח הנשמה וטימא את הגוף, ניתן רשות אז לכל מיני טומאה לשרות על הגוף, כי גוף ההוא נטמא מצד אותו נחש הרע השורה עליו. כי המות מסובבת ממנו. \u0003ועל דא, בכל אתר דההוא חויא בישא שארי, מסאב ליה ואסתאב,\u0004 ועל כן בכל מקום שאותו נחש הרע שוכן, מטמא אותו, והוא נטמא."],[10,"ות\"ח כל בני עלמא בשעתא דניימי על ערסייהו בליליא, וליליא פריש גדפהא על כל בני עלמא:","ובוא וראה, כל בני העולם, בשעה שישנים במטותם בלילה, והלילה פורש כנפיו על כל בני העולם, \u0003טעמי טעמא דמותא, ומגו דטעמי טעמי דמותא, האי רוחא מסאבא שטיא על עלמא וסאיב עלמא.\u0004 טועמים אז טעם המות, ומשום שטועמים טעם המות, רוח הטומאה הזה משוטט אז בעולם ומטמא את העולם, \u0003ושריא על ידוי דבר נש ואסתאב,\u0004 ושורה על ידיו של האדם, והוא נטמא."],[11,"וכד אתער ואתהדר ליה נשמתיה, בכל מה דיקרב בידוי כלהו מסאבי:","וכשמקיץ משנתו, ונשמתו חוזרת אליו. בכל מה שיגע בידיו, יטמא הכל. \u0003בגין דשריא עלייהו רוח מסאבא.\u0004 משום שרוח הטומאה שורה עליהם. \u0003ועל דא לא יסב בר נש מנוי לאלבשא ממאן דלא נטיל ידוי,\u0004 ועל כן לא יקח איש את מלבושיו להתלבש ממי שלא נטל ידיו. \u0003דהא אמשיך עליה ההוא רוח מסאבא ואסתאב.\u0004 כי המשיך על עצמו רוח הטומאה ונטמא. \u0003ואית ליה רשו להאי רוח מסאבא לשריא בכל אתר דאשכח רשימו מסטריה.\u0004 ויש לו רשות לרוח הטומאה הזה לשכון בכל מקום שמוצא רשימה מצדו."],[12,"ועל דא לא יטול ידוי בר נש ממאן דלא נטיל ידוי:","ועל כן לא יטול אדם ידיו ממי שלא נטל ידיו, \u0003בגין דאמשיך עליה ההוא רוח מסאבא, וקביל ליה האי דנטיל מיא מניה, ואית ליה רשו לשריא עלוי דבר נש.\u0004 משום שהמשיך עליו רוח הטומאה, ומקבל אותו מי שנוטל מים ממנו, ויש רשות לרוח הטומאה לשרות עליו."],[12,"בגין כך בעי בר נש לאסתמרא בכל סטרוי, מסטרא דהאי חויא בישא דלא ישלוט עלוי.","ומשום כך צריך האדם להשמר בכל אשר יפנה, מצד נחש הרע הזה שלא ישלוט עליו. \u0003וזמין קב\"ה לעלמא דאתי לאעברא ליה מעלמא הה\"ד ואת רוח הטומאה וגו', וכתיב בלע המות לנצח.\u0004 ועתיד הקב\"ה להעביר את רוח הטומאה מהעולם בעולם הבא. וזהו מה שכתוב ואת רוח הטומאה אעביר מן הארץ. וכתיב בלע המות לנצח וגו'."]],[[0,"","וַיִּתְפְּרוּ עֲלֵה תְאֵנָה. הֲרֵי פֵּרַשְׁנוּ שֶׁלָּמְדוּ כָּל מִינֵי כְשָׁפִים וּקְסָמִים וְנֶאֶחְזוּ בָּזֶה שֶׁלְּמַטָּה, כְּמוֹ שֶׁנִּתְבָּאֵר. בְּאוֹתָהּ שָׁעָה נִגְרְעָה הַזְּקִיפוּת וְקוֹמַת הָאָדָם מֵאָה אַמּוֹת. וְאָז נַעֲשָׂה פֵרוּד, וְעָמַד אָדָם בְּדִין וְהִתְקַלְלָה הָאָרֶץ, וַהֲרֵי בֵּאַרְנוּ."],[1,"","וַיְגָרֶשׁ אֶת הָאָדָם. אָמַר רַבִּי אֶלְעָזָר, לֹא יָדַעְתִּי מִי עָשָׂה גֵרוּשִׁין לְמִי, אִם הַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה גֵרוּשִׁים לָאָדָם אִם לֹא. אֲבָל הַדָּבָר הִתְהַפֵּךְ, וַיְגָרֶשׁ אֶת, אֶ\"ת דַּוְקָא, וּמִי גֵרַשׁ אֶת? הָאָדָם. הָאָדָם וַדַּאי גֵּרַשׁ אֶת,"],[2,"","וְלָכֵן כָּתוּב וַיְשַׁלְּחֵהוּ ה' אֱלֹהִים מִגַּן עֵדֶן. לָמָּה וַיְשַׁלְּחֵהוּ? מִשּׁוּם שֶׁגֵּרַשׁ אָדָם אֶת, כְּפִי שֶׁבֵּאַרְנוּ. וַיַּשְׁכֵּן - הוּא הִשְׁרָה אוֹתָם בְּמָקוֹם זֶה. שֶׁהוּא גָּרַם וְסָתַם דְּרָכִים וּשְׁבִילִים וְהִשְׁרָה דִינִים עַל הָעוֹלָם, וְהִמְשִׁיךְ קְלָלוֹת מֵאוֹתוֹ יוֹם וָמַעְלָה."],[3,"","וְאֶת לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת, כָּל אֵלּוּ שֶׁשְּׁרוּיִים בְּזוֹרְקֵי הַדִּינִים עַל הָעוֹלָם, שֶׁמִּתְהַפְּכִים לִגְוָנִים רַבִּים כְּדֵי לְהִפָּרַע מֵהָעוֹלָם. לִפְעָמִים אֲנָשִׁים וְלִפְעָמִים נָשִׁים. לִפְעָמִים אֵשׁ לוֹהֶטֶת וְלִפְעָמִים רוּחוֹת שֶׁאֵין מִי שֶׁיַּעֲמֹד בָּהֶם. וְכָל זֶה לִשְׁמֹר אֶת דֶּרֶךְ עֵץ הַחַיִּים שֶׁלֹּא יוֹסִיפוּ לְהָרַע כְּמִקֹּדֶם."],[4,"","לַהַט הַחֶרֶב - אֵלּוּ שֶׁמְּלַהֲטִים אֵשׁ וְתַלְיָנִים עַל רָאשֵׁי הָרְשָׁעִים וְהַחוֹטְאִים. וְהַגְּוָנִים מִתְהַפְּכִים לְכַמָּה מִינִים לְפִי דַרְכֵי בְּנֵי הָאָדָם, וְעַל זֶה לַהַט, כְּמוֹ שֶׁנֶּאֱמַר (מלאכי ג) וְלִהַט אֹתָם הַיּוֹם הַבָּא וְגוֹ', וַהֲרֵי נֶאֱמַר. הַחֶרֶב - זוֹ חֶרֶב לַה', כְּמוֹ שֶׁנֶּאֱמַר (ישעיה לד) חֶרֶב לַה' מְלֵאָה דָּם וְגוֹ'."],[5,"","אָמַר רַבִּי יְהוּדָה, לַהַט הַחֶרֶב - (אפלו) כָּל אוֹתָם הַמְמֻנִּים שֶׁלְּמַטָּה שֶׁמִּתְהַפְּכִים מִדְּמוּת לִדְמוּת, כֻּלָּם מְמֻנִּים עַל הָעוֹלָם לְהָרַע וּלְהַסְטוֹת אֶת רִשְׁעֵי הָעוֹלָם שֶׁעוֹבְרִים עַל מִצְווֹת רִבּוֹנָם."],[6,"","בֹּא רְאֵה, כֵּיוָן שֶׁאָדָם חָטָא, הִמְשִׁיךְ עָלָיו כַּמָּה מִינִים רָעִים וְכַמָּה בַּעֲלֵי דִינִים, וּפָחַד מִכֻּלָּם וְלֹא יָכֹל לַעֲמֹד עֲלֵיהֶם. שְׁלֹמֹה יָדַע חָכְמָה עֶלְיוֹנָה, וְשָׂם לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא עֲטֶרֶת מַלְכוּת, וְכָל הָעוֹלָם הָיָה פוֹחֵד מִמֶּנּוּ. כֵּיוָן שֶׁחָטָא, הִמְשִׁיךְ עָלָיו כַּמָּה מִינִים רָעִים וְכַמָּה בַּעֲלֵי דִינִים, וּפָחַד מִכֻּלָּם, וְאָז יָכְלוּ לְהָרַע לוֹ. וּמַה שֶּׁהָיָה בְּיָדוֹ לָקְחוּ מִמֶּנּוּ."],[7,"","וְעַל זֶה, בְּמַה שֶּׁהוֹלֵךְ בֶּן אָדָם וּבְאוֹתָהּ הַדֶּרֶךְ שֶׁנִּדְבָּק בָּהּ, כָּךְ מוֹשֵׁךְ עָלָיו כֹּחַ מְמֻנֶּה שֶׁהוֹלֵךְ כְּנֶגְדּוֹ. כָּךְ אָדָם הָיָה מוֹשֵׁךְ עָלָיו כֹּחַ טָמֵא אַחֵר שֶׁטִּמֵּא אוֹתוֹ וְאֶת כָּל בְּנֵי הָעוֹלָם."],[8,"","בֹּא רְאֵה, כְּשֶׁחָטָא אָדָם, מָשַׁךְ עָלָיו כֹּחַ טֻמְאָה וְטִמֵּא אוֹתוֹ וְאֶת כָּל בְּנֵי הָעוֹלָם, וְזֶהוּ נָחָשׁ הָרָע שֶׁהוּא טָמֵא וּמְטַמֵּא אֶת הָעוֹלָם. שֶׁשָּׁנִינוּ, כְּשֶׁמּוֹצִיא נְשָׁמוֹת מִבְּנֵי הָאָדָם, נִשְׁאָר מִמֶּנּוּ גּוּף טָמֵא, וּמְטַמֵּא אֶת הַבַּיִת וּמְטַמֵּא אֶת כָּל אֵלֶּה שֶׁמִּתְקָרְבִים אֵלָיו. זֶהוּ שֶׁכָּתוּב (במדבר יט) הַנֹּגֵעַ בְּמֵת וְגוֹ'."],[9,"","וְעַל זֶה, כֵּיוָן שֶׁהוּא נוֹטֵל נְשָׁמָה וּמְטַמֵּא אֶת הַגּוּף, אָז נִתְּנָה רְשׁוּת לְכָל אוֹתָם צְדָדִים טְמֵאִים לִשְׁרוֹת עָלָיו, שֶׁהֲרֵי אוֹתוֹ הַגּוּף נִטְמָא מִן הַצַּד שֶׁל אוֹתוֹ הַנָּחָשׁ הָרָע שֶׁשּׁוֹרֶה עָלָיו. וְעַל זֶה, בְּכָל מָקוֹם שֶׁאוֹתוֹ נָחָשׁ הָרָע שׁוֹרֶה, מְטַמֵּא אוֹתוֹ וְנִטְמָא."],[10,"","וּבֹא וּרְאֵה, כָּל בְּנֵי הָעוֹלָם בְּשָׁעָה שֶׁיְּשֵׁנִים עַל מִטּוֹתֵיהֶם בַּלַּיְלָה, וְהַלַּיְלָה פּוֹרֵשׂ כְּנָפָיו עַל כָּל בְּנֵי הָעוֹלָם, טוֹעֲמִים טַעַם הַמָּוֶת. וּמִתּוֹךְ שֶׁטּוֹעֲמִים טַעַם מָוֶת, רוּחַ הַטֻּמְאָה הַזּוֹ שָׁטָה עַל הָעוֹלָם וּמְטַמֵּאת (את) הָעוֹלָם (ד\"א בתוך האהל שלו), וְשׁוֹרָה עַל יְדֵי הָאִישׁ וְנִטְמָא."],[11,"","וּכְשֶׁמִּתְעוֹרֵר וְנִשְׁמָתוֹ חוֹזֶרֶת אֵלָיו, בְּכָל מַה שֶּׁיְּקָרֵב בְּיָדוֹ - הַכֹּל נִטְמָא, כִּי שׁוֹרָה עֲלֵיהֶם רוּחַ טֻמְאָה. וְעַל זֶה לֹא יִקַּח אָדָם בְּגָדָיו לִלְבֹּשׁ מִמִּי שֶׁלֹּא נָטַל יָדָיו, שֶׁהֲרֵי הִמְשִׁיךְ עָלָיו אוֹתוֹ רוּחַ טֻמְאָה וְנִטְמָא. וְיֵשׁ רְשׁוּת לְרוּחַ הַטֻּמְאָה הַזּוֹ לִשְׁרוֹת בְּכָל מָקוֹם שֶׁנִּמְצָא רֹשֶׁם מִצִּדּוֹ."],[12,"","וְלָכֵן לֹא יִטֹּל אָדָם יָדָיו מִמִּי שֶׁלֹּא נָטַל יָדָיו, מִשּׁוּם שֶׁהִמְשִׁיךְ עָלָיו אוֹתוֹ רוּחַ טֻמְאָה וְקִבְּלוֹ זֶה שֶׁנָּטַל מַיִם מִמֶּנּוּ, וְיֵשׁ לוֹ רְשׁוּת לִשְׁרוֹת עַל הָאָדָם. לָכֵן צָרִיךְ אָדָם לְהִשָּׁמֵר בְּכָל צְדָדָיו מִצַּד הַנָּחָשׁ הָרָע הַזֶּה שֶׁלֹּא יִשְׁלֹט עָלָיו, וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לָעוֹלָם הַבָּא לְבַטְּלוֹ מִן הָעוֹלָם. זֶהוּ שֶׁכָּתוּב (זכריה יג) וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ, וְאָז כָּתוּב (ישעיה כב) בִּלַּע הַמָּוֶת לָנֶצַח וְגוֹ'."]]],[["וְהָאָדָם יָדַע אֶת חַוָּה אִשְׁתּוֹ וְגו'. רַבִּי אַבָּא פָּתַח (ואמר) (קהלת ג׳:כ״א) מִי יוֹדֵעַ רוּחַ בְּנִי הָאָדָם הָעוֹלָה הִיא לְמַעְלָה וְרוּחַ הַבְּהֵמָה הַיּוֹרֶדֶת הִיא לְמַטָּה לָאָרֶץ. הַאי קְרָא כַּמָּה גְוָונִין אִית בֵּיהּ. וְהָכִי הוּא כָּל מִלּוֹי דְאוֹרַיְיתָא כַּמָּה גְוָונִין בְּכָל חַד וְחַד וְכֻלְהוּ יָאוּת וְהָכִי אִנּוּן.","וְכָל אוֹרַיְיתָא מִתְפָּרְשָׁא בְּשִׁבְעִין אַנְפִּין. לָקֳבֵיל שִׁבְעִין סִטְרִין וְשִׁבְעִין עַנְפִּין. וְהָכִי הוּא בְּכָל מִלָּה וּמִלָּה דְאוֹרַיְיתָא. וְכָל מַאי דְּנָפִיק מִכָּל מִלָּה וּמִלָּה כַּמָּה גְוָונִין אִתְפַּרְשָׁן מִנֵּיהּ לְכָל סִטְרִין.","תָּא חֲזֵי, כַּד בַּר נָשׁ אָזִיל בְּאֹרַח קְשׁוֹט, הוּא אָזִיל לִימִינָא, וְאַמְשִׁיךְ עֲלֵיהּ רוּחָא קַדִּישָׁא עִלָּאָה מֵעֵילָא. וְהַאי רוּחַ סָלִיק בִּרְעוּתָא קַדִּישָׁא לְאִתְאַחֲדָא לְעֵילָא וּלְאִתְדַבְּקָא בִּקְדוּשָׁה עִלָּאָה דְּלָא אִתְעַדֵּי מִנֵּיהּ.","וְכַד בַּר נָשׁ אָזִיל בְּאוֹרַח בִּישׁ וְסָטֵי אָרְחוֹי, הוּא אַמְשִׁיךְ עֲלֵיהּ רוּחַ מְסָאֳבָא דְּלִסְטַר שְׂמָאלָא, וְסָאִיב לֵיהּ וְאִסְתָּאַב בֵּיהּ. כְּמָא דְאַתְּ אָמֵר, (ויקרא י״א:מ״ג) וְלֹא תִטַּמְאוּ בָּהֶם וְנִטְמֵתֶם בָּם. אֲתָא לְאִסְתָּאֲבָא מְסָאֲבִין לֵיהּ.","וְתָּא חֲזֵי, בְּשַׁעֲתָא דְּבַר נָשׁ אָזִיל בְּאֹרַח קְשׁוֹט וְאַמְשִׁיךְ עֲלֵיהּ רוּחָא קַדִּישָׁא עִלָּאָה וְאִתְדַבִּיק בֵּיהּ, בְּרָא דְיוֹלִיד וְיִפּוּק מִנֵּיהּ לְעָלְמָא, הוּא מָשִׁיךְ עֲלֵיהּ קְדוּשָׁה עִלָּאָה, וִיהֵא קַדִּישׁ בִּקְדוּשָׁה דְמָארֵיהּ. כְּמָה דִכְתִיב, (ויקרא כ׳:ז׳) וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדוֹשִׁים וְגו'.","וְכַד אִיהוּ אָזִיל בִּסְטַר שְׂמָאלָא, וְאַמְשִׁיךְ עֲלֵיהּ רוּחַ מְסָאֲבָא וְאִתְדְּבַק בֵּיהּ, בְּרָא דְּיִפּוּק מִנֵּיהּ לְעָלְמָא הוּא אַמְשִׁיךְ עֲלֵיהּ רוּחַ מְסָאֲבוּ וְיִסְתָּאַב בִּמְסָאֲבוּ דְּהַהוּא סִטְרָא.","וְעַל דָּא כְּתִיב מִי יוֹדֵעַ רוּחַ בְּנִי הָאָדָם הָעוֹלָה הִיא לְמַעְלָה. כַּד אִיהוּ בְּאִתְדַּבְּקוּת יָמִינָא סָלְקָא הִיא לְעֵילָא. וְכַד אִיהוּ בְּאִתְדַּבְּקוּת שְׂמָאלָא הַהוּא סְטַר שְׂמָאלָא דְּאִיהוּ רוּחַ מְסָאֲבוּ נָחִית מֵעֵילָא לְתַתָּא וְשַׁוֵּי דִיּוּרֵיהּ בְּבַר נָשׁ וְלָא אַעֲדֵי מִנֵּיהּ. וּבְרָא (ומה) דְאוֹלִיד בְּהַהוּא (רוח) מְסָאֲבוּ אִיהוּ הֲוֵי בְּרֵיהּ מֵהַהוּא רוּחַ מְסָאַב אִיהוּ הַהוּא בְּרָא.","אָדָם אִתְדָּבַּק בְּהַהוּא רוּחַ מְסָאַב וְאִתְּתֵיהּ אִתְדַּבְּקָא בֵּיהּ בְּקַדְמִיתָא וְנַטְלַת וְקַבִּילַת הַהוּא זוּהֲמָא מִנֵּיהּ אוֹלִיד בַּר. הַאי בְּרָא בְּרָא דְרוּחַ מְסָאֲבָא אִיהוּ. וְעַל דָּא תְּרֵין בְּנִין הֲווּ. חַד מֵהַהוּא רוּחַ מְסָאָב וְחַד כַּד תָּב אָדָם בִּתְיוּבְתָּא. וּבְגִינֵי כָךְ הַאי מִסִּטְרָא מְסָאֳבָא. (ודא ד\"א והאי) מִסִּטְרָא דַכְיָיא.","רַבִּי אֶלְעָזָר אָמַר בְּשַׁעֲתָא דְּאַטִּיל נָחָשׁ הַהוּא זוּהֲמָא בָּהּ בְּחַוָּה קַבִּילַת לֵיהּ. וְכַד אִשְׁתַּמַּשׁ עִמָּהּ אָדָם אוֹלִידַת תְּרֵין בְּנִין. חַד מֵהַהוּא סִטְרָא מְסָאֳבָא וְחַד מִסִּטְרָא דְּאָדָם. וְהֲוֵי דָּמֵי הֶבֶל בְּדִיוּקְנָא דִלְעֵילָא וְקַיִּן בְּדִיוּקְנָא דִלְתַתָּא. וּבְגִין כָּךְ אִתְפְּרָשׁוּ אָרְחַיְיהוּ דָּא מִן דָּא.","וַדַּאי קַיִן בְּרָא דְרוּחַ מְסָאֳבָא הֲוָה דְּאִיהוּ חִוְיָא בִישָׁא. (והבל ברא דאדם) הֲוָה. וּבְגִין דְּקַיִן אֲתָא מִסִּטְרָא דְמַלְאַךְ הַמָּוֶת קָטִיל לֵיהּ לְאֲחוּי. וְהוּא בְּסִטְרָא דִילֵיהּ. וּמִנֵּיהּ כָּל מְדוֹרִין בִּישִׁין וּמַזִיקִין וְשֵׁדִין וְרוּחִין אַתְיָין לְעָלְמָא.","אָמַר רַבִּי יוֹסֵי, קַיִן, קִינָא דִּמְדוֹרִין בִּישִׁין דְּאָתוּ מִסִּטְרָא דִּמְסָאֳבָא לְעָלְמָא. וּלְבָתַר אַיְיתִיאוּ קָרְבָּנָא. דָּא אַקְרִיב מִסִּטְרָא דִילֵיהּ וְדָא אַקְרִיב מִסִּטְרָא דִילֵיהּ. הֲדָא הוּא דִכְתִיב וַיְהִי מִקֵּץ יָמִים וַיָּבֵא קַיִן מִפְּרִי הָאֲדָמָה וְגו'. רַבִּי שִׁמְעוֹן אָמַר וַיְהִי מִקֵּץ יָמִים, מַאי מִקֵּץ יָמִים, דָּא הוּא קֵץ כָּל בָּשָׂר. וּמָאן אִיהוּ דָּא מַלְאַךְ הַמָּוֶת.","וְקַיִן מֵהַהוּא קֵץ יָמִים אַיְיתֵי קָרְבָּנָא. דַּיְיקָא דְּקָאָמַר מִקֵּץ יָמִים וְלָא אָמַר מִקֵּץ יָמִין. וּבְגִין כָּךְ כָּתוּב בְּדָנִיֵּאל (דניאל י״ב:י״ג) וְאַתָּה לֵךְ לַקֵּץ וְתָנוּחַ וְתַעֲמוֹד לְגוֹרָלְךָ. אָמַר לֵיהּ לְקֵץ הַיָּמִים אוֹ לְקֵץ הַיָּמִין. אָמַר לֵיהּ לְקֵץ הַיָּמִין. וְקַיִן מִקֵּץ הַיָּמִים אַיְיתֵי,"],[[0,"והאדם ידע את חוה וגו', רבי אבא פתח, מי יודע רוח בני האדם וגו' האי קרא כמה גוונין אית ביה:","והאדם ידע וגו'. ר\"א פתח. בהכתוב מי יודע רוח בני האדם וגו'. בכתוב הזה כמה פנים יש בו, \u0003והכי הוא כל מלוי דאורייתא, כמה גוונין בכל חד וחד וכלהו יאות.\u0004 וכן הוא כל דבריה של התורה, שיש כמה פנים בכל אחד ואחד, וכולם אמיתים."],[1,"והכי אינון וכל אורייתא מתפרשא בשבעין אנפין לקביל שבעין סטרין ושבעין אנפין,","וכך הם, שכל התורה מתבאר בע' פנים, כנגד ע' קצוות וע' פנים, שיש בז\"א: ע' קצוות, הן בז\"ת שלו, שכל קצה כולל ע\"ס, וז' פעמים עשר הן ע'. וע' פנים, הם בג\"ר שלו, שהם ג\"כ ז\"פ ע\"ס שבראש שלו, אלא שבחינת ג\"ר מכונים פנים, בסו\"ה חכמת אדם תאיר פניו. \u0003והכי הוא בכל מלה ומלה דאורייתא, וכל מאי דנפיק מכל מלה ומלה, כמה גוונין אתפרשן מניה לכל סטרין.\u0004 וכן הוא בכל דבר ודבר שבתורה, ובכל מה שיוצא מכל דבר ודבר, אשר כמה פנים מתבארים ממנו לכל הצדדים."],[2,"ת\"ח, כד בר נש אזיל בארח קשוט, הוא אזיל לימינא, ואמשיך עליה רוחא קדישא עלאה מעילא:","בוא וראה, כאשר האדם הולך בדרך האמת, הוא הולך לימין, וממשיך על עצמו רוח קודש העליון מלמעלה. \u0003והאי רוח סליק ברעותא קדישא לאתאחדא לעילא ולאתדבקא בקדושה עלאה דלא אתעדי מניה.\u0004 ורוח זה נעשה לו רצון קדוש להתיחד למעלה ולהתדבק בקדושה העליונה שלא תפסק ממנו לעולם."],[3,"וכד בר נש אזיל באורח ביש וסטי אורחוי, הוא אמשיך עליה רוח מסאבא דלסטר שמאלא,","וכאשר אדם הולך בדרך הרע, ודרכיו נטו מדרך הישר, הוא ממשיך על עצמו רוח הטומאה שבצד שמאל. \u0003וסאיב ליה ואסתאב ביה, כד\"א ולא תטמאו וגו', אתא לאסתאבא מסאבין ליה.\u0004 ומטמא אותו ונטמא בו, כמו שאתה אומר, ולא תטמאו בהם, ונטמתם בם. הבא לטמא מטמאים אותו."],[4,"ותא חזי בשעתא דבר נש אזיל בארח קשוט, ואמשיך עליה רוחא קדישא עלאה ואתדבק ביה:","ובוא וראה, בשעה שאדם הולך בדרך האמת, וממשיך עליו רוח קדוש עליון ומתדבק בו, \u0003ברא דיוליד ויפוק מניה לעלמא הוא משיך עליה קדושה עלאה, ויהא קדיש בקדושה דמאריה כד\"א והתקדשתם\u0004 וגו', הבן שיוליד ויצא ממנו לעולם הוא ממשיך עליו קדושה עליונה, ויהיה קדוש בקדושת רבונו, כמו שכתוב והתקדשתם והייתם קדושים וגו'."],[5,"וכד איהו אזיל בסטר שמאלא, ואמשיך עליה רוח מסאבא ואתדבק ביה:","וכשהוא הולך בצד השמאל והמשיך על עצמו רוח הטומאה ונתדבק בו, \u0003ברא דיפוק מניה לעלמא, הוא אמשיך עליה רוח מסאבו, ויסתאב במסאבו דההוא סטרא,\u0004 הבן שיוצא ממנו לעולם, הוא ממשיך עליו רוח הטומאה, ויטמא בהטומאה של אותו הצד."],[6,"ועל דא כתיב מי יודע רוח בני האדם העולה וגו', כד איהו באתדבקות ימינא סלקא היא לעילא:","וע\"כ כתוב, מי יודע רוח בני האדם וגו' כי כאשר האדם הוא בדבקות הימין, עולה, האור שממשיך, ממטה למעלה, \u0003וכד איהו באתדבקות שמאלא, ההוא סטר שמאלא, דאיהו רוח מסאבו נחית מעילא לתתא,\u0004 וכאשר האדם הוא בדביקות בהשמאל, אותו צד השמאל, שהוא רוח הטומאה יורד ממעלה למטה, דהיינו שממשיך הארת השמאל ממעלה למטה, \u0003ושוי דיוריה בבר נש ולא אעדי מניה,\u0004 ומשים דירתו בהאדם, ואינו עוזב אותו, פירוש. כי מבאר ההפרש מצד הקדושה לצד הטומאה עם הכתוב, מי יודע רוח בני האדם העולה היא למעלה ורוח הבהמה היורדת היא למטה. וז\"ש \u0003כד איהו באתדבקות ימינא סלקא היא לעילא,\u0004 דהיינו רוח בני האדם העולה היא למעלה. דהיינו ממטה למעלה. וז\"ש \u0003רוח מסאבו נחית מעילא לתתא,\u0004 דהיינו ורוח הבהמה היורדת היא למטה, וטעם הדבר וההפרש בין המשכת השפע ממטה למעלה אל המשכתו ממעלה למטה, כבר נתבאר לעיל (דף קע\"א ד\"ה אדם) \u0003וברא דאוליד בההוא מסאבו איהו הוה בריה מההוא רוח מסאב,\u0004 והבן שהוליד בטומאה ההיא, הוא נחשב לבנו של רוח הטומאה ההוא."],[7,"אדם אתדבק בההוא רוח מסאב ואתתיה אתדבקא ביה בקדמיתא ונטלת וקבילת ההוא זוהמא מניה:","אדם הראשון נתדבק באותו רוח הטומאה, הוא הנחש, ואשתו חוה, נתדבקה בו בתחילה, ולקחה וקבלה אותה הזוהמא ממנו. \u0003אוליד בר, האי ברא ברא דרוח מסאבא איהו,\u0004 והוליד בן, הרי בן הזה הוא של רוח הטמא. \u0003וע\"ד תרין בנין הוו, חד מההוא רוח מסאב, וחד כד תב אדם בתיובתא.\u0004 ב' בנים היו, אחד מאותו רוח הטמא. והוא קין. ואחד כשהאדם חזר בתשובה, והוא הבל. \u0003ובגיני כך, האי מסטרא מסאבא, והאי מסטרא דכייא,\u0004 ומשום זה, זה היה מצד הטומאה, דהיינו קין. וזה היה מצד הטהור. דהיינו הבל."],[8,"רבי אלעזר אמר, בשעתא דאטיל נחש ההוא זוהמא בחוה, קבילת ליה, וכד אשתמש עמה אדם אולידת תרין בנין:","רא\"א, בשעה שהטיל הנחש את הזוהמא בחוה, קבלתה אותו, דהיינו שנתעברה הימנו. וכשאדם שימש עמה הולידה ב' בנים, \u0003חד מההוא סטרא מסאבא, וחד מסטרא דאדם, והוי דמי הבל בדיוקנא דלעילא וקין בדיוקנא דלתתא,\u0004 אחד היה מאותו צד הטמא, דהיינו קין, ואחד מצד אדם דהיינו הבל. והיה הבל דומה לצורה של מעלה וקין לצורה של מטה. \u0003ובגין כך אתפרשו ארחייהו דא מן דא,\u0004 ומשום זה נפרדו דרכיהם זה מזה."],[9,"ודאי קין ברא דרוח מסאבא הוה דאיהו חויא בישא הוה:","ודאי שקין בן רוח הטמא היה, שהוא נחש הרע. \u0003ובגין דקין אתא מסטרא דמלאך המות קטיל ליה לאחוי,\u0004 ומשום שקין בא מצד מלאך המות הרג את אחיו. כלומר, שהריגת הבל הוא ענין אחד עם החטא של עצה\"ד שהסית הנחש, וכמו שבעצה\"ד קבל מלאך המות שליטה על כל העולם, כן קיבל כאן שליטה להוציא נשמת הבל. \u0003והוא בסטרא דיליה, ומניה כל מדורין ומזיקין ושדין ורוחין אתיין לעלמא.\u0004 וקין הוא מהצד שלו. וכל מדורים הרעים ומזיקים ושדים ורוחות, באים ממנו להעולם."],[10,"אמר רבי יוסי קין קינא דמדורין בישין, דאתו מסטרא דמסאבא לעלמא,","אר\"י השם קין יורה, קן לכל מדורים הרעים הבאים מהצד הטמא להעולם. \u0003ולבתר אייתיאו קרבנא דא אקריב מסטרא דיליה\u0004 וכו'. ואח\"כ הביאו קרבן, זה הקריב מהצד שלו וזה הקריב מהצד שלו. \u0003הה\"ד ויהי מקץ ימים ויבא קין מפרי האדמה וגו'. ר\"ש אמר ויהי מקץ ימים מאי מקץ ימים, דא הוא קץ כל בשר ומאן איהו דא מלאך המות,\u0004 וז\"ש ויהי מקץ ימים ויבא קין מפרי האדמה וגו' ר\"ש אמר, כתוב ויהי מקץ ימים, מהו מקץ ימים, זהו קץ כל בשר, ומי הוא קץ כל בשר, זהו מלאך המות. הרי שקרבנו של קין מהצד הטמא היה."],[11,"וקין מההוא קץ ימים אייתי קרבנא, דייקא דקאמר מקץ ימים, ולא אמר מקץ ימין:","וקין מאותו קץ הימים הביא הקרבן, בדיוק אמר הכתוב מקץ ימים, ואינו אומר מקץ ימין, \u0003ובגין כך כתוב בדניאל, ואתה לך לקץ ותנוח ותעמוד לגורלך, אמר לו\u0004 דניאל להקב\"ה, \u0003לקץ הימים או לקץ הימין\u0004 וכו', כי קץ הימים הוא קליפה רעה (כמ\"ש להלן פרשת נח דף כ\"ח אות ע\"ה ע\"ו ובהסולם) \u0003וקין מקץ הימים אייתי,\u0004 וקין, מקץ הימים הביא קרבנו שהוא מסטרא דמלאך המות, הרי שהקריב קרבנו מהצד שלו."]],[[0,"","וְהָאָדָם יָדַע אֶת חַוָּה אִשְׁתּוֹ וְגוֹ'. רַבִּי אַבָּא פָּתַח וְאָמַר, (קהלת ג) מִי יוֹדֵעַ רוּחַ בְּנֵי הָאָדָם הָעֹלָה הִיא לְמָעְלָה וְרוּחַ הַבְּהֵמָה הַיֹּרֶדֶת הִיא לְמַטָּה לָאָרֶץ. לַפָּסוּק הַזֶּה יֵשׁ כַּמָּה גְוָנִים, וְכֵן הוּא כָּל דִּבְרֵי הַתּוֹרָה יֵשׁ בְּכָל אֶחָד וְאֶחָד כַּמָּה גְוָנִים, וְכֻלָּם נְאוֹתִים וְכָךְ הֵם."],[1,"","וְכָל הַתּוֹרָה מִתְפָּרֶשֶׁת בְּשִׁבְעִים פָּנִים כְּנֶגֶד שִׁבְעִים צְדָדִים וְשִׁבְעִים עֲנָפִים, וְכָךְ הוּא בְּכָל דָּבָר וְדָבָר שֶׁל הַתּוֹרָה. וְכָל מַה שֶּׁיּוֹצֵא מִכָּל דָּבָר וְדָבָר, כַּמָּה אֳפָנִים מִתְפָּרְשִׁים מִמֶּנּוּ לְכָל הַצְּדָדִים."],[2,"","בֹּא רְאֵה, כְּשֶׁבֶּן אָדָם הוֹלֵךְ בְּדֶרֶךְ אֱמֶת, הוּא הוֹלֵךְ לְיָמִין וּמַמְשִׁיךְ עָלָיו רוּחַ קְדוֹשָׁה עֶלְיוֹנָה מִלְמַעְלָה, וְרוּחַ זוֹ עוֹלָה בְרָצוֹן קָדוֹשׁ לְהֵאָחֵז לְמַעְלָה וּלְהִדָּבֵק בִּקְדֻשָּׁה עֶלְיוֹנָה שֶׁלֹּא תָזוּז מִמֶּנּוּ."],[3,"","וּכְשֶׁאָדָם הוֹלֵךְ בְּדֶרֶךְ רָעָה וְסוֹטֶה בִּדְרָכָיו, הוּא מוֹשֵׁךְ עָלָיו רוּחַ טֻמְאָה שֶׁלְּצַד שְׂמֹאל, וּמְטַמֵּא אוֹתוֹ וְנִטְמָא בּוֹ, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא יא) וְלֹא תִטַּמְּאוּ בָּהֶם וְנִטְמֵתֶם בָּם. בָּא לְהִטָּמֵא - מְטַמְּאִים אוֹתוֹ."],[4,"","וּבֹא וּרְאֵה, בְּשָׁעָה שֶׁבֶּן אָדָם הוֹלֵךְ בְּדֶרֶךְ אֱמֶת וּמוֹשֵׁךְ עָלָיו רוּחַ קְדֻשָּׁה עֶלְיוֹנָה וְנִדְבָּק בָּהּ, הַבֵּן שֶׁיּוֹלִיד וְיֵצֵא מִמֶּנּוּ לָעוֹלָם הוּא מַמְשִׁיךְ עָלָיו קְדֻשָּׁה עֶלְיוֹנָה וְיִהְיֶה קָדוֹשׁ בִּקְדֻשַּׁת רִבּוֹנוֹ, כְּמוֹ שֶׁכָּתוּב (שם כ) וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדשִׁים וְגוֹ'."],[5,"","וּכְשֶׁהוּא הוֹלֵךְ בְּצַד שְׂמֹאל וּמַמְשִׁיךְ עָלָיו רוּחַ טֻמְאָה וְנִדְבָּק בּוֹ, הַבֵּן שֶׁיֵּצֵא מִמֶּנּוּ לָעוֹלָם הוּא מַמְשִׁיךְ עָלָיו רוּחַ טֻמְאָה וְיִטְמָא בְּטֻמְאַת אוֹתוֹ הַצַּד."],[6,"","וְעַל זֶה כָּתוּב, מִי יוֹדֵעַ רוּחַ בְּנֵי הָאָדָם הָעֹלָה הִיא לְמָעְלָה. וּכְשֶׁהוּא בְּהִדָּבְקוּת הַיָּמִין, הִיא עוֹלָה לְמַעְלָה. וּכְשֶׁהוּא בְּהִדָּבְקוּת הַשְּׂמֹאל, אוֹתוֹ צַד שְׂמֹאל שֶׁהוּא רוּחַ טֻמְאָה יוֹרֵד מִלְמַעְלָה לְמַטָּה, וְשָׂם דִּיּוּרוֹ בְּבֶן הָאָדָם וְלֹא זָז מִמֶּנּוּ. וְהַבֵּן (ומה) שֶׁהוֹלִיד בְּאוֹתָהּ (רוח) טֻמְאָה הוּא נִהְיָה בְּנוֹ מֵאוֹתוֹ רוּחַ הַטֻּמְאָה הוּא אוֹתוֹ הַבֵּן."],[7,"","אָדָם נִדְבַּק בְּאוֹתוֹ רוּחַ טָמֵא, וְאִשְׁתּוֹ נִדְבְּקָה בּוֹ בַּהַתְחָלָה, וְלָקְחָה וְקִבְּלָה אוֹתָהּ זֻהֲמָה מִמֶּנָּה הוֹלִיד בֵּן. בֵּן זֶה הוּא בֵּן שֶׁל רוּחַ הַטֻּמְאָה. וְעַל זֶה שְׁנֵי בָנִים הֵם - אֶחָד מֵאוֹתוֹ רוּחַ טָמֵא, וְאֶחָד כְּשֶׁשָּׁב אָדָם בִּתְשׁוּבָה. וְלָכֵן זֶה מִצַּד הַטֻּמְאָה, (וזה) וְזֶה מִצַּד הַטָּהֳרָה."],[8,"","רַבִּי אֶלְעָזָר אָמַר, בְּשָׁעָה שֶׁהִטִּיל נָחָשׁ אוֹתָהּ זֻהֲמָה בְּחַוָּה, הִיא קִבְּלָה אוֹתוֹ, וּכְשֶׁשִּׁמֵּשׁ עִמָּהּ אָדָם, הוֹלִידָה שְׁנֵי בָנִים - אֶחָד מֵאוֹתוֹ צַד טָמֵא, וְאֶחָד מִצַּד שֶׁל אָדָם. וְהֶבֶל הָיָה דּוֹמֶה בִּדְמוּת עֶלְיוֹנָה, וְקַיִן בִּדְמוּת תַּחְתּוֹנָה, וְלָכֵן דַּרְכֵיהֶם נִפְרְדוּ זֶה מִזֶּה."],[9,"","וַדַּאי שֶׁקַּיִן הָיָה בֵּן שֶׁל רוּחַ הַטֻּמְאָה שֶׁהוּא הַנָּחָשׁ הָרָע (והבל בן של אדם) הָיָה. וּבִגְלַל שֶׁקַּיִן בָּא מִצַּד שֶׁל מַלְאַךְ הַמָּוֶת, הָרַג אֶת אָחִיו, וְהוּא בְּצִדּוֹ, וּמִמֶּנּוּ כָּל הַמְּדוֹרִים הָרָעִים וּמַזִּיקִים וְשֵׁדִים וְרוּחוֹת בָּאִים לָעוֹלָם."],[10,"","אָמַר רַבִּי יוֹסֵי, קַיִן - קֵן שֶׁל מְדוֹרִים רָעִים שֶׁבָּאוּ מִצַּד הַטֻּמְאָה לָעוֹלָם. וְאַחַר כָּךְ הֵבִיאוּ קָרְבָּן. זֶה הִקְרִיב מִצַּד שֶׁלּוֹ, וְזֶה הִקְרִיב מִצַּד שֶׁלּוֹ. זֶהוּ שֶׁכָּתוּב וַיְהִי מִקֵּץ יָמִים וַיָּבֵא קַיִן מִפְּרִי הָאֲדָמָה וְגוֹ'. רַבִּי שִׁמְעוֹן אָמַר, וַיְהִי מִקֵּץ יָמִים, מַה זֶּה מִקֵּץ יָמִים? זֶהוּ קֵץ כָּל בָּשָׂר. וּמִיהוּ זֶה? מַלְאַךְ הַמָּוֶת."],[11,"","וְקַיִן מֵאוֹתוֹ קֵץ יָמִים הֵבִיא קָרְבָּן. דַּוְקָא שֶׁאָמַר מִקֵּץ יָמִים וְלֹא אָמַר מִקֵּץ יָמִין. וְלָכֵן כָּתוּב בְּדָנִיֵּאל (דניאל יב) וְאַתָּה לֵךְ לַקֵּץ וְתָנוּחַ וְתַעֲמֹד לְגֹרָלְךְ. אָמַר לוֹ, לְקֵץ הַיָּמִים אוֹ לְקֵץ הַיָּמִין? אָמַר לוֹ, לְקֵץ הַיָּמִין. וְקַיִן הֵבִיא מִקֵּץ הַיָּמִים."]]],[["וַיָּבֵא קַיִן מִפְּרִי הָאֲדָמָה. כְּמָא דְאַתְּ אָמֵר וּמִפְּרִי הָעֵץ. אָמַר רַבִּי אֶלְעָזָר מִפְּרִי הָאֲדָמָה כְּמָא דְאַתְּ אָמֵר, (ישעיהו ג׳:י״א) אוֹי לָרָשָׁע רָע כִּי גְמוּל יָדָיו וְגו'. (כי פרי מעלליהם יאכלו. פרי מעלליהם יאכלו דא מלאך המות יאכלו) (נ\"א גמול ידיו דא מלאך המות. יעשה לו דאתמשך) עֲלַיְיהוּ וְיִתְדַּבַּק בְּהוּ לְקָטְלָא לוֹן וּלְסָאֳבָא לוֹן. וְעַל דָּא קַיִן אַקְרִיב מִסִּטְרָא דִילֵיהּ.","וְהֶבֶל הֵבִיא גַּם הוּא מִבְּכוֹרוֹת לְאַסְגָּאָה סִטְרָא עִלָּאָה דְּאַתְיָא מִסְּטַר קְדוּשָׁתָא (ד\"א מסטרא קדישא). וּבְגִינֵי כָךְ וַיִּשַּׁע יְיָ אֶל הֶבֶל וְאֶל מִנְחָתוֹ וְאֶל קַיִן וְאֶל מִנְחָתוֹ לא שָׁעָה. לָא קַבִּיל (לון) (ד\"א ליה) קוּדְשָׁא בְּרִיךְ הוּא. וְעַל דָּא וַיִּחַר לְקַיִן מְאֹד. וַיִּפְּלוּ פָנָיו דְּהָא לָא אִתְקַבִּילוּ אַנְפּוֹי, אִנּוּן אַנְפִּין דְּסִטְרוֹי וְקַבִּיל לֵיהּ לְהֶבֶל.","וּבְגִינֵי כָךְ כָּתוּב וַיְהִי בִּהְיוֹתָם בַּשָּׂדֶה. בַּשָּׂדֶה דָּא אִתְּתָא. כְּמָא דְאַתְּ אָמֵר (דברים כ״ב:כ״ז) כִּי בַּשָּׂדֶה מְצָאָהּ, וְקַיִן קָנֵי עַל נוּקְבָא יְתֵירָה דְּאִתְיְלִידַת עִם הֶבֶל דִּכְתִיב וַתּוֹסֶף לָלֶדֶת וְהָא אִתְּמָר:","הֲלֹא אִם תֵּיטִיב שְׂאֵת כְּמָה דְאִתְּמָר. אֲבָל שְׂאֵת כְּדְאֲמַר רַבִּי אַבָּא שְׂאֵת תִּסְתַּלַּק לְעֵילָא וְלָא תֵיחוֹת לְתַתָּא. אָמַר רַבִּי יוֹסֵי הַאי מִלָּה הַשְׁתָּא אִתְּמָר וְיָאוּת הוּא. אֲבָל הָכִי שְׁמַעְנָא שְׂאֵת יְסַלַּק מִינָךְ וְיִשְׁבּוֹק לָךְ אִתְדַּבְּקוּתָא דָא דְּרוּחַ מְסָאֲבָא.","וְאִי לָא לַפֶּתַח חַטָּאת רוֹבֵץ. מַאי לַפֶּתַח דָּא דִינָא עִלָּאָה דְּאִיהוּ פִּתְחָא דְכֹלָּא כְּמָא דְאַתְּ אָמֵר (תהילים קי״ח:י״ט) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק. חַטָּאת רוֹבֵץ הַהוּא סִטְרָא דְּאִתְדַּבְּקַת בֵּיהּ וְאִתְמַשְׁכַת עֲלָךְ יְהֵא נָטִיר לָךְ לְאִתְפְּרָעָא מִנָּךְ כְּתַרְגּוּמָא.","אָמַר רַבִּי יִצְחָק, תָּא חֲזֵי, בְּשַׁעֲתָא דְּקָטִיל קַיִן לְהֶבֶל, לָא הֲוָה יָדַע הֵיךְ (נפיק) (ד\"א יפיק) נִשְׁמָתֵיהּ מִנֵּיהּ. וְהֲוָה נָשִׁיךְ לֵיהּ בְּשִׁינֵיהּ כְּחִוְיָא. וְהָא אוּקְמוּהָ חַבְרַיָא. בֵּיהּ שַׁעֲתָא לַיְיט לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא. וְהֲוָה אָזִיל לְכָל סִטְרֵי עָלְמָא, וְלָא הֲוָה אֲתַר דִּמְקַבֵּל לֵיהּ. עַד דְאַטְפַח עַל רֵישֵׁיהּ וְתָב קַמֵּי מָארֵיהּ. וְקַבִּילַת לֵיהּ אַרְעָא בְּמָדוֹרָא לְתַתָּא.","רַבִּי יוֹסֵי אָמַר אַרְעָא קַבִּילַת לֵיהּ לְמֵיהַךְ בָּהּ דִּכְתִיב וַיָּשֶׂם יְיָ לְקַיִן אוֹת. רַבִּי יִצְחָק אָמַר לָאו הָכִי. אֶלָּא לְתַתָּא קַבִּילַת לֵיהּ אַרְעָא בְּמָדוֹרָא חָדָא דִתְחוֹתָהּ דִּכְתִיב הֵן גֵּרַשְׁתָּ אוֹתִי הַיּוֹם מֵעַל פְּנֵי הָאֲדָמָה. מֵעַל פְּנֵי הָאֲדָמָה גּוֹרָשׁ. אֲבָל לְתַתָּא לָא גוֹרָשׁ.","וּבְאָן אֲתַר קַבִּילַת לֵיהּ אַרְעָא, בְּאַרְקָא. וְכָל אִנּוּן דְּדָיְירֵי תַּמָּן עֲלֵיהוֹן כְּתִיב (ירמיהו י׳:י״א) יֵאבַדוּ מֵאַרְעָא וּמִתְּחוֹת שְׁמַיָא אֵלֶּה. וְתַמָּן שַׁוֵּי מְדוֹרֵיהּ. וְהַיְינוּ דִּכְתִיב וַיֵּשֶׁב בְּאֶרֶץ נוֹד קִדְמַת עֵדֶן.","\u0003תּוֹסֶפְתָּא\u0004 כֵּיוָן דְּאָמַר קַיִן גָּדוֹל עֲוֹנִי מִנְשׂא, מָחַל לֵיהּ קוּדְשָׁא בְּרִיךָ הוּא פַּלְגוּ מֵעוֹנְשֵׁיהּ. בְּגִין דְּגָזַר עֲלֵיהּ בְּקַדְמִיתָּא ואָמַר לֵיהּ נָע וָנָד תִּהְיֶה בָאָרֶץ וְהַשְׁתָּא אִשְׁתָּאַר בְּנוֹד בִּלְחוֹדוֹי. הֲדָא הוּא דִכְתִּיב ויֵּצֵּא קַיִן מִלִּפְּנֵי ה, וגו; כְּלוֹמַר דְּכַד נָפַּק מִן קָדָם ה\"הֲוָה בְּגִין לְמֶהֱוִי נָד בְּאַרְעָא ולָא נָע.","ועוֹד אָמְרוּ כַּד נָפַּק קַיִן מִן קָדָם ה\"אָמַר לוֹ אָדָם בְּרִי מָה אִתְּעֲבִיד על דִּינָךָ. אָמַר לוֹ קַיִן אַבָּא כְּבָר אִתְּבַּשְׂרִיתּ דִּמְחַל לִי קוּדְשָׁא בְּרִיךָ הוּא בְּנוֹד בִּלְחוֹדוֹי. אָמַר לוֹ הֵיאַךָ הוּא. אָמַר לוֹ בְּגִין דְּתָּבִיתּ וְאוֹדִיתּ קַמֵּיהּ. אָמַר אָדָם וכִי דֵּין הוּא רַב וְתַּקִּיף חֵילָא דִתְּשׁוּבָה וְאֲנָא לָא יָדִיעַתּ. שְׁרָא לְשַׁבְּחָא לְמָרֵיהּ וּלְאוֹדָאָה לֵיהּ פָּתַּח ואָמַר, (תהילים צ״ב:א׳-ב׳) מִזְמוֹר שִׁיר לְיוֹם הַשַׁבָּתּ טוֹב לְהוֹדוֹתּ לַה; כְּלוֹמַר טוֹב לְשַׁבָּחָא ולְאֲתָּבָא וּלְאוֹדָאָה קַמֵּיהּ קוּדְשָׁא בְּרִיךָ הוּא. (עד כאן תוספתא)","וְאָמַר רַבִּי יִצְחָק מֵהַהִיא שַׁעֲתָא דְּקָטִיל קַיִן לְהֶבֶל, דְאִתְפְּרַשׁ (ד\"א אתפרש) אָדָם מֵאִתְּתֵיהּ. תְּרֵין רוּחִין נוּקְבִין הֲווּ אַתְיָין וּמִזְדָּוְגָן עִמֵּיהּ, וְאוֹלִיד רוּחִין וְשֵׁדִין דְּשָׁאטָן בְּעָלְמָא.","וְלָא תִּקְשֵׁי לָךְ הַאי. דְּהָא בַּר נָשׁ כַּד אִיהוּ בְּחֶלְמֵיהּ אַתְיָין רוּחִין נוּקְבִין וְחַיְיכָן עִמֵּיהּ וּמִתְחַמְּמָן מִנֵּיהּ וְאוֹלִידִין לְבָתַר. וְאִלֵּין אִקְרוּן נִגְעֵי בְּנֵי אָדָם. וְלָא מִתְהַפְּכָן אֶלָּא לִדְיוֹקְנֵי בְּנֵי נָשָׁא. וְלֵית לוֹן שַׂעֲרִין בְּרֵישָׁא. וְעַל דָּא כְּתִיב בִּשְׁלֹמֹה (שמואל ב ז׳:י״ד) וְהוֹכַחְתִּיו בְּשֵׁבֶט אֲנָשִׁים וּבְנִגְעֵי בְּנֵי אָדָם. וְאֲפִילּוּ כְּהַאי גַוְונָא רוּחִין דְּכוּרִין אַתְיָין לִנְשֵׁי עָלְמָא וּמִתְעַבְּרָן מִנַּיְיהוּ וְאוֹלִידָן רוּחִין. וְכֻלְהוֹן נִגְעֵי בְּנֵי אָדָם אִקְרוּן."],[[0,"ויבא קין מפרי האדמה כד\"א ומפרי העץ:","לומד גזירה שוה, מה שם הוא בעץ הדעת, שהיא מבחינת הנחש הרע, אף כאן הביא קרבנו מבחינת הנחש הרע. \u0003אר\"א מפרי האדמה, כד\"א אוי לרשע רע וגו' כי פרי מעלליהם יאכלו, פרי מעלליהם יאכלו דא מלאך המות.\u0004 (ח\"ג) ר\"א לומד גזירה שוה מהכתוב פרי מעלליהם יאכלו, מה שם המדובר הוא במלאך המות, כי המלאך המות הוא פרי מעלליהם של הרשעים. כי לולא החטא לא היה בא לעולם. \u0003יאכלו, דאתמשך עלייהו ויתדבק בהו לקטלא לון ולסאבא לון,\u0004 יאכלו פירושו, שהוא נמשך עליהם ומתדבק בהם להמית אותם ולטמא אותם. \u0003ועל דא, קין אקריב מסטרא דיליה\u0004 וע\"כ גם מפרי האדמה, הנאמר כאן, יורה שקין הקריב מהצד שלו, מבחינת הנחש ומלאך המות."],[0,"והבל הביא גם הוא מבכורות, לאסגאה סטרא עלאה דאתיא מסטר קדושתא:","והבל הביא גם וגו', המלה גם, הוא לרבות את הצד העליון דהיינו בחינת מחזה ולמעלה, הבא מצד הקדוש. \u0003ובגיני כך וישע ה' אל הבל ואל מנחתו ואל קין וגו' לא קביל ליה קב\"ה,\u0004 ומשום זה וישע ה' אל הבל וגו' משום שהיה מצד הקדושה, אבל ואל קין ומנחתו לא שעה, לא קבל הקב\"ה את קרבנו, משום שהיה מהצד הטמא. \u0003ועל דא ויחר לקין מאד ויפלו פניו, דהא לא אתקבילו אנפוי, אינון אנפוי דסטרוי, וקביל ליה להבל,\u0004 וע\"כ ויחר לקין מאד מאד ויפלו פניו, כי לא נתקבל פניו שהם הפנים של הצד שלו אלא שקיבל את הבל."],[2,"ובגיני כך כתיב ויהי בהיותם בשדה, בשדה דא אתתא, כד\"א כי בשדה מצאה:","ומשום זה כתוב ויהי בהיותם בשדה, בשדה יורה אשה, כמו שאתה אומר, בשדה מצאה, שהמדובר הוא שם באשה, אף בשדה שבכאן המדובר הוא באשה. \u0003וקין קני על נוקבא יתירה דאתילידת עם הבל, דכתיב ותוסף ללדת, והא אתמר.\u0004 וקין קנה את הבל על נוקבא יתרה שנולדה עם הבל שכתוב ותוסף ללדת את אחיו \u0003את\u0004 הבל, ב' פעמים את באים לרבות, ב' נוקבות שנולדו עם הבל."],[2,"","ולהבין הדברים, צריכים לידע ענין ההפרש של נשמת קין והבל על בורים. ודע, שנשמות קין והבל, היו צריכים להיות נשמה אחת כמו שת, אלא מתוך שאדם נזדווג עם חוה מטרם שעשה תשובה על חטא דעצה\"ד, והיה הזוהמא של הנחש דבוקה בהם, ע\"כ הוליד רק חציה השמאלי של הנשמה, בפירוד מצד הימין, ששם המקום של זוהמא דחויא, וע\"כ נקרא שמו קין, כמ\"ש ר\"י (לעיל באות של\"ד) \u0003קין קינא דמדורין בישין דאתו מסטרא דמסאבא לעלמא,\u0004 דהיינו כמבואר, שצד השמאל של הנשמה הוא המקום והמדור של זוהמא דחויא. אבל בצד הימין של הנשמה אין לו שום מקום להאחז בו. וע\"כ אח\"כ שעשה תשובה על חטאו, הוליד אז נשמת הבל (כנ\"ל באות של\"א), שהוא הצד הימין של אותה הנשמה, שאין שם מקום לזוהמא דחויא."],[2,"","וכבר ידעת שכל נשמה נמשכת ברזא דתלת נקודין חולם שורק חירק, בסוד השם אלקים. אשר נקודת \u0003החולם\u0004 ה\"ס אתוון מ\"י דאלקים והוא צד ימין. ונקודת \u0003השורק\u0004 ה\"ס אתוון \u0003אל\"ה\u0004 דאלקים וה\"ס צד שמאל. וקו אמצעי יוצא על מסך דנקודת \u0003החירק\u0004 המיחד אותיות מ\"י אל\"ה זה בזה ואשתלם שמא דאלקים. ומתחילה יוצא סדר הזה בבינה, ואח\"כ בזו\"ן, ואח\"כ בנשמות, (כנ\"ל בפ' לך דף ד' ד\"ה פירוש ע\"ש) גם נודע שמשורשם נבחנים אתוון \u0003מ\"י\u0004 לבחינת ג\"ר ואתוון \u0003אל\"ה\u0004 לבחינת ו\"ק. אשר מבחינת פרצוף, נבחן החלק שמחזה ולמעלה לבחינת \u0003מ\"י,\u0004 ששם בחינת ג\"ר דגוף הפרצוף. והחלק שמחזה ולמטה נבחן לבחינת \u0003אל\"ה\u0004 להיותו בחינת ו\"ק דגוף הפרצוף. ולפי\"ז נמצא אשר הבל להיותו בחינת \u0003מ\"י\u0004 הוא בחינת מחזה ולמעלה. וקין בהיותו בחינת \u0003אל\"ה,\u0004 הוא מחזה ולמטה."],[2,"","גם ידעת, שמכח מיתוקה של המלכות בהבינה והכללתן זו בזו, יצאו ד' מלכיות, ב' מלכיות הן מבחינות בינה ומלכות שבנקודת הבינה, וב' מלכיות הן מבחינת בינה ומלכות שבנקודת המלכות. וכבר דברנו מזה לעיל (דף קפ\"ד ד\"ה לזמנין גוברין ולעיל דף ע\"ח ד\"ה וזה אמרו ע\"ש) ובגלוי אין יותר מג' מלכיות, שב' מלכיות משמשות מחזה ולמעלה של פרצוף המלכות, שהם בינה ומלכות דבינה, ואחת מחזה ולמטה שלה, דהיינו בחינת בינה דמלכות לבדה, אבל מלכות דמלכות להיותה מדת הדין מבחינת המלכות דצמצום א', שאינה ראויה לקבל לתוכה אור ישר רק או\"ח לבד, ע\"כ נגנזה. שז\"ס מ\"ש לעיל (ב\"א דף פ\"ו ד\"ה וזה) שאין פני אדם מחזה ולמטה דזו\"ן. ומטעם מלכות הרביעית הזאת שנגנזה, נעשתה הנוקבא לבחינת עץ הדעת טוב ורע כנ\"ל (בהקדמת הזהר דף קכ\"ד אות קכ\"ג ד\"ה אמאי) \u0003לא זכי הא רע,\u0004 שפירושו, שאם ממשיך מקום הזווג למחזה ולמטה, הוא מגלה בזה את המלכות הרביעית שנגנזה, אשר בהתגלותה תיכף מסתלקים האורות, כנ\"ל (בפ' נח דף ק\"ח ד\"ה פירוש)."],[2,"","ולפי זה נמצא, שהבל, אשר הוא בחינת \u0003מ\"י\u0004 ובחינת מחזה ולמעלה כנ\"ל, יש לו ב' מלכיות, שה\"ס בינה ומלכות דבינה, דהיינו שיצאו עם נשמתו ב' נוקבין, המרומזות בב\"פ \u0003את,\u0004 שבהכתוב ותוסף ללדת את אחיו את הבל. אבל קין להיותו בחינת \u0003אל\"ה,\u0004 ובחינת מחזה ולמטה, אין לו אלא מלכות אחת, שהיא בחינת בינה דמלכות, אבל מלכות הד' שהיא מלכות דמלכות, חסרה לו, וז\"ס שעם נשמת קין יצאה רק נוקבא אחת, דהיינו רק מלכות הג' בלבדה."],[2,"","וזה אמרו \u0003בשדה, דא אתתא וכו', וקין קני על נוקבא יתירה דאתילידת עם הבל,\u0004 דהיינו שרצה לגלות ולעשות זווג על מלכות הד' החסרה לו, ויהיו לו ב' נוקבין כמו שיש להבל. והוא ממש כמו החטא של עץ הדעת, שהנחש פיתה אותם לעשות הזווג מחזה ולמטה כדי שיוכל להמשיך האורות ממעלה למטה (כנ\"ל בהקדמת הזהר דף קצ\"ט אות ר\"י), שמחמת זה נגלתה מלכות הד' שנסתלקה מחמתה כל האורות, ונקנסה עליו המיתה. כי הסתלקות אור החיים הוא מיתה. כמ\"ש לעיל (דף ק\"פ ד\"ה ועל) וז\"ש לעיל (דף קצ\"א ד\"ה ודאי קין ברא) שהריגת הבל היא ענין אחד עם החטא דעצה\"ד, כי אף הוא רצה לגלות הזווג מחזה ולמטה, על מלכות הד' וכיון שנגלתה מלכות הזאת תכף נסתלקו האורות מכללות נשמות קין והבל, שהם בחינת הג\"ר, והכלים שהם בחינת ו\"ק נפלו לקליפות. אבל אורות אינם נופלים לקליפות אלא שמסתלקים לשורשם העליון. ונמצא אשר הבל, שהוא בחינת ג\"ר נסתלק לשורשו ומת. וקין שהיה רק בחינת ו\"ק נפל לקליפות, באופן שכל ההפרש מהריגת הבל לחטא דעצה\"ד, הוא, כי אדם היה כלל כל הנשמות ע\"כ נגע חטאו לכל העולם. וקין והבל נגע החטא לבחינת נשמתם בלבד."],[3,"הלא אם תיטיב שאת, כמה דאתמר, אבל שאת כדאמר רבי אבא שאת תסתלק לעילא ולא תיחות לתתא:","הכ' הלא אם תיטיב שאת, הוא כמו שנתבאר, אבל המלה \u0003שאת,\u0004 הוא כמו שאמר רבי אבא \u0003שאת\u0004 פירושו, שתתנשא לעילא ולא תרד למטה, כלומר שתמשיך האורות בבחינת ממטה למעלה, ואל תמשיך עוד האורות ממעלה למטה, שבזה הרג להבל כנ\"ל בדיבור הסמוך."],[3,"א\"ר יוסי האי מלה השתא אתמר, ויאות הוא:","אר\"י דבר זה עתה נאמר, כלומר שהוא חידוש, ויפה הוא. \u0003אבל הכי שמענא, שאת, יסלק מינך וישבוק לך אתדבקותא דא דרוח מסאבא.\u0004 אבל כך שמעתי, שאת פירושו, הסרה וסליחה, שאמר לו הקב\"ה, אם תיטיב, יסור ממך ויסלח לך דבקות הזה של רוח הטומאה."],[4,"ואם לא, לפתח חטאת רובץ. מאי לפתח, דא דינא עלאה, דאיהו פתחא דכלא, כד\"א פתחי לי שערי צדק,","ואם לא תיטיב לפתח חטאת רובץ. ושואל, \u0003לפתח,\u0004 מה פירושו. ואומר, זהו דין העליון הדין של המלכות, שהוא הפתח לכל, כמו שאתה אומר, פתחו לי שערי צדק. פירוש, \u0003צדק\u0004 הוא שם המלכות, ושערי צדק הם הדינים, שאין אדם יוכל לבא אל המלכות, אם אינו מהפך את הדינים הללו שבה לשערים, שזסו\"ה צדיקים יבואו בו. כלומר אותם הדינים, שהרשעים מתרחקים על ידיהם, נעשים בשביל הצדיקים לשערים, שמתדבקים על ידיהם. וכבר נתבאר ענין זה לעיל(הקסה\"ז דף קכ\"ב אות קכ\"א) ע\"ש. וזה שמשמיענו הכתוב בהמלה \u0003לפתח,\u0004 אשר מה שחטאת רובץ על המלכות, אע\"פ שהיא מקור כל העונשין, מ\"מ סוף סוף, אם תעשה תשובה, יתהפך החטאת ויהיה לפתח. כמ\"ש שם. \u0003חטאת רובץ, ההוא סטרא דאתדבקת ביה ואתמשכת עלך, יהא נטיר לך, לאתפרעא מנך כתרגומא,\u0004 חטאת רובץ, פירושו, שאמר לו הקב\"ה, אותו הצד שהתדבקת בו ונמשך עליך, יהיה נטר אותך להפרע ממך. כתרגומו. ושיעור הכתוב, אם תיטיב שאת, דהיינו שיסור ממנו דבקות הזה של רוח הטומאה שנתדבק בו מחמת חטאו. ואם לא תיטיב לפתח חטאת רובץ, דהיינו אותו רוח הטומאה שנתדבק בו מחמת חטאו הוא עצמו יפרע ממך."],[5,"אמר רבי יצחק, ת\"ח בשעתא דקטיל קין להבל לא הוה ידע איך נפק נשמתיה מניה, והוה נשיך ליה בשיניה כחויא:","אר\"י, בוא וראה, בשעה שקין הרג להבל, לא היה יודע איך תצא הנשמה ממנו, כלומר, שלא היה יודע, שעל ידי מעשיו שעושה יוציא מן הבל את נשמתו. וימות. והיה נושך אותו בשיניו, כנחש."],[5,"","פירוש. כי נתבאר שקנא אותו על נוקבא יתירה, שפירושו שרצה להמשיך האורות מלמעלה למטה, ולגלות את מלכות הרביעית החסרה בבחינת מחזה ולמטה כמ\"ש לעיל. אבל לא ידע שעי\"ז תתגבר מדת הדין ויפסק הזווג גם מחזה ולמעלה ויסתלק החיות מהבל וימות, כנ\"ל, אלא אדרבא חשב שגם הבל יהנה ממעשיו. וז\"ש \u0003והוה נשיך ליה בשיניה כחויא,\u0004 שהיה נושך אותו בשיניו כמו נחש הקדמוני והרגו. פירוש. כי כל הנמשך נמשך דרך הפה. אבל הנמשך בקדושה נמשך מכח השפתים, שהם המסך שבפה, שה\"ס זווג דנשיקין הממשיך השפע ממדרגה למדרגה. והנמשך שלא בקדושה, כמעשה נחש הקדמוני. נמשך מכח השנים, כלומר, שחסר שם תקון המסך בכלי מלכות, הנקרא שפתים, והשפע נמשך ממעלה למטה שזה נבחן לנשיכה. שבדרך זה הביא הנחש המיתה לעולם. ונודע שמעשה קין היה כחטא העץ הדעת, (כנ\"ל דף קצ\"ד ד\"ה וזה) שגם הוא החליף הנשיקה לנשיכה, כי משך השפע בלי מסך ממעלה למטה, שעי\"ז נסתלק נשמת הבל כמ\"ש שם, הרי שקין נשך אותו בשיניו כמעשה נחש הקדמוני, ומכח זה הרגו. \u0003ביה שעתא לייט\u0004 וכו': בו בשעה קללו הקב\"ה, והיה הולך לכל רוחות העולם, ולא מצא מקום שיקבל אותו, עד שהכה עצמו על ראשו, ושב לפני רבונו, ואז קבלה הארץ אותו במדור התחתון. כלומר שתשובתו לא היתה שלמה. וע\"כ לא קבלו הארץ שלנו."],[6,"ר\"י אמר ארעא","וכו': ר' יוסי אמר, הארץ עצמה קבלה אותו שילך עליה, שכתוב, וישם ה' לקין אות. שמשמע שהקב\"ה קבל את תשובתו. וע\"כ חזרה וקבלה אותו הארץ. וחולק על ר' יצחק, שאמר שרק מדור התחתון קבלו, מפני שתשובתו לא היתה שלמה. \u0003ר' יצחק אמר לאו הכי\u0004 וכו': והשיב לו רבי יצחק, שאינו כן, אלא הארץ קבלה אותו למטה במדור אחד שמתחתיה, כי כתוב, הן גרשת אותי היום מעל פני האדמה, שמשמע, מעל פני האדמה גורש, אבל למטה מאדמה לא גורש. הרי שמדור תחתון שמתחת האדמה קבל אותו."],[7,"ובאן אתר קבילת","וכו': ושואל באיזה מקום קבלו אותו הארץ, ומשיב, שהוא ב\u0003ארקא.\u0004 היא אחת מז' ארצות (עי' דף כ' אות ל\"ו) וכל אלו הדרים שם, כתוב עליהם, יאבדו מארעא ומתחות שמיא אלה, (כנ\"ל בהקדמת הזהר דף קמ\"ט אות קנ\"א) ושמה שם מקום מדורו, וזה שכתוב שם וישב בארץ נוד קדמת עדן. שהכונה היא על מדור התחתון הנקרא ארקא. ונקרא בשם \u0003נוד,\u0004 מפני שיש להיושבים שם שני ראשים, שפירושו, שהם מתנדנדים לכאן ולכאן פעם לחשך ופעם לאור. (כנ\"ל בהקדמת הזהר דף קנ\"ג ד\"ה ועל דא) עש\"ה."],[8,"כיון דאמר קין","וכו': אחר שאמר קין גדול עוני מנשוא, דהיינו שהתורה ועשה תשובה, מחל לו הקב\"ה החצי מן העונש. מאחר שבתחילה גזר עליו, ואמר לו, נע ונד תהיה בארץ, הוא נשאר עתה ב\u0003נוד\u0004 בלבדו. וזהו שכתוב, ויצא קין מלפני ה' וישב בארץ \u0003נוד.\u0004 כלומר, כאשר יצא מלפני ה', היה כדי להיות \u0003נד\u0004 בארץ ולא \u0003נע.\u0004 כי נמחל לו החצי מהעונש."],[8,"","פירוש. כי הגם שחטאו של קין היתה במלכות דמדת הדין שגילה כנ\"ל, מ\"מ כיון שכבר נמתקו המלכות והבינה זב\"ז, נפגמה גם הבינה על ידו. ולפיכך נענש \u0003בנע ונד\u0004 תהיה בארץ: \u0003נענוע\u0004 מצד המלכות, \u0003ונדנוד\u0004 מצד הפגם שבבינה. ואחר שעשה תשובה, נמחל לו הפגם מהמלכות דהיינו \u0003הנענוע.\u0004 ונשאר לו הפגם שבבינה, שהוא הנדנוד. כי תשובתו לא היתה שלמה בכל צרכה."],[9,"ועוד אמרו","וכו' : כאשר יצא קין מלפני ה', אמר לו אדם, בני מה נעשה בדינך. אמר לו קין: אבא, כבר נתבשרתי שמחל לי הקב\"ה להיות \u0003בנוד\u0004 בלבד. שאל אותו איך זכית לזה. אמר לו משום שעשיתי תשובה והתודיתי לפניו. אמר אדם, וכי כל כך גדול וחזק כח התשובה ואני לא ידעתי. התחיל לשבח אל רבונו ולהתודות לפניו פתח ואמר מזמור שיר ליום השבת וגו', כלומר טוב לשבח ולשוב ולהתודות לפני הקב\"ה."],[10,"ואמר רבי יצחק","וכו': ואר\"י, מאותה השעה שהרג קין את הבל, נפרד אדם מאשתו, וב' רוחות נקבות היו באות ומזדווגות עמו, והוליד רוחות ושדים המשוטטים בעולם. ולהיותם שתים, הוא מטעם, כי הזנות הוא מקליפות הימין, שע\"כ הן מצחקות, אבל בסוף הן מיסרות ומענישות האדם, שהוא בחינת שמאל. וע\"כ היו שתים, אחת מקליפת הימין והשניה מקליפת השמאל."],[11,"ולא תקשי לך האי","וכו': ולא יקשה לך להבין זה, כי גם בן אדם כשהוא בחלומו, באות רוחות נקבות ומצחקות עמו ומתחממות ממנו, ואחר כך מולידות. ואלו התולדות נקראים נגעי בני אדם, ואינם מתהפכים לשום צורה, אלא לצורות בני אדם. ואין להם שער בראשם כי אותם התולדות הן בחינת קליפת הימין, ושערות, מבחינת שמאל הם באים. ועל אלו כתוב בשלמה, והוכחתיו בשבט אנשים ובנגעי בני אדם. \u0003ואפילו כהאי גוונא\u0004 וכו': ויש אפילו כאופן הזה, שרוחות זכרים באים להנשים שבעולם, בחלומן, והנשים מתעברות מהם ומולידות רוחות, וכולם נגעי בני אדם נקראים."]],[[0,"","וַיָּבֵא קַיִן מִפְּרִי הָאֲדָמָה, כְּמוֹ שֶׁנֶּאֱמַר וּמִפְּרִי הָעֵץ. אָמַר רַבִּי אֶלְעָזָר, מִפְּרִי הָאֲדָמָה, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה ג) אוֹי לְרָשָׁע רָע כִּי גְמוּל יָדָיו וְגוֹ' (כי פרי מעלליהם יאכלו, פרי מעלליהם יאכלו זה מלאך המות יאכלו). (גמול ידיו זה מלאך המות, יעשה לו שנמשך) עֲלֵיהֶם וְיִדְבַּק בָּהֶם לַהֲרֹג אוֹתָם וּלְטַמֵּא אוֹתָם. וְעַל זֶה קַיִן הִקְרִיב מִצִּדּוֹ."],[1,"","וְהֶבֶל הֵבִיא גַם הוּא מִבְּכֹרוֹת - לְרַבּוֹת הַצַּד הָעֶלְיוֹן שֶׁבָּא מִצַּד הַקְּדֻשָּׁה (מצד קדוש), וְלָכֵן וַיִּשַׁע ה' אֶל הֶבֶל וְאֶל מִנְחָתוֹ וְאֶל קַיִן וְאֶל מִנְחָתוֹ לֹא שָׁעָה. לֹא קִבֵּל אוֹתָם (אותו) הַקָּדוֹשׁ בָּרוּךְ הוּא. וְלָכֵן וַיִּחַר לְקַיִן מְאֹד וַיִּפְּלוּ פָּנָיו. שֶׁהֲרֵי לֹא הִתְקַבְּלוּ פָנָיו, אוֹתָם פָּנִים שֶׁל צִדּוֹ, וְקִבֵּל אֶת הֶבֶל."],[2,"","וְלָכֵן כָּתוּב וַיְהִי בִּהְיוֹתָם בַּשָּׂדֶה. בַּשָּׂדֶה זוֹ הָאִשָּׁה, כְּמוֹ שֶׁנֶּאֱמַר (דברים כב) כִּי בַּשָּׂדֶה מְצָאָהּ. וְקַיִן קִנֵּא עַל הַנְּקֵבָה הַיְתֵרָה שֶׁנּוֹלְדָה עִם הֶבֶל, שֶׁכָּתוּב וַתֹּסֶף לָלֶדֶת, וַהֲרֵי נֶאֱמַר."],[3,"","הֲלוֹא אִם תֵּיטִיב שְׂאֵת, כְּמוֹ שֶׁנֶּאֱמַר. אֲבָל שְׂאֵת כְּמוֹ שֶׁאָמַר רַבִּי אַבָּא, שְׂאֵת תַּעֲלֶה לְמַעְלָה וְלֹא תֵרֵד לְמַטָּה. אָמַר רַבִּי יוֹסֵי, דָּבָר זֶה כָּעֵת נֶאֱמָר וְנָאֶה הוּא, אֲבָל כָּךְ שָׁמַעְתִּי, שְׂאֵת יַעֲלֶה מִמְּךְ וְיַעֲזֹב לְךְ הִדָּבְקוּת זוֹ שֶׁל רוּחַ הַטֻּמְאָה."],[4,"","וְאִם לֹא - לַפֶּתַח חַטָּאת רֹבֵץ. מַה זֶּה לַפֶּתַח? זֶה הַדִּין הָעֶלְיוֹן שֶׁהוּא הַפֶּתַח שֶׁל הַכֹּל, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קיח) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק. חַטָּאת רֹבֵץ - אוֹתוֹ הַצַּד שֶׁנִּדְבְּקָה בּוֹ וְנִמְשָׁךְ עָלֶיךְ, יִשְׁמֹר אוֹתְךְ לְהִפָּרַע מִמְּךְ, כְּתַרְגּוּמוֹ."],[5,"","אָמַר רַבִּי יִצְחָק, בֹּא רְאֵה, בְּשָׁעָה שֶׁקַּיִן הָרַג אֶת הֶבֶל, לֹא יָדַע אֵיךְ יוֹצִיא (יוצאת) נִשְׁמָתוֹ מִמֶּנּוּ, וְהָיָה נוֹשֵׁךְ אוֹתוֹ בְּשִׁנָּיו כְּנָחָשׁ, וַהֲרֵי בֵּאֲרוּהָ הַחֲבֵרִים. בְּאוֹתָהּ הַשָּׁעָה קִלְּלוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהָיָה הוֹלֵךְ לְכָל צִדְדֵי הָעוֹלָם, וְלֹא הָיָה מָקוֹם שֶׁמְּקַבֵּל אוֹתוֹ, עַד שֶׁטָּפַח עַל רֹאשׁוֹ וְשָׁב לִפְנֵי רִבּוֹנוֹ, וְהָאָרֶץ קִבְּלָה אוֹתוֹ בַּמָּדוֹר הַתַּחְתּוֹן לְמַטָּה."],[6,"","רַבִּי יוֹסֵי אָמַר, הָאָרֶץ קִבְּלָה אוֹתוֹ לָלֶכֶת בָּהּ, שֶׁכָּתוּב וַיָּשֶׂם ה' לְקַיִן אוֹת. רַבִּי יִצְחָק אָמַר, לֹא כָּךְ, אֶלָּא לְמַטָּה קִבְּלָה אוֹתוֹ הָאָרֶץ בְּמָדוֹר אֶחָד שֶׁתַּחְתֶּיהָ, שֶׁכָּתוּב הֵן גֵּרַשְׁתָּ אֹתִי הַיּוֹם מֵעַל פְּנֵי הָאֲדָמָה. מֵעַל פְּנֵי הָאֲדָמָה גֹּרַשׁ, אֲבָל לְמַטָּה לֹא גֹרַשׁ."],[7,"","וּבְאֵיזֶה מָקוֹם קִבְּלָה אוֹתוֹ הָאֲדָמָה? בְּאַרְקָא, וְעַל כָּל אֵלֶּה שֶׁדָּרִים שָׁם כָּתוּב (ירמיה י) יֹאבְדוּ מִן הָאָרֶץ וּמִתַּחַת הַשָּׁמַיִם הָאֵלֶּה. וְשָׁם שָׂם אֶת מְדוֹרוֹ, וְהַיְנוּ שֶׁכָּתוּב וַיֵּשֶׁב בְּאֶרֶץ נוֹד קִדְמַת עֵדֶן."],[8,"","כֵּיוָן שֶׁאָמַר קַיִן גָּדוֹל עֲוֹנִי מִנְּשׂוֹא, מָחַל לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא חֲצִי מֵעָנְשׁוֹ. מִשּׁוּם שֶׁגָּזַר עָלָיו בַּהַתְחָלָה וְאָמַר לוֹ נָע וָנָד תִּהְיֶה בָאָרֶץ, וְעַכְשָׁו נִשְׁאָר בְּנוֹד בִּלְבַדּוֹ. זֶהוּ שֶׁכָּתוּב וַיֵּצֵא קַיִן מִלִּפְנֵי ה' וְגוֹ'. כְּלוֹמַר, שֶׁכְּשֶׁיָּצָא מִלִּפְנֵי ה' הָיָה בִּשְׁבִיל לִהְיוֹת נָד בָּאָרֶץ וְלֹא נָע."],[9,"","וְעוֹד אָמְרוּ, כְּשֶׁיָּצָא קַיִן מִלִּפְנֵי ה', אָמַר לוֹ אָדָם: בְּנִי, מַה נַּעֲשָׂה עַל דִּינְךְ? אָמַר לוֹ קַיִן: אַבָּא, כְּבָר הִתְבַּשַּׂרְתִּי שֶׁמָּחַל לִי הַקָּדוֹשׁ בָּרוּךְ הוּא בְּנוֹד בִּלְבַדּוֹ. אָמַר לוֹ: הֵיאַךְ הוּא? אָמַר לוֹ: מִשּׁוּם שֶׁחָטָאתִי וְהוֹדֵיתִי לְפָנָיו. אָמַר אָדָם: וְכִי זֶהוּ גֹּדֶל וְחֹזֶק כֹּחַ הַתְּשׁוּבָה וַאֲנִי לֹא יָדַעְתִּי!? הִתְחִיל לְשַׁבֵּחַ לְרִבּוֹנוֹ וּלְהוֹדוֹת לוֹ. פָּתַח וְאָמַר (תהלים צב) מִזְמוֹר שִׁיר לְיוֹם הַשַּׁבָּת טוֹב לְהוֹדוֹת לַה'. כְּלוֹמַר, טוֹב לְשַׁבֵּחַ וְלָשׁוּב וּלְהִתְוַדּוֹת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. עד כאן התוספתא."],[10,"","וְאָמַר רַבִּי יִצְחָק, מֵאוֹתָהּ שָׁעָה שֶׁהָרַג קַיִן אֶת הֶבֶל, שֶׁנִּפְרַד (נפרד) אָדָם מֵאִשְׁתּוֹ, שְׁתֵּי רוּחוֹת נְקֵבוֹת הָיוּ בָּאוֹת וּמִזְדַּוְּגוֹת עִמּוֹ, וְהוֹלִיד רוּחוֹת וְשֵׁדִים שֶׁמְּשׁוֹטְטִים בָּעוֹלָם."],[11,"","וְזֶה לֹא יַקְשֶׁה לְךְ, שֶׁהֲרֵי בֶּן אָדָם כְּשֶׁהוּא בַּחֲלוֹמוֹ, בָּאוֹת רוּחוֹת נְקֵבוֹת וְצוֹחֲקוֹת עִמּוֹ וּמִתְחַמְּמוֹת מִמֶּנּוּ וּמוֹלִידוֹת אַחַר כָּךְ, וְאֵלֶּה נִקְרָאִים נִגְעֵי בְּנֵי אָדָם, וְלֹא מִתְהַפְּכִים אֶלָּא לִדְמֻיּוֹת בְּנֵי אָדָם, וְאֵין לָהֶם שְׂעָרוֹת בָּרֹאשׁ. וְעַל זֶה כָּתוּב בִּשְׁלֹמֹה (שמואל ב ז) וְהוֹכַחְתִּיו בְּשֵׁבֶט אֲנָשִׁים וּבְנִגְעֵי בְּנֵי אָדָם. וַאֲפִלּוּ כְּמוֹ זֶה רוּחוֹת זְכָרִים בָּאִים לִנְשׁוֹת הָעוֹלָם, וְהֵן מִתְעַבְּרוֹת מֵהֶם וּמוֹלִידוֹת רוּחוֹת. וְכֻלָּם נִקְרָאִים נִגְעֵי בְּנֵי אָדָם."]]],[["בָּתַר מְאָה וּתְלָתִין שְׁנִין אִתְלַבַּשׁ אָדָם בְּקִינוּיָא וְאִתְחַבַּר בְּאִתְּתֵיהּ וְאוֹלִיד בַּר וּקְרָא שְׁמֵיהּ שֵׁ\"ת. רָזָא דְּסוֹפָא דְּאַתְוָון בְּקִיטְרֵי גְלִיפָן. רַבִּי יְהוּדָה אָמַר רָזָא דְרוּחָא דְּאִתְאֲבִיד דְּאִתְלַבַּשׁ בְּגוּפָא (דארעא) אָחֳרָא בְּעָלְמָא הֲדָא הוּא דִכְתִיב כִּי שָׁת לִי אֱלהִים זֶרַע אַחֵר תַּחַת הֶבֶל.","וְאָמַר רַבִּי יְהוּדָה כְּתִיב וַיּוֹלֶד בִּדְמוּתוֹ (עי' בסי' ט) כְּצַלְמוֹ מַשְׁמַע דִּבְנִין אָחֳרָנִין לָא הֲווּ (בדמותו כצלמו ומלה דא הוא) בְּדִיוּקְנָא דִילֵיהּ. וְדָא בִּדְמוּתוֹ כְּצַלְמוֹ בְּתִיקוּנָא דְגוּפָא וּבְתִיקוּנָא דְּנַפְשָׁא בְּאֹרַח מֵישָׁר. (נ\"א ומלה דא הוא כמה דאתמר. ואמר רבי אבא משמיה דרבי ייסא) כְּמָה דְּאָמַר רַבִּי שִׁמְעוֹן מִשְׁמֵיהּ דְּרַב יֵיבָא סָבָא בְּנִין אָחֳרָנִין בְּאִתְדַבְּקוּתָא דְּזוּהֲמָא דְּנָחָשׁ וְהַהוּא דְּרָכִיב בֵּיהּ דְּאִיהוּ סמאל הֲווּ. וּבְגִינֵי כָךְ לָא הֲוָה בְּדִיוּקְנָא דְּאָדָם. וְאִי תֵימָא הָא אֲמַרְתְּ דְּהֶבֶל מִסִּטְרָא אָחֳרָא הֲוָה. הָכִי הוּא. אֲבָל תַּרְוַויְיהוּ לָא הֲווּ בְּדִיוּקְנָא דִּלְתַתָּא.","אָמַר (ד\"א ליה) רַבִּי יוֹסֵי וְהָא כְּתִיב וְהָאָדָם יָדַע אֶת חַוָּה אִשְׁתּוֹ וַתַּהַר וַתֵּלֶד אֶת קַיִן. וְלָא (ד\"א אמר ליה הכי הוא. אבל תרוויהו לא הוו בדיוקניה. דלא) כְּתִיב וַיּוֹלֶד אֶת קַיִן. וְאֲפִילּוּ בְּהֶבֶל לָא כְּתִיב וַיּוֹלֶד אֶלָּא וַתּוֹסֶף לָלֶדֶת אֶת אָחִיו אֶת הָבֶל. וְדָא הוּא רָזָא דְמִלָּה. אֲבָל בְּהַאי מַה כְּתִיב, וַיּוֹלֶד בִּדְמוּתוֹ כְּצַלְמוֹ.","רַבִּי שִׁמְעוֹן אָמַר מְאָה וּתְלָתִין שְׁנִין אִתְפְּרַשׁ אָדָם מֵאִתְּתֵיהּ. וְכָל אִנּוּן מְאָה וּתְלָתִין שְׁנִין הֲוָה אוֹלִיד רוּחִין וְשֵׁדִין בְּעָלְמָא. בְּגִין הַהוּא חֵילָא דְזוּהֲמָא דְּהֲוָה שָׁאִיב בֵּיהּ. כֵּיוָן דְּחֲסִיל מִנֵּיהּ הַהוּא זוּהֲמָא, תָּב וְקַנִּי (דאעדי) לְאִנְתְּתֵיהּ וְאוֹלִיד בַּר. כְּדֵין כְּתִיב וַיּוֹלֶד בִּדְמוּתוֹ כְּצַלְמוֹ.","תָּא חֲזֵי, כָּל בַּר נָשׁ דְּאֲזִיל לִסְטַר שְׂמָאלָא וְסָאִיב אָרְחוֹי, כָּל רוּחֵי מְסָאֲבֵי מָשִׁיךְ עַל גַּרְמֵיהּ וְרוּחַ מְסָאָב אִתְדָּבַּק בֵּיהּ וְלָא אַעֲדֵי מִנֵּיהּ. וְאִתְדַּבְּקוּתָא (דיליה) דְּהַהוּא רוּחָא מְסָאָב הֲוֵי בְהַאי בַּר נָשׁ וְלָא בְּאָחֳרָא. וּבְגִינֵי כָךְ אִתְדַּבְּקוּתָא דִּלְהוֹן לָאו אִיהוּ אֶלָּא בְּאִנּוּן דְּמִתְדַּבְּקִין בְּהוּ. זַכָּאִין אִנּוּן צַדִּיקַיָא דְּאָזְלֵי בְּאֹרַח מֵישָׁר וְאִנּוּן זַכָּאֵי קְשׁוֹט וּבְנֵיהוֹן זַכָּאִין בְּעָלְמָא וְעֲלַיְיהוּ כְּתִיב, (משלי ב׳:כ״א) כִּי יְשָׁרִים יִשְׁכְּנוּ אָרֶץ.","אָמַר רַבִּי חִיָּיא מַאי דִכְתִיב וַאֲחוֹת תּוּבַל קַיִן נַעֲמָה. מַאי אִירְיָא הָכָא דְּקָאֲמַר קְרָא דִּשְׁמָהּ נַעֲמָה. אֶלָא בְּגִין דְּטָעֲיָין בְּנֵי נָשָׁא אֲבַתְרָהּ וְאֲפִילּוּ רוּחִין וְשֵׁדִין. רַבִּי יִצְחָק אָמַר אִנּוּן בְּנֵי הָאֱלהִים עַזָּא וַעֲזָאֵל טָעוּ בַּתְרָהּ.","רַבִּי שִׁמְעוֹן אָמַר אִמָּן שֶׁל שֵׁדִים הֲוַת. דְּמִסִּטְרָא דְקַיִן נָפְקַת. וְהִיא אִתְמַנַּת עַל לֵילְיָא (עם לילית) בְּאַסְכְּרָה דְּרַבְיֵי. אָמַר לֵיהּ רַבִּי אַבָּא וְהָא אָמַר מַר דְּהִיא אִתְמַנַּת לְחַיְיכָא בִּבְנִי נָשָׁא. אָמַר לֵיהּ הָכִי הוּא וַדַּאי דְּהָא אִיהִי אַתְיַית וְחַיְיכַאת בְּהוּ בִּבְנֵי נָשָׁא, וּלְזִמְנִין דְּאוֹלִידַת רוּחִין בְּעָלְמָא מִנַּיְיהוּ וְעַד כָּאן אִיהִי קָיְימַת לְחַיְיכָא בְּהוּ בִּבְנִי נָשָׁא.","אָמַר לֵיהּ רַבִּי אַבָּא וְהָא אִנּוּן מֵתִין (קל א) כִּבְנֵי נָשָׁא, מַאי טַעְמָא אִיהִי קָיְימַת עַד הַשְׁתָּא. אָמַר לֵיהּ הָכִי הוּא. אֲבָל לִילִית וְנַעֲמָה וְאָגְרַת בַּת מָחֲלַת דְּנָפְקַת מִסִּטְרָא דִלְהוֹן כֻּלְהוּ קַיָּימוֹת עַד דִּיבַעֵר קוּדְשָׁא בְּרִיךְ הוּא, רוּחַ מְסָאֳבָא מֵעָלְמָא דִּכְתִיב (זכריה י״ג:ב׳) וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ.","אָמַר רַבִּי שִׁמְעוֹן וַוי לוֹן לִבְנֵי נָשָׁא אִנּוּן דְּלָא יָדְעִין וְלָא מַשְׁגִּיחִין וְלָא מִסְתַּכְּלִין וְכֻלְהוּ אֲטִימִין דְּלָא יָדְעִין כַּמָּה מַלְיָיא עָלְמָא מִבִּרְיָין מְשַׁנְיָין דְּלָא אִתְחֲזוּן וּמִמִלִין סְתִימִין. דְּאִלְמָלֵא (יהיב) אִתְיְיהַב רְשׁוּ לְעֵינָא לְמֶחֱזֵי, יִתְמְהוּן בְּנֵי נְשָׁא הֵיךְ יָכְלִין לְאִתְקָיְימָא בְּעָלְמָא.","תָּא חֲזֵי, הַאי נַעֲמָה אִמָּא דְשֵׁדִין הֲוַת. וּמִסִּטְרָהּ אַתְיָין כָּל אִנּוּן שֵׁדִין דְּמִתְחַמְּמָן מִבְּנִי נָשָׁא וְנָטְלֵי רוּחַ תִּיאוּבְתָּא מִנַּיְיהוּ וְחָיְיכַת בְּהוֹן דְּעָבְדֵי לוֹן בַּעֲלֵי קֶרְיָין. וּבְגִין דְּבַעַל קֶרִי אָתֵי מִסִּטְרָא דְרוּחַ מְסָאֳבָא, בָּעֵי לְאַסְחָאָה גַרְמֵיהּ לְאִתְדַּכָּאָה מִנֵּיהּ. וְהָא אוּקְמוּהָ חַבְרַיָא:","זֶה סֵפֶר תּוֹלְדוֹת אָדָם לִדְיוֹקְנִי. אָמַר רַבִּי יִצְחָק אַחְמֵי קוּדְשָׁא בְּרִיךְ הוּא לְאָדָם דְּיוֹקְנֵי דְּכָל אִנּוּן דָּרִין דְּיֵיתוּן לְעָלְמָא. וְכָל חַכִּימֵי עָלְמָא וּמַלְכֵי עָלְמָא דִּזְמִינִין לְקָיְימָא עֲלַיְיהוּ דְיִשְׂרָאֵל. (כד) מָטָא לְמֶחֱמֵי דָּוִד מַלְכָּא דְיִשְׂרָאֵל דְּאִתְיְילִיד וּמִית. אָמַר לֵיהּ (ד\"א ל\"ג אמר וכו) (קמ א, קסח א) מִשְּׁנִין דִּילִי (אוסיף) אוֹזִיף לֵיהּ ע' שְׁנִין. וְגָרְעוּ מֵאָדָם ע' שְׁנִין וְסָלִיק לוֹן קוּדְשָׁא בְּרִיךְ הוּא לְדָוִד."],[[0,"בתר מאה ותלתין","וכו': אחר מאה ושלשים שנה, נתלבש האדם בקנאה, ונזדווג באשתו, והוליד בן וקרא שמו שת. בסוד סופי האותיות שבקשרי כ\"ב אותיות החקוקות, דהיינו הא\"ב בצירוף היושר כמו שהן חקוקות לפנינו שהוא א\"ב ג\"ד ה\"ו וכו', שסופם ש\"ת, ובא לאפוקי מצירופי אלפא ביתות אחרים. שאותיות \u0003שת\u0004 אינן בהם בסופם. ופעם הדבר מבאר הזהר להלן במאמר ויקרא את שמו שת. \u0003רבי יהודה אמר\u0004 וכו': רי\"א, השם שת, הוא סוד הרוח שנאבד, דהיינו רוחו של הבל, שנתלבש בגוף אחר בעולם. דהיינו שנתלבש בשת, וע\"כ נקרא שת. וזהו שכתוב, כי שת לי אלקים זרע אחר תחת הבל."],[1,"וא\"ר יהודה כתיב","וכו': ואר\"י כתיב ויולד בדמותו כצלמו. מכאן נשמע שבנים האחרים קין והבל לא היו בדמותו, ורק זה שת היה בדמותו כצלמו, בתקון הגוף ובתקון הנפש, בארח מישר. כמו שאמר רבי שמעון משמו דרבי ייסא סבא. שהבנים האחרים היו בדבקות הזוהמא של הנחש, ושל אותו הרוכב עליו, שהוא סמאל. ומשום זה לא היו בדמותו של אדם. ואם תאמר, הרי אמרת שהבל מצד אחר היה, דהיינו מצד הקדושה ולא מהנחש, כמו קין. ואומר שכן הוא, אבל שניהם לא היו בצורת האדם שלמטה. כלומר שלא היה בהם בחינת קו אמצעי שה\"ס צורת אדם, אלא הבל היה מצד ימין וקין מצד שמאל. וע\"כ לא היו כדמות אדם."],[2,"אמר ר' יוסי והא כתיב","וכו': ר\"י מביא ראיה שגם הבל לא היה שלם ואומר, והרי כתוב והאדם ידע וגו' ותלד את קין דקאי על חוה ולא כתיב ויולד את קין, ואפילו בהבל לא כתיב ויולד, שהיה סובב על אדם, אלא אומר ותוסף ללדת את אחיו את הבל. וזהו סוד הדבר דהיינו, שאפילו הבל לא היה בדמותו בצלמו של אדם, וע\"כ לא כתוב בו ויולד. אבל בזה, בשת, מה כתוב. ויולד בדמותו כצלמו. שהוא מיוחס לאדם."],[3,"רבי שמעון אמר","וכו': רש\"א, מאה ושלשים שנה נפרד אדם מאשתו, וכל אלו מאה ושלשים שנה היה מוליד רוחות ושדים בעולם, משום אותו כח הזוהמא שהיה הולך ונשאב הימנו, כיון שנכלה כל הזוהמא ממנו, חזר וקנא את אשתו והוליד בן. אז כתוב ויולד בדמותו בצלמו."],[4,"ת\"ח כל בר נש","וכו' : בוא וראה כל אדם ההולך לצד שמאל ומטמא דרכיו, כל רוחות הטומאה הוא מושך על עצמו. ורוח הטומאה מתדבק בו ואינו עוזב אותו. ודבקות רוח הטומאה ההוא, הוא רק באותו האדם שמשך אותו. ולא באחר. משום שדבקות שלהם אינה אלא באלו האנשים שנתדבקו בהם. אשריהם הצדיקים ההולכים בדרך הישר והם צדיקי אמת, ובניהם צדיקים בעולם. ועליהם כתוב, כי ישרים ישכנו ארץ."],[5,"אמר ר' חייא","וכו': אר\"ח, מה שכתוב ואחות תובל קין נעמה. שואל, מה משמיענו הכתוב כאן במה שאמר ששמה נעמה. ומשיב, אלא, משום שזנו אחריה בני אדם מרוב יופי ונעימות שבה, ואפילו רוחות ושדים זנו אחריה, וע\"ז יורה השם נעמה, מלשון נעימות. ר' יצחק אמר אלו בני האלהים עזא ועזאל זנו אחריה, ומשום הפלגה הזו נקראה נעמה."],[6,"רבי שמעון","וכו': רש\"א, אמם של שדים היתה, כי היא באה מצד קין, שממנו יצאו שדים ורוחות (כנ\"ל בראשית א' דף של\"ז אות תנ\"ו) והיא נתמנית עם לילית על מיתת אסכרה של התנוקות. א\"ל רבי אבא, והרי אמר מר, שנעמה נתמנית לצחק עם בני אדם בחלומות, (כנ\"ל בראשית א' דף צ\"ט אות ק\"ב) שהיא בחינת ימין דקליפות ולהמית תנוקות בחינת שמאל הוא אמר לו כן הוא ודאי, כי הוא באה ומצחקת עם אנשים, ופעמים היא מולידה מהם רוחות בעולם, ועד עתה עוד היא עומדת בתפקידה לצחק עם אנשים. אבל ר\"ש אמר שהיא משתתפת עם לילית, והמיתה באה מצד לילית ולא מצד נעמה ומה שצריכים לחיבור זה עם זה (עי' לעיל ב\"א דף ק' ד\"ה ותו פגעין). וענין המלאכים עוזא ועזאל ונעמה עי' בהקדמת הזהר דף קנ\"ח ד\"ה ויש להבין."],[7,"אמר ליה ר' אבא","וכו': א\"ל ר\"א, והרי אלו השדים מתים כבני אדם ולמה אמרת שנעמה עודנה חיה עתה. אמר לו כן הוא. שהשדים מתים כבני אדם. אבל לילית ונעמה, ואגרת בת מחלת הבאה מצדם, כולן חיות, עד שיבער הקב\"ה את רוח הטומאה מן הארץ. שכתוב ואת רוח הטומאה אעביר מן הארץ."],[8,"אמר ר' שמעון ווי לון","וכו': אר\"ש ווי להם לבני אדם, שאינם יודעים ואינם משגיחים ואינם מסתכלים, וכולם אטומים, ואינם יודעים כמה מלא העולם מבריות משונות שאינם נראים, ומדברים נעלמים, ואלמלא ניתן רשות לעין לראות, היו בני האדם מתפלאים, איך אפשר להתקיים בעולם."],[9,"ת\"ח האי נעמה","וכו': בוא וראה, נעמה זו, אמם של השדים היא, ומצדה באים כל אלו השדים שמתחממים מבני אדם, ומקבלים רוח תשוקה מהם מצחקים עמהם ומשימים אותם בעלי קרי. ומשום שבעל קרי בא מרוח הטומאה הנז', הוא צריך לרחוץ את עצמו להטהר ממנו. וכבר בארוהו החברים."],[10,"זה ספר תולדות אדם לדיוקני","וכו': זה ספר תולדות אדם, היינו לצורות בלבד, כלומר לנשמות, שכל הנשמות מתולדות אדם היו כתובים בו. אמר ר' יוסי, הקב\"ה הראה לאדם הראשון הצור ות, של הנשמות, של כל הדורו העתידים לבוא לעולם. ושל כל חכמי העולם ומלכי העולם העתידים לקום בישראל, כשהגיע לראות את דוד מלך ישראל, שנולד ומת, שלא היה לו שנות חיים, אמר לו, להקב\"ה, אוסיף לו שבעים שנה משנותי, וגרעו שבעים שנה מאדם הראשון, ונתן אותם הקב\"ה אל דוד."]],[[0,"","אַחַר מֵאָה וּשְׁלוֹשִׁים שָׁנִים הִתְלַבֵּשׁ אָדָם בְּקִנְאָה וְהִתְחַבֵּר בְּאִשְׁתּוֹ, וְהוֹלִיד בֵּן וְקָרָא שְׁמוֹ שֵׁ\"ת. סוֹד שֶׁל סוֹף הָאוֹתִיּוֹת בִּקְשָׁרִים חֲקוּקִים. רַבִּי יְהוּדָה אָמַר, סוֹד שֶׁל רוּחַ שֶׁאוֹבֶדֶת שֶׁמִּתְלַבֶּשֶׁת בְּגוּף (של הארץ) אַחֵר בָּעוֹלָם, זֶהוּ שֶׁכָּתוּב כִּי שָׁת לִי אֱלֹהִים זֶרַע אַחֵר תַּחַת הֶבֶל."],[1,"","וְאָמַר רַבִּי יְהוּדָה, כָּתוּב וַיּוֹלֶד בִּדְמוּתוֹ כְּצַלְמוֹ, מַשְׁמָע שֶׁבָּנִים אֲחֵרִים לֹא הָיוּ (בדמותו כצלמו, ודבר זה הוא) בִּדְמוּתוֹ. וְזֶה בִּדְמוּתוֹ כְּצַלְמוֹ, בְּתִקּוּן הַגּוּף וּבְתִקּוּן הַנֶּפֶשׁ בְּדֶרֶךְ יָשָׁר. (נ\"א: ודבר זה הוא כמו שנאמר, ואמר רבי אבא משם רבי ייסא) כְּמוֹ שֶׁאָמַר רַבִּי שִׁמְעוֹן מִשֵּׁם רַבִּי יֵיבָא הַזָּקֵן, בָּנִים אֲחֵרִים בְּהִתְדַּבְּקוּת זֻהֲמַת הַנָּחָשׁ, וְאוֹתוֹ שֶׁרוֹכֵב עָלָיו, שֶׁהוּא סָמָאֵ\"ל הָיוּ, וְלָכֵן לֹא הָיָה בִּדְמוּת אָדָם. וְאִם תֹּאמַר, הֲרֵי אָמַרְתָּ שֶׁהֶבֶל הָיָה מִצַּד אַחֵר - כָּךְ הוּא! אֲבָל שְׁנֵיהֶם לֹא הָיוּ בַּדְּמוּת שֶׁלְּמַטָּה."],[2,"","אָמַר (לו) רַבִּי יוֹסֵי, וַהֲרֵי כָּתוּב וְהָאָדָם יָדַע אֶת חַוָּה אִשְׁתּוֹ וַתַּהַר וַתֵּלֶד אֶת קַיִן, וְלֹא (ד\"א אמר לה כך הוא, אבל שניהם לא היו בדמותו, שלא) כָתוּב וַיּוֹלֶד אֶת קַיִן. וַאֲפִלּוּ בְּהֶבֶל לֹא כָתוּב וַיּוֹלֶד, אֶלָּא וַתֹּסֶף לָלֶדֶת אֶת אָחִיו אֶת הָבֶל. וְזֶהוּ סוֹד הַדָּבָר. אֲבָל בָּזֶה מַה כָּתוּב? וַיּוֹלֶד בִּדְמוּתוֹ כְּצַלְמוֹ."],[3,"","רַבִּי שִׁמְעוֹן אָמַר, מֵאָה וּשְׁלוֹשִׁים שָׁנִים נִפְרַד אָדָם מֵאִשְׁתּוֹ, וְכָל אוֹתָם מֵאָה וּשְׁלוֹשִׁים הַשָּׁנִים הָיָה מוֹלִיד רוּחוֹת וְשֵׁדִים בָּעוֹלָם בִּגְלַל אוֹתוֹ כֹּחַ הַזֻּהֲמָה שֶׁהָיָה שָׁאוּב בּוֹ. כֵּיוָן שֶׁחִסֵּל מִמֶּנּוּ אוֹתָהּ הַזֻּהֲמָה, שָׁב וְקִנֵּא (שעבר) אֶת אִשְׁתּוֹ וְהוֹלִיד בֵּן. אָז כָּתוּב וַיּוֹלֶד בִּדְמוּתוֹ כְּצַלְמוֹ."],[4,"","בֹּא רְאֵה, כָּל בֶּן אָדָם שֶׁהוֹלֵךְ לְצַד שְׂמֹאל וּמְטַמֵּא אֶת דְּרָכָיו, כָּל רוּחוֹת הַטֻּמְאָה מוֹשֵׁךְ עַל עַצְמוֹ, וְרוּחַ טֻמְאָה נִדְבֶּקֶת בּוֹ וְלֹא זָזָה מִמֶּנּוּ, וְהִתְדַּבְּקוּת (שלו) שֶׁל אוֹתוֹ רוּחַ טָמֵא יִהְיֶה בָּאִישׁ הַזֶּה וְלֹא בְאַחֵר, וְלָכֵן הִתְדַּבְּקוּתָם אֵינָהּ אֶלָּא בְּאֵלֶּה שֶׁנִּדְבָּקִים בָּהֶם. אַשְׁרֵי הַצַּדִּיקִים שֶׁהוֹלְכִים בְּדֶרֶךְ יְשָׁרָה, וְהֵם צַדִּיקֵי אֱמֶת, וּבְנֵיהֶם צַדִּיקִים בָּעוֹלָם, וַעֲלֵיהֶם כָּתוּב (משלי ב) כִּי יְשָׁרִים יִשְׁכְּנוּ אָרֶץ."],[5,"","אָמַר רַבִּי חִיָּיא, מַה שֶּׁכָּתוּב וַאֲחוֹת תּוּבַל קַיִן נַעֲמָה, מַה קָּרָה כָּאן שֶׁהַכָּתוּב אָמַר שֶׁשְּׁמָהּ נַעֲמָה? אֶלָּא מִשּׁוּם שֶׁטָּעוּ בְּנֵי אָדָם אַחֲרֶיהָ וַאֲפִלּוּ רוּחוֹת וְשֵׁדִים. רַבִּי יִצְחָק אָמַר, אוֹתָם בְּנֵי הָאֱלֹהִים עֲזָא וַעֲזָאֵל טָעוּ אַחֲ רֶיהָ."],[6,"","רַבִּי שִׁמְעוֹן אָמַר, אִמָּם שֶׁל הַשֵּׁדִים הָיְתָה שֶׁיָּצְאָה מִצַּד קַיִן, וְהִיא הִתְמַנְּתָה עַל הַלַּיְלָה (עם לילית) בְּאַסְכָּרָה שֶׁל תִּינוֹקוֹת. אָמַר לוֹ רַבִּי אַבָּא, וַהֲרֵי אָמַר מַר שֶׁהִיא הִתְמַנְּתָה לְצַחֵק בִּבְנֵי אָדָם? אָמַר לוֹ, כָּךְ הוּא וַדַּאי, שֶׁהֲרֵי הִיא בָּאָה וּמְצַחֶקֶת בָּהֶם בִּבְנֵי אָדָם, וְלִפְעָמִים מוֹלִידָה רוּחוֹת בָּעוֹלָם מֵהֶם, וְעַד עַכְשָׁו הִיא עוֹמֶדֶת לְצַחֵק בִּבְנֵי אָדָם."],[7,"","אָמַר לוֹ רַבִּי אַבָּא, וַהֲרֵי הֵם מֵתִים כִּבְנֵי אָדָם, מָה הַטַּעַם הִיא עוֹמֶדֶת עַד עַכְשָׁו? אָמַר לוֹ, כָּךְ זֶה! אֲבָל לִילִית וְנַעֲמָה וְאַגְרַת בַּת מָחֲלַת שֶׁיָּצְאָה מֵהַצַּד שֶׁלָּהֶם, כֻּלָּן קַיָּמוֹת, עַד שֶׁיְּבַעֵר הַקָּדוֹשׁ בָּרוּךְ הוּא רוּחַ הַטֻּמְאָה מִן הָעוֹלָם, שֶׁכָּתוּב (זכריה יג) וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ."],[8,"","אָמַר רַבִּי שִׁמְעוֹן, אוֹי לָהֶם לְאוֹתָם בְּנֵי אָדָם שֶׁלֹּא יוֹדְעִים וְלֹא מַשְׁגִּיחִים וְלֹא מִסְתַּכְּלִים וְכֻלָּם אֲטוּמִים, שֶׁלֹּא יוֹדְעִים כַּמָּה מָלֵא הָעוֹלָם מִבְּרִיּוֹת מְשֻׁנּוֹת שֶׁלֹּא נִרְאוֹת וּמִדְּבָרִים נִסְתָּרִים. שֶׁאִלְמָלֵא (נתן) נִתְּנָה רְשׁוּת לָעַיִן לִרְאוֹת, יִתְמְהוּ בְּנֵי אָדָם אֵיךְ יְכוֹלִים לְהִתְקַיֵּם בָּעוֹלָם."],[9,"","בֹּא רְאֵה, נַעֲמָה הַזּוֹ, אֵם הַשֵּׁדִים הָיְתָה, וּמִצִּדָּהּ בָּאִים כָּל אוֹתָם שֵׁדִים שֶׁמִּתְחַמְּמִים בִּבְנֵי אָדָם וְלוֹקְחִים מֵהֶם רוּחַ תַּאֲוָה, וְצוֹחֶקֶת בָּהֶם, שֶׁעוֹשִׂים אוֹתָם בַּעֲלֵי קֶרִי. וּבִגְלַל שֶׁבַּעַל קֶרִי בָּא מִצַּד שֶׁל רוּחַ הַטֻּמְאָה, צָרִיךְ לִרְחֹץ עַצְמוֹ לְהִטָּהֵר מִמֶּנּוּ. וַהֲרֵי בֵּאֲרוּהָ הַחֲבֵרִים:"],[10,"","זֶה סֵפֶר תּוֹלְדת אָדָם - לִדְמֻיּוֹתָיו. אָמַר רַבִּי יִצְחָק, הֶרְאָה הַקָּדוֹשׁ בָּרוּךְ הוּא לָאָדָם דְּמֻיּוֹת שֶׁל כָּל אוֹתָם דּוֹרוֹת שֶׁיָּבאוּ לָעוֹלָם, וְכָל חַכְמֵי הָעוֹלָם וּמַלְכֵי הָעוֹלָם שֶׁעֲתִידִים לַעֲמֹד עַל יִשְׂרָאֵל. הִגִּיעַ לִרְאוֹת אֶת דָּוִד מֶלֶךְ יִשְׂרָאֵל שֶׁנּוֹלַד וּמֵת. אָמַר לוֹ, (אמר) מֵהַשָּׁנִים שֶׁלִּי (אוסיף) אַלְוֶה לוֹ שִׁבְעִים שָׁנִים. וְגָרְעוּ מֵאָדָם שִׁבְעִים שָׁנִים וְהֶעֱלָה אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא לְדָוִד."]]],[["וְעַל דָּא שַׁבַּח דָּוִד וְאָמַר (תהילים צ״ב:ה׳) כִּי שִׂמַּחְתַּנִי ה' בְּפָעֳלֶךָ בְּמַעֲשֵׂי יָדֶיךָ אֲרַנֵּן. מָאן גָּרַם לִי חֶדְוָה (בהאי) בְּעָלְמָא, פָּעֳלֶךָ דָּא הוּא אָדָם קַדְמָאָה דְּאִיהוּ פָּעֳלוֹ דְּקוּדְשָׁא בְּרִיךְ הוּא, וְלָא פָּעֳלוֹ דְּבָשָׂר וָדָם. מַעֲשֵׂה יָדָיו דְּקוּדְשָׁא בְּרִיךְ הוּא וְלָא מִבְּנֵי נָשָׁא. וְעַל דָּא גָּרְעִי אִנּוּן שִׁבְעִין שְׁנִין מֵאָדָם, מֵאֶלֶף שְׁנִין דְּהֲוָה לֵיהּ לְאִתְקָיְימָא בְּהוּ.","וְאַחְמֵי לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא כָּל חַכִּימֵי דָרָא וְדָרָא. עַד דְּמָטָא לְדָרֵיהּ דְּרַבִּי עֲקִיבָא. וְחָמֵי אוֹרַיְיתָא דִידֵיהּ וְחָדֵי. חָמֵי מִיתָתֵיהּ וְעֲצִיב. פָּתַח וְאָמַר (תהילים קל״ט:י״ז) וְלִי מַה יָּקְרוּ רֵעֶיךָ אֵל מֶה עָצְמוּ רָאשֵׁיהֶם:","זֶה סֵפֶר, סֵפֶר וַדַּאי. וְהָא (לעיל לז ב) אוֹקִימְנָא דְּכַד הֲוָה אָדָם בְּגִנְתָּא דְעֵדֶן נָחִית לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא סִפְרָא עַל יְדָא דְרָזִיאֵל מַלְאָכָא קַדִּישָׁא מְמַנָּא עַל רָזֵי עִלָּאִין קַדִּישִׁין וּבֵיהּ גְּלִיפִין גִּלּוּפֵי עִלָּאִין וְחָכְמָה קַדִּישָׁא. וְשִׁבְעִין וּתְרֵין זִינֵי דְחָכְמְתָא הֲווּ מִתְפָּרְשָׁן מִנֵּיהּ לְשִׁית מְאָה וְשִׁבְעִין גְּלִיפִין דְּרָזֵי עִלָּאֵי.","בְּאֶמְצָעִיתָא דְּסַפְרָא גְּלִיפָא דְּחָכְמְתָא לְמִנְדַע אֶלֶף וְחֲמֵשׁ מְאָה מַפְתְּחָן דְּלָא אִתְמַסְּרָן לְעִלָּאֵי קַדִּישֵׁי. וְכֻלְהוּ אִסְתִּימוּ בֵּיהּ בְּסַפְרָא עַד דְּמָטָא (ד\"א ליה לאדם, כיון דמטא) לְגַבֵּי דְאָדָם, (מניה) הֲווּ מִתְכַּנְּשֵׁי מַלְאֲכֵי עִלָּאֵי לְמִנְדַע וּלְמִשְׁמַע. וְהֲווּ אָמְרֵי (תהילים נ״ז:ו׳) רוּמָה עַל הַשָּׁמַיִם אֱלהִים עַל כָּל הָאָרֶץ כְּבוֹדֶךָ.","בָּה שַׁעֲתָא אִתְרְמִיז לְגַבֵּיהּ הדרניאל מַלְאָכָא קַדִּישָׁא וְאָמַר לֵיהּ, אָדָם, אָדָם, הוֵי גָנִיז יְקָרָא דְּמָארָךְ דְּלָא אִתְיְיהִיב רְשׁוּתָא לְעִלָּאֵי לְמִנְדַע בִּיקָרָא דְמָרָךְ בַּר אַנְתְּ. וְהֲוָה עִמֵּיהּ טָמִיר וְגָנִיז הַהוּא סִפְרָא עַד דְּנָפַק אָדָם מִגִּנְתָּא דְעֵדֶן.","דְּהָא בְּקַדְמִיתָא הֲוָה מְעַיֵּין בֵּיהּ וּמִשְׁתַּמֵשׁ כָּל יוֹמָא בְּגִינְזַיָא דְּמָרֵיהּ וְאִתְגַּלְיָין לֵיהּ רָזִין עִלָּאִין מַה דְּלָא יָדְעוּ שַׁמָּשֵׁי עִלָּאִין. כֵּיוָן דְּחָטָא וְעֲבַר עַל פִּקּוּדָא דְּמָארֵיהּ פָּרַח הַהוּא סִפְרָא מִנִּיהּ. וְהֲוָה אָדָם טֹפֵחַ עַל רֵישׁוֹי וּבָכֵי וְעָאל בְּמֵי גִיחוֹן עַד קָדְלֵיהּ וּמַיָא עָבְדִין גּוּפֵיהּ חֲלָדִין חֲלָדִין וְאִשְׁתַּנֵּי זִיִוִיהּ.","בְּשַׁעֲתָא הַהִיא רָמַז קוּדְשָׁא בְּרִיךְ הוּא לִרְפָאֵל וְאָתִיב לֵיהּ הַהוּא סִפְרָא וּבֵיהּ הֲוָה מִשְׁתַּדֵּל אָדָם וְאֲנַח לֵיהּ לְשֵׁת בְּרֵיהּ וְכֵן לְכָל אִנּוּן תּוֹלְדוֹת עַד דְּמָטָא לְאַבְרָהָם וּבֵיהּ הֲוָה יָדַע לְאִסְתַּכָּלָא בִּיקָרָא דְמָארֵיהּ וְהָא אִתְּמָר. וְכֵן לְחֲנוֹךְ אִתְיְיהַב לֵיהּ סִפְרָא וְאִסְתַּכַּל מִנֵּיהּ בִּיקָרָא עִלָּאָה:","זָכָר וּנְקֵבָה בְּרָאָם. רַבִּי שִׁמְעוֹן אָמַר רָזִין עִלָּאִין אִתְגַּלְּיָין בְּהָנִי תְּרֵי קְרָאֵי. זָכָר וּנְקֵבָה בְּרָאָם, לְמִנְדַע יְקָרָא עִלָּאָה רָזָא דִּמְהֵימָנוּתָא דְּמִגּוֹ רָזָא דְּנָא אִתְבְּרֵי אָדָם.","תָּא חֲזֵי בְּרָזָא דְאִתְבְּרִיאוּ שָׁמַיִם וָאָרֶץ אִתְבְּרֵי אָדָם. בְּהוּ כְּתִיב אֵלֶּה תּוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ (בהבראם). בְּאָדָם כְּתִיב זֶה סֵפֶר תּוֹלְדוֹת אָדָם. בְּהוּ כְּתִיב בְּהִבָּרְאָם. בְּאָדָם כְּתִיב בְּיוֹם הִבָּרְאָם.","זָכָר וּנְקֵבָה בְּרָאָם. מֵהָכָא (אוליפנא) כָּל דִּיוּקְנָא דְּלָא אִשְׁתְּכַח בֵּיהּ דְּכַר וְנוּקְבָא לָאו אִיהוּ דִּיוּקְנָא עִלָּאָה כְּדְקָא חָזֵי. וּבְרָזָא דְמַתְנִיתִין אוֹקִימְנָא.","תָּא חֲזֵי, בְּכָל אֲתַר דְּלָא אִשְׁתַּכְּחוּ דְּכַר וְנוּקְבָא כְּחֲדָא קוּדְשָׁא בְּרִיךְ הוּא לָא שָׁוִי מְדוֹרֵיהּ בְּהַהוּא אֲתַר. וּבִרְכָאן לָא אִשְׁתַּכָּחוּ אֶלָּא בְּאֲתַר דְּאִשְׁתְּכַח דְּכַר וְנוּקְבָא. דִּכְתִיב וַיְבָרֶךְ אוֹתָם וַיִּקְרָא אֶת שְׁמָם אָדָם בְּיוֹם הִבָּרְאָם. וְלָא כְּתִיב וַיְבָרֶךְ אוֹתוֹ וַיִּקְרָא אֶת שְׁמוֹ אָדָם. דְּאֲפִילּוּ אָדָם לָא אִקְרֵי אֶלָּא דְּכַר וְנוּקְבָא כְּחֲדָא.","רַבִּי יְהוּדָה אָמַר מִיּוֹמָא דְּאִתְחָרַב בֵּי מַקְדְּשָׁא בִּרְכָאן לָא אִשְׁתַּכְּחוּ בְּעָלְמָא וְאִתְאֲבִידוּ בְּכָל יוֹמָא. דִּכְתִיב, (ישעיהו נ״ז:א׳) הַצַּדִּיק אָבַד. מַאי אָבַד, אָבַד בִּרְכָאן דְּהֲווּ שָׁרְיָין בֵּיהּ כְּמָה דִכְתִיב, (משלי י׳:ו׳) בְּרָכוֹת לְרֹאשׁ צַדִּיק. וּכְתִיב, (ירמיהו ז׳:כ״ח) אָבְדָה הָאֱמוּנָה. כְּגַוְונָא דָא כְּתִיב וַיְבָרֶךְ אוֹתָם וּכְתִיב וַיְבָרֶךְ אוֹתָם אֱלֹהִים. מִשֵּׁ\"ת אִתְיַיחֲסוּ כָּל דָּרֵי עָלְמָא וְכָל אִנּוּן צַדִּיקֵי קְשׁוֹט דְּהֲווּ בְּעָלְמָא.","אָמַר רַבִּי יוֹסֵי אִלֵּין אַתְוָון בַּתְרָאִין דְּהֲווּ בְּאוֹרַיְיתָא (לאשתכחא) אִשְׁתַּכָּחוּ בָּתַר דַּעֲבָר אָדָם עַל אַתְוָון דְּאוֹרַיְיתָא כֻּלְהוּ (בסדר תשר\"ק. ובגין כך קרא לההוא ברא דאיהו כדמותו בצלמו ש\"ת דאנון קיומא דאתוון). וּבִתְיוּבְתֵּיהּ (ס\"א ובתיאובתיה) לְקַמֵּי מָארֵיהּ אָחִיד בְּאִלֵּין תְּרֵין. וּמִכְּדֵין אִתְהַדְּרוּ אַתְוָון לְמַפְרֵעַ בְּסֵדֶר תשר\"ק."],[[0,"ועל דא שבח","וכו': ועל זה שבח דוד ואמר, כי שמחתני ה' בפעליך, במעשה ידיך ארנן. שפירושו. מי גרם לי שמחה בעולם דהיינו לחיות ולשמוח, אדם הראשון גרם לי זאת, שהוא פעליך ולא פעלו של בשר ודם, מעשה ידיו של הקב\"ה ולא מבני אדם. כלומר, שלא נולד מאנשים, אלא שהוא יציר כפיו של הקב\"ה. ועל כן חסרים אלו שבעים שנה לאדם הראשון, מן האלף שנה שהיה לו לחיות בהם. פירוש, כי נאמר לו, ביום אכלך ממנו מות תמות. ויומו של הקב\"ה הוא אלף שנים, ע\"כ היה לו לחיות אלף שנה, (כמ\"ש בז\"ח בראשית אות תש\"פ). והוא חי תשע מאות ושלשים שנה, וחסר לו ע' שנה. שהוא מטעם שנתנם לדוד, שלא היה לו חיים, כמבואר."],[1,"ואחמי ליה קב\"ה","וכו': והראה לו הקב\"ה כל חכמי דור ודור, עד שהגיע לדורו של ר' עקיבא, וראה תורתו ושמח, ראה מיתתו, שנהרג על ידי מלכות הרשעה, (ע\"ז ה') ונעצב. פתח ואמר עליו אדם הראשון, ולי מה יקרו רעיך אל מה עצמו ראשיהם."],[2,"זה ספר","וכו': כתוב \u0003זה ספר\u0004 תולדות, אדם, היינו ספר ממש. וכבר בארנוהו כאשר אדם היה בגן עדן הוריד לו הקב\"ה ספר על ידי רזיאל המלאך, הממונה על סודות עליונים הקדושים. וחקיקות עליונות היו חקוקות בהספר, היינו סוד החקיקות מעלית המלכות לבינה, וחכמה הקדושה וע\"ב מיני חכמה היו מתבארים ממנו כלומר, חכמה הקדושה המתבארת בעת גדלות, ה\"ס ע\"ב מיני חכמה הרומזים רק על בינה שחזרה להיות חכמה ולא חכמה ממש. והוא מושפעת לשש מאות ושבעים חקיקות של סודות העליונים. דהיינו לז\"א ונוקביה, ז\"א, שה\"ס חג\"ת נהי\"מ, מקבל שש מאות מחג\"ת נה\"י דבינה שספירותיה בסוד מאות. והנוקבא מקבלת לז\"ס חג\"ת נהי\"מ שלה, רק שבעים, דהיינו שכל ספירה היא רק בת עשר, להיותה מקבלת מז\"א שספירותיו בסוד עשיריות בלבד."],[3,"באמצעיתא דספרא גליפא","וכו': באמצעית הספר יש חקיקה מחכמה, ה\"ס נקודה אמצעית שהחקיקה שלה אינה מתמלאת קודם גמר התקון. המוכנת לדעת על ידה בגמר התקון, אלף וחמש מאות מפתחות שלא נמסרו בשתא אלפי שני, לעליונים הקדושים, כי לא נגלו עתה בפרצופין העליונים שהם זו\"ן, רק ו\"ק דג\"ר, שה\"ס אלף ת\"ק מפתחות, כי ג\"ר דחכמה כל ספירה בת אלף, והן ג' אלפים, וחצי המדרגה שהיא ו\"ק, היא אלף וחמש מאה. ואלף ות\"ק החסרים, יתגלו בגמר התקון על הזווג דנקודה אמצעית שנגנזה בעתיק. וז\"ש \u0003למנדע אלף וחמש מאה\u0004 וכו' דהיינו בגמר התקון. אבל עתה, \u0003לא אתמסרו לעלאי קדישי.\u0004 ולעיל בראשית א' דף רס\"ג ד\"ה בקולפי, נתבאר זה בארוכה, ושם מכנה אותם אלף ת\"ק אמות וכאן אלף ת\"ק מפתחות והיינו הך."],[3,"וכלהו אסתימו","וכו' וכל הסודות היו סתומים בהספר מטרם שהגיע לאדם הראשון, כיון שהגיע לאדם הראשון היו מתקבצים אליו מלאכים העליונים לדעת ולשמוע אותם, והיו אומרים, רומה על השמים אלקים על כל הארץ כבודך."],[4,"בה שעתא אתרמיז","וכו': בה בשעה רמז אליו הדרניאל המלאך הקדוש, ואמר לו אדם אדם, גנוז כבוד רבונך, ואל תגלה למלאכים, כי לא ניתן רשות לבד ממך, לדעת בכבוד רבונך. ואפילו למלאכים העליונים. והיה הספר ההוא צרור וגנוז עמו, עד שיצא אדם מגן עדן."],[5,"דהא בקדמיתא","וכו': כי בתחילה היה מעיין ומשתמש בו בכל יום בסודות רבונו, ונגלה לו סודות העליונים, מה שלא ידעו מלאכים העליונים. כיון שחטא ועבר על מצות רבונו, שאכל מעץ הדעת, פרח הספר ממנו, והיה אדם טפח על ראשו ובוכה, ונכנס במי גיחון עד צוארו, היינו שעשה תשובה וסיגף את עצמו, עד שגופו נעשה חלודות חלודות, דהיינו נקבים ובקיעות ונשתנה זיוו."],[6,"בשעתא ההיא","וכו': באותה שעה, רמז הקב\"ה לרפאל המלאך, והשיב לו אותו הספר. ובו היה אדם עוסק, והניח אותו לבנו שת. וכל תולדותיו אחריו, עד שהגיע לאברהם, והיה יודע על ידו להסתכל בכבוד רבונו. וכבר נתבאר זה. וכן ניתן ספר לחנוך והסתכל בו בכבוד העליון."],[7,"זכר ונקבה בראם","וכו': ר' שמעון אמר, סודות עליונים נגלו בשני כתובים הללו. היינו בהכתוב, זה ספר. ובהכתוב זכר ונקבה. הכתוב אומר, זכר ונקבה בראם, ללמדנו לדעת כבוד העליון סוד האמונה, אשר מסוד הזה נברא האדם. דהיינו מזו\"ן העליונים, הנקראים שמים וארץ."],[8,"ת\"ח ברזא","וכו': בוא וראה, באותו הסוד שנבראו שמים וארץ, הם זו\"ן העליונים, נברא האדם. בשמים וארץ, כתוב אלה תולדות השמים וארץ, ובאדם כתוב, זה ספר תולדות אדם. בשמים וארץ כתוב בהבראם. ובאדם כתוב ביום הבראם. הרי ששניהם שקולים, כי נבראו כסוד אחד. פירוש כמו שאצילות זו\"ן הוא על ידי אתוון אל\"ה דבינה, ואח\"כ על ידי עלייתם שם למ\"ן להכריע בין ב' הקוין שבבינה, ממש על אותו הדרך, נברא אדם על ידי אתוון אל\"ה דזו\"ן, ואח\"כ על ידי עליתם למ\"ן להם להכריע בין ב' הקוין שלהם. (כנ\"ל דף קמ\"ח ד\"ה פירוש) ע\"ש. הרי שבאותו הסוד שנבראו זו\"ן נבראו ג\"כ אדם."],[9,"זכר ונקבה בראם","וכו': מכאן נשמע, כל צורה שלא נמצאו בה זכר ונקבה, אינה צורה עליונה, כראוי. ובסוד המשנה בארנוהו."],[10,"ת\"ח בכל אתר","וכו': בוא וראה, בכל מקום שלא נמצאו זכר ונקבה יחד, אין הקב\"ה משים דירתו באותו המקום. וברכות אינן נמצאות אלא במקום שנמצא זכר ונקבה. שכתוב ויברך \u0003אותם\u0004 ויקרא את \u0003שמם\u0004 אדם ביום הבראם, ולא כתוב ויברך \u0003אותו\u0004 ויקרא את \u0003שמו אדם.\u0004 ללמדך. שאפילו בשם אדם אינו נקרא, אלא זכר ונקבה יחד."],[11,"ר' יהודה אמר","וכו': רי\"א, מיום שנחרב בית המקדש, ברכות אינן נמצאות בעולם, ונאבדות בכל יום, שכתוב, הצדיק אבד. מהו \u0003אבד,\u0004 אבד הברכות, שהיו שורות בו בהצדיק. כמ\"ש ברכות לראש צדיק. וכתוב, אבדה האמונה, דהיינו הנוקבא, חמקבלת הברכות מהצדיק, שה\"ס יסוד דז\"א, שה\"ס זכר. כעין זה, בעת השלמות. כתוב, ויברך אותם. וכתוב ויברך אותם אלקים. פירוש. בעת החורבן שאין אז זווג זכר ונקבה, נבחנים שניהם לנאבדים, כי בשניהם אינן נמצאות ברכות. ובעת השלימות מתברכים שניהם יחד, כמ\"ש ויברך אותם ויקרא את שמם אדם. דהיינו שניהם יחד."],[12,"משת אתייחסו","וכו': משת נתיחסו כל דורות העולם, וכל צדיקי אמת שבעולם. אמר ר' יוסי אלו אותיות אחרונות שבתורה \u0003ש' ת',\u0004 נמצאו שלמות, גם אחר שעבר אדם על כל אותיות התורה, דהיינו בחטא עצה\"ד הכולל לכל התורה, ובתשובה שעשה לפני רבונו, נאחז באלו שתי אותיות, ש' ת', שנמצאו שלמות. ומאז חזרו הראשונות לאחור בסדר תשר\"ק צפע\"ס וכו'."],[12,"","פירוש, כי הכולל של אותיות התורה הם כ\"ב אותיות. והם הכלים להתלבשות האורות נפש רוח נשמה, (כמ\"ש לעיל בהקדמת הזהר דף ל\"ד ד\"ה גם יש) שג' מדרגות בהם: יחידות עד י' הן לאור הבינה שהוא נשמה, עשרות עד ק' הם לאור ז\"א שהוא רוח, ומאות שהן קרש\"ת הן לאור הנוקבא שהוא נפש. ומקודם החטא היה לאדם נר\"ן מאצילות. ובעת שחטא בעץ הדעת פרחו ממנו ט\"ר שהם הנשמה והרוח וג\"ר דנפש, כי גם נפש דאצילות פרחו ממנו, ונשאר בו ו\"ק ממנה דהיינו נפש מיוד פרצופי בי\"ע. שערך בי\"ע כלפי אצילות הוא כמו ו\"ק כלפי ג\"ר, (כנ\"ל דף קפ\"ג ד\"ה וההיא) ונמצאו נופלים ממנו גם האותיות שהלבישו את נר\"ן הללו שפרחו ממנו, שהם האותיות מ\u0003א'\u0004 עד \u0003י'\u0004 שהן כלי הנשמה, והאותיות מ\u0003י'\u0004 עד \u0003ק'\u0004 שהן כלי הרוח, וחציים של האותיות קרש\"ת שהן רלי ג\"ר הנפש, ולא נשארו בו אלא ב' האותיות אחרונות \u0003ש' ת',\u0004 שהם הכלים לו\"ק דנפש שנשארה בו."],[12,"","וז\"ש \u0003אלין אתוון בתראין דהוו באורייתא\u0004 שהם ש' ת' כנ\"ל. \u0003אשתכחו בתר דעבר אדם על אתוון דאורייתא כלהו,\u0004 נשאר גם אחר שעבר אדם על כל אותיות התורה, דהיינו אפילו אחר החטא, שפרחו ממנו נר\"ן דאצילות עם כל אותיות התורה, שהיו מלובשים בהן, מ\"מ נשארו בו ב' אותיות \u0003ש' ת',\u0004 כי האורות שלהם שהם ו\"ק דנפש לא פרחו מהם כמבואר, וז\"ש \u0003ובתיובתיה לקמיה מאריה אחיד באלין תרין,\u0004 כשעשה תשובה לפני רבונו נאחז באלו ב' האותיות ש' ת' שנשארו בו מכל הכ\"ב אותיות ומהן שאב כל חיותו. וז\"ש \u0003ומכדין אתהדרו אתוון למפרע בסדר תשר\"ק.\u0004 כי סדר א\"ב ביושר, אבג\"ד וכו' יורה על אור ישר, שה\"ס ט\"ר. וסדר א\"ב למפרע יורה על אור חוזר הנבחן לאור נקבה, דהיינו אור הנפש. וכיון שלא נשאר לו אלא אור הנפש, לא היה יכול לקבל עוד מסדר אותיות ביושר, אלא אור חוזר, שהוא: תשר\"ק צפע\"ס נמל\"ך יטח\"ז והר\"ג ב\"א."]],[[0,"","וְעַל זֶה שִׁבַּח דָּוִד וְאָמַר, (תהלים צב) כִּי שִׂמַּחְתַּנִי ה' בְּפָעֳלֶךְ בְּמַעֲשֵׂי יָדֶיךְ אֲרַנֵּן. מִי גָרַם לִי חֶדְוָה בָּעוֹלָם (הזה)? פָּעֳלֶךְ, זֶהוּ אָדָם הָרִאשׁוֹן שֶׁהוּא פָעֳלוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלֹא פָעֳלוֹ שֶׁל בָּשָׂר וָדָם, מַעֲשֵׂה יָדָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וְלֹא מִבְּנֵי אָדָם. וְעַל זֶה גָּרְעוּ אוֹתָם שִׁבְעִים שָׁנִים מֵאָדָם מֵאֶלֶף שָׁנִים שֶׁהָיוּ לוֹ לְהִתְקַיֵּם בָּהֶם."],[1,"","וְהֶרְאָה לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא כָּל חַכְמֵי דּוֹר וָדוֹר, עַד שֶׁהִגִּיעַ לְדוֹרוֹ שֶׁל רַבִּי עֲקִיבָא, וְרָאָה תוֹרָה שֶׁלּוֹ וְשָׂמַח. רָאָה מִיתָתוֹ וְהִתְעַצֵּב. פָּתַח וְאָמַר, (תהלים קלט) וְלִי מַה יָּקְרוּ רֵעֶיךְ אֵל מֶה עָצְמוּ רָאשֵׁיהֶם."],[2,"","זְהִ סֵפֶר - סֵפֶר וַדַּאי. וַהֲרֵי בֵּאַרְנוּ, כְּשֶׁהָיָה אָדָם בְּגַן עֵדֶן, הוֹרִיד לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא סֵפֶר עַל יְדֵי הַמַּלְאָךְ רָזִיאֵל הַקָּדוֹשׁ הַמְמֻנֶּה עַל הַסּוֹדוֹת הָעֶלְיוֹנִים הַקְּדוֹשִׁים, וּבוֹ חֲקוּקִים חֲקִיקוֹת עֶלְיוֹנוֹת וְחָכְמָה קְדוֹשָׁה, וְשִׁבְעִים וּשְׁנַיִם מִינֵי חָכְמָה הָיוּ מִתְפָּרְשִׁים מִמֶּנּוּ לְשֵׁשׁ מֵאוֹת וְשִׁבְעִים חֲקִיקוֹת שֶׁל סוֹדוֹת עֶלְיוֹנִים."],[3,"","בְּאֶמְצַע הַסֵּפֶר חֲקִיקַת הַחָכְמָה לָדַעַת אֶלֶף וַחֲמֵשׁ מֵאוֹת מַפְתְּחוֹת שֶׁלֹּא נִמְסְרוּ לְעֶלְיוֹנִים קְדוֹשִׁים, וְכֻלָּם נִסְתָּרִים בַּסֵּפֶר, עַד שֶׁהִגִּיעַ (לו לאדם, כיון שהגיע) אֵצֶל אָדָם, מִמֶּנּוּ הָיוּ מִתְכַּנְּסִים מַלְאָכִים עֶלְיוֹנִים לָדַעַת וְלִשְׁמֹעַ, וְהָיוּ אוֹמְרִים (שם נז) רוּמָה עַל הַשָּׁמַיִם אֱלֹהִים עַל כָּל הָאָרֶץ כְּבוֹדֶךְ."],[4,"","בְּאוֹתָהּ שָׁעָה נִרְמַז אֵלָיו לְהדרניא\"ל הַמַּלְאָךְ הַקָּדוֹשׁ, וְאָמַר לוֹ: אָדָם, אָדָם, גְּנֹז אֶת כְּבוֹד רִבּוֹנְךְ, שֶׁלֹּא נִתְּנָה רְשׁוּת לָעֶלְיוֹנִים לָדַעַת בִּכְבוֹד רִבּוֹנְךְ פְּרָט לְךְ. וְהָיָה הַסֵּפֶר הַהוּא שָׁמוּר וְגָנוּז עִמּוֹ עַד שֶׁיָּצָא אָדָם מִגַּן עֵדֶן."],[5,"","שֶׁהֲרֵי בַּהַתְחָלָה הָיָה מְעַיֵּן בּוֹ וּמִשְׁתַּמֵּשׁ כָּל יוֹם בְּגִנְזֵי רִבּוֹנוֹ, וְהִתְגַּלּוּ לוֹ סוֹדוֹת עֶלְיוֹנִים מַה שֶּׁלֹּא יָדְעוּ שַׁמָּשִׁים עֶלְיוֹנִים. כֵּיוָן שֶׁחָטָא וְעָבַר עַל מִצְוַת רִבּוֹנוֹ, פָּרַח מִמֶּנּוּ אוֹתוֹ הַסֵּפֶר, וְהָיָה אָדָם טוֹפֵחַ עַל רֹאשׁוֹ וּבוֹכֶה, וְנִכְנַס בְּמֵי גִיחוֹן עַד צַוָּארוֹ, וְהַמַּיִם עוֹשִׂים אֶת גּוּפוֹ נְקָבִים נְקָבִים וְהִשְׁתַּנָּה זִיווֹ."],[6,"","בְּאוֹתָהּ שָׁעָה רָמַז הַקָּדוֹשׁ בָּרוּךְ הוּא לִרְפָאֵל, וְהֵשִׁיב לוֹ אוֹתוֹ הַסֵּפֶר, וּבוֹ הָיָה אָדָם עוֹסֵק וְהִנִּיחוֹ לְשֵׁת בְּנוֹ, וְכֵן לְכָל אוֹתָם צֶאֱצָאִים, עַד שֶׁהִגִּיעַ לְאַבְרָהָם, וּבוֹ הָיָה יוֹדֵעַ לְהִסְתַּכֵּל בִּכְבוֹד רִבּוֹנוֹ, וַהֲרֵי נֶאֱמַר. וְכֵן לַחֲנוֹךְ נִתַּן לוֹ הַסֵּפֶר וְהִסְתַּכֵּל מִמֶּנּוּ בַּכָּבוֹד הָעֶלְיוֹן."],[7,"","זָכָר וּנְקֵבָה בְּרָאָם. רַבִּי שִׁמְעוֹן אָמַר, סוֹדוֹת עֶלְיוֹנִים הִתְגַּלּוּ בִּשְׁנֵי הַפְּסוּקִים הַלָּלוּ. זָכָר וּנְקֵבָה בְּרָאָם לָדַעַת הַכָּבוֹד הָעֶלְיוֹן, סוֹד הָאֱמוּנָה, שֶׁמִּתּוֹךְ סוֹד זֶה נִבְרָא אָדָם."],[8,"","בֹּא רְאֵה, בַּסּוֹד שֶׁל שָׁמַיִם וָאָרֶץ נִבְרָא אָדָם, בָּהֶם כָּתוּב אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ (בהבראם). בְּאָדָם כָּתוּב זֶה סֵפֶר תּוֹלְדת אָדָם. בָּהֶם כָּתוּב בְּהִבָּרְאָם, וּבְאָדָם כָּתוּב בְּיוֹם הִבָּרְאָם."],[9,"","זָכָר וּנְקֵבָה בְּרָאָם. מִכָּאן, כָּל דְּמוּת שֶׁלֹּא נִמְצָא בָּהּ זָכָר וּנְקֵבָה, אֵינָהּ דְּמוּת עֶלְיוֹנָה כָּרָאוּי, וּבְסוֹד הַמִּשְׁנָה בֵּאַרְנוּ."],[10,"","בֹּא רְאֵה, בְּכָל מָקוֹם שֶׁלֹּא נִמְצָאִים זָכָר וּנְקֵבָה כְּאֶחָד, הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא שָׂם אֶת מְדוֹרוֹ בְּאוֹתוֹ הַמָּקוֹם, וְהַבְּרָכוֹת לֹא נִמְצָאוֹת רַק בְּמָקוֹם שֶׁנִּמְצָאִים זָכָר וּנְקֵבָה, שֶׁכָּתוּב וַיְבָרֶךְ אֹתָם וַיִּקְרָא אֶת שְׁמָם אָדָם בְּיוֹם הִבָּרְאָם, וְלֹא כָתוּב וַיְבָרֶךְ אוֹתוֹ וַיִּקְרָא אֶת שְׁמוֹ אָדָם. שֶׁאֲפִלּוּ אָדָם לֹא נִקְרָא אֶלָּא זָכָר וּנְקֵבָה כְּאֶחָד."],[11,"","רַבִּי יְהוּדָה אָמַר, מִיּוֹם שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ לֹא נִמְצָאוֹת בְּרָכוֹת בָּעוֹלָם, וְהֵם אוֹבְדוֹת בְּכָל יוֹם, שֶׁכָּתוּב (ישעיה נז) הַצַּדִּיק אָבָד. מָה אָבַד? אִבֵּד הַבְּרָכוֹת שֶׁהָיוּ שׁוֹרוֹת בּוֹ, כְּמוֹ שֶׁכָּתוּב (משלי י) בְּרָכוֹת לְרֹאשׁ צַדִּיק. וְכָתוּב (ירמיה ז) אָבְדָה הָאֱמוּנָה. כְּמוֹ זֶה כָּתוּב וַיְבָרֶךְ אֹתָם, וְכָתוּב וַיְבָרֶךְ אֹתָם אֱלֹהִים. מִשֵּׁ\"ת הִתְיַחֲסוּ כָּל דּוֹרוֹת הָעוֹלָם וְכָל אוֹתָם צַדִּיקֵי אֱמֶת שֶׁהָיוּ בָּעוֹלָם."],[12,"","אָמַר רַבִּי יוֹסֵי, הָאוֹתִיּוֹת הָאַחֲרוֹנוֹת הַלָּלוּ שֶׁהָיוּ בַּתּוֹרָה (להמצא) נִמְצְאוּ אַחַר שֶׁעָבַר אָדָם עַל אוֹתִיּוֹת הַתּוֹרָה כֻּלָּם (בסדר תשר\"ק, ולכן קרא לאותו הבן שהוא כדמותו כצלמו ש\"ת, שהם קיום האותיות). וּבִתְשׁוּבָתוֹ (ובתשוקתו) לִפְנֵי רִבּוֹנוֹ אָחַז בִּשְׁנֵי אֵלֶּה, וּמֵאָז חָזְרוּ הָאוֹתִיּוֹת לְמַפְרֵעַ בְּסֵדֶר תשר\"ק."]]],[["וּבְגִין דָא קָרָא לְהַהוּא בְּרָא דְּאִתְיְלִיד לֵיהּ דְּאִיהוּ בִּדְמוּתוֹ כְּצַלְמוֹ שֵׁ\"ת דְּאִנּוּן סִיּוּמָא דְּאַתְוָון. וְלָא אִתְתַּקָּנוּ אַתְוָון עַד דְּקָיְימוּ יִשְׂרָאֵל עַל טוּרָא דְסִינַי. וּכְדֵין אַהַדְּרוּ אַתְוָון עַל תִּקּוּנַיְיהוּ כְּיוֹמָא דְּאִתְבְּרִיאוּ שָׁמַיִם וָאָרֶץ. וְאִתְבַּסַּם עָלְמָא וְקָיְמָא עַל קִיּוּמֵיהּ.","רַבִּי אַבָּא אָמַר יוֹמָא דְּעֲבַר אָדָם עַל פִּקּוּדָא דְּמָארֵיהּ, בָּעְיָין שָׁמַיִם וָאָרֶץ (לאתגפא) לְאִתְעַקָּרָא מֵאַתְרַיְיהוּ. מַאי טַעְמָא בְּגִין דְּאִנּוּן לָא קָיְימוּ אֶלָּא עַל בְּרִית דִּכְתִיב (ירמיהו ל״ג:כ״ה) אִם לֹא בְרִיתִי יוֹמָם וָלַיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לא שָׂמְתִּי. וְאָדָם עָבַר בְּרִית שֶׁנֶּאֱמַר (הושע ו׳:ז׳) וְהֵמָּה כְאָדָם עָבְרוּ בְּרִית.","וְאִלְמָלֵא דְּגָלֵי קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא דִּזְמִינִין יִשְׂרָאֵל לְקָיְימָא עַל טוּרָא דְּסִינַי לְקַיְימָא הַאי בְּרִית, לָא אִתְקְיַּים עָלְמָא (דין). רַבִּי חִזְקִיָּה אָמַר כָּל מָאן דְּאוֹדֵי עַל חֶטְאֵיהּ, קוּדְשָׁא בְּרִיךְ הוּא שָׁבִיק לֵיהּ וּמָחִיל עַל חוֹבֵיהּ.","תָּא חֲזֵי, כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא, עֲבַד הַאי בְּרִית וְקָיְימָא עֲלֵיהּ עָלְמָא. מְנָלָן דִּכְתִיב (בראשית) בָּרָא שִׁית, דָּא בְּרִית דְּעָלְמָא קָיְמָא עֲלֵיהּ. שִׁית דְּמִנֵּיהּ נְגִידִין וְנָפְקָא בִּרְכָאן לְעָלְמָא וְעֲלֵיהּ אִתְבְּרֵי עָלְמָא. וְאָדָם עֲבַר עַל הַאי בְּרִית וְאַעֲבַר לֵיהּ מֵאַתְרֵיהּ (ס\"א מעמיה).","הַאי בְּרִית אִתְרְמִיזַת בְּאָת יו\"ד אָת זְעֵירָא עִקְּרָא וִיסוֹדָא דְּעָלְמָא. כַּד אוֹלִיד בַּר, אוֹדֵי עַל חֶטְאוֹ וְקָרָא שְׁמֵיהּ ש\"ת. וְלָא אַדְכַּר בֵּיהּ יו\"ד לְמֶהֱוֵי שִׁית, בְּגִין דְּעֲבַר עֲלֵיהּ. וּבְגִין כָּךְ קוּדְשָׁא בְּרִיךְ הוּא (מהכא) מִינֵּיהּ אִשְׁתִּיל עָלְמָא וְאִתְיַיחֲסוּ כָּל דָּרֵי זַכָּאָה דְּעָלְמָא (משת).","וְתָּא חֲזֵי, כַּד קָיְימוּ יִשְׂרָאֵל עַל טוּרָא דְסִינַי, עָאל בֵּין תְּרֵין אַתְוָון אִלֵּין רָזָא דִּבְרִית. וּמָאן אִיהוּ בֵי\"ת. וְעָאל בֵּין תְּרֵין אַתְוָון דְּאִשְׁתְּאָרוּ וְיָהִיב לֵיהּ לְיִשְׂרָאֵל. וְכַד עָאל בי\"ת רָזָא דִּבְרִית בֵּין תְּרֵין אַתְוָון אִלֵּין דְּאִנּוּן שי\"ן תי\"ו (עאלו) וְאִתְעֲבִידוּ שַׁבָּ\"ת. כְּמָא דְאַתְּ אָמֵר, (שמות ל״א:ט״ז) וְשָׁמְרוּ בְּנֵי יִשְׂרָאֵל אֶת הַשַּׁבָּת לַעֲשׂוֹת אֶת הַשַּׁבָּת לְדוֹרוֹתָם בְּרִית עוֹלָם. כְּמָא דְּהֲוָה שֵׁירוּתָא דְּעָלְמָא לְאִתְיַיחֲסוּ בְּהוּ כָּל דָּרֵי עָלְמָא מֵאִלֵּין תְּרֵין אַתְוָון ש\"ת הֲווּ תַּלְיָין עַד דְּאִשְׁתַּכְלַל עָלְמָא כְּדְקָא יָאוּת וְעָאל בֵּינַיְיהוּ בְּרִית קַדִּישָׁא וְאִשְׁתַּכְלַל בִּשְׁלִימוּ וְאִתְעֲבִידוּ שַׁבָּ\"ת.","אָמַר רַבִּי יוֹסֵי אִלֵּין תְּרֵין אַתְוָון אִשְׁתַּכְלְלוּ בְּאָת בֵּי\"ת וְכַד (אתהדר אתוון למפרע מן יומא דאתייליד שת אהדרו אתוון בכל דרא ודרא עד דמטי ישראל לטורא דסיני ואתתקנו.)","אָמַר רַבִּי יְהוּדָה לְתַתָּא אִתְהַדְּרוּ. וּבְכָל דָּרָא וְדָרָא הֲוָה גָּפִיף עָלְמָא בְּאַתְוָון וְלָא מִתְיַשְׁבִין בְּדוּכְתַּיְיהוּ. כַּד אִתְיַיהֲבַת אוֹרַיְיתָא לְיִשְׂרָאֵל אִתְתַּקַּן כֹּלָּא (נ\"א אתוון כלהו אתתקנו) (כאן שייך מאמר בסתרי אותיות בזוהר חדש דף י, ובדפוס ויניציאה דף יג ב' ויחי אדם כו' ע\"ש) רַבִּי אֶלְעָזָר אוֹמֵר בְּיוֹמֵי אֱנוֹשׁ הֲווּ חַכִּימִין בְּנִי נָשָׁא בְּחָכְמָה דְּחַרְשִׁין וְקוֹסְמִין וּבְחָכְמָתָא לְמֶעֱצַר לְחֵילֵי דִשְׁמַיָא. וְלָא הֲוָה בַּר נָשׁ מִיּוֹמָא דְּנָפַק אָדָם מִגִּנְתָּא דְעֵדֶן וְאַפִּיק עִמֵיהּ חָכְמְתָא דְּטַרְפֵּי אִילָנָא דְּאִשְׁתַּדַּל בָּהּ. דְּהָא אָדָם וְאִתְּתֵיהּ וְאִנּוּן דְּנָפְקוּ מִנֵּיהּ עַד דְּאָתָא אֱנוֹשׁ, שְׁבִיקוּ לָהּ.","כַּד אֲתָא אֱנוֹשׁ חָמָא לוֹן וְחָמָא חָכְמַתְהוֹן מְשַׁנְיָין (ס\"א משטיין) עִלָּאִין. וְאִשְׁתַּדְּלוּ בְּהוֹן וְעָבְדִין (בה) עֲבִידְתִּין וְחַרְשִׁין וְקוֹסְמִין וְאוֹלִיפוּ מִנְהוֹן עַד דְּאִתְפַּשְׁטַת הַהִיא חָכְמְתָא בְּדָרָא דְּמַבּוּל. וְכֻלְהוּ הֲווּ עַבְדֵי עֲבִידְתַּיְיהוּ לְאַבְאָשָׁא.","וְהֲווּ מִתְתַּקְפֵי לְגַבֵּי נֹחַ בְּאִנּוּן חָכְמְתָן. וְאָמְרֵי דְּלָא יָכִיל דִּינָא דְעָלְמָא לְאַשְׁרָאָה עֲלַיְיהוּ, דְּהָא אִנּוּן עָבְדֵי חָכְמְתָא לְדַחְיָיא לְכָל אִנּוּן מָארֵי דְדִינָא. וּמֵאֱנוֹשׁ שָׁרִיאוּ כֻּלְהוּ לְאִשְׁתַּדְּלוּ בְּאִלֵּין חָכְמְתָן הֲדָא הוּא דִכְתִיב אָז הוּחַל לִקְרֹא בְּשֵׁם יְיָ.","רַבִּי יִצְחָק אָמַר כָּל אִנּוּן זַכָּאִין דְּהֲווּ בְּהוּ לְבָתַר בְּהַהוּא דָרָא, כֻּלְהוּ הֲווּ מִשְׁתַּדְּלֵי לְמָחָאָה בְּהוּ (נ\"אבגין דלא אתענשו עליהו) כְּמוֹ יֶרֶד מְתוּשֶׁלַח וְחֲנוֹךְ. וְלָא יָכִילוּ. עַד דְּאִתְפַּשְׁטוּ חַיָּיבִין מָרְדֵי בְּמָארֵיהוֹן וְאָמְרֵי (איוב כ״א:ט״ו) מַה שַּׁדַּי כִּי נַעַבְדֶנּוּ.","וְכִי הַאי טִפְּשׁוּתָא הֲווּ קָא אָמְרֵי. אֶלָּא בְּגִין דְּהֲווּ יָדְעֵי כָּל אִנּוּן חָכְמְתָן וְכֻלְהוּ מְמַנָּן דְּעָלְמָא דְּאִתְפַּקְּדָן עֲלַיְיהוּ וְהֲווּ מְרַחֲצָן בְּהוּ. עַד דְּאָתִיב קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא כְּדְקָא הֲוָה. דְּהָא בְּקַדְמִיתָא הֲוָה מַיִם בְּמַיִם. וּלְבָתַר אָתִיב לֵיהּ לְעָלְמָא כִּדְקַדְמִיתָא. וְלָא אִתְחָרִיב מִכֹּלָא. דְּהָא בְּרַחֲמִין אַשְׁגַּח עֲלַיְיהוּ. דִּכְתִיב, (תהילים כ״ט:י׳) יְיָ לַמַּבּוּל יָשָׁב. וְלָא כְּתִיב אֱלהִים."],[[0,"ובג\"ד קרא","וכו': ומשום זה קרא לאותו הבן שנולד לו, שהוא בדמותו בצלמו בשם \u0003שת,\u0004 שהם סיום האותיות דא\"ב, שנשארו לו. (כנ\"ל בדבור הסמוך). ולא נתקנו האותיות מקלקולם, עד שעמדו ישראל על הר סיני, ואז חזרו האותיות ובאו על תקונם, כמו שהיו ביום שנבראו בו שמים וארץ, דהיינו מקודם החטא דאדם הראשון, כי חזר הסדר דא\"ב ביושר. והעולם נמתק ועמד על קיומו."],[1,"ר' אבא אמר","וכו': רא\"א, ביום שאדם עבר על מצות רבונו, בקשו שמים וארץ להתעקר ממקומם. מה הטעם, הוא, משום שהם אינם עומדים אלא על ברית, שכתוב אם לא בריתי יומם ולילה חוקות שמים וארץ לא שמתי. ואדם עבר ברית, שנאמר, והמה כאדם עברו ברית, וע\"כ אבדו יסודם ובקשו להתעקר ממקומם."],[1,"","פירוש. ברית ה\"ס תקון היסוד, במילה, שה\"ס הרחקת קליפת הערלה. ופריעה, שה\"ס המשכת המוחין דג\"ר. ואז יש זווג זו\"ן, המכונים יומם ולילה, שהמוחין מושפעים לשמים וארץ, ומתקיים העולם. וזשה\"כ, \u0003אם לא בריתי יומם ולילה,\u0004 אם לא נתתקן הברית, שה\"ס תקון היסוד במילה ופריעה כנ\"ל, \u0003חוקות שמים וארץ לא שמתי,\u0004 כי לא היה להם שפע ולא יכלו להתקיים. כנ\"ל. ואדם הראשון בחטאו היה מושך בערלתו, שמשך קליפת הערלה על יסוד הקדוש, ונפרדו זו\"ן העליונים, ולא היה שפע וקיום לשמים וארץ. וז\"ש \u0003בעיין שמים וארץ לאתעקרא מאתרייהו.\u0004 כי לא נמשך להם השפע די קיומם."],[2,"ואלמלא דגלי","וכו': ואלמלא היה נגלה לפני הקב\"ה שעתידים ישראל לעמוד על הר סיני לקיים אותו הברית, לא היה מתקיים העולם אחר חטאו של אדה\"ר. ר' חזקיה אומר. כל מי שמתודה על חטאיו, הקב\"ה סולח לו ומוחל עונו. כלומר כיון שאדם הראשון התודה ועשה תשובה על כן נתקיים העולם. ואינו רוצה לומר, משום שהיה גלוי, לפני הקב\"ה מעמד הר סיני. כמ\"ש ר' אבא."],[3,"ת\"ח כד ברא","וכו': בוא וראה כשברא הקב\"ה את העולם, שה\"ס הנוקבא, עשה ברית הזה, שהוא יסוד דז\"א, שתקנו בהסרת הקליפות בהמשכת המוחין כנ\"ל בסמוך, והעמיד עליו העולם שה\"ס הנוקבא המקבלת ממנו. מאין לנו זה, כי כתוב \u0003בראשית\u0004 שהוא נוטריקון \u0003ברא-שית,\u0004 ו\u0003שית\u0004 היא הברית שהעולם עומד עליו. ונקרא \u0003שית\u0004 שהוא לשון יסוד, שממנו נמשכות ויוצאות הברכות לעולם, ועליו נברא העולם. ואדם בחטאו בעץ הדעת עבר על ברית הזה (כנ\"ל בסמוך) והעביר אותו ממקומו, וע\"כ בקשו אז שמים וארץ להתעקר ממקומם כנ\"ל."],[4,"האי ברית אתרמיזת","וכו': ברית הזה נרמז באות י' אות הקטנה, והיא עיקר ויסוד העולם. כי עליו נברא העולם, (כנ\"ל בסמוך). פירוש. כי האותיות ש' ת' ראוים רק לאור חוזר לבד דהיינו ממטה למעלה כנ\"ל. ואחרי שנמשך ביניהם ה\u0003י'\u0004 שה\"ס יסוד דז\"א, הם מקבלים אור ישר, שה\"ס כל המוחין. ואז נקרא \u0003שית,\u0004 שה\u0003י'\u0004 כוללת כל המוחין. וכאשר אדם הוליד בן, התודה על חטאו, וקרא שמו \u0003שת,\u0004 ולא הזכיר בו \u0003י',\u0004 שה\"ס אור ישר, שיהיה שמו \u0003שית,\u0004 שזה יורה שלא ימשיך בהם רק או\"ח ממטה למעלה לבד, משום שעבר עליו, כמ\"ש והמה כאדם עברו ברית כנ\"ל, וע\"כ בזה שקרא שמו שת, בלי י' התודה על חטאו. ומשום זה שהתודה, הקב\"ה השתיל ממנו העולם, והתייחסו אחריו כל דורות וצדיקי העולם. הרי שמשום שהתודה על חטאו מחל לו הקב\"ה, והעולם נתקיים."],[5,"ות\"ח כד קיימו","וכו': ובוא וראה, כאשר עמדו ישראל על הר סיני נכנסה בין ב' אותיות האלו \u0003ש' ת',\u0004 סוד הברית, ומי היא \u0003ב'\u0004, שה\"ס המוחין המתגלים עם תקון הברית, וע\"כ נקראת הב' \u0003רזא דברית,\u0004 וה\"ס ב' דבראשית (כנ\"ל ב\"א דף רמ\"ו ד\"ה והמלך ע\"ש). והיא נכנסה בין ב' האותיות שנשארו, אהר החטא דעצה\"ד, שהם ש\"ת כנ\"ל. ונתן אותו את השבת, לישראל. וכאשר נכנסה ה\u0003ב',\u0004 שהיא סוד הברית, בין ב' אותיות הללו ש' ת', ונעשו \u0003שבת,\u0004 הוא כמו שאתה אומר ושמרו בני ישראל את השבת לדורותם ברית עולם, דהיינו שזכו לקבל את השבת לכל הדורות בלי הפסק, כי כמו שנעשה התחלה לעולם להתייחס אחריהם כל דורות העולם מאלו ב' האותיות ש' ת', כן עתה שנמשך לתוכו הב' ונעשו שבת, הן מאירות לדורותם, ברית עולם בלי הפסק. כי ש' ת' הללו, היו תלוים עד שנשתכלל העולם כראוי, דהיינו בעת קבלת התורה, ואז נכנס ביניהם ברית הקדוש, ונשתכלל העולם בשלמות, ונעשו \u0003שבת.\u0004"],[6,"אמר ר' יוסי","וכו': אלו ב' האותיות ש' ת' נשתכללו באות ב', שיהיו ראוים לקבל אור ישר, דהיינו במתן תורה. וכמו שחזרו האותיות למפרע מיום שנולד בו שת, דהיינו שלא לקבל ממעלה למטה, רק ממטה למעלה לבד, כן חזרו בכל דור ודור להאיר רק ממטה למעלה, שה\"ס אור הנפש, עד שהגיעו ישראל להר סיני, ונתתקנו, דהיינו שהאיר בהם הב', שה\"ס המוחין דאור ישר המאירים ממעלה למטה, ונעשו שבת."],[7,"א\"ר יהודה","וכו': אר\"י ממעלה למטה חזרו האותיות להאיר, דהיינו אור הרוח. כלומר, שחולק על ר' יוסי, שאמר שמטרם מתן תורה האירו רק ממטה למעלה, שהוא אור הנפש. ובכל דור ודור, מטרם מתן תורה, היה העולם ממשמש בהאותיות ולא היו מתישבות במקומן. פירוש, שהיו מטולטלות מרחמים לדין ומדין לרחמים, כטבע אור הרוח, ולא היו מתישבות. וכאשר ניתנה התורה לישראל נתתקו הכל. שחזרו להאיר בשלמות כמטרם החטא."],[7,"ר' אלעזר אומר:","בימי אנוש היו בני האדם חכמים בכשפים וקסמים, ובהחכמה איך לעצור כחות השמימים, שלא יפעלו על העולם, ומיום שיצא אדם מגן עדן, והוציא עמו החכמה של עלי תאנה, שהיא כשפים (כנ\"ל דף קפ\"א אות שי\"א) לא היה עוד איש שיעסוק בה, כי אדם ואשתו, ואלו שנולדו ממנו מטרם שבא אנוש, עזבו את חכמה הזאת, ולא התעסקו בה."],[8,"כד אתא אנוש וכו':","כאשר בא אנוש, ראה אותם עלי תאנה, וראה שחכמתם מכחשת העליונים, דהיינו שמכחשת הקדושה (כנ\"ל דף קפ\"ב ד\"ה וזה ע\"ש) ועסקו בהם ועשו פעולות וכשפים וקסמים ולמדו מהם לאחרים, עד שנתפשטה חכמה ההיא בדור המבול, וכולם עשו בכחה את מעשיהם להרע."],[9,"והוו מתתקפי וכו':","והיו מתחזקים כלפי נח בחכמתם זו, במה שהזהירם בהמבול, ואמרו, ששום דין שבעולם לא יוכל לשרות עליהם, כי יעשו בחכמה לדחות מעליהם את כל בעלי הדין. ומאנוש ואילך התחילו כולם לעסוק בחכמה הזו, וזהו שכתוב, אז הוחל לקרוא בשם ה'. ו\u0003הוחל,\u0004 פירושו, שעשו חולין את קריאת שם ה', ע\"י חכמת הכשפים שעסקו בה."],[10,"ר' יצחק אמר וכו':","רי\"א, כל אלו הצדיקים שהיו בהם אחר אותו הדור של אנוש, היו כולם משתדלים למחות בהם, כמו ירד מתושלח וחנוך, ולא יכלו. עד שנתפשטו בעולם רשעים המורדים ברבונם, ואמרו, מה שדי כי נעבדנו."],[11,"וכי האי מפשותא וכו':","ושואל, וכי שטות זו אפשר שיאמרו. דהיינו מה שדי כי נעבדנו. ומשיב. אלא משום שהיו יודעים כל אלו החכמות שלהם, וכל ממוני העולם שנפקדו על הנהגת העולם, והיו בוטחים בהם. כלומר שהיו בוטחים בחכמתם, שעל ידי השבעות שישביעו ממונים הללו לא יארע להם כל רע. עד שהשיב הקב\"ה את העולם כמו שהיה, שהביא עליהם מבול מים, כי מתחילה היה העולם מים במים, דהיינו כמו ביום ב' לבריאת העולם מטרם שנראה היבשה. ואחר המבול, החזיר העולם לתקונו כבתחילה, ולא נחרב כולו בעת המבול, כי השגיח עליהם אז ברחמים, שכתוב, ה' למבול ישב. שהוא מדת הרחמים, ולא כתוב, אלקים למבול ישב, שהוא מדת הדין. הרי שדן אותם ברחמים, ומשום זה לא נחרב כולו על ידי המבול."]],[[0,"","וְלָכֵן קָרָא לְאוֹתוֹ בֵּן שֶׁנּוֹלַד לוֹ שֶׁהוּא בִּדְמוּתוֹ בְּצַלְמוֹ שֵׁ\"ת, שֶׁהֵם סִיּוּם הָאוֹתִיּוֹת. וְלֹא נִתְקְנוּ הָאוֹתִיּוֹת עַד שֶׁעָמְדוּ יִשְׂרָאֵל עַל הַר סִינַי, וְאָז חָזְרוּ הָאוֹתִיּוֹת עַל תִּקּוּנָם כְּיוֹם שֶׁנִּבְרְאוּ שָׁמַיִם וָאָרֶץ, וְהִתְבַּסֵּם הָעוֹלָם וְעָמַד עַל קִיּוּמוֹ."],[1,"","רַבִּי אַבָּא אָמַר, בְּיוֹם שֶׁעָבַר אָדָם עַל מִצְוַת רִבּוֹנוֹ, רָצוּ שָׁמַיִם וָאָרֶץ (להנגף) לְהֵעָקֵר מִמְּקוֹמָם. מָה הַטַּעַם? מִשּׁוּם שֶׁהֵם לֹא עָמְדוּ רַק עַל הַבְּרִית, שֶׁכָּתוּב (ירמיה לג) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי. וְאָדָם עָבַר בְּרִית, שֶׁנֶּאֱמַר (הושע ו) וְהֵמָּה כְּאָדָם עָבְרוּ בְרִית."],[2,"","וְאִלְמָלֵא שֶׁגָּלוּי לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁעֲתִידִים יִשְׂרָאֵל לַעֲמֹד עַל הַר סִינַי לְקַיֵּם אֶת הַבְּרִית הַ את, לֹא הִתְקַיֵּם הָעוֹלָם (הזה). רַבִּי חִזְקִיָּה אָמַר, כָּל מִי שֶׁמּוֹדֶה עַל חֶטְאוֹ, הַקָּדוֹשׁ בָּרוּךְ הוּא מֵנִיחַ לוֹ וּמוֹחֵל לוֹ עַל חֶטְאוֹ."],[3,"","בֹּא רְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, עָשָׂה בְּרִית זוֹ וְהֶעֱמִיד עָלֶיהָ אֶת הָעוֹלָם. מִנַּיִן לָנוּ? שֶׁכָּתוּב (בראשית), בָּרָא שִׁית. זוֹ הַבְּרִית שֶׁהָעוֹלָם עוֹמֵד עָלֶיהָ. שִׁית שֶׁמִּמֶּנּוּ שׁוֹפְעִים וְיוֹצְאִים בְּרָכוֹת לָעוֹלָם, וְעָלֶיהָ נִבְרָא הָעוֹלָם. וְאָדָם עָבַר עַל הַבְּרִית הַזּוֹ וְהֶעֱבִירָהּ מִמְּקוֹמָהּ (ס\"א מעמו)."],[4,"","בְּרִית זוֹ נִרְמְזָה בָּאוֹת יוֹ\"ד, אוֹת קְטַנָּה עִקַּר וִיסוֹד הָעוֹלָם. כְּשֶׁהוֹלִיד בֵּן, הוֹדָה עַל חֶטְאוֹ וְקָרָא שְׁמוֹ שֵׁ\"ת, וְלֹא הִזְכִּיר בּוֹ יוֹ\"ד לִהְיוֹת שִׁית, מִשּׁוּם שֶׁעָבַר עָלָיו. וְלָכֵן הַקָּדוֹשׁ בָּרוּךְ הוּא (מכאן) מִמֶּנּוּ שָׁתַל אֶת הָעוֹלָם, וְהִתְיַחֲסוּ כָּל דּוֹרוֹת צַדִּיקֵי הָעוֹלָם (משת)."],[5,"","וּבֹא וּרְאֵה, כְּשֶׁעָמְדוּ יִשְׂרָאֵל עַל הַר סִינַי, נִכְנַס בֵּין שְׁתֵּי הָאוֹתִיּוֹת הַלָּלוּ סוֹד הַבְּרִית, וּמִיהוּ? בֵּי\"ת. וְנִכְנַס בֵּין שְׁתֵּי הָאוֹתִיּוֹת שֶׁנִּשְׁאֲרוּ, וְנָתַן אוֹתָהּ לְיִשְׂרָאֵל. וּכְשֶׁנִּכְנְסָה בֵּי\"ת, סוֹד הַבְּרִית, בֵּין שְׁתֵּי הָאוֹתִיּוֹת הַלָּלוּ, שֶׁהֵם שִׁי\"ן תָּי\"ו, (נכנסו) וְנַעֲשׂוּ שַׁבָּת, כְּמוֹ שֶׁנֶּאֱמַר (שמות לא) וְשָׁמְרוּ בְנֵי יִשְׂרָאֵל אֶת הַשַּׁבָּת לַעֲשׂוֹת אֶת הַשַּׁבָּת לְדרֹתָם בְּרִית עוֹלָם. כְּמוֹ שֶׁהָיָה רֵאשִׁית הָעוֹלָם לְהִתְיַחֵס בָּהֶם כָּל דּוֹרוֹת הָעוֹלָם מִשְּׁתֵּי הָאוֹתִיּוֹת הַלָּלו ש\"ת, הָיוּ תְּלוּיִים עַד שֶׁנִּתְקַן הָעוֹלָם כָּרָאוּי וְנִכְנַס בֵּינֵיהֶם הַבְּרִית הַקָּדוֹשׁ, וְנִתְקַן בִּשְׁלֵמוּת וְנַעֲשָׂה שַׁבָּ\"ת."],[6,"","אָמַר רַבִּי יוֹסֵי, אֵלּוּ שְׁתֵּי הָאוֹתִיּוֹת הַלָּלוּ נִתְקְנוּ בָּאוֹת בֵּי\"ת, וּכְשֶׁחָזְרוּ הָאוֹתִיּוֹת לְמַפְרֵעַ מִיּוֹם שֶׁנּוֹלַד שֵׁת, חָזְרוּ הָאוֹתִיּוֹת בְּכָל דּוֹר וָדוֹר עַד שֶׁהִגִּיעוּ יִשְׂרָאֵל לְהַר סִינַי וְנִתְקְנוּ."],[7,"","אָמַר רַבִּי יְהוּדָה, לְמַטָּה חָזְרוּ. וּבְכָל דּוֹר וָדוֹר הָיָה מְחֻבָּק הָעוֹלָם בָּאוֹתִיּוֹת וְלֹא מִתְיַשְּׁבִים בִּמְקוֹמָם. כְּשֶׁנִּתְּנָה הַתּוֹרָה לְיִשְׂרָאֵל, הַכֹּל נִתְקַן (נ\"א: כל האותיות נתקנו). רַבִּי אֶלְעָזָר אוֹמֵר, בִּימֵי אֱנוֹשׁ הָיוּ הָאֲנָשִׁים חֲכָמִים בְּחָכְמָה שֶׁל כְּשָׁפִים וְקוֹסְמִים וּבְחָכְמָה לַעֲצֹר אֶת חֵילוֹת הַשָּׁמַיִם. וְלֹא הָיָה בֶּן אָדָם מִיּוֹם שֶׁיָּצָא אָדָם מִגַּן עֵדֶן וְהוֹצִיא עִמּוֹ חָכְמָה שֶׁל הֶעָלִים שֶׁל הָאִילָן שֶׁהִתְעַסֵּק בָּהּ. שֶׁהֲרֵי אָדָם וְאִשְׁתּוֹ, וְאוֹתָם שֶׁיָּצְאוּ מִמֶּנּוּ עַד שֶׁבָּא אֱנוֹשׁ, עָזְבוּ אוֹתָהּ."],[8,"","כְּשֶׁבָּא אֱנוֹשׁ, רָאָה אוֹתָם וְרָאָה אֶת חָכְמָתָם מְשַׁנָּה (ס\"א משטה) אֶת הָעֶלְיוֹנִים, וְעָסְקוּ בָהֶם וְעָשׂוּ (בהם) מַעֲשִׂים וּכְשָׁפִים וּקְסָמִים וְלָמְדוּ מֵהֶם, עַד שֶׁהִתְפַּשְּׁטָה אוֹתָהּ חָכְמָה בְּדוֹר הַמַּבּוּל. וְכֻלָּם הָיוּ עוֹשִׂים מַעֲשֵׂיהֶם לְהָרַע."],[9,"","וְהָיוּ מִתְחַזְּקִים כְּלַפֵּי נֹחַ בְּאוֹתָן חָכְמוֹת, וְאוֹמְרִים שֶׁלֹּא יָכוֹל דִּין הָעוֹלָם לִשְׁרוֹת עֲלֵיהֶם, שֶׁהֲרֵי הֵם עוֹשִׂים חָכְמָה לִדְחוֹת אֶת כָּל אוֹתָם בַּעֲלֵי הַדִּין. וּמֵאֱנוֹשׁ הִתְחִילוּ כֻלָּם לְהִתְעַסֵּק בַּחָכְמוֹת הַלָּלוּ. זֶהוּ שֶׁכָּתוּב אָז הוּחַל לִקְרֹא בְּשֵׁם ה'."],[10,"","רַבִּי יִצְחָק אָמַר, כָּל אוֹתָם צַדִּיקִים שֶׁהָיוּ בֵינֵיהֶם אַחַר אוֹתוֹ הַדּוֹר, כֻּלָּם הָיוּ מִשְׁתַּדְּלִים לִמְחוֹת בָּהֶם (נ\"א: כדי שלא יענשו עליהם), כְּמוֹ יֶרֶד מְתוּשֶׁלַח וַחֲנוֹךְ, וְלֹא יָכְלוּ, עַד שֶׁהִתְפַּשְּׁטוּ רְשָׁעִים הַמּוֹרְדִים בְּרִבּוֹנָם, וְאָמְרוּ (איוב כא) מַה שַּׁדַּי כִּי נַעַבְדֶנּוּ."],[11,"","וְכִי הַטִּפְּשׁוּת הַזּוֹ הֵם הָיוּ אוֹמְרִים? אֶלָּא מִשּׁוּם שֶׁהָיוּ יוֹדְעִים כָּל אוֹתָם הַחָכְמוֹת וְכָל אוֹתָם הַמְמֻנִּים שֶׁל הָעוֹלָם שֶׁהֻפְקְדוּ עֲלֵיהֶם וְהָיוּ סוֹמְכִים עֲלֵיהֶם, עַד שֶׁהֵשִׁיב הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם כְּשֶׁהָיָה. שֶׁהֲרֵי בַּתְּחִלָּה הָיָה מַיִם בְּמַיִם, אַחַר כָּךְ הֵשִׁיב הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם כְּבַתְּחִלָּה, וְלֹא נֶחֱרַב מֵהַכֹּל, שֶׁהֲרֵי בְּרַחֲמִים הִשְׁגִּיחַ עֲלֵיהֶם, שֶׁכָּתוּב (תהלים כט) ה' לַמַּבּוּל יָשָׁב, וְלֹא כָתוּב אֱלֹהִים."]]],[["בְּיוֹמוֹי דֶּאֱנוֹשׁ אֲפִלּוּ יְנוּקֵי דְּהַהוּא (יומא) דָרָא כֻּלְהוּ הֲווּ מַשְׁגְּחָן בְּחָכְמָתָאן עִלָּאִין וְהֲוֵי מִסְתַּכְּלָן בְּהוּ. אָמַר רַבִּי יֵיסָא אִי הָכִי טִפְּשִׁין הֲווּ דְּלָא הֲווּ יָדְעִין דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאַיְיתָאָה עֲלַיְיהוּ מֵי טוֹפָנָא וִימוּתוּן בְּהוּ.","אָמַר רַבִּי יִצְחָק מִנְדַע יָדְעֵי. אֲבָל אֲחִידוּ טִפְּשׁוּתָא בְּלִבַּיְיהוּ. דְּאִנּוּן הֲווּ יָדְעֵי הַהוּא מַלְאָכָא דִּמְמַנָּא עַל אֶשָׁא וְהַהוּא דִּמְמַנָּא עַל מַיָא וְהֲווּ יָדְעִין לְמֶעֱצַר לוֹן דְּלָא יָכְלִין לְמֶעְבַּד דִּינָא עֲלַיְיהוּ. וְאִנּוּן לָא הֲווּ יָדְעֵי דְּקוּדְשָׁא בְּרִיךְ הוּא שָׁלִיט עַל אַרְעָא וּמִנֵּיהּ יֵיתֵי דִינָא עַל עָלְמָא.","אֶלָא הֲווּ חָמָאן דְּעָלְמָא אִתְפַּקַּד בִּידָא דְּאִנּוּן מְמַנָּן וּבְהוּ כָּל מִלֵּי עָלְמָא. וּבְגִינֵי כָּךְ לָא הֲווּ מִסְתַּכְּלָן בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא וְלָא מַשְׁגִּיחִין בְּעֲבִידְתֵּיהּ. עַד דְּאַרְעָא אִתְחַבָּלַת. וְרוּחַ קוּדְשָׁא אַכְרִיז בְּכָל יוֹמָא וְאָמַר (תהילים ק״ד:ל״ה) יִתַּמּוּ חַטָּאִים מִן הָאָרֶץ וּרְשָׁעִים עוֹד אֵינָם.","וְאוֹרִיךְ קוּדְשָׁא בְּרִיךְ הוּא לוֹן כָּל הַהוּא זִמְנָא דְּאִנּוּן זַכָּאִין יֶרֶד וּמְתוּשֶׁלַח וְחֲנוֹךְ קָיְימִין בְּעָלְמָא. כֵּיוָן דְּאִסְתַּלָּקוּ מֵעָלְמָא, וּכְדֵין אַנְחִית קוּדְשָׁא בְּרִיךְ הוּא דִּינָא עֲלַיְיהוּ וְאִתְאֲבִידוּ כְּמָא דְּאַתְּ אָמֵר, (בראשית ז׳:כ״ג) וַיִּמָּחוּ מִן הָאָרֶץ (כאן שייך מאמר בז\"ח דף ס\"ו ובדפוס וניציאה מ\"ב א' ע\"ש):","וַיִּתְהַלֵּךָ חֲנוֹךְ אֶת הָאֱלֹהִים וְאֵינֶנּוּ כִּי לָקַח אוֹתוֹ אֱלֹהִים. רַבִּי יוֹסֵי פָּתַח (שיר השירים א׳:י״ב) עַד שֶׁהַמֶּלֶךְ בִּמְסִבּוֹ נִרְדִּי נָתַן רֵיחוֹ. הַאי קְרָא אִתְּמָר. אֲבָלתָּא חֲזֵי, כָּךְ אָרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא. בְּשַׁעְתָּא דְּבַר נָשׁ אִתְדָּבַּק בֵּיהּ וְהוּא אַשְׁרֵי דִּיּוּרֵיהּ עֲלֵיהּ. וְיָדַע דִּלְבָתַר יוֹמִין יִסְרַח. אַקְדִים וְלָקִיט רֵיחֵיהּ טַב מִנֵּיהּ וְסָלִיק לֵיהּ מֵעָלְמָא.","הֲדָא הוּא דִכְתִיב עַד שֶׁהַמֶּלֶךְ בִּמְסִבּוֹ נִרְדִּי נָתַן רֵיחוֹ. עַד שֶׁהַמֶּלֶךְ דָּא קוּדְשָׁא בְּרִיךְ הוּא. בִּמְסִבּוֹ דָּא הַהוּא בַּר נָשׁ דְּאִתְדָּבַּק בֵּיהּ וְאָזִיל בְּאָרְחוֹי. נִרְדִּי נָתַן רֵיחוֹ, אִנּוּן עוֹבָדִין טָבִין דְּבֵיהּ דִּבְגִינְהוֹן יִסְתַּלַּק מֵעָלְמָא עַד דְּלָא מָטָא זִמְנֵיהּ.","וְעַל דָּא הֲוָה שְׁלמֹה מַלְכָּא אָמַר (קהלת ח׳:י״ד) יֵשׁ הֶבֶל אֲשֶׁר נַעֲשָׂה עַל הָאָרֶץ אֲשֶׁר יֵשׁ צַדִּיקִים וְגו'. יֵשׁ צַדִּיקִים אֲשֶׁר מַגִּיעַ אֲלֵיהֶם כְּמַעֲשֵׂה הָרְשָׁעִים, כְּמָה דְאוֹקִימְנָא דִּבְגִין דְּעוֹבָדֵיהוֹן טָבִין קוּדְשָׁא בְּרִיךְ הוּא סָלִיק לוֹן מֵעָלְמָא (בגין דלא יסרחו (יחיו). ומגו רחימותא בהו מסלק להון) עַד לָא מָטָא זִמְנַיְיהוּ. וְעָבִיד בְּהוֹן דִּינִין. וְיֵשׁ רְשָׁעִים אֲשֶׁר מַגִּיעַ אֲלֵיהֶם כְּמַעֲשֵׂה הַצַּדִּיקִים דְּקוּדְשָׁא בְּרִיךְ הוּא אוֹרִיךְ לוֹן יוֹמִין וְאוֹרִיךְ רוּגְזֵיהּ בְּהוּ. וְכָל דָּא כְּמָה דְּאִתְּמָר. אִלֵּין בְּגִין דְּלָא יִסְרְחוּן. וְאִלֵּין בְּגִין דְּלִהַדְּרוּ לְגַבֵּיהּ. אוֹ בְּגִין דְּיִפּוּק מִנַּיְיהוּ בְּנִין דְּמַעֲלֵי.","תָּא חֲזֵי חֲנוֹךְ זַּכָּאָה הֲוָה. וְקוּדְשָׁא בְּרִיךְ הוּא חָמָא לֵיהּ דְּיִסְרַח לְבָתַר. וְלָקִיט לֵיהּ עַד לָא יִסְרַח. הֲדָא הוּא דִכְתִיב, (שיר השירים ו׳:ב׳) וְלִלְקוֹט שׁוֹשַׁנִּים. בְּגִין דְּיַהֲבֵי רֵיחָא טַב לָקִיט לוֹן קוּדְשָׁא בְּרִיךְ הוּא עַד לָא יִסְרְחוּ. וְאֵינְנּוּ כִּי לָקַח אוֹתוֹ אֱלֹהִים. וְאֵינֶנּוּ, לְאָרְכָא יוֹמִין כִּשְׁאָר בְּנִי נָשָׁא דְּהֲווּ אוֹרְכֵי יוֹמִין. מַאי טַעְמָא בְּגִין דְּלָקַח לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא עַד לָא מָטֵי זִמְנֵיהּ.","רַבִּי אֶלְעָזָר אָמַר חֲנוֹךְ נָטִיל לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא מֵאַרְעָא וְאַסְקֵיהּ לִשְׁמֵי מְרוֹמִים וְאַמְסַר בִּידֵיהּ כָּל גִּנְזֵי עִלָּאִין (לעיל לז ב) וּמ\"ה מַפְתְּחָן סָתְרֵי גְלִיפִין דְּבְּהוּ מִשְׁתַּמְּשֵׁי מַלְאֲכֵי עִלָּאֵי וְכֻלְהוּ אִתְמְסָרוּ בִּידֵיהּ. וְהָא אוֹקִימְנָא:","וַיַּרְא יְיָ כִּי רַבָּה רָעַת הָאָדָם בָּאָרֶץ וְכָל יֵצֶר מַחְשְׁבוֹת לִבּוֹ. רַבִּי יְהוּדָה פָּתַח (תהילים ה׳:ה׳) כִּי לא אֵל חָפֵץ רֶשַׁע אָתָּה לֹא יְגוּרְךָ רָע. הַאי קְרָא אִתְּמָר וְאוּקְמוּהָ. אֲבָלתָּא חֲזֵי, מַאן דְּאִתְדָּבַּק בְּיֵצֶר הָרָע וְאִתְמָשִׁיךְ אֲבַתְרֵיהּ וְיִסְתָּאַב הוּא וִיסָאֲבוּן לֵיהּ כְּמָה דְּאִתְּמָר.","כִּי רַבָּה רָעַת הָאָדָם, כָּל בִּישִׁין הֲווּ עָבְדֵי, וְלָא אִשְׁתְּלִים חוֹבַיְיהוּ עַד דְּהֲווּ אוֹשְׁדִין דָּמִין לְמַגָּנָא עַל אַרְעָא. וּמָאן אִנּוּן דְּהֲווּ מְחַבְּלִין אָרְחַיְיהוּ עַל אַרְעָא. הֲדָא הוּא דִכְתִיב רַק רַע כָּל הַיּוֹם. כְּתִיב הָכָא רַק רַע וּכְתִיב הָתָם (לא יגורך רע, וכתיב) (בראשית ל״ח:ז׳) וַיְהִי עֵר בְּכוֹר יְהוּדָה רַע בְּעֵינִי יְיָ."],[[0,"ביומוי דאנוש וכו':","בימי אנוש, אפילו התינוקות שבאותו הדור, היו משגיחים כולם בחכמות העליונות והיו מסתכלים בהם. כלומר, שהיו מתבוננים בהם, א\"ר ייסא, אם כן, טפשים היו, שלא היו יודעים שעתיד הקב\"ה להביא עליהם מי המבול וימותו בהם."],[1,"אמר ר' יצחק:","והשיב לו ר' יצחק, יודעים היו, אבל אחזו טפשות בלבם, שהם היו יודעים את המלאך הממונה על האש, ואת המלאך הממונה על המים, והיו יודעים לעצור אותם, שלא יוכלו לעשות בהם דין, וע\"כ לא פחדו מעונש. והם לא היו יודעים, שהקב\"ה הוא השולט על הארץ, וממנו יבא הדין על העולם."],[2,"אלא הוו חמאן:","אלא היו רואים, שהעולם נפקד ביד ממונים האלו. ובהם תלוים כל דברי העולם, ומשום זה לא היו מסתכלים בהקב\"ה, ולא היו משגיחים במעשיו, עד שנשחתה הארץ. ורוח הקדש הכריז עליהם בכל יום, יתמו חטאים מן הארץ ורשעים עוד אינם."],[3,"ואוריך קב\"ה לון וכו':","והמתין להם הקב\"ה כל אותו הזמן שהצדיקים, ירד מתושלח וחנוך, היו חיים בהעולם, כיון שנפטרו מהעולם, אז הוריד הקב\"ה עליהם את הדין, ונתאבדו. כמו שאתה אומר, וימחו מן הארץ ."],[4,"ויתהלך חנוך את האלקים ואיננו וגו':","ר' יוסי פתח. עד שהמלך במסבו נרדי נתן ריחו. מקרא זה כבר נתבאר. אבל בוא וראה, כך דרכיו של הקב\"ה. בשעה שהאדם מתדבק בו, והוא משרה שכינתו עליו, ויודע שלאחר כך יחטא הוא מקדים ולוקט ריחו הטוב ממנו ולוקח אותו מהעולם."],[5,"הה\"ד עד שהמלך במסבו נרדי נתן ריחו:","עד שהמלך זהו הקב\"ה. \u0003במסבו,\u0004 זהו אותו האדם שנתדבק בו, והולך בדרכיו, \u0003נרדי נתן ריחו,\u0004 הם המעשים טובים שבו, שבשבילם נפטר מהעולם קודם זמנו כדי שלא יקלקל אותם."],[6,"ועל דא הוה שלמה מלכא וכו':","ועל זה אמר שלמה המלך. יש הבל אשר נעשה על הארץ. אשר יש צדיקים וגו'. יש צדיקים אשר מגיע אליהם כמעשה הרשעים הוא כמו שבארנו, שבשביל מעשים הטובים שעשו, הקב\"ה לוקח אותם מהעולם עד שלא הגיע זמנם, ועושה בהם דינים, כדי שלא יקלקלו מעשיהם. ויש רשעים אשר מגיע אליהם כמעשה הצדיקים, הוא שהקב\"ה מאריך להם הזמן, ומאריך אפו, כנ\"ל בדור המבול. וכל זה הוא כמו שבארנו, אלו, כדי שלא יחטאו ויקלקלו מעשיהם הטובים. ע\"כ מגיע אליהם דינים כמעשה הרשעים, ואלו, כדי שיחזרו אליו בתשובה, או בשביל שצריך לצאת מהם בנים טובים. ע\"כ ממתין להם ומאריך אפו ומגיע אליהם כמעשה הצדיקים."],[7,"ת\"ח חנוך זכאה וכו':","בוא וראה. חנוך צדיק היה, והקב\"ה ראה אותו שיחטא אחר כך, ולקט אותו מטרם שיחטא, וז\"ש וללקוט שושנים. שפירושו, שבשביל שנותנים ריח טוב לוקח אותם הקב\"ה מטרם שיחטאו. כנ\"ל. ואיננו כי לקח אותו אלקים. \u0003ואיננו,\u0004 פירושו, שאיננו להאריך ימים כשאר בני דורו שהיו מאריכים ימים, מה הטעם, משום שלקחו הקב\"ה מטרם שהגיע זמנו כנ\"ל."],[8,"ר\"א אמר חנוך וכו':","רא\"א חנוך, לקחו הקב\"ה מן הארץ והעלהו לשמי מרומים, ומסר בידו כל אוצרות העליונים, ומ\"ה מפתחות סתרי חקיקות, שבהם משתמשים מלאכים העליונים. וכולם נמסרו בידו. וכבר נתבאר."],[9,"וירא ה' כי רבה רעת האדם וגו':","ר\"י פתח. כי לא אל חפץ רשע אתה לא יגורך רע. מקרא זה נאמר ובארוהו אבל בוא וראה, כל המתדבק ביצר הרע ונמשך אחריו, הוא יטמא ויטמאו אותו כמו שלמדנו."],[10,"כי רבה רעת האדם:","פירושו, כל העבירות היו עושים ולא נשלם עוונם, ער ששפכו דם לבטלה על הארץ. ומי המה. הם, המשחיתים דרכם על הארץ. דהיינו שמוציאים זרע לבטלה, וזהו שכתוב, רק רע כל היום. כתוב כאן רק רע, וכתוב שמה, ויהי ער בכור יהודה רע בעיני ה'. ויליף גזירה שוה. מה רע אשר שם, פירושו, שהיה מוציא זרעו לבטלה אף רע שבכאן פירושו מוציאים זרעם לבטלה."]],[[0,"","בִּימֵי אֱנוֹשׁ אֲפִלּוּ תִּינוֹקוֹת שֶׁל אוֹתוֹ (היום) הַדּוֹר הָיוּ מַשְׁגִּיחִים בְּחָכְמוֹת עֶלְיוֹנוֹת וְהָיוּ מִסְתַּכְּלִים בָּהֶם. אָמַר רַבִּי יֵיסָא, אִם כָּךְ, טִפְּשִׁים הָיוּ שֶׁלֹּא הָיוּ יוֹדְעִים שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהָבִיא עֲלֵיהֶם מֵי מַבּוּל וְיָמוּתוּ בָהֶם?"],[1,"","אָמַר רַבִּי יִצְחָק, יָדוֹעַ הָיוּ יוֹדְעִים, אֲבָל אָחֲזוּ טִפְּשׁוּת בְּלִבָּם. שֶׁהֵם הָיוּ יוֹדְעִים אוֹתוֹ מַלְאָךְ הַמְמֻנֶּה עַל אֵשׁ וְאוֹתוֹ הַמְמֻנֶּה עַל הַמַּיִם, וְהָיוּ יוֹדְעִים לַעֲצֹר אוֹתָם שֶׁלֹּא יוּכְלוּ לַעֲשׂוֹת דִּין עֲלֵיהֶם. וְהֵם לֹא הָיוּ יוֹדְעִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹלֵט עַל הָאָרֶץ וּמִמֶּנּוּ יָבֹא דִין עַל הָעוֹלָם?"],[2,"","אֶלָּא הָיוּ רוֹאִים שֶׁהָעוֹלָם הֻפְקַד בִּידֵי אוֹתָם מְמֻנִּים, וּבָהֶם כָּל דִּבְרֵי הָעוֹלָם, וְלָכֵן לֹא הָיוּ מִסְתַּכְּלִים בַּקָּדוֹשׁ-בָּרוּךְ-הוּא וְלֹא מַשְׁגִּיחִים בְּמַעֲשָׂיו עַד שֶׁהָאָרֶץ נִשְׁחֲתָה. וְרוּחַ הַקֹּדֶשׁ מַכְרִיזָה בְּכָל יוֹם וְאוֹמֶרֶת: יִתַּמּוּ חַטָּאִים מִן הָאָרֶץ וּרְשָׁעִים עוֹד אֵינָם."],[3,"","וְהַקָּדוֹשׁ בָּרוּךְ הוּא הֶאֱרִיךְ לָהֶם כָּל אוֹתוֹ הַזְּמַן שֶׁאוֹתָם צַדִּיקִים, יֶרֶד וּמְתוּשֶׁלַח וַחֲנוֹךְ, קַיָּמִים בָּעוֹלָם. כֵּיוָן שֶׁהִסְתַּלְּקוּ מֵהָעוֹלָם, אָז הוֹרִיד הַקָּדוֹשׁ בָּרוּךְ הוּא דִּין עֲלֵיהֶם וְנֶאֶבְדוּ, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ז) וַיִּמָּחוּ מִן הָאָרֶץ."],[4,"","וַיִּתְהַלֵּךָ חֲנוֹךְ אֶת הָאֱלֹהִים וְאֵינֶנּוּ כִּי לָקַח אֹתוֹ אֱלֹהִים. רַבִּי יוֹסֵי פָּתַח, (שיר א) עַד שֶׁהַמֶּלֶךְ בִּמְסִבּוֹ נִרְדִּי נָתַן רֵיחוֹ. פָּסוּק זֶה נֶאֱמַר. אֲבָל בּא רְאֵה, כָּךְ דַּרְכּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא - בְּשָׁעָה שֶׁבֶּן אָדָם נִדְבָּק בּוֹ וְהוּא מַשְׁרֶה דִיּוּרוֹ עָלָיו וְיוֹדֵעַ שֶׁאַחַר יָמִים הוּא יִסְרַח, מַקְדִּים וְלוֹקֵט רֵיחוֹ הַטּוֹב מִמֶּנּוּ וּמְסַלֵּק אוֹתוֹ מֵהָעוֹלָם."],[5,"","זֶהוּ שֶׁכָּתוּב עַד שֶׁהַמֶּלֶךְ בִּמְסִבּוֹ נִרְדִּי נָתַן רֵיחוֹ. עַד שֶׁהַמֶּלֶךְ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. בִּמְסִבּוֹ - זֶה אוֹתוֹ בֶּן אָדָם שֶׁנִּדְבָּק בּוֹ וְהוֹלֵךְ בִּדְרָכָיו. נִרְדִּי נָתַן רֵיחוֹ - אוֹתָם מַעֲשִׂים טוֹבִים שֶׁבּוֹ שֶׁבִּגְלָלָם יִסְתַּלֵּק מֵהָעוֹלָם בְּטֶרֶם הִגִּיעַ זְמַנּוֹ."],[6,"","וְעַל זֶה הָיָה שְׁלֹמֹה הַמֶּלֶךְ אוֹמֵר (קהלת ח) יֵשׁ הֶבֶל אֲשֶׁר נַעֲשָׂה עַל הָאָרֶץ אֲשֶׁר יֵשׁ צַדִּיקִים וְגוֹ'. יֵשׁ צַדִּיקִים אֲשֶׁר מַגִּיעַ אֲלֵיהֶם כְּמַעֲשֵׂה הָרְשָׁעִים - כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁבִּשְׁבִיל מַעֲשִׂים טוֹבִים הַקָּדוֹשׁ בָּרוּךְ הוּא מְסַלְּקָם מֵהָעוֹלָם (כדי שלא יתקלקלו (יחיו), ומתוך אהבתו בהם מסלק אותם) בְּטֶרֶם הִגִּיעַ זְמַנָּם, וְעוֹשֶׂה בָהֶם דִּינִים. וְיֵשׁ רְשָׁעִים שֶׁמַּגִּיעַ אֲלֵהֶם כְּמַעֲשֵׂה הַצַּדִּיקִים - שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַאֲרִיךְ לָהֶם יָמִים וּמַאֲרִיךְ בָּהֶם אֶת רֻגְזוֹ, וְכָל זֶה כְּמוֹ שֶׁנִּתְבָּאֵר. אֵלֶּה בִּשְׁבִיל שֶׁלֹּא יִתְקַלְקְלוּ, וְאֵלֶּה כְּדֵי שֶׁיַּחְזְרוּ אֵלָיו, אוֹ כְּדֵי שֶׁיֵּצְאוּ מֵהֶם בָּנִים מְעֻלִּים."],[7,"","בֹּא רְאֵה, חֲנוֹךְ הָיָה צַדִּיק, וְהַקָּדוֹשׁ בָּרוּךְ הוּא רָאָה שֶׁאַחַר כָּךְ יְקַלְקֵל, וְלָקַח אוֹתוֹ בְּטֶרֶם יְקַלְקֵל. זֶהוּ שֶׁכָּתוּב (שיר ו) וְלִלְקֹט שׁוֹשַׁנִּים. מִשּׁוּם שֶׁנּוֹתְנִים רֵיחַ טוֹב, לוֹקֵחַ אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא בְּטֶרֶם יְקַלְקְלוּ. וְאֵינֶנּוּ כִּי לָקַח אֹתוֹ אֱלֹהִים. וְאֵינֶנּוּ - לְהַאֲרִיךְ יָמִים כִּשְׁאָר בְּנֵי אָדָם שֶׁהָיוּ מַאֲרִיכִים יָמִים. מָה הַטַּעַם? כִּי לָקַח אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּטֶרֶם הִגִּיעַ זְמַנּוֹ."],[8,"","רַבִּי אֶלְעָזָר אָמַר, הַקָּדוֹשׁ בָּרוּךְ הוּא נְטָלוֹ אֶת חֲנוֹךְ וְהֶעֱלָהוּ לִשְׁמֵי מְרוֹמִים, וּמָסַר בְּיָדָיו כָּל הַגְּנָזִים הָעֶלְיוֹנִים וַחֲמִשָּׁה וְאַרְבָּעִים מַפְתְּחוֹת סְתָרִים חֲקוּקִים שֶׁבָּהֶם מִשְׁתַּמְּשִׁים מַלְאָכִים עֶלְיוֹנִים, וְכֻלָּם נִמְסְרוּ בְּיָדוֹ, וַהֲרֵי בֵּאַרְנוּ."],[9,"","וַיַּרְא ה' כִּי רַבָּה רָעַת הָאָדָם בָּאָרֶץ וְכָל יֵצֶר מַחְשְׁבֹת לִבּוֹ. רַבִּי יְהוּדָה פָּתַח, (תהלים ה) כִּי לֹא אֵל חָפֵץ רֶשַׁע אָתָּה לֹא יְגֻרְךְ רָע. פָּסוּק זֶה נֶאֱמַר וּבֵאַרְנוּהוּ. אֲבָל בּא רְאֵה, מִי שֶׁנִּדְבָּק בַּיֵּצֶר הָרָע וְנִמְשָׁךְ אַחֲרָיו, יִטְמָא הוּא וִיטַמְּאוּ אוֹתוֹ, כְּמוֹ שֶׁנִּתְבָּאֵר."],[10,"","כִּי רַבָּה רָעַת הָאָדָם - כָּל הָרָעוֹת הָיוּ עוֹשִׂים, וְלֹא נִשְׁלַם חֶטְאָם עַד שֶׁהָיוּ שׁוֹפְכִים דָּמִים לְחִנָּם עַל הָאָרֶץ. וּמִי הֵם שֶׁהָיוּ מַשְׁחִיתִים דַּרְכָּם עַל הָאָרֶץ? זֶהוּ שֶׁכָּתוּב רַק רַע כָּל הַיּוֹם. כָּתוּב כָּאן רַק רַע, וְכָתוּב שָׁם (לא יגרך רע, וכתוב) (בראשית לח) וַיְהִי עֵר בְּכוֹר יְהוּדָה רַע בְּעֵינֵי ה'."]]],[["אָמַר רַבִּי יוֹסֵי וְכִי רָע לָאו אִיהוּ רָשָׁע. אָמַר לֵיהּ, לָא. רָשָׁע אֲפִלּוּ אָרִים יְדֵיהּ לְגַבֵּי חַבְרֵיהּ, אַף עַל גַּב דְּלָא עָבִיד לֵיהּ מִידִי אִקְרֵי רָשָׁע. כְּמָה דִכְתִיב, (שמות ב׳:י״ג) וַיֹּאמֶר לָרָשָׁע לָמָּה תַכֶּה רֵעֶךָ. הִכִּיתָ לָא כְּתִיב אֶלָּא תַכֶּה.","אֲבָל רַע לא אִקְרֵי אֶלָּא מַאן דִּמְחַבֵּל אָרְחֵיהּ וְסָאִיב גַּרְמֵיהּ וְסָאִיב אַרְעָא וְיָהִיב חֵילָא וְתוּקְפָּא לְרוּחַ מְסָאֳבָא דְּאִקְרֵי רָע דִּכְתִיב רַק רַע כָּל הַיּוֹם. וְלָא עָאל (סט א) בְּפַלְטְרִין וְלָא חָמֵי אַפֵּי שְׁכִינְתָּא. בְּגִין דִּבְהַאי אִסְתַּלַּק שְׁכִינְתָּא מֵעָלְמָא.","מְנָלָן מִיַּעֲקֹב. דְּכַד אִסְתַּלַּק שְׁכִינְתָּא מִנֵּיהּ חָשִׁיב דְּבִבְנוֹהִי הֲוָה פִּיסוּל דִּבְגִינַיְיהוּ אִתְתַּקַּף בְּעָלְמָא רוּחָא מְסָאֳבָא וְגָרַע נְהוֹרָא מִן סִיהֲרָא וּפָגִים לָהּ. וְאִי תֵימָא אַמַּאי. בְּגִין דְּדָא סָאִיב מַקְדְּשָׁא וְאִסְתַּלְּקָא שְׁכִינְתָּא מֵעֲלוֹי דְּיַעֲקֹב. כָּל שֶׁכֵּן הַהוּא דִּמְסָאָב אָרְחֵיהּ וְסָאִיב גַּרְמֵיהּ דְּהוּא אַתְקִיף לֵיהּ לְרוּחָא מְסָאֳבָא. וּבְגִין כָּךְ כַּד אִסְתָּאָב אִקְרֵי רָע.","תָּא חֲזֵי, כַּד בַּר נָשׁ אִסְתָּאָב לָא יִתְפַּקַּד מֵעִם קוּדְשָׁא בְּרִיךְ הוּא לְטַב. וּבְכָל זִמְנָא אִתְפַּקִּיד מֵהַהוּא דְּאִתְקְרֵי רָע לְבִישׁ. הֲדָא הוּא דִכְתִיב, (משלי י״ט:כ״ג) וְשָׂבֵעַ יָלִין בַּל יִפָּקֶד רָע, כַּד אָזִיל בְּאֹרַח מֵישָׁר, כְּדֵין בַּל יִפָּקֶד רָע. וְעַל דָּא כְּתִיב רַק רַע כָּל הַיּוֹם. וּכְתִיב לֹא יְגוּרְךָ רָע. וְדָא אִקְרֵי רָע וְלָא אִקְרֵי רָשָׁע. וּכְתִיב (תהילים כ״ג:ד׳) גַּם כִּי אֵלֵךְ בְּגֵיא צַלְמָוֶת לא אִירָא רָע כִּי אַתָּה עִמָּדִי:","וַיִּנָחֶם יְיָ כִּי עָשָׂה אֶת הָאָדָם בָּאָרֶץ וַיִּתְעַצֵּב אֶל לִבּוֹ. רַבִּי יוֹסֵי פָּתַח (ישעיהו ה׳:י״ח) הוֹי מוֹשְׁכֵי הֶעָוֹן בְּחַבְלֵי הַשָּׁוְא וְכַעֲבוֹת הָעֲגָלָה חַטָּאָה. הוֹי מוֹשְׁכֵי הֶעָוֹן אִלֵּין בְּנִי נָשָׁא דְּחָטָאן קַמֵי מָארֵיהוֹן בְּכָל יוֹמָא, וְאִתְדַּמָּן בְּעֵינַיְיהוּ אִנּוּן חוֹבִין דְּאִנּוּן כְּחַבְלֵי הַשְּׁוָא. וְחָשְׁבִין דְּהַהוּא עוֹבָדָא דְּעָבְדִין וְהַהוּא חוֹבָא דְּעָבְדִין דְּלָאו אִיהוּ כְלוּם וְלָא אַשְׁגַּח בְּהוּ קוּדְשָׁא בְּרִיךְ הוּא. עַד דְּעָבְדִין לְהַהוּא חוֹבָא תַּקִּיף וְרָבֵי כַּעֲבוֹת הָעֲגָלָה דְּאִיהוּ תַּקִּיף דְּלָא יָכִיל לְאִשְׁתֵּצָאָה.","וְתָא חֲזֵי כַּד עָבִיד קוּדְשָׁא בְּרִיךְ הוּא דִּינָא בְּחַיָּיבֵי עָלְמָא, אַף עַל גַּב דְּאִנּוּן חָטָאן קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא וְאַרְגְּזִין לֵיהּ כָּל יוֹמָא. לָא בָּעֵי לְאוֹבָדָא לְהוּ מֵעָלְמָא. וְכַד אַשְׁגַּח בְּעוֹבָדֵיהוֹן אִתְנְחַם עֲלַיְיהוּ עַל דְּאִנּוּן עוֹבְדֵי יְדוֹי וְאוֹרִיךְ לוֹן בְּעָלְמָא.","וּבְגִין דְּאִנּוּן עוֹבָדֵי יְדוֹי נָטִיל נְחָמָה וְאִתְנְחָם עֲלַיְיהוּ וְחַיִיס עֲלַיְיהוּ. וְכַד בָּעֵי לְמֶעְבַּד בְּהוּ דִּינָא כִּבְיָכוֹל עָצִיב (ד\"א ל\"ג חדוון לא תיעול קדמוהי) דְּכֵיוָן דְּעוֹבָדֵי יְדוֹי אִנּוּן, עָצִיב עֲלַיְיהוּ. כְּמָא דְאַתְּ אָמֵר, (דניאל ו׳:י״ט) וְדַחֲוָון לָא הַנְעֵל קָדָמוֹהִי.","כְּתִיב, (ס\"א והא כתיב) (תהילים צ״ו:ו׳) הוֹד וְהָדָר לְפָנָיו עוֹז וְחֶדְוָה בִּמְקוֹמוֹ. אָמַר רַבִּי יוֹסֵי תָּא חֲזֵי, וַיִּתְעַצֵּב אֶל לִבּוֹ כְּתִיב. אֶל לִבּוֹ עָצִיב וְלָא לְאֲתַר אָחֳרָא. לִבּוֹ כְּמָא דְאַתְּ אָמֵר, (שמואל א ב׳:ל״ה) כַּאֲשֶׁר בִּלְבָבִי וּבְנַפְשִׁי יַעֲשֶׂה. רַבִּי יִצְחָק אָמַר וַיִּנָּחֶם יְיָ כְּמָא דְאַתְּ אָמֵר (שמות ל״ב:י״ד) וַיִנָּחֶם יְיָ עַל הָרָעָה אֲשֶׁר דִּבֶּר לַעֲשׂוֹת לְעַמּוֹ.","רַבִּי יֵיסָא אָמַר לְטַב. רַבִּי חִזְקִיָּה אָמַר לְבִישׁ. רַבִּי יֵיסָא אָמַר לְטַב, כְּמָה דְּאִתְּמָר דְּקוּדְשָׁא בְּרִיךְ הוּא נָחִים עַל דְּאִנּוּן עוֹבָדֵי יְדוֹי וְחַיִיס עֲלַיְיהוּ. וַיִּתְעַצֵּב בְּגִין דְּאִנּוּן חָטָאן קַמֵּיהּ.","וְרַבִּי חִזְקִיָּה אָמַר לְבִישׁ דְּכַד קוּדְשָׁא בְּרִיךְ הוּא בָּעֵי לְאוֹבָדָא לְחַיָּיבֵי עָלְמָא נָטִיל נִיחוּמִין עֲלַיְיהוּ וְקַבִּיל נִיחוּמִין. כִּבְיָכוֹל כְּמַאן דִּמְקַבֵּל נִיחוּמִין עַל מַה דְּאֲבִיד. כֵּיוָן דְּקַבֵּל נִיחוּמִין וַדַּאי דִּינָא אִתְעֲבַד וְלָא תַלְיָא מִלְּתָא בִּתְשׁוּבָה.","אֵימָתַי תַּלְיָא בִּתְשׁוּבָה, עַד לָא קַבִּיל תַּנְחוּמִין עֲלַיְיהוּ. הָא קַבִּיל תַּנְחוּמִין עֲלַיְיהוּ לָא תַלְיָיא מִלְּתָא בִּתְשׁוּבָה כְּלַל וְדִינָא אִתְעֲבִיד. וּכְדֵין אוֹסִיף דִּינָא עַל דִּינָא, וְאַתְקִיף (לקמן ע ב) לְהַהוּא אֲתַר דְּדִינָא, לְמֶעְבַּד דִּינָא וְאוֹבִיד לוֹן לְחַיָּיבַיָא מִן עָלְמָא. וְכֹלָּא בַּקְּרָא דִּכְתִיב וַיִּנָּחֶם יְיָ. קִבֵּל תַּנְחוּמִין. וּלְבָתַר וַיִּתְעַצֵּב אֶל לִבּוֹ. יָהַב תּוּקְפָּא לְדִינָא לְמֶעְבַּד דִּינָא.","רַבִּי חִיָּיא אָמַר וַיִּנָּחֶם יְיָ כִּי עָשָׂה אֶת הָאָדָם בָּאָרֶץ. נָטַל תַּנְחוּמִין וְחֶדְוָה, כַּד עֲבַד קוּדְשָׁא בְּרִיךְ הוּא לָאָדָם בְּאַרְעָא דְּאִיהוּ כְּגַוְונָא עִלָּאָה וְכָל מַלְאֲכֵי עִלָּאֵי מְשַׁבְּחָן לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא כַּד חָמוּ לֵיהּ בְּדִיוּקְנָא עִלָּאָה וְאָמָרוּ (תהילים ח׳:ו׳) וַתְּחַסְּרֵהוּ מְעַט מֵאֱלֹהִים וְכָבוֹד וְהָדָר תְּעַטְּרֵהוּ."],[[0,"אמר ר' יוסי וכו':","אר\"י, וכי רע אינו רשע. עד שאתה אומר, שהשם \u0003רע\u0004 מיוחד למוציא זרעו לבטלה. אמר לו, לא. רשע הוא, אפילו אם מרים את ידו על חבירו, ואף על פי שלא עשה לו כלום נקרא רשע. כמו שכתוב, ויאמר לרשע למה תכה רעך. \u0003הכית\u0004 לא כתיב שיהיה משמע שכבר הכה אותו, אלא כתוב \u0003תכה.\u0004 שמשמע שעוד לא הכה אותו. ואע\"פ כן קראו רשע."],[1,"אבל רע לא אקרי וכו':","אבל רע אינו נקרא אלא המשחית דרכו, ומטמא את עצמו, ומטמא את הארץ, ונותן כח ועצמה לרוח הטומאה הנקרא \u0003רע.\u0004 שכתוב רק רע כל היום. ואינו נכנס בהיכל ה', ואינו רואה פני השכינה. משום שבחטא זה, מסתלקת השכינה מן העולם."],[2,"מנלן מיעקב וכו':","מאין לנו, שהשכינה מסתלקת בעון זה, מן יעקב למדנו. כי בשעה שנסתלקה השכינה ממנו חשב שיש פסול בבניו. דהיינו העון הנזכר, שבשבילו נתחזק רוח הטומאה בעולם, וגרע אור הלבנה, שהיא הנוקבא דז\"א, ופגם אותה. שמשום זה נסתלקה ממנו השכינה, ואם תאמר, למה חשב כך. ואומר, משום שעון זה מטמא המקדש, שע\"כ נסתלקה השכינה מיעקב, אע\"פ שהוא עצמו לא חטא. כל שכן מי שמטמא דרכיו ומטמא את עצמו, שהוא מחזק את רוח הטומאה. ומשום זה. כשהוא נטמא, הוא נקרא רע."],[3,"ת\"ח כד בר נש וכו':","בוא וראה. כשהאדם נטמא, בעון הנזכר, לא יהיה נפקד מעם הקב\"ה לטוב. ובכל עת הוא נפקד לרע, מאותו רוח הטומאה הנקרא רע. וע\"כ הוא גורם הסתלקות השכינה. כי בעת שרוח הטומאה פוקד אותו, תכף מסתלקת השכינה. וז\"ש ושבע ילין בל יפקד רע. שפירושו, כאשר הולך בדרך הישר, ואינו נכשל בעון הנז', אז בל יפקד רע. וע\"כ כתוב רק רע כל היום. וכתוב לא יגורך רע. כי זה נקרא רע, ולא רשע. וכתוב, גם כי אלך בגיא צלמות לא אירע \u0003רע\u0004 כי אתה עמדי. הרי, שכן הוא גם להיפך, אם השכינה עמו, אינו מפחד מרוח הטומאה הנקרא רע. כמ\"ש לא אירא רע, כי אתה עמדי. כי כמו שהשכינה בורחת מפני הטומאה הנק' רע, כן הטומאה בורחת מפני השכינה."],[4,"וינחם ה' וגו':","ר' יוסי פתח. הוי מושכי העון בחבלי השוא וגו'. \u0003הוי מושכי העון\u0004 אלו הם האנשים החוטאים לפני הקב\"ה בכל יום והחטאים נדמו בעיניהם, שהם כחבלי השוא, כי חושבים את המעשה שעושים ואותו העון שעושים, שלא כלום הוא, ואין הקב\"ה מסתכל בהם, עד שעושים את העון הזה, לעון חזק וגדול, כעבות העגלה, שהוא חזק ואי אפשר להשחיתו."],[5,"ותא חזי כד וכו':","ובוא וראה: כשהקב\"ה עושה דין ברשעי עולם אע\"פ שהם חוטאים לפני הקב\"ה, ומכעיסים אותו כל היום, אינו רוצה להאבידם מן העולם, וכשמסתכל במעשיהם, מתנחם עליהם על שהם מעשה ידיו ומאריך אפו להם בעולם."],[6,"ובגין דאינון וכו':","ומשום שהם מעשה ידיו מקבל נחמה ומתנחם עליהם, ומרחם עליהם. וכשמבקש לעשות בהם דין, נעצב כביכול, כי משום שהם מעשה ידיו נעצב עליהם כמו שאתה אומר, ודחוון לא הנעל קדמוהי."],[7,"כתיב הוד והדר לפניו וגו':","וכאן אומר ויתעצב וגו'. אר\"י בוא וראה. ויתעצב אל לבו כתוב, להורות, אל לבו נעצב, ולא למקום אחר. \u0003לבו\u0004 הוא כמ\"ש כאשר בלבבי ובנפשי יעשה. שה\"ס הנוקבא. פירוש. הצמצום לא היה אלא באור החכמה ולא באור החסדים. וכיון שהמדרגות שלפני הנוקבא הם כולן באור החסדים (כנ\"ל דף ט\"ז ד\"ה אמר) אין שום אחיזה בהן לקליפות וז\"ס הוד והדר לפניו עוז וחדוה במקומו. כי אין אחיזה לדינים וקליפות. אלא הנוקבא בלבדה שמאירה בהארת חכמה, נאחזים בה כל הדינים והקליפות ויש בה עצבות. וז\"ש \u0003אל לבו עצוב,\u0004 שהוא הנוקבא, \u0003ולא לאחר אחרא,\u0004 ולא לשום מקום שלמעלה מהנוקבא, כי הם מאירים בחסדים מכוסים שאין אחיזה בהם לדינים."],[7,"רבי יצחק אמר וכו':","רי\"א \u0003וינחם ה'\u0004 פירושו, כמו שאתה אומר וינחם ה' על הרעה אשר דבר לעשות לעמו. ושיעור הכתוב הוא וינחם ה', כי עשה את האדם, היינו שלא היה רוצה להענישם, ומשום זה כשהגיע הזמן לעשות בהם דין, ויתעצב אל לבו."],[8,"ר' ייסא אמר לטב וכו':","ר\"י אמר, בפירוש הכתוב וינחם וגו', שהוא לטוב. ר' חזקיה אמר שהוא לרע. ומפרש: ר' ייסא אמר לטוב, כמו שאמרנו, שהקב\"ה נחם על שהם מעשה ידיו, ומרחם עליהם ושיעור הכתוב \u0003וינחם ה',\u0004 שרחם הקב\"ה, בשביל, כי עשה את האדם. והוא מעשה ידיו."],[9,"ורבי חזקיה וכו':","ור\"ח אמר לרע. כי כשהקב\"ה מבקש להאביד את רשעי עולם, מקבל מקודם תנחומים עליהם. וכביכול, מקבל תנחומים, כמי שמקבל תנחומים על מה שאבד. כיון שקבל תנחומים, ודאי שהדין נעשה, ואין הדבר תלוי עוד בתשובה."],[10,"אימתי תליא וכו':","מתי תלוי בתשובה. הוא, מטרם שקבל תנחומים עליהם, כיון שקבל תנחומים עליהם, אין הדבר תלוי כלום בתשובה והדין נעשה. ואז מוסיף הקב\"ה דין על דין, ומחזק את מקום הדין שהוא הנוקבא לעשות הדין, ומאביד את הרשעים מן העולם. והכל הוא בהכתוב, שכתוב, \u0003וינחם ה'\u0004 היינו שקבל תנחומים, ואח\"כ \u0003ויתעצב אל לבו,\u0004 היינו שנתן חיזוק למקום הדין, לעשות הדין. כי \u0003לבו\u0004 ה\"ס הנוקבא המכונה לב, שהיא מקום הדין, \u0003ויתעצב,\u0004 פירושו שנתן תוקף וחיזוק."],[11,"ר' חייא וכו':","רח\"א וינחם ה' וגו', היינו שקבל תנחומים וחדוה. כי בשעה שעשה הקב\"ה את האדם בארץ, שהיה כמו העליונים. כל מלאכי מרום היו משבחים להקב\"ה, כשראו אותו בצורה עליונה, ואמרו ותחסרהו מעט מאלקים וכבוד והדר תעטרהו."]],[[0,"","אָמַר רַבִּי יוֹסֵי, וְכִי רָע אֵינוֹ רָשָׁע? אָמַר לוֹ, לֹא. רָשָׁע - אֲפִלּוּ הֵרִים יָדוֹ עַל חֲבֵרוֹ, אַף עַל גַּב שֶׁלֹּא עָשָׂה לוֹ דָבָר, נִקְרָא רָשָׁע, כְּמוֹ שֶׁכָּתוּב (שמות ב) וַיֹּאמֶר לָרָשָׁע לָמָּה תַכֶּה רֵעֶךְ. הִכִּיתָ לֹא כָתוּב, אֶלָּא תַּכֶּה."],[1,"","אֲבָל רַע לֹא נִקְרָא אֶלָּא מִי שֶׁמַּשְׁחִית דַּרְכּוֹ וּמְטַמֵּא עַצְמוֹ וּמְטַמֵּא אֶת הָאָרֶץ, וְנוֹתֵן כֹּחַ וְחֹזֶק לְרוּחַ הַטֻּמְאָה שֶׁנִּקְרֵאת רַע, שֶׁכָּתוּב רַק רַע כָּל הַיּוֹם. וְלֹא נִכְנָס בְּפַלְטֵרִין וְלֹא רוֹאֶה פְּנֵי שְׁכִינָה, מִשּׁוּם שֶׁבָּזֶה מִסְתַּלֶּקֶת שְׁכִינָה מִן הָעוֹלָם."],[2,"","וּמִנַּיִן לָנוּ? מִיַּעֲקֹב. שֶׁכְּשֶׁהִסְתַּלְּקָה מִמֶּנּוּ שְׁכִינָה, חָשַׁב שֶׁיֵּשׁ פְּסוּל בְּבָנָיו שֶׁבִּגְלָלָם הִתְחַזְּקָה בָּעוֹלָם רוּחַ הַטֻּמְאָה וְנִגְרַע הָאוֹר מֵהַלְּבָנָה וּפָגַם אוֹתָהּ. וְאִם תֹּאמַר לָמָּה? מִשּׁוּם זֶה מְטַמֵּא אֶת הַמִּקְדָּשׁ וְהִסְתַּלְּקָה שְׁכִינָה מֵעַל יַעֲקֹב. כָּל שֶׁכֵּן אוֹתוֹ שֶׁמְּטַמֵּא דַרְכּוֹ וּמְטַמֵּא עַצְמוֹ שֶׁהוּא מְחַזֵּק אֶת רוּחַ הַטֻּמְאָה, וְלָכֵן כְּשֶׁנִּטְמָא נִקְרָא רַע."],[3,"","בֹּא רְאֵה, כְּשֶׁבֶּן אָדָם נִטְמָא, לֹא נִפְקָד מִן הַקָּדוֹשׁ בָּרוּךְ הוּא לְטוֹב, וּבְכָל פַּעַם נִפְקָד מֵאוֹתוֹ שֶׁנִּקְרָא רַע לְרַע. זֶהוּ שֶׁכָּתוּב (משלי יט) וְשָׂבֵעַ יָלִין בַּל יִפָּקֶד רָע. כְּשֶׁהוֹלֵךְ בְּדֶרֶךְ יָשָׁר, אָז בַּל יִפָּקֶד רָע. וְעַל זֶה כָּתוּב רַק רַע כָּל הַיּוֹם, וְכָתוּב לֹא יְגֻרְךְ רָע. וְזֶה נִקְרָא רַע וְלֹא נִקְרָא רָשָׁע. וְכָתוּב (תהלים כג) גַּם כִּי אֵלֵךְ בְּגֵיא צַלְמָוֶת לֹא אִירָע רָע כִּי אַתָּה עִמָּדִי."],[4,"","וַיִּנָּחֶם ה' כִּי עָשָׂה אֶת הָאָדָם בָּאָרֶץ וַיִּתְעַצֵּב אֶל לִבּוֹ. רַבִּי יוֹסֵי פָּתַח, (ישעיה ה) הוֹי מוֹשְׁכֵי הֶעָון בְּחַבְלֵי הַשָּׁוְא וְכַעֲבוֹת הָעֲגָלָה חַטָּאָה. הוֹי מוֹשְׁכֵי הֶעָון - אֵלּוּ בְּנֵי אָדָם שֶׁחוֹטְאִים לִפְנֵי רִבּוֹנָם בְּכָל יוֹם, וְנִדְמִים בְּעֵינֵיהֶם אוֹתָם חֲטָאִים שֶׁהֵם כְּחַבְלֵי הַשָּׁוְא, וְחוֹשְׁבִים שֶׁאוֹתוֹ מַעֲשֶׂה שֶׁעָשׂוּ וְאוֹתוֹ חֵטְא שֶׁעָשׂוּ שֶׁאֵינוֹ כְלוּם, וְלֹא מַשְׁגִּיחַ בָּהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא עַד שֶׁעוֹשִׂים אֶת אוֹתוֹ חֵטְא חָזָק וְגָדוֹל כַּעֲבוֹת הָעֲגָלָה, שֶׁהוּא חָזָק שֶׁלֹּא יוּכַל לְהִתְכַּלּוֹת."],[5,"","וּבֹא וּרְאֵה, כְּשֶׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא דִּין בְּרִשְׁעֵי הָעוֹלָם, אַף עַל גַּב שֶׁהֵם חָטְאוּ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְהִרְגִּיזוּ אוֹתוֹ כָּל יוֹם, אֵינוֹ רוֹצֶה לְאַבֵּד אוֹתָם מֵהָעוֹלָם. וּכְשֶׁמַּשְׁגִּיחַ בְּמַעֲשֵׂיהֶם, מִתְנַחֵם עֲלֵיהֶם עַל שֶׁהֵם מַעֲשֵׂי יָדָיו וּמַאֲרִיךְ לָהֶם בָּעוֹלָם."],[6,"","וּבִגְלַל שֶׁהֵם מַעֲשֵׂי יָדָיו, נוֹטֵל נֶחָמָה וּמִתְנַחֵם עֲלֵיהֶם וְחָס עֲלֵיהֶם. וּכְשֶׁרוֹצֶה לַעֲשׂוֹת בָּהֶם דִּין, כִּבְיָכוֹל הוּא עָצוּב (ד\"א שמחות לא יכנסו לפניו). שֶׁכֵּיוָן שֶׁהֵם מַעֲשֵׂי יָדָיו, הוּא עָצוּב עֲלֵיהֶם, כְּמוֹ שֶׁנֶּאֱמַר (דניאל ו) וּשְׂמָחוֹת לֹא הִכְנִיס לְפָנָיו."],[7,"","כָּתוּב (ס\"א והרי כתוב) (תהלים צו) הוֹד וְהָדָר לְפָנָיו עֹז וְחֶדְוָה בִּמְקוֹמוֹ. אָמַר רַבִּי יוֹסֵי, בּא רְאֵה, וַיִּתְעַצֵּב אֶל לִבּוֹ כָּתוּב. הוּא הִתְעַצֵּב אֶל לִבּוֹ וְלֹא לְמָקוֹם אַחֵר. לִבּוֹ, כְּמוֹ שֶׁנֶּאֱמַר (שמואל א ב) כַּאֲשֶׁר בִּלְבָבִי וּבְנַפְשִׁי יַעֲשֶׂה. רַבִּי יִצְחָק אָמַר, וַיִּנָּחֶם ה', כְּמוֹ שֶׁנֶּאֱמַר (שמות לב) וַיִּנָּחֶם ה' עַל הָרָעָה אֲשֶׁר דִּבֶּר לַעֲשׂוֹת לְעַמּוֹ."],[8,"","רַבִּי יֵיסָא אָמַר לְטוֹב. רַבִּי חִזְקִיָּה אָמַר לְרַע. רַבִּי יֵיסָא אָמַר לְטוֹב, כְּמוֹ שֶׁנִּתְבָּאֵר שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְנַחֵם עַל אוֹתָם מַעֲשֵׂי יָדָיו וְחָס עֲלֵיהֶם. וַיִּתְעַצֵּב, מִשּׁוּם שֶׁהֵם חוֹטְאִים לְפָנָיו."],[9,"","וְרַבִּי חִזְקִיָּה אָמַר לְרַע, שֶׁכְּשֶׁרוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לְאַבֵּד רִשְׁעֵי הָעוֹלָם, נוֹטֵל עֲלֵיהֶם נִחוּמִים וּמְקַבֵּל נִחוּמִים, כִּבְיָכוֹל כְּמִי שֶׁמְּקַבֵּל נִחוּמִים עַל מַה שֶּׁאָבַד. כֵּיוָן שֶׁקִּבֵּל נִחוּמִים, וַדַּאי נַעֲשָׂה דִין, וְלֹא תָלוּי הַדָּבָר בִּתְשׁוּבָה."],[10,"","אֵימָתַי זֶה תָלוּי בִּתְשׁוּבָה? עַד שֶׁלֹּא קִבֵּל עֲלֵיהֶם תַּנְחוּמִים. הֲרֵי שֶׁקִּבֵּל עֲלֵיהֶם תַּנְחוּמִים, אָז הַדָּבָר כְּבָר לֹא תָלוּי בִּתְשׁוּבָה כְּלָל וְהַדִּין נַעֲשָׂה. וְאָז מוֹסִיף דִּין עַל דִּין וּמְחַזֵּק אֶת אוֹתוֹ מְקוֹם הַדִּין לַעֲשׂוֹת דִּין, וּמְאַבֵּד אֶת הָרְשָׁעִים מֵהָעוֹלָם, וְהַכֹּל בַּכָּתוּב, שֶׁכָּתוּב וַיִּנָּחֶם ה', קִבֵּל תַּנְחוּמִים. וְאַחַר כָּךְ וַיִּתְעַצֵּב אֶל לִבּוֹ, נָתַן כֹּחַ לַדִּין לַעֲשׂוֹת דִּין."],[11,"","רַבִּי חִיָּיא אָמַר, וַיִּנָּחֶם ה' כִּי עָשָׂה אֶת הָאָדָם בָּאָרֶץ - נָטַל תַּנְחוּמִים וְחֶדְוָה. כְּשֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָאָדָם בָּאָרֶץ, שֶׁהוּא כְּדֻגְמָא עֶלְיוֹנָה, וְכָל הַמַּלְאָכִים הָעֶלְיוֹנִים מְשַׁבְּחִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁרָאוּ אוֹתוֹ בִּדְמוּת עֶלְיוֹנָה, וְאָמְרוּ (תהלים ח) וַתְּחַסְּרֵהוּ מְּעַט מֵאֱלֹהִים וְכָבוֹד וְהָדָר תְּעַטְּרֵהוּ."]]],[["לְבָתַר כַּד חָטָא אָדָם אִתְעַצֵּב קוּדְשָׁא בְּרִיךְ הוּא עַל דְּחָטָא. דְּיָהַב פִּתְחוֹן פֶּה לְמַלְאֲכֵי הַשָּׁרֵת דְּאָמְרוּ קַמֵּיהּ בְּקַדְמִיתָא כַּד בָּעָא לְמִבְרֵי לֵיהּ, מָה אֱנוֹשׁ כִּי תִזְכְּרֶנּוּ וּבֶן אָדָם כִּי תִפְקְדֶנּוּ.","אָמַר רַבִּי יְהוּדָה וַיִּתְעַצֵּב אֶל לִבּוֹ בְּגִין דְּבָעֵי לְמֶעְבַּד בְּהוּ דִּינָא שֶׁנֶּאֱמַר (דברי הימים ב ב) בְּצֵאת לִפְנֵי הֶחָלוּץ וְאוֹמְרִים הוֹדוּ לַיְיָ כִּי לְעוֹלָם חַסְדּוֹ. וְאָמַר רַבִּי יִצְחָק אַמַּאי לָא כְּתִיב הָכָא כִּי טוֹב. אֶלָּא בְּגִין דְּאוֹבִיד עוֹבְדֵי יְדוֹי קַמַּיְיהוּ דְּיִשְׂרָאֵל.","כְּגַוְונָא דָא כַּד הֲווּ יִשְׂרָאֵל עָבְרִין יַמָּא. אָתוּ מַלְאֲכֵי עִלָּאֵי לְמֵימַר שִׁירָה קַמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא בְּהַהוּא לֵילְיָא. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא וּמַה עוֹבָדֵי יַדָי טָבְעִין בְּיַמָּא וְאַתּוּן אָמְרִין שִׁירָה. כְּדֵין (שמות י״ד:כ׳) וְלֹא קָרַב זֶה אֶל זֶה כָּל הַלָּיְלָה. אוּף הָכָא בְּכָל זִמְנִין דְּאִיבּוּד רַשִּׁיעַיָא אִיהוּ מֵעָלְמָא כְּדֵין עֲצִיבוּ אִשְׁתְּכַח עֲלַיְיהוּ.","רַבִּי אַבָּא אָמַר בְּשַׁעֲתָא דְּחָב קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא אָדָם וְעָבַר עַל פִּקּוּדוֹי, כְּדֵין אִשְׁתְּכַח עֲצִיבוּ קַמֵּיהּ. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא אָדָם וַוי דְּחָלְשַׁת חֵילָא עִלָּאָה. בְּהַאי שַׁעֲתָא אִתְחַשְׁכַת נְהוֹרָא חַד. מִיָּד תָּרִיךְ לֵיהּ מִגִּנְתָּא דְעֵדֶן.","אָמַר לֵיהּ אֲנָא אַעֲלִית לָךְ לְגִנְתָּא דְעֵדֶן לְקָרְבָא קָרְבָּנָא. וְאַתְּ פְּגִימַת מַדְבְּחָא דְּלָא אִתְקְרַב קָרְבָּנָא. מִכָּאן וּלְהָלְאָה לַעֲבוֹד אֶת הָאֲדָמָה. וְגָזַר עֲלֵיהּ מִיתָה. וְחָס עֲלֵיהּ קוּדְשָׁא בְּרִיךְ הוּא וְגָנִיז לֵיהּ בְּשַׁעֲתָא דְמִית סָמִיךְ לְגִנְתָּא.","מַה עֲבַד אָדָם עֲבַד מְעַרְתָּא חָדָא וְאִתְטַמַּר בָּהּ הוּא וְאִתְּתֵיהּ. מְנָא יָדַע. אֶלָּא חָמָא חַד נְהוֹרָא דַּקִּיק עָיִיל בְּהַהוּא אֲתַר דְּנָפִיק מִגִּנְתָּא דְעֵדֶן וְתָאַב תֵּיאוּבְתֵּיהּ לְקִבְרֵיהּ. וְתַמָּן הוּא אֲתַר סָמוּךְ לִתְרַע דְּגִנְתָּא דְּעֵדֶן.","תָּא חֲזֵי, לָא אִסְתַּלַּק בַּר נָשׁ מֵעָלְמָא עַד דְּחָמֵי לֵיהּ לְאָדָם הָרִאשׁוֹן. שָׁאִיל לֵיהּ עַל מָה אָזִיל מֵעָלְמָא וְהֵיךְ נָפִיק. הוּא אָמַר לֵיהּ וַוי דִּבְגִינָךְ נְפַקְנָא מֵעָלְמָא. וְהוּא אָתִיב לֵיהּ בְּרִי אֲנָא עֲבָרִית עַל פִּקּוּדָא חָדָא וְאִתְעֲנָּשִׁית בְּגִינָהּ. חָמֵי אַתְּ כַּמָּה חוֹבִין וְכַמָּה פִּקּוּדִין דְּמָארָךְ עֲבַרְתְּ.","אָמַר רַבִּי חִיָּיא עַד כְּדוֹ יוֹמָא קָאִים אָדָם הָרִאשׁוֹן וְחָזֵי בַּאֲבָהָן תְּרֵין זִמְנִין בְּיוֹמָא וְאוֹדֵי עַל חוֹבוֹי. וְאַחְמֵי לוֹן הַהוּא אֲתַר דְּהֲוָה בֵּיהּ בִּיקָרָא עִלָּאָה. וְאָזִיל וְחָמֵי כָּל אִנּוּן צַדִּיקַיָּיא וְחֲסִידֵי דְּנָפְקוּ מִנִּיהּ וְיָרְתוּ לְהַהוּא יְקָרָא עִלָּאָה דִּבְגִנְתָּא דְעֵדֶן. וְאֲבָהָן כֻּלְהוֹן אוֹדָן וְאָמְרִין (תהילים ל״ו:ח׳) מַה יָּקָר חַסְדְּךָ אֱלֹהִים וּבְנֵי אָדָם בְּצֵל כְּנָפֶיךָ יֶחסָיוּן.","רַבִּי יֵיסָא אָמַר כֻּלְהוּ בְּנֵי עָלְמָא חָמָאן לֵיהּ לְאָדָם הָרִאשׁוֹן בְּשַׁעֲתָא דְּמִסְתַּלְּקֵי מִן עָלְמָא, לְאַחֲזָאָה סַהֲדוּתָא דִּבְגִין חוֹבוֹי דְּבַר נָשׁ אִיהוּ אִסְתַּלַּק מֵעָלְמָא וְלָא בְגִינֵיהּ דְּאָדָם. כְּמָה דִּתְנִינָן אֵין מִיתָה בְּלא חֵטְא.","בַּר אִנּוּן תְּלָתָא דְּאִסְתַּלָּקוּ בְּגִין הַהוּא עֵיטָא דְּנָחָשׁ הַקַּדְמוֹנִי. וְאִלֵּין אִנּוּן, עַמְרָם לֵוִי וּבִנְיָמִין. וְאִית דְּאָמְרֵי אוּף נָמֵי יִשַּׁי. דְּלָא חָבוּ וְלָא אִשְׁתְּכַח עֲלַיְיהוּ חוֹבָא דִּימוּתוּן בֵּיהּ, בַּר דְּאַדְכַּר עֲלַיְיהוּ הַהוּא עֵיטָא דְּנָחָשׁ כִּדְאֲמָרָן.","תָּא חֲזֵי, כֻּלְהוֹן דָּרִין דְּהֲווּ בְּיוֹמוֹי דְּנֹחַ כֻּלְהוּ אַפְשִׁיטוּ חוֹבִין עַל עָלְמָא בְּאִתְגַּלְיָא לְעֵינֵיהוֹן דְּכֹלָּא. רַבִּי שִׁמְעוֹן הֲוָה אָזִיל יוֹמָא חַד בְּפִילֵי דִטְבֶרְיָה, חָמָא בְּנִי נְשָׁא דְּהֲוֵי מְקַטְרֵי בְּקִיטְרָא דְקַשְׁתָּא בְּקוּלְפָא דְּקַנְסִיר. אָמַר וּמַה חוֹבָא דָא בְּאִתְגַּלְיָא לְאַרְגָּזָא לְמָרֵיהוֹן. יָהִיב עֵינוֹי בְּהוּ וְאִתְרְמִיּוּ לְגוֹ יַמָּא וּמִיתוּ.","תָּא חֲזֵי, כָּל חוֹבָא דְּאִתְעֲבִיד בְּאִתְגַּלְיָא דָּחֵי לָהּ לִשְׁכִינְתָּא מֵאַרְעָא וּסְלִיקַת דִּיּוּרָהּ מֵעָלְמָא. אִלֵּין הֲווּ אָזְלִין בְּרִישָׁא זָקִיף וְעַבְדֵי חוֹבַיְיהוּ בְּאִתְגַלְיָיא וְדָחוּ לָהּ לִשְׁכִינְתָּא מֵעָלְמָא. עַד דְּקוּדְשָׁא בְּרִיךְ הוּא דָּחָא לוֹן וְאַעֲבִיר לוֹן מִנֵּיהּ. וְעַל דָּא כְּתִיב (משלי כ״ה:ה׳) הָגוֹ רָשָׁע לִפְנִי מֶלֶךְ וְגו' הָגוֹ סִגִּים מִכֶּסֶף וְגו':","וַיֹּאמֶר יְיָ לֹא יָדוֹן רוּחִי בָּאָדָם לְעוֹלָם בְּשַׁגָּם הוּא בָּשָׂר וְגו'. אָמַר רַבִּי אֶלְעָזָר תָּא חֲזֵי, כַּד בְּרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא עֲבַד לְהַאי עָלְמָא לְאִשְׁתַּמָּשָׁא כְּגַוְונָא דִלְעֵילָא. וְכַד בְּנֵי עָלְמָא אִנּוּן זַכָּאִין דְּאָזְלֵי בְּאֹרַח מֵישָׁר, קוּדְשָׁא בְּרִיךְ הוּא אַתְעַר רוּחָא דְחַיֵּי דִּלְעֵילָא עַד דְּמָטוּ אִנּוּן חַיִּין לְאֲתַר דְּיַעֲקֹב שַׁרְיָא בֵּיהּ."],[[0,"לבתר כד וכו':","אחר כך, כשהאדם חטא, נעצב הקב\"ה על שחטא, כי נתן פתחון פה למלאכי השרת שאמרו לפניו מתחילה כשרצה לברוא האדם, מה אנוש כי תזכרנו ובן אדם כי תפקדנו. ושיעור הכתוב, \u0003וינחם ה'\u0004 וגו' הוא, מטרם שחטא, שקבל אז מהמלאכים תנחומים וחדוה. \u0003ויתעצב\u0004 וגו' הוא, אחר שחטא."],[1,"אמר ר' יהודה וכו':","אר\"י ויתעצב אל לבו, הוא משום שבקש לעשות בהם דין. שנאמר, בצאת לפני החלוץ ואומרים הודו לה' כי לעולם חסדו. ואמר ר' יצחק למה לא כתוב כאן הודו לה' כי טוב, הוא משום שהאביד מעשה ידיו בשביל ישראל."],[2,"כגוונא דא וכו':","כעין זה, כשעברו ישראל את הים. באו מלאכי השרת לומר באותה הלילה שירה לפני הקב\"ה אמר להם הקב\"ה. והרי מעשי ידי טובעים בים ואתם אומרים שירה. אז ולא קרב זה אל זה כל הלילה. אף כאן, כל פעם שיש איבוד רשעים בעולם, נמצא לפניו עצבות. פי' כי \u0003זה אל זה,\u0004 רומז על המלאכים שכתוב בהם וקרא זה אל זה ואמר וגו'. ולא קרב זה אל זה כל הלילה, היינו שלא אמרו כלום כל הלילה."],[3,"ר' אבא וכו':","ר\"א אמר, בשעה שאדם חטא לפני הקב\"ה, ועבר על מצותו אז נמצא עצבות לפניו. אמר לו הקב\"ה: אדם, ווי שהחלשת כח העליון. באותה שעה נחשך אור אחד. דהיינו הנוקבא. (כנ\"ל באות ת\"ב) מיד גרש אותו מגן עדן."],[4,"א\"ל אנא אעלית וכו':","אמר לו אני הכנסתיך לגן עדן להקריב קרבן, לעשות יחוד קב\"ה ושכינתיה, ואתה פגמת את המזבח, שהיא הנוקבא, עד שאי אפשר עוד להקריב קרבן. מכאן ולהלאה, לך מכאן, לעבוד את האדמה. וגזר עליו מיתה. והקב\"ה חס עליו, וכשמת קבר אותו סמוך לגן, דהיינו במערת המכפלה ששם פתח גן עדן. כמ\"ש להלן בפרשת לך דף ל\"ז אות צ\"ה."],[5,"מה עבד וכו':","מה עשה אדם. עשה מערה אחת, היינו מערת המכפלה, והתחבאו בה אדם ואשתו. מאין ידע, לבחור במקום ההוא. אלא ראה שם אור אחד דק, שיצא מגן עדן, ונכנס באותו המקום. ונתעורר חשקו להקבר שם. ושם הוא מקום סמוך לפתח גן עדן."],[6,"תא חזי לא אסתלק וכו':","בוא וראה, אין בן אדם נפטר מן העולם עד שרואה לאדם הראשון. ושואל אותו אדם הראשון, על מה הלך מן העולם, ואיך יצא נשמתו. והוא אומר לו: ווי כי בשבילך יצאתי מן העולם. דהיינו בשביל שחטא בעץ הדעת ונגזר מיתה לבני אדם. ואדם הראשון משיב לו: בני, אני עברתי על מצוה אחת, ונענשתי בשבילה, אתה, ראה, כמה עבירות וכמה מצות רבונך, עברת ולא קימת."],[7,"אמר ר' חייא וכו':","אר\"ח, עד היום הזה, עומד אדם הראשון, ורואה את האבות ב' פעמים ביום, ומתודה על חטאיו. ומראה להם אותו מקום שבגן עדן, שהיה בו בכבוד העליון מטרם שחטא. והולך ורואה, כל אלו הצדיקים והחסידים שיצאו ממנו, וירשו אותו כבוד העליון שבגן עדן, שהיה בו קודם חטאו. והאבות, כולם מודים ואומרים, מה יקר חסדך אלקים ובני אדם בצל כנפיך יחסיון."],[8,"ר' ייסא אמר וכו':","רי\"א, הטעם, אשר כל בני העולם רואים את אדם הראשון, בשעה שנפטרים מן העולם, הוא, להעיד עדות, שבשביל חטאיו עצמו של כל איש, הוא נפטר מן העולם, ולא בשביל חטאו של אדם הראשון. כמו שלמדנו, אין מיתה בלא חטא."],[9,"בר אינון וכו':","לבד מאלו השלשה, שנפטרו בשביל העצה של נחש הקדמוני, שיעץ לחוה לאכול מעץ הדעת, ולא מתו בחטאיהם עצמם, ואלו הם עמרם לוי ובנימין. ויש אומרים גם ישי שהם לא חטאו ולא נמצא בהם שום חטא שימותו בשבילו, לבד ממה שנזכר עליהם העצה של הנחש, כמו שאמרנו."],[10,"תא חזי כלהון וכו':","בוא וראה. כל הדורות שהיו בימי נח, כולם הפשיטו, היינו שגילו את עונותיהם בעולם, בגלוי לעיני כל. ר\"ש היה מהלך יום אחד בשערי טבריה. ראה בני אדם, שהיו מקשרים חצים בקשרי הקשת ויורים לתוך כדי חרס. כלומר, שהיו מוציאים זרע לבטלה בפרהסיא. אמר למה הם עושים עון זה בגלוי, הוא רק להכעיס את רבונם, נתן עיניו בהם, והושלכו תוך הים ומתו."],[11,"ת\"ח כל חובא וכו':","בוא וראה. כל חטא הנעשה בגלוי, דוחה את השכינה מן הארץ, ונעלה משכנה מן העולם. אלו שבדור המבול, היו מהלכים בראש זקוף, בלי בושה, ועשו עונם בגלוי ודחו את השכינה מן העולם, עד שהקב\"ה דחה אותם, והעבירם מעל פניו. כמ\"ש הגו רשע לפני, מלך וגו'. הגו סגים מכסף וגו'."],[12,"ויאמר ה' לא ידון רוחי וגו':","אמר ר' אלעזר בוא וראה, כשברא הקב\"ה את העולם, עשה את עולם הזה שהוא מלכות, להשתמש בה, כמו עולם העליון שהיא בינה. כלומר שכל האורות המאירים בבינה, עשה שיאירו גם במלכות, שה\"ס עולם הזה. וכשבני העולם הם צדיקים, שהולכים בדרך הישר, הקב\"ה מעורר את רוח החיים שהם המוחין, של מעלה שבבינה, עד שהחיים הללו מגיעים להמקום שיעקב שורה בו, שהיא ז\"א כי מבינה הם נמשכים לז\"א, כנודע."]],[[0,"","אַחַר כָּךְ כְּשֶׁחָטָא אָדָם, הִתְעַצֵּב הַקָּדוֹשׁ בָּרוּךְ הוּא עַל שֶׁחָטָא. שֶׁנָּתַן פִּתְחוֹן פֶּה לְמַלְאֲכֵי הַשָּׁרֵת שֶׁאָמְרוּ לְפָנָיו בַּתְּחִלָּה כְּשֶׁרָצָה לִבְרֹא אוֹתוֹ, מָה אֱנוֹשׁ כִּי תִזְכְּרֶנּוּ וּבֶן אָדָם כִּי תִפְקְדֶנּוּ."],[1,"","אָמַר רַבִּי יְהוּדָה, וַיִּתְעַצֵּב אֶל לִבּוֹ, כִּי רָצָה לַעֲשׂוֹת בָּהֶם דִּין, שֶׁנֶּאֱמַר (דברי הימים ב כ) בְּצֵאת לִפְנֵי הֶחָלוּץ וְאֹמְרִים הוֹדוּ לַה' כִּי לְעוֹלָם חַסְדּוֹ. וְאָמַר רַבִּי יִצְחָק, לָמָּה לֹא כָתוּב כָּאן כִּי טוֹב? אֶלָּא מִשּׁוּם שֶׁהֶאֱבִיד אֶת מַעֲשֵׂי יָדָיו מִפְּנֵי יִשְׂרָאֵל."],[2,"","כְּמוֹ זֶה כְּשֶׁהָיוּ יִשְׂרָאֵל עוֹבְרִים אֶת הַיָּם, בָּאוּ מַלְאָכִים עֶלְיוֹנִים לוֹמַר שִׁירָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתוֹ לַיְלָה. אָמַר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא: וּמָה מַעֲשֵׂי יָדַי טוֹבְעִים בַּיָּם, וְאַתֶּם אוֹמְרִים שִׁירָה!? אָז (שמות יד) וְלֹא קָרַב זֶה אֶל זֶה כָּל הַלָּיְלָה. גַּם כָּאן, בְּכָל הַפְּעָמִים שֶׁל אִבּוּד רְשָׁעִים מֵהָעוֹלָם, אָז נִמְצֵאת עֲלֵיהֶם עַצְבוּת."],[3,"","רַבִּי אַבָּא אָמַר, בְּשָׁעָה שֶׁחָטָא אָדָם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְעָבַר עַל מִצְוָתוֹ, אָז נִמְצְאָה עַצְבוּת לְפָנָיו. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: אָדָם, אוֹי שֶׁהֶחֱלַשְׁתָּ אֶת הַכֹּחַ הָעֶלְיוֹן. בְּשָׁעָה זוֹ נֶחְשַׁךְ מָאוֹר אֶחָד. מִיָּד גֵּרַשׁ אוֹתוֹ מִגַּן עֵדֶן."],[4,"","אָמַר לוֹ: אֲנִי הִכְנַסְתִּי אוֹתְךְ לְגַן עֵדֶן לְהַקְרִיב קָרְבָּן, וְאַתָּה פָּגַמְתָּ אֶת הַמִּזְבֵּחַ שֶׁלֹּא נִקְרָב הַקָּרְבָּן!? מִכָּאן וָהָלְאָה - לַעֲבֹד אֶת הָאֲדָמָה. וְגָזַר עָלָיו מִיתָה. וְחָס עָלָיו הַקָּדוֹשׁ בָּרוּךְ הוּא וּגְנָזוֹ בְּשָׁעָה שֶׁמֵּת סָמוּךְ לַגָּן."],[5,"","מֶה עָשָׂה אָדָם? עָשָׂה מְעָרָה אַחַת וְהִסְתַּתֵּר בָּהּ הוּא וְאִשְׁתּוֹ. מֵאֵיפֹה יָדַע? אֶלָּא רָאָה אוֹר דַּקִּיק אֶחָד שֶׁנִּכְנַס בְּאוֹתוֹ מָקוֹם שֶׁיּוֹצֵא מִגַּן עֵדֶן, וְהִתְאַוָּה תַאֲוָתוֹ לְקִבְרוֹ, וְשָׁם הוּא מָקוֹם סָמוּךְ לְשַׁעַר גַּן עֵדֶן."],[6,"","בֹּא רְאֵה, לֹא מִסְתַּלֵּק אָדָם מֵהָעוֹלָם עַד שֶׁיִּרְאֶה אֶת אָדָם הָרִאשׁוֹן. שׁוֹאֵל אוֹתוֹ: עַל מָה הָלַךְ מֵהָעוֹלָם וְאֵיךְ יָצָא? הוּא אוֹמֵר לוֹ: אוֹי שֶׁבִּגְלָלְךְ יָצָאתִי מֵהָעוֹלָם. וְהוּא מֵשִׁיב לוֹ: בְּנִי, אֲנִי עָבַרְתִּי עַל מִצְוָה אַחַת וְנֶעֱנַשְׁתִּי בִּשְׁבִילָהּ, רְאֵה אַתָּה כַּמָּה חֲטָאִים וְכַמָּה מִצְווֹת שֶׁל רִבּוֹנְךְ עָבַרְתָּ."],[7,"","אָמַר רַבִּי חִיָּיא, עַד הַיּוֹם הַזֶּה עוֹמֵד אָדָם הָרִאשׁוֹן וְרוֹאֶה אֶת הָאָבוֹת פַּעֲמַיִם בְּיוֹם וּמוֹדֶה עַל חֶטְאוֹ, וּמַרְאֶה לָהֶם אֶת אוֹתוֹ מָקוֹם שֶׁהָיָה בּוֹ בְּכָבוֹד עֶלְיוֹן, וְהוֹלֵךְ וְרוֹאֶה כָּל אוֹתָם הַצַּדִּיקִים וַחֲסִידִים שֶׁיָּצְאוּ מִמֶּנּוּ וְיָרְשׁוּ אֶת אוֹתוֹ כָבוֹד עֶלְיוֹן שֶׁבְּגַן עֵדֶן. וְכָל הָאָבוֹת מוֹדִים וְאוֹמְרִים, (תהלים לו) מַה יָּקָר חַסְדְּךְ אֱלֹהִים וּבְנֵי אָדָם בְּצֵל כְּנָפֶיךְ יֶחֱסָיוּן."],[8,"","רַבִּי יֵיסָא אָמַר, כָּל בְּנֵי הָעוֹלָם רוֹאִים אֶת אָדָם הָרִאשׁוֹן בְּשָׁעָה שֶׁמִּסְתַּלְּקִים מֵהָעוֹלָם, לְהַרְאוֹת עֵדוּת שֶׁמִּשּׁוּם חֲטָאֵי הָאִישׁ הוּא מִסְתַּלֵּק מֵהָעוֹלָם וְלֹא בִּגְלָלוֹ שֶׁל אָדָם, כְּמוֹ שֶׁשָּׁנִינוּ אֵין מִיתָה בְּלֹא חֵטְא,"],[9,"","פְּרָט לְאוֹתָם שְׁלֹשָׁה שֶׁהִסְתַּלְּקוּ בְּעֶטְיוֹ שֶׁל נָחָשׁ הַקַּדְמוֹנִי, וְאֵלֶּה הֵם: עַמְרָם, לֵוִי וּבִנְיָמִין. וְיֵשׁ אוֹמְרִים גַּם יִשַׁי. שֶׁלֹּא חָטְאוּ, וְלֹא נִמְצָא בָהֶם חֵטְא שֶׁיָּמוּתוּ בוֹ, רַק שֶׁנִּזְכְּרָה עֲלֵיהֶם אוֹתָהּ עֲצַת הַנָּחָשׁ, כְּמוֹ שֶׁבֵּאַרְנוּ."],[10,"","בֹּא רְאֵה, כָּל הַדּוֹרוֹת שֶׁהָיוּ בִּימֵי נֹחַ, כֻּלָּם הִפְשִׁיטוּ חֲטָאִים עַל הָעוֹלָם בְּגָלוּי לְעֵינֵי כֹל. רַבִּי שִׁמְעוֹן הָיָה הוֹלֵךְ יוֹם אֶחָד בְּשַׁעֲרֵי טְבֶרְיָה. רָאָה בְּנֵי אָדָם שֶׁהָיוּ קוֹשְׁרִים בְּקֶשֶׁר הַקֶּשֶׁת בְּכַדֵּי חֶרֶס. אָמַר, וּמַה חֵטְא זֶה בְּגָלוּי לְהַרְגִּיז אֶת רִבּוֹנָם? נָתַן עֵינוֹ בָהֶם וְנִזְרְקוּ לְתוֹךְ הַיָּם וּמֵתוּ."],[11,"","בֹּא רְאֵה, כָּל חֵטְא שֶׁנַּעֲשֶׂה בְּגָלוּי, דּוֹחֶה אֶת הַשְּׁכִינָה מֵהָאָרֶץ וּמְסַלֵּק אֶת דִּיּוּרָהּ מִן הָעוֹלָם. אֵלֶּה הָיוּ הוֹלְכִים בְּרֹאשׁ זָקוּף וְעוֹשִׂים חֲטָאֵיהֶם בְּגָלוּי, וְדָחוּ אֶת הַשְּׁכִינָה מֵהָעוֹלָם, עַד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא דָּחָה אוֹתָם וְהֶעֱבִיר אוֹתָם מִמֶּנּוּ. וְעַל זֶה כָּתוּב (משלי כה) הָגוֹ רָשָׁע לִפְנֵי מֶלֶךְ וְגוֹ', הָגוֹ סִיגִים מִכָּסֶף וְגוֹ'."],[12,"","וַיֹּאמֶר ה' לֹא יָדוֹן רוּחִי בָאָדָם לְעֹלָם בְּשַׁגַּם הוּא בָשָׂר וְגוֹ'. אָמַר רַבִּי אֶלְעָזָר, בּא רְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, עָשָׂה אֶת הָעוֹלָם הַזֶּה לְהִשְׁתַּמֵּשׁ כְּמוֹ שֶׁלְּמַעְלָה, וּכְשֶׁבְּנֵי אָדָם הֵם צַדִּיקִים שֶׁהוֹלְכִים בְּדֶרֶךְ יָשָׁר, הַקָּדוֹשׁ בָּרוּךְ הוּא מְעוֹרֵר רוּחַ חַיִּים שֶׁלְּמַעְלָה, עַד שֶׁמַּגִּיעִים אוֹתָם חַיִּים לַמָּקוֹם שֶׁיַּעֲקֹב אָבִינוּ שָׁרוּי בּוֹ."]]],[["וּמִתַּמָּן נָגְדֵי אִנּוּן חַיִּין עַד דְּאִתְמְשִׁיךְ הַהוּא רוּחָא לְהַאי עוֹלָם דְּדָוִד מַלְכָּא שָׁרְיָא בֵּיהּ. וּמִתַּמָּן נָגְדֵי בִּרְכָאן לְכֻלְהוּ אִנּוּן תַּתָּאֵי. וְהַהוּא רוּחָא עִלָּאָה אִתְנְגִיד וְאִתְמְשִׁיךְ לְתַתָּא וְיָכְלִין לְאִתְקַיְימָא בְּעָלְמָא.","וּבְגִינֵי כָּךְ לְעוֹלָם חַסְדּוֹ דָּא הוּא עוֹלָם דְּדָוִד מַלְכָּא. וּבְגִין כָּךְ כְּתִיב לְעֹלָם בְּלָא וָא\"ו. דְּהָא כַּד (איהו) הַהוּא רוּחָא אִתְנְגִיד לְהַהוּא עוֹלָם, מִתַּמָּן נָפְקֵי בִּרְכָאן וְחַיִּין לְכֹלָא לְאִתְקָיְימָא. הַשְׁתָּא דְּחָבוּ בְּנֵי נָשָׁא אִסְתַּלַּק כֹּלָּא. בְּגִין דְּלָא יִמְטֵי הַהוּא רוּחָא דְחַיֵּי לְהַאי עוֹלָם לְאִתְהַנָּאָה מִנֵּיהּ תַּתָּאֵי וּלְאִתְקָיְימָא בֵּיהּ. בְּשַׁגָּם הוּא בָּשָׂר בְּגִין דְּלָא יִתְרַק הַאי רוּחָא לְהַאי עוֹלָם. מַאי טַעְמָא דְּלָא לְאַסְגָּאָה נָחָשׁ תַּתָּאָה. דְּדַרְגִין דְּיִתְתַּקַּף בֵּיהּ (ד\"א ל\"ג ובעינן) רוּחָא דִּקְדוּשָׁא דְּלָא יִתְעָרַב בְּרוּחַ מְסָאָב.","בְּשַׁגָּם הוּא בָּשָׂר דָּא נָחָשׁ קַדְמָאָה דְּיִתְבָּרַךְ בְגִין כָּךְ הוּא בָּשָׂר כְּמָא דְאַתְּ אָמֵר, (בראשית ו׳:י״ג) קֵץ כָּל בָּשָׂר בָּא לְפָנַי וְאָמַר רַבִּי שִׁמְעוֹן דָּא מַלְאַךְ הַמָּוֶת. וְהָיוּ יָמָיו מֵאָה וְעֶשְׂרִים שָׁנָה אוֹרִיכוּ דְקוּסְטִירָא דְּקִיטְרָא:","הַנְּפִילִים הָיוּ בָּאָרֶץ. תָּנֵי רַבִּי יוֹסֵי אִלֵּין עַזָּ\"א וַעֲזָאֵ\"ל. כְּמָה דְּאִתְּמָר דְּאַפִּיק (ד\"א דאפיל) לוֹן קוּדְשָׁא בְּרִיךְ הוּא מִקְדוּשָׁתָא דִּלְעֵילָא. וְאִי תֵימָא וְהֵיךְ יָכְלוּ לְאִתְקַיְימָא בְּהַאי עָלְמָא. אָמַר רַבִּי חִיָּיא אִלֵּין הֲווּ מֵאִנּוּן דִּכְתִיב וְעוֹף יְעוֹפֵף עַל הָאָרֶץ. וְהָא אִתְּמָר דְּאִלֵּין אִתְחֲזוּ לִבְנֵי נָשָׁא כְּחֵזוּ דִּלְהוֹן. וְאִי תֵימָא הֵיךְ יָכְלִין לְאִתְהַפָּכָא. הָא אִתְּמָר דְּאִתְהַפְּכָן לְכַמָּה גְוָונִין וּבְשַׁעֲתָא דְּנָחְתֵי אַגְלִימוּ בַּאֲוִירָא דְעָלְמָא וְאִתְחַזּוּן כִּבְנֵי נָשָׁא.","וְהָנֵי עַזָּ\"א וַעֲזָאֵ\"ל דְּמָרְדוּ לְעֵילָא וְאַפִּיל לוֹן קוּדְשָׁא בְּרִיךְ הוּא וְאַגְלִימוּ בְּאַרְעָא וְאִתְקָיְימוּ בֵּיהּ וְלָא יָכִילוּ לְאִתְפַּשְׁטָא מִנֵּיהּ. וּלְבָתַר טָעוּ בָּתַר נְשֵׁי עָלְמָא. וְעַד כְּעָן יוֹמָא דָא אִנּוּן קָיְימֵי וְאוֹלְפֵי חָרְשִׁין לִבְנֵי נָשָׁא וְאוֹלִידוּ בְּנִין וְקָרוּ לְהוּ עֲנָקִים גִּבָּרִין. וְאִנּוּן נְפִילִים אִקְרוּן בְּנֵי אֱלהִים. וְהָא אִתְּמָר.","וַיֹּאמֶר יְיָ אֶמְחֶה אֶת הָאָדָם אֲשֶׁר בָּרָאתִי מֵעַל פְּנִי הָאֲדָמָה. רַבִּי יוֹסֵי פָּתַח (ישעיהו נ״ה:ח׳) כִּי לא מַחְשְׁבוֹתַי מַחְשְׁבוֹתֵיכֶם. תָּא חֲזֵי, כַּד בַּר נָשׁ בָּעֵי לְנָקְמָא מֵאַחֲרָא שָׁתִיק וְלָא אָמַר מִידִי. דְּאִילוּ אוֹדְעֵיהּ יִסְתַּמַּר וְלָא יָכִיל לֵיהּ.","אֲבָל קוּדְשָׁא בְּרִיךְ הוּא לָאו הָכִי עָבִיד. לָא עָבִיד דִּינָא בְּעָלְמָא עַד דְּאַכְרִיז וְאוֹדַע לְהוּ זִמְנָא תְּרֵין וּתְלָתָא. בְּגִין דְּלָא אִיתָאי דְּיִמְחֵי בִּידֵיהּ דְּיֵימָא לֵיהּ מָה עֲבָדַת וְלָא יִסְתַּמַּר מִנֵּיהּ וְלָא יָכִיל לְקָיְימָא קַמֵּיהּ.","תָּא חֲזֵי, וַיֹּאמֶר יְיָ אֶמְחֶה אֶת הָאָדָם אֲשֶׁר בָּרָאתִי מֵעַל פְּנֵי הָאֲדָמָה. אוֹדַע לוֹן עַל יְדָא דְנֹחַ וְאַתְרֵי בְּהוֹן כַּמָּה זִמְנִין וְלָא שָׁמְעֵי. בָּתַר דְּלָא שְׁמָעוּ, אַיְיתֵי עֲלֵיהוֹן דִּינָא וְאוֹבִיד לוֹן מֵעַל אַפֵּי אַרְעָא.","תָּא חֲזֵי מַה כְּתִיב בֵּיהּ בְּנֹחַ וַיִּקְרָא אֶת שְׁמוֹ (ס' א) נֹחַ לֵאמֹר זֶה יְנַחֲמֵנוּ מִמַּעֲשֵׂנוּ. (זה מקומו בדף ס' ובתוס' בהגהת האר\"י) (ס\"א אמאי הכא לאמר. ואמאי זה. אלא לאמר דא אתתא. זה דא צדיק. רמז דקודשא בריך הוא קרא ליה לנח נייחא דארעא. לאמר. מאי לאמר. אלא אתר דא קרי ליה נח ומאן איהו ארעא קדישא. לאמר זה ינחמנו עבד ליה קודשא בריך הוא לתתא כגוונא עילאה. כתיב הכא זה ינחמנו וכתיב התם (ישעיהו כ״ה:ט׳) זה יי קוינו לו. זכאין אנון צדיקייא דרשימין ברשימו דגושפנקא דמלכא עילאה למהוי בשמיה רשימין. ואיהו שוי שמהן בארעא כדקא יאות. כתיב ויקרא את שמו נח, וכתיב, (בראשית כ״ה:כ״ו) ויקרא שמו יעקב. אמאי לא כתיב את. אלא התם דרגא (חדא) והכא דרגא אחרא. כמא דאת אמר (ישעיה ו) ואראה את ה'. ואראה יי לא כתיב אלא את יי. אוף הכא ויקרא שמו יעקב דרגא דיליה קודשא בריך הוא ממש קרי ליה יעקב. אבל הכא א\"ת, לאכללא שכינתא). מְנָא הֲוָה יָדַע. אֶלָּא בְּשַׁעֲתָא דְּלַיְיט קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא דִּכְתִיב אֲרוּרָה הָאֲדָמָה בַּעֲבוּרְךָ. אָמַר אָדָם קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, רִבּוֹנוֹ שֶׁל עוֹלָם עַד מָתַי יְהֵא עָלְמָא בְּלַטְיוּתָא. אָמַר לֵיהּ עַד דְּיִתְיְלִיד לָךְ בֵּן מָהוּל כְּגַוְונָא דִילָךְ."],[[0,"ומתמן נגדי וכו':","ומשם נמשכים החיים עד שנמשך אותו רוח החיים לעולם הזה, דהיינו להנוקבא, להמקום שדוד המלך שורה בו. ומשם נמשכים הברכות לכל התחתונים שבבי\"ע, ואותו רוח העליון הנזכר. מתפשט ונמשך למטה, והתחתונים יכולים להתקיים בעולם."],[1,"ובגיני כך וכו':","ומשום זה כתוב לעולם חסדו, עם \u0003ו,\u0004 זה הוא עולם של דוד המלך, דהיינו עולם הזה שהיא הנוקבא. שה\u0003ו'\u0004 ה\"ס רוח החיים הנמשך לעולם. ומשום זה, כתוב כאן, בהכ' לא ידון רוחי באדם \u0003לעלם,\u0004 בלי \u0003ו',\u0004 כי כאשר רוח ההוא נמשך לאותו עולם, יוצאים משם ברכות וחיים לכל שיתקיימו. ועתה, בדור המבול, שבני האדם חטאו להמשיך ממעלה למטה. ופגמו בקו אמצעי, ונתאחזו בקו שמאל, נסתלק הכל מהעולם, כדי שלא יבא אותו רוח החיים לעולם הזה להנות בו התחתונים ויתקיימו בו. וע\"כ כתוב כאן \u0003לעלם\u0004 בלי \u0003ו'.\u0004 דהיינו משום שפגמו בקו אמצעי שה\"ס \u0003ו'\u0004 וה\"ס רוח החיים, ונאחזו בקו שמאל."],[2,"בשגם הוא בשר:","משום זה לא יהיה מושפע רוח החיים הזה לעולם הזה. ושואל מהו הטעם של הכתוב. ואומר, שהוא, כדי שלא להגדיל את הנחש, התחתון של המדרגות, הנקרא בשר, שיתחזק על ידי רוח החיים הזה, ורוח הקדוש לא יתערב ברוח הטומאה של הנחש. ושיעור הכתוב \u0003בשגם הוא בשר.\u0004 הוא, \u0003בשגם\u0004 נחש הקדמוני הנקרא \u0003בשר,\u0004 יתברך באותו רוח החיים. ומשום זה נקרא הנחש בשר, כמו שאתה אומר קץ כל בשר בא לפני. ואמר ר\"ש שזה מלאך המות. שהוא נחש הקדמוני. הרי שהנחש נקרא בשר. והיה ימיו \u0003מאה ועשרים שנה.\u0004 היינו המתנה דמגדל המקושר. \u0003קוסטרא\u0004 פירושו מגדל. \u0003קיטרא\u0004 פירושו קשר. פירוש. הנוקבא נקראת \u0003מגדל\u0004 בסוד הכתוב כמגדל דוד צוארך. ונקראת בשם זה. רק בעת שהיא עולית אל החג\"ת ונקשרת בהם בסוד רביעי לאבות. (כנ\"ל ב\"א דף ק\"י ד\"ה ואלו) ולפיכך היא מכונה בזהר בכ\"מ, בשם \u0003קוסטירא דקיטרא,\u0004 דהיינו מגדל המקושר. והנה אז יש בה ג' קשרים, כלומר, שהחג\"ת והנוקבא נקשרים זה בזה, וד' מדרגות, שבכל אחד עשר ספירות, ה\"ס מ'. ויש קשר של מ' מקו ימין, וכן מ' מקו שמאל, וכן מ' מקו אמצעי וג' פעמים מ' ה\"ס מאה ועשרים. שנה, פירושו ספירות. וז\"ס שאמרו חז\"ל (ר\"ה לא:) כל שנותיו של ריב\"ז מאה ועשרים שנה. מ' שנה עסק בפרקמטיא, מ' שנה למד, מ' שנה לימד. כי ה\"ס ג' הקשרים שבמלכות הנ\"ל. מ' בפרקמטיא ה\"ס מקו ימין. מ' דלמד ה\"ס מקו שמאל. מ' דלימד ה\"ס מקו אמצעי. וזה שיעור הכתוב. לא ידון רוחי באדם לעלם, משום שחסר \u0003ו'\u0004 שפגמו בקו אמצעי ונאחזו בקו שמאל להמשיך ממנו מלמעלה למטה, ע\"כ לא יאיר רוח החיים אליהם, כי בשגם הוא בשר, כי הנחש שנקרא בשר יתגדל ממנו. כנ\"ל. אלא, והיו ימיו מאה ועשרים שנה שצריכים לתקן המלכות שתקבל מכל ג' הקוין בסוד ג' ממין, כנ\"ל שהם ק\"כ שנה. וז\"ש הזהר, שמספר ק\"כ שנה הוא \u0003אוריכו דקוסטירא דקיטרא.\u0004 שהיא המתנה וזמן לתקן את המגדל המקושר. דהיינו בכל ג' הקשרים שהם מספר מאה ועשרים. ואז שוב ידון רוחי באדם שרוח החיים יחזור ויאיר לתחתונים."],[3,"הנפילים היו בארץ:","תני ר' יוסי, אלו הם עוזא ועזאל, שנקראים נפילים. כמו שלמדנו. שהוא משום שהפיל אותם הקב\"ה מקדושה שלמעלה, ואם תאמר איך יכלו להתקיים בעולם הזה. אמר ר' חייא, אלו הם, מאלו שכתוב בהם, ועוף יעופף על הארץ. ולמדנו, שהם נראים לבני אדם בצורתם של בני אדם. ואם תאמר איך יכולים להתהפך מצורת מלאך לצורת אדם. הנה למדנו שהם מתהפכים לכמה צורות, ובשעה שהם יורדים לעולם הזה, מתלבשים בלבוש אויר העולם, ונראים כבני אדם."],[4,"והני עוזא וכו':","ואלו עוזא ועזאל שמרדו למעלה והפיל אותם הקב\"ה משמים ונתלבשו בארץ, ונתקיימו באותו הלבוש ולא יכלו להתפשט ממנו ולחזור למקומם כמו שאר מלאכים, אלא שנשארו בארץ. ואח\"כ זנו אחר נשי העולם. ועד עתה, עד היום הזה, הם חיים וקימים, ומלמדים כשוף לבני אדם. והולידו בנים וקראו אותם, ענקים גבורים. ואלו הנפילים נקראים גם כן בני האלהים. וכבר נתבאר. ועי' לעיל בהקדמת הזהר דף קנ\"ה ד\"ה והנה ביאור שבארנו שם ענין עוזא ועזאל באורך."],[5,"ויאמר ה' אמחה את האדם וגו':","ר' יוסי פתח. כי לא מחשבותי מחשבותיכם. בוא וראה כשבן אדם רוצה לנקום מאחר, הוא שותק ואינו אומר לו כלום, שאלו מודיעו, ישמור עצמו ולא יוכל לו."],[6,"אבל קב\"ה וכו':","אבל הקב\"ה אינו עושה כך, כי אינו עושה דין בעולם עד שמכריז ומודיע להם. פעם ושתים ושלש. משום שאין מי שימחה בידו, שיאמר לו מת תעשה. ואין להשמר ממנו, ואין להתיצב כנגדו."],[7,"ת\"ח ויאמר וכו':","בוא וראה, ויאמר ה' אמחה את האדם וגו'. הודיע אותם זה על ידי נח, והתרה בהם כמה פעמים ולא שמעו. ואחר שלא שמעו, הביא עליהם את הדין והאביד אותם מעל פני האדמה."],[8,"ת\"ח מה כתיב וכו':","בוא וראה מה כתוב בו בנח, ויקרא את שמו נח לאמר זה ינחמנו ממעשנו, ושואל מאין היה יודע שזה ינחמנו ממעשנו תכף בעת לידתו. ואומר, אלא בשעה שהקב\"ה קלל את העולם, שכתוב ארורה האדמה בעבורך. אמר אדם לפני הקב\"ה, רבונו של עולם, עד מתי יהיה העולם בקללה. אמר לו הקב\"ה, עד שיולד לך בן מהול כמותך."]],[[0,"","וּמִשָּׁם שׁוֹפְעִים אוֹתָם חַיִּים, עַד שֶׁנִּמְשֶׁכֶת אוֹתָהּ רוּחַ לָעוֹלָם הַזֶּה שֶׁדָּוִד הַמֶּלֶךְ שָׁרוּי בּוֹ, וּמִשָּׁם שׁוֹפְעוֹת הַבְּרָכוֹת לְכָל אוֹתָם הַתַּחְתּוֹנִים. וְאוֹתָהּ רוּחַ עֶלְיוֹנָה שׁוֹפַעַת וְנִמְשֶׁכֶת לְמַטָּה, וִיכוֹלִים לְהִתְקַיֵּם בָּעוֹלָם."],[1,"","וּמִשּׁוּם כָּךְ לְעוֹלָם חַסְדּוֹ, זֶהוּ עוֹלָם שֶׁל דָּוִד הַמֶּלֶךְ, וְלָכֵן כָּתוּב לְעֹלָם בְּלִי וָא\"ו. שֶׁהֲרֵי כְּשֶׁאוֹתָהּ רוּחַ שׁוֹפַעַת לְאוֹתוֹ עוֹלָם, מִשָּׁם יוֹצְאוֹת בְּרָכוֹת וְחַיִּים לַכֹּל לְהִתְקַיֵּם. עַכְשָׁו שֶׁחָטְאוּ בְּנֵי אָדָם, הִסְתַּלֵּק הַכֹּל, בִּשְׁבִיל שֶׁלֹּא יַגִּיעַ אוֹתוֹ רוּחַ חַיִּים לְעוֹלָם זֶה לֵהָנוֹת מִמֶּנּוּ הַתַּחְתּוֹנִים וּלְהִתְקַיֵּם בּוֹ. בְּשַׁגַּם הוּא בָשָׂר - כְּדֵי שֶׁלֹּא תֻשְׁפַּע זוֹ הָרוּחַ לָעוֹלָם הַזֶּה. מָה הַטַּעַם? שֶׁלֹּא לְהַרְבּוֹת נָחָשׁ הַתַּחְתּוֹן. שֶׁדְּרָגוֹת שֶׁיִּתְחַזֵּק בּוֹ (וצריכים) רוּחַ שֶׁל קְדֻשָּׁה שֶׁלֹּא יִתְעָרֵב בְּרוּחַ טָמֵא."],[2,"","בְּשַׁגַּם הוּא בָשָׂר - זֶה נָחָשׁ הַקַּדְמוֹנִי שֶׁיִּתְבָּרֵךְ. מִשּׁוּם כָּךְ הוּא בָשָׂר, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ו) קֵץ כָּל בָּשָׂר בָּא לְפָנַי. וְאָמַר רַבִּי שִׁמְעוֹן, זֶהוּ מַלְאַךְ הַמָּוֶת. וְהָיוּ יָמָיו מֵאָה וְעֶשְׂרִים שָׁנָה - הַמְתָּנָה שֶׁל מִגְדָּל הַמְקֻשָּׁר."],[3,"","הַנְּפִלִים הָיוּ בָאָרֶץ. שָׁנָה רַבִּי יוֹסֵי, אֵלּוּ עֲזָ\"א וַעֲזָאֵ\"ל, כְּמוֹ שֶׁנֶּאֱמַר שֶׁהוֹצִיא (ד\"א שהפיל) אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא מֵהַקְּדֻשָּׁה שֶׁלְּמַעְלָה. וְאִם תֹּאמַר, אֵיךְ יָכְלוּ לְהִתְקַיֵּם בָּעוֹלָם הַזֶּה? אָמַר רַבִּי חִיָּיא, אֵלֶּה הָיוּ מֵאוֹתָם שֶׁכָּתוּב וְעוֹף יְעוֹפֵף עַל הָאָרֶץ. וַהֲרֵי נֶאֱמַר שֶׁאֵלֶּה נִרְאִים לִבְנֵי אָדָם כַּמַּרְאֶה שֶׁלָּהֶם. וְאִם תֹּאמַר, אֵיךְ יָכְלוּ לְהִתְהַפֵּךְ? הֲרֵי נֶאֱמַר שֶׁמִּתְהַפְּכִים לְכַמָּה גְוָנִים. וּבְשָׁעָה שֶׁיָּרְדוּ, הִתְלַבְּשׁוּ בַּאֲוִיר הָעוֹלָם וְנִרְאוּ כִּבְנֵי אָדָם."],[4,"","וַעָזָ\"א וַעֲזָאֵ\"ל הַלָּלוּ שֶׁמָּרְדוּ לְמַעְלָה וְהִפִּילָם הַקָּדוֹשׁ בָּרוּךְ הוּא וְהִתְלַבְּשׁוּ בָאָרֶץ וְהִתְקַיְּמוּ בָהּ, וְלֹא יָכְלוּ לְהִתְפַּשֵּׁט מִמֶּנּוּ, וְאַחַר כָּךְ טָעוּ אַחַר נְשׁוֹת הָעוֹלָם. וְעַד הַיּוֹם הַזֶּה הֵם קַיָּמִים וּמְלַמְּדִים כְּשָׁפִים לִבְנֵי אָדָם, וְהוֹלִידוּ בָנִים, וְקָרְאוּ לָהֶם עֲנָקִים גִּבּוֹרִים. וְאוֹתָם נְפִילִים נִקְרָאִים בְּנֵי אֱלֹהִים, וַהֲרֵי נִתְבָּאֵר."],[5,"","וַיֹּאמֶר ה' אֶמְחֶה אֶת הָאָדָם אֲשֶׁר בָּרָאתִי מֵעַל פְּנֵי הָאֲדָמָה. רַבִּי יוֹסֵי פָּתַח, (ישעיה נה) כִּי לֹא מַחְשְׁבוֹתַי מַחְשְׁבוֹתֵיהֶם. בֹּא רְאֵה, כְּשֶׁבֶּן אָדָם רוֹצֶה לִנְקֹם מֵאַחֵר, הוּא שׁוֹתֵק וְלֹא אוֹמֵר דָּבָר. שֶׁאִם יוֹדִיעַ לוֹ, הַהוּא יִשָּׁמֵר וְלֹא יוּכַל לוֹ."],[6,"","אֲבָל הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא עוֹשֶׂה כָּךְ, לֹא עוֹשֶׂה דִין בָּעוֹלָם עַד שֶׁמַּכְרִיז וּמוֹדִיעַ לָהֶם פַּעַם פַּעֲמַיִם וְשָׁלֹשׁ, כִּי אֵין מִי שֶׁיִּמְחֶה בְיָדוֹ שֶׁיֹּאמַר לוֹ מֶה עָשִׂיתָ, וְלֹא יִשָּׁמֵר מִמֶּנּוּ וְלֹא יוּכַל לַעֲמֹד לְפָנָיו."],[7,"","בֹּא רְאֵה, וַיֹּאמֶר ה' אֶמְחֶה אֶת הָאָדָם אֲשֶׁר בָּרָאתִי מֵעַל פְּנֵי הָאֲדָמָה. הוֹדִיעַ לָהֶם עַל יְדֵי נֹחַ וְהִתְרָה בָהֶם כַּמָּה פְעָמִים וְלֹא שָׁמְעוּ. אַחַר שֶׁלֹּא שָׁמְעוּ, הֵבִיא עֲלֵיהֶם דִּין וְהֶאֱבִיד אוֹתָם מֵעַל פְּנֵי הָאָרֶץ."],[8,"","בֹּא רְאֵה מַה כָּתוּב בְּנֹחַ, וַיִּקְרָא אֶת שְׁמוֹ נֹחַ לֵאמֹר זֶה יְנַחֲמֵנוּ מִמַּעֲשֵׂנוּ. (למה כאן לאמר, ולמה זה? אלא לאמר זו האשה, זה זה צדיק, רמז שהקדוש ברוך הוא קרא לנח, מנוחת הארץ, לאמר, מה זה לאמר? אלא מקום זה קורא לו נח, ומיהו? ארץ הקדושה, לאמר זה ינחמנו, עשה אותו הקדוש ברוך הוא למטה כדגמא עליונה, כתוב כאן זה ינחמנו, וכתוב שם (ישעיה כה) זה ה' קוינו לו. אשרי הצדיקים שרשומים ברשם של חותמת המלך העליונה להיות רשומים בשמו, והוא שם שמות בארץ כראוי. כתוב ויקרא את שמו נח, וכתוב (בראשית כה) ויקרא את שמו יעקב, למה לא כתוב את? אלא שם דרגה (אחת), וכאן דרגה אחרת, כמו שנאמר (ישעיה ו) ואראה את ה', ואראה ה' לא כתוב אלא את ה', גם כאן ויקרא שמו יעקב דרגתו ממש, הקדוש ברוך הוא קרא לו י קב, אבל כאן א\"ת להכליל את השכינה.) מֵאֵיפֹה הָיָה יוֹדֵעַ? אֶלָּא בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא קִלֵּל אֶת הָעוֹלָם, שֶׁכָּתוּב אֲרוּרָה הָאֲדָמָה בַּעֲבוּרֶךְ, אָמַר אָדָם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא: רִבּוֹנוֹ שֶׁל עוֹלָם, עַד מָתַי יִהְיֶה הָעוֹלָם בִּקְלָלָה? אָמַר לוֹ: עַד שֶׁיִּוָּלֵד לְךְ בֵּן מָהוּל כְּמוֹתְךְ."]]],[["וְהֲווּ מְחַכָּאן עַד שַׁעֲתָא דְּאִתְיַלִּיד נֹחַ. וְכֵיוָן דְּאִתְיַילִיד (נח נט ב) חָמָא לֵיהּ גָּזִיר רָשִׁים בְּאָת קַדִּישָׁא. וְחָמָא שְׁכִינְתָא מִתְדַּבְּקָא בַּהֲדֵיהּ. כְּדֵין קָרָא שְׁמֵיהּ עַל מָה דְּעָבִיד לְבָתָר.","בְּקַדְמִיתָא לָא הֲווּ יָדְעֵי לְמִזְרַע וּלְמֶחֱצָד וּלְמֶחֱרַשׁ וְהֲווּ עָבְדֵי פּוּלְחָנָא דְאַרְעָא בִּידַיְיהוּ. כֵּיוָן דְּאָתָא נֹחַ אַתְקִין אוּמְנוּתָא לְהוּ וְכָל מָאנִין (צו ב) דִּצְרִיכִין לְתַקְנָא אַרְעָא לְמֶעְבַּד פֵּירִין. הֲדָא הוּא דִכְתִיב זֶה יְנַחֲמֵנוּ מִמַּעֲשֵׂנוּ וּמֵעִצְבוֹן יָדֵינוּ, מִן הָאֲדָמָה. דְּאִיהוּ אַפִּיק אַרְעָא מִמַּה דְּאִתְלַטְיָיא. דְּהֲווּ זָרְעִין חִטִּין וְקָצְרִין גּוֹבִין וְדַרְדַּרִין. וּבְגִינֵי כָךְ כְּתִיב אִישׁ הָאֲדָמָה.","רַבִּי יְהוּדָה אָמַר אִישׁ הָאֲדָמָה כְּמָא דְאַתְּ אָמֵר, (רות א׳:ג׳) אִישׁ נָעֳמִי. בְּגִין דְּאִקְרֵי צַדִּיק וְאַפִּיק לָהּ לְאַרְעָא בְּקָרְבָּנָא דְּעֲבַד מִמַּה דְּאִתְלַטְיָיא דִּכְתִיב לא אוֹסִיף לְקַלֵּל עוֹד אֶת הָאֲדָמָה בַּעֲבוּר הָאָדָם. וּבְגִין דָּא אִקְרֵי אִישׁ הָאֲדָמָה. וְעַל דָּא קְרָא לֵיהּ שְׁמָא עַל מַה דְּיֵיתֵי.","רַבִּי יְהוּדָה פָּתַח (תהילים מ״ו:ט׳) לְכוּ חֲזוּ מִפְעֲלוֹת אֱלֹהִים אֲשֶׁר שָׂם שַׁמּוֹת בָּאָרֶץ. הַאי קְרָא אוּקְמוּהָ וְאִתְּמָר. אֲבָל לְכוּ חֲזוּ וְגו'. (מאי חזו כמא דאת אמר, (ישעיהו כ״א:ב׳) חזות קשה הוגד לי. בעובדוי דקודשא בריך הוא אתגלי נבואה עלאה לבני נשא. אשר שם שמות בארץ. שמות ודאי דהא שמא גרים לכלא) (והוא לשון שממון) דְּאִלּוּ הֲווּ מִפְעֲלוֹת יוד הא ואו הא שָׂם קִיּוּם בָּאָרֶץ, אֲבָל בְּגִין דְּהֲווּ מִפְעֲלוֹת שְׁמָא דֵאלהִים שָׂם שַׁמּוֹת בָּאָרֶץ.","אָמַר לֵיהּ רַבִּי חִיָּיא הַשְׁתָּא אִתְעָרַת לְהַאי. לָאו, אֲנָא הָכִי אֲמִינָא לֵיהּ. בְּגִין דְּבֵין שְׁמָא דָא וּבֵין שְׁמָא דָא כֹּלָּא הוּא שְׁבַחָא. אֲבָל אֲנָא אֲמִינָא לֵיהּ כְּמָה דְּאִתְעָרוּ חַבְרַיָא דְּשָׁוֵי שְׁמָהָן. שַׁמּוֹת בָּאָרֶץ שֵׁמוֹת מַמָּשׁ (שם בארץ ואמאי בגין לאשתמשא בהו עלמא ולמהוי קיומא בעלמא).","רַבִּי יִצְחָק אָמַר כֹּלָּא הוּא. וְאֲפִילּוּ מַה דְאָמַר רַבִּי יְהוּדָה שַׁפִּיר קָאֲמַר. דְּאִלּוּ יְהֵא עָלְמָא בִּשְׁמָא דְרַחֲמֵי יִתְקַיָּים עָלְמָא, אֲבָל בְּגִין דְּאִתְבְּרֵי עָלְמָא עַל דִּינָא וְקָיְימָא עַל דִּינָא שָׂם שַׁמּוֹת בָּאָרֶץ וְשַׁפִּיר הוּא דְּאִלְמָלֵא כָּךְ לָא יָכִיל עָלְמָא לְאִתְקָיְימָא מִקַּמֵּי חוֹבֵיהוֹן דִּבְנֵי נָשָׁא.","תָּא חֲזֵי, נֹחַ כַּד אִתְיְילִיד קָרוּן לֵיהּ עַל שְׁמָא דִּנְחָמָה (נח, נייחאליה, נייחא לעלמא, נייחא לאבהן, נייחא לבנין, נייחא לעלאין, נייחא לתתאין, נייחא לעלמא דין, נייחא לעלמא דאתי) וְלֶהֱוֵי (ד\"א ולמהוי) שְׁמָא גָרִים. אֲבָל (נ\"א לגבי) קוּדְשָׁא בְּרִיךְ הוּא לָאו הָכִי. נֹחַ בְּהִפּוּךְ אָתְוָון חֵן כְּמָא דְאַתְּ אָמֵר וְנֹחַ מָצָא חֵן. אָמַר רַבִּי יוֹסֵי חֵן הַיְינוּ נֹחַ. בְּצַדִּיקַיָיא שְׁמֵיהוֹן גָּרִים לְטַב. בְּחַיָּיבַיָא שְׁמֵיהוֹן גָּרִים לְבִישׁ. בְּנֹחַ כְּתִיב וְנֹחַ מָצָא חֵן בְּעֵינֵי יְיָ. בְּעֵר בְּכוֹר יְהוּדָה אִתְהַפָּכוּ אָתְווֹי לְבִישׁ. עֵ\"ר רָ\"ע. רַע בְּעֵינֵי יְיָ.","תָּא חֲזֵי, כֵּיוָן דְּאִתְיְילִיד נֹחַ חָמָא עוֹבָדֵיהוֹן דִּבְנֵי נָשָׁא דְּאִנּוּן חָטָאן קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְהֲוָה גָּנִיז גַּרְמֵיהּ וְאִשְׁתְּדָּל בְּפוּלְחָנָא דְּמָארֵיהּ. בְּגִין דְּלֹא לְמֵהַךְ בְּאוֹרְחַיְיהוּ. וְכִי תֹּאמַר בַּמָּה אִשְׁתַּדַּל. בְּהַהוּא (ל\"ז ב) סִפְרָא דְאָדָם וְסִפְרָא דְּחֲנוֹךְ וְהֲוָה אִשְׁתַּדַּל בְּהוּ לְמִפְלַח לְמָרֵיהּ.","תָּא חֲזֵי, דְּהָכִי הוּא דְּהָא נֹחַ מְנָא הֲוָה יָדַע לִקְרַב קָרְבָּנָא לְמָרֵיהּ. אֶלָּא בְּגִין דְּאַשְׁכַּח חָכְמְתָא עַל מַה מִּתְקַיֵּים עָלְמָא וְיָדַע דְּעַל קָרְבָּנָא מִתְקַיֵּים. וְאִלְמָלֵא קָרְבָּנָא לָא הֲווּ קָיְימֵי עִלָּאֵי וְתַתָּאֵי.","רַבִּי שִׁמְעוֹן הֲוָה אָזִיל בְּאָרְחָא וְהֲווּ עִמֵּיהּ רַבִּי אֶלְעָזָר בְּרֵיהּ וְרַבִּי יוֹסֵי וְרַבִּי חִיָּיא. עַד דְּהֲווּ אָזְלֵי, אָמַר רַבִּי אֶלְעָזָר לְאֲבוּהִי אָרְחָא מְתַקְנָא קַמָּן בָּעִינָן לְמִשְׁמַע מִלֵּי דְאוֹרַיְיתָא.","פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר (קהלת י׳:ג׳) גַּם בַּדֶּרֶךְ כְּשֶׁהַסָּכָל הוֹלֵךְ לִבּוֹ חָסֵר וְגו'. כַּד בַּר נָשׁ בָּעֵי לְאַתְקָנָא אָרְחֵיהּ קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא. עַד לָא יִפּוּק לְאָרְחָא בָּעֵי לְאַמְלָכָא בֵּיהּ וּלְצַלֵּי קַמֵּיהּ עַל אָרְחֵיהּ. כְּמָה דְּתָנִינָן דִּכְתִיב, (תהילים פ״ה:י״ד) צֶדֶק לְפָנָיו יְהַלֵּךְ וְיָשֵׂם לְדֶרֶךְ פְּעָמָיו. דְּהָא שְׁכִינְתָּא לָא אִתְפָּרְשָׁא מִנֵּיהּ."],[[0,"והוו מחכאן וכו':","והיו חוכים עד השעה שנולד נח. וכיון שנולד נח, ראה אותו מהול ורשום באות הקדוש. וראה שהשכינה דבוקה בו. אז הבין שבימיו תתבטל הקללה מן האדמה, וקרא שמו על שם הנעשה לאחר כך."],[1,"בקדמיתא לא הוו ידעי וכו':","מתחילה לא היו יודעים לזרוע ולקצור ולחרוש, והיו עושים עבודת האדמה בידיהם. כיון שבא נח. תקן להם כלי אומנות, וכל הכלים הצריכים לתקון האדמה, שתעשה פירות. וז\"ש זה ינחמנו ממעשנו ומעצבון ידינו מן האדמה אשר אררה ה'. כי הוא הוציא את האדמה ממה שנתקללה, שהיו זורעים חטים וקוצרים קוצים ודרדרים, וע\"כ כתוב בו איש האדמה."],[2,"ר' יהודה אמר וכו':","רי\"א \u0003איש האדמה,\u0004 פירושו כמו שאתה אומר איש \u0003נעמי,\u0004 דהיינו בעלה של האדמה, משום שהוציא את האדמה ממה שנתקללה, על ידי הקרבן שהקריב. שכתוב אז, לא אוסיף לקלל עוד את האדמה בעבור האדם, ומשום זה נקרא איש האדמה. ועל כן קרא לו השם נח על מה שעתיד לבא."],[3,"ר' יהודה פתח וכו':","ר\"י פתח לכו חזו מפעלות אלקים וגו'. מקרא זה נתבאר ונאמר. אבל לכו חזו וגו', כי אלו היה העולם נברא במפעלות השם הוי\"ה שהוא רחמים, היה משים קיום בארץ, אבל משום שמפעלות השם אלקים הם, שהוא דין, שם שמות בארץ דהיינו שממה. ונראה שהזהר היה לו נוסח זה, כי בספרים שלנו כתוב מפעלות הויה."],[4,"א\"ל ר' חייא וכו':","א\"ל ר\"ח, עתה נתעוררת לזה לפרש שמות בארץ מלשון שממה. אני איני מפרש כן, כי בין שם זה, \u0003הוי\"ה,\u0004 ובין שם זה, \u0003אלקים,\u0004 הכל הוא לשבח. אבל אני מפרש את הכתוב כמו שהעירו החברים, ששם שמות הקדושים, \u0003שמות בארץ\u0004 פירושו שמות ממש, שם בארץ."],[5,"ר' יצחק אמר כלא וכו':","רי\"א הכל אמת הוא בפירוש הכתוב, ואפילו מה דאמר ר' יהודה יפה אמר, כי אלו היה העולם בשם הרחמים היה מתקים העולם. אבל משום שהעולם נברא על הדין, ועומד על הדין, ע\"כ \u0003שם שמות בארץ.\u0004 דהיינו ששם שמות הקדושים שיגינו על הארץ, ויפה הוא, כי אלמלא כך, לא היה העולם יכול להתקיים מחמת עונותיהם של בני האדם."],[6,"ת\"ח נח כד אתייליד:","בוא וראה, נח כאשר נולד, קראו שמו על שם הנחמה, כדי שהשם יגרום להם נחמה. אבל הקב\"ה אינו כך, שלא הסכים עמהם, אלא שהביא עליהם את המבול. כי רצה שיטיבו דרכם ויעשו תשובה, נח בהיפוך האותיות הוא חן. כמו שאתה אומר ונח מצא חן. אמר ר' יוסי, חן היינו נח, שאותיותיהם שוות. בצדיקים, שמותיהם גורמים להם טוב. וברשעים, שמותיהם גורמים להם רע, כי בנח כתוב ונח מצא חן בעיני ה', שנתהפכו האותיות לטוב. בער בכור יהודה נתהפכו האותיות לרע, \u0003ע\"ר\u0004 נתהפך \u0003לר\"ע,\u0004 כמ\"ש ויהי ער בכור יהודה \u0003רע\u0004 בעיני ה'."],[7,"ת\"ח כיון דאתיליד נח וכו':","בוא וראה כיון שנולד נח, ראה מעשיהם של בני אדם, שהם חוטאים לפני הקב\"ה. והיה מסתיר את עצמו שלא ללכת בדרכיהם, ועסק בעבודת רבונו. ואם תאמר במה עסק. הוא עסק בספרו של אדם הראשון, ובספרו של חנוך. והיה עוסק בהם לדעת איך לעבוד לרבונו:"],[8,"ת\"ח דהכי הוא וכו':","בוא וראה שכן הוא. שעסק בספריהם של אדם וחנוך. כי מאין היה יודע נח להקריב קרבן לרבונו. אלא משום שמצא חכמה, בספריהם של אדם וחנוך, לדעת על מה מתקיים העולם. וידע מהם, שעל הקרבן מתקיים העולם, שאלמלא הקרבן לא היו מתקיימים העליונים והתחתונים, וע\"כ הקריב קרבן."],[9,"ר' שמעון וכו':","ר\"ש היה הולך בדרך, והיה עמו ר' אלעזר בנו ורבי יוסי ורבי חייא. בעוד שהיו מהלכים, אמר ר' אלעזר לאביו, הדרך, הרי מתוקן לפנינו, ואנו רוצים לשמוע דברי תורה."],[10,"פתח ר\"ש ואמר:","גם בהדרך כשהסכל הולך לבו חסר. כאשר האדם רוצה לתקן דרכיו לפני הקב\"ה. צריך להתיעץ בו, ולהתפלל לפניו שיצליח בדרכו. כמו שלמדנו שכתוב, צדק לפניו יהלך וישם לדרך פעמיו. כי יתפלל שהשכינה, הנקראת צדק, שלא תפרוש ממנו, ואחר זה, וישם לדרך פעמיו."]],[[0,"","וְהָיוּ מְחַכִּים עַד שָׁעָה שֶׁנּוֹלַד נֹחַ. וְכֵיוָן שֶׁנּוֹלַד, רָאָה אוֹתוֹ מָהוּל רָשׁוּם בְּאוֹת הַקֹּדֶשׁ, וְרָאָה שְׁכִינָה דְּבוּקָה עִמּוֹ, וְאָז קָרָא אֶת שְׁמוֹ עַל מַה שֶּׁעָשָׂה אַחַר כָּךְ."],[1,"","בַּתְּחִלָּה לֹא הָיוּ יוֹדְעִים לִזְרֹעַ וְלִקְצֹר וְלַחֲר!שׁ, וְהָיוּ עוֹשִׂים עֲבוֹדַת הָאֲדָמָה בִּידֵיהֶם. כֵּיוָן שֶׁבָּא נֹחַ, הִתְקִין אֻמָּנוּת לָהֶם וְכָל הַכֵּלִים שֶׁצְּרִיכִים לְתַקֵּן אֶת הָאֲדָמָה לַעֲשׂוֹת פֵּרוֹת. זֶהוּ שֶׁכָּתוּב זֶה יְנַחֲמֵנוּ מִמַּעֲשֵׂנוּ וּמֵעִצְּבוֹן יָדֵינוּ מִן הָאֲדָמָה. שֶׁהוּא הוֹצִיא אֶת הָאָרֶץ מִמַּה שֶּׁהִתְקַלְּלָה שֶׁהָיוּ זוֹרְעִים חִטִּים - וְקוֹצְרִים קוֹצִים וְדַרְדָּרִים. וְלָכֵן כָּתוּב אִישׁ הָאֲדָמָה."],[2,"","רַבִּי יְהוּדָה אָמַר, אִישׁ הָאֲדָמָה, כְּמוֹ שֶׁנֶּאֱמַר (רות א) אִישׁ נָעֳמִי. מִשּׁוּם שֶׁנִּקְרָא צַדִּיק וְהוֹצִיא אֶת הָאָרֶץ בְּקָרְבָּן שֶׁעָשָׂה מִמַּה שֶּׁהִתְקַלְּלָה, שֶׁכָּתוּב לֹא אֹסִף לְקַלֵּל עוֹד אֶת הָאֲדָמָה בַּעֲבוּר הָאָדָם. וְלָכֵן נִקְרָא אִישׁ הָאֲדָמָה, וְעַל זֶה קָרָא לוֹ שֵׁם עַל מַה שֶּׁיָּבֹא."],[3,"","רַבִּי יְהוּדָה פָּתַח, (תהלים מו) לְכוּ חֲזוּ מִפְעֲלוֹת אֱלֹהִים אֲשֶׁר שָׂם שַׁמּוֹת בָּאָרֶץ. פָּסוּק זֶה הֱקִימוּהוּ וְנִתְבָּאֵר. אֲבָל לְכוּ חֲזוּ וְגוֹ' (מה זה חזו? כמו שנאמר (ישעיה כא) חזות קשה הגד לי, במעשי הקדוש ברוך הוא נגלתה נבואה עליונה לבני אדם, אשר שם שמות בארץ שמות ודאי, שהרי השם גורם לכל) (והוא לשון שממון). שֶׁאִלּוּ הָיוּ מִפְעֲלוֹת יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א - שָׂם קִיּוּם בָּאָרֶץ, אֲבָל מִשּׁוּם שֶׁהָיוּ מִפְעֲלוֹת הַשֵּׁם שֶׁל אֱלֹהִים - שָׂם שַׁמּוֹת בָּאָרֶץ."],[4,"","אָמַר לוֹ רַבִּי חִיָּיא, כָּעֵת הִתְעוֹרַרְתָּ לָזֶה? לֹא כָּךְ אֲנִי אָמַרְתִּי לוֹ, מִשּׁוּם שֶׁבֵּין שֵׁם זֶה וּבֵין שֵׁם זֶה הַכֹּל הוּא שֶׁבַח. אֲבָל אֲנִי אָמַרְתִּי לוֹ כְּמוֹ שֶׁהֵעִירוּ הַחֲבֵרִים שֶׁשָּׂם שֵׁמוֹת. שַׁמּוֹת בָּאָרֶץ, שֵׁמוֹת מַמָּשׁ (שם בארץ, ולמה? בשביל להשתמש בהם העולם ולהיות קיום בעולם)."],[5,"","רַבִּי יִצְחָק אָמַר, הַכֹּל הוּא, וַאֲפִלּוּ מַה שֶּׁאָמַר רַבִּי יְהוּדָה - יָפֶה אָמַר. שֶׁאִלּוּ הָעוֹלָם יִהְיֶה בְּשֵׁם הָרַחֲמִים, יִתְקַיֵּם הָעוֹלָם. אֲבָל מִשּׁוּם שֶׁהָעוֹלָם נִבְרָא עַל דִּין וְעוֹמֵד עַל דִּין, שָׂם שַׁמּוֹת בָּאָרֶץ, וְיָפֶה הוּא, שֶׁאִלְמָלֵא כָּךְ לֹא יוּכַל הָעוֹלָם לְהִתְקַיֵּם מִלִּפְנֵי חֲטָאֵי בְּנֵי הָאָדָם."],[6,"","בֹּא רְאֵה, כְּשֶׁנּוֹלַד נֹחַ קָרְאוּ לוֹ עַל שֵׁם שֶׁל נֶחָמָה (נח נוח לו, נוח לעולם, נוח לאבות, נוח לבנים, נוח לעליונים, נוח לתחתונים, נוח לעולם הזה, נוח לעולם הבא) וְשֶׁיִּהְיֶה (ולהיות) הַשֵּׁם גּוֹרֵם. אֲבָל לְגַבֵּי הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא כָּךְ. נֹחַ בְּהִפּוּךְ אוֹתִיּוֹת - חֵ\"ן, כְּמוֹ שֶׁנֶּאֱמַר וְנֹחַ מָצָא חֵן. אָמַר רַבִּי יוֹסֵי, חֵן הַיְנוּ נֹחַ. בַּצַּדִּיקִים, הַשֵּׁם שֶׁלָּהֶם גּוֹרֵם לְטוֹב. בָּרְשָׁעִים, הַשֵּׁם שֶׁלָּהֶם גּוֹרֵם לְרַע. בְּנֹחַ כָּתוּב וְנֹחַ מָצָא חֵן בְּעֵינֵי ה'. בְּעֵר בְּכוֹר יְהוּדָה הִתְהַפְּכוּ אוֹתִיּוֹתָיו לְרַע. עֵ\"ר רַ\"ע. רַע בְּעֵינֵי ה'."],[7,"","בֹּא רְאֵה, כֵּיוָן שֶׁנּוֹלַד נֹחַ, רָאָה אֶת מַעֲשֵׂי בְּנֵי הָאָדָם שֶׁהֵם חוֹטְאִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהָיָה גוֹנֵז עַצְמוֹ וְעָסַק בַּעֲבוֹדַת רִבּוֹנוֹ כְּדֵי לֹא לָלֶכֶת בְּדַרְכָּם. וְכִי תֹאמַר, בַּמָּה הוּא עָסַק? בְּאוֹתוֹ סֵפֶר שֶׁל אָדָם וְסֵפֶר שֶׁל חֲנוֹךְ. וְהָיָה עוֹסֵק בָּהֶם לַעֲבֹד אֶת רִבּוֹנוֹ."],[8,"","בֹּא רְאֵה שֶׁכָּךְ הוּא, שֶׁהֲרֵי מֵאֵיפֹה יָדַע נֹחַ לְהַקְרִיב קָרְבָּן לְרִבּוֹנוֹ? אֶלָּא מִשּׁוּם שֶׁמָּצָא חָכְמָה עַל מָה הָעוֹלָם עוֹמֵד, וְיָדַע שֶׁהוּא עוֹמֵד עַל הַקָּרְבָּן, וְאִלְמָלֵא הַקָּרְבָּן לֹא הָיוּ עוֹמְדִים עֶלְיוֹנִים וְתַחְתּוֹנִים."],[9,"","רַבִּי שִׁמְעוֹן הָיָה הוֹלֵךְ בַּדֶּרֶךְ וְהָיוּ עִמּוֹ רַבִּי אֶלְעָזָר בְּנוֹ וְרַבִּי יוֹסֵי וְרַבִּי חִיָּיא. עַד שֶׁהָיוּ הוֹלְכִים, אָמַר רַבִּי אֶלְעָזָר לְאָבִיו, הַדֶּרֶךְ מְתֻקֶּנֶת לְפָנֵינוּ, רוֹצִים לִשְׁמֹעַ דִּבְרֵי תוֹרָה"],[10,"","פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (קהלת י) וְגַם בַּדֶּרֶךְ כְּשֶׁהַסָּכָל הֹלֵךְ לִבּוֹ חָסֵר וְגוֹ'. כְּשֶׁבֶּן אָדָם רוֹצֶה לְתַקֵּן דְּרָכָיו לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, עַד שֶׁלֹּא יֵצֵא לַדֶּרֶךְ צָרִיךְ לְהִמָּלֵךְ בּוֹ וּלְהִתְפַּלֵּל לְפָנָיו עַל דַּרְכּוֹ, כְּמוֹ שֶׁשָּׁנִינוּ שֶׁכָּתוּב (תהלים פה) צֶדֶק לְפָנָיו יְהַלֵּךְ וְיָשֵׂם לְדֶרֶךְ פְּעָמָיו. שֶׁהֲרֵי הַשְּׁכִינָה לֹא נִפְרֶדֶת מִמֶּנּוּ."]]],[["וּמָאן דְּאִיהוּ לָא מְהֵימְנָא בְּמָרֵיהּ, מַה כְּתִיב בֵּיהּ וְגַם בַּדֶּרֶךְ כְּשֶׁהַסָּכָל הוֹלֵךְ לִבּוֹ חָסֵר. מַאן לִבּוֹ. דָּא קוּדְשָׁא בְּרִיךְ הוּא דְּלָא יְהַךְ עִמֵּיהּ בְּאָרְחָא וְגָרַע מִן סִיַּיעְתֵּיהּ בְּאָרְחֵיהּ. בְּגִין דְּהַהוּא בַּר נָשׁ דְּלָא מְהֵימָן בֵּיהּ בְּמָארֵיהּ עַד לָא יִפּוּק בְּאָרְחָא לָא בָּעֵי סִיַּעְתָּא דְמָארֵיהּ.","וְאֲפִילּוּ בְּאָרְחָא כַּד אִיהוּ אָזִיל לָא אִשְׁתַּדַּל בְּמִלֵּי דְאוֹרַיְיתָא. וּבְגִינֵי כָךְ לִבּוֹ חָסֵר דְּלָא אָזִיל בַּהֲדֵיהּ דְּמָרֵיהּ וְלָא אִשְׁתְּכַח בְּאָרְחֵיהּ. וְאֹמֵר לַכֹּל סָכָל הוּא, אֲפִלּוּ כַּד שְׁמַע מִלָּה דִמְהֵימְנוּתָא דְמָארֵיהּ, הוּא אָמַר דְּטִפְּשׁוּתָא הוּא לְאִשְׁתַּדָּלָא בֵּיהּ.","כְּהַאי דְּשָׁאִילוּ לְבַר נָשׁ (חד) עַל אָת קְיָימָא דִּרְשִׁימוּ בְּבִשְׂרֵיהּ דְּבַר נָשׁ. וְאָמַר לָאו אִיהוּ מְהֵימְנוּתָא. שָׁמַע רַב יֵיבָא סָבָא וְאִסְתַּכַּל בֵּיהּ וְאִתְעֲבִיד תִּלָּא דְּגַרְמֵי. וְאֲנַן בְּהַאי אוֹרְחָא בְּסִיַּיעְתָּא דְּקוּדְשָׁא בְּרִיךְ הוּא בָּעִינָן לְמֵימַר מִלֵּי דְאוֹרַיְיתָא.","פָּתַח וְאָמַר (תהילים פ״ו:י״א) הוֹרֵנִי יְיָ דַּרְכֶּךָ אֲהַלֵּךְ בַּאֲמִתֶּךָ יַחֵד לְבָבִי לְיִרְאָה שְׁמֶךָ. הַאי קְרָא קַשְׁיָא. דְּהָא תָּנִינָן כֹּלָא הִיא בִּידָא דְּקוּדְשָׁא בְּרִיךְ הוּא, בַּר לְמֶהֱוֵי זַכָּאָה אוֹ חַיָּיבָא. וְדָוִד הֵיךְ תָּבַע דָּא מֵעִם קוּדְשָׁא בְּרִיךְ הוּא.","אֶלָּא דָּוִד הָכִי קָאֲמַר. הוֹרֵנִי יְיָ דַּרְכֶּךָ. הַהוּא אֹרַח מִישׁוֹר וּמְתַקְנָא לְגַלָּאָה עֵינַי וּלְמִנְדַע לֵיהּ, וּלְבָתַר אֲהַלֵּךְ בַּאֲמִתֶּךָ אֵיהַךְ בְּאֹרַח קְשׁוֹט וְלָא אַסְטֵי לְיָמִינָא וְלִשְׂמָאלָא. יַחֵד לְבָבִי מַאן לְבָבִי. כְּמָא דְאַתְּ אָמֵר (תהילים ע״ג:כ״ו) צוּר לְבָבִי וְחֶלְקִי. וְכָל דָּא אֲנָא תָּבַע לְיִרְאָה אֶת שְׁמֶךָ. לְאִתְדַּבְּקָא בְּדַחַלְתָּךְ, לְאִסְתַּמָּרָא אוֹרְחֵי כְּדְקָא יָאוֹת. לְיִרְאָה שְׁמֶךָ אֲתַר חוּלְקִי דְּבֵיהּ שַׁרְיָא דַחַלְתָּא לְמִדְחַל.","תָּא חֲזֵי, כָּל בַּר נָשׁ דְּדָחִיל לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא שַׁרְיָא עִמֵּיהּ מְהֵימְנוּתָא כְּדְקָא יְאוּת דְּהָא הַהוּא בַּר נָשׁ שְׁלִים בְּפוּלְחָנָא דְמָרֵיהּ. וּמָאן דְּלָא שָׁרְיָא בֵּיהּ דַּחֲלָא דְמָרֵיהּ לָא שָׁרְיָיא עִמֵּיהּ מְהֵימְנוּתָא וְלָאו אִיהוּ כְּדַאי לְמֶהֱוֵי לֵיהּ חוּלָקָא בְּעָלְמָא דְאָתֵי.","תּוּ פָּתַח וְאָמַר, (משלי ד׳:י״ח) וְאֹרַח צַדִּיקִים כְּאוֹר נוֹגַהּ הוֹלֵךְ וְאוֹר עַד נְכוֹן הַיּוֹם. זַכָּאִין אִנּוּן צַדִּיקַיָא בְּעָלְמָא דֵין וּבְעָלְמָא דְאָתֵי דְּקוּדְשָׁא בְּרִיךְ הוּא בָּעֵי בִּיקָרֵיהוֹן. תָּא חֲזֵי, מַה כְּתִיב וְאֹרַח צַדִּיקִים כְּאוֹר נוֹגַהּ. מַאי כְּאוֹר נוֹגַהּ. כְּהַהוּא נְהוֹרָא דְּנָהִיר דְּבָרָא קוּדְשָׁא בְּרִיךְ הוּא בְּעוֹבָדָא דִבְרֵאשִׁית, דָּא הוּא דְּגָנִיז לוֹן לְצַדִּיקַיָא לְעָלְמָא דְאָתֵי. הוֹלֵךְ וְאוֹר דְּאִיהוּ סָלִיק בִּנְהוֹרֵיהּ תָּדִיר וְלָא גָרַע מִנֵּיהּ.","אֲבָל בְּחַיָּיבַיָא מַה כְּתִיב, (משלי ד׳:י״ט) דֶּרֶךְ רְשָׁעִים כָּאֲפֵלָה, לֹא יָדְעוּ בַּמֶּה יִכָּשֵׁלוּ. לא יָדְעוּ, וְכִי לָא יָדְעִין. אֶלָּא חַיָּיבַיָא אָזְלֵי בְּעֲקִימוּ דְּאָרְחָא בְּהַאי עָלְמָא. וְלָא בָּעָאן לְאִסְתַּכְּלָא דְּזַמִּין (ד\"א ל\"ג לון) קוּדְשָׁא בְּרִיךְ הוּא לְמֵידַן לְהוּ בְּהַהוּא עָלְמָא וּלְאַעָלָאָה לוֹן בְּדִינָא דְּגֵיהִנֹּם. וְאִנּוּן צָווחִין וְאָמְרִין וַוי לָן דְּלָא אוֹרִיכְנָא אוּדְנִין וְלָא אֲצִיתְנָא בְּהַהוּא עָלְמָא. וּבְכָל יוֹמָא אָמְרֵי ווי דָא (רלז ב).","תָּא חֲזֵי, זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאַנְהָרָא לוֹן לְצַדִּיקַיָּא לְעָלְמָא דְאָתֵי, וּלְמֵיהַב לוֹן אֲגַר חוּלַקְהוֹן אֲתַר דְּעֵינָא לָא שָׁלְטָא לְמֵיקַם עֲלֵיהּ כְּמָא דְאַתְּ אָמֵר, (ישעיהו ס״ד:ג׳) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתֶךָ יַעֲשֶׂה לִמְחַכֵּה לוֹ. וּכְתִיב, (ישעיהו ס״ו:כ״ד) וְיָצְאוּ וְרָאוּ בְּפִגְרֵי הָאֲנָשִׁים הַפּוֹשְׁעִים בִּי. וּכְתִיב, (מלאכי ג׳:כ״א) וְעַסּוֹתֶם רְשָׁעִים כִּי יִהְיוּ אֵפֶר תַּחַת כַּפּוֹת רַגְלֵיכֶם. זַכָּאִין אִנּוּן צַדִּיקַיָא בְּעָלְמָא דֵין וּבְעָלְמָא דְאָתֵי. עֲלַיְיהוּ כְּתִיב (ישעיהו ס׳:כ״א) צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ. וּכְתִיב, (תהילים ק״מ:י״ד) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךָ יֵשְׁבוּ יְשָׁרִים אֶת פָּנֶיךָ. בָּרוּךְ יְיָ לְעוֹלָם אָמֵן וְאָמֵן (חסר):"],[[0,"ומאן דאיהו וכו':","ומי שאינו מאמין ברבונו, מה כתוב בו. וגם בדרך כשהסכל הולך לבו חסר. ושואל מי הוא לבו. ואומר, זהו הקב\"ה, המשרה שכינתו בלב הצדיקים. שאינו הולך עמו בדרך וע\"כ לבו חסר מהשראת השכינה, וחסר, מעזרתו בדרך. משום שאדם ההוא, שאינו מאמין ברבונו, הנקרא כסיל, שאין אדם חוטא אלא אם כן נכנס בו רוח שטות לא בקש עזרה מרבונו מטרם שיצא לדרך."],[1,"ואפילו בארחא וכו':","ואפילו כשהוא הולך בדרך אינו עוסק בדברי תורה, ומשום זה לבו חסר. שאינו הולך עם רבונו, ורבונו אינו נמצא בדרכו. \u0003ואמר לכל שסכל הוא,\u0004 אפילו כשהוא שומע דבר של אמונה ברבונו, אומר שטפשות הוא לעסוק בו."],[2,"כהאי דשאילו וכו':","כמו זה, ששאלו לאדם על אות ברית קודש הרשום בבשר האדם. ואמר, שאין הוא אמונה. שמע רבי ייסא סבא, והסתכל בו, ועשאו גל של עצמות. ואנו, נמצאים בדרך הזה בעזרת הקב\"ה. ע\"כ, אנו צריכים לומר בו דברי תורה."],[3,"פתח ואמר הורני ה' דרכך וגו':","מקרא זה קשה. הרי למדנו הכל הוא בידי הקב\"ה חוץ מלהיות צדיק או רשע. דהיינו כמ\"ש הכל בידי שמים חוץ מיראת שמים. ולפי\"ז קשה, דוד, איך בקש זה מעם הקב\"ה."],[4,"אלא דוד וכו':","ומשיב, אלא דוד, כך אמר, \u0003הורני ה' דרכך,\u0004 בקש מהקב\"ה לגלות עיניו ולהודיעו את דרך הישר והמתוקן, ואחר כך \u0003אהלך באמתך,\u0004 אהלך בדרך האמת, ולא אטה לימין ושמאל. \u0003יחד לבבי,\u0004 מהו לבבי. הוא כמו שאתה אומר, צור לבבי וחלקי, דהיינו השכינה הקדושה המתלבשת בלב, הנקראת \u0003צור לבבי,\u0004 ועליה בקש, \u0003יחד\u0004 לבבי. וכל זה אני מבקש. \u0003כדי ליראה את שמך.\u0004 להתדבק ביראתך, ולשמור דרכי כראוי, \u0003ליראה שמך,\u0004 הוא מקום חלקי. דהיינו המלכות, שהיא חלקו של דוד. שבו שורה היראה לירא ממנו. כי המלכות ה\"ס היראה, ונקראת יראה, כנודע."],[5,"ת\"ח כל בר נש וכו':","בוא וראה כל אדם המתירא מפני הקב\"ה, שורה עמו האמונה כראוי. כי אדם הזה שלם בעבודת רבונו. ומי שאין יראת רבונו שורה בו, אין האמונה שורה בו, ואינו כדאי שיהיה לו חלק לעולם הבא."],[6,"תו פתח ואמר וארח צדיקים כאור נוגה וגו':","אשריהם הצדיקים בעולם הזה ובעולם הבא, כי הקב\"ה חפץ ביקרם, בוא וראה מה כתוב. וארח צדיקים כאור נוגה, מהו \u0003כאור נוגה,\u0004 הוא, כאותו אור המאיר, שברא הקב\"ה במעשה בראשית, זה הוא האור שגנז הקב\"ה לצדיקים לעולם הבא. הולך ואור, כי הוא הולך ועולה באורו תמיד, ואינו חסר לעולם."],[7,"אבל בחייביא וכו':","אבל ברשעים מה כתוב, דרך רשעים כאפלה, לא ידעו במה יכשלו. ושואל \u0003ולא ידעו,\u0004 וכי אינם יודעים במה יכשלו. ומשיב, אלא, הרשעים הולכים בדרך עקום בעולם הזה, ואינם רוצים להסתכל שעתיד הקב\"ה לדון אותם בעולם האמת ויביאם בדינו של גיהנם. והם צועקים בגיהנם ואומרים, ווי לנו שלא הטינו אזנינו ולא האזנו למצותיו בעולם הזה. ובכל יום ויום אומרים ווי הזה."],[8,"ת\"ח זמין קב\"ה וכו':","עתיד הקב\"ה להאיר לצדיקים בעולם הבא, ולתת להם שכר מנת חלקם, מקום שהעין אינת שולטת לעמוד עליו, כמו שאתה אומרעין לא ראתה אלקים זולתך יעשה למחכה לו. וכתוב. ועסותם רשעים כי יהיו אפר תחת כפות רגליכם. אשריהם הצדיקים בעולם הזה ובעולם הבא. עליהם כתוב, צדיקים לעולם וגו'. וכתוב אך צדיקים וגו'. ברוך ה' לעולם אמן ואמן."]],[[0,"","וּמִי שֶׁלֹּא מַאֲמִין בְּרִבּוֹנוֹ, מַה כָּתוּב בּוֹ? וְגַם בַּדֶּרֶךְ שֶׁהַסָּכָל הֹלֵךְ לִבּוֹ חָסֵר. מִי זֶה לִבּוֹ? זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא יֵלֵךְ עִמּוֹ בַּדֶּרֶךְ וְגוֹרֵעַ מִסִּיּוּעוֹ בְּדַרְכּוֹ. מִשּׁוּם שֶׁאוֹתוֹ בֶּן אָדָם שֶׁלֹּא מַאֲמִין בְּרִבּוֹנוֹ, עַד שֶׁלֹּא יֵצֵא לְדַרְכּוֹ לֹא בִקֵּשׁ אֶת סִיּוּעַ רִבּוֹנוֹ."],[1,"","וַאֲפִלּוּ בַּדֶּרֶךְ כְּשֶׁהוּא הוֹלֵךְ, לֹא עוֹסֵק בְּדִבְרֵי תוֹרָה, וְלָכֵן לִבּוֹ חָסֵר, שֶׁאֵינוֹ הוֹלֵךְ יַחַד עִם רִבּוֹנוֹ וְלֹא נִמְצָא בְדַרְכּוֹ. וְאוֹמֵר לַכֹּל סָכָל הוּא - וַאֲפִלּוּ כְּשֶׁשּׁוֹמֵעַ דְּבַר אֱמוּנָה שֶׁל רִבּוֹנוֹ, הוּא אוֹמֵר שֶׁזּוֹ טִפְּשׁוּת לַעֲסֹק בָּזֶה."],[2,"","כְּמוֹ זֶה שֶׁשָּׁאֲלוּ לְבֶן אָדָם עַל אוֹת הַבְּרִית שֶׁרָשְׁמוּ בִּבְשַׂר הָאָדָם, וְאוֹמֵר שֶׁלֹּא דְּבַר אֱמוּנָה הוּא. שָׁמַע זֹאת רַבִּי יֵיבָא הַזָּקֵן וְהִסְתַּכֵּל בּוֹ, וְנַעֲשָׂה גַל שֶׁל עֲצָמוֹת. וְאָנוּ בַּדֶּרֶךְ הַזּוֹ בְּסִיּוּעַ הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצִים לוֹמַר דִּבְרֵי תוֹרָה."],[3,"","פָּתַח וְאָמַר, (תהלים פו) הוֹרֵנִי ה' דַּרְכֶּךְ אֲהַלֵּךְ בַּאֲמִתֶּךְ יַחֵד לְבָבִי לְיִרְאָה שְׁמֶךְ. פָּסוּק זֶה קָשֶׁה, שֶׁהֲרֵי שָׁנִינוּ, הַכֹּל בְּיַד הַקָּדוֹשׁ בָּרוּךְ הוּא חוּץ מִלִּהְיוֹת צַדִּיק אוֹ רָשָׁע. וְדָוִד אֵיךְ תָּבַע אֶת זֶה מֵהַקָּדוֹשׁ בָּרוּךְ הוּא?"],[4,"","אֶלָּא דָּוִד כָּךְ אָמַר, הוֹרֵנִי ה' דַּרְכֶּךְ - אוֹתָהּ דֶּרֶךְ מִישׁוֹר וּמְתֻקֶּנֶת לְגַלּוֹת עֵינַי וְלָדַעַת אוֹתוֹ. אַחַר כָּךְ אֲהַלֵּךְ בַּאֲמִתֶּךְ - אֵלֵךְ בְּדֶרֶךְ אֱמֶת וְלֹא אֶסְטֶה לְיָמִין וְלִשְׂמֹאל. יַחֵד לְבָבִי - מַה זֶּה לְבָבִי? כְּמוֹ שֶׁנֶּאֱמַר (שם עג) צוּר לְבָבִי וְחֶלְקִי. וְכָל זֶה אֲנִי מְבַקֵּשׁ לְיִרְאָה אֶת שְׁמֶךְ. לְהִדָּבֵק בְּיִרְאָתֶךְ, לִשְׁמֹר אֶת דְּרָכַי כָּרָאוּי. לְיִרְאָה שְׁמֶךְ - מְקוֹם חֶלְקִי שֶׁבּוֹ שְׁרוּיָה הַיִּרְאָה לִירָא."],[5,"","בֹּא רְאֵה, כָּל בֶּן אָדָם שֶׁיָּרֵא אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, שְׁרוּיָה עִמּוֹ הָאֱמוּנָה כָּרָאוּי, שֶׁהֲרֵי אוֹתוֹ אָדָם הוּא שָׁלֵם בַּעֲבוֹדַת רִבּוֹנוֹ. וּמִי שֶׁלֹּא שְׁרוּיָה בּוֹ יִרְאַת רִבּוֹנוֹ, לֹא שְׁרוּיָה בּוֹ אֱמוּנָה, וְאֵינוֹ כְדַאי לִהְיוֹת לוֹ חֵלֶק לָעוֹלָם הַבָּא."],[6,"","עוֹד פָּתַח וְאָמַר, (משלי ד) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ הוֹלֵךְ וָאוֹר עַד נְכוֹן הַיּוֹם. אַשְׁרֵיהֶם הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בִּיקָרָם. בֹּא רְאֵה מַה כָּתוּב, וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ. מַה זֶּה כְּאוֹר נֹגַהּ? כְּמוֹ אוֹתוֹ הָאוֹר הַמֵּאִיר שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמַעֲשֵׂה בְרֵאשִׁית, זֶהוּ שֶׁגָּנַז לַצַּדִּיקִים לָעוֹלָם הַבָּא. הוֹלֵךְ וָאוֹר - שֶׁהוּא עוֹלֶה בְאוֹרוֹ תָּמִיד וְלֹא גוֹרֵעַ מִמֶּנּוּ."],[7,"","אֲבָל בָּרְשָׁעִים מַה כָּתוּב? (שם) דֶּרֶךְ רְשָׁעִים כָּאֲפֵלָה לֹא יָדְעוּ בַּמֶּה יִכָּשֵׁלוּ. לֹא יָדְעוּ - וְכִי לֹא יוֹדְעִים? אֶלָּא רְשָׁעִים שֶׁהוֹלְכִים בְּדֶרֶךְ עֲקֻמָּה בָּעוֹלָם הַזֶּה וְלֹא רוֹצִים לְהִסְתַּכֵּל (להם) שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לָדוּן אוֹתָם בְּאוֹתוֹ עוֹלָם וּלְהַכְנִיסָם בְּדִין גֵּיהִנֹּם. וְהֵם צוֹוְחִים וְאוֹמְרִים: אוֹי לָנוּ שֶׁלֹּא הִרְכַּנְנוּ אָזְנַיִם וְלֹא הִקְשַׁבְנוּ בְּאוֹתוֹ עוֹלָם. וּבְכָל יוֹם אוֹמְרִים: וַי לָנוּ!"],[8,"","בֹּא רְאֵה, עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהָאִיר לַצַּדִּיקִים לָעוֹלָם הַבָּא וְלָתֵת לָהֶם שְׂכַר חֶלְקָם, מָקוֹם שֶׁעַיִן לֹא שׁוֹלֶטֶת לַעֲמֹד עָלָיו, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה סד) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ יַעֲשֶׂה לִמְחַכֵּה לוֹ. וְכָתוּב (שם סו) וְיָצְאוּ וְרָאוּ בְּפִגְרֵי הָאֲנָשִׁים הַפֹּשְׁעִים בִּי. וְכָתוּב (מלאכי ג) וְעַסּוֹתֶם רְשָׁעִים כִּי יִהְיוּ אֵפֶר תַּחַת כַּפּוֹת רַגְלֵיכֶם. אַשְׁרֵי הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. עֲלֵיהֶם כָּתוּב (ישעיה ס) צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ. וְכָתוּב (תהלים קמ) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךְ יֵשְׁבוּ יְשָׁרִים אֶת פָּנֶיךְ. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן:"]]]]};
